String _getPresidentCardRank(String card) => card.substring(0, card.length - 1);

int _getPresidentCardValue(String card, bool isRevolutionActive) {
  final rank = _getPresidentCardRank(card);
  if (isRevolutionActive) {
    return _presidentCardValuesRevolution[rank]!;
  }
  return _presidentCardValues[rank]!;
}

int _comparePresidentCards(String a, String b, bool isRevolutionActive) =>
    _getPresidentCardValue(
      a,
      isRevolutionActive,
    ).compareTo(_getPresidentCardValue(b, isRevolutionActive));

enum HandRank {
  highCard,
  onePair,
  twoPair,
  threeOfAKind,
  straight,
  flush,
  fullHouse,
  fourOfAKind,
  straightFlush,
  royalFlush,
}

class PokerCard implements Comparable<PokerCard> {
  final String suit;
  final String rank;
  final int value;

  PokerCard(String cardStr)
    : suit = cardStr.substring(1),
      rank = cardStr.substring(0, 1),
      value = _getRankValue(cardStr.substring(0, 1));

  static int _getRankValue(String rank) {
    const rankValues = {'T': 10, 'J': 11, 'Q': 12, 'K': 13, 'A': 14};
    return rankValues[rank] ?? int.tryParse(rank) ?? 0;
  }

  @override
  int compareTo(PokerCard other) => other.value.compareTo(value); // Descending order

  @override
  String toString() => '$rank$suit';
}

class PokerHand implements Comparable<PokerHand> {
  final HandRank rank;
  final List<int> kickerValues; // Values of the 5 cards making the hand

  PokerHand(this.rank, this.kickerValues);

  @override
  int compareTo(PokerHand other) {
    if (rank.index != other.rank.index) {
      return rank.index.compareTo(other.rank.index); // Higher rank wins
    }

    for (int i = 0; i < kickerValues.length; i++) {
      if (kickerValues[i] != other.kickerValues[i]) {
        return kickerValues[i].compareTo(other.kickerValues[i]);
      }
    }
    return 0; // It's a tie
  }

  @override
  String toString() => '${rank.name} with kickers: $kickerValues';
}

class PokerHandEvaluator {
  static PokerHand evaluateHand(List<String> sevenCardsStr) {
    final List<PokerCard> sevenCards =
        sevenCardsStr.map((c) => PokerCard(c)).toList();

    final combinations = _getCombinations(sevenCards, 5);

    PokerHand? bestHand;
    for (final combo in combinations) {
      final hand = _evaluateFiveCards(combo);
      if (bestHand == null || hand.compareTo(bestHand) > 0) {
        bestHand = hand;
      }
    }
    return bestHand!;
  }

  static List<List<T>> _getCombinations<T>(List<T> list, int length) {
    if (length == 0) return [[]];
    if (list.isEmpty) return [];

    final T head = list.first;
    final List<T> tail = list.sublist(1);

    final withoutHead = _getCombinations(tail, length);
    final withHead =
        _getCombinations(
          tail,
          length - 1,
        ).map((combo) => [head, ...combo]).toList();

    return [...withHead, ...withoutHead];
  }

  static PokerHand _evaluateFiveCards(List<PokerCard> fiveCards) {
    fiveCards.sort(); // Tri descendant par valeur (14 -> 2)

    List<int> values = fiveCards.map((c) => c.value).toList();
    final suits = fiveCards.map((c) => c.suit).toList();
    final isFlush = suits.toSet().length == 1;

    // Détection Quinte As-Bas (Wheel: 5-4-3-2-A)
    bool isWheelStraight =
        values.contains(14) &&
        values.contains(2) &&
        values.contains(3) &&
        values.contains(4) &&
        values.contains(5);

    bool isStraight = isWheelStraight || _isStraight(values);

    // Rétablir la bonne hiérarchie de kickers pour la Wheel (5 est la carte haute, As vaut 1)
    if (isWheelStraight) {
      values = [5, 4, 3, 2, 1];
    }

    if (isStraight && isFlush) {
      if (values[0] == 14 && !isWheelStraight) {
        return PokerHand(HandRank.royalFlush, values);
      }
      return PokerHand(HandRank.straightFlush, values);
    }

    final rankCounts = _getRankCounts(values);
    final counts = rankCounts.values.toList()..sort((a, b) => b.compareTo(a));

    if (counts[0] == 4) {
      // Four of a kind
      final fourValue = rankCounts.entries.firstWhere((e) => e.value == 4).key;
      final kicker = values.firstWhere((v) => v != fourValue);
      return PokerHand(HandRank.fourOfAKind, [
        fourValue,
        fourValue,
        fourValue,
        fourValue,
        kicker,
      ]);
    }

    if (counts[0] == 3 && counts[1] == 2) {
      // Full House
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final twoValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      return PokerHand(HandRank.fullHouse, [
        threeValue,
        threeValue,
        threeValue,
        twoValue,
        twoValue,
      ]);
    }

    if (isFlush) return PokerHand(HandRank.flush, values);
    if (isStraight) return PokerHand(HandRank.straight, values);

    if (counts[0] == 3) {
      // Three of a kind
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final kickers = values.where((v) => v != threeValue).toList();
      return PokerHand(HandRank.threeOfAKind, [
        threeValue,
        threeValue,
        threeValue,
        ...kickers,
      ]);
    }

    if (counts[0] == 2 && counts[1] == 2) {
      // Two Pair
      final pairs =
          rankCounts.entries
              .where((e) => e.value == 2)
              .map((e) => e.key)
              .toList()
            ..sort((a, b) => b.compareTo(a));
      final kicker = values.firstWhere((v) => v != pairs[0] && v != pairs[1]);
      return PokerHand(HandRank.twoPair, [
        pairs[0],
        pairs[0],
        pairs[1],
        pairs[1],
        kicker,
      ]);
    }

    if (counts[0] == 2) {
      // One Pair
      final pairValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      final kickers = values.where((v) => v != pairValue).toList();
      return PokerHand(HandRank.onePair, [pairValue, pairValue, ...kickers]);
    }

    return PokerHand(HandRank.highCard, values);
  }

  static bool _isStraight(List<int> sortedValues) {
    if (sortedValues.toSet().containsAll({14, 2, 3, 4, 5})) return true;

    for (int i = 0; i < sortedValues.length - 1; i++) {
      if (sortedValues[i] != sortedValues[i + 1] + 1) return false;
    }
    return true;
  }

  static Map<int, int> _getRankCounts(List<int> values) {
    final counts = <int, int>{};
    for (final value in values) {
      counts[value] = (counts[value] ?? 0) + 1;
    }
    return counts;
  }
}

class MultiplayerTeamSelectionDialog extends StatefulWidget {
  final String gameCode;
  final Map<String, dynamic> players;
  final Map<int, List<String>>
  initialTeams; // Modifié pour accepter plusieurs équipes
  final String gameName;
  final int minTeams;

  MultiplayerTeamSelectionDialog({
    Key? key,
    required this.gameCode,
    required this.players,
    required this.initialTeams,
    required this.gameName,
    this.minTeams = 2,
  }) : super(key: key);

  @override
  _MultiplayerTeamSelectionDialogState createState() =>
      _MultiplayerTeamSelectionDialogState();
}

class _MultiplayerTeamSelectionDialogState
    extends State<MultiplayerTeamSelectionDialog> {
  late List<String> unassignedPlayers;
  late Map<int, List<String>> teams;
  final FirebaseService _firebaseService = FirebaseService();

  final List<Color> teamColors = [
    Colors.redAccent,
    Colors.blueAccent,
    Colors.greenAccent,
    Colors.orangeAccent,
    Colors.purpleAccent,
    Colors.cyanAccent,
  ];

  @override
  void initState() {
    super.initState();
    teams = Map<int, List<String>>.from(widget.initialTeams);

    if (teams.isEmpty) {
      for (int i = 0; i < widget.minTeams; i++) {
        teams[i] = [];
      }
    }

    final allAssigned = teams.values.expand((playerList) => playerList).toSet();
    unassignedPlayers =
        widget.players.keys.where((pId) => !allAssigned.contains(pId)).toList();
  }

  void _addTeam() {
    setState(() {
      if (teams.length < 6) {
        // Limite à 6 équipes pour l'UI
        teams[teams.length] = [];
      }
    });
  }

  void _removeLastTeam() {
    setState(() {
      if (teams.length > widget.minTeams) {
        int lastTeamKey = teams.keys.last;
        List<String>? playersToUnassign = teams[lastTeamKey];
        if (playersToUnassign != null) {
          unassignedPlayers.addAll(playersToUnassign);
        }
        teams.remove(lastTeamKey);
      }
    });
  }

  void _assignPlayer(String playerId, int teamIndex) {
    setState(() {
      unassignedPlayers.remove(playerId);

      for (var team in teams.values) {
        team.remove(playerId);
      }
      teams[teamIndex]?.add(playerId);
    });
  }

  void _unassignPlayer(String playerId, int fromTeamIndex) {
    setState(() {
      teams[fromTeamIndex]?.remove(playerId);
      if (!unassignedPlayers.contains(playerId)) {
        unassignedPlayers.add(playerId);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = widget.players.keys.toList()..shuffle();
      unassignedPlayers.clear();
      teams.forEach((key, value) => value.clear()); // Vider toutes les équipes
      for (int i = 0; i < all.length; i++) {
        int teamIndex = i % teams.length;
        teams[teamIndex]?.add(all[i]);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm = unassignedPlayers.isEmpty;

    return AlertDialog(
      title: Text(
        AppLocalizations.of(context)!.equipesPour.replaceAll(
          "{0}",
          GameRulesLocalization.getGameTitle(context, widget.gameName),
        ),
      ),
      content: Container(
        width: double.maxFinite,
        height: 500, // Augmenté pour l'UI
        child: Column(
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton.icon(
                  icon: Icon(Icons.sync),
                  label: Text(AppLocalizations.of(context)!.equilibrer),
                  onPressed: _autoBalance,
                ),
                ElevatedButton.icon(
                  icon: Icon(Icons.add),
                  label: Text(AppLocalizations.of(context)!.equipe),
                  onPressed: _addTeam,
                ),
                if (teams.length > widget.minTeams)
                  ElevatedButton.icon(
                    icon: Icon(Icons.remove),
                    label: Text(AppLocalizations.of(context)!.retirer),
                    onPressed: _removeLastTeam,
                  ),
              ],
            ),
            SizedBox(height: 10),
            Expanded(
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children:
                      teams.entries.map((entry) {
                        int teamIndex = entry.key;
                        List<String> teamPlayers = entry.value;
                        return _buildTeamColumn(
                          GameContentLocalization.format(
                            context,
                            AppLocalizations.of(context)!.equipe1,
                            [teamIndex + 1],
                          ),
                          teamPlayers,
                          teamIndex,
                          teamColors[teamIndex % teamColors.length],
                        );
                      }).toList(),
                ),
              ),
            ),
            Divider(),
            Text(
              AppLocalizations.of(context)!.joueursNonAssignes.replaceAll(
                "{0}",
                unassignedPlayers.length.toString(),
              ),
            ),
            Expanded(
              flex: 0, // Taille minimale pour le Wrap
              child: SingleChildScrollView(
                child: Wrap(
                  spacing: 6,
                  children:
                      unassignedPlayers
                          .map(
                            (pId) => ActionChip(
                              label: Text(
                                widget.players[pId]?['name'] ?? '...',
                              ),
                              onPressed: () {
                                var smallestTeam = teams.entries.reduce(
                                  (a, b) =>
                                      a.value.length < b.value.length ? a : b,
                                );
                                _assignPlayer(pId, smallestTeam.key);
                              },
                            ),
                          )
                          .toList(),
                ),
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text(AppLocalizations.of(context)!.annuler),
        ),
        ElevatedButton(
          onPressed:
              canConfirm
                  ? () {
                    _firebaseService.updateTeams(widget.gameCode, teams);
                    Navigator.of(context).pop();
                  }
                  : null,
          child: Text(AppLocalizations.of(context)!.confirmerLesEquipes),
        ),
      ],
    );
  }

  Widget _buildTeamColumn(
    String title,
    List<String> team,
    int teamIndex,
    Color color,
  ) {
    return Container(
      width: 200, // Largeur fixe pour chaque colonne
      margin: EdgeInsets.all(4),
      decoration: BoxDecoration(
        border: Border.all(color: color.withOpacity(0.5)),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              title,
              style: TextStyle(color: color, fontWeight: FontWeight.bold),
            ),
          ),
          Expanded(
            child: ListView(
              children:
                  team
                      .map(
                        (pId) => ListTile(
                          title: Text(
                            widget.players[pId]?['name'] ?? '...',
                            overflow: TextOverflow.ellipsis,
                          ),
                          trailing: IconButton(
                            icon: Icon(Icons.undo, size: 18),
                            onPressed: () => _unassignPlayer(pId, teamIndex),
                          ),
                        ),
                      )
                      .toList(),
            ),
          ),
        ],
      ),
    );
  }
}

// Modèle pour une entrée d'historique IA
class AiThemeHistoryItem {
  final String id;
  String title;
  String prompt;
  String gameType;
  List<String> words;
  final DateTime createdAt;

  AiThemeHistoryItem({
    required this.id,
    required this.title,
    required this.prompt,
    required this.gameType,
    required this.words,
    required this.createdAt,
  });

  Map<String, dynamic> toMap() => {
    'title': title,
    'prompt': prompt,
    'gameType': gameType,
    'words': words,
    'createdAt': Timestamp.fromDate(createdAt),
  };

  factory AiThemeHistoryItem.fromDoc(DocumentSnapshot doc) {
    final data = doc.data() as Map<String, dynamic>? ?? {};
    return AiThemeHistoryItem(
      id: doc.id,
      title: data['title'] ?? _l10n.themeIa,
      prompt: data['prompt'] ?? '',
      gameType: data['gameType'] ?? '',
      words: List<String>.from(data['words'] ?? []),
      createdAt: (data['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),
    );
  }
}

class FirebaseService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  /// Retourne le nombre idéal d'éléments générés selon le jeu
  static int getAiWordCountForGame(String gameType) {
    switch (gameType) {
      case 'Codenames':
        return 35; // 25 requis pour la grille + réserve
      case "Time's Up":
      case 'Pictionary':
      case 'Devine Tête':
        return 40;
      case 'Just One':
        return 20; // 13 cartes pour une partie complète + réserve
      case 'Infiltré & Mr. White':
        return 20; // 20 paires "MotCivil:MotInfiltré"
      case 'Taboo':
        return 25; // 25 cartes
      case 'Petit Bac':
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return 20; // 20 catégories thématiques
      case 'Gribouillis':
        return 15; // 15 phrases de départ amusantes à dessiner
      case 'Cadavre Exquis':
        return 15; // 15 débuts de récits / univers inspirants
      case 'Le Dilemme':
        return 20; // 20 dilemmes au format "OptionA ou OptionB"
      case 'Action ou Vérité':
      case 'Jeu de la Pièce':
      case 'On se passe un objet rapidement':
      case 'Blanc Manger Coco':
      case 'Le Juge':
      case 'Le Menteur':
      case 'Qui Pourrait le Plus ?':
      case 'Le Roi des Mèmes':
        return 25;
      default:
        return 30;
    }
  }

  /// Retourne le nombre MINIMUM d'éléments requis pour que le jeu fonctionne sans accroc
  static int getMinAiWordCountForGame(String gameType) {
    switch (gameType) {
      case 'Codenames':
        return 25; // 25 requis pour remplir la grille 5x5
      case "Time's Up":
      case 'Devine Tête':
        return 20;
      case 'Just One':
        return 13;
      case 'Infiltré & Mr. White':
        return 10;
      case 'Taboo':
        return 15;
      case 'Petit Bac':
        return 6;
      case 'Gribouillis':
      case 'Cadavre Exquis':
        return 10;
      default:
        return 15;
    }
  }

  /// Retourne le nombre MAXIMUM d'éléments autorisés
  static int getMaxAiWordCountForGame(String gameType) {
    switch (gameType) {
      case 'Petit Bac':
        return 30;
      case 'Infiltré & Mr. White':
      case 'Taboo':
        return 50;
      case 'Codenames':
      case "Time's Up":
      case 'Devine Tête':
      case 'Pictionary':
        return 80;
      default:
        return 60;
    }
  }

  /// Instructions système personnalisées envoyées à la Cloud Function selon le jeu,
  /// supportant les thèmes multiples et le style/ton sélectionné.
  static String formatAiPromptForGame(
    String gameType,
    String userPrompt, {
    List<String>? themes,
    String? style,
  }) {
    final List<String> themeParts = [];
    if (themes != null && themes.isNotEmpty) {
      themeParts.addAll(themes);
    }
    if (userPrompt.trim().isNotEmpty) {
      themeParts.add(userPrompt.trim());
    }

    String combinedTheme =
        themeParts.isEmpty ? _l10n.generalEtVarie : themeParts.join(" + ");
    if (themeParts.length > 1) {
      combinedTheme = _l10n.melangeEquilibreDesThemesSuivants1(combinedTheme);
    }

    String styleInstruction = "";
    if (style != null && style.trim().isNotEmpty) {
      styleInstruction = _l10n.ambianceTonImpose(style);
    }

    final finalPrompt = "$combinedTheme$styleInstruction";

    switch (gameType) {
      case 'Infiltré & Mr. White':
        return _l10n.genereDesPairesDeMots1(finalPrompt);
      case 'Taboo':
        return _l10n.genereDesCartesTabooAu1(finalPrompt);
      case 'Petit Bac':
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return _l10n.genereDesCategoriesOriginalesEt1(finalPrompt);
      case 'Gribouillis':
        return _l10n.genereDesPhrasesCourtesVisuelles1(finalPrompt);
      case 'Cadavre Exquis':
        return _l10n.genereDesPhrasesDAccroche1(finalPrompt);
      case 'Le Dilemme':
        return _l10n.genereDesDilemmesCorneliensAu1(finalPrompt);
      case 'Action ou Vérité':
        return _l10n.genereUnMelangeDeDefis1(finalPrompt);
      case 'Jeu de la Pièce':
      case 'On se passe un objet rapidement':
        return _l10n.genereDesQuestionsDirectesAmusantes1(finalPrompt);
      case 'Blanc Manger Coco':
        return _l10n.genereDesPhrasesCourtesA1(finalPrompt);
      case 'Le Juge':
        return _l10n.aiPromptLeJuge(finalPrompt);
      case 'Qui Pourrait le Plus ?':
      case 'Le Roi des Mèmes':
      case 'Le Roi des Mêmes':
        return _l10n.genereDesSituationsHumoristiquesEt1(finalPrompt);
      default:
        return _l10n.genereUneListeDeMots1(gameType, finalPrompt);
    }
  }

  /// Enregistre un pack généré par l'IA directement dans Firestore
  Future<String> saveAiThemeToFirebase({
    required String uid,
    required String prompt,
    required String gameType,
    required List<String> words,
    String? title,
    String? existingDocId,
    List<String>? themes,
    String? style,
  }) async {
    final colRef = _db.collection('users').doc(uid).collection('ai_history');

    // Titre automatique généré si aucun titre fourni
    String autoTitle = title ?? '';
    if (autoTitle.trim().isEmpty) {
      if (prompt.trim().isNotEmpty) {
        autoTitle = prompt.trim();
        if (autoTitle.length > 28)
          autoTitle = "${autoTitle.substring(0, 28)}...";
      } else if (words.isNotEmpty) {
        autoTitle = _l10n.pack(words.take(2).join(', '));
      } else {
        autoTitle = _l10n.theme(gameType);
      }
    }

    final data = <String, dynamic>{
      'title': autoTitle,
      'prompt': prompt,
      'gameType': gameType,
      'words': words,
      'itemCount': words.length,
      if (themes != null && themes.isNotEmpty) 'themes': themes,
      if (style != null && style.isNotEmpty) 'style': style,
    };

    if (existingDocId != null && existingDocId.isNotEmpty) {
      data['updatedAt'] = FieldValue.serverTimestamp();
      await colRef.doc(existingDocId).set(data, SetOptions(merge: true));
      return existingDocId;
    } else {
      data['createdAt'] = FieldValue.serverTimestamp();
      final docRef = await colRef.add(data);
      return docRef.id;
    }
  }

  /// Écoute en temps réel de l'historique Firebase filtré par jeu ou 'all'.
  /// Tri côté client par date pour s'affranchir de tout index composite Firestore manquant.
  Stream<List<AiThemeHistoryItem>> getAiHistoryStream(
    String uid, [
    String? gameType,
  ]) {
    final colRef = _db.collection('users').doc(uid).collection('ai_history');
    if (gameType != null && gameType.isNotEmpty && gameType != 'all') {
      return colRef.where('gameType', isEqualTo: gameType).snapshots().map((
        snap,
      ) {
        final items =
            snap.docs.map((doc) => AiThemeHistoryItem.fromDoc(doc)).toList();
        items.sort((a, b) => b.createdAt.compareTo(a.createdAt));
        return items;
      });
    }
    return colRef.snapshots().map((snap) {
      final items =
          snap.docs.map((doc) => AiThemeHistoryItem.fromDoc(doc)).toList();
      items.sort((a, b) => b.createdAt.compareTo(a.createdAt));
      return items;
    });
  }

  /// Suppression d'un thème sur Firebase
  Future<void> deleteAiThemeFromFirebase(String uid, String docId) async {
    await _db
        .collection('users')
        .doc(uid)
        .collection('ai_history')
        .doc(docId)
        .delete();
  }

  /// Sauvegarde ou met à jour un pack IA dans l'historique de l'utilisateur (rétro-compatibilité)
  Future<String> saveAiThemeHistory({
    required String uid,
    required String prompt,
    required String gameType,
    required List<String> words,
    String? title,
    String? existingId,
  }) => saveAiThemeToFirebase(
    uid: uid,
    prompt: prompt,
    gameType: gameType,
    words: words,
    title: title,
    existingDocId: existingId,
  );

  /// Récupère le flux d'historique filtré pour un utilisateur et optionnellement par jeu (rétro-compatibilité)
  Stream<List<AiThemeHistoryItem>> getAiThemeHistoryStream(
    String uid, {
    String? gameType,
  }) => getAiHistoryStream(uid, gameType);

  /// Supprime une entrée d'historique (rétro-compatibilité)
  Future<void> deleteAiThemeHistory(String uid, String historyId) =>
      deleteAiThemeFromFirebase(uid, historyId);

  /// Signale et bloque un joueur (UGC report + liste des utilisateurs bloqués)
  Future<void> reportAndBlockPlayer({
    required String reporterId,
    required String reportedPlayerId,
    required String reportedPlayerName,
    required String gameCode,
    required String reason,
  }) async {
    try {
      await _db.collection('reports').add({
        'reporterId': reporterId,
        'reportedPlayerId': reportedPlayerId,
        'reportedPlayerName': reportedPlayerName,
        'gameCode': gameCode,
        'reason': reason,
        'timestamp': FieldValue.serverTimestamp(),
      });
      if (reporterId.isNotEmpty && reportedPlayerId.isNotEmpty) {
        await _db.collection('users').doc(reporterId).set({
          'blockedUsers': FieldValue.arrayUnion([reportedPlayerId]),
        }, SetOptions(merge: true));
      }
    } catch (e) {
      debugPrint('Error reporting/blocking player: $e');
    }
  }

  /// Débloque un joueur pour un utilisateur
  Future<void> unblockPlayer(String myId, String blockedPlayerId) async {
    try {
      if (myId.isNotEmpty && blockedPlayerId.isNotEmpty) {
        await _db.collection('users').doc(myId).set({
          'blockedUsers': FieldValue.arrayRemove([blockedPlayerId]),
        }, SetOptions(merge: true));
      }
    } catch (e) {
      debugPrint('Error unblocking player: $e');
    }
  }

  // =========================================================================
  // ⚡ MOTEUR D'XP ET CALCUL DU BONUS DE VITESSE DYNAMIQUE
  // =========================================================================

  /// Indique si la phase actuelle du jeu est simultanée (plusieurs joueurs agissent en même temps)
  static bool isSimultaneousPhase(Map<String, dynamic> gameData) {
    final String gameType = gameData['gameType'] ?? '';
    final String? roundState = gameData['roundState'] as String?;
    final String? currentPhase = gameData['currentPhase'] as String?;

    if (gameType == 'Petit Bac' ||
        gameType == 'Gribouillis' ||
        gameType == 'Cadavre Exquis' ||
        gameType == 'Photo Roulette' ||
        gameType == 'Le Dilemme') {
      return true;
    }
    if (gameType == 'Zéro Pointé' &&
        (roundState == 'revealing_initial' || roundState == 'round_end')) {
      return true;
    }
    if (gameType == 'Bataille Navale' && roundState == 'placement') {
      return true;
    }
    if (gameType == 'Just One' &&
        (roundState == 'clue_giving' || roundState == 'round_end')) {
      return true;
    }
    if ((gameType == 'Blanc Manger Coco' ||
            gameType == 'Blanc Manger Cocon' ||
            gameType == 'BMC') &&
        (roundState == 'judging_selection' || roundState == 'round_end')) {
      return true;
    }
    if (gameType == 'Infiltré & Mr. White' &&
        (roundState == 'voting' || roundState == 'turn_result')) {
      return true;
    }
    if (gameType == 'Loup-Garou' &&
        (currentPhase == 'loups_turn' ||
            currentPhase == 'jour_discussion' ||
            currentPhase == 'jour_vote' ||
            currentPhase == 'aube_annonce')) {
      return true;
    }
    if ((gameType == 'Qui Pourrait le Plus ?' ||
            gameType == 'Le Juge' ||
            gameType == 'Le Menteur' ||
            gameType == 'Le Roi des Mèmes' ||
            gameType == 'Le Roi des Mêmes' ||
            gameType == 'Synonyme ou Banni') &&
        (roundState == 'answering' ||
            roundState == 'voting' ||
            roundState == 'reveal_and_vote' ||
            roundState == 'result')) {
      return true;
    }
    if (gameType == 'Skull' &&
        (roundState == 'initial_placement' || roundState == 'result')) {
      return true;
    }
    return false;
  }

  static bool _isPlayerIdBot(Map<String, dynamic> gameData, String pid) {
    final players = gameData['players'] as Map<String, dynamic>?;
    if (players != null && players[pid] is Map) {
      final pData = players[pid] as Map;
      if (pData['isBot'] == true || pData['replacedByBot'] == true) return true;
    }
    final botPlayers = gameData['botPlayers'] as Map<String, dynamic>?;
    if (botPlayers != null && botPlayers[pid] == true) return true;
    return false;
  }

  /// Récupère l'ID du joueur dont c'est actuellement le tour
  static String? getCurrentPlayerId(Map<String, dynamic> gameData) {
    if (isSimultaneousPhase(gameData)) return null;

    final gameType = gameData['gameType'] ?? '';
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    if (gameType == 'Uno') {
      final unoOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['unoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < unoOrder.length) return unoOrder[idx];
    } else if (gameType == 'Mille Bornes') {
      final mbOrder = List<String>.from(
        gameData['milleBornesPlayerOrder'] ?? playerOrder,
      );
      final idx =
          (gameData['milleBornesCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < mbOrder.length) return mbOrder[idx];
    } else if (gameType == 'Petits Chevaux') {
      final pcOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['petitsChevauxCurrentIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < pcOrder.length) return pcOrder[idx];
    } else if (gameType == 'Big Two') {
      final btOrder = List<String>.from(
        gameData['bigTwoPlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['bigTwoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < btOrder.length) return btOrder[idx];
    } else if (gameType == 'Jeu de Dames') {
      final chOrder = List<String>.from(
        gameData['checkersPlayerOrder'] ?? playerOrder,
      );
      final idx =
          (gameData['checkersCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < chOrder.length) return chOrder[idx];
    } else if (gameType == 'Blokus') {
      final bOrder = List<String>.from(
        gameData['blokusPlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['blokusCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < bOrder.length) return bOrder[idx];
    } else if (gameType == 'Zombie!') {
      final zOrder = List<String>.from(
        gameData['zombiePlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['zombieCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < zOrder.length) return zOrder[idx];
    } else if (gameType == 'Belote') {
      final beloteOrder = List<String>.from(
        gameData['belotePlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['beloteCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < beloteOrder.length) return beloteOrder[idx];
    } else if (gameType == 'Dominoes') {
      final dOrder = List<String>.from(
        gameData['dominoesPlayerOrder'] ?? playerOrder,
      );
      final idx =
          (gameData['dominoesCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < dOrder.length) return dOrder[idx];
    } else if (gameType == 'Skull') {
      final idx = (gameData['skullCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < playerOrder.length) return playerOrder[idx];
    } else if (gameType == 'Rami') {
      if (gameData['ramiCurrentPlayerId'] != null) {
        return gameData['ramiCurrentPlayerId'] as String;
      }
    } else if (gameType == 'Yams') {
      if (gameData['yamsCurrentPlayerId'] != null) {
        return gameData['yamsCurrentPlayerId'] as String;
      }
    } else if (gameType == 'La Patate Chaude' ||
        gameType == 'Le Jeu des Catégories') {
      if (gameData['hotPotatoCurrentPlayerId'] != null) {
        return gameData['hotPotatoCurrentPlayerId'] as String;
      }
    } else if (gameType == 'Action ou Vérité') {
      if (gameData['aoVPhase'] == 'writing_challenge' &&
          gameData['aoVChallengeAuthor'] != null) {
        return gameData['aoVChallengeAuthor'] as String;
      }
      if (gameData['aoVCurrentPlayerId'] != null) {
        return gameData['aoVCurrentPlayerId'] as String;
      }
    } else if (gameType == 'Blanc Manger Coco' ||
        gameType == 'Blanc Manger Cocon' ||
        gameType == 'BMC') {
      if (gameData['bmcJudgeId'] != null) {
        return gameData['bmcJudgeId'] as String;
      }
    } else if (gameType == 'Just One') {
      if (gameData['justOneGuesserId'] != null) {
        return gameData['justOneGuesserId'] as String;
      }
    } else if (gameType == 'Zéro Pointé') {
      return gameData['currentPlayerId'] as String?;
    } else if (gameType == 'Loup-Garou') {
      return gameData['activePlayerId'] as String?;
    } else if (gameType == "Time's Up" || gameType == 'Devine Tête') {
      return gameData['currentGuesserId'] as String?;
    } else if (gameType == 'Taboo') {
      return gameData['tabooClueGiverId'] as String?;
    } else if (gameType == 'Codenames') {
      if (gameData['roundState'] == 'giving_clue') {
        return gameData['activeTeam'] == 'red'
            ? gameData['masterSpyRed'] as String?
            : gameData['masterSpyBlue'] as String?;
      }
      return null;
    } else if (gameData['currentPlayerIndex'] != null) {
      final idx = (gameData['currentPlayerIndex'] as num).toInt();
      if (idx >= 0 && idx < playerOrder.length) return playerOrder[idx];
    }
    return gameData['currentPlayerId'] as String?;
  }

  /// Détecte si le joueur dont c'est le tour (ou tous les joueurs restants d'une phase simultanée) est un robot / ordi
  static bool isCurrentPlayerBot(Map<String, dynamic> gameData) {
    if (isSimultaneousPhase(gameData)) {
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players.isEmpty) return false;
      final String gameType = gameData['gameType'] ?? '';
      final String? roundState = gameData['roundState'] as String?;
      Iterable<String> remaining = const [];

      if (gameType == 'Blanc Manger Coco' ||
          gameType == 'Blanc Manger Cocon' ||
          gameType == 'BMC') {
        if (roundState == 'judging_selection') {
          final played = Map<String, dynamic>.from(
            gameData['bmcPlayedCards'] ?? {},
          );
          final judgeId = gameData['bmcJudgeId'];
          remaining = players.keys.where(
            (id) => id != judgeId && !played.containsKey(id),
          );
        }
      } else if (gameType == 'Just One' && roundState == 'clue_giving') {
        final clues = Map<String, dynamic>.from(
          gameData['justOneSubmittedClues'] ?? {},
        );
        final guesserId = gameData['justOneGuesserId'];
        remaining = players.keys.where(
          (id) => id != guesserId && !clues.containsKey(id),
        );
      } else if (gameType == 'Zéro Pointé' &&
          roundState == 'revealing_initial') {
        final ready = List<String>.from(gameData['playersReady'] ?? []);
        remaining = players.keys.where((id) => !ready.contains(id));
      } else if (gameType == 'Bataille Navale' && roundState == 'placement') {
        final pData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
        remaining = players.keys.where(
          (id) => (pData[id] as Map?)?['ready'] != true,
        );
      } else if (gameType == 'Infiltré & Mr. White' && roundState == 'voting') {
        final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
        final pData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
        remaining = players.keys.where(
          (id) =>
              ((pData[id] as Map?)?['status'] ?? 'active') == 'active' &&
              !votes.containsKey(id),
        );
      } else if (gameType == 'Qui Pourrait le Plus ?' ||
          gameType == 'Le Juge' ||
          gameType == 'Le Menteur' ||
          gameType == 'Le Roi des Mèmes' ||
          gameType == 'Le Roi des Mêmes' ||
          gameType == 'Synonyme ou Banni') {
        if (roundState == 'answering') {
          final ans = Map<String, dynamic>.from(gameData['answers'] ?? {});
          remaining = players.keys.where((id) => !ans.containsKey(id));
        } else if (roundState == 'voting' || roundState == 'reveal_and_vote') {
          final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
          final targetId =
              gameType == 'Le Juge' ? gameData['jugeTargetId'] : null;
          remaining = players.keys.where(
            (id) => id != targetId && !votes.containsKey(id),
          );
        }
      }

      if (remaining.isNotEmpty &&
          remaining.every((id) => _isPlayerIdBot(gameData, id))) {
        return true;
      }
      return false;
    }

    final curId = getCurrentPlayerId(gameData);
    if (curId == null) return false;
    return _isPlayerIdBot(gameData, curId);
  }

  /// Récupère la durée effective du timer selon le jeu, ses réglages et son état
  static int getEffectiveTurnTimer(Map<String, dynamic> gameData) {
    // 1. Si le chrono a été désactivé par l'hôte, AUCUN timer (même pour les bots)
    final bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer) return 0;

    final String gameType = gameData['gameType'] ?? '';
    if (gameType == 'Dobble')
      return 0; // Dobble est un jeu de rapidité en temps réel

    // 0. Si le joueur actuel est un ordinateur (bot) ou a manqué un tour, le délai est fixé à 5 secondes
    if (isCurrentPlayerBot(gameData)) {
      return 5;
    }
    final curId = getCurrentPlayerId(gameData);
    if (curId != null) {
      final inactiveCounts =
          gameData['inactiveTurnCounts'] as Map<String, dynamic>?;
      if (inactiveCounts != null && (inactiveCounts[curId] as num? ?? 0) >= 1) {
        return 5;
      }
    }

    final int? customTurnTimer =
        (gameData['turnTimerSeconds'] as num?)?.toInt();

    // 2. Si une durée personnalisée globale a été définie (> 0)
    if (customTurnTimer != null && customTurnTimer > 0) {
      // Cas particuliers avec réglages spécifiques qui priment si configurés
      if (gameType == 'La Patate Chaude' &&
          gameData['hotPotatoUseGlobalTimer'] == true) {
        return (gameData['hotPotatoGlobalDuration'] as num?)?.toInt() ?? 60;
      }
      if (gameType == 'Petit Bac' && gameData['petitBacTime'] != null) {
        return (gameData['petitBacTime'] as num).toInt();
      }
      if (gameType == 'Photo Roulette') {
        return (gameData['photoRouletteTime'] as num?)?.toInt() ?? 5;
      }
      if (gameType == "Time's Up" && gameData['currentRoundTime'] != null) {
        return (gameData['currentRoundTime'] as num).toInt();
      }
      return customTurnTimer;
    }

    // 3. Durées par défaut spécifiques selon le type de jeu
    switch (gameType) {
      case 'Dobble':
        return 0;
      case 'Petit Bac':
        return (gameData['petitBacTime'] as num?)?.toInt() ?? 120;
      case 'Pictionary':
        return 90;
      case 'Devine Tête':
      case 'Taboo':
        return 60;
      case 'La Patate Chaude':
        return gameData['hotPotatoUseGlobalTimer'] == true
            ? ((gameData['hotPotatoGlobalDuration'] as num?)?.toInt() ?? 60)
            : 30;
      case 'Photo Roulette':
        return (gameData['photoRouletteTime'] as num?)?.toInt() ?? 5;
      case "Time's Up":
        return (gameData['currentRoundTime'] as num?)?.toInt() ?? 30;
      case 'Infiltré & Mr. White':
      case 'Loup-Garou':
      case 'Poker':
      case 'Uno':
      case 'Zéro Pointé':
      case 'Big Two':
      case 'Mille Bornes':
      case 'Rami':
      case 'Belote':
      case 'Yams':
      case 'Skull':
      case 'Blokus':
      case 'Petits Chevaux':
      case 'Jeu de Dames':
      case 'Dominoes':
      case 'Zombie!':
      case 'Blanc Manger Coco':
      case 'Qui Pourrait le Plus ?':
      case 'Le Menteur':
      case 'Synonyme ou Banni':
      case 'Le Roi des Mèmes':
      case 'Le Roi des Mêmes':
      default:
        return 30;
    }
  }

  /// Calcul du bonus de rapidité et de sang-froid basé sur le temps serveur et la durée réelle
  static int calculateSpeedBonus(
    Timestamp? turnStartTime, {
    required int effectiveTimerSeconds,
  }) {
    // Si pas de timestamp, ou chrono désactivé (<= 0) -> aucun bonus de vitesse
    if (turnStartTime == null || effectiveTimerSeconds <= 0) return 0;

    final int elapsedMs = max(
      0,
      DateTime.now().millisecondsSinceEpoch -
          turnStartTime.millisecondsSinceEpoch,
    );
    final double elapsedSeconds = (elapsedMs / 1000.0).clamp(
      0.0,
      effectiveTimerSeconds.toDouble(),
    );

    // Pourcentage du temps consommé par le joueur
    final double percentElapsed =
        (elapsedSeconds / effectiveTimerSeconds) * 100.0;

    if (percentElapsed <= 10.0)
      return 10; // 0% - 10%  -> +10 XP (Réflexe Éclair)
    if (percentElapsed <= 20.0) return 9; // 11% - 20% -> +9 XP (Ultra-Rapide)
    if (percentElapsed <= 30.0) return 8; // 21% - 30% -> +8 XP (Très Rapide)
    if (percentElapsed <= 40.0) return 7; // 31% - 40% -> +7 XP (Vif)
    if (percentElapsed <= 50.0) return 6; // 41% - 50% -> +6 XP (Bon tempo)
    if (percentElapsed <= 60.0) return 5; // 51% - 60% -> +5 XP (Calculé)
    if (percentElapsed <= 70.0) return 4; // 61% - 70% -> +4 XP (Stratégique)
    if (percentElapsed <= 80.0) return 3; // 71% - 80% -> +3 XP (Réfléchi)
    if (percentElapsed <= 90.0) return 2; // 81% - 90% -> +2 XP (In Extremis)
    return 1; // 91% - 100% -> +1 XP (Sur le fil)
  }

  /// Vérifie si le tour en cours a réellement dépassé la durée impartie
  static bool _isTurnTimedOut(
    Map<String, dynamic> gameData, {
    int? customDuration,
  }) {
    // Si c'est un robot/ordinateur, tolérance immédiate
    if (isCurrentPlayerBot(gameData)) return true;

    final turnStartTime =
        ((gameData['turnStartTime'] ??
                    gameData['roundStartTime'] ??
                    gameData['petitBacRoundStartTime'] ??
                    gameData['pictionaryStartTime'] ??
                    gameData['hotPotatoRoundStartedAt'])
                as Timestamp?)
            ?.toDate();
    if (turnStartTime == null) return false;
    final int duration = customDuration ?? getEffectiveTurnTimer(gameData);
    if (duration <= 0) return false;
    final int elapsed = DateTime.now().difference(turnStartTime).inSeconds;
    return elapsed >= (duration - 2); // Tolérance de 2s
  }

  /// Crédite l'XP au joueur en diversifiant les gains (vitesse, sang-froid, combo, difficulté, type de jeu, VIP)
  void creditPlayerXp(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
    int baseAmount, {
    bool applySpeedBonus = true,
    String?
    actionType, // 'precision', 'combo', 'bluff', 'defense', 'clutch', 'creativity'
  }) {
    if (baseAmount <= 0) return;

    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    // Si le joueur est un bot ou a été remplacé par un bot, il ne gagne rien (aucun XP)
    if (players[playerId]?['isBot'] == true ||
        players[playerId]?['replacedByBot'] == true ||
        gameData['botPlayers']?[playerId] == true) {
      return;
    }
    final authUid = players[playerId]?['authUid'] ?? playerId;
    final turnStartTime = gameData['turnStartTime'] as Timestamp?;

    // Détection automatique de la durée du timer réelle
    final int effectiveTimer = getEffectiveTurnTimer(gameData);

    int totalXp = baseAmount;

    // 1. Bonus Vitesse & Sang-froid (Temps de réponse)
    if (applySpeedBonus && turnStartTime != null && effectiveTimer > 0) {
      totalXp += calculateSpeedBonus(
        turnStartTime,
        effectiveTimerSeconds: effectiveTimer,
      );
    }

    // 2. Bonus de Combo d'Actions (Enchaînement d'actions réussies)
    final Map<String, dynamic> streaks = Map<String, dynamic>.from(
      gameData['playerActionStreaks'] ?? {},
    );
    final int currentStreak = (streaks[playerId] as num?)?.toInt() ?? 0;
    if (currentStreak >= 4) {
      totalXp += 12; // Combo Enflammé x5+ 🔥
    } else if (currentStreak >= 2) {
      totalXp += 7; // Super Série x3 ⚡
    } else if (currentStreak >= 1) {
      totalXp += 3; // Enchaînement x2 ✨
    }
    transaction.update(gameRef, {
      'playerActionStreaks.$playerId': FieldValue.increment(1),
    });

    // 3. Bonus selon la Difficulté de la Partie
    final String difficulty =
        (gameData['difficulty'] as String?)?.toLowerCase() ?? '';
    if (difficulty == 'hardcore' || difficulty == 'expert') {
      totalXp += 6; // Mode Extrême
    } else if (difficulty == 'medium' || difficulty == 'difficile') {
      totalXp += 3; // Défi Supérieur
    }

    // 4. Bonus Thématique selon la Catégorie du Jeu
    final String gameType = (gameData['gameType'] as String?) ?? '';
    if (gameType == 'Uno' ||
        gameType == 'Poker' ||
        gameType == 'Belote' ||
        gameType == 'Président' ||
        gameType == 'Rami' ||
        gameType == 'Big Two' ||
        gameType == 'Skull' ||
        gameType == 'Zéro Pointé' ||
        gameType == 'Mille Bornes') {
      totalXp += 5; // Coup Tactique de Cartes
    } else if (gameType == 'Blokus' ||
        gameType == 'Yams' ||
        gameType == 'Dominoes' ||
        gameType == 'Bataille Navale' ||
        gameType == 'Jeu de Dames' ||
        gameType == 'Petits Chevaux') {
      totalXp += 6; // Manœuvre Stratégique de Plateau
    } else if (gameType == 'Petit Bac' ||
        gameType == 'Taboo' ||
        gameType == "Time's Up" ||
        gameType == 'Synonyme ou Banni' ||
        gameType == 'Codenames' ||
        gameType == 'Devine Tête') {
      totalXp += 6; // Intuition & Maîtrise du Vocabulaire
    } else if (gameType == 'Loup-Garou' || gameType == 'Infiltré & Mr. White') {
      totalXp += 8; // Déduction & Flair Psychologique
    } else if (gameType == 'Dobble' || gameType == 'La Patate Chaude') {
      totalXp += 6; // Réflexe d'Adrénaline
    } else if (gameType == 'Pictionary' ||
        gameType == 'Gribouillis' ||
        gameType == 'Cadavre Exquis' ||
        gameType == 'Le Roi des Mèmes') {
      totalXp += 5; // Créativité & Spontanéité
    }

    // 5. Bonus selon le Style Spécifique de l'Action
    if (actionType != null) {
      switch (actionType) {
        case 'precision':
          totalXp += 6; // Action d'une précision chirurgicale
          break;
        case 'combo':
          totalXp += 8; // Combinaison multiple
          break;
        case 'bluff':
          totalXp += 8; // Coup de bluff audacieux
          break;
        case 'defense':
          totalXp += 7; // Parade / Contre défensif
          break;
        case 'clutch':
          totalXp += 10; // Action décisive in extremis
          break;
        case 'creativity':
          totalXp += 6; // Coup créatif ou inspiré
          break;
      }
    }

    // 6. Bonus Abonné VIP (+50% d'XP sur chaque action en jeu)
    final bool isVip =
        players[playerId]?['isPremium'] == true ||
        gameData['isPremiumLobby'] == true;
    if (isVip) {
      totalXp = (totalXp * 1.5).round();
    }

    // 1. Mise à jour de la session de jeu
    transaction.update(gameRef, {
      'players.$playerId.xp': FieldValue.increment(totalXp),
    });

    // 2. Mise à jour du profil utilisateur persistant
    final userDocRef = _db.collection('users').doc(authUid);
    transaction.set(userDocRef, {
      'xp': FieldValue.increment(totalXp),
    }, SetOptions(merge: true));
  }

