  // =========================================================================
  // GESTION PROPRE DU DÉPART DU SALON (NE SUPPRIME PAS LE SALON DE L'HÔTE)
  // =========================================================================
  Future<void> leaveLounge(String loungeId, String playerId) async {
    final docRef = _db.collection('lounges').doc(loungeId);

    try {
      await docRef.collection('presences').doc(playerId).delete();
    } catch (_) {}

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(docRef);
      if (!snap.exists) return;

      final data = snap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(data['players'] ?? {});
      final String hostId = data['hostId'] ?? '';

      // Si c'est l'hôte qui navigue, on met à jour son statut sans supprimer le salon
      if (hostId == playerId) {
        transaction.update(docRef, {
          'players.$playerId.isOnline': false,
          'streamers': FieldValue.arrayRemove([playerId]),
        });
        return;
      }

      // Si c'est un invité qui part
      players.remove(playerId);
      final updates = <String, dynamic>{
        'players.$playerId': FieldValue.delete(),
        'streamers': FieldValue.arrayRemove([playerId]),
      };

      final pendingGame = data['pendingGame'] as Map<String, dynamic>?;
      if (pendingGame != null) {
        updates['pendingGame.joinedPlayers'] = FieldValue.arrayRemove([
          playerId,
        ]);
      }

      transaction.update(docRef, updates);
    });
  }

  /// Suppression définitive du salon (Uniquement si l'hôte clique sur "Supprimer")
  Future<void> deleteLounge(String loungeId) async {
    final docRef = _db.collection('lounges').doc(loungeId);
    await docRef.delete();
  }

  Future<void> sweepLoungeGame(String loungeId) async {
    try {
      final loungeDoc = await _db.collection('lounges').doc(loungeId).get();
      if (!loungeDoc.exists) return;
      final lData = loungeDoc.data() as Map<String, dynamic>;
      final pendingGame = lData['pendingGame'] as Map<String, dynamic>?;
      if (pendingGame == null) return;

      final String gameCode = pendingGame['gameCode'] ?? '';
      final String hostId = pendingGame['hostId'] ?? '';
      final String status = pendingGame['status'] ?? '';
      final now = DateTime.now();

      // 1. Si le gameCode est vide
      if (gameCode.isEmpty) {
        await _db.collection('lounges').doc(loungeId).update({
          'pendingGame': FieldValue.delete(),
        });
        return;
      }

      final gameDoc = await _db.collection('games').doc(gameCode).get();
      if (!gameDoc.exists) {
        await _db.collection('lounges').doc(loungeId).update({
          'pendingGame': FieldValue.delete(),
        });
        return;
      }

      final gData = gameDoc.data() as Map<String, dynamic>;
      final String gState = gData['gameState'] ?? '';

      // 2. Si la partie est terminée ou annulée
      if (gState == 'gameOver' ||
          gState == 'finished' ||
          gState == 'cancelled' ||
          status == 'cancelled' ||
          status == 'finished') {
        String winnerName =
            gData['players']?[gData['gameWinner']]?['name'] ?? _l10n.inconnu;
        String reason = gData['gameEndReason'] ?? '';
        await _db.collection('lounges').doc(loungeId).update({
          'pendingGame': FieldValue.delete(),
          'lastGameResult': {
            'gameName':
                gData['gameType'] ?? pendingGame['gameName'] ?? _l10n.jeu1,
            'winnerName': winnerName,
            'reason': reason,
            'timestamp': FieldValue.serverTimestamp(),
          },
        });
        return;
      }

      // 3. Détection si l'hôte a quitté subitement ou perdu sa connexion pendant l'attente
      if (status == 'waiting') {
        final players = lData['players'] as Map<String, dynamic>? ?? {};
        final hostData = players[hostId] as Map<String, dynamic>?;

        bool hostMissing = !players.containsKey(hostId);
        bool hostExplicitlyOffline =
            hostData != null && hostData['isOnline'] == false;
        bool hostHeartbeatDead = false;

        try {
          final presDoc =
              await _db
                  .collection('lounges')
                  .doc(loungeId)
                  .collection('presences')
                  .doc(hostId)
                  .get();
          if (presDoc.exists) {
            final ts = presDoc.data()?['lastHeartbeat'] as Timestamp?;
            if (ts != null && now.difference(ts.toDate()).inSeconds > 35) {
              hostHeartbeatDead = true;
            }
          } else {
            final ts = hostData?['lastHeartbeat'] as Timestamp?;
            if (ts != null && now.difference(ts.toDate()).inSeconds > 35) {
              hostHeartbeatDead = true;
            }
          }
        } catch (_) {}

        if (hostMissing || hostExplicitlyOffline || hostHeartbeatDead) {
          await _db.collection('lounges').doc(loungeId).update({
            'pendingGame': FieldValue.delete(),
          });
          await _db
              .collection('games')
              .doc(gameCode)
              .update({
                'gameState': 'cancelled',
                'gameEndReason': _l10n.abandonTousLesJoueursDeconnectes,
              })
              .catchError((_) {});

          await sendLoungeMessage(
            loungeId,
            'system',
            _l10n.systeme,
            _l10n.tousLesJoueursSeSont,
            type: 'system',
          );
          return;
        }
      }

      // 4. Détection quand la partie est commencée
      if (status == 'started') {
        final presencesSnap =
            await _db
                .collection('games')
                .doc(gameCode)
                .collection('presences')
                .get();
        bool hasActivePlayer = false;

        for (var pDoc in presencesSnap.docs) {
          final pMap = pDoc.data();
          final ts = pMap['lastHeartbeat'] as Timestamp?;
          if (ts != null && now.difference(ts.toDate()).inSeconds < 35) {
            hasActivePlayer = true;
            break;
          }
        }

        if (!hasActivePlayer && presencesSnap.docs.isNotEmpty) {
          await _db.collection('games').doc(gameCode).update({
            'gameState': 'gameOver',
            'gameEndReason': _l10n.abandonTousLesJoueursDeconnectes,
          });
          await sendLoungeMessage(
            loungeId,
            'system',
            _l10n.systeme,
            _l10n.laPartieEstTermineeTous,
            type: 'game_result',
            extraData: {
              'gameName': gData['gameType'] ?? pendingGame['gameName'],
              'winnerName': _l10n.aucun,
              'reason': _l10n.tousLesJoueursSeSont,
              'oldGameCode': gameCode,
            },
          );
          await _db.collection('lounges').doc(loungeId).update({
            'pendingGame': FieldValue.delete(),
            'lastGameResult': {
              'gameName': gData['gameType'] ?? pendingGame['gameName'],
              'winnerName': _l10n.aucun,
              'reason': _l10n.tousLesJoueursSeSont,
              'timestamp': FieldValue.serverTimestamp(),
            },
          });
        }
      }
    } catch (_) {}
  }

