  /// Appel sécurisé vers la Cloud Function pour la génération de mots IA
  static Future<List<String>> generateAiWords({
    required String instructions,
    int count = 20,
    String gameType = '',
  }) async {
    try {
      final HttpsCallable callable = FirebaseFunctions.instance.httpsCallable(
        'generateAiWords',
      );
      final result = await callable.call({
        'instructions': instructions,
        'count': count,
        'gameType': gameType,
        ...ForceUpdateService.versionPayload,
      });

      if (result.data is List) {
        return List<String>.from(result.data);
      }
    } catch (e) {
      debugPrint("Erreur generateAiWords sécurisé : $e");
    }
    return [];
  }

  /// Validation sécurisée de l'indice Just One via Cloud Function
  static Future<bool> validateJustOneClueAi({
    required String clue,
    required String targetWord,
  }) async {
    try {
      final HttpsCallable callable = FirebaseFunctions.instance.httpsCallable(
        'validateJustOneClue',
      );
      final result = await callable.call({
        'clue': clue,
        'targetWord': targetWord,
        ...ForceUpdateService.versionPayload,
      });
      return result.data['isValid'] == true;
    } catch (e) {
      debugPrint("Erreur validateJustOneClueAi : $e");
      return true; // Fail-open pour ne pas bloquer le jeu en cas de panne réseau
    }
  }

  int _getMinPlayersForGame(String gameType) {
    switch (gameType) {
      case 'Zombie!':
      case 'Belote':
      case 'Petits Chevaux':
        return 4;
      case 'Loup-Garou':
        return 5;
      case 'Synonyme ou Banni':
      case 'Infiltré & Mr. White':
      case 'Photo Roulette':
        return 3;
      default:
        return 2;
    }
  }

  /// 1. Vote pour rejouer : Si 100% des joueurs ont voté, relance immédiate
  Future<void> submitRestartVote(String gameCode, String playerId) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final data = snap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(data['players'] ?? {});
      final playerProfiles = Map<String, dynamic>.from(
        data['playerProfiles'] ?? {},
      );

      // Sauvegarde préalable de tous les profils existants
      players.forEach((pId, pData) {
        if (pData is Map) {
          playerProfiles[pId] = Map<String, dynamic>.from(pData);
        }
      });

      // Rassembler tous les IDs de joueurs ayant participé à cette session
      final Set<String> allPlayerIds = {};
      allPlayerIds.addAll(players.keys);
      allPlayerIds.addAll(playerProfiles.keys);
      if (data['playerOrder'] is List) {
        allPlayerIds.addAll(
          (data['playerOrder'] as List).map((e) => e.toString()),
        );
      }
      for (String key in [
        'bigTwoPlayerOrder',
        'belotePlayerOrder',
        'unoPlayerOrder',
        'tarotPlayerOrder',
        'ramiPlayerOrder',
        'yamsPlayerOrder',
        'yamsScores',
      ]) {
        if (data[key] is List) {
          allPlayerIds.addAll((data[key] as List).map((e) => e.toString()));
        } else if (data[key] is Map) {
          allPlayerIds.addAll((data[key] as Map).keys.map((e) => e.toString()));
        }
      }
      allPlayerIds.add(playerId);

      // Restaurer chaque joueur dans players pour éviter les disparitions et "Inconnu"
      for (String pId in allPlayerIds) {
        if (!players.containsKey(pId) || players[pId] is! Map) {
          final profile =
              playerProfiles[pId] is Map
                  ? Map<String, dynamic>.from(playerProfiles[pId])
                  : {};
          players[pId] = {
            'name': profile['name'] ?? _l10n.joueur,
            'score': profile['score'] ?? 0,
            'xp': profile['xp'] ?? 0,
            'authUid': profile['authUid'] ?? pId,
            'livekitIdentity': profile['livekitIdentity'] ?? pId,
          };
        } else {
          final pMap = Map<String, dynamic>.from(players[pId]);
          if ((pMap['name'] == null ||
                  pMap['name'] == 'Inconnu' ||
                  pMap['name'].toString().trim().isEmpty) &&
              playerProfiles[pId] is Map &&
              playerProfiles[pId]['name'] != null &&
              playerProfiles[pId]['name'] != 'Inconnu') {
            pMap['name'] = playerProfiles[pId]['name'];
            players[pId] = pMap;
          }
        }
      }

      final restartVotes = Map<String, dynamic>.from(
        data['restartVotes'] ?? {},
      );
      restartVotes[playerId] = true;

      final String gameType = data['gameType'] ?? '';
      final int minRequired = _getMinPlayersForGame(gameType);
      final int totalSessionPlayers = players.length;

      transaction.update(gameRef, {
        'players': players,
        'playerProfiles': playerProfiles,
        'restartVotes': restartVotes,
      });

      // Si TOUT LE MONDE a cliqué sur Rejouer et qu'on a le minimum requis -> Relance auto instantanée
      if (restartVotes.length >= totalSessionPlayers &&
          totalSessionPlayers >= minRequired) {
        final Map<String, dynamic> playerXpResets = {};
        players.forEach((pId, _) {
          playerXpResets['players.$pId.xp'] = 0;
        });

        transaction.update(gameRef, {
          'players': players,
          'playerProfiles': playerProfiles,
          'playerOrder': players.keys.toList(),
          'gameState': 'playing',
          'roundState': 'waitingForStart',
          'currentRound': FieldValue.increment(1),
          'gameWinner': null,
          'gameEndReason': null,
          'roundWinnerId': null,
          'roundLoserId': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'restartVotes': {},
          'beloteTeamScores': {},
          'beloteTotalScores': {},
          'ramiTotalScores': {},
          'ramiRoundScores': {},
          'ramiMelds': {},
          'yamsScores': {},
          'totalScores': {},
          ...playerXpResets,
        });
      }
    });

    // Vérifier si la transaction a relancé la partie
    final freshSnap = await gameRef.get();
    if (freshSnap.exists && freshSnap.get('gameState') == 'playing') {
      await startGame(gameCode);
    }
  }

  /// 2. Fin des 30 secondes : Démarre la manche avec tous les joueurs présents sans supprimer personne
  Future<void> handleRestartDecisionTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final data = snap.data() as Map<String, dynamic>;

      if (data['gameState'] == 'playing') return; // Déjà relancé

      final players = Map<String, dynamic>.from(data['players'] ?? {});
      final playerProfiles = Map<String, dynamic>.from(
        data['playerProfiles'] ?? {},
      );

      // On préserve l'intégralité des profils et des joueurs
      players.forEach((pId, pData) {
        if (pData is Map) {
          playerProfiles[pId] = Map<String, dynamic>.from(pData);
        }
      });

      // Rassembler tous les participants connus
      final Set<String> allPlayerIds = {};
      allPlayerIds.addAll(players.keys);
      allPlayerIds.addAll(playerProfiles.keys);
      if (data['playerOrder'] is List) {
        allPlayerIds.addAll(
          (data['playerOrder'] as List).map((e) => e.toString()),
        );
      }
      for (String key in [
        'bigTwoPlayerOrder',
        'belotePlayerOrder',
        'unoPlayerOrder',
        'tarotPlayerOrder',
        'ramiPlayerOrder',
        'yamsPlayerOrder',
        'yamsScores',
      ]) {
        if (data[key] is List) {
          allPlayerIds.addAll((data[key] as List).map((e) => e.toString()));
        } else if (data[key] is Map) {
          allPlayerIds.addAll((data[key] as Map).keys.map((e) => e.toString()));
        }
      }

      for (String pId in allPlayerIds) {
        if (!players.containsKey(pId) || players[pId] is! Map) {
          final profile =
              playerProfiles[pId] is Map
                  ? Map<String, dynamic>.from(playerProfiles[pId])
                  : {};
          players[pId] = {
            'name': profile['name'] ?? _l10n.joueur,
            'score': profile['score'] ?? 0,
            'xp': profile['xp'] ?? 0,
            'authUid': profile['authUid'] ?? pId,
            'livekitIdentity': profile['livekitIdentity'] ?? pId,
          };
        } else {
          final pMap = Map<String, dynamic>.from(players[pId]);
          if ((pMap['name'] == null ||
                  pMap['name'] == 'Inconnu' ||
                  pMap['name'].toString().trim().isEmpty) &&
              playerProfiles[pId] is Map &&
              playerProfiles[pId]['name'] != null &&
              playerProfiles[pId]['name'] != 'Inconnu') {
            pMap['name'] = playerProfiles[pId]['name'];
            players[pId] = pMap;
          }
        }
      }

      final restartVotes = Map<String, dynamic>.from(
        data['restartVotes'] ?? {},
      );
      final String gameType = data['gameType'] ?? '';
      final int minRequired = _getMinPlayersForGame(gameType);
      String currentHost =
          data['hostId'] ?? (players.isNotEmpty ? players.keys.first : '');

      final Map<String, dynamic> playerXpResets = {};
      players.forEach((pId, _) {
        playerXpResets['players.$pId.xp'] = 0;
      });

      // CAS A : Assez de joueurs présents (>= minRequired) et au moins 1 a voté Rejouer
      // -> Relance automatique pour tout le monde avec scores conservés !
      if (players.length >= minRequired && restartVotes.isNotEmpty) {
        transaction.update(gameRef, {
          'players': players,
          'playerProfiles': playerProfiles,
          'hostId': currentHost,
          'playerOrder': players.keys.toList(),
          'gameState': 'playing',
          'roundState': 'waitingForStart',
          'currentRound': FieldValue.increment(1),
          'gameWinner': null,
          'gameEndReason': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'restartVotes': {},
          'beloteTeamScores': {},
          'beloteTotalScores': {},
          'ramiTotalScores': {},
          'ramiRoundScores': {},
          'ramiMelds': {},
          'yamsScores': {},
          'totalScores': {},
          'gameLog': FieldValue.arrayUnion([
            _l10n.finDuCompteARebours1(players.length),
          ]),
          ...playerXpResets,
        });
      }
      // CAS B : Aucun vote ou moins de joueurs que le minimum -> Salon d'attente sans perte de profil
      else {
        transaction.update(gameRef, {
          'players': players,
          'playerProfiles': playerProfiles,
          'hostId': currentHost,
          'playerOrder': players.keys.toList(),
          'gameState': 'lobby',
          'roundState': 'waitingForStart',
          'currentRound': 0,
          'gameWinner': null,
          'gameEndReason': null,
          'turnStartTime': null,
          'restartVotes': {},
          ...playerXpResets,
          'gameLog': FieldValue.arrayUnion([
            _l10n.scoresConservesEnAttenteDans,
          ]),
        });
      }
    });

    final checkSnap = await gameRef.get();
    if (checkSnap.exists && checkSnap.get('gameState') == 'playing') {
      await startGame(gameCode);
    }
  }

  // 3. Logique pour rejoindre une partie en cours de "refilling" (Remplacement)
  Future<bool> joinRefillingGame(
    String gameCode,
    String playerName,
    String playerId,
  ) async {
    return _db.runTransaction((transaction) async {
      DocumentReference gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot snap = await transaction.get(gameRef);

      if (!snap.exists || snap['gameState'] != 'refilling') return false;

      Map<String, dynamic> players = Map.from(snap['players']);
      int targetCount =
          snap['playerCount'] ?? 0; // Le nombre de joueurs visé à la création

      if (players.length >= targetCount) return false; // Déjà plein

      // Ajouter le joueur
      User? currentUser = FirebaseAuth.instance.currentUser;
      players[playerId] = {
        'name': playerName,
        'score': 0,
        'xp': 0,
        'authUid': currentUser?.uid,
        'livekitIdentity': playerId,
      };

      Map<String, dynamic> updates = {
        'players': players,
        'gameLog': FieldValue.arrayUnion([_l10n.aRejointLaPartie(playerName)]),
      };

      // Si l'ancien hôte n'est plus là, le nouveau prend le relais (selon ta règle)
      // Note : on a déjà géré le transfert basique dans handleRestartDecisionTimeout,
      // mais si on veut que le NOUVEAU soit hôte :
      // updates['hostId'] = playerId; // Décommenter si tu veux STRICTEMENT que le nouveau soit l'hôte

      transaction.update(gameRef, updates);
      return true;
    });
  }

  // 4. Forcer le démarrage après les 10s de recherche
  Future<void> forceStartAfterRefill(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot snap = await gameRef.get();
    if (snap.exists && snap['gameState'] == 'refilling') {
      // Choisir un hôte aléatoire
      Map<String, dynamic> players = snap['players'];
      List<String> ids = players.keys.toList();
      String randomHost = ids[new Random().nextInt(ids.length)];

      await gameRef.update({'hostId': randomHost});
      await startGame(gameCode);
    }
  }

  // =========================================================================
  // 26. JUST ONE
  // =========================================================================
  Future<void> handleJustOneTimeout(String gameCode) async {
    final preSnap = await _db.collection('games').doc(gameCode).get();
    if (!preSnap.exists) return;
    final preData = preSnap.data() as Map<String, dynamic>;
    if (preData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(preData)) return;

    if (preData['roundState'] == 'result') {
      await nextJustOneRound(gameCode);
      return;
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      String roundState = gameData['roundState'] ?? '';

      if (roundState == 'guesser_chooses_word') {
        List<String> words = List<String>.from(gameData['justOneWords'] ?? []);
        if (words.isEmpty) {
          words = List<String>.from(
            GameWords.justOneWords[gameData['difficulty']] ??
                GameWords.justOneWords['soft']!,
          )..shuffle();
        }
        if (words.isNotEmpty) {
          final String randomWord = words[Random().nextInt(words.length)];
          transaction.update(gameRef, {
            'justOneCurrentWord': randomWord,
            'roundState': 'clue_giving',
            'justOneClues': {},
            'justOneFilteredClues': [],
            'justOneGuesserAnswer': null,
            'justOneRevealIndex': 0,
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      } else if (roundState == 'clue_giving') {
        Map<String, dynamic> players = gameData['players'];
        Map<String, dynamic> clues = Map.from(gameData['justOneClues'] ?? {});
        String guesserId = gameData['justOneGuesserId'];

        for (final pId in players.keys) {
          if (pId != guesserId && !clues.containsKey(pId)) {
            clues[pId] = "INACTIF_$pId";
          }
        }

        String normalizeJustOneClue(String raw) {
          var s = raw.toLowerCase().trim();
          const withDia = 'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ';
          const withoutDia = 'aaaaaaceeeeiiiinooooouuuuyy';
          for (int i = 0; i < withDia.length; i++) {
            s = s.replaceAll(withDia[i], withoutDia[i]);
          }
          s = s.replaceAll(RegExp(r'[^a-z0-9]'), '');
          if (s.length > 3 && s.endsWith('s') && !s.endsWith('ss')) {
            s = s.substring(0, s.length - 1);
          }
          return s;
        }

        final String targetNorm = normalizeJustOneClue(
          (gameData['justOneCurrentWord'] ?? '').toString(),
        );
        Map<String, int> normalizedCounts = {};
        for (var c in clues.values) {
          final String raw = c.toString();
          if (raw.startsWith("INACTIF_")) continue;
          final String norm = normalizeJustOneClue(raw);
          if (norm.isEmpty) continue;
          normalizedCounts[norm] = (normalizedCounts[norm] ?? 0) + 1;
        }

        List<String> filteredClues = [];
        for (var c in clues.values) {
          final String raw = c.toString();
          if (raw.startsWith("INACTIF_")) continue;
          final String norm = normalizeJustOneClue(raw);
          if (norm.isNotEmpty &&
              norm != targetNorm &&
              normalizedCounts[norm] == 1) {
            filteredClues.add(raw);
          }
        }

        transaction.update(gameRef, {
          'justOneClues': clues,
          'justOneFilteredClues': filteredClues,
          'roundState': 'reveal_clues',
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else if (roundState == 'reveal_clues' || roundState == 'guessing') {
        transaction.update(gameRef, {
          'justOneGuesserAnswer': _l10n.tempsEcoule1,
          'roundState': 'result',
          'gameEndReason': _l10n.tempsEcoule,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> startPhotoRouletteVoting(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (gameSnap.exists && gameSnap.get('roundState') == 'showing_photo') {
        transaction.update(gameRef, {'roundState': 'voting'});
      }
    });
  }

  Future<void> handleSimultaneousInputTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final String roundState = gameData['roundState'];
      if (roundState != 'answering' && roundState != 'declaring_truth') return;

      final players = Map<String, dynamic>.from(gameData['players']);
      bool updatesMade = false;

      if (roundState == 'answering') {
        final answers = Map<String, dynamic>.from(gameData['answers'] ?? {});
        final gameType = gameData['gameType'] ?? '';
        final bool isSocial = GameData.isSocialOpinionGame(gameType);

        String? judgeId;
        if (gameType == 'Le Juge') judgeId = gameData['currentTargetPlayerId'];

        for (var pId in players.keys) {
          if (pId == judgeId) continue;
          if (!answers.containsKey(pId)) {
            // Sur jeu social / opinion : marquer comme inactif sans réponse arbitraire
            answers[pId] = isSocial ? "[INACTIF]" : _l10n.tempsEcoule2;
            updatesMade = true;
            await _incrementInactiveCountAndCheckExpulsion(
              transaction,
              gameRef,
              gameData,
              pId,
            );
          }
        }

        if (updatesMade ||
            answers.length >=
                (judgeId != null ? players.length - 1 : players.length)) {
          String nextState = 'voting';
          if (gameType == 'Le Menteur' &&
              gameData['isSimplifiedLiar'] == true) {
            nextState = 'declaring_truth';
          }
          transaction.update(gameRef, {
            'answers': answers,
            'roundState': nextState,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([_l10n.leTempsEstEcouleOn]),
          });
        }
      } else if (roundState == 'declaring_truth') {
        final storyTruths = Map<String, dynamic>.from(
          gameData['storyTruths'] ?? {},
        );
        final bool isSocial = GameData.isSocialOpinionGame(
          gameData['gameType'] ?? '',
        );
        for (var pId in players.keys) {
          if (!storyTruths.containsKey(pId)) {
            storyTruths[pId] = isSocial ? false : Random().nextBool();
            updatesMade = true;
            await _incrementInactiveCountAndCheckExpulsion(
              transaction,
              gameRef,
              gameData,
              pId,
            );
          }
        }
        if (updatesMade || storyTruths.length == players.length) {
          String voteMode = gameData['liarVoteMode'] ?? 'simultaneous';
          transaction.update(gameRef, {
            'storyTruths': storyTruths,
            'roundState':
                (voteMode == 'turn_by_turn') ? 'reveal_and_vote' : 'voting',
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([_l10n.leTempsEstEcoulePour]),
          });
        }
      }
    });
  }

  // =========================================================================
  // 9. BATAILLE NAVALE - TIR ET GESTION DU TIMEOUT
  // =========================================================================
  Future<void> shootBatailleNavale(
    String gameCode,
    String playerId,
    int targetIndex, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    if (targetIndex < 0 || targetIndex >= 100) {
      throw Exception(_l10n.cibleHorsDeLaGrille);
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'playing' ||
          gameData['currentPlayerId'] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      List<String> playerIds = playerData.keys.toList();
      String opponentId = playerIds.firstWhere(
        (id) => id != playerId,
        orElse: () => '',
      );
      if (opponentId.isEmpty) return;

      var shooterData = Map<String, dynamic>.from(playerData[playerId] ?? {});
      var opponentData = Map<String, dynamic>.from(
        playerData[opponentId] ?? {},
      );

      var enemyGrid = List<String>.from(
        shooterData['enemyGrid'] ?? List.filled(100, 'unknown'),
      );
      var opponentIncomingGrid = List<String>.from(
        opponentData['incomingGrid'] ?? List.filled(100, 'unknown'),
      );
      var opponentGrid = List<int>.from(
        opponentData['myGrid'] ?? List.filled(100, 0),
      );
      var opponentShips = Map<String, dynamic>.from(
        opponentData['shipsPlaced'] ?? {},
      );

      if (enemyGrid[targetIndex] != 'unknown') {
        throw Exception(_l10n.caseDejaCiblee);
      }

      String result = 'miss';
      if (opponentGrid[targetIndex] != 0) {
        result = 'hit';
        int shipId = opponentGrid[targetIndex];

        for (var entry in opponentShips.entries) {
          var ship = Map<String, dynamic>.from(entry.value);
          if (ship['id'] == shipId) {
            ship['hits'] = (ship['hits'] as int) + 1;
            if (ship['hits'] >= ship['area']) {
              ship['sunk'] = true;
              result = 'sunk';
              for (int i = 0; i < 100; i++) {
                if (opponentGrid[i] == shipId) {
                  enemyGrid[i] = 'sunk';
                  opponentIncomingGrid[i] = 'sunk';
                }
              }
            }
            opponentShips[entry.key] = ship;
            break;
          }
        }
        if (result == 'sunk') {
          opponentData['shipsSunk'] =
              (opponentData['shipsSunk'] as int? ?? 0) + 1;
        }
      }

      enemyGrid[targetIndex] = result;
      opponentIncomingGrid[targetIndex] = result;

      int xpBase = 2; // Tir à l'eau
      if (enemyGrid.where((cell) => cell != 'unknown').length == 1 &&
          (result == 'hit' || result == 'sunk')) {
        xpBase = 50; // Sniper 1er coup
        if (!isAuto && currentAuthUid != null) {
          _db.collection('users').doc(currentAuthUid).set({
            'unlockedBadges.naval_sniper': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      } else if (result == 'sunk') {
        xpBase = 25; // Coulé
      } else if (result == 'hit') {
        xpBase = 10; // Touché
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      shooterData['enemyGrid'] = enemyGrid;
      opponentData['incomingGrid'] = opponentIncomingGrid;
      opponentData['shipsPlaced'] = opponentShips;
      playerData[playerId] = shooterData;
      playerData[opponentId] = opponentData;

      Map<String, dynamic> updates = {'playerData': playerData};

      if ((opponentData['shipsSunk'] ?? 0) >=
          GameData.batailleNavaleShips.length) {
        int winXp = 40;
        int myLostShips = (shooterData['shipsSunk'] as int? ?? 0);
        if (myLostShips <= 1) {
          winXp += 50; // Victoire Parfaite
        }
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          winXp,
          applySpeedBonus: false,
        );
        updates.addAll({
          'gameState': 'gameOver',
          'roundState': 'gameOver',
          'gameWinner': playerId,
          'players.$playerId.score': FieldValue.increment(1),
          'gameEndReason': _l10n.aCouleTouteLaFlotte1(shooterData['name']),
        });
      } else {
        // Si touché ou coulé, le joueur rejoue, sinon au tour de l'adversaire
        String nextPlayerId =
            (result == 'hit' || result == 'sunk') ? playerId : opponentId;
        String logMessage =
            (result == 'hit' || result == 'sunk')
                ? _l10n.aToucheUneCibleIl(shooterData['name'])
                : _l10n.aTireDansLEau(
                  shooterData['name'],
                  opponentData['name'],
                );

        updates.addAll({
          'currentPlayerId': nextPlayerId,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([logMessage]),
        });
      }
      transaction.update(gameRef, updates);
    });
  }

  Future<void> handleBatailleNavaleTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      var gameData = snap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      if (gameData['roundState'] == 'placement') {
        var playerData = Map<String, dynamic>.from(
          gameData['playerData'] ?? {},
        );
        Random rand = Random();

        playerData.forEach((pId, pInfo) {
          var pMap = Map<String, dynamic>.from(pInfo);
          if (pMap['isReady'] != true) {
            List<int> grid = List.filled(100, 0);
            Map<String, dynamic> shipsPlaced = {};

            for (var entry in GameData.batailleNavaleShips.entries) {
              String shipType = entry.key;
              int shipId =
                  GameData.batailleNavaleShips.keys.toList().indexOf(shipType) +
                  1;
              int length = entry.value['length'];
              int width = entry.value['width'];
              int area = entry.value['area'];
              bool placed = false;

              while (!placed) {
                bool isHorizontal = rand.nextBool();
                int startRow = rand.nextInt(10);
                int startCol = rand.nextInt(10);
                int actualCols = isHorizontal ? length : width;
                int actualRows = isHorizontal ? width : length;

                if (startRow + actualRows > 10 || startCol + actualCols > 10)
                  continue;

                bool valid = true;
                List<int> indices = [];
                for (int r = 0; r < actualRows; r++) {
                  for (int c = 0; c < actualCols; c++) {
                    int idx = (startRow + r) * 10 + (startCol + c);
                    if (grid[idx] != 0) {
                      valid = false;
                      break;
                    }
                    indices.add(idx);
                  }
                  if (!valid) break;
                }

                if (valid) {
                  for (int idx in indices) grid[idx] = shipId;
                  shipsPlaced[shipType] = {
                    'id': shipId,
                    'area': area,
                    'startIndex': startRow * 10 + startCol,
                    'isHorizontal': isHorizontal,
                    'hits': 0,
                    'sunk': false,
                  };
                  placed = true;
                }
              }
            }
            pMap['myGrid'] = grid;
            pMap['shipsPlaced'] = shipsPlaced;
            pMap['isReady'] = true;
            playerData[pId] = pMap;
          }
        });

        List<String> playerIds = playerData.keys.toList();
        String firstPlayer = playerIds[rand.nextInt(playerIds.length)];

        transaction.update(gameRef, {
          'playerData': playerData,
          'roundState': 'playing',
          'currentPlayerId': firstPlayer,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.placementAutomatiqueEffectue,
          ]),
        });
      } else if (gameData['roundState'] == 'playing') {
        final currentPlayerId = gameData['currentPlayerId'];
        if (currentPlayerId == null) return;

        var playerData = Map<String, dynamic>.from(
          gameData['playerData'] ?? {},
        );
        List<String> playerIds = playerData.keys.toList();
        String opponentId = playerIds.firstWhere(
          (id) => id != currentPlayerId,
          orElse: () => '',
        );
        if (opponentId.isEmpty) return;

        var shooterData = Map<String, dynamic>.from(
          playerData[currentPlayerId] ?? {},
        );
        var enemyGrid = List<String>.from(
          shooterData['enemyGrid'] ?? List.filled(100, 'unknown'),
        );

        List<int> validTargets = [];
        for (int i = 0; i < 100; i++) {
          if (enemyGrid[i] == 'unknown') validTargets.add(i);
        }

        if (validTargets.isEmpty) return;

        // Intelligence de tir "Hunt & Target" : cibler autour des cases 'hit' non coulées
        List<int> hitCells = [];
        for (int i = 0; i < 100; i++) {
          if (enemyGrid[i] == 'hit') hitCells.add(i);
        }

        List<int> priorityTargets = [];
        if (hitCells.isNotEmpty) {
          // 1. Si deux 'hit' sont alignés, privilégier le prolongement de la ligne
          for (int h in hitCells) {
            int r = h ~/ 10;
            int c = h % 10;
            if (c + 1 < 10 && enemyGrid[r * 10 + (c + 1)] == 'hit') {
              if (c - 1 >= 0 && enemyGrid[r * 10 + (c - 1)] == 'unknown') {
                priorityTargets.add(r * 10 + (c - 1));
              }
              if (c + 2 < 10 && enemyGrid[r * 10 + (c + 2)] == 'unknown') {
                priorityTargets.add(r * 10 + (c + 2));
              }
            }
            if (r + 1 < 10 && enemyGrid[(r + 1) * 10 + c] == 'hit') {
              if (r - 1 >= 0 && enemyGrid[(r - 1) * 10 + c] == 'unknown') {
                priorityTargets.add((r - 1) * 10 + c);
              }
              if (r + 2 < 10 && enemyGrid[(r + 2) * 10 + c] == 'unknown') {
                priorityTargets.add((r + 2) * 10 + c);
              }
            }
          }
          // 2. Sinon, toutes les cases adjacentes (N, S, E, O) aux 'hit'
          if (priorityTargets.isEmpty) {
            for (int h in hitCells) {
              int r = h ~/ 10;
              int c = h % 10;
              if (r > 0 && enemyGrid[(r - 1) * 10 + c] == 'unknown') {
                priorityTargets.add((r - 1) * 10 + c);
              }
              if (r < 9 && enemyGrid[(r + 1) * 10 + c] == 'unknown') {
                priorityTargets.add((r + 1) * 10 + c);
              }
              if (c > 0 && enemyGrid[r * 10 + (c - 1)] == 'unknown') {
                priorityTargets.add(r * 10 + (c - 1));
              }
              if (c < 9 && enemyGrid[r * 10 + (c + 1)] == 'unknown') {
                priorityTargets.add(r * 10 + (c + 1));
              }
            }
          }
        }

        int targetIndex;
        if (priorityTargets.isNotEmpty) {
          targetIndex =
              priorityTargets[Random().nextInt(priorityTargets.length)];
        } else {
          // Mode recherche en damier (plus efficace pour trouver les bateaux >= 2 cases)
          final checkerboard =
              validTargets
                  .where((idx) => ((idx ~/ 10) + (idx % 10)) % 2 == 0)
                  .toList();
          final pool = checkerboard.isNotEmpty ? checkerboard : validTargets;
          targetIndex = pool[Random().nextInt(pool.length)];
        }

        var opponentData = Map<String, dynamic>.from(
          playerData[opponentId] ?? {},
        );
        var opponentIncomingGrid = List<String>.from(
          opponentData['incomingGrid'] ?? List.filled(100, 'unknown'),
        );
        var opponentGrid = List<int>.from(
          opponentData['myGrid'] ?? List.filled(100, 0),
        );
        var opponentShips = Map<String, dynamic>.from(
          opponentData['shipsPlaced'] ?? {},
        );

        String result = 'miss';
        if (opponentGrid[targetIndex] != 0) {
          result = 'hit';
          int shipId = opponentGrid[targetIndex];

          for (var entry in opponentShips.entries) {
            var ship = Map<String, dynamic>.from(entry.value);
            if (ship['id'] == shipId) {
              ship['hits'] = (ship['hits'] as int) + 1;
              if (ship['hits'] >= ship['area']) {
                ship['sunk'] = true;
                result = 'sunk';
                for (int i = 0; i < 100; i++) {
                  if (opponentGrid[i] == shipId) {
                    enemyGrid[i] = 'sunk';
                    opponentIncomingGrid[i] = 'sunk';
                  }
                }
              }
              opponentShips[entry.key] = ship;
              break;
            }
          }
          if (result == 'sunk') {
            opponentData['shipsSunk'] =
                (opponentData['shipsSunk'] as int? ?? 0) + 1;
          }
        }

        enemyGrid[targetIndex] = result;
        opponentIncomingGrid[targetIndex] = result;

        shooterData['enemyGrid'] = enemyGrid;
        opponentData['incomingGrid'] = opponentIncomingGrid;
        opponentData['shipsPlaced'] = opponentShips;
        playerData[currentPlayerId] = shooterData;
        playerData[opponentId] = opponentData;

        Map<String, dynamic> updates = {'playerData': playerData};

        if ((opponentData['shipsSunk'] ?? 0) >=
            GameData.batailleNavaleShips.length) {
          updates.addAll({
            'gameState': 'gameOver',
            'roundState': 'gameOver',
            'gameWinner': currentPlayerId,
            'players.$currentPlayerId.score': FieldValue.increment(1),
            'gameEndReason': _l10n.aCouleTouteLaFlotte1(shooterData['name']),
          });
        } else {
          String nextPlayerId =
              (result == 'hit' || result == 'sunk')
                  ? currentPlayerId
                  : opponentId;
          updates.addAll({
            'currentPlayerId': nextPlayerId,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              _l10n.aTireAutomatiquementEn(
                shooterData['name'],
                (targetIndex ~/ 10) + 1,
                (targetIndex % 10) + 1,
                result,
              ),
            ]),
          });
        }

        transaction.update(gameRef, updates);
      }
    });
  }

  // =========================================================================
  // 3. PRÉSIDENT
  // =========================================================================
  Future<void> handlePresidentTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;

      // Protection anti-doublon : s'assurer que le tour a réellement expiré
      if (!_isTurnTimedOut(gameData)) return;

      final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
      final currentIndex =
          (gameData['currentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (playerOrder.isEmpty || currentIndex >= playerOrder.length) return;

      final playerId = playerOrder[currentIndex];
      final playerName =
          gameData['players']?[playerId]?['name'] ?? _l10n.joueur;
      final hands = Map<String, dynamic>.from(gameData['playerHands'] ?? {});
      final myHand = List<String>.from(hands[playerId] ?? []);
      final lastPlay =
          gameData['lastPlay'] != null
              ? Map<String, dynamic>.from(gameData['lastPlay'])
              : null;
      List<String> passedPlayers = List<String>.from(
        gameData['passedPlayers'] ?? [],
      );
      List<String> finishedPlayers = List<String>.from(
        gameData['finishedPlayers'] ?? [],
      );
      bool isRevolution = gameData['isRevolutionActive'] ?? false;

      // Sécurité : si le joueur n'a déjà plus de cartes, avancer au joueur actif suivant
      if (myHand.isEmpty) {
        if (!finishedPlayers.contains(playerId)) {
          finishedPlayers.add(playerId);
        }
        final remaining =
            playerOrder.where((p) => !finishedPlayers.contains(p)).toList();
        if (remaining.length <= 1) {
          _endPresidentRound(transaction, gameRef, gameData, {
            'playerHands': hands,
            'finishedPlayers': finishedPlayers,
          });
          return;
        }
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        int loopGuard0 = 0;
        while ((finishedPlayers.contains(playerOrder[nextIndex]) ||
                passedPlayers.contains(playerOrder[nextIndex])) &&
            loopGuard0 < playerOrder.length) {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          loopGuard0++;
        }
        transaction.update(gameRef, {
          'finishedPlayers': finishedPlayers,
          'currentPlayerIndex': nextIndex,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        return;
      }

      // CAS A : Table vide (le joueur ouvre le pli avec toutes les cartes de sa plus petite valeur)
      if (lastPlay == null && myHand.isNotEmpty) {
        Map<String, List<String>> rankGroups = {};
        for (String c in myHand) {
          String rank = _getPresidentCardRank(c);
          rankGroups.putIfAbsent(rank, () => []).add(c);
        }
        var sortedEntries =
            rankGroups.entries.toList()..sort(
              (a, b) => _getPresidentCardValue(
                a.value.first,
                isRevolution,
              ).compareTo(_getPresidentCardValue(b.value.first, isRevolution)),
            );
        List<String> cardsToPlay;
        if (!isRevolution && myHand.contains('3C')) {
          cardsToPlay = List<String>.from(rankGroups['3'] ?? ['3C']);
        } else {
          cardsToPlay = List<String>.from(sortedEntries.first.value);
        }
        for (final c in cardsToPlay) {
          myHand.remove(c);
        }
        hands[playerId] = myHand;

        if (myHand.isEmpty && !finishedPlayers.contains(playerId)) {
          finishedPlayers.add(playerId);
        }

        final remaining =
            playerOrder.where((p) => !finishedPlayers.contains(p)).toList();
        if (remaining.length <= 1) {
          _endPresidentRound(transaction, gameRef, gameData, {
            'playerHands': hands,
            'finishedPlayers': finishedPlayers,
          });
          return;
        }

        int nextIndex = (currentIndex + 1) % playerOrder.length;
        int loopGuard1 = 0;
        while (finishedPlayers.contains(playerOrder[nextIndex]) &&
            loopGuard1 < playerOrder.length) {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          loopGuard1++;
        }

        transaction.update(gameRef, {
          'playerHands': hands,
          'lastPlay': {
            'cards': cardsToPlay,
            'value': _getPresidentCardValue(cardsToPlay.first, isRevolution),
            'playedBy': playerId,
          },
          'currentPile': FieldValue.arrayUnion(cardsToPlay),
          'lastPlayerToPlay': playerId,
          'currentPlayerIndex': nextIndex,
          'passedPlayers': [],
          'finishedPlayers': finishedPlayers,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aOuvertAvec(playerName, cardsToPlay.join(', ')),
          ]),
        });
      }
      // CAS B : Pli en cours (tente de jouer une carte supérieure, sinon passe)
      else if (lastPlay != null) {
        int targetSize = (lastPlay['cards'] as List).length;
        int lastVal = (lastPlay['value'] as num?)?.toInt() ?? 0;

        // Regrouper la main par rang et trier par valeur croissante
        Map<String, List<String>> rankGroups = {};
        for (String c in myHand) {
          String rank = _getPresidentCardRank(c);
          rankGroups.putIfAbsent(rank, () => []).add(c);
        }

        var sortedEntries =
            rankGroups.entries.toList()..sort(
              (a, b) => _getPresidentCardValue(
                a.value.first,
                isRevolution,
              ).compareTo(_getPresidentCardValue(b.value.first, isRevolution)),
            );

        List<String>? candidateCards;
        for (var entry in sortedEntries) {
          if (entry.value.length >= targetSize) {
            int val = _getPresidentCardValue(entry.value.first, isRevolution);
            if (val > lastVal) {
              candidateCards = entry.value.take(targetSize).toList();
              break;
            }
          }
        }

        // Si le joueur a une combinaison valide, il la pose
        if (candidateCards != null) {
          for (var c in candidateCards) {
            myHand.remove(c);
          }
          hands[playerId] = myHand;

          if (myHand.isEmpty && !finishedPlayers.contains(playerId)) {
            finishedPlayers.add(playerId);
          }

          final remaining =
              playerOrder.where((p) => !finishedPlayers.contains(p)).toList();
          if (remaining.length <= 1) {
            _endPresidentRound(transaction, gameRef, gameData, {
              'playerHands': hands,
              'finishedPlayers': finishedPlayers,
            });
            return;
          }

          int nextIndex = (currentIndex + 1) % playerOrder.length;
          int loopGuard2 = 0;
          while ((finishedPlayers.contains(playerOrder[nextIndex]) ||
                  passedPlayers.contains(playerOrder[nextIndex])) &&
              loopGuard2 < playerOrder.length) {
            nextIndex = (nextIndex + 1) % playerOrder.length;
            loopGuard2++;
          }

          transaction.update(gameRef, {
            'playerHands': hands,
            'lastPlay': {
              'cards': candidateCards,
              'value': _getPresidentCardValue(
                candidateCards.first,
                isRevolution,
              ),
              'playedBy': playerId,
            },
            'currentPile': FieldValue.arrayUnion(candidateCards),
            'lastPlayerToPlay': playerId,
            'currentPlayerIndex': nextIndex,
            'finishedPlayers': finishedPlayers,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              _l10n.aJoue4(playerName, candidateCards.join(', ')),
            ]),
          });
          return;
        }

        // Sinon, le joueur passe son tour proprement
        if (!passedPlayers.contains(playerId)) passedPlayers.add(playerId);

        final stillInPlay =
            playerOrder
                .where(
                  (p) =>
                      !finishedPlayers.contains(p) &&
                      !passedPlayers.contains(p),
                )
                .toList();
        final bool trickEnded = stillInPlay.isEmpty || stillInPlay.length == 1;

        if (trickEnded) {
          String lastWinner = gameData['lastPlayerToPlay'] ?? playerId;
          int nextIndex = playerOrder.indexOf(lastWinner);
          if (nextIndex == -1) nextIndex = 0;
          int loopGuard3 = 0;
          while (finishedPlayers.contains(playerOrder[nextIndex]) &&
              loopGuard3 < playerOrder.length) {
            nextIndex = (nextIndex + 1) % playerOrder.length;
            loopGuard3++;
          }

          transaction.update(gameRef, {
            'passedPlayers': [],
            'lastPlay': null,
            'currentPile': [],
            'currentPlayerIndex': nextIndex,
            'lastPlayerToPlay': playerOrder[nextIndex],
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              _l10n.pliTermineAuTourDe3(
                gameData['players']?[playerOrder[nextIndex]]?['name'],
              ),
            ]),
          });
        } else {
          int nextIndex = (currentIndex + 1) % playerOrder.length;
          int loopGuard4 = 0;
          while ((finishedPlayers.contains(playerOrder[nextIndex]) ||
                  passedPlayers.contains(playerOrder[nextIndex])) &&
              loopGuard4 < playerOrder.length) {
            nextIndex = (nextIndex + 1) % playerOrder.length;
            loopGuard4++;
          }

          transaction.update(gameRef, {
            'passedPlayers': passedPlayers,
            'currentPlayerIndex': nextIndex,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([_l10n.passeSonTour2(playerName)]),
          });
        }
      }
    });
  }

  // =========================================================================
  // 11. BLOKUS
  // =========================================================================
  Future<void> handleBlokusTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final playerOrder = List<String>.from(gameData['blokusPlayerOrder'] ?? []);
    final currentIndex = gameData['blokusCurrentPlayerIndex'] ?? 0;
    if (currentIndex >= playerOrder.length) return;

    final playerId = playerOrder[currentIndex];
    final myHand = List<int>.from(
      gameData['blokusPlayerHands']?[playerId] ?? [],
    );
    final myColor = gameData['blokusPlayerColors']?[playerId] ?? 'blue';
    final board = Map<String, String>.from(gameData['blokusBoard'] ?? {});
    final isFirst = !(gameData['blokusFirstPiecePlaced']?[playerId] ?? false);

    bool placed = false;
    // Prioriser les grandes pièces (5 carrés d'abord) pour maximiser les points
    List<int> candidatePieces =
        List.from(myHand)
          ..shuffle()
          ..sort(
            (a, b) => (GameData.blokusPieces[b]?.length ?? 0).compareTo(
              GameData.blokusPieces[a]?.length ?? 0,
            ),
          );

    for (int pieceId in candidatePieces) {
      for (int rot = 0; rot < 4; rot++) {
        for (bool flip in [false, true]) {
          final shape = GameData.getRotatedPiece(pieceId, rot, flipped: flip);
          for (int r = 0; r < 20; r++) {
            for (int c = 0; c < 20; c++) {
              final coords = shape.map((p) => [p[0] + r, p[1] + c]).toList();

              bool inBounds = coords.every(
                (p) => p[0] >= 0 && p[0] < 20 && p[1] >= 0 && p[1] < 20,
              );
              if (!inBounds) continue;
              if (coords.any((p) => board.containsKey("${p[0]}_${p[1]}")))
                continue;

              bool touchesEdge = coords.any((p) {
                final neighbors = [
                  [p[0] - 1, p[1]],
                  [p[0] + 1, p[1]],
                  [p[0], p[1] - 1],
                  [p[0], p[1] + 1],
                ];
                return neighbors.any(
                  (n) => board["${n[0]}_${n[1]}"] == myColor,
                );
              });
              if (touchesEdge) continue;

              bool touchesCorner = coords.any((p) {
                final diags = [
                  [p[0] - 1, p[1] - 1],
                  [p[0] - 1, p[1] + 1],
                  [p[0] + 1, p[1] - 1],
                  [p[0] + 1, p[1] + 1],
                ];
                return diags.any((d) => board["${d[0]}_${d[1]}"] == myColor);
              });

              if (isFirst) {
                final List<String> validCorners = [
                  "0_0",
                  "19_19",
                  "0_19",
                  "19_0",
                ];
                String defaultCorner =
                    myColor == 'blue'
                        ? "0_0"
                        : myColor == 'red'
                        ? "19_19"
                        : myColor == 'green'
                        ? "0_19"
                        : "19_0";
                bool matchesCorner = coords.any((p) {
                  final key = "${p[0]}_${p[1]}";
                  return key == defaultCorner ||
                      (validCorners.contains(key) && !board.containsKey(key));
                });
                if (matchesCorner) {
                  await placeBlokusPiece(
                    gameCode,
                    playerId,
                    pieceId,
                    r,
                    c,
                    rot,
                    flipped: flip,
                    isAuto: true,
                  );
                  placed = true;
                  break;
                }
              } else if (touchesCorner) {
                await placeBlokusPiece(
                  gameCode,
                  playerId,
                  pieceId,
                  r,
                  c,
                  rot,
                  flipped: flip,
                  isAuto: true,
                );
                placed = true;
                break;
              }
            }
            if (placed) break;
          }
          if (placed) break;
        }
        if (placed) break;
      }
      if (placed) break;
    }

    if (!placed) {
      await passBlokusTurn(gameCode, playerId, isAuto: true);
    }
  }

  // =========================================================================
  // 10. JEU DE DAMES (CHECKERS)
  // =========================================================================
  Future<void> handleCheckersTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    List<String> playerOrder = List<String>.from(
      gameData['checkersPlayerOrder'],
    );
    int currentIndex = gameData['checkersCurrentPlayerIndex'];
    final playerId = playerOrder[currentIndex];
    final board = Map<String, String>.from(gameData['checkersBoard'] ?? {});
    final currentColor = gameData['checkersCurrentColor'] ?? 'red';

    bool hasCapture = _isAnyCaptureAvailable(board, currentColor);
    final String? mandatoryPiece = gameData['checkersMandatoryPiece'];
    List<Map<String, int>> legalMoves = [];

    for (var entry in board.entries) {
      if (mandatoryPiece != null && entry.key != mandatoryPiece) continue;
      if (entry.value.startsWith(currentColor)) {
        final pos = entry.key.split(',').map(int.parse).toList();
        final r = pos[0];
        final c = pos[1];
        final isKing = entry.value.endsWith('_king');

        final dirs =
            isKing
                ? [
                  [-1, -1],
                  [-1, 1],
                  [1, -1],
                  [1, 1],
                ]
                : (currentColor == 'red'
                    ? [
                      [-1, -1],
                      [-1, 1],
                    ]
                    : [
                      [1, -1],
                      [1, 1],
                    ]);

        if (hasCapture) {
          if (_canPieceCapture(board, r, c, currentColor, isKing)) {
            String opp = currentColor == 'red' ? 'black' : 'red';
            for (var d in [
              [-1, -1],
              [-1, 1],
              [1, -1],
              [1, 1],
            ]) {
              if (isKing) {
                bool foundOpponent = false;
                for (int step = 1; step < 8; step++) {
                  int nr = r + d[0] * step;
                  int nc = c + d[1] * step;
                  if (nr < 0 || nr > 7 || nc < 0 || nc > 7) break;
                  String? p = board["$nr,$nc"];
                  if (p != null) {
                    if (p.startsWith(currentColor)) break;
                    if (p.startsWith(opp)) {
                      if (foundOpponent) break;
                      foundOpponent = true;
                    }
                  } else {
                    if (foundOpponent) {
                      legalMoves.add({
                        'fromR': r,
                        'fromC': c,
                        'toR': nr,
                        'toC': nc,
                      });
                    }
                  }
                }
              } else {
                int toR = r + d[0] * 2;
                int toC = c + d[1] * 2;
                if (toR >= 0 &&
                    toR < 8 &&
                    toC >= 0 &&
                    toC < 8 &&
                    !board.containsKey("$toR,$toC")) {
                  int midR = r + d[0];
                  int midC = c + d[1];
                  if (board["$midR,$midC"]?.startsWith(opp) == true) {
                    legalMoves.add({
                      'fromR': r,
                      'fromC': c,
                      'toR': toR,
                      'toC': toC,
                    });
                  }
                }
              }
            }
          }
        } else {
          for (var d in dirs) {
            if (isKing) {
              for (int step = 1; step < 8; step++) {
                int toR = r + d[0] * step;
                int toC = c + d[1] * step;
                if (toR >= 0 &&
                    toR < 8 &&
                    toC >= 0 &&
                    toC < 8 &&
                    !board.containsKey("$toR,$toC")) {
                  legalMoves.add({
                    'fromR': r,
                    'fromC': c,
                    'toR': toR,
                    'toC': toC,
                  });
                } else {
                  break;
                }
              }
            } else {
              int toR = r + d[0];
              int toC = c + d[1];
              if (toR >= 0 &&
                  toR < 8 &&
                  toC >= 0 &&
                  toC < 8 &&
                  !board.containsKey("$toR,$toC")) {
                legalMoves.add({
                  'fromR': r,
                  'fromC': c,
                  'toR': toR,
                  'toC': toC,
                });
              }
            }
          }
        }
      }
    }

    if (legalMoves.isNotEmpty) {
      // Prioriser les promotions en Dame et les avancées vers le centre
      legalMoves.shuffle();
      legalMoves.sort((a, b) {
        final bool aPromo =
            (currentColor == 'red' && a['toR'] == 0) ||
            (currentColor == 'black' && a['toR'] == 7);
        final bool bPromo =
            (currentColor == 'red' && b['toR'] == 0) ||
            (currentColor == 'black' && b['toR'] == 7);
        if (aPromo != bPromo) return bPromo ? 1 : -1;
        return 0;
      });
      final move = legalMoves.first;
      await checkersMove(
        gameCode,
        playerId,
        move['fromR']!,
        move['fromC']!,
        move['toR']!,
        move['toC']!,
        isAuto: true,
      );

      final nextSnap = await gameRef.get();
      if (nextSnap.exists) {
        final nextData = nextSnap.data() as Map<String, dynamic>;
        if (nextData['checkersMandatoryPiece'] != null &&
            nextData['gameState'] == 'playing') {
          await handleCheckersTimeout(gameCode);
        }
      }
    } else {
      if (mandatoryPiece == null) {
        // Aucun coup légal en début de tour -> blocage complet, victoire de l'adversaire !
        int oppIndex = (currentIndex + 1) % playerOrder.length;
        String winnerId = playerOrder[oppIndex];
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'players.$winnerId.score': FieldValue.increment(1),
          'gameEndReason': _l10n.aGagne2(
            players[winnerId]?['name'] ?? _l10n.joueur,
          ),
        });
      } else {
        String nextColor = currentColor == 'red' ? 'black' : 'red';
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        await gameRef.update({
          'checkersCurrentColor': nextColor,
          'checkersCurrentPlayerIndex': nextIndex,
          'checkersMandatoryPiece': null,
          'checkersTurnCaptures': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    }
  }

