  // =========================================================================
  // 24. TIME'S UP
  // =========================================================================
  Future<void> handleTimesUpTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    final gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    if (gameData['roundState'] == 'collecting_words') {
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final submitted = Map<String, dynamic>.from(
        gameData['timesUpSubmittedPlayers'] ?? {},
      );
      final existingWords = List<String>.from(gameData['timesUpWords'] ?? []);

      bool missingFound = false;
      for (var pId in players.keys) {
        if (!submitted.containsKey(pId)) {
          submitted[pId] = true;
          missingFound = true;
        }
      }

      if (missingFound || submitted.length >= players.length) {
        if (existingWords.isEmpty) {
          final fallback =
              (GameWords.pictionaryWords.values.expand((list) => list).toList()
                    ..shuffle())
                  .take(10)
                  .toList();
          existingWords.addAll(fallback);
        }

        final allDeck = List<String>.from(existingWords)..shuffle();
        final playerIds = players.keys.toList()..shuffle();
        final half = (playerIds.length / 2).ceil();
        final existingTeams = Map<String, dynamic>.from(
          gameData['teams'] ?? {},
        );
        final List<String> teamA =
            existingTeams['teamA'] != null &&
                    (existingTeams['teamA'] as List).isNotEmpty
                ? List<String>.from(existingTeams['teamA'])
                : playerIds.sublist(0, half);
        final List<String> teamB =
            existingTeams['teamB'] != null &&
                    (existingTeams['teamB'] as List).isNotEmpty
                ? List<String>.from(existingTeams['teamB'])
                : playerIds.sublist(half);

        await gameRef.update({
          'timesUpWords': existingWords,
          'timesUpSubmittedPlayers': submitted,
          'timesUpCurrentDeck': allDeck,
          'timesUpDiscarded': [],
          'teams': {'teamA': teamA, 'teamB': teamB},
          'teamScores': {'teamA': 0, 'teamB': 0},
          'roundState': 'playing_round_1',
          'currentRoundNumber': 1,
          'currentGuesserId':
              teamA.isNotEmpty
                  ? teamA[0]
                  : (playerIds.isNotEmpty ? playerIds[0] : ''),
          'currentRoundTime': 30,
          'timesUpTeamATurnIndex': teamA.length > 1 ? 1 : 0,
          'timesUpTeamBTurnIndex': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([_l10n.tempsEcoulePourLaSaisie]),
        });
      }
    } else if (gameData['roundState'].toString().startsWith('playing_round_') ||
        gameData['roundState'] == 'waiting_for_turn') {
      await startTimesUpRoundTurn(gameCode);
    }
  }

  // =========================================================================
  // 22. GRIBOUILLIS
  // =========================================================================
  Future<void> handleGribouillisTimeout(String gameCode) async {
    final gameSnap = await _db.collection('games').doc(gameCode).get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final players = Map<String, dynamic>.from(gameData['players']);
    final submitted = List<String>.from(gameData['submittedPlayers'] ?? []);
    final roundState = gameData['roundState'];

    if (roundState == 'results' || gameData['gameState'] == 'gameOver') return;

    final List<String> aiWords = List<String>.from(gameData['aiWords'] ?? []);
    final List<String> fallbackPool =
        aiWords.isNotEmpty
            ? aiWords
            : List<String>.from(
              GameWords.pictionaryWords['Facile'] ?? ['Soleil', 'Maison'],
            );

    for (var pId in players.keys) {
      if (!submitted.contains(pId)) {
        if (roundState == 'initial_writing' || roundState == 'guessing') {
          final String fallbackWord =
              fallbackPool.isNotEmpty
                  ? fallbackPool[Random().nextInt(fallbackPool.length)]
                  : "...";
          await submitGribouillisStep(
            gameCode,
            pId,
            'text',
            fallbackWord,
            isAuto: true,
          );
        } else {
          await submitGribouillisStep(
            gameCode,
            pId,
            'drawing',
            "",
            isAuto: true,
          );
        }
      }
    }
  }

  // =========================================================================
  // 21. CADAVRE EXQUIS
  // =========================================================================
  Future<void> handleCadavreExquisTimeout(String gameCode) async {
    final gameSnap = await _db.collection('games').doc(gameCode).get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    final currentIndex = (gameData['currentPlayerIndex'] as num?)?.toInt() ?? 0;
    if (currentIndex < playerOrder.length) {
      final playerId = playerOrder[currentIndex];
      // Injecter un mot par défaut pour faire progresser les étapes de la feuille jusqu'à la fin de partie
      await submitCadavreExquisStep(gameCode, playerId, "...", isAuto: true);
    }
  }

  // =========================================================================
  // 8. PETITS CHEVAUX (LUDO)
  // =========================================================================
  Future<void> handlePetitsChevauxTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    var gameData = snap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final playerOrder = List<String>.from(gameData['petitsChevauxPlayerOrder']);
    final currentIndex = gameData['petitsChevauxCurrentIndex'];
    if (currentIndex >= playerOrder.length) return;
    String currentPlayerId = playerOrder[currentIndex];

    if (gameData['petitsChevauxHasRolled'] != true) {
      await rollDicePetitsChevaux(gameCode, currentPlayerId, isAuto: true);
      final nextSnap = await gameRef.get();
      if (!nextSnap.exists) return;
      gameData = nextSnap.data() as Map<String, dynamic>;
      if (gameData['petitsChevauxCurrentIndex'] != currentIndex) {
        return; // Le tour a été passé automatiquement car aucun coup possible
      }
    }

    if (gameData['petitsChevauxHasRolled'] == true) {
      final allPositions = Map<String, dynamic>.from(
        gameData['petitsChevauxPositions'] ?? {},
      );
      String targetOwnerId = currentPlayerId;
      List<int> positions = List<int>.from(
        allPositions[currentPlayerId] ?? [-1, -1, -1, -1],
      );
      final bool is2v2 = gameData['petitsChevauxIs2v2'] == true;
      if (is2v2 &&
          playerOrder.length == 4 &&
          positions.every((pos) => pos == 56)) {
        final String allyId = playerOrder[(currentIndex + 2) % 4];
        targetOwnerId = allyId;
        positions = List<int>.from(allPositions[allyId] ?? [-1, -1, -1, -1]);
      }

      final dice = (gameData['petitsChevauxDice'] as num?)?.toInt() ?? 0;
      List<int> candidatePawns = [];

      if ((dice == 1 || dice == 6) && !positions.contains(0)) {
        for (int i = 0; i < 4; i++) {
          if (positions[i] == -1) {
            candidatePawns.add(i);
          }
        }
      }
      List<int> trackPawns = [];
      for (int i = 0; i < 4; i++) {
        int pos = positions[i];
        if (pos >= 0 && pos + dice <= 56) {
          trackPawns.add(i);
        }
      }
      // Trier les pions en course du plus avancé au moins avancé
      trackPawns.sort((a, b) => positions[b].compareTo(positions[a]));
      candidatePawns.addAll(trackPawns);

      bool moved = false;
      for (int pawnIdx in candidatePawns) {
        try {
          await movePawnPetitsChevaux(
            gameCode,
            currentPlayerId,
            targetOwnerId,
            pawnIdx,
            isAuto: true,
          );
          moved = true;
          break;
        } catch (_) {}
      }

      if (!moved) {
        await passTurnPetitsChevaux(gameCode, currentPlayerId, isAuto: true);
      }
    }
  }

  Future<void> updatePlayerHeartbeat(String gameCode, String playerId) async {
    final now = FieldValue.serverTimestamp();
    await _db
        .collection('games')
        .doc(gameCode)
        .collection('presences')
        .doc(playerId)
        .set({'lastHeartbeat': now}, SetOptions(merge: true));

    await _db
        .collection('games')
        .doc(gameCode)
        .update({
          'players.$playerId.lastHeartbeat': now,
          'players.$playerId.isOnline': true,
        })
        .catchError((_) {});
  }

  Future<void> removePlayerFromGame(
    String gameCode,
    String playerIdToRemove,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) return;

    for (int attempt = 0; attempt < 5; attempt++) {
      try {
        await _db.runTransaction((transaction) async {
          final gameRef = _db.collection('games').doc(gameCode);
          DocumentSnapshot gameSnap = await transaction.get(gameRef);
          if (!gameSnap.exists) return;

          var gameData = gameSnap.data() as Map<String, dynamic>;
          String hostId = gameData['hostId'] ?? '';
          var players = Map<String, dynamic>.from(gameData['players'] ?? {});
          var playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
          var teams = Map<String, dynamic>.from(gameData['teams'] ?? {});

          if (!players.containsKey(playerIdToRemove)) return;

          final callerAuthUid = currentAuthUid;
          final targetAuthUid =
              players[playerIdToRemove]?['authUid'] ?? playerIdToRemove;
          final hostAuthUid = players[hostId]?['authUid'] ?? hostId;

          // Sécurité : Seul l'hôte ou le joueur lui-même peut déclencher le départ
          if (callerAuthUid != targetAuthUid && callerAuthUid != hostAuthUid) {
            return;
          }

          String removedPlayerName =
              players[playerIdToRemove]?['name'] ?? _l10n.unJoueur;
          players.remove(playerIdToRemove);
          playerOrder.remove(playerIdToRemove);
          teams.forEach((key, playerList) {
            (playerList as List).remove(playerIdToRemove);
          });

          List<String> newLogs = [_l10n.aQuitteLaPartie(removedPlayerName)];
          Map<String, dynamic> updates = {
            'players': players,
            'playerOrder': playerOrder,
            'teams': teams,
            'inactiveTurnCounts.$playerIdToRemove': FieldValue.delete(),
            'pendingBotReplacement': FieldValue.delete(),
          };

          // Cas 1 : Moins de 2 joueurs dans une partie en cours -> Victoire du joueur restant par forfait
          if (players.length < 2 && gameData['gameState'] == 'playing') {
            final String? remainingPlayerId =
                players.keys.isNotEmpty ? players.keys.first : null;
            final String remainingName =
                remainingPlayerId != null
                    ? (players[remainingPlayerId]?['name'] ?? _l10n.joueur)
                    : _l10n.inconnu;

            updates['gameState'] = 'gameOver';
            updates['gameWinner'] = remainingPlayerId;
            updates['gameEndReason'] = _l10n.sEstDeconnecteVictoireDe(
              removedPlayerName,
              remainingName,
            );
            if (remainingPlayerId != null) {
              updates['players.$remainingPlayerId.score'] =
                  FieldValue.increment(1);
            }
          } else {
            // Cas 2 : Transmission du rôle d'hôte
            if (gameData['hostId'] == playerIdToRemove &&
                playerOrder.isNotEmpty) {
              updates['hostId'] = playerOrder[0];
              newLogs.add(
                _l10n.estLeNouvelHote1(players[playerOrder[0]]?['name']),
              );
            }

            // Cas 3 : Décalage propre du tour pour tous les jeux
            int currentPlayerIndex =
                (gameData['currentPlayerIndex'] as num?)?.toInt() ?? 0;
            if (playerOrder.isNotEmpty) {
              if (currentPlayerIndex >= playerOrder.length) {
                updates['currentPlayerIndex'] = 0;
              }
              updates['currentPlayerId'] =
                  playerOrder[updates['currentPlayerIndex'] ??
                      currentPlayerIndex];
            }

            // Nettoyage des listes d'ordres spécifiques aux sous-jeux
            final Map<String, String> orderIndexPairs = {
              'unoPlayerOrder': 'unoCurrentPlayerIndex',
              'bigTwoPlayerOrder': 'bigTwoCurrentPlayerIndex',
              'milleBornesPlayerOrder': 'milleBornesCurrentPlayerIndex',
              'petitsChevauxPlayerOrder': 'petitsChevauxCurrentIndex',
              'checkersPlayerOrder': 'checkersCurrentPlayerIndex',
              'blokusPlayerOrder': 'blokusCurrentPlayerIndex',
              'dominoesPlayerOrder': 'dominoesCurrentPlayerIndex',
              'zombiePlayerOrder': 'zombieCurrentPlayerIndex',
              'belotePlayerOrder': 'beloteCurrentPlayerIndex',
              'yamsPlayerOrder': 'yamsCurrentPlayerIndex',
            };
            orderIndexPairs.forEach((orderKey, indexKey) {
              if (gameData[orderKey] != null) {
                List<String> subOrder = List<String>.from(gameData[orderKey]);
                subOrder.remove(playerIdToRemove);
                updates[orderKey] = subOrder;
                if (subOrder.isNotEmpty && gameData[indexKey] != null) {
                  int subIdx = (gameData[indexKey] as num?)?.toInt() ?? 0;
                  updates[indexKey] = subIdx % subOrder.length;
                }
              }
            });
            if (gameData['skullCurrentPlayerIndex'] != null &&
                playerOrder.isNotEmpty) {
              int skullIdx =
                  (gameData['skullCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
              updates['skullCurrentPlayerIndex'] =
                  skullIdx % playerOrder.length;
            }
          }

          updates['gameLog'] = FieldValue.arrayUnion(newLogs);
          transaction.update(gameRef, updates);
        });
        break;
      } catch (e) {
        if (attempt == 4) rethrow;
        await Future.delayed(Duration(milliseconds: 50 * (attempt + 1)));
      }
    }
  }

  Future<bool> _incrementInactiveCountAndCheckExpulsion(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String timedOutPlayerId,
  ) async {
    final gameType = gameData['gameType'] ?? '';
    const realTimeGames = ['Dobble', 'La Patate Chaude'];
    if (realTimeGames.contains(gameType)) {
      return false; // Pas d'expulsion d'inactivité individuelle sur les jeux d'observation en temps réel
    }
    var inactiveCounts = Map<String, int>.from(
      gameData['inactiveTurnCounts'] ?? {},
    );
    int newInactiveCount = (inactiveCounts[timedOutPlayerId] ?? 0) + 1;
    transaction.update(gameRef, {
      'inactiveTurnCounts.$timedOutPlayerId': newInactiveCount,
    });

    // Seuil de 3 timers arrivés à 0
    if (newInactiveCount >= 3) {
      var players = Map<String, dynamic>.from(gameData['players'] ?? {});
      var playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
      String playerName = players[timedOutPlayerId]?['name'] ?? _l10n.unJoueur;
      final gameType = gameData['gameType'] ?? '';
      final isSocial = GameData.isSocialOpinionGame(gameType);

      // Notifier l'administrateur avec dialogue de décision
      Map<String, dynamic> updates = {
        'pendingBotReplacement': {
          'playerId': timedOutPlayerId,
          'playerName': playerName,
          'reason': _l10n.inactif3ToursSansReponse,
          'isSocial': isSocial,
          'timestamp': FieldValue.serverTimestamp(),
        },
        'gameLog': FieldValue.arrayUnion([_l10n.aManque3ToursSans(playerName)]),
      };

      // Passer au joueur suivant pour débloquer la partie pendant la décision
      if (playerOrder.isNotEmpty) {
        int oldIndex = playerOrder.indexOf(timedOutPlayerId);
        int currentIndex =
            (gameData['currentPlayerIndex'] as num?)?.toInt() ?? 0;
        if (oldIndex == currentIndex) {
          int nextIndex = (currentIndex + 1) % playerOrder.length;
          updates['currentPlayerIndex'] = nextIndex;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
      }

      transaction.update(gameRef, updates);
      return true;
    }
    return false;
  }

  /// Demande à l'administrateur s'il souhaite remplacer un joueur inactif/déconnecté par un bot
  Future<void> requestBotReplacement(
    String gameCode,
    String playerId,
    String playerName,
    String reason,
  ) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    final isSocial = GameData.isSocialOpinionGame(gameData['gameType'] ?? '');

    await gameRef.update({
      'pendingBotReplacement': {
        'playerId': playerId,
        'playerName': playerName,
        'reason': reason,
        'isSocial': isSocial,
        'timestamp': FieldValue.serverTimestamp(),
      },
      'gameLog': FieldValue.arrayUnion([
        _l10n.neRepondPlusLAdministrateur(playerName, reason),
      ]),
    });
  }

  /// Convertit un joueur en bot : l'ordinateur joue à sa place et le joueur réel est exclu sans gains
  Future<void> convertPlayerToBot(String gameCode, String playerId) async {
    final gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!players.containsKey(playerId)) return;
      final playerName = players[playerId]?['name'] ?? _l10n.joueur;

      Map<String, dynamic> updates = {
        'players.$playerId.isBot': true,
        'players.$playerId.replacedByBot': true,
        'botPlayers.$playerId': true,
        'pendingBotReplacement': FieldValue.delete(),
        'inactiveTurnCounts.$playerId': 0,
        'turnStartTime':
            FieldValue.serverTimestamp(), // Réinitialise à 5s maintenant
        'gameLog': FieldValue.arrayUnion([_l10n.aEteRemplaceParL(playerName)]),
      };

      transaction.update(gameRef, updates);
    });
  }

  Future<void> handleTurnTimeout(String gameCode) async {
    final preRef = _db.collection('games').doc(gameCode);
    final preSnap = await preRef.get();
    if (!preSnap.exists || preSnap.data() == null) return;
    final preData = preSnap.data() as Map<String, dynamic>;
    if (preData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(preData)) return;

    // Cas spéciaux Infiltré & Mr. White hors tour classique
    if (preData['gameType'] == 'Infiltré & Mr. White') {
      final String phase = preData['currentPhase'] ?? '';
      if (phase == 'mr_white_guess') {
        await preRef.update({
          'mrWhiteGuess': _l10n.tempsEcoule1,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        await processEliminationsAndCheckWin(gameCode);
        return;
      } else if (phase == 'tie_breaker') {
        final candidates = List<String>.from(
          preData['tieBreakerCandidates'] ?? [],
        );
        final String? chosen =
            candidates.isNotEmpty
                ? candidates[Random().nextInt(candidates.length)]
                : null;
        await preRef.update({
          'currentPhase': 'turn_result',
          'eliminatedThisTurn': chosen != null ? [chosen] : [],
          'votingTieCount': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        return;
      } else if (phase == 'avenger_revenge') {
        final pData = Map<String, dynamic>.from(preData['playerData'] ?? {});
        final eliminated = List<String>.from(
          preData['eliminatedThisTurn'] ?? [],
        );
        final activeTargets =
            pData.entries
                .where(
                  (e) =>
                      e.value['status'] == 'active' &&
                      !eliminated.contains(e.key),
                )
                .map((e) => e.key)
                .toList();
        if (activeTargets.isNotEmpty) {
          final victim = activeTargets[Random().nextInt(activeTargets.length)];
          eliminated.add(victim);
        }
        await preRef.update({
          'currentPhase': 'turn_result',
          'eliminatedThisTurn': eliminated,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        return;
      }
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
      final currentPlayerIndex = gameData['currentPlayerIndex'] ?? -1;
      if (playerOrder.isEmpty ||
          currentPlayerIndex == -1 ||
          currentPlayerIndex >= playerOrder.length)
        return;

      final timedOutPlayerId = playerOrder[currentPlayerIndex];
      final gameType = gameData['gameType'] ?? '';
      final bool isSocialGame = GameData.isSocialOpinionGame(gameType);

      // 1. Gestion de l'inactivité (Strike / Expulsion après 3 timers)
      final bool triggeredAdminAlert =
          await _incrementInactiveCountAndCheckExpulsion(
            transaction,
            gameRef,
            gameData,
            timedOutPlayerId,
          );
      if (triggeredAdminAlert &&
          !(gameType == 'Infiltré & Mr. White' &&
              gameData['currentPhase'] == 'clue_giving')) {
        return; // Alerte admin déclenchée
      }

      String playerName =
          gameData['players'][timedOutPlayerId]?['name'] ?? _l10n.joueur;

      // 2. Si c'est un jeu social / opinion / créatif : PAS DE COUP AUTOMATIQUE !
      if (isSocialGame) {
        // Cas particulier Infiltré & Mr. White : avancer de joueur sans indice bidon
        if (gameData['gameType'] == 'Infiltré & Mr. White' &&
            gameData['currentPhase'] == 'clue_giving') {
          var playerData = Map<String, dynamic>.from(
            gameData['playerData'] ?? {},
          );
          int findNextActivePlayer(int currentIndex) {
            int nextIndex = (currentIndex + 1) % playerOrder.length;
            int loopGuard = 0;
            while (playerData[playerOrder[nextIndex]]?['status'] != 'active' &&
                loopGuard < playerOrder.length) {
              nextIndex = (nextIndex + 1) % playerOrder.length;
              loopGuard++;
            }
            if (loopGuard >= playerOrder.length) return -1;
            return nextIndex;
          }

          int nextIndex = findNextActivePlayer(currentPlayerIndex);
          Map<String, dynamic> playerClues = Map<String, dynamic>.from(
            gameData['playerClues'] ?? {},
          );
          int activePlayerCount =
              playerData.values.where((p) => p['status'] == 'active').length;
          bool isLastPlayer =
              (nextIndex == -1 || nextIndex <= currentPlayerIndex);

          Map<String, dynamic> updates = {
            'turnLog': FieldValue.arrayUnion([_l10n.nAPasDonneD(playerName)]),
            'turnStartTime': FieldValue.serverTimestamp(),
          };

          if (isLastPlayer || playerClues.length >= activePlayerCount) {
            updates['currentPhase'] = 'voting';
            updates['votes'] = {};
            updates['turnLog'] = FieldValue.arrayUnion([_l10n.laPhaseDeVoteA]);
          } else {
            updates['currentPlayerIndex'] = nextIndex;
          }
          transaction.update(gameRef, updates);
          return;
        }

        // Pour tous les autres jeux d'opinion : tour passé sans coup auto
        int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
        transaction.update(gameRef, {
          'currentPlayerIndex': nextPlayerIndex,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([_l10n.nAPasReponduJeu(playerName)]),
        });
        return;
      }

      // 3. Logique par défaut pour les autres jeux (Passer au joueur suivant simplement)
      int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
      transaction.update(gameRef, {
        'currentPlayerIndex': nextPlayerIndex,
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([_l10n.nAPasJoueA3(playerName)]),
      });
    });
  }

  Future<void> handleVotingTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      // MODIFICATION : Vérification de roundState OU currentPhase (pour Infiltré)
      bool isVoting =
          gameData['roundState'] == 'voting' ||
          gameData['roundState'] == 'reveal_and_vote' ||
          gameData['currentPhase'] == 'voting';

      if (gameData['gameState'] != 'playing' || !isVoting) return;
      if (!_isTurnTimedOut(gameData)) return;

      final players = Map<String, dynamic>.from(gameData['players']);
      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      final gameType = gameData['gameType'];

      if (gameType == 'Le Juge') {
        // Pour Le Juge, seul le juge doit voter (sélectionner la réponse gagnante)
        final judgeId =
            gameData['currentTargetPlayerId'] ??
            gameData['judgeId'] ??
            gameData['currentPlayerId'];
        if (judgeId != null && !votes.containsKey(judgeId)) {
          await _incrementInactiveCountAndCheckExpulsion(
            transaction,
            gameRef,
            gameData,
            judgeId,
          );
        }
      } else {
        for (var pId in players.keys) {
          if (!votes.containsKey(pId)) {
            await _incrementInactiveCountAndCheckExpulsion(
              transaction,
              gameRef,
              gameData,
              pId,
            );
          }
        }
      }
    });

    // Après la transaction (si des joueurs ont été expulsés ou non), on force le calcul des votes
    final gameRef = _db.collection('games').doc(gameCode);
    var updatedGameData = (await gameRef.get()).data() as Map<String, dynamic>;

    if (updatedGameData['gameType'] == 'Le Juge' &&
        updatedGameData['roundState'] == 'voting') {
      // Le juge n'a pas voté à temps : on annule la manche sans donner de point au hasard
      await gameRef.update({
        'roundState': 'result',
        'roundWinnerId': null,
        'gameEndReason': _l10n.leJugeNAPas,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
      return;
    }

    if (updatedGameData['roundState'] == 'voting' ||
        updatedGameData['roundState'] == 'reveal_and_vote') {
      await _tallyVotes(gameRef, updatedGameData);
    } else if (updatedGameData['gameType'] == 'Infiltré & Mr. White' &&
        updatedGameData['currentPhase'] == 'voting') {
      // Force la résolution du vote avec les votes actuels
      var votes = Map<String, dynamic>.from(updatedGameData['votes'] ?? {});
      var playerData = Map<String, dynamic>.from(
        updatedGameData['playerData'] ?? {},
      );

      final activeIds =
          playerData.entries
              .where((e) => (e.value['status'] ?? 'active') == 'active')
              .map((e) => e.key)
              .toList();
      for (final pId in activeIds) {
        if (!votes.containsKey(pId) && _isPlayerIdBot(updatedGameData, pId)) {
          final targets = activeIds.where((id) => id != pId).toList();
          if (targets.isNotEmpty) {
            votes[pId] = targets[Random().nextInt(targets.length)];
          }
        }
      }

      if (votes.isEmpty) {
        // Personne n'a voté, passer au prochain tour sans élimination
        await gameRef.update({
          'currentPhase': 'turn_result',
          'eliminatedThisTurn': [],
          'turnLog': FieldValue.arrayUnion([_l10n.personneNAVoteAucun]),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        // Compter les votes existants
        Map<String, int> voteCounts = {};
        votes.forEach(
          (_, targetId) =>
              voteCounts[targetId as String] = (voteCounts[targetId] ?? 0) + 1,
        );

        int maxVotes = 0;
        List<String> tiedPlayers = [];
        voteCounts.forEach((player, count) {
          if (count > maxVotes) {
            maxVotes = count;
            tiedPlayers = [player];
          } else if (count == maxVotes) {
            tiedPlayers.add(player);
          }
        });

        if (tiedPlayers.length > 1) {
          final String? goddessId =
              updatedGameData['specialRoles']?['justiceGoddess'];
          if (goddessId != null &&
              playerData[goddessId]?['status'] == 'active') {
            await gameRef.update({
              'currentPhase': 'tie_breaker',
              'tieBreakerCandidates': tiedPlayers,
              'turnLog': FieldValue.arrayUnion([_l10n.egaliteLorsDuVoteLa]),
              'turnStartTime': FieldValue.serverTimestamp(),
            });
          } else {
            int tieCount =
                (updatedGameData['votingTieCount'] as num? ?? 0).toInt() + 1;
            int aliveCount =
                playerData.values
                    .where((p) => (p['status'] ?? 'active') == 'active')
                    .length;

            if (tieCount >= 2 || aliveCount <= 3) {
              // Égalité persistante ou fin de partie bloquée : tirage au sort parmi les ex-aequo
              String randomEliminated =
                  tiedPlayers[Random().nextInt(tiedPlayers.length)];
              await gameRef.update({
                'currentPhase': 'turn_result',
                'eliminatedThisTurn': [randomEliminated],
                'votingTieCount': 0,
                'turnLog': FieldValue.arrayUnion([
                  _l10n.egalitePersistanteLeDestinDepartage1(
                    playerData[randomEliminated]?['name'],
                  ),
                ]),
                'turnStartTime': FieldValue.serverTimestamp(),
              });
            } else {
              await gameRef.update({
                'currentPhase': 'turn_result',
                'eliminatedThisTurn': [],
                'votingTieCount': tieCount,
                'turnLog': FieldValue.arrayUnion([
                  _l10n.egaliteParfaiteLorsDuVote2(tiedPlayers.length),
                ]),
                'turnStartTime': FieldValue.serverTimestamp(),
              });
            }
          }
        } else {
          String? eliminatedPlayerId =
              tiedPlayers.isNotEmpty ? tiedPlayers.first : null;
          await gameRef.update({
            'currentPhase': 'turn_result',
            'eliminatedThisTurn':
                eliminatedPlayerId != null ? [eliminatedPlayerId] : [],
            'turnLog': FieldValue.arrayUnion([_l10n.leTempsDeVoteEst]),
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    } else if (updatedGameData['gameType'] == 'Le Juge' &&
        updatedGameData['roundState'] == 'voting') {
      // Forcer la résolution pour Le Juge via _tallyVotes si non fait
      await _tallyVotes(gameRef, updatedGameData);
    }
  }

  Future<void> handleHostActionTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;

    if (gameData['gameState'] != 'playing') return;
    final String? rState = gameData['roundState'] as String?;
    final String? cPhase = gameData['currentPhase'] as String?;
    final bool isDominoRoundOver = gameData['dominoesRoundOver'] == true;
    if (rState != 'result' &&
        rState != 'round_end' &&
        rState != 'results' &&
        cPhase != 'turn_result' &&
        !isDominoRoundOver) {
      return;
    }

    final gameType = gameData['gameType'];
    switch (gameType) {
      case 'Dobble':
        await nextDobbleRound(gameCode);
        break;
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        await nextHotPotatoRound(gameCode);
        break;
      case 'Pictionary':
        await nextPictionaryRound(gameCode);
        break;
      case 'Just One':
        await nextJustOneRound(gameCode);
        break;
      case 'Skull':
        await nextSkullRound(gameCode);
        break;
      case 'Président':
        await nextPresidentRound(gameCode);
        break;
      case 'Devine Tête':
        await nextDevineTeteTurn(gameCode);
        break;
      case 'Infiltré & Mr. White':
        await processEliminationsAndCheckWin(gameCode);
        break;
      case 'Zéro Pointé':
        await _startZeroPointeRound(gameRef, gameData);
        break;
      case 'Rami':
        await _startRamiRound(gameRef, gameData);
        break;
      case 'Dominoes':
        await startNextDominoesRound(gameCode);
        break;
      case 'Photo Roulette':
        await startNextPhotoRouletteRound(gameCode);
        break;
      case 'Yams':
      case 'Bataille Navale':
        break;

      default:
        await nextRound(gameCode);
        break;
    }
  }

  // --- LOGIQUE YAMS ---
  Future<void> _startYamsRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerProfiles = Map<String, dynamic>.from(
      gameData['playerProfiles'] ?? {},
    );
    final Set<String> allPlayerIds = {};
    allPlayerIds.addAll(players.keys);
    allPlayerIds.addAll(playerProfiles.keys);
    if (gameData['playerOrder'] is List) {
      allPlayerIds.addAll(
        (gameData['playerOrder'] as List).map((e) => e.toString()),
      );
    }
    if (gameData['yamsPlayerOrder'] is List) {
      allPlayerIds.addAll(
        (gameData['yamsPlayerOrder'] as List).map((e) => e.toString()),
      );
    }

    for (String pId in allPlayerIds) {
      String pName = _l10n.joueur;
      if (players[pId] is Map &&
          players[pId]['name'] != null &&
          players[pId]['name'] != 'Inconnu' &&
          players[pId]['name'].toString().trim().isNotEmpty) {
        pName = players[pId]['name'];
      } else if (playerProfiles[pId] is Map &&
          playerProfiles[pId]['name'] != null &&
          playerProfiles[pId]['name'] != 'Inconnu' &&
          playerProfiles[pId]['name'].toString().trim().isNotEmpty) {
        pName = playerProfiles[pId]['name'];
      }
      players[pId] = {
        ...(players[pId] is Map ? players[pId] : {}),
        'name': pName,
        'score': (players[pId] is Map ? players[pId]['score'] : 0) ?? 0,
      };
      playerProfiles[pId] = {
        ...(playerProfiles[pId] is Map ? playerProfiles[pId] : {}),
        'name': pName,
      };
    }

    final playerIds = allPlayerIds.toList()..shuffle();

    Map<String, Map<String, int>> scores = {};
    for (String pId in playerIds) {
      scores[pId] = {};
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'players': players,
      'playerProfiles': playerProfiles,
      'playerOrder': playerIds,
      'yamsPlayerOrder': playerIds,
      'yamsCurrentPlayerId': playerIds.first,
      'yamsDice': [0, 0, 0, 0, 0],
      'yamsHeldDice': [false, false, false, false, false],
      'yamsRollsLeft': 3,
      'yamsScores': scores,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [_l10n.logYamsStart],
    });
  }

  Future<void> yamsRollDice(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      if (gameData['yamsCurrentPlayerId'] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }
      final int rollsLeft = gameData['yamsRollsLeft'] ?? 3;
      if (rollsLeft <= 0) {
        throw Exception(_l10n.plusDeLancersDisponibles);
      }

      final rawDice = gameData['yamsDice'] as List<dynamic>?;
      List<int> currentDice =
          (rawDice != null && rawDice.length == 5)
              ? List<int>.from(rawDice.map((e) => (e as num).toInt()))
              : [0, 0, 0, 0, 0];
      final List<bool> heldDice = List<bool>.from(
        gameData['yamsHeldDice'] ?? [false, false, false, false, false],
      );
      final List<bool> effectiveHeld =
          (rollsLeft == 3) ? [false, false, false, false, false] : heldDice;
      final rand = Random();

      for (int i = 0; i < 5; i++) {
        if (!effectiveHeld[i] || currentDice[i] == 0 || rollsLeft == 3) {
          currentDice[i] = rand.nextInt(6) + 1;
        }
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        1,
        applySpeedBonus: true,
      );

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final pName = players[playerId]?['name'] ?? _l10n.joueur;
      final String rollMsg =
          (rollsLeft == 3)
              ? _l10n.aLanceLesDes(pName)
              : _l10n.aRelanceLesDes2(pName, 3 - rollsLeft + 1);

      transaction.update(gameRef, {
        'yamsDice': currentDice,
        'yamsHeldDice': effectiveHeld,
        'yamsRollsLeft': rollsLeft - 1,
        'yamsLastHoldAction': rollMsg,
        'yamsLastTappedIndex': null,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
      updateYamsLiveInteraction(gameCode, playerId, tappedDieIndex: null);
    });
  }

  Future<void> yamsToggleHold(
    String gameCode,
    String playerId,
    int index,
  ) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    if (gameData['yamsCurrentPlayerId'] != playerId) return;
    if (gameData['yamsRollsLeft'] == 3) return;

    List<bool> heldDice = List<bool>.from(
      gameData['yamsHeldDice'] ?? [false, false, false, false, false],
    );
    if (index >= 0 && index < heldDice.length) {
      heldDice[index] = !heldDice[index];
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final pName = players[playerId]?['name'] ?? _l10n.joueur;
      final isNowHeld = heldDice[index];
      final currentDice = List<int>.from(gameData['yamsDice'] ?? []);
      final dieVal = (index < currentDice.length) ? currentDice[index] : 0;
      final actionText =
          isNowHeld
              ? _l10n.aGardeLeDeDe(pName, dieVal, index + 1)
              : _l10n.aDebloqueLeDe(pName, index + 1);

      await gameRef.update({
        'yamsHeldDice': heldDice,
        'yamsLastHoldAction': actionText,
        'yamsLastTappedIndex': index,
      });

      updateYamsLiveInteraction(gameCode, playerId, tappedDieIndex: index);
    }
  }

  // --- YAMS ---
  Future<void> yamsScoreCategory(
    String gameCode,
    String playerId,
    String category, {
    bool isAuto = false,
  }) async {
    if (!isAuto) {
      final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
      if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      if (gameData['yamsCurrentPlayerId'] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }
      if (gameData['yamsRollsLeft'] == 3 && !isAuto) {
        throw Exception(_l10n.vousDevezLancerLesDes);
      }

      final rawScores = Map<String, dynamic>.from(gameData['yamsScores'] ?? {});
      final myScores = Map<String, dynamic>.from(rawScores[playerId] ?? {});

      if (myScores.containsKey(category)) {
        throw Exception(_l10n.categorieDejaCompletee);
      }

      final dice = List<int>.from(gameData['yamsDice'] ?? []);
      final score = dice.length == 5 ? calculateYamsScore(dice, category) : 0;
      myScores[category] = score;
      rawScores[playerId] = myScores;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final isGameOver = players.keys.every(
        (pId) => (rawScores[pId] as Map?)?.length == 13,
      );

      final playerOrder = List<String>.from(
        gameData['yamsPlayerOrder'] ?? players.keys.toList(),
      );
      final nextPlayerId =
          playerOrder[(playerOrder.indexOf(playerId) + 1) % playerOrder.length];

      if (!isAuto) {
        int rollsLeft = (gameData['yamsRollsLeft'] as num?)?.toInt() ?? 3;
        int xpBase = 8; // Catégorie simple (As à Six)

        if (category == 'Grande Suite' && score == 40 && rollsLeft == 2) {
          final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.yams_full_suite': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }

        if (category == 'Yams') {
          xpBase = 75; // YAMS complet
        } else if (category == 'Grande Suite' || category == 'Petite Suite') {
          xpBase = 35;
        } else if (category == 'Full') {
          xpBase = 25;
        } else if (category == 'Brelan' || category == 'Carré') {
          xpBase = 15;
        }

        // Bonus de 20 XP si la combinaison a été validée dès le premier jet de dés
        if (rollsLeft == 2 && score > 0) {
          xpBase += 20;
        }

        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          xpBase,
          applySpeedBonus: true,
        );
      }

      final updates = <String, dynamic>{
        'yamsScores': rawScores,
        'yamsCurrentPlayerId': nextPlayerId,
        'yamsDice': [],
        'yamsHeldDice': [false, false, false, false, false],
        'yamsRollsLeft': 3,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isGameOver) {
        final Map<String, int> finalScores = {};
        for (final pId in players.keys) {
          final pScores = Map<String, dynamic>.from(rawScores[pId] ?? {});
          final upperSum = [
            'As',
            'Deux',
            'Trois',
            'Quatre',
            'Cinq',
            'Six',
          ].fold<int>(
            0,
            (sum, cat) => sum + ((pScores[cat] as num?)?.toInt() ?? 0),
          );
          final bonus = upperSum >= 63 ? 35 : 0;
          if (upperSum >= 63) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'unlockedBadges.yams_bonus_sup': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              40, // Prime 63 points
              applySpeedBonus: false,
            );
          }
          final total =
              pScores.values.fold<int>(
                0,
                (sum, val) => sum + ((val as num?)?.toInt() ?? 0),
              ) +
              bonus;
          finalScores[pId] = total;
        }

        final winnerId =
            finalScores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = winnerId;
        updates['players.$winnerId.score'] = FieldValue.increment(1);
        updates['yamsFinalScores'] = finalScores;
        updates['gameEndReason'] = _l10n.grilleDeYamsCompleteePar;
      }

      transaction.update(gameRef, updates);
    });
  }

  int calculateYamsScore(List<int> dice, String category) {
    if (dice.length != 5 || dice.any((d) => d < 1 || d > 6)) return 0;
    Map<int, int> counts = {};
    for (int d in dice) counts[d] = (counts[d] ?? 0) + 1;
    int sum = dice.fold(0, (a, b) => a + b);
    List<int> sortedDice = List.from(dice)..sort();

    switch (category) {
      case 'As':
        return counts[1] ?? 0;
      case 'Deux':
        return (counts[2] ?? 0) * 2;
      case 'Trois':
        return (counts[3] ?? 0) * 3;
      case 'Quatre':
        return (counts[4] ?? 0) * 4;
      case 'Cinq':
        return (counts[5] ?? 0) * 5;
      case 'Six':
        return (counts[6] ?? 0) * 6;
      case 'Brelan':
        return counts.values.any((c) => c >= 3) ? sum : 0;
      case 'Carré':
        return counts.values.any((c) => c >= 4) ? sum : 0;
      case 'Full':
        // 3 identiques + 2 identiques (ou 5 identiques)
        return (counts.values.contains(3) && counts.values.contains(2)) ||
                counts.values.contains(5)
            ? 25
            : 0;
      case 'Petite Suite':
        bool hasSmall =
            [1, 2, 3, 4].every((e) => sortedDice.contains(e)) ||
            [2, 3, 4, 5].every((e) => sortedDice.contains(e)) ||
            [3, 4, 5, 6].every((e) => sortedDice.contains(e));
        return hasSmall ? 30 : 0;
      case 'Grande Suite':
        bool hasLarge =
            [1, 2, 3, 4, 5].every((e) => sortedDice.contains(e)) ||
            [2, 3, 4, 5, 6].every((e) => sortedDice.contains(e));
        return hasLarge ? 40 : 0;
      case 'Yams':
        return counts.values.contains(5) ? 50 : 0;
      case 'Chance':
        return sum;
      default:
        return 0;
    }
  }

  // =========================================================================
  // 7. YAMS (YAHTZEE)
  // =========================================================================
  Future<void> handleYamsTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final data = snap.data() as Map<String, dynamic>;
    if (data['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(data)) return;

    final currentPlayerId = data['yamsCurrentPlayerId'];
    if (currentPlayerId == null) return;
    final rollsLeft = (data['yamsRollsLeft'] as num?)?.toInt() ?? 3;
    Map<String, dynamic> currentData = data;

    if (rollsLeft == 3) {
      try {
        await yamsRollDice(gameCode, currentPlayerId, isAuto: true);
        final updatedSnap = await gameRef.get();
        if (updatedSnap.exists) {
          currentData = updatedSnap.data() as Map<String, dynamic>;
        }
      } catch (_) {}
    }

    final rawDice = currentData['yamsDice'] as List<dynamic>?;
    List<int> dice =
        (rawDice != null && rawDice.length == 5 && !rawDice.contains(0))
            ? List<int>.from(rawDice.map((e) => (e as num).toInt()))
            : [1, 2, 3, 4, 5];

    final rawScores = Map<String, dynamic>.from(
      currentData['yamsScores'] ?? {},
    );
    final myScores = Map<String, dynamic>.from(
      rawScores[currentPlayerId] ?? {},
    );

    const allCategories = [
      'Yams',
      'Grande Suite',
      'Petite Suite',
      'Full',
      'Carré',
      'Brelan',
      'Six',
      'Cinq',
      'Quatre',
      'Trois',
      'Deux',
      'As',
      'Chance',
    ];
    final available =
        allCategories.where((cat) => !myScores.containsKey(cat)).toList();
    if (available.isEmpty) return;

    // 1. Choisir la catégorie disponible qui rapporte le meilleur score (> 0)
    String? bestCategory;
    int bestScore = 0;
    for (final cat in available) {
      final int sc = calculateYamsScore(dice, cat);
      if (sc > bestScore) {
        bestScore = sc;
        bestCategory = cat;
      }
    }

    // 2. Si toutes les catégories disponibles valent 0, sacrifier la moins pénalisante
    if (bestCategory == null) {
      const sacrificeOrder = [
        'As',
        'Deux',
        'Trois',
        'Brelan',
        'Carré',
        'Quatre',
        'Cinq',
        'Six',
        'Petite Suite',
        'Full',
        'Chance',
        'Grande Suite',
        'Yams',
      ];
      bestCategory = sacrificeOrder.firstWhere(
        (cat) => available.contains(cat),
        orElse: () => available.first,
      );
    }

    await yamsScoreCategory(
      gameCode,
      currentPlayerId,
      bestCategory,
      isAuto: true,
    );
  }

  Future<void> startCadavreExquis(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final List<String> playerIds =
        gameData['playerOrder'] != null &&
                (gameData['playerOrder'] as List).isNotEmpty
            ? List<String>.from(gameData['playerOrder'])
            : (Map<String, dynamic>.from(
                gameData['players'] ?? {},
              ).keys.toList()
              ..shuffle());
    final variant = gameData['cadavreVariant'] ?? 'classic';
    final passingMode = gameData['cadavrePassingMode'] ?? 'single';

    int totalSteps = variant == 'classic' ? 5 : playerIds.length;
    final List<String> aiWords = List<String>.from(gameData['aiWords'] ?? []);

    Map<String, dynamic> papers = {};
    int numPapers = passingMode == 'single' ? 1 : playerIds.length;
    for (int i = 0; i < numPapers; i++) {
      final List<Map<String, dynamic>> initialSteps = [];
      if (aiWords.isNotEmpty) {
        initialSteps.add({
          'authorId': 'AI',
          'text': aiWords[i % aiWords.length],
          'round': 0,
          'playerIndex': -1,
        });
      }
      papers[i.toString()] = {'steps': initialSteps};
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing',
      'playerOrder': playerIds,
      'papers': papers,
      'currentRound': 0,
      'currentPlayerIndex': 0,
      'totalStepsPerPaper': totalSteps,
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> submitCadavreExquisStep(
    String gameCode,
    String playerId,
    String rawText, {
    bool isAuto = false,
  }) async {
    if (!isAuto) {
      final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
      if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);
    }

    final cleanText = sanitizeUserInput(rawText, maxLength: 80);
    if (cleanText.isEmpty) throw Exception(_l10n.texteRequis);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'playing') return;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      int currentPlayerIndex = (gameData['currentPlayerIndex'] ?? 0) as int;
      int currentRound = (gameData['currentRound'] ?? 0) as int;
      int totalSteps = (gameData['totalStepsPerPaper'] ?? 5) as int;
      String passingMode = gameData['cadavrePassingMode'] ?? 'single';

      if (playerOrder.isEmpty ||
          currentPlayerIndex >= playerOrder.length ||
          playerOrder[currentPlayerIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre1);
      }

      int paperIndex =
          (passingMode == 'single')
              ? 0
              : (((currentPlayerIndex -
                      (currentRound % playerOrder.length) +
                      playerOrder.length) %
                  playerOrder.length));

      Map<String, dynamic> papers = Map<String, dynamic>.from(
        gameData['papers'] ?? {},
      );
      Map<String, dynamic> paper = Map<String, dynamic>.from(
        papers[paperIndex.toString()] ?? {'steps': []},
      );
      List<dynamic> steps = List<dynamic>.from(paper['steps'] ?? []);

      steps.add({
        'authorId': playerId,
        'text': cleanText,
        'round': currentRound,
        'playerIndex': currentPlayerIndex,
      });
      paper['steps'] = steps;
      papers[paperIndex.toString()] = paper;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final updates = <String, dynamic>{'papers': papers};

      if (passingMode == 'single') {
        // En mode feuille unique : chaque mot est 1 étape globale
        if (steps.length >= totalSteps) {
          updates['roundState'] = 'results';
          updates['gameState'] = 'gameOver';
          for (var pId in players.keys) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'badgeProgress.cadavre_master': FieldValue.increment(1),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              30,
              applySpeedBonus: false,
            );
          }
        } else {
          updates['currentPlayerIndex'] =
              (currentPlayerIndex + 1) % playerOrder.length;
          updates['currentRound'] = steps.length;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
      } else {
        // En mode feuilles multiples (tournante)
        int nextPlayerIndex = currentPlayerIndex + 1;
        int nextRound = currentRound;

        if (nextPlayerIndex >= playerOrder.length) {
          nextPlayerIndex = 0;
          nextRound++;
        }

        if (nextRound >= totalSteps) {
          updates['roundState'] = 'results';
          updates['gameState'] = 'gameOver';
          for (var pId in players.keys) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'badgeProgress.cadavre_master': FieldValue.increment(1),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              30,
              applySpeedBonus: false,
            );
          }
        } else {
          updates['currentPlayerIndex'] = nextPlayerIndex;
          updates['currentRound'] = nextRound;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
      }

      if (!isAuto) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          10,
          applySpeedBonus: true,
        );
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> submitCadavreExquisStepSecure(
    String gameCode,
    String playerId,
    String rawText,
  ) => submitCadavreExquisStep(gameCode, playerId, rawText);

  // =========================================================================
  // 2. UNO
  // =========================================================================
  Future<void> handleUnoTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final playerOrder = List<String>.from(gameData['unoPlayerOrder'] ?? []);
      final currentIndex =
          (gameData['unoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (playerOrder.isEmpty || currentIndex >= playerOrder.length) return;

      final playerId = playerOrder[currentIndex];
      final playerName =
          gameData['players']?[playerId]?['name'] ?? _l10n.joueur;
      final hands = Map<String, dynamic>.from(gameData['unoPlayerHands'] ?? {});
      final myHand = List<String>.from(hands[playerId] ?? []);
      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      final String topCard =
          discardPile.isNotEmpty ? discardPile.last : 'red-0';
      final String? wildColor = gameData['unoWildColorChosen'];
      int direction = (gameData['unoDirection'] as num?)?.toInt() ?? 1;
      int pendingDraw = (gameData['unoPendingDraw'] as num?)?.toInt() ?? 0;
      final bool stackDraws = gameData['unoStackDraws'] == true;

      final bool drawActionDone = gameData['unoDrawActionDone'] == true;
      final String? lastDrawn = gameData['unoLastDrawnCard'] as String?;
      int nextIndex =
          (currentIndex + direction + playerOrder.length) % playerOrder.length;

      String drawOneCard() {
        if (deck.isEmpty && discardPile.length > 1) {
          String topCardDiscard = discardPile.removeLast();
          deck = List<String>.from(discardPile)..shuffle();
          discardPile = [topCardDiscard];
        }
        return deck.isNotEmpty ? deck.removeAt(0) : 'red-0';
      }

      String determineBestUnoColor(List<String> hand) {
        const colors = ['red', 'blue', 'green', 'yellow'];
        Map<String, int> counts = {
          'red': 0,
          'blue': 0,
          'green': 0,
          'yellow': 0,
        };
        for (var c in hand) {
          for (var col in colors) {
            if (c.startsWith(col)) counts[col] = (counts[col] ?? 0) + 1;
          }
        }
        String best = 'red';
        int maxC = -1;
        counts.forEach((col, count) {
          if (count > maxC) {
            maxC = count;
            best = col;
          }
        });
        return best;
      }

      void applyCardPlay(String playedCard) {
        myHand.remove(playedCard);
        discardPile.add(playedCard);
        hands[playerId] = myHand;
        final String? autoWild =
            playedCard.startsWith('wild')
                ? determineBestUnoColor(myHand)
                : null;

        if (myHand.isEmpty) {
          int roundScore = 0;
          hands.forEach((pId, h) {
            if (pId != playerId && h is List) {
              for (var c in h) {
                final String cs = c.toString();
                if (cs.startsWith('wild')) {
                  roundScore += 50;
                } else if (cs.endsWith('draw2') ||
                    cs.endsWith('skip') ||
                    cs.endsWith('reverse')) {
                  roundScore += 20;
                } else {
                  final parts = cs.split('-');
                  roundScore +=
                      parts.length > 1 ? (int.tryParse(parts[1]) ?? 5) : 5;
                }
              }
            }
          });
          if (roundScore <= 0) roundScore = 1;
          transaction.update(gameRef, {
            'gameState': 'gameOver',
            'gameWinner': playerId,
            'players.$playerId.score': FieldValue.increment(roundScore),
            'unoPlayerHands': hands,
            'unoDeck': deck,
            'unoDiscardPile': discardPile,
            'unoWildColorChosen': autoWild,
            'unoPendingDraw': 0,
            'gameEndReason': _l10n.aGagne(playerName),
          });
          return;
        }

        int step = 1;
        if (playedCard.endsWith('reverse')) {
          if (playerOrder.length == 2) {
            step = 2;
          } else {
            direction = -direction;
          }
        } else if (playedCard.endsWith('skip')) {
          step = 2;
        } else if (playedCard.endsWith('draw2')) {
          if (stackDraws) {
            pendingDraw += 2;
          } else {
            final victimId = playerOrder[nextIndex];
            final victimHand = List<String>.from(hands[victimId] ?? []);
            for (int i = 0; i < 2; i++) victimHand.add(drawOneCard());
            hands[victimId] = victimHand;
            step = 2;
          }
        } else if (playedCard == 'wild_draw4') {
          if (stackDraws) {
            pendingDraw += 4;
          } else {
            final victimId = playerOrder[nextIndex];
            final victimHand = List<String>.from(hands[victimId] ?? []);
            for (int i = 0; i < 4; i++) victimHand.add(drawOneCard());
            hands[victimId] = victimHand;
            step = 2;
          }
        }

        final int computedNext =
            (currentIndex + (direction * step) + (playerOrder.length * 4)) %
            playerOrder.length;

        transaction.update(gameRef, {
          'unoPlayerHands': hands,
          'unoDeck': deck,
          'unoDiscardPile': discardPile,
          'unoDirection': direction,
          'unoPendingDraw': pendingDraw,
          'unoCurrentPlayerIndex': computedNext,
          'unoDrawActionDone': false,
          'unoLastDrawnCard': null,
          'unoWildColorChosen': autoWild,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aJoue1(playerName, playedCard),
          ]),
        });
      }

      // 0. Gestion de la pénalité de pioche cumulée (+2 / +4)
      if (pendingDraw > 0) {
        if (stackDraws) {
          final String stackCard = myHand.firstWhere(
            (c) =>
                (topCard.endsWith('draw2') && c.endsWith('draw2')) ||
                (topCard == 'wild_draw4' && c == 'wild_draw4'),
            orElse: () => '',
          );
          if (stackCard.isNotEmpty) {
            applyCardPlay(stackCard);
            return;
          }
        }
        for (int i = 0; i < pendingDraw; i++) {
          myHand.add(drawOneCard());
        }
        hands[playerId] = myHand;
        transaction.update(gameRef, {
          'unoPlayerHands': hands,
          'unoDeck': deck,
          'unoDiscardPile': discardPile,
          'unoPendingDraw': 0,
          'unoCurrentPlayerIndex': nextIndex,
          'unoDrawActionDone': false,
          'unoLastDrawnCard': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.piocheEtPasseSonTour(playerName),
          ]),
        });
        return;
      }

      // 1. Déjà pioché : jouer la carte piochée si possible, sinon passer
      if (drawActionDone) {
        if (lastDrawn != null &&
            myHand.contains(lastDrawn) &&
            GameData.canPlayUnoCard(lastDrawn, topCard, wildColor)) {
          applyCardPlay(lastDrawn);
        } else {
          transaction.update(gameRef, {
            'unoCurrentPlayerIndex': nextIndex,
            'unoDrawActionDone': false,
            'unoLastDrawnCard': null,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([_l10n.passeSonTour2(playerName)]),
          });
        }
        return;
      }

      // 2. Jouer la meilleure carte valide (garder les Jokers en dernier recours)
      final playableCards =
          myHand
              .where((c) => GameData.canPlayUnoCard(c, topCard, wildColor))
              .toList();
      if (playableCards.isNotEmpty) {
        playableCards.sort((a, b) {
          int scoreCard(String c) {
            if (c == 'wild_draw4') return 30;
            if (c == 'wild') return 20;
            if (c.endsWith('draw2') ||
                c.endsWith('skip') ||
                c.endsWith('reverse'))
              return 5;
            return 10;
          }

          return scoreCard(a).compareTo(scoreCard(b));
        });
        applyCardPlay(playableCards.first);
      }
      // 3. Piocher
      else {
        myHand.add(drawOneCard());
        hands[playerId] = myHand;
        transaction.update(gameRef, {
          'unoPlayerHands': hands,
          'unoDeck': deck,
          'unoDiscardPile': discardPile,
          'unoCurrentPlayerIndex': nextIndex,
          'unoDrawActionDone': false,
          'unoLastDrawnCard': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.piocheEtPasseSonTour(playerName),
          ]),
        });
      }
    });
  }

  // =========================================================================
  // 14. POKER
  // =========================================================================
  Future<void> handlePokerTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;

    final phase = gameData['phase'] as String?;
    if (phase == 'hand_over') {
      await _startPokerHand(gameRef, gameData);
      return;
    }
    if (!_isTurnTimedOut(gameData)) return;
    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    int currentPlayerIndex =
        (gameData['currentPlayerIndex'] as num? ?? 0).toInt();
    if (currentPlayerIndex >= playerOrder.length) return;
    String timedOutPlayerId = playerOrder[currentPlayerIndex];
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    if (playerData[timedOutPlayerId]?['status'] != 'active') {
      final turnUpdates = _advancePokerTurn(gameData);
      if (turnUpdates.isNotEmpty) {
        await gameRef.update(turnUpdates);
      }
      return;
    }

    final int currentBet = (gameData['currentBet'] as num? ?? 0).toInt();
    final int myBet =
        (playerData[timedOutPlayerId]?['currentBet'] as num? ?? 0).toInt();
    final String action = (myBet >= currentBet) ? 'check' : 'fold';

    await pokerAction(gameCode, timedOutPlayerId, action, isAuto: true);
  }

  // =========================================================================
  // GESTION DU TIMEOUT / JEU AUTOMATIQUE ROBUSTE DE ZÉRO POINTÉ
  // =========================================================================
  Future<void> handleZeroPointeTimeout(String gameCode) async {
    final preRef = _db.collection('games').doc(gameCode);
    final preSnap = await preRef.get();
    if (!preSnap.exists || preSnap.data() == null) return;
    final preData = preSnap.data() as Map<String, dynamic>;
    if (preData['gameState'] != 'playing') return;
    if (preData['roundState'] == 'round_end') {
      if (_isTurnTimedOut(preData)) {
        await _startZeroPointeRound(preRef, preData);
      }
      return;
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final String roundState = gameData['roundState'] ?? '';
      if (roundState == 'round_end') return;

      // CAS 1 : Phase de révélation des 2 cartes initiales
      if (roundState == 'revealing_initial') {
        var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
        var counts = Map<String, int>.from(
          (gameData['revealedInitialCardsCount'] as Map? ?? {}).map(
            (k, v) => MapEntry(k.toString(), (v as num?)?.toInt() ?? 0),
          ),
        );
        var players = Map<String, dynamic>.from(gameData['players'] ?? {});
        bool updated = false;

        players.forEach((pId, _) {
          var playerGrid =
              (grids[pId] as List?)
                  ?.map((e) => Map<String, dynamic>.from(e as Map))
                  .toList() ??
              [];
          int revCount = counts[pId] ?? 0;

          for (int i = 0; i < playerGrid.length && revCount < 2; i++) {
            if (playerGrid[i]['revealed'] == false) {
              playerGrid[i]['revealed'] = true;
              revCount++;
              updated = true;
            }
          }
          grids[pId] = playerGrid;
          counts[pId] = revCount;
        });

        if (updated) {
          bool allReady = counts.values.every((c) => c >= 2);
          transaction.update(gameRef, {
            'playerGrids': grids,
            'revealedInitialCardsCount': counts,
            'roundState': allReady ? 'player_turn' : 'revealing_initial',
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
        return;
      }

      // CAS 2 : Phase de tour normale ou carte déjà piochée
      final timedOutPlayerId = gameData['currentPlayerId'];
      if (timedOutPlayerId == null) return;

      await _drawAndDiscardZeroPointeLogic(
        transaction,
        gameRef,
        gameData,
        timedOutPlayerId,
      );
    });
  }

  Future<void> _drawAndDiscardZeroPointeLogic(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
  ) async {
    var deck = List<int>.from(gameData['deck'] ?? []);
    var discardPile = List<int>.from(gameData['discardPile'] ?? []);
    var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
    var playerGrid =
        (grids[playerId] as List)
            .map((e) => Map<String, dynamic>.from(e as Map))
            .toList();

    // 1. Obtenir la carte piochée (ou piocher depuis le paquet)
    int? drawnCard;
    if (gameData['drawnCard'] != null) {
      drawnCard = (gameData['drawnCard'] as num).toInt();
    } else if (deck.isNotEmpty) {
      drawnCard = deck.removeAt(0);
    } else if (discardPile.length > 1) {
      int top = discardPile.removeLast();
      deck = List<int>.from(discardPile)..shuffle();
      discardPile = [top];
      if (deck.isNotEmpty) {
        drawnCard = deck.removeAt(0);
      }
    }

    // 2. Décision intelligente : si la carte piochée est basse (<= 4), remplacer la pire carte haute révélée (>= 6)
    bool replacedHighCard = false;
    if (drawnCard != null && drawnCard <= 4) {
      int worstIdx = -1;
      int worstVal = -999;
      for (int i = 0; i < playerGrid.length; i++) {
        final int val = (playerGrid[i]['value'] as num).toInt();
        if (playerGrid[i]['revealed'] == true &&
            val != -100 &&
            val >= 6 &&
            val > worstVal) {
          worstVal = val;
          worstIdx = i;
        }
      }
      if (worstIdx != -1) {
        discardPile.add(worstVal);
        playerGrid[worstIdx]['value'] = drawnCard;
        playerGrid[worstIdx]['revealed'] = true;
        grids[playerId] = playerGrid;
        replacedHighCard = true;
      }
    }

    if (!replacedHighCard) {
      if (drawnCard != null) {
        discardPile.add(drawnCard);
      }
      // Révéler la première carte encore cachée
      int? indexToReveal;
      for (int i = 0; i < playerGrid.length; i++) {
        if (playerGrid[i]['revealed'] == false &&
            playerGrid[i]['value'] != -100) {
          indexToReveal = i;
          break;
        }
      }
      if (indexToReveal != null) {
        playerGrid[indexToReveal]['revealed'] = true;
        grids[playerId] = playerGrid;
      }
    }

    // Mettre à jour l'objet gameData en mémoire pour la suite du traitement
    gameData['playerGrids'] = grids;
    gameData['deck'] = deck;
    gameData['discardPile'] = discardPile;
    gameData['drawnCard'] = null;

    final String playerName =
        gameData['players']?[playerId]?['name'] ?? _l10n.unJoueur;

    transaction.update(gameRef, {
      'drawnCard': null,
      'deck': deck,
      'discardPile': discardPile,
      'playerGrids': grids,
      'gameLog': FieldValue.arrayUnion([_l10n.nAPasJoueA4(playerName)]),
    });

    // 3. Traiter immédiatement la fin du tour et passer au joueur suivant
    await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
  }

  Future<void> _processZeroPointeTurnEnd(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
  ) async {
    var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
    var playerGrid =
        (grids[playerId] as List)
            .map((e) => Map<String, dynamic>.from(e as Map))
            .toList();
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    // Annulation des colonnes identiques
    for (int col = 0; col < 4; col++) {
      int card1Index = col;
      int card2Index = col + 4;
      int card3Index = col + 8;
      if (playerGrid[card1Index]['value'] != -100 &&
          playerGrid[card2Index]['value'] != -100 &&
          playerGrid[card3Index]['value'] != -100 &&
          playerGrid[card1Index]['revealed'] == true &&
          playerGrid[card2Index]['revealed'] == true &&
          playerGrid[card3Index]['revealed'] == true &&
          playerGrid[card1Index]['value'] == playerGrid[card2Index]['value'] &&
          playerGrid[card1Index]['value'] == playerGrid[card3Index]['value']) {
        playerGrid[card1Index]['value'] = -100;
        playerGrid[card2Index]['value'] = -100;
        playerGrid[card3Index]['value'] = -100;
      }
    }
    grids[playerId] = playerGrid;

    bool allCardsRevealed = playerGrid.every(
      (card) => card['revealed'] == true || card['value'] == -100,
    );

    if (allCardsRevealed) {
      // Fin de la manche
      Map<String, int> roundScores = {};
      int lowestScoreInRound = 999;

      players.keys.forEach((pId) {
        List<Map<String, dynamic>> currentGrid =
            (grids[pId] as List)
                .map((card) => Map<String, dynamic>.from(card as Map))
                .toList();
        for (var card in currentGrid) {
          card['revealed'] = true;
        }
        for (int col = 0; col < 4; col++) {
          int c1 = col;
          int c2 = col + 4;
          int c3 = col + 8;
          if (currentGrid[c1]['value'] != -100 &&
              currentGrid[c2]['value'] != -100 &&
              currentGrid[c3]['value'] != -100 &&
              currentGrid[c1]['value'] == currentGrid[c2]['value'] &&
              currentGrid[c1]['value'] == currentGrid[c3]['value']) {
            currentGrid[c1]['value'] = -100;
            currentGrid[c2]['value'] = -100;
            currentGrid[c3]['value'] = -100;
          }
        }
        grids[pId] = currentGrid;
      });

      players.keys.forEach((pId) {
        int score = 0;
        (grids[pId] as List).forEach((card) {
          final cardMap = card as Map;
          if (cardMap['value'] != -100) {
            score += (cardMap['value'] as num).toInt();
          }
        });
        roundScores[pId] = score;
        if (score < lowestScoreInRound) {
          lowestScoreInRound = score;
        }
      });

      final roundEnderId = playerId;
      if ((roundScores[roundEnderId] ?? 0) > lowestScoreInRound) {
        roundScores[roundEnderId] = (roundScores[roundEnderId]! + 10);
      }

      var totalScores = Map<String, dynamic>.from(
        gameData['totalScores'] ?? {},
      );
      roundScores.forEach((pId, score) {
        totalScores[pId] = (totalScores[pId] ?? 0) + score;
      });

      Map<String, dynamic> updates = {
        'roundState': 'round_end',
        'roundEnderId': roundEnderId,
        'playerGrids': grids,
        'roundScores': roundScores,
        'totalScores': totalScores,
        'drawnCard': null,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      bool isGameOver = totalScores.values.any(
        (score) => (score as num) >= (gameData['targetScore'] ?? 100),
      );

      if (isGameOver) {
        String? gameWinnerId;
        int finalLowestScore = 9999;
        totalScores.forEach((pId, score) {
          int s = (score as num).toInt();
          if (s < finalLowestScore) {
            finalLowestScore = s;
            gameWinnerId = pId;
          }
        });
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': gameWinnerId,
          if (gameWinnerId != null)
            'players.$gameWinnerId.score': FieldValue.increment(1),
          'gameEndReason': _l10n.gagneAvecLeScoreLe(
            players[gameWinnerId]?['name'] ?? _l10n.joueur,
          ),
        });
      }

      transaction.update(gameRef, updates);
    } else {
      // Passer au joueur suivant
      var playerOrder = List<String>.from(
        gameData['playerOrder'] ?? players.keys.toList(),
      );
      int currentIndex = playerOrder.indexOf(playerId);
      int nextIndex = (currentIndex + 1) % playerOrder.length;

      transaction.update(gameRef, {
        'currentPlayerId': playerOrder[nextIndex],
        'roundState': 'player_turn',
        'drawnCard': null,
        'playerGrids': grids,
        'turnStartTime':
            FieldValue.serverTimestamp(), // Relance immédiatement le timer pour le joueur suivant
      });
    }
  }

