  Future<void> _checkForWinCondition(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    List<dynamic> vivants =
        playerData.values.where((p) => p['status'] == 'vivant').toList();
    if (vivants.isEmpty) return;

    String? winner;
    String? reason;

    int loupsVivants =
        vivants
            .where(
              (p) =>
                  GameData.roleCamps[p['role']] == 'loups' ||
                  p['infectionStatus'] == 'infecte',
            )
            .length;
    int villageoisVivants =
        vivants
            .where(
              (p) =>
                  (GameData.roleCamps[p['role']] == 'villageois' ||
                      GameData.roleCamps[p['role']] == 'special') &&
                  p['infectionStatus'] != 'infecte',
            )
            .length;

    final int nightNumber = (gameData['nightNumber'] as num?)?.toInt() ?? 0;
    int solitairesNonLoupsVivants =
        vivants
            .where(
              (p) =>
                  GameData.roleCamps[p['role']] == 'solitaire' &&
                  p['role'] != 'Loup Blanc' &&
                  !(p['role'] == 'Mercenaire' && nightNumber > 1),
            )
            .length;
    int loupBlancVivant =
        vivants.where((p) => p['role'] == 'Loup Blanc').length;
    int pyromancienVivant =
        vivants.where((p) => p['role'] == 'Pyromancien').length;

    int ratMaladeVivant =
        vivants.where((p) => p['role'] == 'Rat Malade').length;
    int contaminesVivants = vivants.where((p) => p['poisoned'] == true).length;
    List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    bool areLoversAlive =
        lovers.length == 2 &&
        playerData[lovers[0]]?['status'] == 'vivant' &&
        playerData[lovers[1]]?['status'] == 'vivant';

    if (areLoversAlive && vivants.length == 2) {
      winner = "Les Amoureux";
      reason = _l10n.seulsLesDeuxAmoureuxSont;
    }

    if (winner == null && loupBlancVivant == 1 && vivants.length == 1) {
      winner = "Loup Blanc";
      reason = _l10n.leLoupBlancEstLe;
    }

    if (winner == null && pyromancienVivant == 1 && vivants.length == 1) {
      winner = "Pyromancien";
      reason = "Le Pyromancien a réduit le village en cendres et survit seul !";
    }

    // Le Rat Malade gagne quand tous les AUTRES joueurs vivants sont contaminés (ou qu'il est le seul survivant)
    if (winner == null &&
        ratMaladeVivant > 0 &&
        contaminesVivants == vivants.length - ratMaladeVivant) {
      winner = "Rat Malade";
      reason =
          vivants.length == ratMaladeVivant
              ? _l10n.leRatMaladeEstLe
              : _l10n.tousLesAutresSurvivantsSont;
    }

    if (winner == null &&
        loupsVivants > 0 &&
        loupBlancVivant == 0 &&
        loupsVivants >= (villageoisVivants + solitairesNonLoupsVivants)) {
      winner = "Loups-Garous";
      reason = _l10n.lesLoupsGarousSontDevenus;
    }

    if (winner == null &&
        loupsVivants == 0 &&
        solitairesNonLoupsVivants == 0 &&
        loupBlancVivant == 0 &&
        villageoisVivants > 0) {
      winner = "Villageois";
      reason = _l10n.toutesLesMenacesOntEte;
    }

    if (winner != null) {
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final Map<String, dynamic> xpUpdates = {};

      if (winner == 'Les Amoureux') {
        for (var loverId in lovers) {
          _db
              .collection('users')
              .doc(players[loverId]?['authUid'] ?? loverId)
              .set({
                'unlockedBadges.lg_cupidon_love_win':
                    FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
        }
      } else if (winner == 'Loup Blanc') {
        final lbEntry =
            playerData.entries
                .where((e) => e.value['role'] == 'Loup Blanc')
                .firstOrNull;
        if (lbEntry != null) {
          final lbId = lbEntry.key;
          _db.collection('users').doc(players[lbId]?['authUid'] ?? lbId).set({
            'unlockedBadges.lg_loup_blanc_solo': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      } else if (winner == 'Rat Malade') {
        final rmEntry =
            playerData.entries
                .where((e) => e.value['role'] == 'Rat Malade')
                .firstOrNull;
        if (rmEntry != null) {
          final rmId = rmEntry.key;
          _db.collection('users').doc(players[rmId]?['authUid'] ?? rmId).set({
            'unlockedBadges.lg_rat_malade_win': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      } else if (winner == 'Villageois') {
        playerData.forEach((id, pInfo) {
          if (pInfo['role'] == 'Simple Villageois' &&
              pInfo['status'] == 'vivant') {
            _db.collection('users').doc(players[id]?['authUid'] ?? id).set({
              'unlockedBadges.lg_survivor_village':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        });
      } else if (winner == 'Loups-Garous') {
        playerData.forEach((id, pInfo) {
          if (pInfo['role'] == 'Loup Bavard' && pInfo['status'] == 'vivant') {
            _db.collection('users').doc(players[id]?['authUid'] ?? id).set({
              'unlockedBadges.lg_loup_bavard_alive':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        });
        bool noWolfDied = playerData.values
            .where((p) => GameData.roleCamps[p['role']] == 'loups')
            .every((p) => p['status'] == 'vivant');
        if (noWolfDied) {
          playerData.forEach((id, pInfo) {
            if (GameData.roleCamps[pInfo['role']] == 'loups') {
              _db.collection('users').doc(players[id]?['authUid'] ?? id).set({
                'unlockedBadges.lg_wolf_pack_win': FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
            }
          });
        }
      }

      playerData.forEach((pId, pInfo) {
        final role = pInfo['role'];
        final camp = GameData.roleCamps[role];
        final isInfected = pInfo['infectionStatus'] == 'infecte';
        final pAuth = players[pId]?['authUid'] ?? pId;
        int winXp = 0;

        if (winner == 'Loup Blanc' && role == 'Loup Blanc') {
          winXp = 75;
        } else if (winner == 'Pyromancien' && role == 'Pyromancien') {
          winXp = 75;
        } else if (winner == 'Rat Malade' && role == 'Rat Malade') {
          winXp = 75;
        } else if (winner == 'Les Amoureux' && lovers.contains(pId)) {
          winXp = 50;
        } else if (winner == 'Loups-Garous' &&
            (camp == 'loups' || isInfected)) {
          winXp = 35;
        } else if (winner == 'Villageois' &&
            (camp == 'villageois' || camp == 'special') &&
            !isInfected) {
          winXp = 35;
        }

        if (winXp > 0) {
          _db.collection('users').doc(pAuth).set({
            'xp': FieldValue.increment(winXp),
          }, SetOptions(merge: true));
          xpUpdates['players.$pId.xp'] = FieldValue.increment(winXp);
          xpUpdates['players.$pId.score'] = FieldValue.increment(1);
        }
      });

      await gameRef.update({
        'gameState': 'gameOver',
        'phase': 'gameOver',
        'gameWinner': winner,
        'gameLog': FieldValue.arrayUnion([
          _l10n.laPartieEstTermineeVictoire1(winner),
          reason,
        ]),
        ...xpUpdates,
      });
    }
  }

  static const List<String> nightPhaseOrder = [
    'cupidon_turn',
    'heritier_turn',
    'garde_turn',
    'voyante_turn',
    'rat_malade_turn',
    'loups_turn',
    'loup_blanc_turn',
    'sorciere_turn',
    'pyromancien_turn',
  ];

  bool _isPlayerForPhaseActive(
    String phase,
    Map<String, dynamic> gameData,
    Map<String, dynamic> playerData,
  ) {
    int nightNumber = gameData['nightNumber'] ?? 0;
    final nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );

    bool isRoleAlive(String role) {
      return playerData.values.any(
        (p) => p['role'] == role && p['status'] == 'vivant',
      );
    }

    switch (phase) {
      case 'cupidon_turn':
        return nightNumber == 0 &&
            isRoleAlive('Cupidon') &&
            nightActions['cupidonActed'] != true;
      case 'heritier_turn':
        var heritier = playerData.entries.firstWhere(
          (e) => e.value['role'] == 'Héritier' && e.value['status'] == 'vivant',
          orElse: () => MapEntry('', {}),
        );
        return nightNumber == 0 &&
            heritier.key.isNotEmpty &&
            heritier.value['testateurId'] == null;
      case 'garde_turn':
        return isRoleAlive('Garde') && nightActions['gardeActed'] != true;
      case 'voyante_turn':
        return isRoleAlive('Voyante') && nightActions['voyanteActed'] != true;
      case 'rat_malade_turn':
        return isRoleAlive('Rat Malade') &&
            nightActions['ratMaladeActed'] != true;
      case 'loups_turn':
        return playerData.values.any(
              (p) =>
                  (GameData.roleCamps[p['role']] == 'loups' ||
                      p['infectionStatus'] == 'infecte') &&
                  p['status'] == 'vivant',
            ) &&
            nightActions['loupsVoted'] != true;
      case 'loup_blanc_turn':
        // Nuit 0 (1ère nuit) : pas de réveil
        // Nuit 1 (2ème nuit) : réveil
        // Nuit 2 (3ème nuit) : repos
        // Nuit 3 (4ème nuit) : réveil
        return nightNumber >= 1 &&
            (nightNumber % 2 == 1) &&
            isRoleAlive('Loup Blanc') &&
            nightActions['loupBlancActed'] != true;
      case 'sorciere_turn':
        var sorciere = playerData.entries.firstWhere(
          (e) => e.value['role'] == 'Sorcière' && e.value['status'] == 'vivant',
          orElse: () => MapEntry('', {}),
        );
        if (sorciere.key.isEmpty) return false;
        return nightActions['sorciereActed'] != true;
      case 'pyromancien_turn':
        return isRoleAlive('Pyromancien') &&
            nightActions['pyromancienActed'] != true;
      default:
        return false;
    }
  }

  Future<void> startNextNightPhase(String gameCode) async {
    for (int attempt = 0; attempt < 5; attempt++) {
      try {
        await _db.runTransaction((transaction) async {
          final gameRef = _db.collection('games').doc(gameCode);
          DocumentSnapshot gameSnap = await transaction.get(gameRef);
          if (!gameSnap.exists) return;

          var gameData = gameSnap.data() as Map<String, dynamic>;
          var playerData = Map<String, dynamic>.from(gameData['playerData']);
          String currentSubPhase = gameData['subPhase'];

          int currentPhaseIndex = nightPhaseOrder.indexOf(currentSubPhase);
          // 'loups_voted' or 'loup_noir_action' are sentinels set during wolf phase; treat as loups_turn
          if (currentSubPhase == 'loups_voted' ||
              currentSubPhase == 'loup_noir_action') {
            currentPhaseIndex = nightPhaseOrder.indexOf('loups_turn');
            transaction.update(gameRef, {'nightActions.loupsVoted': true});
          }
          if (currentPhaseIndex == -1) currentPhaseIndex = -1;

          for (int i = currentPhaseIndex + 1; i < nightPhaseOrder.length; i++) {
            String nextPhase = nightPhaseOrder[i];
            if (_isPlayerForPhaseActive(nextPhase, gameData, playerData)) {
              transaction.update(gameRef, {
                'subPhase': nextPhase,
                'turnStartTime': FieldValue.serverTimestamp(),
              });
              return;
            }
          }

          await _startDayPhase(transaction, gameRef, gameData);
        });
        break; // Succès
      } catch (e) {
        if (attempt >= 4) rethrow;
        await Future.delayed(Duration(milliseconds: 150 * (attempt + 1)));
      }
    }

    final gameRef = _db.collection('games').doc(gameCode);
    final updatedGameData =
        (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedGameData);
  }

  /// Voyante : Découverte du rôle
  Future<void> voyanteSee(
    String gameCode,
    String voyanteId,
    String targetId, {
    bool isAuto = false,
  }) async {
    bool shouldAdvance = false;
    await _db.runTransaction((transaction) async {
      shouldAdvance = false;
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, voyanteId, isAuto: isAuto);

      if (gameData['subPhase'] != 'voyante_turn') return;
      if (gameData['nightActions']?['voyanteActed'] == true) return;

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[voyanteId]?['role'] != 'Voyante' ||
          playerData[voyanteId]?['status'] != 'vivant')
        return;

      String targetRole = playerData[targetId]?['role'] ?? 'Simple Villageois';
      String targetName = playerData[targetId]?['name'] ?? _l10n.inconnu;

      bool isWolf =
          GameData.roleCamps[targetRole] == 'loups' ||
          playerData[targetId]?['infectionStatus'] == 'infecte';
      int xpGained = isWolf ? 30 : 10;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        voyanteId,
        xpGained,
        applySpeedBonus: true,
      );

      if (GameData.roleCamps[targetRole] == 'loups') {
        final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
        if (currentAuthUid != null) {
          _db.collection('users').doc(currentAuthUid).set({
            'badgeProgress.lg_voyante_seen': FieldValue.increment(1),
          }, SetOptions(merge: true));
        }
      }

      transaction.update(gameRef, {
        'gameLog': FieldValue.arrayUnion([_l10n.laVoyanteASondeUne]),
        'playerData.$voyanteId.privateInfo': _l10n.leRoleDeEst(
          targetName,
          targetRole,
        ),
        'nightActions.voyanteActed': true,
      });
      shouldAdvance = true;
    });

    if (shouldAdvance) {
      await Future.delayed(Duration(seconds: 2));
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> heritierChooseTestateur(
    String gameCode,
    String heritierId,
    String testateurId, {
    bool isAuto = false,
  }) async {
    await _db.runTransaction((transaction) async {
