    if (shouldAdvance) {
      await Future.delayed(Duration(seconds: 2));
      await startNextNightPhase(gameCode);
    }
  }

  /// Loup Noir : Infection
  Future<void> loupNoirInfect(
    String gameCode,
    String loupNoirId,
    bool infectChosenTarget, {
    bool isAuto = false,
  }) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, loupNoirId, isAuto: isAuto);

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[loupNoirId]?['role'] != 'Loup Noir' ||
          playerData[loupNoirId]?['status'] != 'vivant')
        return;

      String? loupTargetId = gameData['nightActions']?['loupTarget'];
      playerData[loupNoirId]['infectionUsed'] = true;

      if (infectChosenTarget && loupTargetId != null) {
        playerData[loupTargetId]['infectionStatus'] = 'infecte';
        playerData[loupTargetId]['privateInfo'] = _l10n.vousAvezEteInfectePar;

        transaction.update(gameRef, {
          'playerData': playerData,
          'gameLog': FieldValue.arrayUnion([_l10n.leLoupNoirAUtilise]),
          'nightActions.loupTarget': null, // Annule la mort par les loups
        });
      } else {
        transaction.update(gameRef, {
          'playerData': playerData,
          'gameLog': FieldValue.arrayUnion([_l10n.leLoupNoirNA]),
        });
      }
    });

    await startNextNightPhase(gameCode);
  }

  Future<void> petiteFilleSpy(
    String gameCode,
    String spyId,
    String targetId, {
    bool isAuto = false,
  }) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, spyId, isAuto: isAuto);

      if (gameData['subPhase'] != 'loups_turn') return;

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[spyId]?['role'] != 'Petite Fille' ||
          playerData[spyId]?['status'] != 'vivant')
        return;

      bool discovered =
          Random().nextDouble() < 0.30; // 30% de chance d'être découverte

      if (discovered) {
        transaction.update(gameRef, {
          'playerData.$spyId.status': 'mort',
          'playerData.$spyId.revealedRole': 'Petite Fille',
          'nightActions.petiteFilleKilled': spyId,
          'gameLog': FieldValue.arrayUnion([_l10n.laPetiteFilleAEte]),
        });
      } else {
        String targetRole = playerData[targetId]?['role'] ?? _l10n.inconnu;
        String targetName = playerData[targetId]?['name'] ?? _l10n.inconnu;

        if (!(playerData[spyId]?['privateInfo']?.contains("infecté") ??
                false) &&
            !(playerData[spyId]?['privateInfo']?.contains("contaminé") ??
                false)) {
          playerData[spyId]['privateInfo'] = _l10n.vousAvezEspionneEtDecouvert(
            targetName,
            targetRole,
          );
        }
        if (!(playerData[targetId]?['privateInfo']?.contains("infecté") ??
                false) &&
            !(playerData[targetId]?['privateInfo']?.contains("contaminé") ??
                false)) {
          playerData[targetId]['privateInfo'] = _l10n.vousVousSentezObserveE;
        }
        transaction.update(gameRef, {'playerData': playerData});
      }
    });
  }

  /// Sorcière : Potions de vie et de mort
  Future<void> sorciereUsePotion(
    String gameCode,
    String sorciereId,
    String potionType,
    String? targetId, {
    bool isAuto = false,
  }) async {
    bool shouldAdvance = false;
    await _db.runTransaction((transaction) async {
      shouldAdvance = false;
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, sorciereId, isAuto: isAuto);

      if (gameData['subPhase'] != 'sorciere_turn') return;
      if (gameData['nightActions']?['sorciereActed'] == true) return;

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[sorciereId]?['role'] != 'Sorcière' ||
          playerData[sorciereId]?['status'] != 'vivant')
        return;

      Map<String, dynamic> updates = {'nightActions.sorciereActed': true};

      if (potionType == 'rien') {
        transaction.update(gameRef, updates);
        shouldAdvance = true;
      }
      if (potionType == 'guerison' &&
          playerData[sorciereId]['potions']?['guerison'] == true) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          sorciereId,
          25,
          applySpeedBonus: true,
        );
        if (playerData[sorciereId]['potions']?['poison'] == false) {
          // Bonus de 25 XP pour avoir utilisé les 2 potions !
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            sorciereId,
            25,
            applySpeedBonus: false,
          );
          final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.lg_sorciere_double': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }
        updates.addAll({
          'nightActions.sorciereSave': true,
          'playerData.$sorciereId.potions.guerison': false,
          'gameLog': FieldValue.arrayUnion([_l10n.laSorciereAUtiliseSa]),
        });
        transaction.update(gameRef, updates);
        shouldAdvance = true;
      } else if (potionType == 'poison' &&
          playerData[sorciereId]['potions']?['poison'] == true &&
          targetId != null) {
        bool targetIsWolf =
            GameData.roleCamps[playerData[targetId]?['role']] == 'loups' ||
            playerData[targetId]?['infectionStatus'] == 'infecte';
        int xpPoison = targetIsWolf ? 40 : 10;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          sorciereId,
          xpPoison,
          applySpeedBonus: true,
        );
        if (playerData[sorciereId]['potions']?['guerison'] == false) {
          // Bonus de 25 XP pour avoir utilisé les 2 potions !
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            sorciereId,
            25,
            applySpeedBonus: false,
          );
          final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.lg_sorciere_double': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }
        updates.addAll({
          'nightActions.sorciereKill': targetId,
          'playerData.$sorciereId.potions.poison': false,
          'gameLog': FieldValue.arrayUnion([_l10n.laSorciereAConcocteUn]),
        });
        transaction.update(gameRef, updates);
        shouldAdvance = true;
      }
    });

    if (shouldAdvance) {
      await Future.delayed(Duration(seconds: 2));
      await startNextNightPhase(gameCode);
    }
  }

  /// Pyromancien : Dépôt de tonneau sans suppression au matin
  Future<void> pyromancienAct(
    String gameCode,
    String pyromancienId,
    String actionType,
    String? targetId, {
    bool isAuto = false,
  }) async {
    bool shouldAdvance = false;
    await _db.runTransaction((transaction) async {
      shouldAdvance = false;
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, pyromancienId, isAuto: isAuto);

      if (gameData['subPhase'] != 'pyromancien_turn') return;
      if (gameData['nightActions']?['pyromancienActed'] == true) return;

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[pyromancienId]?['role'] != 'Pyromancien' ||
          playerData[pyromancienId]?['status'] != 'vivant')
        return;

      Map<String, dynamic> pyromancienBarrels = Map<String, dynamic>.from(
        gameData['pyromancienBarrels'] ?? {},
      );

      if (actionType == 'place' && targetId != null) {
        pyromancienBarrels[targetId] =
            (pyromancienBarrels[targetId] as int? ?? 0) + 1;
        transaction.update(gameRef, {
          'pyromancienBarrels': pyromancienBarrels,
          'nightActions.pyromancienActed': true,
          'gameLog': FieldValue.arrayUnion([_l10n.lePyromancienAEntreposeUn]),
        });
        shouldAdvance = true;
      } else if (actionType == 'detonate') {
        transaction.update(gameRef, {
          'nightActions.pyromancienDetonate': true,
          'nightActions.pyromancienActed': true,
          'gameLog': FieldValue.arrayUnion([_l10n.lePyromancienAllumeLaMeche]),
        });
        shouldAdvance = true;
      }
    });

    if (shouldAdvance) {
      await Future.delayed(Duration(seconds: 2));
      await startNextNightPhase(gameCode);
    }
  }

  /// Lever du jour : Résolution synchronisée des morts et des immunités
  Future<void> _startDayPhase(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    var playerData = Map<String, dynamic>.from(gameData['playerData']);
    var nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );
    List<String> deadThisNightIds = [];

    // 1. Potion de mort de la Sorcière (traverse les protections standard)
    String? sorciereTargetId = nightActions['sorciereKill'];
    if (sorciereTargetId != null && sorciereTargetId.isNotEmpty) {
      deadThisNightIds.add(sorciereTargetId);
    }

    // 2. Loup Blanc (traverse toutes les protections de villageois)
    String? loupBlancTargetId = nightActions['loupBlancKill'];
    if (loupBlancTargetId != null && loupBlancTargetId.isNotEmpty) {
      deadThisNightIds.add(loupBlancTargetId);
    }

    // 2b. Petite Fille tuée sur le champ si découverte
    String? petiteFilleKilled = nightActions['petiteFilleKilled'];
    if (petiteFilleKilled != null && petiteFilleKilled.isNotEmpty) {
      deadThisNightIds.add(petiteFilleKilled);
    }

    // 3. Attaque des Loups standard
    String? loupTargetId = nightActions['loupTarget'];
    bool loupTargetSaved = nightActions['sorciereSave'] == true;

    if (loupTargetId != null && loupTargetId.isNotEmpty && !loupTargetSaved) {
      String? protectedByGardeId = nightActions['gardeProtect'];
      String? chasseurId =
          playerData.entries
              .firstWhere(
                (e) => e.value['role'] == 'Chasseur',
                orElse: () => MapEntry('', {}),
              )
              .key;
      String? chaperonRougeId =
          playerData.entries
              .firstWhere(
                (e) => e.value['role'] == 'Chaperon Rouge',
                orElse: () => MapEntry('', {}),
              )
              .key;

      bool chasseurIsAlive =
          chasseurId.isNotEmpty &&
          playerData[chasseurId]?['status'] == 'vivant' &&
          playerData[chasseurId]?['infectionStatus'] != 'infecte' &&
          !deadThisNightIds.contains(chasseurId);
      bool chaperonIsProtected =
          (loupTargetId == chaperonRougeId && chasseurIsAlive);
      bool isGardeProtected = (loupTargetId == protectedByGardeId);

      if (isGardeProtected) {
        final gardeEntry = playerData.entries.firstWhere(
          (e) => e.value['role'] == 'Garde',
          orElse: () => MapEntry('', {}),
        );
        if (gardeEntry.key.isNotEmpty) {
          final players = Map<String, dynamic>.from(gameData['players'] ?? {});
          final gardeAuth =
              players[gardeEntry.key]?['authUid'] ?? gardeEntry.key;
          _db.collection('users').doc(gardeAuth).set({
            'unlockedBadges.lg_garde_save': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      }

      if (!isGardeProtected && !chaperonIsProtected) {
        deadThisNightIds.add(loupTargetId);
      }
    }

    // 4. Explosion des tonneaux du Pyromancien (si vivant au matin)
    bool pyromancienDetonated = nightActions['pyromancienDetonate'] == true;
    String? pyromancienId =
        playerData.entries
            .firstWhere(
              (e) => e.value['role'] == 'Pyromancien',
              orElse: () => MapEntry('', {}),
            )
            .key;

    bool pyromancienAlive =
        pyromancienId.isNotEmpty &&
        playerData[pyromancienId]?['status'] == 'vivant' &&
        !deadThisNightIds.contains(pyromancienId);

    if (pyromancienDetonated && pyromancienAlive) {
      Map<String, dynamic> barrels = Map<String, dynamic>.from(
        gameData['pyromancienBarrels'] ?? {},
      );
      int detonatedLivingCount = 0;
      barrels.forEach((tId, count) {
        if ((count as int? ?? 0) > 0 &&
            playerData[tId]?['status'] == 'vivant') {
          deadThisNightIds.add(tId);
          detonatedLivingCount++;
        }
      });
      if (detonatedLivingCount >= 3) {
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        final pyroAuth = players[pyromancienId]?['authUid'] ?? pyromancienId;
        _db.collection('users').doc(pyroAuth).set({
          'unlockedBadges.lg_pyro_detonate_3': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
      transaction.update(gameRef, {
        'pyromancienBarrels': {},
      }); // Réinitialisation uniquement après explosion
    }

    deadThisNightIds = deadThisNightIds.toSet().toList();

    // 5. Application des morts en cascade (Amoureux, Capitaine, Chasseur, Fossoyeur)
    List<String> logMessages = [_l10n.leSoleilSeLeveSur];
    List<String> deadThisNightNames = [];
    String? chasseurDiedId, captainDiedId, fossoyeurDiedId;
    List<String> processingQueue = List.from(deadThisNightIds);
    Set<String> processedDeaths = {};

    while (processingQueue.isNotEmpty) {
      String deadId = processingQueue.removeAt(0);
      if (processedDeaths.contains(deadId) ||
          playerData[deadId]?['status'] == 'mort')
        continue;

      playerData[deadId]['status'] = 'mort';
      playerData[deadId]['revealedRole'] = playerData[deadId]['role'];
      deadThisNightNames.add(playerData[deadId]['name'] ?? _l10n.inconnu);
      processedDeaths.add(deadId);

      if (playerData[deadId]['role'] == 'Chasseur' &&
          playerData[deadId]['infectionStatus'] != 'infecte') {
        chasseurDiedId = deadId;
      }
      if (deadId == gameData['captainId']) captainDiedId = deadId;
      if (playerData[deadId]['role'] == 'Fossoyeur') fossoyeurDiedId = deadId;

      List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
      if (lovers.contains(deadId)) {
        String otherLoverId = lovers.firstWhere(
          (id) => id != deadId,
          orElse: () => '',
        );
        if (otherLoverId.isNotEmpty &&
            !processedDeaths.contains(otherLoverId) &&
            playerData[otherLoverId]?['status'] == 'vivant') {
          processingQueue.add(otherLoverId);
          logMessages.add(
            _l10n.estMortEDeChagrin1(playerData[otherLoverId]['name']),
          );
        }
      }
    }

    // 6. Héritier : Récupération du testament
    String? heritierId =
        playerData.entries
            .firstWhere(
              (e) =>
                  e.value['role'] == 'Héritier' &&
                  e.value['status'] == 'vivant',
              orElse: () => MapEntry('', {}),
            )
            .key;

    if (heritierId.isNotEmpty) {
      String? testateurId = playerData[heritierId]['testateurId'];
      if (testateurId != null && processedDeaths.contains(testateurId)) {
        String newRole = playerData[testateurId]['role'];
        playerData[heritierId]['role'] = newRole;
        logMessages.add(
          _l10n.lHeritierHeriteDuRole2(
            playerData[heritierId]['name'],
            playerData[testateurId]['name'],
            newRole,
          ),
        );

        if (playerData[testateurId].containsKey('potions'))
          playerData[heritierId]['potions'] =
              playerData[testateurId]['potions'];
        if (playerData[testateurId].containsKey('infectionUsed'))
          playerData[heritierId]['infectionUsed'] =
              playerData[testateurId]['infectionUsed'];
        if (playerData[testateurId].containsKey('powerUsed'))
          playerData[heritierId]['powerUsed'] =
              playerData[testateurId]['powerUsed'];
        if (playerData[testateurId].containsKey('lastProtectedId'))
          playerData[heritierId]['lastProtectedId'] =
              playerData[testateurId]['lastProtectedId'];

        if (gameData['captainId'] == testateurId) {
          transaction.update(gameRef, {'captainId': heritierId});
          logMessages.add(
            _l10n.heriteEgalementDuStatutDe1(playerData[heritierId]['name']),
          );
          captainDiedId = null;
        }
      }
    }

    // 7. Tirage du mot du Loup Bavard
    String? loupBavardId =
        playerData.entries
            .firstWhere(
              (e) =>
                  e.value['role'] == 'Loup Bavard' &&
                  e.value['status'] == 'vivant',
              orElse: () => MapEntry('', {}),
            )
            .key;

    if (loupBavardId.isNotEmpty) {
      String newWord =
          GameData.bavardWords[Random().nextInt(GameData.bavardWords.length)];
      playerData[loupBavardId]['currentBavardWord'] = newWord;
      playerData[loupBavardId]['hasSaidBavardWord'] = false;
      playerData[loupBavardId]['privateInfo'] = _l10n.votreMotDuJourPrononcez(
        newWord,
      );
    }

    if (deadThisNightNames.isEmpty) {
      logMessages.add(_l10n.miraculeusementPersonneNAPeri);
    } else {
      logMessages.add(
        _l10n.leVillageDecouvreAvecEffroi1(
          deadThisNightNames.toSet().join(', '),
        ),
      );
    }

    playerData.forEach((pId, data) {
      if (data['privateInfo'] == null ||
          !((data['privateInfo'] as String).contains("infecté") ||
              (data['privateInfo'] as String).contains("contaminé") ||
              (data['privateInfo'] as String).contains("mot du jour"))) {
        playerData[pId]['privateInfo'] = null;
      }
    });

    final String? dictatorId =
        playerData.entries
            .firstWhere(
              (e) => e.value['role'] == 'Dictateur',
              orElse: () => MapEntry('', {}),
            )
            .key;
    final bool dictatorValid =
        dictatorId != null &&
        dictatorId.isNotEmpty &&
        playerData[dictatorId]?['status'] == 'vivant' &&
        playerData[dictatorId]?['infectionStatus'] != 'infecte';

    final bool dictatorActiveCoup =
        (gameData['dictatorTookPowerAtNight'] == true) && dictatorValid;

    transaction.update(gameRef, {
      'playerData': playerData,
      'gameLog': FieldValue.arrayUnion(logMessages),
      'nightActions': {},
      'dayVotes': {},
      'dictatorTookPowerAtNight': dictatorActiveCoup,
    });

    // File d'attente des pouvoirs de jour
    List<Map<String, dynamic>> pendingDayEffects = [];
    if (captainDiedId != null)
      pendingDayEffects.add({
        'subPhase': 'captain_designate',
        'activePlayerId': captainDiedId,
      });
    if (chasseurDiedId != null &&
        playerData[chasseurDiedId]?['infectionStatus'] != 'infecte')
      pendingDayEffects.add({
        'subPhase': 'chasseur_revenge',
        'activePlayerId': chasseurDiedId,
      });
    if (fossoyeurDiedId != null)
      pendingDayEffects.add({
        'subPhase': 'fossoyeur_reveal',
        'activePlayerId': fossoyeurDiedId,
      });
    if (dictatorActiveCoup)
      pendingDayEffects.add({
        'subPhase': 'dictateur_coup',
        'activePlayerId': dictatorId,
      });

    if (pendingDayEffects.isNotEmpty) {
      var firstEffect = pendingDayEffects.removeAt(0);
      transaction.update(gameRef, {
        'isPostVote': false,
        'phase': 'jour_discussion',
        'subPhase': firstEffect['subPhase'],
        'activePlayerId': firstEffect['activePlayerId'],
        'pendingDayEffects': pendingDayEffects,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    } else {
      transaction.update(gameRef, {
        'isPostVote': false,
        'phase': 'jour_discussion',
        'subPhase': '',
        'activePlayerId': null,
        'pendingDayEffects': [],
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    }
  }

  Future<void> fossoyeurReveal(
    String gameCode,
    String fossoyeurId,
    String targetPlayerId, {
    bool isAuto = false,
  }) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      var gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, fossoyeurId, isAuto: isAuto);

      final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
      if (currentAuthUid != null) {
        _db.collection('users').doc(currentAuthUid).set({
          'unlockedBadges.lg_fossoyeur_dig': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      String targetRole = playerData[targetPlayerId]['role'];
      String targetCamp = GameData.roleCamps[targetRole] ?? 'unknown';

      List<String> livingPlayers =
          playerData.entries
              .where(
                (e) =>
                    e.value['status'] == 'vivant' &&
                    e.key != fossoyeurId &&
                    e.key != targetPlayerId,
              )
              .map((e) => e.key)
              .toList()
            ..shuffle();

      String? otherRevealedPlayerId;
      String? otherRevealedRole;

      for (String id in livingPlayers) {
        String currentCamp =
            GameData.roleCamps[playerData[id]['role']] ?? 'unknown';
        bool isOppositeCamp =
            (targetCamp == 'loups' && currentCamp != 'loups') ||
            (targetCamp != 'loups' && currentCamp == 'loups');
        if (isOppositeCamp) {
          otherRevealedPlayerId = id;
          otherRevealedRole = playerData[id]['role'];
          break;
        }
      }

      if (otherRevealedPlayerId == null && livingPlayers.isNotEmpty) {
        otherRevealedPlayerId = livingPlayers.first;
        otherRevealedRole = playerData[otherRevealedPlayerId]['role'];
      }

      String logMessage = _l10n.leFossoyeurReveleEtaitUn1(
        playerData[fossoyeurId]['name'],
        playerData[targetPlayerId]['name'],
        targetRole,
      );
      if (otherRevealedPlayerId != null) {
        logMessage += _l10n.etEtaitUnE(
          playerData[otherRevealedPlayerId]['name'],
          otherRevealedRole ?? '',
        );
      }
      transaction.update(gameRef, {
        'gameLog': FieldValue.arrayUnion([logMessage]),
      });

      List<Map<String, dynamic>> pendingDayEffects =
          List<Map<String, dynamic>>.from(
            (gameData['pendingDayEffects'] as List<dynamic>?)?.map(
                  (e) => Map<String, dynamic>.from(e),
                ) ??
                [],
          );

      if (pendingDayEffects.isNotEmpty) {
        var nextEffect = pendingDayEffects.removeAt(0);
        transaction.update(gameRef, {
          'subPhase': nextEffect['subPhase'],
          'activePlayerId': nextEffect['activePlayerId'],
          'pendingDayEffects': pendingDayEffects,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        bool isPostVote = gameData['isPostVote'] == true;
        if (isPostVote) {
          transaction.update(gameRef, {
            'phase': 'nuit',
            'subPhase': 'initial',
            'nightNumber': FieldValue.increment(1),
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        } else {
          transaction.update(gameRef, {
            'phase': 'jour_discussion',
            'subPhase': '',
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });

    final updatedGameData =
        (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedGameData);
    if (updatedGameData['phase'] == 'nuit') {
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> triggerDictateurCoup(String gameCode, String dictateurId) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    final gameData = gameSnap.data() as Map<String, dynamic>;
    _verifyPlayerAuth(gameData, dictateurId);

    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    if (playerData[dictateurId]?['powerUsed'] == true ||
        playerData[dictateurId]?['infectionStatus'] == 'infecte' ||
        playerData[dictateurId]?['status'] != 'vivant')
      return;

    final dictateurName = playerData[dictateurId]?['name'] ?? _l10n.leDictateur;
    await gameRef.update({
      'subPhase': 'dictateur_coup',
      'activePlayerId': dictateurId,
      'dictatorTookPowerAtNight': true,
      'gameLog': FieldValue.arrayUnion([
        _l10n.declareUnCoupDEtat(dictateurName),
      ]),
    });
  }

  /// Coup d'État du Dictateur
  Future<void> dictateurCoup(
    String gameCode,
    String dictatorId,
    String targetId, {
    bool isAuto = false,
  }) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      var gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, dictatorId, isAuto: isAuto);

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      if (playerData[dictatorId]?['role'] != 'Dictateur' ||
          playerData[dictatorId]?['status'] != 'vivant' ||
          playerData[dictatorId]?['powerUsed'] == true ||
          playerData[dictatorId]?['infectionStatus'] == 'infecte')
        return;

      String targetRole = playerData[targetId]['role'];
      String targetCamp = GameData.roleCamps[targetRole] ?? 'villageois';

      playerData[dictatorId]['powerUsed'] = true;
      bool targetIsWolf =
          (targetCamp == 'loups') ||
          playerData[targetId]?['infectionStatus'] == 'infecte';
      int xpDictateur = targetIsWolf ? 50 : 10;
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        dictatorId,
        xpDictateur,
        applySpeedBonus: false,
      );

      String executedId = targetIsWolf ? targetId : dictatorId;
      List<String> deaths = [executedId];
      playerData[executedId]['status'] = 'mort';
      playerData[executedId]['revealedRole'] = playerData[executedId]['role'];

      // Amoureux mort de chagrin
      List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
      if (lovers.contains(executedId)) {
        String partnerId = lovers.firstWhere((id) => id != executedId);
        if (playerData[partnerId]?['status'] == 'vivant') {
          playerData[partnerId]['status'] = 'mort';
          playerData[partnerId]['revealedRole'] = playerData[partnerId]['role'];
          deaths.add(partnerId);
        }
      }

      String? chasseurDiedId;
      String? captainDiedId;
      String? fossoyeurDiedId;

      for (String dId in deaths) {
        if (playerData[dId]?['role'] == 'Chasseur' &&
            playerData[dId]?['infectionStatus'] != 'infecte') {
          chasseurDiedId = dId;
        }
        if (playerData[dId]?['role'] == 'Fossoyeur') fossoyeurDiedId = dId;
        if (gameData['captainId'] == dId) captainDiedId = dId;

        // Héritier
        String? heritierId =
            playerData.entries
                .firstWhere(
                  (e) =>
                      e.value['role'] == 'Héritier' &&
                      e.value['status'] == 'vivant',
                  orElse: () => MapEntry('', {}),
                )
                .key;
        if (heritierId.isNotEmpty &&
            playerData[heritierId]?['testateurId'] == dId) {
          playerData[heritierId]['role'] = playerData[dId]['role'];
          if (playerData[dId].containsKey('potions')) {
            playerData[heritierId]['potions'] = playerData[dId]['potions'];
          }
          if (playerData[dId].containsKey('infectionUsed')) {
            playerData[heritierId]['infectionUsed'] =
                playerData[dId]['infectionUsed'];
          }
          if (playerData[dId].containsKey('powerUsed')) {
            playerData[heritierId]['powerUsed'] = playerData[dId]['powerUsed'];
          }
          if (captainDiedId == dId) {
            transaction.update(gameRef, {'captainId': heritierId});
            captainDiedId = null;
          }
        }
      }

      if (targetIsWolf) {
        playerData[dictatorId]['captainId'] = dictatorId;
        transaction.update(gameRef, {
          'captainId': dictatorId,
          'gameLog': FieldValue.arrayUnion([
            _l10n.leDictateurAExecuteUn1(
              playerData[dictatorId]['name'],
              playerData[targetId]['name'],
              targetRole,
            ),
          ]),
        });
      } else {
        transaction.update(gameRef, {
          'gameLog': FieldValue.arrayUnion([_l10n.leDictateurSEstTrompe]),
        });
      }

      List<Map<String, dynamic>> pendingDayEffects =
          List<Map<String, dynamic>>.from(
            (gameData['pendingDayEffects'] as List<dynamic>?)?.map(
                  (e) => Map<String, dynamic>.from(e),
                ) ??
                [],
          );
      if (captainDiedId != null) {
        pendingDayEffects.add({
          'subPhase': 'captain_designate',
          'activePlayerId': captainDiedId,
        });
      }
      if (chasseurDiedId != null &&
          playerData[chasseurDiedId]?['infectionStatus'] != 'infecte') {
        pendingDayEffects.add({
          'subPhase': 'chasseur_revenge',
          'activePlayerId': chasseurDiedId,
        });
      }
      if (fossoyeurDiedId != null) {
        pendingDayEffects.add({
          'subPhase': 'fossoyeur_reveal',
          'activePlayerId': fossoyeurDiedId,
        });
      }

      final bool isPostVote = gameData['isPostVote'] == true;
      if (pendingDayEffects.isNotEmpty) {
        var firstEffect = pendingDayEffects.removeAt(0);
        transaction.update(gameRef, {
          'playerData': playerData,
          'dictatorUsed': true,
          'dictatorTookPowerAtNight': false,
          'isPostVote': isPostVote,
          'subPhase': firstEffect['subPhase'],
          'activePlayerId': firstEffect['activePlayerId'],
          'pendingDayEffects': pendingDayEffects,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else if (isPostVote) {
        transaction.update(gameRef, {
          'playerData': playerData,
          'dictatorUsed': true,
          'dictatorTookPowerAtNight': false,
          'isPostVote': true,
          'phase': 'nuit',
          'subPhase': 'initial',
          'nightNumber': FieldValue.increment(1),
          'nightActions': {},
          'activePlayerId': null,
          'pendingDayEffects': [],
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        transaction.update(gameRef, {
          'playerData': playerData,
          'dictatorUsed': true,
          'dictatorTookPowerAtNight': false,
          'isPostVote': false,
          'phase': 'jour_discussion',
          'subPhase': '',
          'activePlayerId': null,
          'pendingDayEffects': [],
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });

    final updatedGameData =
        (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedGameData);
    if (updatedGameData['phase'] == 'nuit') {
      await startNextNightPhase(gameCode);
    }
  }

  /// Détection du mot secret du Loup Bavard dans le chat
  Future<void> handleLoupBavardChat(
    String gameCode,
    String senderId,
    String message,
  ) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;

    if (gameData['gameType'] != 'Loup-Garou') return;
    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final senderData = playerData[senderId];

    if (senderData != null &&
        senderData['role'] == 'Loup Bavard' &&
        senderData['status'] == 'vivant') {
      final String? targetWord = senderData['currentBavardWord'];
      if (targetWord != null &&
          message.toLowerCase().contains(targetWord.toLowerCase())) {
        await gameRef.update({'playerData.$senderId.hasSaidBavardWord': true});
      }
    }
  }

  Future<void> checkLoupBavardWord(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      var gameData = gameSnap.data() as Map<String, dynamic>;
      var playerData = Map<String, dynamic>.from(gameData['playerData']);

      String? loupBavardId =
          playerData.entries
              .firstWhere(
                (e) =>
                    e.value['role'] == 'Loup Bavard' &&
                    e.value['status'] == 'vivant',
                orElse: () => MapEntry('', {}),
              )
              .key;

      if (loupBavardId.isNotEmpty &&
          (playerData[loupBavardId]['hasSaidBavardWord'] == true) &&
          playerData[loupBavardId]['status'] == 'vivant') {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          loupBavardId,
          25,
          applySpeedBonus: false,
        );
      }

      if (loupBavardId.isNotEmpty &&
          !(playerData[loupBavardId]['hasSaidBavardWord'] ?? false) &&
          !(gameData['dictatorTookPowerAtNight'] ?? false)) {
        playerData[loupBavardId]['status'] = 'mort';
        playerData[loupBavardId]['revealedRole'] =
            playerData[loupBavardId]['role'];
        await _addLog(
          gameRef,
          _l10n.leLoupBavardNA1(playerData[loupBavardId]['name']),
          transaction: transaction,
        );

        List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
        if (lovers.length == 2 && lovers.contains(loupBavardId)) {
          String otherLoverId = lovers.firstWhere(
            (lId) => lId != loupBavardId,
            orElse: () => '',
          );
          if (otherLoverId.isNotEmpty &&
              playerData[otherLoverId]?['status'] == 'vivant') {
            playerData[otherLoverId]['status'] = 'mort';
            playerData[otherLoverId]['revealedRole'] =
                playerData[otherLoverId]['role'];
            await _addLog(
              gameRef,
              _l10n.estMortEDeChagrin1(playerData[otherLoverId]['name']),
              transaction: transaction,
            );
          }
        }
        transaction.update(gameRef, {'playerData': playerData});
      }
    });
  }

  Future<void> submitDayVote(
    String gameCode,
    String voterId,
    String targetId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    final gameData = gameSnap.data() as Map<String, dynamic>;
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final voterAuthUid = players[voterId]?['authUid'] ?? voterId;
    if (currentAuthUid != voterAuthUid) {
      throw Exception(_l10n.tentativeDUsurpationDIdentite);
    }

    int speedBonus = calculateSpeedBonus(
      gameData['turnStartTime'] as Timestamp?,
      effectiveTimerSeconds: getEffectiveTurnTimer(gameData),
    );
    int totalXp = 8 + speedBonus;
    await gameRef.update({
      'dayVotes.$voterId': targetId,
      'players.$voterId.xp': FieldValue.increment(totalXp),
    });
    _db.collection('users').doc(voterAuthUid).set({
      'xp': FieldValue.increment(totalXp),
    }, SetOptions(merge: true));

    DocumentSnapshot updatedSnap = await gameRef.get();
    var updatedData = updatedSnap.data() as Map<String, dynamic>;
    var playerData = Map<String, dynamic>.from(updatedData['playerData'] ?? {});
    var dayVotes = Map<String, dynamic>.from(updatedData['dayVotes'] ?? {});

    List<String> vivantsIds =
        playerData.entries
            .where((e) => e.value['status'] == 'vivant')
            .map((e) => e.key)
            .toList();

    if (updatedData['subPhase'] != 'captain_designate' &&
        dayVotes.length == vivantsIds.length) {
      await checkLoupBavardWord(gameCode);
      await processDayVote(gameCode);
    }
  }

  /// Vote du village avec gestion du Mercenaire Jour 1
  Future<void> processDayVote(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['phase'] != 'jour_vote') return;

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      var dayVotes = Map<String, dynamic>.from(gameData['dayVotes'] ?? {});
      final String? captainId = gameData['captainId'];
      List<String> newlyDeadIds = [];

      Map<String, int> voteCounts = {};
      dayVotes.forEach((voterId, targetId) {
        if (playerData[voterId]?['status'] == 'vivant' &&
            playerData[targetId]?['status'] == 'vivant') {
          voteCounts[targetId] = (voteCounts[targetId] ?? 0) + 1;
        }
      });

      // Vote double du Capitaine (uniquement si vivant et vote sur joueur vivant)
      if (captainId != null && playerData[captainId]?['status'] == 'vivant') {
        String? captainVote = dayVotes[captainId];
        if (captainVote != null &&
            playerData[captainVote]?['status'] == 'vivant') {
          voteCounts[captainVote] = (voteCounts[captainVote] ?? 0) + 1;
        }
      }

      String? eliminatedId;
      int maxVotes = 0;
      List<String> tiedCandidates = [];
      voteCounts.forEach((pId, count) {
        if (count > maxVotes) {
          maxVotes = count;
          tiedCandidates = [pId];
        } else if (count == maxVotes) {
          tiedCandidates.add(pId);
        }
      });

      if (tiedCandidates.length == 1) {
        eliminatedId = tiedCandidates.first;
        newlyDeadIds.add(eliminatedId);

        final String? targetRole = playerData[eliminatedId]['role'];
        final bool targetIsWolf =
            GameData.roleCamps[targetRole] == 'loups' ||
            playerData[eliminatedId]['infectionStatus'] == 'infecte' ||
            targetRole == 'Loup Blanc' ||
            targetRole == 'Rat Malade';

        if (targetIsWolf) {
          for (String vId in dayVotes.keys) {
            if (dayVotes[vId] == eliminatedId) {
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                vId,
                30,
                applySpeedBonus: false,
              );
            }
          }
        }

        transaction.update(gameRef, {
          'gameLog': FieldValue.arrayUnion([
            _l10n.leVillageAVoteEt1(playerData[eliminatedId]['name']),
          ]),
        });
      } else {
        transaction.update(gameRef, {
          'gameLog': FieldValue.arrayUnion([_l10n.egaliteParfaiteLorsDuVote1]),
        });
      }

      // Règle du Mercenaire (Victoire solitaire au Jour 1)
      int nightNumber = gameData['nightNumber'] ?? 0;
      if (nightNumber <= 1 && eliminatedId != null) {
        String? mercenaireId =
            playerData.entries
                .firstWhere(
                  (e) =>
                      e.value['role'] == 'Mercenaire' &&
                      e.value['status'] == 'vivant',
                  orElse: () => MapEntry('', {}),
                )
                .key;

        if (mercenaireId.isNotEmpty &&
            playerData[mercenaireId]?['mercenaireTarget'] == eliminatedId) {
          final players = Map<String, dynamic>.from(gameData['players'] ?? {});
          final mercAuth = players[mercenaireId]?['authUid'] ?? mercenaireId;
          _db.collection('users').doc(mercAuth).set({
            'unlockedBadges.lg_mercenaire_j1': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            mercenaireId,
            60,
            applySpeedBonus: false,
          );

          transaction.update(gameRef, {
            'gameState': 'gameOver',
            'phase': 'gameOver',
            'gameWinner': mercenaireId,
            'gameLog': FieldValue.arrayUnion([
              _l10n.leMercenaireAFaitEliminer1(
                playerData[mercenaireId]['name'],
              ),
            ]),
          });
          return;
        }
      }

      // Résolution des éliminations
      String? chasseurDiedId, captainDiedId, fossoyeurDiedId;
      Set<String> processedDeaths = {};

      while (newlyDeadIds.isNotEmpty) {
        String deadId = newlyDeadIds.removeAt(0);
        if (processedDeaths.contains(deadId) ||
            playerData[deadId]?['status'] == 'mort')
          continue;

        playerData[deadId]['status'] = 'mort';
        playerData[deadId]['revealedRole'] = playerData[deadId]['role'];
        processedDeaths.add(deadId);

        if (playerData[deadId]['role'] == 'Chasseur' &&
            playerData[deadId]['infectionStatus'] != 'infecte') {
          chasseurDiedId = deadId;
        }
        if (deadId == gameData['captainId']) captainDiedId = deadId;
        if (playerData[deadId]['role'] == 'Fossoyeur') fossoyeurDiedId = deadId;

        List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
        if (lovers.contains(deadId)) {
          String otherLoverId = lovers.firstWhere(
            (id) => id != deadId,
            orElse: () => '',
          );
          if (otherLoverId.isNotEmpty &&
              !processedDeaths.contains(otherLoverId) &&
              playerData[otherLoverId]?['status'] == 'vivant') {
            newlyDeadIds.add(otherLoverId);
            transaction.update(gameRef, {
              'gameLog': FieldValue.arrayUnion([
                _l10n.meurtDeChagrinPourSon1(playerData[otherLoverId]['name']),
              ]),
            });
          }
        }
      }

      String? heritierId =
          playerData.entries
              .firstWhere(
                (e) =>
                    e.value['role'] == 'Héritier' &&
                    e.value['status'] == 'vivant',
                orElse: () => MapEntry('', {}),
              )
              .key;
      if (heritierId.isNotEmpty) {
        String? testateurId = playerData[heritierId]['testateurId'];
        if (testateurId != null && processedDeaths.contains(testateurId)) {
          final players = Map<String, dynamic>.from(gameData['players'] ?? {});
          final heritierAuth = players[heritierId]?['authUid'] ?? heritierId;
          _db.collection('users').doc(heritierAuth).set({
            'unlockedBadges.lg_heritier_role': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

          String newRole = playerData[testateurId]['role'];
          playerData[heritierId]['role'] = newRole;
          transaction.update(gameRef, {
            'gameLog': FieldValue.arrayUnion([
              _l10n.lHeritierHeriteDuRole2(
                playerData[heritierId]['name'],
                playerData[testateurId]['name'],
                newRole,
              ),
            ]),
          });

          if (playerData[testateurId].containsKey('potions'))
            playerData[heritierId]['potions'] =
                playerData[testateurId]['potions'];
          if (playerData[testateurId].containsKey('infectionUsed'))
            playerData[heritierId]['infectionUsed'] =
                playerData[testateurId]['infectionUsed'];
          if (playerData[testateurId].containsKey('powerUsed'))
            playerData[heritierId]['powerUsed'] =
                playerData[testateurId]['powerUsed'];

          if (gameData['captainId'] == testateurId) {
            transaction.update(gameRef, {'captainId': heritierId});
            transaction.update(gameRef, {
              'gameLog': FieldValue.arrayUnion([
                _l10n.heriteEgalementDuStatutDe1(
                  playerData[heritierId]['name'],
                ),
              ]),
            });
          }
        }
      }

      transaction.update(gameRef, {'playerData': playerData});

      List<Map<String, dynamic>> pendingDayEffects = [];
      if (captainDiedId != null)
        pendingDayEffects.add({
          'subPhase': 'captain_designate',
          'activePlayerId': captainDiedId,
        });
      if (chasseurDiedId != null &&
          playerData[chasseurDiedId]?['infectionStatus'] != 'infecte')
        pendingDayEffects.add({
          'subPhase': 'chasseur_revenge',
          'activePlayerId': chasseurDiedId,
        });
      if (fossoyeurDiedId != null)
        pendingDayEffects.add({
          'subPhase': 'fossoyeur_reveal',
          'activePlayerId': fossoyeurDiedId,
        });

      if (pendingDayEffects.isNotEmpty) {
        var firstEffect = pendingDayEffects.removeAt(0);
        transaction.update(gameRef, {
          'isPostVote': true,
          'phase': 'jour_discussion',
          'subPhase': firstEffect['subPhase'],
          'activePlayerId': firstEffect['activePlayerId'],
          'pendingDayEffects': pendingDayEffects,
        });
      } else {
        transaction.update(gameRef, {
          'isPostVote': true,
          'phase': 'nuit',
          'subPhase': 'initial',
          'nightNumber': FieldValue.increment(1),
          'nightActions': {},
          'pendingDayEffects': [],
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });

    final gameRef = _db.collection('games').doc(gameCode);
    final updatedData = (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedData);

    if (updatedData['phase'] == 'nuit') {
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> chasseurShoot(
    String gameCode,
    String chasseurId,
    String targetId, {
    bool isAuto = false,
  }) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, chasseurId, isAuto: isAuto);

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      String? captainDiedId;
      String? fossoyeurDiedId;

      if (playerData[chasseurId]?['role'] == 'Chasseur' &&
          playerData[chasseurId]?['infectionStatus'] != 'infecte' &&
          playerData[targetId]?['status'] == 'vivant') {
        playerData[targetId]['status'] = 'mort';
        playerData[targetId]['revealedRole'] = playerData[targetId]['role'];
        String targetName = playerData[targetId]['name'];

        bool targetIsWolf =
            GameData.roleCamps[playerData[targetId]?['role']] == 'loups' ||
            playerData[targetId]?['infectionStatus'] == 'infecte';
        int xpChasseur = targetIsWolf ? 40 : 10;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          chasseurId,
          xpChasseur,
          applySpeedBonus: false,
        );

        if (targetIsWolf) {
          final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.lg_chasseur_revenge':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }

        await _addLog(
          gameRef,
          _l10n.leChasseurTireEtTue1(targetName),
          transaction: transaction,
        );

        List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
        if (lovers.length == 2 && lovers.contains(targetId)) {
          String? otherLoverId = lovers.firstWhere(
            (lId) => lId != targetId,
            orElse: () => '',
          );
          if (otherLoverId.isNotEmpty &&
              playerData[otherLoverId]?['status'] == 'vivant') {
            playerData[otherLoverId]['status'] = 'mort';
            playerData[otherLoverId]['revealedRole'] =
                playerData[otherLoverId]['role'];
            await _addLog(
              gameRef,
              _l10n.estMortEDeChagrin1(playerData[otherLoverId]['name']),
              transaction: transaction,
            );

            if (otherLoverId == gameData['captainId'])
              captainDiedId = otherLoverId;
            if (playerData[otherLoverId]['role'] == 'Fossoyeur')
              fossoyeurDiedId = otherLoverId;
          }
        }

        if (targetId == gameData['captainId']) captainDiedId = targetId;
        if (playerData[targetId]['role'] == 'Fossoyeur')
          fossoyeurDiedId = targetId;
      }

      String? heritierIdCheck =
          playerData.entries
              .firstWhere(
                (e) =>
                    e.value['role'] == 'Héritier' &&
                    e.value['status'] == 'vivant',
                orElse: () => MapEntry('', {}),
              )
              .key;
      if (heritierIdCheck.isNotEmpty) {
        String? testateurId = playerData[heritierIdCheck]['testateurId'];
        if (testateurId != null &&
            playerData[testateurId]?['status'] == 'mort') {
          String newRole = playerData[testateurId]['role'];
          playerData[heritierIdCheck]['role'] = newRole;
          await _addLog(
            gameRef,
            _l10n.lHeritierHeriteDuRole2(
              playerData[heritierIdCheck]['name'],
              playerData[testateurId]['name'],
              newRole,
            ),
            transaction: transaction,
          );
        }
      }

      List<Map<String, dynamic>> pendingEffects =
          List<Map<String, dynamic>>.from(
            (gameData['pendingDayEffects'] as List<dynamic>?)?.map(
                  (e) => Map<String, dynamic>.from(e),
                ) ??
                [],
          );

      if (captainDiedId != null) {
        pendingEffects.add({
          'subPhase': 'captain_designate',
          'activePlayerId': captainDiedId,
        });
      }
      if (fossoyeurDiedId != null) {
        pendingEffects.add({
          'subPhase': 'fossoyeur_reveal',
          'activePlayerId': fossoyeurDiedId,
        });
      }

      if (pendingEffects.isNotEmpty) {
        var firstEffect = pendingEffects.removeAt(0);
        transaction.update(gameRef, {
          'playerData': playerData,
          if (captainDiedId != null) 'captainId': null,
          'subPhase': firstEffect['subPhase'],
          'activePlayerId': firstEffect['activePlayerId'],
          'pendingDayEffects': pendingEffects,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        bool isPostVote = gameData['isPostVote'] == true;
        if (isPostVote) {
          transaction.update(gameRef, {
            'playerData': playerData,
            'phase': 'nuit',
            'subPhase': 'initial',
            'nightNumber': FieldValue.increment(1),
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        } else {
          transaction.update(gameRef, {
            'playerData': playerData,
            'phase': 'jour_discussion',
            'subPhase': '',
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });

    final chasseurGameRef = _db.collection('games').doc(gameCode);
    final chasseurUpdatedData =
        (await chasseurGameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(chasseurGameRef, chasseurUpdatedData);
    if (chasseurUpdatedData['phase'] == 'nuit') {
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> captainDesignate(
    String gameCode,
    String formerCaptainId,
    String newCaptainId, {
    bool isAuto = false,
  }) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, formerCaptainId, isAuto: isAuto);

      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      String formerCaptainName =
          playerData[formerCaptainId]?['name'] ?? _l10n.lAncienCapitaine1;
      String newCaptainName =
          playerData[newCaptainId]?['name'] ?? _l10n.inconnu;

      if (playerData[newCaptainId]?['status'] == 'vivant') {
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        final newCaptainAuth =
            players[newCaptainId]?['authUid'] ?? newCaptainId;
        _db.collection('users').doc(newCaptainAuth).set({
          'unlockedBadges.lg_capitaine_elected': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));

        transaction.update(gameRef, {
          'captainId': newCaptainId,
          'gameLog': FieldValue.arrayUnion([
            _l10n.aDesigneCommeNouveauCapitaine(
              formerCaptainName,
              newCaptainName,
            ),
          ]),
        });
      }

      List<Map<String, dynamic>> pendingDayEffects =
          List<Map<String, dynamic>>.from(
            (gameData['pendingDayEffects'] as List<dynamic>?)?.map(
                  (e) => Map<String, dynamic>.from(e),
                ) ??
                [],
          );

      if (pendingDayEffects.isNotEmpty) {
        var nextEffect = pendingDayEffects.removeAt(0);
        transaction.update(gameRef, {
          'playerData': playerData,
          'subPhase': nextEffect['subPhase'],
          'activePlayerId': nextEffect['activePlayerId'],
          'pendingDayEffects': pendingDayEffects,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        bool isPostVote = gameData['isPostVote'] == true;
        if (isPostVote) {
          transaction.update(gameRef, {
            'playerData': playerData,
            'phase': 'nuit',
            'subPhase': 'initial',
            'nightNumber': FieldValue.increment(1),
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        } else {
          transaction.update(gameRef, {
            'playerData': playerData,
            'phase': 'jour_discussion',
            'subPhase': '',
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });

    final gameRef = _db.collection('games').doc(gameCode);
    final updatedData = (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedData);
    if (updatedData['phase'] == 'nuit') {
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> selectCupidonLover(
    String gameCode,
    String cupidonId,
    String targetId, {
    bool isAuto = false,
  }) async {
    bool shouldAdvance = false;
    await _db.runTransaction((transaction) async {
      shouldAdvance = false;
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, cupidonId, isAuto: isAuto);

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      if (playerData[cupidonId]?['role'] != 'Cupidon' ||
          playerData[cupidonId]?['status'] != 'vivant')
        return;

      if ((gameData['nightNumber'] ?? 0) != 0) return;
      if (gameData['nightActions']?['cupidonActed'] == true) return;

      List<String> currentLovers = List<String>.from(gameData['lovers'] ?? []);

      if (currentLovers.length >= 2 || currentLovers.contains(targetId)) return;

      currentLovers.add(targetId);
      if (currentLovers.length == 2) {
        String lover1Name =
            playerData[currentLovers[0]]?['name'] ?? _l10n.amoureux1;
        String lover2Name =
            playerData[currentLovers[1]]?['name'] ?? _l10n.amoureux2;
        transaction.update(gameRef, {
          'lovers': currentLovers,
          'nightActions.cupidonActed': true,
          'playerData.${currentLovers[0]}.privateInfo': _l10n
              .vousEtesAmoureuxDe(lover2Name),
          'playerData.${currentLovers[1]}.privateInfo': _l10n
              .vousEtesAmoureuxDe1(lover1Name),
          'gameLog': FieldValue.arrayUnion([
            _l10n.cupidonADesigneEtComme(lover1Name, lover2Name),
          ]),
        });
        shouldAdvance = true;
      } else {
        transaction.update(gameRef, {'lovers': currentLovers});
      }
    });
    if (shouldAdvance) {
      await startNextNightPhase(gameCode);
    }
  }

  Future<void> resetLoupGarouGame(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;
    Map<String, dynamic> players = gameData['players'];

    Map<String, dynamic> resetPlayers = {};
    players.forEach((id, data) {
      resetPlayers[id] = {'name': data['name'], 'score': 0};
    });

    await _startGameLoupGarou(
      gameRef,
      resetPlayers,
      resetPlayers.keys.toList()..shuffle(),
    );
  }

  Future<void> _advancePendingDayEffects(DocumentReference gameRef) async {
    await _db.runTransaction((transaction) async {
      DocumentSnapshot snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      var gameData = snap.data() as Map<String, dynamic>;
      List<Map<String, dynamic>> pendingDayEffects =
          List<Map<String, dynamic>>.from(
            (gameData['pendingDayEffects'] as List<dynamic>?)?.map(
                  (e) => Map<String, dynamic>.from(e),
                ) ??
                [],
          );
      if (pendingDayEffects.isNotEmpty) {
        var nextEffect = pendingDayEffects.removeAt(0);
        transaction.update(gameRef, {
          'subPhase': nextEffect['subPhase'],
          'activePlayerId': nextEffect['activePlayerId'],
          'pendingDayEffects': pendingDayEffects,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        bool isPostVote = gameData['isPostVote'] == true;
        if (isPostVote) {
          transaction.update(gameRef, {
            'isPostVote': true,
            'phase': 'nuit',
            'subPhase': 'initial',
            'nightNumber': FieldValue.increment(1),
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        } else {
          transaction.update(gameRef, {
            'phase': 'jour_discussion',
            'subPhase': '',
            'activePlayerId': null,
            'pendingDayEffects': [],
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });
  }

  Future<void> handleLoupGarouTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final String phase = gameData['phase'] ?? '';
    final String subPhase = gameData['subPhase'] ?? '';
    final String? activePlayerId = gameData['activePlayerId'];
    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final livingPlayers =
        playerData.entries
            .where((e) => e.value['status'] == 'vivant')
            .map((e) => e.key)
            .toList();

    String? findAliveRolePlayer(String roleName) {
      final entry = playerData.entries.firstWhere(
        (e) => e.value['role'] == roleName && e.value['status'] == 'vivant',
        orElse: () => MapEntry('', {}),
      );
      return entry.key.isNotEmpty ? entry.key : null;
    }

    // 1. Sous-phases de pouvoirs prioritaires
    if (subPhase == 'captain_designate' && activePlayerId != null) {
      final candidates =
          livingPlayers.where((id) => id != activePlayerId).toList();
      if (candidates.isNotEmpty) {
        candidates.shuffle();
        await captainDesignate(
          gameCode,
          activePlayerId,
          candidates.first,
          isAuto: true,
        );
      } else {
        await _advancePendingDayEffects(gameRef);
      }
      return;
    }

    if (subPhase == 'chasseur_revenge' && activePlayerId != null) {
      final targets =
          livingPlayers.where((id) => id != activePlayerId).toList();
      if (targets.isNotEmpty) {
        targets.shuffle();
        await chasseurShoot(
          gameCode,
          activePlayerId,
          targets.first,
          isAuto: true,
        );
      } else {
        await _advancePendingDayEffects(gameRef);
      }
      return;
    }

    if (subPhase == 'fossoyeur_reveal' && activePlayerId != null) {
      final targets =
          livingPlayers.where((id) => id != activePlayerId).toList();
      if (targets.isNotEmpty) {
        targets.shuffle();
        await fossoyeurReveal(
          gameCode,
          activePlayerId,
          targets.first,
          isAuto: true,
        );
      } else {
        await _advancePendingDayEffects(gameRef);
      }
      return;
    }

    if (subPhase == 'dictateur_coup') {
      final dictatorId = activePlayerId ?? findAliveRolePlayer('Dictateur');
      final targets = livingPlayers.where((id) => id != dictatorId).toList();
      if (dictatorId != null && targets.isNotEmpty) {
        targets.shuffle();
        await dictateurCoup(gameCode, dictatorId, targets.first, isAuto: true);
      } else {
        await gameRef.update({'dictatorTookPowerAtNight': false});
        await _advancePendingDayEffects(gameRef);
      }
      return;
    }

    // 2. Nuit
    if (phase == 'nuit') {
      if (subPhase == 'loup_noir_action') {
        final loupNoirId = findAliveRolePlayer('Loup Noir');
        if (loupNoirId != null) {
          await loupNoirInfect(gameCode, loupNoirId, false, isAuto: true);
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'loups_turn') {
        final wolfVotes = Map<String, dynamic>.from(
          (gameData['nightActions'] as Map?)?['votes'] ?? {},
        );
        final wolves =
            livingPlayers
                .where(
                  (id) =>
                      GameData.roleCamps[playerData[id]?['role']] == 'loups' ||
                      playerData[id]?['infectionStatus'] == 'infecte',
                )
                .toList();
        final nonWolves =
            livingPlayers.where((id) => !wolves.contains(id)).toList();

        if (nonWolves.isNotEmpty && wolves.isNotEmpty) {
          nonWolves.shuffle();
          final defaultTarget = nonWolves.first;
          bool anyVoted = false;
          for (var wolfId in wolves) {
            if (!wolfVotes.containsKey(wolfId)) {
              anyVoted = true;
              await loupGarouVote(
                gameCode,
                wolfId,
                defaultTarget,
                isAuto: true,
              );
            }
          }
          if (!anyVoted) {
            await startNextNightPhase(gameCode);
          }
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'voyante_turn') {
        final voyanteId = activePlayerId ?? findAliveRolePlayer('Voyante');
        final targets = livingPlayers.where((id) => id != voyanteId).toList();
        if (voyanteId != null && targets.isNotEmpty) {
          targets.shuffle();
          await voyanteSee(gameCode, voyanteId, targets.first, isAuto: true);
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'heritier_turn') {
        final heritierId = activePlayerId ?? findAliveRolePlayer('Héritier');
        final targets = livingPlayers.where((id) => id != heritierId).toList();
        if (heritierId != null && targets.isNotEmpty) {
          targets.shuffle();
          await heritierChooseTestateur(
            gameCode,
            heritierId,
            targets.first,
            isAuto: true,
          );
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'garde_turn') {
        final gardeId = activePlayerId ?? findAliveRolePlayer('Garde');
        final gardeMap = gardeId != null ? playerData[gardeId] as Map? : null;
        final lastProtected = gardeMap?['lastProtectedId'];
        final targets =
            livingPlayers.where((id) => id != lastProtected).toList();
        if (gardeId != null && targets.isNotEmpty) {
          targets.shuffle();
          await gardeProtect(gameCode, gardeId, targets.first, isAuto: true);
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'sorciere_turn') {
        final sorciereId = activePlayerId ?? findAliveRolePlayer('Sorcière');
        if (sorciereId != null) {
          final loupTarget = (gameData['nightActions'] as Map?)?['loupTarget'];
          final hasHeal =
              playerData[sorciereId]?['potions']?['guerison'] == true;
          if (hasHeal && loupTarget == sorciereId) {
            await sorciereUsePotion(
              gameCode,
              sorciereId,
              'guerison',
              null,
              isAuto: true,
            );
          } else {
            await sorciereUsePotion(
              gameCode,
              sorciereId,
              'rien',
              null,
              isAuto: true,
            );
          }
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'pyromancien_turn') {
        final pyroId = activePlayerId ?? findAliveRolePlayer('Pyromancien');
        final barrels = Map<String, dynamic>.from(
          gameData['pyromancienBarrels'] ?? {},
        );
        final barreledLiving =
            livingPlayers.where((id) => (barrels[id] as int? ?? 0) > 0).length;
        final targets =
            livingPlayers
                .where((id) => id != pyroId && (barrels[id] as int? ?? 0) == 0)
                .toList();
        if (pyroId != null) {
          if (barreledLiving >= 2 || targets.isEmpty) {
            await pyromancienAct(
              gameCode,
              pyroId,
              'detonate',
              null,
              isAuto: true,
            );
          } else {
            targets.shuffle();
            await pyromancienAct(
              gameCode,
              pyroId,
              'place',
              targets.first,
              isAuto: true,
            );
          }
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'cupidon_turn') {
        final cupidonId = activePlayerId ?? findAliveRolePlayer('Cupidon');
        final currentLovers = List<String>.from(gameData['lovers'] ?? []);
        final candidates =
            livingPlayers.where((id) => !currentLovers.contains(id)).toList()
              ..shuffle();
        if (cupidonId != null &&
            candidates.length >= (2 - currentLovers.length)) {
          while (currentLovers.length < 2 && candidates.isNotEmpty) {
            final picked = candidates.removeAt(0);
            currentLovers.add(picked);
            await selectCupidonLover(gameCode, cupidonId, picked, isAuto: true);
          }
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'rat_malade_turn') {
        final ratId = activePlayerId ?? findAliveRolePlayer('Rat Malade');
        final targets =
            livingPlayers
                .where(
                  (id) => id != ratId && playerData[id]?['poisoned'] != true,
                )
                .toList();
        if (ratId != null && targets.isNotEmpty) {
          targets.shuffle();
          await ratMaladeContaminate(
            gameCode,
            ratId,
            targets.take(2).toList(),
            isAuto: true,
          );
        } else {
          await startNextNightPhase(gameCode);
        }
        return;
      }

      if (subPhase == 'loup_blanc_turn') {
        await startNextNightPhase(gameCode);
        return;
      }

      await startNextNightPhase(gameCode);
      return;
    }

    // 3. Jour - Discussion
    if (phase == 'jour_discussion') {
      await startDayVotePhase(gameCode);
      return;
    }

    // 4. Jour - Vote
    if (phase == 'jour_vote') {
      final dayVotes = Map<String, dynamic>.from(gameData['dayVotes'] ?? {});
      for (final voterId in livingPlayers) {
        if (!dayVotes.containsKey(voterId) &&
            _isPlayerIdBot(gameData, voterId)) {
          final candidates =
              livingPlayers.where((id) => id != voterId).toList();
          if (candidates.isNotEmpty) {
            candidates.shuffle();
            dayVotes[voterId] = candidates.first;
          }
        }
      }
      await gameRef.update({'dayVotes': dayVotes});
      await checkLoupBavardWord(gameCode);
      await processDayVote(gameCode);
      return;
    }
  }

  Future<void> createGameWithAllPlayers({
    required String gameCode,
    required String hostId,
    required Map<String, dynamic> allPlayers,
    required String gameType,
    required String difficulty,
    int? playerCount,
    bool isPremiumLobby = false, // NOUVEAU PARAMÈTRE
    bool videoEnabled = false, // NOUVEAU PARAMÈTRE
    bool audioEnabled = false, // NOUVEAU PARAMÈTRE
    bool devineTeteUseTeams = false,
    List<String>? aiWords, // Pre-generated AI words
    String? cadavreVariant,
    String? cadavrePassingMode,

    String? scope,
    bool dobbleSymbolsPerCard = false,
    bool isSimplifiedLiar = false,
    String liarVoteMode = 'simultaneous',
    String quiPourraitVoteMode = 'grouper',
    List<String>? selectedCategoriesList,
    List<String>? petitBacCategories,
    int? petitBacTime,
    bool presidentRevolution = false,
    bool pictionaryOnly30Strokes = false,
    bool? pictionaryUseTeams,
    bool justOneAllowInvalidClues = false,
    Map<String, int>? selectedLoupGarouRoles,
    int? unoStartingCards,
    bool? unoStackDraws,
    int? zeroPointeTargetScore,
    int? pokerStartChips,
    int? pokerSmallBlind,
    int? pokerBigBlind,
    bool? hotPotatoUseGlobalTimer,
    int? hotPotatoGlobalDuration,
    String? gribouillisMode,
    bool? gribouillisAjouter1,
    int? photoRouletteRounds,
    int? photoRoulettePhotosPerPlayer,
    int? photoRouletteTime,
    String? photoRouletteMediaType,
    Map<String, bool>? undercoverRoleSettings,
    int? infiltreCount,
    int? mrWhiteCount,
    int? undercoverClueTime,
    bool? useTimer,
    int? turnTimerSeconds,
    int? resultTimerSeconds,
    String? aiInstructions,
    int? timesUpTotalRounds,
    String? dominoesMode,
    int? dominoesTargetScore,
    bool? petitsChevauxTeamMode,
    bool? aoVPlayersDecide,
    int? aoVVoteThreshold,
    int? aoVMaxRounds,
    bool isRanked = false,
  }) async {
    final String? currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    Map<String, dynamic> enrichedPlayers = {};
    allPlayers.forEach((pId, pData) {
      if (pData is Map) {
        Map<String, dynamic> pMap = Map<String, dynamic>.from(pData);
        pMap['livekitIdentity'] = pMap['livekitIdentity'] ?? pId;
        if (!pMap.containsKey('authUid') || pMap['authUid'] == null) {
          if (pId == hostId &&
              currentAuthUid != null &&
              currentAuthUid.isNotEmpty) {
            pMap['authUid'] = currentAuthUid;
          } else {
            pMap['authUid'] = pId;
          }
        }
        pMap['isReady'] = pMap['isReady'] ?? (pId == hostId);
        pMap['isOnline'] = true;
        pMap['lastHeartbeat'] = FieldValue.serverTimestamp();
        enrichedPlayers[pId] = pMap;
      } else {
        enrichedPlayers[pId] = {
          'name': pData.toString(),
          'score': 0,
          'xp': 0,
          'livekitIdentity': pId,
          'isReady': pId == hostId,
          'isOnline': true,
          'lastHeartbeat': FieldValue.serverTimestamp(),
          'authUid':
              (pId == hostId &&
                      currentAuthUid != null &&
                      currentAuthUid.isNotEmpty)
                  ? currentAuthUid
                  : pId,
        };
      }
    });

    await _db.collection('games').doc(gameCode).set({
      'hostId': hostId,
      'players': enrichedPlayers,
      'gameType': gameType,
      'isRanked': isRanked,
      'enableFloatingChat': true,
      if (gameType == 'Action ou Vérité') ...{
        'aoVPlayersDecide': aoVPlayersDecide ?? false,
        'aoVVoteThreshold': aoVVoteThreshold ?? 100,
        'aoVMaxRounds': aoVMaxRounds ?? 10,
      },
      if (gameType == 'Blanc Manger Coco') ...{'bmcTargetScore': 10},
      if (gameType == 'Devine Tête') 'devineTeteUseTeams': devineTeteUseTeams,
      'difficulty': difficulty,
      'gameState': 'lobby',
      'isPremiumLobby': isPremiumLobby, // NOUVEAU CHAMP
      'videoEnabled': videoEnabled, // NOUVEAU CHAMP
      'audioEnabled': audioEnabled, // NOUVEAU CHAMP
      'useTimer': useTimer ?? true,
      'turnTimerSeconds': turnTimerSeconds ?? 30,
      'resultTimerSeconds': resultTimerSeconds ?? 15,
      if (aiInstructions != null && aiInstructions.isNotEmpty)
        'aiInstructions': aiInstructions,
      if (aiWords != null && aiWords.isNotEmpty) 'aiWords': aiWords,

      'createdAt': FieldValue.serverTimestamp(),
      'currentRound': 0,
      'roundState': 'waitingForStart',
      'playerCount': playerCount,
