  Future<bool> joinGame(
    String gameCode,
    String playerName,
    String playerId,
  ) async {
    final cleanCode = gameCode.trim();
    final cleanName = playerName.trim().isEmpty ? 'Joueur' : playerName.trim();
    final DocumentReference gameRef = _db.collection('games').doc(cleanCode);

    try {
      return await _db.runTransaction<bool>((transaction) async {
        final DocumentSnapshot gameSnap = await transaction.get(gameRef);

        if (!gameSnap.exists) {
          debugPrint("[joinGame] La partie n'existe pas : $cleanCode");
          return false;
        }

        final data = gameSnap.data() as Map<String, dynamic>? ?? {};
        final String gameState = data['gameState'] ?? '';

        if (gameState != 'lobby') {
          debugPrint("[joinGame] La partie n'est pas en lobby : $gameState");
          return false;
        }

        final Map<String, dynamic> players =
            Map<String, dynamic>.from(data['players'] ?? {});
        final List<String> playerOrder =
            List<String>.from(data['playerOrder'] ?? []);
        final User? currentUser = FirebaseAuth.instance.currentUser;
        final String authUid = currentUser?.uid ?? playerId;

        // Écriture complète avec tous les champs requis pour l'affichage immédiat
        players[playerId] = {
          'name': cleanName,
          'score': 0,
          'xp': 0,
          'authUid': authUid,
          'livekitIdentity': playerId,
          'isReady': false,
          'isOnline': true,
          'lastHeartbeat': FieldValue.serverTimestamp(),
        };

        if (!playerOrder.contains(playerId)) {
          playerOrder.add(playerId);
        }

        final Map<String, dynamic> updates = {
          'players': players,
          'playerOrder': playerOrder,
          'players.$playerId.isOnline': true,
          'players.$playerId.name': cleanName,
        };

        if (data['gameType'] == 'Petit Bac') {
          updates['petitBacTotalScores.$playerId'] = 0;
        }

        transaction.update(gameRef, updates);
        return true;
      });
    } catch (e) {
      debugPrint("--- ERREUR CRITIQUE DANS joinGame : $e ---");
      return false;
    }
  }

  Stream<DocumentSnapshot> getGameStream(String gameCode) {
    return _db.collection('games').doc(gameCode).snapshots();
  }

  Future<void> _startUndercoverGame(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();
    final int playerCount = playerIds.length;
    final roleSettings = Map<String, bool>.from(
      gameData['undercoverRoleSettings'] ?? {},
    );
    final difficulty = gameData['difficulty'] ?? 'soft';

    List<String> wordPairs;
    if (gameData['aiWords'] != null &&
        (gameData['aiWords'] as List).isNotEmpty) {
      wordPairs = List<String>.from(gameData['aiWords']);
    } else {
      wordPairs =
          GameWords.undercoverData[difficulty]?['wordPairs'] ??
          GameWords.undercoverData['soft']!['wordPairs']!;
    }
    final rawPair = wordPairs[Random().nextInt(wordPairs.length)];
    String wordCivil;
    String wordUndercover;

    if (rawPair.contains(':')) {
      final parts = rawPair.split(':');
      wordCivil = parts[0].trim();
      wordUndercover = parts[1].trim();
    } else {
      // Sécurité anti-doublon : si l'IA renvoie des mots simples séparés
      int idx = wordPairs.indexOf(rawPair);
      wordCivil = rawPair.trim();
      wordUndercover =
          (idx + 1 < wordPairs.length)
              ? wordPairs[idx + 1].trim()
              : _l10n.variante1(rawPair.trim());
    }

    final roleCounts = Map<String, int>.from(
      gameData['undercoverRoleCounts'] ?? {},
    );
    int desiredInfiltres = roleCounts['infiltres'] ?? 1;
    int desiredMrWhites = roleCounts['mrWhites'] ?? 1;

    int totalImpostors = desiredInfiltres + desiredMrWhites;

    if (totalImpostors == 0) desiredInfiltres = 1;
    totalImpostors = desiredInfiltres + desiredMrWhites;
    int maxAllowedImpostors = (playerCount / 2).floor();
    if (maxAllowedImpostors < 1) maxAllowedImpostors = 1;
    if (totalImpostors >= maxAllowedImpostors) {
      totalImpostors = maxAllowedImpostors > 1 ? maxAllowedImpostors - 1 : 1;
      desiredMrWhites = min(desiredMrWhites, totalImpostors);
      desiredInfiltres = max(1, totalImpostors - desiredMrWhites);
    }

    List<String> baseRolesToAssign = [];
    for (int i = 0; i < desiredInfiltres; i++)
      baseRolesToAssign.add('Infiltré');
    for (int i = 0; i < desiredMrWhites; i++)
      baseRolesToAssign.add('Mr. White');
    while (baseRolesToAssign.length < playerCount)
      baseRolesToAssign.add('Civil');
    baseRolesToAssign.shuffle();

    List<String> specialRolesPool = [];
    roleSettings.forEach((role, isEnabled) {
      if (isEnabled) {
        if (role == 'Amoureux' && playerCount < 5) return;
        if (role == 'Vendeur de Falafels' && playerCount < 4) return;
        if (role == 'Vengeuse' && playerCount < 5) return;
        if (role == 'Duellistes' && playerCount < 5) return;
        specialRolesPool.add(role);
      }
    });
    specialRolesPool.shuffle();

    Map<String, dynamic> publicPlayerData = {};
    Map<String, Map<String, dynamic>> privatePlayerData = {};

    for (int i = 0; i < playerCount; i++) {
      String pId = playerIds[i];
      String baseRole = baseRolesToAssign[i];
      String secretWord =
          (baseRole == 'Infiltré')
              ? wordUndercover
              : (baseRole == 'Mr. White' || baseRole == 'Vendeur de Falafels')
              ? _l10n.vousNAvezPasDe
              : wordCivil;
      if (baseRole == 'Vendeur de Falafels') baseRole = 'Civil';

      publicPlayerData[pId] = {
        'name': players[pId]['name'],
        'status': 'active',
        'canVote': true,
      };

      privatePlayerData[pId] = {
        'role': baseRole,
        'secretWord': secretWord,
        'specialAbilities': <String>[],
      };
    }

    if (specialRolesPool.isNotEmpty) {
      List<String> playersForSpecialRoles = List.from(playerIds)..shuffle();
      for (int i = 0; i < specialRolesPool.length; i++) {
        String specialRole = specialRolesPool[i];
        String playerToReceiveRoleId = playersForSpecialRoles[i % playerCount];
        (privatePlayerData[playerToReceiveRoleId]!['specialAbilities']
                as List<String>)
            .add(specialRole);
      }
    }

    Map<String, dynamic> specialRolesData = {};
    List<String> tempPlayers = List.from(playerIds)..shuffle();

    if (privatePlayerData.values.any(
          (p) => (p['specialAbilities'] as List).contains('Amoureux'),
        ) &&
        tempPlayers.length >= 2) {
      String amoreuxId =
          privatePlayerData.entries
              .firstWhere(
                (e) =>
                    (e.value['specialAbilities'] as List).contains('Amoureux'),
              )
              .key;
      tempPlayers.remove(amoreuxId);
      String partnerId = tempPlayers.removeAt(0);
      (privatePlayerData[partnerId]!['specialAbilities'] as List<String>).add(
        'Amoureux',
      );
      specialRolesData['lovers'] = [amoreuxId, partnerId];
      String amoureux1Name = players[amoreuxId]['name'];
      String amoureux2Name = players[partnerId]['name'];
      privatePlayerData[amoreuxId]!['privateInfo'] = _l10n.votreAmoureuxSe(
        amoureux2Name,
      );
      privatePlayerData[partnerId]!['privateInfo'] = _l10n.votreAmoureuxSe1(
        amoureux1Name,
      );
    }
    if (privatePlayerData.values.any(
          (p) => (p['specialAbilities'] as List).contains('Duellistes'),
        ) &&
        tempPlayers.length >= 1) {
      String duellist1Id =
          privatePlayerData.entries
              .firstWhere(
                (e) => (e.value['specialAbilities'] as List).contains(
                  'Duellistes',
                ),
              )
              .key;
      tempPlayers.remove(duellist1Id);
      if (tempPlayers.isNotEmpty) {
        String duellist2Id = tempPlayers.removeAt(0);
        (privatePlayerData[duellist2Id]!['specialAbilities'] as List<String>)
            .add('Duellistes');
        specialRolesData['duellists'] = [duellist1Id, duellist2Id];
      }
    }
    if (privatePlayerData.values.any(
      (p) => (p['specialAbilities'] as List).contains('Déesse de la Justice'),
    )) {
      specialRolesData['justiceGoddess'] =
          privatePlayerData.entries
              .firstWhere(
                (e) => (e.value['specialAbilities'] as List).contains(
                  'Déesse de la Justice',
                ),
              )
              .key;
    }
    if (privatePlayerData.values.any(
      (p) => (p['specialAbilities'] as List).contains('Mr. Meme'),
    )) {
      specialRolesData['mrMemePlayerId'] =
          privatePlayerData.entries
              .firstWhere(
                (e) =>
                    (e.value['specialAbilities'] as List).contains('Mr. Meme'),
              )
              .key;
    }
    if (privatePlayerData.values.any(
      (p) => (p['specialAbilities'] as List).contains('Fou de Joie'),
    )) {
      specialRolesData['fouDeJoie'] =
          privatePlayerData.entries
              .firstWhere(
                (e) => (e.value['specialAbilities'] as List).contains(
                  'Fou de Joie',
                ),
              )
              .key;
    }

    // Écriture des données privées sécurisées et synchronisation des capacités
    for (String pId in playerIds) {
      final abilities = List<String>.from(
        privatePlayerData[pId]!['specialAbilities'] ?? [],
      );
      if (abilities.contains('Vendeur de Falafels')) {
        privatePlayerData[pId]!['secretWord'] = _l10n.vousNAvezPasDe;
      }
      publicPlayerData[pId]['role'] = privatePlayerData[pId]!['role'];
      publicPlayerData[pId]['specialAbilities'] = abilities;
      publicPlayerData[pId]['revealedAbilities'] = <String>[];
      await gameRef
          .collection('private_data')
          .doc(pId)
          .set(privatePlayerData[pId]!);
    }

    await gameRef.update({
      'gameState': 'playing',
      'currentPhase': 'clue_giving',
      'playerData': publicPlayerData,
      'playerOrder': playerIds,
      'specialRoles': specialRolesData,
      'currentPlayerIndex': 0,
      'playerClues': {},
      'votes': {},
      'eliminatedOrder': [],
      'turnLog': [_l10n.logClueGivingStart],
      'turnStartTime': FieldValue.serverTimestamp(),
      'inactiveTurnCounts': {for (var pId in playerIds) pId: 0},
    });
  }

  Future<void> submitUndercoverClue(
    String gameCode,
    String playerId,
    String clue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['currentPhase'] != 'clue_giving') return;

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;

      if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length)
        return;
      if (playerOrder[currentPlayerIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }
      if ((gameData['playerClues'] as Map?)?.containsKey(playerId) ?? false)
        return;
      final Map<String, dynamic> playerData = gameData['playerData'] ?? {};
      final cleanClue = sanitizeUserInput(clue.split(' ').first, maxLength: 30);

      int findNextActivePlayer(int currentIndex) {
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        int checked = 0;
        while (playerData[playerOrder[nextIndex]]?['status'] != 'active') {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          checked++;
          if (checked >= playerOrder.length) return -1;
        }
        return nextIndex;
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8,
        applySpeedBonus: true,
      );

      Map<String, dynamic> updates = {
        'playerClues.$playerId': cleanClue,
        'turnLog': FieldValue.arrayUnion([
          _l10n.aDit(playerData[playerId]?['name'] ?? _l10n.joueur, cleanClue),
        ]),
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      int nextIndex = findNextActivePlayer(currentPlayerIndex);

      Map<String, dynamic> playerClues = Map<String, dynamic>.from(
        gameData['playerClues'] ?? {},
      );
      playerClues[playerId] = cleanClue;
      int activePlayerCount =
          playerData.values.where((p) => p['status'] == 'active').length;
      bool allCluesGiven =
          activePlayerCount > 0 && playerClues.length >= activePlayerCount;

      if (nextIndex == -1 || allCluesGiven) {
        updates['currentPhase'] = 'voting';
        updates['votes'] = {};
        updates['turnLog'] = FieldValue.arrayUnion([
          _l10n.laPhaseDeVoteCommence,
        ]);
      } else {
        updates['currentPlayerIndex'] = nextIndex;
      }
      transaction.update(gameRef, updates);
    });
  }

  Future<void> startUndercoverVoting(String gameCode) async {
    await _db.collection('games').doc(gameCode).update({
      'currentPhase': 'voting',
      'votes': {},
      'turnLog': FieldValue.arrayUnion([_l10n.laPhaseDeVoteA]),
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  // --- DERNIÈRE CHANCE DE MR. WHITE (RÈGLE OFFICIELLE) ---
  Future<void> submitMrWhiteGuess(
    String gameCode,
    String playerId,
    String guessedWord,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    final gameData = gameSnap.data() as Map<String, dynamic>;

    _verifyPlayerAuth(gameData, playerId);

    final privateSnap =
        await gameRef.collection('private_data').doc(playerId).get();
    final pData = privateSnap.data() ?? {};

    if (pData['role'] != 'Mr. White') {
      throw Exception(_l10n.seulMrWhitePeutDeviner);
    }
    // Récupérer le mot civil depuis un joueur civil
    final allPrivate = await gameRef.collection('private_data').get();
    String civilWord = "";
    for (var doc in allPrivate.docs) {
      if (doc.data()['role'] == 'Civil') {
        civilWord = doc.data()['secretWord'] ?? "";
        break;
      }
    }

    bool mrWhiteWins =
        civilWord.isNotEmpty &&
        guessedWord.trim().toLowerCase() == civilWord.trim().toLowerCase();

    if (mrWhiteWins) {
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final pAuth = players[playerId]?['authUid'] ?? playerId;
      _db.collection('users').doc(pAuth).set({
        'xp': FieldValue.increment(65),
      }, SetOptions(merge: true));
      await gameRef.update({
        'players.$playerId.xp': FieldValue.increment(65),
        'turnLog': FieldValue.arrayUnion([
          _l10n.aDevineLeMotCivil1(
            gameData['playerData']?[playerId]?['name'] ?? 'Mr. White',
            civilWord,
          ),
        ]),
        'eliminatedThisTurn': [],
      });
      await _endUndercoverGameAndAssignScores(gameRef, 'Mr. White');
    } else {
      await gameRef.update({
        'turnLog': FieldValue.arrayUnion([
          _l10n.aProposeMaisCeN(
            gameData['playerData']?[playerId]?['name'] ?? 'Mr. White',
            guessedWord,
            civilWord,
          ),
        ]),
      });
      await processEliminationsAndCheckWin(gameCode);
    }
  }

  Future<void> undercoverGoddessDecision(
    String gameCode,
    String eliminatedId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid != null) {
      _db.collection('users').doc(currentAuthUid).set({
        'unlockedBadges.underc_justice_vote': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }

    final gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      final playerData = Map<String, dynamic>.from(gameData['playerData']);
      String? goddessId = gameData['specialRoles']?['justiceGoddess'];

      if (goddessId != null && playerData[goddessId] != null) {
        final revealed = List<String>.from(
          playerData[goddessId]['revealedAbilities'] ?? [],
        );
        if (!revealed.contains('Déesse de la Justice')) {
          revealed.add('Déesse de la Justice');
        }
        playerData[goddessId]['revealedAbilities'] = revealed;
      }

      transaction.update(gameRef, {
        'currentPhase': 'turn_result',
        'eliminatedThisTurn': [eliminatedId],
        'playerData': playerData,
        'turnLog': FieldValue.arrayUnion([_l10n.laDeesseDeLaJustice]),
      });
    });
  }

  Future<void> processEliminationsAndCheckWin(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      var playerData = Map<String, dynamic>.from(gameData['playerData']);
      List<String> toEliminateQueue = List<String>.from(
        gameData['eliminatedThisTurn'] ?? [],
      );
      Set<String> processedEliminations = {};

      while (toEliminateQueue.isNotEmpty) {
        String pId = toEliminateQueue.removeAt(0);
        if (playerData[pId]?['status'] == 'active') {
          playerData[pId]['status'] = 'eliminated';
          processedEliminations.add(pId);

          // --- NOUVEAU : Récompense XP pour avoir démasqué un imposteur ---
          String role = playerData[pId]['role'] ?? 'Civil';
          if (role == 'Infiltré' || role == 'Mr. White') {
            final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
            votes.forEach((voterId, votedForId) {
              if (votedForId == pId) {
                // +20 XP pour les civils perspicaces !
                creditPlayerXp(
                  transaction,
                  gameRef,
                  gameData,
                  voterId,
                  20,
                  applySpeedBonus: false,
                );
              }
            });
          }
          // ----------------------------------------------------------------

          bool isGhost =
              (playerData[pId]['specialAbilities'] as List<dynamic>?)?.contains(
                'Fantôme',
              ) ??
              false;
          if (!isGhost) {
            playerData[pId]['canVote'] = false;
          } else {
            final players = Map<String, dynamic>.from(
              gameData['players'] ?? {},
            );
            final ghostAuth = players[pId]?['authUid'] ?? pId;
            _db.collection('users').doc(ghostAuth).set({
              'unlockedBadges.underc_fantome_vote':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }

          bool isBoomerang =
              (playerData[pId]['specialAbilities'] as List<dynamic>?)?.contains(
                'Boomerang',
              ) ??
              false;
          if (isBoomerang) {
            // AJOUT DE L'XP BOOMERANG
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              40,
              applySpeedBonus: false,
            );
            final players = Map<String, dynamic>.from(
              gameData['players'] ?? {},
            );
            final boomAuth = players[pId]?['authUid'] ?? pId;
            _db.collection('users').doc(boomAuth).set({
              'unlockedBadges.underc_boomerang': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }

          List<String> lovers = List<String>.from(
            gameData['specialRoles']?['lovers'] ?? [],
          );
          if (lovers.contains(pId)) {
            String otherLover = lovers.firstWhere(
              (id) => id != pId,
              orElse: () => '',
            );
            if (otherLover.isNotEmpty &&
                playerData[otherLover]?['status'] == 'active') {
              toEliminateQueue.add(otherLover);
            }
          }
        }
      }

      String? vengeuseId =
          (playerData.entries.firstWhere(
            (e) =>
                (e.value['specialAbilities'] as List<dynamic>?)?.contains(
                  'Vengeuse',
                ) ??
                false,
            orElse: () => MapEntry('', {}),
          )).key;
      if (vengeuseId.isNotEmpty && processedEliminations.contains(vengeuseId)) {
        transaction.update(gameRef, {
          'playerData': playerData,
          'eliminatedOrder': FieldValue.arrayUnion(
            processedEliminations.toList(),
          ),
          'currentPhase': 'avenger_revenge',
        });
        return;
      }

      transaction.update(gameRef, {
        'playerData': playerData,
        'eliminatedOrder': FieldValue.arrayUnion(
          processedEliminations.toList(),
        ),
      });
    });

    bool gameOver = await _checkUndercoverWinCondition(gameRef);
    if (!gameOver) {
      // Trouver le premier joueur actif pour commencer le nouveau tour
      DocumentSnapshot latestSnap = await gameRef.get();
      var latestData = latestSnap.data() as Map<String, dynamic>;
      var playerData = Map<String, dynamic>.from(latestData['playerData']);
      List<String> playerOrder = List<String>.from(
        latestData['playerOrder'] ?? [],
      );
      int firstActiveIndex = 0;
      for (int i = 0; i < playerOrder.length; i++) {
        if (playerData[playerOrder[i]]?['status'] == 'active') {
          firstActiveIndex = i;
          break;
        }
      }
      await gameRef.update({
        'currentPhase': 'clue_giving',
        'currentPlayerIndex': firstActiveIndex,
        'votes': {},
        'playerClues': {},
        'turnLog': FieldValue.arrayUnion([_l10n.unNouveauTourCommence]),
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    }
  }

  Future<void> undercoverAvengerDecision(
    String gameCode,
    String avengerId,
    String targetId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid != null) {
      _db.collection('users').doc(currentAuthUid).set({
        'unlockedBadges.underc_vengeuse_kill': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }

    final gameRef = _db.collection('games').doc(gameCode);
    var gameData = (await gameRef.get()).data() as Map<String, dynamic>;
    var eliminatedThisTurn = List<String>.from(
      gameData['eliminatedThisTurn'] ?? [],
    );
    eliminatedThisTurn.add(targetId);

    final avengerAuth =
        gameData['players']?[avengerId]?['authUid'] ?? avengerId;
    _db.collection('users').doc(avengerAuth).set({
      'xp': FieldValue.increment(35),
    }, SetOptions(merge: true));

    await gameRef.update({
      'players.$avengerId.xp': FieldValue.increment(35),
      'eliminatedThisTurn': eliminatedThisTurn,
      'turnLog': FieldValue.arrayUnion([_l10n.laVengeuseEmporteQuelquUn]),
      'currentPhase': 'turn_result',
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<bool> _checkUndercoverWinCondition(DocumentReference gameRef) async {
    var gameData = (await gameRef.get()).data() as Map<String, dynamic>;
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final privateSnaps = await gameRef.collection('private_data').get();
    Map<String, Map<String, dynamic>> privateMap = {};
    for (var doc in privateSnaps.docs) {
      privateMap[doc.id] = doc.data();
    }

    int activeCivilians = 0;
    int activeImpostors = 0;

    playerData.forEach((pId, data) {
      if (data['status'] == 'active') {
        final pPrivate = privateMap[pId] ?? {};
        String role = pPrivate['role'] ?? data['role'] ?? 'Civil';
        final specialAbilities =
            (pPrivate['specialAbilities'] as List?) ??
            (data['specialAbilities'] as List?);
        if (role == 'Infiltré' ||
            role == 'Mr. White' ||
            specialAbilities?.contains('Vendeur de Falafels') == true) {
          activeImpostors++;
        } else {
          activeCivilians++;
        }
      }
    });

    String? winnerFaction;
    if (activeImpostors == 0) {
      winnerFaction = 'Civils';
    } else if (activeImpostors >= activeCivilians) {
      winnerFaction = 'Imposteurs';
    }

    if (winnerFaction != null) {
      await _endUndercoverGameAndAssignScores(gameRef, winnerFaction);
      return true;
    }
    return false;
  }

  Future<void> _endUndercoverGameAndAssignScores(
    DocumentReference gameRef,
    String winnerFaction,
  ) async {
    var gameData = (await gameRef.get()).data() as Map<String, dynamic>;
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final privateSnaps = await gameRef.collection('private_data').get();
    Map<String, Map<String, dynamic>> privateMap = {};
    for (var doc in privateSnaps.docs) {
      privateMap[doc.id] = doc.data();
    }

    Map<String, int> pointsGained = {};

    playerData.forEach((pId, data) {
      final pPrivate = privateMap[pId] ?? {};
      String role = pPrivate['role'] ?? data['role'] ?? 'Civil';
      final specialAbilities =
          (pPrivate['specialAbilities'] as List?) ??
          (data['specialAbilities'] as List?);
      bool hasFalafel =
          specialAbilities?.contains('Vendeur de Falafels') == true;
      bool isImpostorTeam =
          role == 'Infiltré' || role == 'Mr. White' || hasFalafel;

      if (winnerFaction == 'Mr. White') {
        if (role == 'Mr. White') pointsGained[pId] = 10;
      } else if (winnerFaction == 'Imposteurs' && isImpostorTeam) {
        if (role == 'Infiltré')
          pointsGained[pId] = 10;
        else if (role == 'Mr. White')
          pointsGained[pId] = 6;
        else if (hasFalafel)
          pointsGained[pId] = 8;
      } else if (winnerFaction == 'Civils' && !isImpostorTeam) {
        pointsGained[pId] = 2;
      }
    });

    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    if (winnerFaction == 'Mr. White') {
      final mwEntry =
          playerData.entries
              .where(
                (e) =>
                    (privateMap[e.key]?['role'] ?? e.value['role']) ==
                    'Mr. White',
              )
              .firstOrNull;
      if (mwEntry != null) {
        final mw = mwEntry.key;
        _db.collection('users').doc(players[mw]?['authUid'] ?? mw).set({
          'unlockedBadges.underc_mrwhite_guess': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
    } else if (winnerFaction == 'Imposteurs') {
      playerData.forEach((pId, p) {
        final pPrivate = privateMap[pId] ?? {};
        final role = pPrivate['role'] ?? p['role'] ?? 'Civil';
        final abilities =
            (pPrivate['specialAbilities'] as List?) ??
            (p['specialAbilities'] as List?);
        if (role == 'Infiltré') {
          _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
            'unlockedBadges.underc_infiltre_win': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
        if (abilities?.contains('Vendeur de Falafels') == true) {
          _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
            'unlockedBadges.underc_falafel_bluff': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      });
    } else if (winnerFaction == 'Civils') {
      playerData.forEach((pId, p) {
        final pPrivate = privateMap[pId] ?? {};
        final role = pPrivate['role'] ?? p['role'] ?? 'Civil';
        if (role == 'Civil') {
          _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
            'badgeProgress.underc_civil_win_streak': FieldValue.increment(1),
          }, SetOptions(merge: true));
        }
      });
    }

    List<String> eliminatedOrder = List<String>.from(
      gameData['eliminatedOrder'] ?? [],
    );
    if (eliminatedOrder.isNotEmpty) {
      String firstEliminatedId = eliminatedOrder.first;
      final firstPrivate = privateMap[firstEliminatedId] ?? {};
      final abilities =
          (firstPrivate['specialAbilities'] as List<dynamic>?) ??
          (playerData[firstEliminatedId]?['specialAbilities']
              as List<dynamic>?);
      bool isFouDeJoie =
          (abilities?.contains('Fou de Joie') ?? false) ||
          (gameData['specialRoles']?['fouDeJoie'] == firstEliminatedId);
      if (isFouDeJoie) {
        pointsGained[firstEliminatedId] =
            (pointsGained[firstEliminatedId] ?? 0) + 4;
        final fAuth =
            players[firstEliminatedId]?['authUid'] ?? firstEliminatedId;
        _db.collection('users').doc(fAuth).set({
          'unlockedBadges.underc_fou_de_joie': FieldValue.serverTimestamp(),
          'xp': FieldValue.increment(35),
        }, SetOptions(merge: true));
      }
    }

    final duellists = List<String>.from(
      gameData['specialRoles']?['duellists'] ?? [],
    );
    if (duellists.length == 2) {
      final d1Alive = playerData[duellists[0]]?['status'] == 'active';
      final d2Alive = playerData[duellists[1]]?['status'] == 'active';
      if (d1Alive && !d2Alive) {
        _db
            .collection('users')
            .doc(players[duellists[0]]?['authUid'] ?? duellists[0])
            .set({
              'unlockedBadges.underc_duelliste_win':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
      } else if (d2Alive && !d1Alive) {
        _db
            .collection('users')
            .doc(players[duellists[1]]?['authUid'] ?? duellists[1])
            .set({
              'unlockedBadges.underc_duelliste_win':
                  FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
      }
    }

    Map<String, dynamic> votes = Map<String, dynamic>.from(
      gameData['votes'] ?? {},
    );
    Map<String, dynamic> scoreUpdates = {};
    pointsGained.forEach((pId, points) {
      if (points != 0) {
        scoreUpdates['players.$pId.score'] = FieldValue.increment(points);
      }
      final pPrivate = privateMap[pId] ?? {};
      String role = pPrivate['role'] ?? playerData[pId]?['role'] ?? 'Civil';

      int winXp = (winnerFaction == 'Civils') ? 25 : 35;

      // Si un infiltré gagne sans avoir reçu aucun vote contre lui
      int votesReceived = 0;
      votes.forEach((_, votedFor) {
        if (votedFor == pId) votesReceived++;
      });
      if (role == 'Infiltré' &&
          winnerFaction == 'Imposteurs' &&
          votesReceived == 0) {
        winXp = 50; // Bonus Taupe Parfaite
      } else if (role == 'Mr. White' && winnerFaction == 'Mr. White') {
        winXp = 45;
      }

      scoreUpdates['players.$pId.xp'] = FieldValue.increment(winXp);
      final pAuth = (players[pId]?['authUid']) ?? pId;
      _db.collection('users').doc(pAuth).set({
        'xp': FieldValue.increment(winXp),
      }, SetOptions(merge: true));
    });

    await gameRef.update({
      'gameState': 'gameOver',
      'winnerFaction': winnerFaction,
      'pointsGained': pointsGained,
      ...scoreUpdates,
    });
  }

  // --- LOGIQUE TABOO ---
  Future<void> _startTabooTurn(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final tabooTeams = Map<String, dynamic>.from(gameData['tabooTeams'] ?? {});
    final int currentTeamIndex = gameData['tabooCurrentTeamIndex'] ?? 0;
    final List<String> teamIds = tabooTeams.keys.toList();
    final String currentTeamId = teamIds[currentTeamIndex];
    final List<String> currentTeamPlayers = List<String>.from(
      tabooTeams[currentTeamId] ?? [],
    );

    // Choisir un donneur d'indice aléatoire dans l'équipe actuelle
    final String clueGiverId =
        currentTeamPlayers[Random().nextInt(currentTeamPlayers.length)];

    // Choisir un mot et ses interdits
    String word = "Paris";
    List<String> forbidden = [
      "France",
      "Capitale",
      _l10n.tourEiffel,
      "Seine",
      "Ville",
    ];

    if (gameData['aiWords'] != null &&
        (gameData['aiWords'] as List).isNotEmpty) {
      final List<String> aiDeck = List<String>.from(gameData['aiWords']);
      final rawCard = aiDeck[Random().nextInt(aiDeck.length)];
      if (rawCard.contains(':')) {
        final parts = rawCard.split(':');
        word = parts[0].trim();
        forbidden = parts[1].split(',').map((e) => e.trim()).toList();
      } else {
        word = rawCard.trim();
        forbidden = [];
      }
    } else {
      final String difficulty = gameData['difficulty'] ?? 'soft';
      final tabooWords =
          GameWords.tabooWordsData[difficulty] ??
          GameWords.tabooWordsData['soft']!;
      final allWords = tabooWords.keys.toList();
      word = allWords[Random().nextInt(allWords.length)];
      forbidden = tabooWords[word] ?? [];
    }

    await gameRef.update({
      'tabooCurrentTeamId': currentTeamId,
      'tabooClueGiverId': clueGiverId,
      'tabooCurrentWord': word,
      'tabooForbiddenWords': forbidden,
      'turnStartTime': FieldValue.serverTimestamp(),
      'turnTimerSeconds': 60, // 60 secondes par tour
      'tabooTurnActive': true,
      'gameLog': FieldValue.arrayUnion([
        _l10n.cEstAuTourDe4(currentTeamIndex + 1),
      ]),
    });
  }

  Future<void> tabooAction(
    String gameCode,
    String playerId,
    String action, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (gameData['tabooTurnActive'] != true) return;
      if (_isTurnTimedOut(gameData, customDuration: 60)) return;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      final currentTeamId = gameData['tabooCurrentTeamId'];
      final tabooTeams = Map<String, dynamic>.from(
        gameData['tabooTeams'] ?? {},
      );
      String? actorTeamId;
      tabooTeams.forEach((tId, members) {
        if ((members as List).contains(playerId)) actorTeamId = tId;
      });

      final scores = Map<String, int>.from(gameData['tabooScores'] ?? {});
      final updates = <String, dynamic>{};
      String nextWord = "Paris";
      List<String> nextForbidden = [
        "France",
        "Capitale",
        _l10n.tourEiffel,
        "Seine",
        "Ville",
      ];

      if (gameData['aiWords'] != null &&
          (gameData['aiWords'] as List).isNotEmpty) {
        final List<String> aiDeck = List<String>.from(gameData['aiWords']);
        final rawCard = aiDeck[Random().nextInt(aiDeck.length)];
        if (rawCard.contains(':')) {
          final parts = rawCard.split(':');
          nextWord = parts[0].trim();
          nextForbidden = parts[1].split(',').map((e) => e.trim()).toList();
        } else {
          nextWord = rawCard.trim();
          nextForbidden = [];
        }
      } else {
        final String difficulty = gameData['difficulty'] ?? 'soft';
        final dict =
            GameWords.tabooWordsData[difficulty] ??
            GameWords.tabooWordsData['soft']!;
        final words = dict.keys.toList();
        nextWord = words[Random().nextInt(words.length)];
        nextForbidden = dict[nextWord] ?? [];
      }

      if (action == 'buzz') {
        // Sécurité : Seule l'équipe adverse peut buzzer
        if (actorTeamId == currentTeamId) {
          throw Exception(_l10n.vousNePouvezPasBuzzer);
        }
        scores[currentTeamId] = max(0, (scores[currentTeamId] ?? 0) - 1);
        if (!isAuto) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            12,
            applySpeedBonus: true,
          );
        }
        updates['tabooScores'] = scores;
        updates['tabooCurrentWord'] = nextWord;
        updates['tabooForbiddenWords'] = nextForbidden;

        if (!isAuto && currentAuthUid != null) {
          _db.collection('users').doc(currentAuthUid).set({
            'badgeProgress.taboo_buzz_master': FieldValue.increment(1),
          }, SetOptions(merge: true));
        }
      } else if (action == 'correct') {
        // Sécurité : Seule l'équipe active valide
        if (actorTeamId != currentTeamId) {
          throw Exception(_l10n.seuleLEquipeActivePeut);
        }
        scores[currentTeamId] = (scores[currentTeamId] ?? 0) + 1;
        if (!isAuto) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            15,
            applySpeedBonus: true,
          );
        }
        updates['tabooScores'] = scores;
        updates['tabooCurrentWord'] = nextWord;
        updates['tabooForbiddenWords'] = nextForbidden;

        if (!isAuto && currentAuthUid != null) {
          _db.collection('users').doc(currentAuthUid).set({
            'badgeProgress.taboo_no_buzz': FieldValue.increment(1),
          }, SetOptions(merge: true));

          final teamScore = scores[currentTeamId] ?? 0;
          if (teamScore >= 10) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.taboo_speed_10': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }
      } else if (action == 'skip') {
        if (actorTeamId != currentTeamId) {
          throw Exception(_l10n.seuleLEquipeActivePeut1);
        }
        updates['tabooCurrentWord'] = nextWord;
        updates['tabooForbiddenWords'] = nextForbidden;
      }

      transaction.update(gameRef, updates);
    });
  }

  // =========================================================================
  // 25. TABOO
  // =========================================================================
  Future<void> handleTabooTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;

    if (gameData['tabooTurnActive'] == true) {
      final String currentTeamId = gameData['tabooCurrentTeamId'];
      final tabooTeams = Map<String, dynamic>.from(
        gameData['tabooTeams'] ?? {},
      );
      final List<String> teamIds = tabooTeams.keys.toList();
      final scores = Map<String, int>.from(gameData['tabooScores'] ?? {});
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final clueGiverId =
          gameData['tabooClueGiverId'] ?? gameData['currentPlayerId'];

      if ((scores[currentTeamId] ?? 0) >= 4 && clueGiverId != null) {
        final giverAuth = players[clueGiverId]?['authUid'] ?? clueGiverId;
        _db.collection('users').doc(giverAuth).set({
          'unlockedBadges.taboo_flawless': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }

      int nextTeamIndex = (teamIds.indexOf(currentTeamId) + 1) % teamIds.length;
      int currentRoundNum =
          (gameData['tabooRoundNumber'] as num?)?.toInt() ?? 1;
      int totalRounds = (gameData['tabooTotalRounds'] as num?)?.toInt() ?? 4;

      if (nextTeamIndex == 0) {
        currentRoundNum++;
      }

      if (currentRoundNum > totalRounds) {
        String winnerTeam =
            (scores['team_0'] ?? 0) >= (scores['team_1'] ?? 0)
                ? 'team_0'
                : 'team_1';
        String winnerName =
            winnerTeam == 'team_0' ? _l10n.equipe12 : _l10n.equipe21;
        Map<String, dynamic> scoreUpdates = {};
        if (tabooTeams[winnerTeam] is List) {
          for (var pId in (tabooTeams[winnerTeam] as List)) {
            scoreUpdates['players.$pId.score'] = FieldValue.increment(1);
          }
        }
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': winnerTeam,
          'gameEndReason': _l10n.finDesManchesVictoireDe(winnerName),
          ...scoreUpdates,
        });
        return;
      }

      await gameRef.update({
        'tabooTurnActive': false,
        'tabooCurrentTeamIndex': nextTeamIndex,
        'tabooRoundNumber': currentRoundNum,
        'gameLog': FieldValue.arrayUnion([_l10n.tempsEcoulePassageAL]),
      });

      gameData['tabooCurrentTeamIndex'] = nextTeamIndex;
      gameData['tabooRoundNumber'] = currentRoundNum;
      await _startTabooTurn(gameRef, gameData);
    }
  }

  Future<void> startBatailleNavale(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    Map<String, dynamic> playerData = {};

    for (var pId in players.keys) {
      playerData[pId] = {
        'name': players[pId]['name'],
        'myGrid': List.filled(100, 0), // 0 = eau, >0 = ID du navire
        'enemyGrid': List.filled(100, 'unknown'), // unknown, miss, hit, sunk
        'shipsPlaced': {},
        'shipsSunk': 0,
      };
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'placement',
      'playerData': playerData,
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> placeShipBatailleNavale(
    String gameCode,
    String playerId,
    String shipType,
    int startIndex,
    bool isHorizontal,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'placement') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      var myData = Map<String, dynamic>.from(playerData[playerId] ?? {});
      var myGrid = List<int>.from(myData['myGrid'] ?? List.filled(100, 0));
      var shipsPlaced = Map<String, dynamic>.from(myData['shipsPlaced'] ?? {});

      var shipInfo = GameData.batailleNavaleShips[shipType];
      if (shipInfo == null) {
        throw Exception(_l10n.typeDeNavireInvalideOu);
      }
      if (shipsPlaced.containsKey(shipType)) {
        throw Exception(_l10n.ceNavireADejaEte);
      }

      int length = shipInfo['length'];
      int width = shipInfo['width'];
      int area = shipInfo['area'];

      int actualCols = isHorizontal ? length : width;
      int actualRows = isHorizontal ? width : length;

      int startRow = startIndex ~/ 10;
      int startCol = startIndex % 10;

      // Vérification des limites
      if (startRow + actualRows > 10 || startCol + actualCols > 10) {
        throw Exception(_l10n.leNavireDepasseDeLa);
      }

      List<int> indices = [];
      for (int r = 0; r < actualRows; r++) {
        for (int c = 0; c < actualCols; c++) {
          int idx = (startRow + r) * 10 + (startCol + c);
          if (myGrid[idx] != 0) {
            throw Exception(_l10n.emplacementDejaOccupeParUn);
          }
          indices.add(idx);
        }
      }

      // ID déterministe basé sur l'index de la liste des bateaux
      int shipId =
          GameData.batailleNavaleShips.keys.toList().indexOf(shipType) + 1;

      for (int idx in indices) {
        myGrid[idx] = shipId;
      }
      shipsPlaced[shipType] = {
        'id': shipId,
        'area': area,
        'startIndex': startIndex,
        'isHorizontal': isHorizontal,
        'hits': 0,
        'sunk': false,
      };

      myData['myGrid'] = myGrid;
      myData['shipsPlaced'] = shipsPlaced;
      playerData[playerId] = myData;

      transaction.update(gameRef, {'playerData': playerData});
    });
  }

  Future<void> removeShipBatailleNavale(
    String gameCode,
    String playerId,
    String shipType,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'placement') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      var myData = Map<String, dynamic>.from(playerData[playerId] ?? {});
      var myGrid = List<int>.from(myData['myGrid'] ?? List.filled(100, 0));
      var shipsPlaced = Map<String, dynamic>.from(myData['shipsPlaced'] ?? {});

      if (!shipsPlaced.containsKey(shipType)) return;

      int shipId = shipsPlaced[shipType]['id'];
      for (int i = 0; i < myGrid.length; i++) {
        if (myGrid[i] == shipId) myGrid[i] = 0;
      }

      shipsPlaced.remove(shipType);

      myData['myGrid'] = myGrid;
      myData['shipsPlaced'] = shipsPlaced;
      myData['isReady'] = false;
      playerData[playerId] = myData;

      transaction.update(gameRef, {'playerData': playerData});
    });
  }

