  Future<void> randomizeShipsBatailleNavale(
    String gameCode,
    String playerId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'placement') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      var myData = Map<String, dynamic>.from(playerData[playerId] ?? {});

      List<int> grid = List.filled(100, 0);
      Map<String, dynamic> shipsPlaced = {};
      Random rand = Random();

      for (var entry in GameData.batailleNavaleShips.entries) {
        String shipType = entry.key;
        int shipId =
            GameData.batailleNavaleShips.keys.toList().indexOf(shipType) + 1;
        int length = entry.value['length'];
        int width = entry.value['width'];
        int area = entry.value['area'];
        bool placed = false;

        while (!placed) {
          bool isHorizontal = rand.nextBool();
          int startRow = rand.nextInt(10);
          int startCol = rand.nextInt(10);
          int actualCols = isHorizontal ? length : width;
          int actualRows = isHorizontal ? width : length;

          if (startRow + actualRows > 10 || startCol + actualCols > 10)
            continue;

          bool valid = true;
          List<int> indices = [];
          for (int r = 0; r < actualRows; r++) {
            for (int c = 0; c < actualCols; c++) {
              int idx = (startRow + r) * 10 + (startCol + c);
              if (grid[idx] != 0) {
                valid = false;
                break;
              }
              indices.add(idx);
            }
            if (!valid) break;
          }

          if (valid) {
            for (int idx in indices) grid[idx] = shipId;
            shipsPlaced[shipType] = {
              'id': shipId,
              'area': area,
              'startIndex': startRow * 10 + startCol,
              'isHorizontal': isHorizontal,
              'hits': 0,
              'sunk': false,
            };
            placed = true;
          }
        }
      }

      myData['myGrid'] = grid;
      myData['shipsPlaced'] = shipsPlaced;
      playerData[playerId] = myData;

      transaction.update(gameRef, {'playerData': playerData});
    });
  }

  Future<void> setPlayerReadyBatailleNavale(
    String gameCode,
    String playerId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'placement') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      var myData = Map<String, dynamic>.from(playerData[playerId] ?? {});
      var shipsPlaced = Map<String, dynamic>.from(myData['shipsPlaced'] ?? {});

      if (shipsPlaced.length != GameData.batailleNavaleShips.length) {
        throw Exception(_l10n.veuillezPlacerTousVosNavires);
      }

      myData['isReady'] = true;
      playerData[playerId] = myData;

      bool allReady = playerData.values.every((p) => p['isReady'] == true);

      Map<String, dynamic> updates = {'playerData': playerData};
      if (allReady) {
        List<String> playerIds = playerData.keys.toList();
        String firstPlayer = playerIds[Random().nextInt(playerIds.length)];
        updates.addAll({
          'roundState': 'playing',
          'currentPlayerId': firstPlayer,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.tousLesJoueursSontPrets1(
              playerData[firstPlayer]?['name'] ?? _l10n.joueur,
            ),
          ]),
        });
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> _startRamiRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerIds = players.keys.toList()..shuffle();
    final int handSize = playerIds.length == 2 ? 10 : 7;

    List<String> deck = GameData.generateRamiDeck(playerIds.length);
    Map<String, List<String>> hands = {};
    Map<String, List<dynamic>> melds = {};
    Map<String, int> totalScores = Map<String, int>.from(
      gameData['ramiTotalScores'] ?? {},
    );

    for (var pId in playerIds) {
      hands[pId] = [];
      for (int i = 0; i < handSize && deck.isNotEmpty; i++) {
        hands[pId]!.add(deck.removeAt(0));
      }
      melds[pId] = [];
      totalScores[pId] = totalScores[pId] ?? 0;
    }

    List<String> discard = [];
    if (deck.isNotEmpty) {
      discard.add(deck.removeAt(0));
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'playerOrder': playerIds,
      'ramiCurrentPlayerId': playerIds.first,
      'ramiPlayerHands': hands,
      'ramiMelds': melds,
      'ramiStock': deck,
      'ramiDiscard': discard,
      'ramiTotalScores': totalScores,
      'ramiRoundOver': false,
      'ramiHasDrawn': false,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': FieldValue.arrayUnion([
        _l10n.laMancheDeRamiCommence1(
          players[playerIds.first]?['name'] ?? _l10n.joueur,
        ),
      ]),
    });
  }

  Future<void> ramiAction(
    String gameCode,
    String playerId,
    String action, {
    List<String>? cards,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing' ||
          gameData['ramiRoundOver'] == true)
        return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto) {
        final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
        if (currentAuthUid != voterAuthUid) {
          throw Exception(_l10n.actionNonAutorisee);
        }
      }

      if (gameData['ramiCurrentPlayerId'] != playerId) return;

      Map<String, dynamic> playerHands = Map.from(gameData['ramiPlayerHands']);
      List<String> myHand = List.from(playerHands[playerId]);
      List<String> stock = List.from(gameData['ramiStock']);
      List<String> discard = List.from(gameData['ramiDiscard']);
      Map<String, dynamic> melds = Map.from(gameData['ramiMelds']);
      List<dynamic> myMelds = List.from(melds[playerId]);
      bool hasDrawn = gameData['ramiHasDrawn'] ?? false;

      if (action == 'draw_stock' || action == 'draw_discard') {
        if (hasDrawn) throw Exception(_l10n.vousAvezDejaPioche);
        if (action == 'draw_stock') {
          if (stock.isEmpty) {
            if (discard.length > 1) {
              String topDiscard = discard.removeLast();
              stock.addAll(discard..shuffle());
              discard = [topDiscard];
            } else {
              // Fin de manche immédiate : pioche et défausse épuisées
              Map<String, dynamic> totalScores = Map<String, dynamic>.from(
                gameData['ramiTotalScores'] ?? {},
              );
              playerHands.forEach((pId, pHand) {
                int penalty = (pHand as List).fold(0, (sum, c) {
                  if (c == null) return sum;
                  String str = c.toString().trim();
                  if (str.toUpperCase().contains('JOKER')) return sum + 20;
                  String base = str.split('_')[0].trim();
                  if (base.length < 2) return sum;
                  String rank = base.substring(0, base.length - 1);
                  return sum + (GameData.ramiCardValues[rank] ?? 5);
                });
                totalScores[pId] = (totalScores[pId] ?? 0) + penalty;
              });

              int targetScore = gameData['ramiTargetScore'] ?? 100;
              bool gameOver = totalScores.values.any(
                (score) => score >= targetScore,
              );

              transaction.update(gameRef, {
                'ramiPlayerHands': playerHands,
                'ramiStock': stock,
                'ramiDiscard': discard,
                'ramiTotalScores': totalScores,
                'ramiRoundOver': true,
                'roundState': 'round_end',
                'gameLog': FieldValue.arrayUnion([
                  _l10n.piocheEtDefausseEpuiseesFin,
                ]),
                if (gameOver) ...{
                  'gameState': 'gameOver',
                  'gameWinner':
                      totalScores.entries
                          .reduce((a, b) => a.value < b.value ? a : b)
                          .key,
                  'players.${totalScores.entries.reduce((a, b) => a.value < b.value ? a : b).key}.score':
                      FieldValue.increment(1),
                  'gameEndReason': _l10n.scoreCibleAtteint,
                },
              });
              return;
            }
          }
          myHand.add(stock.removeAt(0));
        } else {
          if (discard.isEmpty) throw Exception(_l10n.defausseVide);
          myHand.add(discard.removeLast());
        }
        playerHands[playerId] = myHand;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          2,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiStock': stock,
          'ramiDiscard': discard,
          'ramiHasDrawn': true,
        });
        return;
      }

      if (!hasDrawn) throw Exception(_l10n.vousDevezDAbordPiocher);

      if (action == 'meld') {
        if (cards == null || cards.length < 3) {
          throw Exception(_l10n.ilFautAuMoins31);
        }
        if (cards.toSet().length != cards.length) {
          throw Exception(_l10n.tentativeDeTricheVousNe);
        }
        for (String c in cards) {
          if (!myHand.contains(c)) {
            throw Exception(_l10n.carteManquanteDansVotreMain);
          }
        }
        if (!GameData.isValidRamiMeld(cards)) {
          throw Exception(_l10n.combinaisonInvalideSelonLesRegles);
        }

        for (String c in cards) myHand.remove(c);
        myMelds.add(cards);
        playerHands[playerId] = myHand;
        melds[playerId] = myMelds;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          15,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiMelds': melds,
        });
        return;
      }

      if (action == 'discard') {
        if (!hasDrawn && !isAuto) {
          throw Exception(_l10n.vousDevezDAbordPiocher);
        }
        if (cards == null || cards.length != 1)
          throw Exception(_l10n.defaussezExactement1Carte);
        String cardToDiscard = cards[0];
        if (!myHand.contains(cardToDiscard))
          throw Exception(_l10n.carteNonTrouvee);

        myHand.remove(cardToDiscard);
        discard.add(cardToDiscard);

        if (myHand.isEmpty) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            35,
            applySpeedBonus: true,
          );
          final targetAuth =
              (gameData['players'] as Map?)?[playerId]?['authUid'] ?? playerId;
          _db.collection('users').doc(targetAuth).set({
            'unlockedBadges.rami_gin': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

          Map<String, dynamic> totalScores = Map.from(
            gameData['ramiTotalScores'],
          );
          Map<String, dynamic> players = Map.from(gameData['players']);

          players.keys.forEach((pId) {
            if (pId != playerId) {
              List<String> pHand = List.from(playerHands[pId]);
              int penalty = pHand.fold(0, (sum, c) {
                String base = c.split('_')[0].trim();
                if (base.toUpperCase().contains('JOKER')) return sum + 20;
                if (base.length < 2) return sum;
                String rank = base.substring(0, base.length - 1);
                return sum + (GameData.ramiCardValues[rank] ?? 0);
              });
              totalScores[pId] = (totalScores[pId] ?? 0) + penalty;
            }
          });

          int targetScore = gameData['ramiTargetScore'] ?? 100;
          bool gameOver = totalScores.values.any(
            (score) => score >= targetScore,
          );

          transaction.update(gameRef, {
            'ramiPlayerHands': playerHands,
            'ramiDiscard': discard,
            'ramiTotalScores': totalScores,
            'ramiRoundOver': true,
            'roundState': 'round_end',
            'gameLog': FieldValue.arrayUnion([
              _l10n.aGagneLaManche1(players[playerId]["name"]),
            ]),
            if (gameOver) ...{
              'gameState': 'gameOver',
              'gameWinner':
                  totalScores.entries
                      .reduce((a, b) => a.value < b.value ? a : b)
                      .key,
              'players.${totalScores.entries.reduce((a, b) => a.value < b.value ? a : b).key}.score':
                  FieldValue.increment(1),
              'gameEndReason': _l10n.scoreCibleAtteint,
            },
          });
          return;
        }

        List<String> playerOrder = List.from(gameData['playerOrder']);
        int nextIndex =
            (playerOrder.indexOf(playerId) + 1) % playerOrder.length;
        playerHands[playerId] = myHand;
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiDiscard': discard,
          'ramiCurrentPlayerId': playerOrder[nextIndex],
          'ramiHasDrawn': false,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  // =========================================================================
  // 5. RAMI
  // =========================================================================
  List<List<String>> _findValidRamiMelds(List<String> hand) {
    final List<List<String>> foundMelds = [];
    final List<String> remaining = List<String>.from(hand);

    // 1. Chercher des Brelans / Carrés (même rang, couleurs différentes)
    final Map<String, List<String>> byRank = {};
    for (String c in remaining) {
      String clean = c.split('_')[0];
      if (clean.toUpperCase().contains('JOKER') || clean.length < 2) continue;
      String rank = clean.substring(0, clean.length - 1);
      byRank.putIfAbsent(rank, () => []).add(c);
    }
    for (var entry in byRank.entries) {
      final list = entry.value;
      final Map<String, String> suitMap = {};
      for (var c in list) {
        String clean = c.split('_')[0];
        String suit = clean.substring(clean.length - 1);
        suitMap[suit] = c;
      }
      if (suitMap.length >= 3) {
        final meld = suitMap.values.take(4).toList();
        if (GameData.isValidRamiMeld(meld)) {
          foundMelds.add(meld);
          for (var c in meld) remaining.remove(c);
        }
      }
    }

    // 2. Chercher des Suites (même couleur, rangs consécutifs)
    final Map<String, List<String>> bySuit = {};
    for (String c in remaining) {
      String clean = c.split('_')[0];
      if (clean.toUpperCase().contains('JOKER') || clean.length < 2) continue;
      String suit = clean.substring(clean.length - 1);
      bySuit.putIfAbsent(suit, () => []).add(c);
    }
    for (var entry in bySuit.entries) {
      final list = entry.value;
      if (list.length >= 3) {
        int getVal(String c) {
          String clean = c.split('_')[0];
          if (clean.toUpperCase().contains('JOKER') || clean.length < 2)
            return 0;
          String r = clean.substring(0, clean.length - 1);
          if (r == 'A') return 1;
          if (r == 'J') return 11;
          if (r == 'Q') return 12;
          if (r == 'K') return 13;
          return int.tryParse(r) ?? 0;
        }

        list.sort((a, b) => getVal(a).compareTo(getVal(b)));
        List<String> currentRun = [];
        for (int i = 0; i < list.length; i++) {
          if (currentRun.isEmpty) {
            currentRun.add(list[i]);
          } else {
            int prevVal = getVal(currentRun.last);
            int curVal = getVal(list[i]);
            if (curVal == prevVal + 1) {
              currentRun.add(list[i]);
            } else if (curVal > prevVal + 1) {
              if (currentRun.length >= 3 &&
                  GameData.isValidRamiMeld(currentRun)) {
                foundMelds.add(List.from(currentRun));
                for (var c in currentRun) remaining.remove(c);
              }
              currentRun = [list[i]];
            }
          }
        }
        if (currentRun.length >= 3 && GameData.isValidRamiMeld(currentRun)) {
          foundMelds.add(List.from(currentRun));
          for (var c in currentRun) remaining.remove(c);
        }
      }
    }

    return foundMelds;
  }

  Future<void> handleRamiTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final data = snap.data() as Map<String, dynamic>;
    if (data['gameState'] != 'playing') return;
    if (data['roundState'] == 'round_end' || data['ramiRoundOver'] == true) {
      await _startRamiRound(gameRef, data);
      return;
    }
    if (!_isTurnTimedOut(data)) return;

    final currentPlayerId = data['ramiCurrentPlayerId'];
    if (currentPlayerId == null) return;
    final hasDrawn = data['ramiHasDrawn'] ?? false;

    if (!hasDrawn) {
      await ramiAction(gameCode, currentPlayerId, 'draw_stock', isAuto: true);
    }

    final updatedSnap = await gameRef.get();
    if (!updatedSnap.exists) return;
    final updatedData = updatedSnap.data() as Map<String, dynamic>;
    if (updatedData['roundState'] == 'round_end' ||
        updatedData['ramiRoundOver'] == true ||
        updatedData['gameState'] == 'gameOver') {
      return;
    }
    final hand = List<String>.from(
      updatedData['ramiPlayerHands']?[currentPlayerId] ?? [],
    );

    if (hand.isNotEmpty) {
      final melds = _findValidRamiMelds(hand);
      for (final meld in melds) {
        try {
          await ramiAction(
            gameCode,
            currentPlayerId,
            'meld',
            cards: meld,
            isAuto: true,
          );
        } catch (_) {}
      }

      final postMeldSnap = await gameRef.get();
      if (!postMeldSnap.exists) return;
      final postMeldData = postMeldSnap.data() as Map<String, dynamic>;
      final postHand = List<String>.from(
        postMeldData['ramiPlayerHands']?[currentPlayerId] ?? [],
      );
      if (postHand.isNotEmpty) {
        // Choisir la carte la moins utile (éviter les Jokers et les paires, défausser la plus haute valeur)
        final Map<String, int> rankCount = {};
        for (final c in postHand) {
          final clean = c.split('_')[0];
          if (!clean.toUpperCase().contains('JOKER') && clean.length >= 2) {
            final r = clean.substring(0, clean.length - 1);
            rankCount[r] = (rankCount[r] ?? 0) + 1;
          }
        }
        int cardScore(String c) {
          final clean = c.split('_')[0];
          if (clean.toUpperCase().contains('JOKER')) return -100;
          if (clean.length < 2) return 0;
          final r = clean.substring(0, clean.length - 1);
          final val = GameData.ramiCardValues[r] ?? 5;
          final isPaired = (rankCount[r] ?? 0) >= 2;
          return isPaired ? val - 20 : val;
        }

        final sortedToDiscard = List<String>.from(postHand)
          ..sort((a, b) => cardScore(b).compareTo(cardScore(a)));
        await ramiAction(
          gameCode,
          currentPlayerId,
          'discard',
          cards: [sortedToDiscard.first],
          isAuto: true,
        );
      }
    }
  }

  // --- LOGIQUE PETITS CHEVAUX (Plateau Circulaire) ---
  Future<void> startPetitsChevaux(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    // Protection : 2v2 nécessite 4 joueurs
    bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
    if (playerIds.length != 4) isTeamMode = false;

    Map<String, dynamic> positions = {};
    Map<String, int> consecutiveSixes = {};
    for (String pId in playerIds) {
      positions[pId] = [-1, -1, -1, -1];
      consecutiveSixes[pId] = 0;
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'rolling',
      'petitsChevauxPositions': positions,
      'petitsChevauxPlayerOrder': playerIds,
      'petitsChevauxCurrentIndex': 0,
      'petitsChevauxDice': 0,
      'petitsChevauxHasRolled': false,
      'petitsChevauxTeamMode': isTeamMode, // On s'assure de l'enregistrer ici
      'petitsChevauxConsecutiveSixes': consecutiveSixes,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [
        isTeamMode ? _l10n.laPartie2v2Commence : _l10n.laPartieCommence1,
      ],
    });
  }

  Future<void> rollDicePetitsChevaux(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      final playerOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'] ?? [],
      );
      final currentIndex = gameData['petitsChevauxCurrentIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }
      if (gameData['petitsChevauxHasRolled'] == true) {
        throw Exception(_l10n.desDejaLancesPourCe);
      }

      final dice = Random().nextInt(6) + 1;
      final consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      if (dice == 6) {
        consecutiveSixes[playerId] = (consecutiveSixes[playerId] ?? 0) + 1;
      } else {
        consecutiveSixes[playerId] = 0;
      }

      final positions = Map<String, dynamic>.from(
        gameData['petitsChevauxPositions'] ?? {},
      );
      final List<int> myPawns = List<int>.from(
        positions[playerId] ?? [-1, -1, -1, -1],
      );
      final bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
      final int myIdx = playerOrder.indexOf(playerId);

      // Vérifier si AU MOINS UN coup est possible
      bool hasValidMove = false;

      final List<int> startOffsets = [0, 13, 39, 26];
      const List<int> starSquares = [8, 21, 34, 47];
      final int mySixes = (consecutiveSixes[playerId] as num?)?.toInt() ?? 0;

      // Pénalité 3 six consécutifs : retour immédiat du pion le plus avancé sur la piste à l'écurie
      if (mySixes >= 3) {
        int penaltyPawnIdx = -1;
        int maxTrackPos = -1;
        for (int i = 0; i < myPawns.length; i++) {
          if (myPawns[i] >= 0 && myPawns[i] <= 50 && myPawns[i] > maxTrackPos) {
            maxTrackPos = myPawns[i];
            penaltyPawnIdx = i;
          }
        }
        if (penaltyPawnIdx != -1) {
          myPawns[penaltyPawnIdx] = -1;
          positions[playerId] = myPawns;
        }
        consecutiveSixes[playerId] = 0;
        final playerName =
            gameData['players']?[playerId]?['name'] ?? _l10n.joueur;
        transaction.update(gameRef, {
          'petitsChevauxPositions': positions,
          'petitsChevauxDice': dice,
          'petitsChevauxHasRolled': false,
          'petitsChevauxCurrentIndex': (currentIndex + 1) % playerOrder.length,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.k3SixConsecutifsLePion1(playerName),
          ]),
        });
        return;
      }

      bool canMoveOwnerPawn(int ownerIdx, int p) {
        final String ownerId = playerOrder[ownerIdx];
        final int ownerStartOffset = startOffsets[ownerIdx];
        if (ownerIdx != myIdx) {
          // Allié en 2v2 : uniquement sortie d'écurie (-1) ou escalier (> 50)
          if (p == -1 && (dice == 1 || dice == 6)) {
            for (int i = 0; i < playerOrder.length; i++) {
              if (playerOrder[i] == ownerId ||
                  (isTeamMode && (i % 2 == ownerIdx % 2))) {
                final oPos = List<int>.from(positions[playerOrder[i]] ?? []);
                for (final op in oPos) {
                  if (op >= 0 &&
                      op <= 50 &&
                      (op + startOffsets[i]) % 52 == ownerStartOffset) {
                    return false;
                  }
                }
              }
            }
            return true;
          }
          return p > 50 && (p + dice <= 56);
        }

        if (p == -1) {
          if (dice != 1 && dice != 6) return false;
          for (int i = 0; i < playerOrder.length; i++) {
            if (playerOrder[i] == ownerId ||
                (isTeamMode && (i % 2 == ownerIdx % 2))) {
              final oPos = List<int>.from(positions[playerOrder[i]] ?? []);
              for (final op in oPos) {
                if (op >= 0 &&
                    op <= 50 &&
                    (op + startOffsets[i]) % 52 == ownerStartOffset) {
                  return false;
                }
              }
            }
          }
          return true;
        }

        final int newPos = p + dice;
        if (newPos > 56) return false;
        if (newPos <= 50) {
          final int targetAbs = (newPos + ownerStartOffset) % 52;
          for (int i = 0; i < playerOrder.length; i++) {
            final String otherId = playerOrder[i];
            final int otherStart = startOffsets[i];
            final List<int> otherPos = List<int>.from(positions[otherId] ?? []);
            for (final int op in otherPos) {
              if (op >= 0 && op <= 50) {
                final int otherAbs = (op + otherStart) % 52;
                if (targetAbs == otherAbs) {
                  if (otherId == ownerId ||
                      (isTeamMode && (i % 2 == ownerIdx % 2))) {
                    return false;
                  }
                  if (starSquares.contains(targetAbs) ||
                      targetAbs == otherStart) {
                    return false;
                  }
                }
              }
            }
          }
        }
        return true;
      }

      // 1. Vérification précise sur mes propres pions
      for (int p in myPawns) {
        if (canMoveOwnerPawn(myIdx, p)) {
          hasValidMove = true;
          break;
        }
      }

      // 2. Vérification sur les pions de l'allié en mode 2v2
      if (!hasValidMove && isTeamMode && playerOrder.length == 4) {
        final int allyIdx = (myIdx + 2) % 4;
        final String allyId = playerOrder[allyIdx];
        final List<int> allyPawns = List<int>.from(
          positions[allyId] ?? [-1, -1, -1, -1],
        );
        for (int p in allyPawns) {
          if (canMoveOwnerPawn(allyIdx, p)) {
            hasValidMove = true;
            break;
          }
        }
      }

      final playerName =
          gameData['players']?[playerId]?['name'] ?? _l10n.joueur;

      if (!hasValidMove) {
        // Aucun coup possible -> Passage automatique immédiat au joueur suivant
        consecutiveSixes[playerId] = 0;
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        transaction.update(gameRef, {
          'petitsChevauxDice': dice,
          'petitsChevauxHasRolled': false,
          'petitsChevauxCurrentIndex': nextIndex,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aFaitUnMaisAucun(playerName, dice),
          ]),
        });
      } else {
        // Coup possible -> Le joueur choisit son pion
        transaction.update(gameRef, {
          'petitsChevauxDice': dice,
          'petitsChevauxHasRolled': true,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> movePawnPetitsChevaux(
    String gameCode,
    String playerId,
    String targetOwnerId,
    int pawnIndex, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      // SÉCURITÉ AUTH
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      List<String> playerOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'],
      );
      int currentIndex = gameData['petitsChevauxCurrentIndex'];
      if (playerOrder[currentIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }

      // VÉRIFICATION OBLIGATOIRE DU LANCER
      if (gameData['petitsChevauxHasRolled'] != true ||
          (gameData['petitsChevauxDice'] ?? 0) <= 0) {
        throw Exception(_l10n.vousDevezDAbordLancer);
      }

      bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
      int myPlayerIdx = playerOrder.indexOf(playerId);
      int targetPlayerIdx = playerOrder.indexOf(targetOwnerId);

      bool isTeammate =
          isTeamMode &&
          (playerId != targetOwnerId) &&
          (myPlayerIdx % 2 == targetPlayerIdx % 2);

      if (playerId != targetOwnerId && !isTeammate) {
        throw Exception(_l10n.vousNePouvezPasDeplacer);
      }

      Map<String, dynamic> allPositions = Map<String, dynamic>.from(
        gameData['petitsChevauxPositions'],
      );
      List<int> targetPositions = List<int>.from(allPositions[targetOwnerId]);
      int currentPos = targetPositions[pawnIndex];
      int dice = gameData['petitsChevauxDice'];

      Map<String, dynamic> consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      int mySixes = consecutiveSixes[playerId] ?? 0;
      if (mySixes >= 3) {
        targetPositions[pawnIndex] = -1;
        allPositions[targetOwnerId] = targetPositions;
        consecutiveSixes[playerId] = 0;
        transaction.update(gameRef, {
          'petitsChevauxPositions': allPositions,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'petitsChevauxCurrentIndex': (currentIndex + 1) % playerOrder.length,
          'petitsChevauxHasRolled': false,
          'petitsChevauxDice': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.k3SixConsecutifsLePion1(
              players[playerId]?['name'] ?? _l10n.joueur,
            ),
          ]),
        });
        return;
      }

      if (isTeammate) {
        if (currentPos == -1 && (dice != 1 && dice != 6)) {
          throw Exception(_l10n.ilFautUn1Ou);
        } else if (currentPos >= 0 && currentPos <= 50) {
          throw Exception(_l10n.vousNePouvezAiderUn);
        }
      }

      bool captured = false;
      int newPos = currentPos;
      final List<int> startOffsets = [0, 13, 39, 26];
      int targetStartOffset = startOffsets[targetPlayerIdx];

      // 1. Sortie d'écurie
      if (currentPos == -1) {
        if (dice != 6 && dice != 1) {
          throw Exception(_l10n.ilFautUn6Ou);
        }
        newPos = 0;
        int myAbsPos = targetStartOffset;

        for (int i = 0; i < playerOrder.length; i++) {
          String otherId = playerOrder[i];
          int otherStartOffset = startOffsets[i];
          List<int> otherPos = List<int>.from(allPositions[otherId]);
          for (int pIdx = 0; pIdx < 4; pIdx++) {
            int p = otherPos[pIdx];
            if (p >= 0 && p <= 50) {
              int otherAbsPos = (p + otherStartOffset) % 52;
              if (otherAbsPos == myAbsPos) {
                if (otherId == targetOwnerId ||
                    (isTeamMode && (i % 2 == targetPlayerIdx % 2))) {
                  throw Exception(_l10n.caseDeDepartOccupeePar);
                } else {
                  // Capture autorisée sur sa propre case de départ
                  otherPos[pIdx] = -1;
                  allPositions[otherId] = otherPos;
                  captured = true;
                }
              }
            }
          }
        }
        targetPositions[pawnIndex] = newPos;
      } else {
        // 2. Déplacement normal sur piste ou escalier
        newPos = currentPos + dice;

        if (currentPos <= 50 && newPos > 50) {
          int overshoot = newPos - 50;
          newPos = 50 + overshoot;
          if (newPos > 56) {
            throw Exception(_l10n.lancerTropElevePourEntrer);
          }
        } else if (currentPos > 50) {
          if (newPos > 56) {
            transaction.update(gameRef, {
              'petitsChevauxHasRolled': false,
              'petitsChevauxDice': 0,
              'petitsChevauxCurrentIndex':
                  (currentIndex + 1) % playerOrder.length,
              'turnStartTime': FieldValue.serverTimestamp(),
              'gameLog': FieldValue.arrayUnion([
                _l10n.lancerTropElevePourAtteindre(dice),
              ]),
            });
            return;
          }
        }

        if (newPos <= 50) {
          int myAbsPos = (newPos + targetStartOffset) % 52;
          const List<int> starSquares = [8, 21, 34, 47];

          for (int i = 0; i < playerOrder.length; i++) {
            String otherId = playerOrder[i];
            int otherStartOffset = startOffsets[i];
            List<int> otherPos = List<int>.from(allPositions[otherId]);

            for (int pIdx = 0; pIdx < 4; pIdx++) {
              int p = otherPos[pIdx];
              if (p >= 0 && p <= 50) {
                int otherAbsPos = (p + otherStartOffset) % 52;
                if (myAbsPos == otherAbsPos) {
                  if (otherId == targetOwnerId ||
                      (isTeamMode && (i % 2 == targetPlayerIdx % 2))) {
                    throw Exception(_l10n.caseOccupeeParVotreEquipe);
                  }
                  if (starSquares.contains(myAbsPos) ||
                      myAbsPos == otherStartOffset) {
                    throw Exception(_l10n.caseRefugeProtegeeCaptureImpossible);
                  }
                  otherPos[pIdx] = -1;
                  allPositions[otherId] = otherPos;
                  captured = true;
                }
              }
            }
          }
        }
        targetPositions[pawnIndex] = newPos;
      }

      allPositions[targetOwnerId] = targetPositions;

      consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      mySixes = consecutiveSixes[playerId] ?? 0;
      bool reachedFinish = newPos == 56;
      bool extraTurn = (dice == 6 || captured || reachedFinish);

      final playerAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && captured && playerAuthUid != null) {
        _db.collection('users').doc(playerAuthUid.toString()).set({
          'badgeProgress.ludo_capture_3': FieldValue.increment(1),
        }, SetOptions(merge: true));
      }

      if (!isAuto && mySixes == 2 && playerAuthUid != null) {
        _db.collection('users').doc(playerAuthUid.toString()).set({
          'unlockedBadges.ludo_six_streak': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }

      int xpBase = (newPos == 56) ? 25 : (captured ? 20 : 5);
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      Map<String, dynamic> updates = {
        'petitsChevauxPositions': allPositions,
        'petitsChevauxHasRolled': false,
        'petitsChevauxDice': 0, // Reset systématique du dé
      };

      // Vérification de Victoire
      bool won = false;
      if (isTeamMode) {
        String allyId = playerOrder[(myPlayerIdx + 2) % 4];
        List<int> myPos = List<int>.from(allPositions[playerId]);
        List<int> allyPos = List<int>.from(allPositions[allyId]);
        if ((myPos.where((p) => p == 56).length +
                allyPos.where((p) => p == 56).length) >=
            4) {
          won = true;
        }
      } else {
        if (targetPositions.every((pos) => pos == 56)) won = true;
      }

      if (won) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          40,
          applySpeedBonus: false,
        );
        updates['players.$playerId.score'] = FieldValue.increment(1);
        if (isTeamMode) {
          String allyId = playerOrder[(myPlayerIdx + 2) % 4];
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            allyId,
            40,
            applySpeedBonus: false,
          );
          updates['players.$allyId.score'] = FieldValue.increment(1);
        }
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
        updates['gameEndReason'] = _l10n.aGagne3(players[playerId]["name"]);
        transaction.update(gameRef, updates);
        return;
      }

      // Pénalité des 3 six consécutifs déjà traitée en début d'action pour préserver l'intégrité du plateau

      updates['petitsChevauxConsecutiveSixes'] = consecutiveSixes;
      if (extraTurn) {
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      } else {
        updates['petitsChevauxCurrentIndex'] =
            (currentIndex + 1) % playerOrder.length;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

