      'roundState': 'turn_result',
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> nextDevineTeteTurn(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      List<String> words = List<String>.from(gameData['devineTeteWords'] ?? []);
      if (words.isEmpty) {
        words = List<String>.from(GameWords.devineTeteByDifficulty['soft']!)
          ..shuffle();
      }

      final bool useTeams = gameData['devineTeteUseTeams'] == true;
      Map<String, dynamic> updates = {
        'roundState': 'playing_turn',
        'currentWord': words.removeAt(0),
        'devineTeteWords': words,
        'guessedCount': 0,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (useTeams) {
        Map<String, dynamic> teams = gameData['teams'] ?? {};
        List<String> teamA = List<String>.from(teams['teamA'] ?? []);
        List<String> teamB = List<String>.from(teams['teamB'] ?? []);

        int tAIdx = gameData['teamATurnIndex'] ?? 0;
        int tBIdx = gameData['teamBTurnIndex'] ?? 0;
        String nextTeam = gameData['activeTeam'] == 'teamA' ? 'teamB' : 'teamA';

        // Si l'équipe adverse a fini, on reste sur la même
        if (nextTeam == 'teamA' && tAIdx >= teamA.length) nextTeam = 'teamB';
        if (nextTeam == 'teamB' && tBIdx >= teamB.length) nextTeam = 'teamA';

        if (tAIdx >= teamA.length && tBIdx >= teamB.length) {
          final tScores = Map<String, dynamic>.from(
            gameData['teamScores'] ?? {},
          );
          final aScore = (tScores['teamA'] as num?)?.toInt() ?? 0;
          final bScore = (tScores['teamB'] as num?)?.toInt() ?? 0;
          String winnerTeam = aScore >= bScore ? 'teamA' : 'teamB';
          List<String> winningPlayers = (winnerTeam == 'teamA') ? teamA : teamB;
          for (String wId in winningPlayers) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              wId,
              35,
              applySpeedBonus: false,
            );
          }
          transaction.update(gameRef, {
            'gameState': 'gameOver',
            'gameWinner': winnerTeam,
            for (String wId in winningPlayers)
              'players.$wId.score': FieldValue.increment(1),
            'gameEndReason': _l10n.chaqueJoueurADevineUne,
          });
          return;
        }

        String nextGuesser;
        if (nextTeam == 'teamA') {
          nextGuesser = teamA[tAIdx];
          tAIdx++;
        } else {
          nextGuesser = teamB[tBIdx];
          tBIdx++;
        }

        updates['activeTeam'] = nextTeam;
        updates['currentGuesserId'] = nextGuesser;
        updates['teamATurnIndex'] = tAIdx;
        updates['teamBTurnIndex'] = tBIdx;
      } else {
        List<String> playerOrder = List<String>.from(
          gameData['playerOrder'] ?? [],
        );
        int currentIndex = gameData['currentPlayerIndex'] ?? 0;
        int nextIndex = currentIndex + 1;

        if (nextIndex >= playerOrder.length) {
          final pMap = Map<String, dynamic>.from(gameData['players'] ?? {});
          String bestPlayer = playerOrder.isNotEmpty ? playerOrder.first : '';
          int highestScore = -1;
          pMap.forEach((k, v) {
            int sc = (v is Map ? (v['score'] ?? 0) : 0);
            if (sc > highestScore) {
              highestScore = sc;
              bestPlayer = k;
            }
          });
          if (bestPlayer.isNotEmpty) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              bestPlayer,
              35,
              applySpeedBonus: false,
            );
          }
          transaction.update(gameRef, {
            'gameState': 'gameOver',
            'gameWinner': bestPlayer,
            if (bestPlayer.isNotEmpty)
              'players.$bestPlayer.score': FieldValue.increment(1),
            'gameEndReason': _l10n.toutLeMondeEstPasse,
          });
          return;
        }
        updates['currentPlayerIndex'] = nextIndex;
        updates['currentGuesserId'] = playerOrder[nextIndex];
      }

      transaction.update(gameRef, updates);
    });
  }

  // =============================================================================
  // ACTION OU VÉRITÉ - LOGIQUE MULTIJOUEUR EN LIGNE
  // =============================================================================

  Future<void> _startActionOuVeriteRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerIds = players.keys.toList()..shuffle();
    final bool playersDecide = gameData['aoVPlayersDecide'] ?? false;
    final int voteThreshold = gameData['aoVVoteThreshold'] ?? 100;

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'spinning_wheel',
      'aoVPlayerOrder': playerIds,
      'aoVCurrentPlayerIndex': -1, // -1 = personne n'a encore été désigné
      'aoVCurrentPlayerId': null,
      'aoVCurrentChallenge': null,
      'aoVChallengeType': null, // 'action' ou 'verite'
      'aoVChallengeAuthor': null, // ID du joueur qui a écrit le défi
      'aoVPhase':
          'waiting_spin', // waiting_spin, spin_result, writing_challenge, performing, voting, result
      'aoVPlayersDecide': playersDecide,
      'aoVVoteThreshold': voteThreshold,
      'aoVVotes': {},
      'aoVCurrentRound': 1,
      'aoVSpinsRemaining': gameData['aoVMaxRounds'] ?? 10,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': FieldValue.arrayUnion([_l10n.laPartieDActionOu]),
    });
  }

  /// Le joueur tourne la roulette pour savoir qui joue (avec incrément de spin unique)
  Future<void> aoVSpinWheel(String gameCode, String playerId) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;

      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['aoVPhase'] != 'waiting_spin') return;

      final playerOrder = List<String>.from(gameData['aoVPlayerOrder'] ?? []);
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (playerOrder.isEmpty) return;

      final randomIndex = Random().nextInt(playerOrder.length);
      final selectedPlayerId = playerOrder[randomIndex];
      final selectedName = players[selectedPlayerId]?['name'] ?? _l10n.joueur;

      transaction.update(gameRef, {
        'aoVCurrentPlayerIndex': randomIndex,
        'aoVCurrentPlayerId': selectedPlayerId,
        'aoVPhase': 'spin_result',
        'aoVSpinCount': FieldValue.increment(
          1,
        ), // Force la détection de rotation
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([
          _l10n.laRouletteADesigne(selectedName),
        ]),
      });
    });
  }

  /// Le joueur désigné tire Action ou Vérité
  Future<void> aoVDrawChallengeType(String gameCode, String playerId) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;

      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['aoVPhase'] != 'spin_result') return;
      if (gameData['aoVCurrentPlayerId'] != playerId) return;

      final bool playersDecide = gameData['aoVPlayersDecide'] ?? false;
      final playerOrder = List<String>.from(gameData['aoVPlayerOrder'] ?? []);
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // Tirer aléatoirement Action ou Vérité
      final challengeType = Random().nextBool() ? 'action' : 'verite';

      if (playersDecide) {
        // Mode Juges : désigner un joueur aléatoire pour écrire le défi
        final otherPlayers = playerOrder.where((p) => p != playerId).toList();
        if (otherPlayers.isEmpty) {
          // Fallback automatique si aucun autre joueur disponible
          final String difficulty = gameData['difficulty'] ?? 'soft';
          final List<String> fallbackChallenges =
              challengeType == 'action'
                  ? (GameWords.dares[difficulty] ?? GameWords.dares['soft']!)
                  : (GameWords.truths[difficulty] ?? GameWords.truths['soft']!);
          final chosenChallenge =
              fallbackChallenges[Random().nextInt(fallbackChallenges.length)];
          final targetPlayerName = players[playerId]?['name'] ?? _l10n.joueur;

          transaction.update(gameRef, {
            'aoVChallengeType': challengeType,
            'aoVCurrentChallenge': chosenChallenge,
            'aoVPhase': 'performing',
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              _l10n.aTireDefi(
                targetPlayerName,
                challengeType == 'action' ? _l10n.action1 : _l10n.verite1,
              ),
              _l10n.iAucunAutreJoueurDisponible,
            ]),
          });
          return;
        }

        final authorId = otherPlayers[Random().nextInt(otherPlayers.length)];
        final authorName = players[authorId]?['name'] ?? _l10n.joueur;
        final targetPlayerName = players[playerId]?['name'] ?? _l10n.joueur;

        transaction.update(gameRef, {
          'aoVChallengeType': challengeType,
          'aoVChallengeAuthor': authorId,
          'aoVPhase': 'writing_challenge',
          'aoVCurrentChallenge': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aTireDefi(
              targetPlayerName,
              challengeType == 'action' ? _l10n.action1 : _l10n.verite1,
            ),
            _l10n.doitEcrireLeDefi(authorName),
          ]),
        });
      } else {
        // Mode Classique : générer un défi aléatoire (priorité aux mots IA si présents)
        final String difficulty = gameData['difficulty'] ?? 'soft';
        List<String> challenges = [];
        if (gameData['aiWords'] != null &&
            (gameData['aiWords'] as List).isNotEmpty) {
          final aiList = List<String>.from(gameData['aiWords']);
          final filtered =
              aiList
                  .where((item) {
                    final lower = item.trim().toLowerCase();
                    if (challengeType == 'action') {
                      return lower.startsWith('action');
                    } else {
                      return lower.startsWith('vérité') ||
                          lower.startsWith('verite');
                    }
                  })
                  .map((item) {
                    final colonIdx = item.indexOf(':');
                    return colonIdx != -1
                        ? item.substring(colonIdx + 1).trim()
                        : item.trim();
                  })
                  .where((s) => s.isNotEmpty)
                  .toList();
          challenges =
              filtered.isNotEmpty
                  ? filtered
                  : aiList
                      .map((item) {
                        final colonIdx = item.indexOf(':');
                        return colonIdx != -1
                            ? item.substring(colonIdx + 1).trim()
                            : item.trim();
                      })
                      .where((s) => s.isNotEmpty)
                      .toList();
        }
        if (challenges.isEmpty) {
          if (challengeType == 'action') {
            challenges =
                GameWords.dares[difficulty] ?? GameWords.dares['soft']!;
          } else {
            challenges =
                GameWords.truths[difficulty] ?? GameWords.truths['soft']!;
          }
        }
        String challenge = challenges[Random().nextInt(challenges.length)];
        if (challenge.contains('{player}')) {
          final otherNames =
              playerOrder
                  .where((id) => id != playerId)
                  .map(
                    (id) => (players[id]?['name'] ?? _l10n.joueur).toString(),
                  )
                  .toList();
          final pickedName =
              otherNames.isNotEmpty
                  ? otherNames[Random().nextInt(otherNames.length)]
                  : (players[playerId]?['name'] ?? _l10n.joueur).toString();
          challenge = challenge.replaceAll('{player}', pickedName);
        }
        final targetPlayerName = players[playerId]?['name'] ?? _l10n.joueur;

        transaction.update(gameRef, {
          'aoVChallengeType': challengeType,
          'aoVCurrentChallenge': challenge,
          'aoVPhase': 'performing',
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aTireDefi(
              targetPlayerName,
              challengeType == 'action' ? _l10n.action1 : _l10n.verite1,
            ),
          ]),
        });
      }
    });
  }

  /// Le joueur auteur soumet le défi écrit
  Future<void> aoVSubmitWrittenChallenge(
    String gameCode,
    String playerId,
    String challenge,
  ) async {
    final cleanChallenge = FirebaseService.sanitizeUserInput(
      challenge,
      maxLength: 200,
    );
    if (cleanChallenge.isEmpty) return;

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;

      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['aoVPhase'] != 'writing_challenge') return;
      if (gameData['aoVChallengeAuthor'] != playerId) return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final currentPlayerId = gameData['aoVCurrentPlayerId'];
      final currentPlayerName =
          players[currentPlayerId]?['name'] ?? _l10n.joueur;

      transaction.update(gameRef, {
        'aoVCurrentChallenge': cleanChallenge,
        'aoVPhase': 'performing',
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([
          _l10n.leDefiAEteEnvoye1(currentPlayerName),
        ]),
      });
    });
  }

  /// Le joueur confirme qu'il a réalisé le défi → passe au vote
  Future<void> aoVConfirmPerformed(String gameCode, String playerId) async {
    await _db.runTransaction((transaction) async {
