  /// 1. Écriture sécurisée et isolée des réponses de chaque joueur
  Future<void> submitPetitBacAnswer(
    String gameCode,
    String playerId,
    String category,
    String answer,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final cleanAnswer = sanitizeUserInput(answer, maxLength: 35).trim();

    final gameRef = _db.collection('games').doc(gameCode);

    // Écriture isolée dans une sous-collection privée pour empêcher les autres joueurs de lire la réponse en temps réel
    await gameRef.collection('petit_bac_private_answers').doc(playerId).set({
      category: cleanAnswer,
    }, SetOptions(merge: true));
  }

  /// 2. Clôture de la saisie d'un joueur
  Future<void> endPetitBacTurn(String gameCode, String playerId) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final gameRef = _db.collection('games').doc(gameCode);
    bool allFinished = false;

    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      // Le joueur a fini de remplir avant la fin du temps !
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        20,
        applySpeedBonus: false,
      );

      transaction.update(gameRef, {'petitBacSubmittedPlayers.$playerId': true});

      Map<String, dynamic> submitted = Map.from(
        gameData['petitBacSubmittedPlayers'] ?? {},
      );
      submitted[playerId] = true;
      Map<String, dynamic> players = gameData['players'] ?? {};

      if (submitted.length >= players.length) {
        allFinished = true;
      }
    });

    if (allFinished) {
      await evaluatePetitBacAnswers(gameCode);
    }
  }

  Future<void> evaluatePetitBacAnswers(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;

    if (gameData['roundState'] != 'answering') return;

    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final categories = List<String>.from(gameData['petitBacCategories'] ?? []);
    String normalizePetitBacStr(String str) {
      return str
          .trim()
          .toLowerCase()
          .replaceAll(RegExp(r'[àáâãäå]'), 'a')
          .replaceAll(RegExp(r'[ç]'), 'c')
          .replaceAll(RegExp(r'[èéêë]'), 'e')
          .replaceAll(RegExp(r'[ìíîï]'), 'i')
          .replaceAll(RegExp(r'[ñ]'), 'n')
          .replaceAll(RegExp(r'[òóôõö]'), 'o')
          .replaceAll(RegExp(r'[ùúûü]'), 'u')
          .replaceAll(RegExp(r'[ýÿ]'), 'y');
    }

    final targetLetter = normalizePetitBacStr(
      gameData['petitBacCurrentLetter'] as String? ?? '',
    );
    const rareLetters = ['k', 'w', 'x', 'y', 'z', 'q'];
    bool isRareLetter = rareLetters.contains(targetLetter);

    final privateAnswersSnap =
        await gameRef.collection('petit_bac_private_answers').get();
    final Map<String, Map<String, dynamic>> allPlayerAnswers = {};
    for (final doc in privateAnswersSnap.docs) {
      allPlayerAnswers[doc.id] = doc.data();
    }

    final Map<String, int> roundScores = {
      for (final pId in players.keys) pId: 0,
    };

    final Map<String, int> xpGainedPerPlayer = {
      for (final pId in players.keys) pId: 0,
    };

    for (final category in categories) {
      final Map<String, String> validAnswers = {};
      for (final entry in allPlayerAnswers.entries) {
        final rawAns = (entry.value[category] as String? ?? '').trim();
        final normAns = normalizePetitBacStr(rawAns);
        if (normAns.isNotEmpty && normAns.startsWith(targetLetter)) {
          validAnswers[entry.key] = normAns;
        }
      }

      final Map<String, int> wordCounts = {};
      for (final w in validAnswers.values) {
        wordCounts[w] = (wordCounts[w] ?? 0) + 1;
      }

      final validCount = validAnswers.length;
      for (final entry in validAnswers.entries) {
        final pId = entry.key;
        final w = entry.value;
        if (validCount == 1) {
          roundScores[pId] =
              (roundScores[pId] ?? 0) + 20; // Seul joueur à avoir trouvé
          _db
              .collection('users')
              .doc(players[entry.key]?['authUid'] ?? entry.key)
              .set({
                'unlockedBadges.petit_bac_solo_20':
                    FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
        } else if ((wordCounts[w] ?? 0) == 1) {
          roundScores[pId] = (roundScores[pId] ?? 0) + 10; // Réponse unique
        } else {
          roundScores[pId] = (roundScores[pId] ?? 0) + 5; // Réponse partagée
        }
        // --- NOUVELLE LOGIQUE XP ---
        int xpBase = (wordCounts[w] ?? 0) == 1 ? 15 : 5;
        if (isRareLetter) xpBase += 15; // Bonus lettre rare

        xpGainedPerPlayer[pId] = (xpGainedPerPlayer[pId] ?? 0) + xpBase;
      }
    }

    final totalScores = Map<String, dynamic>.from(
      gameData['petitBacTotalScores'] ?? {},
    );
    for (final entry in roundScores.entries) {
      totalScores[entry.key] = (totalScores[entry.key] ?? 0) + entry.value;
    }

    roundScores.forEach((pId, score) {
      if (score >= 50) {
        _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
          'unlockedBadges.petit_bac_round_50': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
    });

    // Nettoyage des réponses privées
    final batch = _db.batch();
    for (final doc in privateAnswersSnap.docs) {
      batch.delete(doc.reference);
    }
    await batch.commit();

    final Map<String, dynamic> xpUpdates = {};
    for (final entry in xpGainedPerPlayer.entries) {
      if (entry.value > 0) {
        final pAuth = players[entry.key]?['authUid'] ?? entry.key;
        _db.collection('users').doc(pAuth).set({
          'xp': FieldValue.increment(entry.value),
        }, SetOptions(merge: true));
        xpUpdates['players.${entry.key}.xp'] = FieldValue.increment(
          entry.value,
        );
      }
    }

    await gameRef.update({
      'petitBacAnswers': allPlayerAnswers,
      'petitBacRoundScores': roundScores,
      'petitBacTotalScores': totalScores,
      'roundState': 'round_results',
      'petitBacRoundEnded': true,
      'turnStartTime': FieldValue.serverTimestamp(),
      ...xpUpdates,
    });
  }

  Future<void> finishPetitBacGame(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    final totalScores = Map<String, dynamic>.from(
      gameData['petitBacTotalScores'] ?? {},
    );
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    String? winnerId;
    int maxScore = -1;
    totalScores.forEach((pId, sc) {
      final s = (sc as num?)?.toInt() ?? 0;
      if (s > maxScore) {
        maxScore = s;
        winnerId = pId;
      }
    });

    await gameRef.update({
      'gameState': 'gameOver',
      'gameWinner': winnerId,
      'gameEndReason':
          winnerId != null
              ? _l10n.gagneAvecPoints(
                players[winnerId]?['name'] ?? _l10n.unJoueur,
                maxScore,
              )
              : _l10n.finDeLaPartie,
      if (winnerId != null) 'players.$winnerId.score': FieldValue.increment(1),
    });
  }

