  Future<void> submitPictionaryGuess(
    String gameCode,
    String playerId,
    String guesserName,
    String guess,
  ) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);

    final guessData = {
      'guesserId': playerId,
      'guesserName': guesserName,
      'guess': guess.trim(),

      'timestamp': DateTime.now().millisecondsSinceEpoch,
    };

    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      if (gameSnap.get('roundState') == 'drawing' ||
          gameSnap.get('roundState') == 'guessing_drawing') {
        print(
          "--- DEBUG PICTIONARY --- Condition 'roundState == drawing' ou 'guessing_drawing' est VRAIE. Mise à jour de la base de données...",
        );

        final List<dynamic> currentGuesses = List.from(
          gameSnap.get('pictionaryGuesses') ?? [],
        );
        currentGuesses.add(guessData);
        transaction.update(gameRef, {'pictionaryGuesses': currentGuesses});
      } else {
        print(
          "--- DEBUG PICTIONARY --- Condition 'roundState == drawing' est FAUSSE. L'état actuel est '${gameSnap.get('roundState')}'",
        );
      }
    });
  }

  Future<void> validatePictionaryGuess(
    String gameCode,
    String winnerId, {
    String? drawerId,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    DocumentReference gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      // Accepter les états normaux de dessin
      if (gameData['roundState'] == 'drawing' ||
          gameData['roundState'] == 'guessing_drawing' ||
          gameData['roundState'] == 'playing') {
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});

        // 1. SÉCURITÉ : Vérifier que c'est BIEN le dessinateur qui valide
        final expectedDrawerId = gameData['currentDrawingPlayerId'] ?? drawerId;
        if (expectedDrawerId == null ||
            !players.containsKey(expectedDrawerId)) {
          throw Exception(_l10n.dessinateurIntrouvable);
        }
        if (drawerId != null && drawerId != expectedDrawerId) {
          throw Exception(_l10n.seulLeDessinateurActifPeut);
        }
        final drawerAuthUid =
            players[expectedDrawerId]?['authUid'] ?? expectedDrawerId;
        if (currentAuthUid != drawerAuthUid) {
          throw Exception(_l10n.usurpationDIdentiteDuDessinateur);
        }

        // 2. Le dessinateur ne peut pas se déclarer vainqueur lui-même
        if (winnerId == expectedDrawerId || !players.containsKey(winnerId)) {
          throw Exception(_l10n.gagnantInvalide);
        }

        final bool isCollective = gameData['pictionaryTeams'] == true;
        final updates = <String, dynamic>{};

        if (isCollective) {
          try {
            FirebaseDatabase.instance
                .ref('games/$gameCode/pictionary')
                .remove();
          } catch (_) {}
          // Mode collectif : avancer à la carte suivante ou terminer le lot
          final List<String> collectiveWords = List<String>.from(
            gameData['pictionaryCollectiveWords'] ?? [],
          );
          final int cardIndex =
              (gameData['pictionaryCollectiveCardIndex'] ?? 0) as int;
          final int guessedCount =
              ((gameData['pictionaryCollectiveGuessed'] ?? 0) as int) + 1;

          if (collectiveWords.isEmpty ||
              cardIndex >= collectiveWords.length - 1) {
            // Dernière carte ! Fin du tour collectif
            updates['pictionaryCollectiveGuessed'] = guessedCount;
            updates['roundState'] = 'result';
            updates['gameEndReason'] = _l10n.motsDevines(
              guessedCount,
              collectiveWords.length,
            );
            updates['roundWinnerId'] = winnerId;
            updates['turnStartTime'] = FieldValue.serverTimestamp();
          } else {
            // Passer à la carte suivante
            final String nextWord = collectiveWords[cardIndex + 1];
            updates['pictionaryCollectiveCardIndex'] = FieldValue.increment(1);
            updates['pictionaryCollectiveGuessed'] = guessedCount;
            updates['currentPictionaryWord'] = nextWord;
            updates['pictionaryDrawing'] = null;
            updates['pictionaryGuesses'] = [];
            updates['pictionaryStrokeCount'] = 0;
          }
        } else {
          // Mode normal : 1 point pour celui qui a trouvé + 1 point pour le dessinateur
          updates['players.$winnerId.score'] = FieldValue.increment(1);
          updates['players.$expectedDrawerId.score'] = FieldValue.increment(1);
          updates['roundState'] = 'result';
          updates['roundWinnerId'] = winnerId;
          updates['gameEndReason'] = _l10n.motTrouveAvecSucces;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }

        final Timestamp? startTime =
            gameData['pictionaryStartTime'] as Timestamp? ??
            gameData['turnStartTime'] as Timestamp?;
        int elapsedSeconds =
            startTime != null
                ? DateTime.now().difference(startTime.toDate()).inSeconds
                : 99;

        int guesserXp = 20;
        if (elapsedSeconds <= 15) guesserXp += 15; // Bonus rapidité

        int drawerXp = 20;
        final bool only30 = gameData['pictionaryOnly30Strokes'] == true;
        final int strokeCount =
            (gameData['pictionaryStrokeCount'] as int? ?? 0);
        if (only30 && strokeCount <= 15)
          drawerXp += 20; // Bonus économie de traits

        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          winnerId,
          guesserXp,
          applySpeedBonus: false,
        );
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          expectedDrawerId,
          drawerXp,
          applySpeedBonus: false,
        );

        transaction.update(gameRef, updates);

        // 1. pic_30_strokes_win (Moins de 15 traits en mode 30 traits)
        if (only30 && strokeCount <= 15) {
          _db.collection('users').doc(drawerAuthUid).set({
            'unlockedBadges.pic_30_strokes_win': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }

        // 2. pic_fast_guess (Trouvé en moins de 10 secondes)
        if (elapsedSeconds <= 10) {
          _db.collection('users').doc(drawerAuthUid).set({
            'unlockedBadges.pic_fast_guess': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }

        // 3. pic_guesser_10 (Incrémenter la progression du devineur)
        final winnerAuthUid = players[winnerId]?['authUid'] ?? winnerId;
        _db.collection('users').doc(winnerAuthUid).set({
          'badgeProgress.pic_guesser_10': FieldValue.increment(1),
        }, SetOptions(merge: true));
      }
    });
  }

  Future<void> validatePictionaryGuessSecure({
    required String gameCode,
    required String drawerId,
    required String winnerGuesserId,
  }) => validatePictionaryGuess(gameCode, winnerGuesserId, drawerId: drawerId);

  Future<void> handlePictionaryTimeout(
    String gameCode,
    String currentRoundState,
  ) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;

    if (gameData['roundState'] == 'drawing' ||
        gameData['roundState'] == 'guessing_drawing') {
      String reason =
          (gameData['roundState'] == 'drawing')
              ? _l10n.leDessinateurNAPas
              : _l10n.leTempsEstEcoulePersonne;
      await gameRef.update({
        'roundState': 'result',
        'gameEndReason': reason,
        'turnStartTime': FieldValue.serverTimestamp(),
        'pictionaryStartTime': FieldValue.serverTimestamp(),
      });
      Future.delayed(Duration(seconds: 3), () async {
        await nextPictionaryRound(gameCode);
      });
    } else if (gameData['roundState'] == 'result') {
      await nextPictionaryRound(gameCode);
    }

    try {
      await FirebaseDatabase.instance
          .ref('games/$gameCode/pictionary')
          .remove();
    } catch (_) {}
  }

  Future<void> nextPictionaryRound(String gameCode) async {
    try {
      await FirebaseDatabase.instance
          .ref('games/$gameCode/pictionary')
          .remove();
    } catch (_) {}
    try {
      await FirebaseDatabase.instance
          .ref('games/$gameCode/pictionaryChat')
          .remove();
    } catch (_) {}

    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    List<String> pictionaryWords = List<String>.from(
      gameData['pictionaryWords'] ?? [],
    );

    int currentDrawingPlayerIndex = playerOrder.indexOf(
      gameData['currentDrawingPlayerId'],
    );
    int nextDrawingPlayerIndex =
        (currentDrawingPlayerIndex + 1) % playerOrder.length;
    String nextDrawingPlayerId = playerOrder[nextDrawingPlayerIndex];

    String currentWord = gameData['currentPictionaryWord'];
    pictionaryWords.remove(currentWord);
    if (pictionaryWords.isEmpty) {
      pictionaryWords = List.from(
        GameWords.pictionaryWords[gameData['difficulty']] ??
            GameWords.pictionaryWords['soft']!,
      )..shuffle();
    }
    String nextPictionaryWord =
        pictionaryWords[Random().nextInt(pictionaryWords.length)];
    final bool isCollective = gameData['pictionaryTeams'] == true;
    List<String> newCollectiveWords = [];
    if (isCollective) {
      pictionaryWords.shuffle();
      newCollectiveWords = pictionaryWords.take(13).toList();
      nextPictionaryWord = newCollectiveWords[0];
    }

    await gameRef.update({
      'currentRound': FieldValue.increment(1),
      'roundState': 'drawing',
      'pictionaryWords': pictionaryWords,
      'currentDrawingPlayerId': nextDrawingPlayerId,
      'currentPictionaryWord': nextPictionaryWord,
      'pictionaryDrawing': null,
      'pictionaryGuesses': [],
      'pictionaryStrokeCount': 0,
      'currentPlayerIndex': nextDrawingPlayerIndex,
      'pictionaryStartTime': FieldValue.serverTimestamp(),
      'roundWinnerId': null,
      'gameEndReason': null,
      'turnStartTime': FieldValue.serverTimestamp(),
      if (isCollective) 'pictionaryCollectiveWords': newCollectiveWords,
      if (isCollective) 'pictionaryCollectiveCardIndex': 0,
      if (isCollective) 'pictionaryCollectiveGuessed': 0,
    });
  }

