  /// 1. Soumission d'un indice sécurisée dans une sous-collection privée via Cloud Function
  Future<void> submitJustOneClue(
    String gameCode,
    String playerId,
    String clue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final cleanClue =
        FirebaseService.sanitizeUserInput(clue, maxLength: 30).trim();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'clue_giving') {
        throw Exception(_l10n.ceNEstPasLa2);
      }
      if (gameData['justOneGuesserId'] == playerId) {
        throw Exception(_l10n.leDevineurNePeutPas);
      }

      final clues = Map<String, dynamic>.from(gameData['justOneClues'] ?? {});
      clues[playerId] = cleanClue;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final nonGuessersCount = players.length - 1;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        10,
        applySpeedBonus: true,
      );

      final updates = <String, dynamic>{
        'justOneClues': clues,
        'justOneSubmittedCount': clues.length,
      };

      if (clues.length >= nonGuessersCount) {
        // Normalisation stricte Just One : sans accents, ponctuation, ni pluriels simples
        String normalizeJustOneClue(String raw) {
          var s = raw.toLowerCase().trim();
          const withDia = 'àáâãäåçèéêëìíîïñòóôõöùúûüýÿ';
          const withoutDia = 'aaaaaaceeeeiiiinooooouuuuyy';
          for (int i = 0; i < withDia.length; i++) {
            s = s.replaceAll(withDia[i], withoutDia[i]);
          }
          s = s.replaceAll(RegExp(r'[^a-z0-9]'), '');
          if (s.length > 3 && s.endsWith('s') && !s.endsWith('ss')) {
            s = s.substring(0, s.length - 1);
          }
          return s;
        }

        final String normalizedTarget = normalizeJustOneClue(
          gameData['justOneCurrentWord']?.toString() ?? '',
        );
        final bool allowInvalid = gameData['justOneAllowInvalidClues'] == true;

        // Filtrage des doublons et du mot mystère lui-même
        final Map<String, int> clueCounts = {};
        for (final c in clues.values) {
          final normalized = normalizeJustOneClue(c as String);
          clueCounts[normalized] = (clueCounts[normalized] ?? 0) + 1;
        }

        final filteredClues = <String>[];
        for (final entry in clues.entries) {
          final normalized = normalizeJustOneClue(entry.value as String);
          final bool isTargetSame =
              !allowInvalid &&
              normalizedTarget.isNotEmpty &&
              (normalized == normalizedTarget ||
                  normalized.contains(normalizedTarget) ||
                  normalizedTarget.contains(normalized));
          if (!isTargetSame && (clueCounts[normalized] ?? 0) == 1) {
            filteredClues.add(entry.value as String);
          }
        }

        if (filteredClues.length == 1) {
          final uniqueAuthorId =
              clues.entries
                  .firstWhere((e) => filteredClues.contains(e.value))
                  .key;
          _db
              .collection('users')
              .doc(players[uniqueAuthorId]?['authUid'] ?? uniqueAuthorId)
              .set({
                'unlockedBadges.just_one_unique_clue':
                    FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
        }

        updates['justOneFilteredClues'] = filteredClues;
        updates['roundState'] = 'reveal_clues';
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  /// 3. Soumission de la proposition du devineur
  Future<void> submitJustOneGuess(
    String gameCode,
    String playerId,
    String guess,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final cleanGuess = sanitizeUserInput(guess, maxLength: 40).toLowerCase();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'reveal_clues') {
        throw Exception(_l10n.ceNEstPasLe);
      }
      if (gameData['justOneGuesserId'] != playerId) {
        throw Exception(_l10n.seulLeDevineurPeutFaire);
      }

      String normalizeGuess(String str) {
        return str
            .trim()
            .toLowerCase()
            .replaceAll(RegExp(r'[àáâãäå]'), 'a')
            .replaceAll(RegExp(r'[ç]'), 'c')
            .replaceAll(RegExp(r'[èéêë]'), 'e')
            .replaceAll(RegExp(r'[ìíîï]'), 'i')
            .replaceAll(RegExp(r'[ñ]'), 'n')
            .replaceAll(RegExp(r'[òóôõö]'), 'o')
            .replaceAll(RegExp(r'[ùúûü]'), 'u')
            .replaceAll(RegExp(r'[ýÿ]'), 'y')
            .replaceAll(RegExp(r'[^a-z0-9]'), '');
      }

      String currentWord =
          (gameData['justOneCurrentWord'] as String? ?? '').toLowerCase();
      bool isCorrect =
          normalizeGuess(cleanGuess).isNotEmpty &&
          normalizeGuess(cleanGuess) == normalizeGuess(currentWord);

      Map<String, dynamic> updates = {
        'justOneGuesserAnswer': cleanGuess,
        'roundState': 'result',
        'gameEndReason': isCorrect ? _l10n.motDevine : _l10n.motNonDevine,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isCorrect) {
        updates['justOneTotalScore'] = FieldValue.increment(1);
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        players.keys.forEach((pId) {
          int xp = pId == playerId ? 30 : 25;
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            pId,
            xp,
            applySpeedBonus: false,
          );
        });
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> nextJustOneRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'result') return;

      List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      List<String> justOneDeck = List<String>.from(
        gameData['justOneDeck'] ?? [],
      );
      int currentDeckIndex = gameData['justOneDeckIndex'] ?? 0;
      int nextDeckIndex = currentDeckIndex + 1;

      if (nextDeckIndex >= justOneDeck.length) {
        // Toutes les 13 cartes jouées → fin de partie
        final int finalScore = gameData['justOneTotalScore'] ?? 0;
        if (finalScore == 13) {
          final playersMap = Map<String, dynamic>.from(
            gameData['players'] ?? {},
          );
          for (final pId in playersMap.keys) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              100,
              applySpeedBonus: false,
            );
            final pAuth = playersMap[pId]?['authUid'] ?? pId;
            _db.collection('users').doc(pAuth).set({
              'unlockedBadges.just_one_13': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }

        transaction.update(gameRef, {
          'gameState': 'gameOver',
          'gameWinner': playerOrder.isNotEmpty ? playerOrder.first : null,
          'gameEndReason': _l10n.les13CartesOntEte,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        return;
      }

      int currentGuesserIndex = playerOrder.indexOf(
        gameData['justOneGuesserId'],
      );
      int nextGuesserIndex = (currentGuesserIndex + 1) % playerOrder.length;
      String nextGuesserId = playerOrder[nextGuesserIndex];

      transaction.update(gameRef, {
        'currentRound': FieldValue.increment(1),
        'roundState': 'clue_giving',
        'justOneDeckIndex': nextDeckIndex,
        'justOneCurrentWord': justOneDeck[nextDeckIndex],
        'justOneGuesserId': nextGuesserId,
        'justOneClues': {},
        'justOneFilteredClues': [],
        'justOneSubmittedCount': 0,
        'justOneGuesserAnswer': null,
        'justOneRevealIndex': 0,
        'currentPlayerIndex': nextGuesserIndex,
        'gameEndReason': null,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> submitHotPotatoAnswer(
    String gameCode,
    String playerId,
    String answer,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final cleanAnswer =
        sanitizeUserInput(answer, maxLength: 40).trim().toLowerCase();
    if (cleanAnswer.isEmpty) throw Exception(_l10n.reponseInvalide);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'playing') {
        throw Exception(_l10n.ceNEstPasLe1);
      }
      if (gameData['hotPotatoCurrentPlayerId'] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre4);
      }

      final usedAnswers = List<String>.from(
        gameData['hotPotatoUsedAnswers'] ?? [],
      );
      if (usedAnswers.contains(cleanAnswer)) {
        throw Exception(_l10n.cetteReponseADejaEte);
      }
      usedAnswers.add(cleanAnswer);

      final playerOrder = List<String>.from(
        gameData['playerOrder'] ?? gameData['players'].keys.toList(),
      );
      final currentIdx = playerOrder.indexOf(playerId);
      final nextIdx = (currentIdx + 1) % playerOrder.length;
      final nextPlayerId = playerOrder[nextIdx];

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8,
        applySpeedBonus: true,
      );

      final roundStartedAt =
          ((gameData['hotPotatoRoundStartedAt'] ?? gameData['turnStartTime'])
                  as Timestamp?)
              ?.toDate();
      final timerDuration =
          (gameData['hotPotatoSecondsLeft'] as num?)?.toInt() ??
          (gameData['hotPotatoGlobalDuration'] as num?)?.toInt() ??
          (gameData['turnTimer'] as num?)?.toInt() ??
          30;

      int elapsed =
          roundStartedAt != null
              ? DateTime.now().difference(roundStartedAt).inSeconds
              : 0;
      if (elapsed <= 0) elapsed = 1;
      int secondsLeft = max(0, timerDuration - elapsed);

      if (secondsLeft <= 2 && secondsLeft > 0) {
        _db.collection('users').doc(currentAuthUid).set({
          'unlockedBadges.patate_last_second': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
      _db.collection('users').doc(currentAuthUid).set({
        'badgeProgress.patate_survivor_3': FieldValue.increment(1),
      }, SetOptions(merge: true));

      transaction.update(gameRef, {
        'hotPotatoUsedAnswers': usedAnswers,
        'hotPotatoCurrentPlayerId': nextPlayerId,
        'hotPotatoSecondsLeft': secondsLeft,
        'hotPotatoRoundStartedAt': FieldValue.serverTimestamp(),
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([
          _l10n.aReponduEtPasseLa(
            gameData['players'][playerId]['name'],
            cleanAnswer,
          ),
        ]),
      });
    });
  }

  // =========================================================================
  // 20. PATATE CHAUDE
  // =========================================================================
  Future<void> handleHotPotatoTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;

    if (gameData['gameState'] != 'playing') return;
    if (gameData['roundState'] == 'result') {
      await nextHotPotatoRound(gameCode);
      return;
    }
    if (gameData['roundState'] != 'playing') {
      return;
    }

    if (!_isTurnTimedOut(gameData)) {
      return; // La bombe vient d'être passée, ne pas exploser !
    }

    final loserId = gameData['hotPotatoCurrentPlayerId'];
    if (loserId == null) return;

    final loserName = gameData['players']?[loserId]?['name'] ?? _l10n.joueur;

    await gameRef.update({
      'roundState': 'result',
      'roundLoserId': loserId,
      'players.$loserId.score': FieldValue.increment(1),
      'gameEndReason': _l10n.laBombeAExploseDans(loserName),
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> nextHotPotatoRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? gameData['players'].keys.toList(),
    );
    String gameType = gameData['gameType'] ?? '';

    // Check game-end condition for Categories
    if (gameType == 'Le Jeu des Catégories') {
      int currentRound = gameData['currentRound'] ?? 0;
      List<String> categories = List<String>.from(
        gameData['selectedCategories'] ?? [],
      );
      int maxRounds = max(categories.length, playerOrder.length * 2);
      if (currentRound >= maxRounds) {
        // Find winner (lowest score)
        Map<String, dynamic> players = Map<String, dynamic>.from(
          gameData['players'] ?? {},
        );
        String? winnerId;
        int lowestScore = 999;
        players.forEach((id, data) {
          int score = data['score'] ?? 0;
          if (score < lowestScore) {
            lowestScore = score;
            winnerId = id;
          }
        });
        if (winnerId != null) {
          final wAuth = players[winnerId]?['authUid'] ?? winnerId;
          _db.collection('users').doc(wAuth).set({
            'xp': FieldValue.increment(35),
          }, SetOptions(merge: true));
        }
        String winnerName = players[winnerId]?['name'] ?? _l10n.personne;
        await gameRef.update({
          'gameState': 'gameOver',
          'gameEndReason': _l10n.gagneAvecPoint(
            winnerName,
            lowestScore,
            lowestScore > 1 ? 's' : '',
          ),
        });
        return;
      }
    }

    // Récupération d'une catégorie aléatoire parmi celles sélectionnées par l'hôte ou IA
    List<String> availableCategories;
    if (gameData['aiWords'] != null &&
        (gameData['aiWords'] as List).isNotEmpty) {
      availableCategories = List<String>.from(gameData['aiWords']);
    } else {
      availableCategories = List<String>.from(
        gameData['selectedCategories'] ?? GameData.categoriesGameList,
      );
    }
    String category = _l10n.categorie;
    if (availableCategories.isNotEmpty) {
      category =
          availableCategories[Random().nextInt(availableCategories.length)];
    }

    int duration =
        gameData['hotPotatoUseGlobalTimer'] == true
            ? (gameData['hotPotatoGlobalDuration'] ?? 60)
            : (gameData['turnTimerSeconds'] ?? 30);

    // Pick a different player from the previous one if possible
    String? previousPlayerId = gameData['hotPotatoCurrentPlayerId'];
    String nextPlayerId = playerOrder[Random().nextInt(playerOrder.length)];
    if (playerOrder.length > 1 && nextPlayerId == previousPlayerId) {
      nextPlayerId =
          playerOrder[(playerOrder.indexOf(previousPlayerId!) + 1) %
              playerOrder.length];
    }

    await gameRef.update({
      'currentRound': FieldValue.increment(1),
      'roundState': 'playing',
      'hotPotatoCategory': category,
      'hotPotatoCurrentPlayerId': nextPlayerId,
      'hotPotatoSecondsLeft': duration,
      'hotPotatoUsedAnswers': [],
      'hotPotatoRoundStartedAt': FieldValue.serverTimestamp(),
      'turnStartTime': FieldValue.serverTimestamp(),
      'roundWinnerId': null,
      'gameEndReason': null,
    });
  }

  Future<void> drawUnoCard(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception(_l10n.partieNonTrouvee);

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
      int unoDirection = gameData['unoDirection'] ?? 1;
      List<String> myHand = List<String>.from(
        gameData['unoPlayerHands']?[playerId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      int pendingDraw = gameData['unoPendingDraw'] ?? 0;

      if (playerOrder[currentPlayerIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre5);
      }

      Map<String, dynamic> updates = {};

      if (deck.isEmpty) {
        if (discardPile.length > 1) {
          String topCard = discardPile.removeLast();
          deck.addAll(discardPile..shuffle());
          discardPile = [topCard];
          updates['unoDeck'] = deck;
          updates['unoDiscardPile'] = discardPile;
          updates['unoLog'] = FieldValue.arrayUnion([_l10n.laPiocheEstVideLa]);
        } else {
          throw Exception(_l10n.impossibleDePiocherIlN);
        }
      }

      if (pendingDraw > 0) {
        List<String> drawnCards = [];
        for (int i = 0; i < pendingDraw; i++) {
          if (deck.isNotEmpty) {
            drawnCards.add(deck.removeAt(0));
          } else {
            if (discardPile.length > 1) {
              String topCard = discardPile.removeLast();
              deck.addAll(discardPile..shuffle());
              discardPile = [topCard];
              updates['unoDiscardPile'] = discardPile;
              i--; // Recommencer cette itération avec le nouveau deck
            } else {
              break; // Plus aucune carte à piocher
            }
          }
        }

        myHand.addAll(drawnCards);
        final Map<String, dynamic> allHands = Map<String, dynamic>.from(
          gameData['unoPlayerHands'] ?? {},
        );
        allHands[playerId] = myHand;
        updates['unoPlayerHands'] = allHands;
        updates['unoDeck'] = deck;
        updates['unoPendingDraw'] = 0; // La pénalité est purgée
        updates['unoLog'] = FieldValue.arrayUnion([
          _l10n.aPiocheCarteS(
            players[playerId]?['name'] ?? _l10n.joueur,
            pendingDraw,
          ),
        ]);

        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();

        transaction.update(gameRef, updates);
        return; // Fin de la logique pour la pioche forcée
      }

      String drawnCard = deck.removeAt(0);
      myHand.add(drawnCard);
      final Map<String, dynamic> allHands = Map<String, dynamic>.from(
        gameData['unoPlayerHands'] ?? {},
      );
      allHands[playerId] = myHand;
      updates['unoPlayerHands'] = allHands;
      updates['unoDeck'] = deck;

      if (discardPile.isEmpty) throw Exception(_l10n.laPileDeDefausseEst);
      String topCard = discardPile.last;
      String? wildColor = gameData['unoWildColorChosen'];
      bool canPlayDrawnCard = GameData.canPlayUnoCard(
        drawnCard,
        topCard,
        wildColor,
      );

      if (canPlayDrawnCard) {
        updates['unoLog'] = FieldValue.arrayUnion([
          _l10n.aPiocheUneCarteEt2(players[playerId]?['name'] ?? _l10n.joueur),
        ]);
        updates['unoDrawActionDone'] =
            true; // Indique à l'UI de permettre de jouer la carte
        updates['unoLastDrawnCard'] = drawnCard;
      } else {
        updates['unoLog'] = FieldValue.arrayUnion([
          _l10n.aPiocheUneCarteEt3(players[playerId]?['name'] ?? _l10n.joueur),
        ]);
        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> callUno(
    String gameCode,
    String callerId,
    String targetId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception(_l10n.partieNonTrouvee);

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid de l'appelant
      final callerAuthUid = players[callerId]?['authUid'] ?? callerId;
      if (currentAuthUid != callerAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      Map<String, dynamic> unoPlayerHands = Map<String, dynamic>.from(
        gameData['unoPlayerHands'] ?? {},
      );
      List<String> targetHand = List<String>.from(
        unoPlayerHands[targetId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      Map<String, dynamic> unoCalledUno = Map<String, dynamic>.from(
        gameData['unoCalledUno'] ?? {},
      );
      String? lastActionPlayerId = gameData['unoLastActionPlayerId'];

      if (targetHand.length != 1) {
        throw Exception(
          _l10n.nAPas1Carte1(players[targetId]?['name'] ?? _l10n.leJoueur),
        );
      }
      Map<String, dynamic> updates = {};

      if (callerId != targetId &&
          !(unoCalledUno[targetId] ?? false) &&
          lastActionPlayerId == targetId) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          callerId,
          25,
          applySpeedBonus: true,
        );
        List<String> penaltyCards = [];
        for (int i = 0; i < 2; i++) {
          if (deck.isNotEmpty) {
            penaltyCards.add(deck.removeAt(0));
          } else {
            break;
          }
        }
        targetHand.addAll(penaltyCards);
        final Map<String, dynamic> allHands = Map<String, dynamic>.from(
          gameData['unoPlayerHands'] ?? {},
        );
        allHands[targetId] = targetHand;
        updates['unoPlayerHands'] = allHands;
        updates['unoDeck'] = deck;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          _l10n.aCrieContreUnoPioche1(
            players[callerId]?['name'] ?? _l10n.joueur,
            players[targetId]?['name'] ?? _l10n.joueur,
          ),
        ]);

        updates['unoCalledUno.$targetId'] = true;
      } else if (callerId == targetId && targetHand.length == 1) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          callerId,
          10,
          applySpeedBonus: true,
        );
        updates['unoCalledUno.$targetId'] = true;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          _l10n.aDitUno1(players[targetId]?['name'] ?? _l10n.joueur),
        ]);
      } else {
        throw Exception(_l10n.appelUnoInvalide);
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> chooseWildColor(
    String gameCode,
    String playerId,
    String chosenColor,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception(_l10n.partieNonTrouvee);

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (currentAuthUid != voterAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;

      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre6);
      }

      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      if (discardPile.isEmpty) throw Exception(_l10n.laPileDeDefausseEst);
      String topCard = discardPile.last;
      String topCardValue = GameData.getUnoCardValue(topCard);

      if (GameData.unoWildCards.contains(topCardValue)) {
        transaction.update(gameRef, {
          'unoWildColorChosen': chosenColor,
          'unoLog': FieldValue.arrayUnion([
            _l10n.aChoisiLaCouleur(
              players[playerId]?['name'] ?? _l10n.joueur,
              chosenColor,
            ),
          ]),
        });
      } else {
        throw Exception(_l10n.vousNePouvezPasChoisir);
      }
    });
  }

  Future<void> nextRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    String gameType = gameData['gameType'];
    String difficulty = gameData['difficulty'];
    Map<String, dynamic> players = gameData['players'];
    if (players.keys.isEmpty) return;

    final random = Random();

    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? -1;

    if (playerOrder.isEmpty) {
      print(
        "ERREUR CRITIQUE: playerOrder est vide dans nextRound. Impossible de continuer.",
      );
      return;
    }

    final int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
    String activePlayerId = playerOrder[nextPlayerIndex];

    String question = _l10n.questionNonTrouvee;
    String? currentTargetPlayerId;
    String? liarId;
    String? undercoverId;
    String? mrWhiteId;
    Map<String, dynamic> secretData = {};
    String? roundData;
    String roundState = 'answering';
    String? memeUrl;

    final List<dynamic>? rawAiWords = gameData['aiWords'] as List<dynamic>?;
    final List<String>? aiWordPool =
        (rawAiWords != null && rawAiWords.isNotEmpty)
            ? rawAiWords.map((e) => e.toString()).toList()
            : null;

    if (gameType == 'Le Juge') {
      List<String> questions =
          aiWordPool ??
          GameWords.judgeData[difficulty] ??
          GameWords.judgeData['soft']!;
      question = questions[random.nextInt(questions.length)];
      currentTargetPlayerId = activePlayerId; // Le joueur actif est la cible
      question = question.replaceAll(
        '{player}',
        players[currentTargetPlayerId]['name'],
      );
      roundState = 'answering';
    } else if (gameType == 'Qui Pourrait le Plus ?') {
      List<String> questions =
          aiWordPool ??
          GameWords.whoIsMostLikely[difficulty] ??
          GameWords.whoIsMostLikely['soft']!;
      question = _l10n.quiPourraitLePlus3(
        questions[random.nextInt(questions.length)],
      );
      roundState = 'voting';
    } else if (gameType == 'Le Menteur') {
      List<String> prompts =
          aiWordPool ??
          GameWords.liarData[difficulty] ??
          GameWords.liarData['soft']!;
      question = prompts[random.nextInt(prompts.length)];
      roundState = 'answering';

      if (gameData['isSimplifiedLiar'] == true) {
        liarId = null;
        await gameRef.update({
          'storyTruths': {},
          'playerOrder': List<String>.from(players.keys.toList())..shuffle(),
          'revealIndex': 0,
        });
      } else {
        // MODE CLASSIQUE SÉCURISÉ : On choisit le menteur secrètement
        String secretLiarId = playerOrder[random.nextInt(playerOrder.length)];
        for (var pId in players.keys) {
          await gameRef.collection('private_data').doc(pId).set({
            'isLiar': (pId == secretLiarId),
            'role': (pId == secretLiarId) ? _l10n.menteur : _l10n.honnete,
          });
        }
        liarId = null;
      }
    } else if (gameType == 'Infiltré & Mr. White') {
      if (playerOrder.length >= 3) {
        List<String> wordPairs =
            aiWordPool ??
            GameWords.undercoverData[difficulty]?['wordPairs'] ??
            GameWords.undercoverData['soft']!['wordPairs']!;
        String pair = wordPairs[random.nextInt(wordPairs.length)];
        List<String> words =
            pair.contains(':') ? pair.split(':') : [pair, pair];

        List<String> shuffledRoles = List.from(playerOrder)..shuffle();
        String secUndercoverId = shuffledRoles[0];
        String secMrWhiteId = shuffledRoles[1];

        question = _l10n.decrivezVotreMotSecretEn;
        for (var pId in players.keys) {
          String pRole =
              (pId == secUndercoverId)
                  ? 'Infiltré'
                  : (pId == secMrWhiteId ? 'Mr. White' : 'Civil');
          String pWord =
              (pId == secUndercoverId)
                  ? words[1]
                  : (pId == secMrWhiteId ? _l10n.vousNAvezPasDe : words[0]);

          await gameRef.collection('private_data').doc(pId).set({
            'role': pRole,
            'secretWord': pWord,
            'specialAbilities': <String>[],
          });
        }
        undercoverId = null;
        mrWhiteId = null;
        secretData = {};
        roundData = null;
        roundState = 'answering';
      } else {
        question = _l10n.pasAssezDeJoueursPour;
        roundState = 'result';
      }
    } else if (gameType == 'Synonyme ou Banni') {
      List<String> words =
          aiWordPool ??
          GameWords.synonymOrBanned[difficulty]?['words'] ??
          GameWords.synonymOrBanned['soft']!['words']!;
      String word = words[random.nextInt(words.length)];
      question = _l10n.trouvezLeMeilleurSynonymePour1(word);
      roundData = word;
      roundState = 'answering';
    } else if (gameType == 'Le Roi des Mèmes') {
      memeUrl = await _fetchRandomMemeUrl();
      question = _l10n.ajouteLaDescriptionLaPlus;
      roundState = 'answering';
    } else if (gameType == 'Skull') {
      await nextSkullRound(gameCode);
      return;
    } else if (gameType == 'Uno') {
      List<String> deck = GameData.generateUnoDeck();
      Map<String, List<String>> playerHands = {};
      int startingCards = gameData['unoStartingCards'] ?? 7;

      Map<String, dynamic> currentScores = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      Map<String, int> updatedScores = {};
      currentScores.forEach((id, data) {
        updatedScores[id] = data['score'] ?? 0;
      });

      String? overallWinnerId;
      for (var entry in updatedScores.entries) {
        if (entry.value >= 500) {
          overallWinnerId = entry.key;
          break;
        }
      }

      if (overallWinnerId != null) {
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': overallWinnerId,
          'gameEndReason': _l10n.aAtteintPointsEtGagne(
            players[overallWinnerId]?['name'] ?? '',
            updatedScores[overallWinnerId] ?? 0,
          ),
        });
        return;
      }

      for (String pId in playerOrder) {
        playerHands[pId] = [];
        for (int i = 0; i < startingCards; i++) {
          playerHands[pId]!.add(deck.removeAt(0));
        }
      }

      String firstCard;
      do {
        firstCard = deck.removeAt(0);
      } while (GameData.getUnoCardColor(firstCard) == 'wild');

      await gameRef.update({
        'unoDeck': deck,
        'unoDiscardPile': [firstCard],
        'unoPlayerHands': playerHands,
        'unoCurrentPlayerIndex': 0,
        'unoDirection': 1,
        'unoPendingDraw': 0,
        'unoWildColorChosen': null,
        'unoCalledUno': {for (var pId in playerOrder) pId: false},
        'unoLastActionPlayerId': null,
        'gameState': 'playing',
        'roundState': 'playing_turn',
        'unoLog': FieldValue.arrayUnion([_l10n.uneNouvelleMancheDeUno]),
        'turnStartTime': FieldValue.serverTimestamp(),
      });
      await _applyFirstUnoCardEffect(gameRef, firstCard, playerOrder[0]);
      return; // On arrête l'exécution ici pour Uno
    }

    final updateMap = {
      'currentPlayerIndex': nextPlayerIndex,
      'currentRound': FieldValue.increment(1),
      'roundState': roundState,
      'currentQuestion': question,
      'currentTargetPlayerId': currentTargetPlayerId,
      'activePlayerId': activePlayerId,
      'liarId': liarId,
      'undercoverId': undercoverId,
      'mrWhiteId': mrWhiteId,
      'secretData': secretData,
      'roundData': roundData,
      'answers': {},
      'votes': {},
      'accusations': {},
      'roundWinnerId': null,
      'voteResults': null,
      'gameEndReason': null,
      'memeUrl': memeUrl,
      'turnStartTime': FieldValue.serverTimestamp(),
    };

    if (currentPlayerIndex > -1) {
      String oldPlayerId = playerOrder[currentPlayerIndex];
      updateMap['inactiveTurnCounts.$oldPlayerId'] = 0;
    }

    await gameRef.update(updateMap);
  }

  int _nextSkullActiveIndex(
    List<String> playerOrder,
    int currentIndex,
    Map<String, dynamic> players, [
    Set<String> blockedPlayers = const <String>{},
  ]) {
    if (playerOrder.isEmpty) return -1;

    for (int step = 1; step <= playerOrder.length; step++) {
      final int nextIndex = (currentIndex + step) % playerOrder.length;
      final String candidateId = playerOrder[nextIndex];
      final Map<String, dynamic> candidatePlayer = Map<String, dynamic>.from(
        players[candidateId] ?? {},
      );
      final int cardsInHand = candidatePlayer['cardsInHand'] ?? 0;
      final bool isOut = candidatePlayer['isOut'] == true;

      if (!isOut && cardsInHand > 0 && !blockedPlayers.contains(candidateId)) {
        return nextIndex;
      }
    }

    return -1;
  }

  List<Map<String, dynamic>> _buildSkullRevealSequence(
    List<String> playerOrder,
    String challengerId,
    Map<String, dynamic> skullMats,
  ) {
    if (playerOrder.isEmpty) return [];

    final int challengerIndex = playerOrder.indexOf(challengerId);
    final List<String> orderedPlayers = [
      ...playerOrder.sublist(challengerIndex < 0 ? 0 : challengerIndex),
      ...playerOrder.sublist(0, challengerIndex < 0 ? 0 : challengerIndex),
    ];

    final List<Map<String, dynamic>> sequence = [];
    for (final ownerId in orderedPlayers) {
      final List<Map<String, dynamic>> matCards =
          List<Map<String, dynamic>>.from(
            (skullMats[ownerId] as List? ?? []).map(
              (card) => Map<String, dynamic>.from(card as Map),
            ),
          );
      for (int index = matCards.length - 1; index >= 0; index--) {
        if (matCards[index]['revealed'] == true) continue;
        sequence.add({
          'ownerId': ownerId,
          'index': index,
          'type': matCards[index]['type'],
        });
      }
    }

    return sequence;
  }

  Future<void> placeSkullCard(
    String gameCode,
    String playerId,
    String cardType, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (!isAuto && players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty ||
          currentPlayerIndex < 0 ||
          currentPlayerIndex >= playerOrder.length ||
          playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
        gameData['skullHands'] ?? {},
      );
      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> myHand = List<String>.from(skullHands[playerId] ?? []);
      if (!myHand.contains(cardType)) {
        throw Exception(_l10n.vousNAvezPasCette);
      }

      myHand.remove(cardType);
      skullHands[playerId] = myHand;

      final List<Map<String, dynamic>> myMat = List<Map<String, dynamic>>.from(
        (skullMats[playerId] as List? ?? []).map(
          (card) => Map<String, dynamic>.from(card as Map),
        ),
      );
      myMat.add({'type': cardType, 'revealed': false});
      skullMats[playerId] = myMat;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        3,
        applySpeedBonus: true,
      );

      players[playerId] = {
        ...Map<String, dynamic>.from(players[playerId] ?? {}),
        'cardsInHand': myHand.length,
        'isOut': false,
      };

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
      );

      final Map<String, dynamic> updates = {
        'skullHands': skullHands,
        'skullMats': skullMats,
        'players': players,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['gameEndReason'] = _l10n.plusAucunJoueurActif;
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> startSkullBid(
    String gameCode,
    String playerId,
    int bid, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (!isAuto && players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> activePlayers =
          playerOrder.where((pId) {
            final data = Map<String, dynamic>.from(players[pId] ?? {});
            return data['isOut'] != true && (data['cardsInHand'] ?? 0) > 0;
          }).toList();

      final bool allActivePlaced = activePlayers.every((pId) {
        final List mat = skullMats[pId] as List? ?? [];
        return mat.isNotEmpty;
      });

      if (!allActivePlaced) {
        throw Exception(_l10n.chaqueJoueurActifDoitPoser);
      }

      final int totalCardsOnTables = skullMats.values.fold<int>(0, (
        sum,
        cards,
      ) {
        return sum + (cards is List ? cards.length : 0);
      });

      if (bid < 1 || bid > totalCardsOnTables) {
        throw Exception(_l10n.enchereInvalide);
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8, // +8 XP pour l'ouverture de l'enchère
        applySpeedBonus: true,
      );

      final Map<String, dynamic> updates = {
        'roundState': 'bidding',
        'skullCurrentBid': bid,
        'skullHighestBidderId': playerId,
        'skullPassedPlayers': <String>[],
        'skullNextStarterId': playerId,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (bid >= totalCardsOnTables) {
        final updatedGameData = {...gameData, ...updates};
        await _resolveSkullChallengeTransaction(
          transaction,
          gameRef,
          updatedGameData,
        );
        return;
      }

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
        {playerId},
      );
      if (nextIndex == -1) {
        final updatedGameData = {...gameData, ...updates};
        await _resolveSkullChallengeTransaction(
          transaction,
          gameRef,
          updatedGameData,
        );
        return;
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> raiseSkullBid(String gameCode, String playerId, int bid) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
