  Future<void> submitSimplifiedLiarVote(
    String gameCode,
    String voterId,
    String storyOwnerId,
    String voteValue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final gameRef = _db.collection('games').doc(gameCode);

    bool allVotesIn = false;
    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting' &&
          gameData['roundState'] != 'reveal_and_vote') {
        return;
      }

      _verifyPlayerAuth(gameData, voterId);

      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      final storyVotes = Map<String, dynamic>.from(votes[storyOwnerId] ?? {});
      storyVotes[voterId] = voteValue;
      votes[storyOwnerId] = storyVotes;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final expectedVotesPerStory =
          players.length - 1; // Tous les joueurs sauf l'auteur

      final voteMode = gameData['liarVoteMode'] ?? 'simultaneous';
      final playerOrder = List<String>.from(
        gameData['playerOrder'] ?? players.keys.toList(),
      );
      final revealIndex = (gameData['revealIndex'] as num?)?.toInt() ?? 0;
      final updates = <String, dynamic>{'votes': votes};

      if (voteMode == 'turn_by_turn') {
        if (storyVotes.length >= expectedVotesPerStory) {
          if (revealIndex + 1 < playerOrder.length) {
            updates['revealIndex'] = revealIndex + 1;
            updates['turnStartTime'] = FieldValue.serverTimestamp();
          } else {
            allVotesIn = true;
          }
        }
      } else {
        int completedStories = 0;
        for (final pId in players.keys) {
          final sVotes = Map<String, dynamic>.from(votes[pId] ?? {});
          if (sVotes.length >= expectedVotesPerStory) {
            completedStories++;
          }
        }
        if (completedStories >= players.length) {
          allVotesIn = true;
        }
      }

      transaction.update(gameRef, updates);
    });

    if (allVotesIn) {
      final snap = await gameRef.get();
      if (snap.exists) {
        await _tallyVotes(gameRef, snap.data() as Map<String, dynamic>);
      }
    }
  }

  Future<void> submitUndercoverVote(
    String gameCode,
    String voterId,
    String targetPlayerId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final gameRef = _db.collection('games').doc(gameCode);
    bool shouldTally = false;

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      _verifyPlayerAuth(gameData, voterId);

      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      votes[voterId] = targetPlayerId;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final alivePlayers =
          players.entries
              .where((e) => e.value['isEliminated'] != true)
              .map((e) => e.key)
              .toList();

      if (votes.length >= alivePlayers.length) {
        shouldTally = true;
      }

      transaction.update(gameRef, {'votes': votes});
    });

    if (shouldTally) {
      final snap = await gameRef.get();
      if (snap.exists) {
        await _tallyVotes(gameRef, snap.data() as Map<String, dynamic>);
      }
    }
  }

  Future<void> validateMrWhiteGuess(String gameCode, String guess) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    final cleanGuess =
        sanitizeUserInput(guess, maxLength: 40).trim().toLowerCase();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      final civilianWord =
          (gameData['civilianWord'] as String? ?? '').trim().toLowerCase();
      final isCorrect = cleanGuess == civilianWord;

      final updates = <String, dynamic>{
        'mrWhiteGuess': cleanGuess,
        'mrWhiteGuessCorrect': isCorrect,
        'roundState': 'result',
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isCorrect) {
        updates['roundWinnerId'] = 'mr_white';
        updates['gameEndReason'] = _l10n.mrWhiteADevineLe1(civilianWord);
        final mrWhiteId = gameData['mrWhiteId'];
        if (mrWhiteId != null) {
          updates['players.$mrWhiteId.score'] = FieldValue.increment(3);
        }
      } else {
        updates['roundWinnerId'] = 'civilians';
        updates['gameEndReason'] = _l10n.mrWhiteAEchoueA1(civilianWord);
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> _tallyVotes(
    DocumentReference gameRef,
    Map<String, dynamic> initialGameData,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting' &&
          gameData['roundState'] != 'reveal_and_vote') {
        return;
      }

      final votes = Map.from(gameData['votes'] as Map<String, dynamic>);
      final gameType = gameData['gameType'];
      final updates = <String, dynamic>{};

      if (gameType == 'Le Menteur' && gameData['isSimplifiedLiar'] == true) {
        final storyTruths = Map.from(
          gameData['storyTruths'] as Map<String, dynamic>,
        );
        final players = Map.from(gameData['players'] as Map<String, dynamic>);
        Map<String, int> roundPoints = {for (var pId in players.keys) pId: 0};

        votes.forEach((storyOwnerId, storyVotesMap) {
          final storyVotes = Map.from(storyVotesMap as Map<String, dynamic>);
          final bool actualTruth = storyTruths[storyOwnerId] ?? false;

          storyVotes.forEach((voterId, voteValue) {
            final bool guessedCorrectly =
                (voteValue == 'Vrai' && actualTruth) ||
                (voteValue == 'Faux' && !actualTruth);
            if (guessedCorrectly) {
              roundPoints[voterId] = (roundPoints[voterId] ?? 0) + 1;
            } else {
              roundPoints[storyOwnerId] = (roundPoints[storyOwnerId] ?? 0) + 1;
            }
          });
        });

        roundPoints.forEach((playerId, points) {
          if (points > 0) {
            updates['players.$playerId.score'] = FieldValue.increment(points);
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              playerId,
              points * 10,
              applySpeedBonus: false,
            );
          }
        });
        updates['voteResults'] = votes;
      } else if (gameType == 'Le Roi des Mèmes') {
        Map<String, int> voteCounts = {};
        votes.forEach((voter, votedFor) {
          voteCounts[votedFor] = (voteCounts[votedFor] ?? 0) + 1;
        });

        String? mostVotedPlayerId;
        int maxVotes = -1;
        voteCounts.forEach((playerId, count) {
          if (count > maxVotes) {
            maxVotes = count;
            mostVotedPlayerId = playerId;
          }
        });

        if (mostVotedPlayerId == null) {
          final answers = Map<String, dynamic>.from(gameData['answers'] ?? {});
          if (answers.isNotEmpty) {
            final answerKeys = answers.keys.toList();
            mostVotedPlayerId = answerKeys[Random().nextInt(answerKeys.length)];
          }
        }

        if (mostVotedPlayerId != null) {
          updates['players.$mostVotedPlayerId.score'] = FieldValue.increment(1);
          updates['roundWinnerId'] = mostVotedPlayerId;
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            mostVotedPlayerId!,
            25,
            applySpeedBonus: false,
          );
          updates['gameEndReason'] = _l10n.laDescriptionLaPlusDrole;
        } else {
          updates['gameEndReason'] = _l10n.aucuneDescriptionNAEte1;
        }
        updates['voteResults'] = voteCounts;
      } else if (gameType == 'Qui Pourrait le Plus ?') {
        final Map<String, int> voteCounts = {};
        for (final target in votes.values) {
          voteCounts[target as String] = (voteCounts[target] ?? 0) + 1;
        }

        int maxVotes = 0;
        List<String> topVoted = [];
        voteCounts.forEach((target, count) {
          if (count > maxVotes) {
            maxVotes = count;
            topVoted = [target];
          } else if (count == maxVotes) {
            topVoted.add(target);
          }
        });

        if (topVoted.length == 1) {
          final winner = topVoted.first;
          updates['roundWinnerId'] = winner;
          updates['players.$winner.score'] = FieldValue.increment(1);
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            winner,
            15,
            applySpeedBonus: false,
          );
        } else {
          updates['roundWinnerId'] = null;
          updates['gameEndReason'] = _l10n.egaliteParfaiteAucunPointAttribue;
        }
        updates['voteResults'] = voteCounts;
      } else if (gameType == 'Synonyme ou Banni') {
        final Map<String, int> banCounts = {};
        for (final t in votes.values) {
          banCounts[t as String] = (banCounts[t] ?? 0) + 1;
        }

        int maxVotes = 0;
        List<String> topBanned = [];
        banCounts.forEach((target, count) {
          if (count > maxVotes) {
            maxVotes = count;
            topBanned = [target];
          } else if (count == maxVotes) {
            topBanned.add(target);
          }
        });

        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        if (topBanned.isEmpty) {
          final candidateIds = players.keys.toList();
          if (candidateIds.isNotEmpty) {
            topBanned = [candidateIds[Random().nextInt(candidateIds.length)]];
          }
        } else if (topBanned.length > 1) {
          topBanned = [topBanned[Random().nextInt(topBanned.length)]];
        }

        if (topBanned.isNotEmpty) {
          final loserId = topBanned.first;
          updates['roundLoserId'] = loserId;
          updates['roundWinnerId'] = null;

          players.keys.where((id) => id != loserId).forEach((winnerId) {
            updates['players.$winnerId.score'] = FieldValue.increment(1);
            _db
                .collection('users')
                .doc(players[winnerId]?['authUid'] ?? winnerId)
                .set({
                  'unlockedBadges.synonyme_unbanned':
                      FieldValue.serverTimestamp(),
                }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              winnerId,
              15,
              applySpeedBonus: false,
            );
          });
        }
        updates['voteResults'] = banCounts;
      } else {
        Map<String, int> voteCounts = {};
        votes.forEach((voter, votedFor) {
          voteCounts[votedFor] = (voteCounts[votedFor] ?? 0) + 1;
        });

        String? mostVotedPlayerId;
        int maxVotes = 0;
        voteCounts.forEach((playerId, count) {
          if (count > maxVotes) {
            maxVotes = count;
            mostVotedPlayerId = playerId;
          }
        });

        if (gameType == 'La Patate Chaude' && mostVotedPlayerId != null) {
          updates['players.$mostVotedPlayerId.score'] = FieldValue.increment(1);
          updates['roundWinnerId'] = mostVotedPlayerId;
        } else if (gameType == 'Le Menteur') {
          String? actualLiarId = gameData['liarId'];
          if (actualLiarId == null) {
            final privSnap = await gameRef.collection('private_data').get();
            for (var doc in privSnap.docs) {
              if (doc.data()['isLiar'] == true) {
                actualLiarId = doc.id;
                break;
              }
            }
          }
          if (actualLiarId != null) {
            updates['liarId'] = actualLiarId;
            int fooledCount = 0;
            votes.forEach((voterId, votedId) {
              if (votedId == actualLiarId) {
                updates['players.$voterId.score'] = FieldValue.increment(2);
                creditPlayerXp(
                  transaction,
                  gameRef,
                  gameData,
                  voterId,
                  15,
                  applySpeedBonus: false,
                );
              } else {
                fooledCount++;
              }
            });
            if (fooledCount > 0) {
              updates['players.$actualLiarId.score'] = FieldValue.increment(
                fooledCount,
              );
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                actualLiarId,
                fooledCount * 12,
                applySpeedBonus: false,
              );
            }
          }
        } else if (gameType == 'Infiltré & Mr. White') {
          String? undercoverId = gameData['undercoverId'];
          String? mrWhiteId = gameData['mrWhiteId'];
          if (undercoverId == null || mrWhiteId == null) {
            final privSnap = await gameRef.collection('private_data').get();
            for (var doc in privSnap.docs) {
              if (doc.data()['role'] == 'Infiltré') undercoverId = doc.id;
              if (doc.data()['role'] == 'Mr. White') mrWhiteId = doc.id;
            }
          }
          if (undercoverId != null) updates['undercoverId'] = undercoverId;
          if (mrWhiteId != null) updates['mrWhiteId'] = mrWhiteId;

          if (mostVotedPlayerId == undercoverId) {
            updates['roundWinnerId'] = 'civilians_and_mrwhite';
            (gameData['players'] as Map).keys
                .where((pId) => pId != undercoverId)
                .forEach((pId) {
                  updates['players.$pId.score'] = FieldValue.increment(1);
                  creditPlayerXp(
                    transaction,
                    gameRef,
                    gameData,
                    pId.toString(),
                    20,
                    applySpeedBonus: false,
                  );
                });
          } else if (mostVotedPlayerId == mrWhiteId) {
            updates['roundWinnerId'] = 'civilians_and_undercover';
            (gameData['players'] as Map).keys
                .where((pId) => pId != mrWhiteId)
                .forEach((pId) {
                  updates['players.$pId.score'] = FieldValue.increment(1);
                  creditPlayerXp(
                    transaction,
                    gameRef,
                    gameData,
                    pId.toString(),
                    20,
                    applySpeedBonus: false,
                  );
                });
          } else {
            updates['roundWinnerId'] = 'impostors';
            if (undercoverId != null) {
              updates['players.$undercoverId.score'] = FieldValue.increment(2);
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                undercoverId,
                30,
                applySpeedBonus: false,
              );
            }
            if (mrWhiteId != null) {
              updates['players.$mrWhiteId.score'] = FieldValue.increment(2);
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                mrWhiteId,
                30,
                applySpeedBonus: false,
              );
            }
          }
        }
      }

      updates['roundState'] = 'result';
      updates['turnStartTime'] = FieldValue.serverTimestamp();
      transaction.update(gameRef, updates);
    });
  }

  Future<void> selectWinningAnswer(
    String gameCode,
    String winnerPlayerId, {
    String? judgePlayerId,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final currentJudgeId = gameData['currentTargetPlayerId'] ?? judgePlayerId;
      if (currentJudgeId == null || !players.containsKey(currentJudgeId)) {
        throw Exception(_l10n.jugeIntrouvable);
      }

      final judgeAuthUid =
          players[currentJudgeId]?['authUid'] ?? currentJudgeId;
      if (!isAuto && currentAuthUid != judgeAuthUid) {
        throw Exception(_l10n.seulLeJugeEnTitre);
      }

      final answers = Map<String, dynamic>.from(gameData['answers'] ?? {});
      if (!answers.containsKey(winnerPlayerId)) {
        throw Exception(_l10n.ceJoueurNAPas1);
      }

      final winnerName = players[winnerPlayerId]?['name'] ?? _l10n.joueur;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        winnerPlayerId,
        20,
        applySpeedBonus: false,
      );

      transaction.update(gameRef, {
        'players.$winnerPlayerId.score': FieldValue.increment(1),
        'roundState': 'result',
        'roundWinnerId': winnerPlayerId,
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([_l10n.remporteLaManche(winnerName)]),
      });
    });
  }

  Future<void> sendChatMessage(
    String gameCode,
    String playerId,
    String message,
    String chatType,
  ) async {
    final cleanMessage = message.trim();
    if (cleanMessage.isEmpty) return;
    final safeMessage =
        cleanMessage.length > 150
            ? cleanMessage.substring(0, 150)
            : cleanMessage;

    DocumentReference gameRef = _db.collection('games').doc(gameCode);

    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;

    var gameData = gameSnap.data() as Map<String, dynamic>;
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    var players = Map<String, dynamic>.from(gameData['players'] ?? {});
    String playerName =
        playerData[playerId]?['name'] ??
        players[playerId]?['name'] ??
        _l10n.inconnu;

    // Écriture unique dans la sous-collection 'chat' pour éviter la saturation du document principal (1 Mo)
    await gameRef.collection('chat').add({
      'senderId': playerId,
      'senderName': playerName,
      'text': safeMessage,
      'message': safeMessage,
      'chatType': chatType,
      'timestamp': FieldValue.serverTimestamp(),
    });

    // Déclenche la vérification du mot pour le Loup Bavard
    await handleLoupBavardChat(gameCode, playerId, safeMessage);
  }

  Future<void> _startZeroPointeRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    List<int> deck = [];

    deck.addAll(List.generate(4, (_) => -2));
    deck.addAll(List.generate(6, (_) => -1));
    deck.addAll(List.generate(10, (_) => 0));

    for (int i = 1; i <= 12; i++) {
      deck.addAll(List.generate(10, (_) => i));
    }
    deck.shuffle();

    Map<String, dynamic> playerGrids = {};
    Map<String, dynamic> totalScores = Map.from(gameData['totalScores'] ?? {});
    Map<String, int> revealedCardsCount = {};

    for (String pId in playerIds) {
      List<Map<String, dynamic>> grid = [];
      for (int i = 0; i < 12; i++) {
        grid.add({'value': deck.removeAt(0), 'revealed': false});
      }
      playerGrids[pId] = grid;

      if (!totalScores.containsKey(pId)) {
        totalScores[pId] = 0;
      }
      revealedCardsCount[pId] = 0;
    }

    List<int> discardPile = [deck.removeAt(0)];

    await gameRef.update({
      'gameState': 'playing',
      'roundState':
          'revealing_initial', // Phase où chaque joueur retourne 2 cartes
      'deck': deck,
      'playerGrids': playerGrids,
      'discardPile': discardPile,
      'playerOrder': playerIds,
      'currentPlayerId': playerIds.first,
      'drawnCard': null,
      'roundEnderId': null,
      'roundScores': {},
      'totalScores': totalScores, // Garder les scores totaux
      'revealedInitialCardsCount': revealedCardsCount,
      'gameLog': [_l10n.laPartieDeZeroPointe],
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> revealInitialZeroPointeCard(
    String gameCode,
    String playerId,
    int cardIndex,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      if (gameData['roundState'] != 'revealing_initial') return;

      var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
      var counts = Map<String, dynamic>.from(
        gameData['revealedInitialCardsCount'] ?? {},
      );

      var playerGrid =
          (grids[playerId] as List)
              .map((e) => Map<String, dynamic>.from(e as Map))
              .toList();

      if ((counts[playerId] ?? 0) < 2 &&
          playerGrid[cardIndex]['revealed'] == false) {
        playerGrid[cardIndex]['revealed'] = true;
        grids[playerId] = playerGrid;
        counts[playerId] = (counts[playerId] ?? 0) + 1;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          2,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'playerGrids': grids,
          'revealedInitialCardsCount': counts,
        });
      }

      bool allReady = true;
      (gameData['players'] as Map).keys.forEach((pId) {
        if ((counts[pId] ?? 0) < 2) {
          allReady = false;
        }
      });

      if (allReady) {
        transaction.update(gameRef, {
          'roundState': 'player_turn',
          'gameLog': FieldValue.arrayUnion([_l10n.toutLeMondeARevele]),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> takeDiscardZeroPointe(
    String gameCode,
    String playerId,
    int gridIndexToReplace,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'player_turn') {
        return;
      }

      var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
      var playerGrid =
          (grids[playerId] as List)
              .map((e) => Map<String, dynamic>.from(e as Map))
              .toList();
      var discardPile = List<int>.from(gameData['discardPile'] ?? []);
      if (discardPile.isEmpty) return;

      int takenCard = discardPile.removeLast();
      int replacedCardValue = playerGrid[gridIndexToReplace]['value'];
      if (replacedCardValue == -100) {
        return; // Ne pas remplacer une case de colonne éliminée
      }

      playerGrid[gridIndexToReplace]['value'] = takenCard;
      playerGrid[gridIndexToReplace]['revealed'] = true;
      grids[playerId] = playerGrid;
      discardPile.add(replacedCardValue);

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        2,
        applySpeedBonus: true,
      );

      transaction.update(gameRef, {
        'playerGrids': grids,
        'discardPile': discardPile,
      });

      gameData['playerGrids'] = grids;
      await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
    });
  }

  Future<void> drawFromDeckZeroPointe(String gameCode, String playerId) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'player_turn') {
        return;
      }

      var deck = List<int>.from(gameData['deck'] ?? []);
      var discardPile = List<int>.from(gameData['discardPile'] ?? []);

      // Recyclage automatique si pioche vide
      if (deck.isEmpty) {
        if (discardPile.length > 1) {
          int topDiscard = discardPile.removeLast();
          deck = List<int>.from(discardPile)..shuffle();
          discardPile = [topDiscard];
        } else {
          throw Exception(_l10n.plusAucuneCarteDisponible);
        }
      }

      int drawnCard = deck.removeAt(0);

      transaction.update(gameRef, {
        'deck': deck,
        'discardPile': discardPile,
        'drawnCard': drawnCard,
        'roundState': 'drawn_card_phase',
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> useDrawnCardZeroPointe(
    String gameCode,
    String playerId,
    int gridIndexToReplace,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'drawn_card_phase') {
        return;
      }

      var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
      var playerGrid =
          (grids[playerId] as List)
              .map((e) => Map<String, dynamic>.from(e as Map))
              .toList();
      var discardPile = List<int>.from(gameData['discardPile'] ?? []);
      int drawnCard = gameData['drawnCard'];

      int replacedCardValue = playerGrid[gridIndexToReplace]['value'];
      if (replacedCardValue == -100) {
        return; // Ne pas remplacer une case de colonne éliminée
      }
      playerGrid[gridIndexToReplace]['value'] = drawnCard;
      playerGrid[gridIndexToReplace]['revealed'] = true;
      grids[playerId] = playerGrid;
      discardPile.add(replacedCardValue);

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        2,
        applySpeedBonus: true,
      );

      transaction.update(gameRef, {
        'playerGrids': grids,
        'discardPile': discardPile,
        'drawnCard': null,
      });

      gameData['playerGrids'] = grids;
      await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
    });
  }

  Future<void> discardDrawnCardZeroPointe(
    String gameCode,
    String playerId,
    int gridIndexToReveal,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'drawn_card_phase') {
        return;
      }

      var grids = Map<String, dynamic>.from(gameData['playerGrids']);
      var playerGrid = List<Map<String, dynamic>>.from(
        (grids[playerId] as List).map(
          (e) => Map<String, dynamic>.from(e as Map),
        ),
      );
      var discardPile = List<int>.from(gameData['discardPile']);
      int drawnCard = gameData['drawnCard'];

      if (playerGrid[gridIndexToReveal]['revealed'] == true ||
          playerGrid[gridIndexToReveal]['value'] == -100) {
        throw Exception(_l10n.vousDevezChoisirUneCarte);
      }

      discardPile.add(drawnCard);
      playerGrid[gridIndexToReveal]['revealed'] = true;
      grids[playerId] = playerGrid;

      transaction.update(gameRef, {
        'playerGrids': grids,
        'discardPile': discardPile,
        'drawnCard': null,
      });

      gameData['playerGrids'] = grids;
      await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
    });
  }

  Future<void> _startPokerHand(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds =
        players.keys.toList(); // Ne pas mélanger pour garder l'ordre des blinds

    Map<String, dynamic> playerData = Map.from(gameData['playerData'] ?? {});
    bool isFirstHand = playerData.isEmpty;
    if (isFirstHand) {
      int startChips = gameData['startChips'] ?? 1000;
      for (String pId in playerIds) {
        playerData[pId] = {
          'name': players[pId]['name'],
          'chips': startChips,
          'hand': [],
          'currentBet': 0,
          'totalBet': 0,
          'status': 'active', // 'active', 'folded', 'all-in'
        };
      }
    } else {
      playerData.forEach((pId, data) {
        playerData[pId]['hand'] = [];
        playerData[pId]['currentBet'] = 0;
        playerData[pId]['totalBet'] = 0;
        playerData[pId]['status'] = (data['chips'] ?? 0) > 0 ? 'active' : 'out';
      });

      List<String> playersWithChips =
          playerData.entries
              .where((e) => (e.value['chips'] as num? ?? 0) > 0)
              .map((e) => e.key)
              .toList();

      if (playersWithChips.length <= 1) {
        String winner =
            playersWithChips.isNotEmpty
                ? playersWithChips.first
                : playerIds.first;
        String winnerName =
            playerData[winner]?['name'] ??
            players[winner]?['name'] ??
            _l10n.joueur;
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': winner,
          'players.$winner.score': FieldValue.increment(1),
          'gameEndReason': _l10n.aRemporteTousLesJetons(winnerName),
        });
        return;
      }
    }

    List<String> suits = ['H', 'D', 'C', 'S']; // Coeur, Carreau, Trèfle, Pique
    List<String> ranks = [
      '2',
      '3',
      '4',
      '5',
      '6',
      '7',
      '8',
      '9',
      'T',
      'J',
      'Q',
      'K',
      'A',
    ];
    List<String> deck = [
      for (var suit in suits)
        for (var rank in ranks) '$rank$suit',
    ]..shuffle();

    playerData.forEach((pId, data) {
      if (data['status'] == 'active') {
        playerData[pId]['hand'] = [deck.removeAt(0), deck.removeAt(0)];
      }
    });

    // Helper to find next non-out player index
    int nextActivePokerIndex(int fromIndex) {
      int idx = (fromIndex + 1) % playerIds.length;
      int safety = 0;
      while (playerData[playerIds[idx]]?['status'] == 'out' &&
          safety < playerIds.length) {
        idx = (idx + 1) % playerIds.length;
        safety++;
      }
      return idx;
    }

    int dealerIndex = nextActivePokerIndex(
      (gameData['dealerIndex'] as int?) ?? -1,
    );
    int smallBlindIndex = nextActivePokerIndex(dealerIndex);
    int bigBlindIndex = nextActivePokerIndex(smallBlindIndex);
    int firstToActIndex = nextActivePokerIndex(bigBlindIndex);

    String smallBlindId = playerIds[smallBlindIndex];
    String bigBlindId = playerIds[bigBlindIndex];

    int smallBlindAmount = gameData['smallBlind'] ?? 10;
    int bigBlindAmount = gameData['bigBlind'] ?? 20;

    int smallBlindActual =
        (playerData[smallBlindId]['chips'] as int) < smallBlindAmount
            ? (playerData[smallBlindId]['chips'] as int)
            : smallBlindAmount;
    int bigBlindActual =
        (playerData[bigBlindId]['chips'] as int) < bigBlindAmount
            ? (playerData[bigBlindId]['chips'] as int)
            : bigBlindAmount;

    playerData[smallBlindId]['chips'] -= smallBlindActual;
    playerData[smallBlindId]['currentBet'] = smallBlindActual;
    playerData[smallBlindId]['totalBet'] = smallBlindActual;
    if ((playerData[smallBlindId]['chips'] as int) == 0) {
      playerData[smallBlindId]['status'] = 'all-in';
    }
    playerData[bigBlindId]['chips'] -= bigBlindActual;
    playerData[bigBlindId]['currentBet'] = bigBlindActual;
    playerData[bigBlindId]['totalBet'] = bigBlindActual;
    if ((playerData[bigBlindId]['chips'] as int) == 0) {
      playerData[bigBlindId]['status'] = 'all-in';
    }
    int pot = smallBlindActual + bigBlindActual;

    await gameRef.update({
      'gameState': 'playing',
      'phase': 'pre-flop',
      'playerData': playerData,
      'deck': deck,
      'communityCards': [],
      'pot': pot,
      'dealerIndex': dealerIndex,
      'currentPlayerIndex': firstToActIndex,
      'playerOrder': playerIds, // Important pour l'ordre de jeu
      'currentBet': bigBlindActual,
      'lastRaiserId': bigBlindId,
      'pokerActedPlayers': <String>[],
      'smallBlindIndex': smallBlindIndex,
      'bigBlindIndex': bigBlindIndex,
      'handLog': [
        _l10n.nouvelleMainEstLeDonneur1(
          players[playerIds[dealerIndex]]['name'],
        ),
        _l10n.poseLaPetiteBlindDe1(
          players[smallBlindId]['name'],
          smallBlindActual,
        ),
        _l10n.poseLaGrosseBlindDe1(players[bigBlindId]['name'], bigBlindActual),
      ],
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> pokerAction(
    String gameCode,
    String playerId,
    String action, {
    int? amount,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    try {
      await _db.runTransaction((transaction) async {
        final gameRef = _db.collection('games').doc(gameCode);
        DocumentSnapshot gameSnap = await transaction.get(gameRef);

        if (!gameSnap.exists) {
          throw Exception(_l10n.laPartieNExistePas);
        }

        var gameData = gameSnap.data() as Map<String, dynamic>;
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});

        // SÉCURITÉ : Vérifier l'authUid
        final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
        if (!isAuto && currentAuthUid != voterAuthUid) {
          throw Exception(_l10n.actionNonAutorisee);
        }

        List<String> playerOrder = List<String>.from(
          gameData['playerOrder'] ?? [],
        );
        final int currentPlayerIndex =
            (gameData['currentPlayerIndex'] as num? ?? 0).toInt();

        if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length) {
          throw Exception(_l10n.donneesDeJeuInvalidesPlayerorder);
        }
        if (playerOrder[currentPlayerIndex] != playerId) {
          throw Exception(_l10n.ceNEstPasLe3(playerId));
        }

        var playerData = Map<String, dynamic>.from(
          json.decode(json.encode(gameData['playerData'] ?? {})),
        );
        var myData = playerData[playerId];

        if (myData == null) {
          throw Exception(_l10n.donneesDuJoueurIntrouvables(playerId));
        }

        int currentBet = (gameData['currentBet'] as num? ?? 0).toInt();
        int pot = (gameData['pot'] as num? ?? 0).toInt();
        List<String> handLog = List<String>.from(gameData['handLog'] ?? []);
        String? lastRaiserId = gameData['lastRaiserId'];

        Map<String, dynamic> allUpdates = {};

        switch (action) {
          case 'fold':
            myData['status'] = 'folded';
            handLog.add(_l10n.seCouche1(myData['name']));
            break;
          case 'check':
            if ((myData['currentBet'] as num).toInt() < currentBet) {
              throw Exception(_l10n.vousNePouvezPasChecker);
            }
            handLog.add(_l10n.pokerPlayerCheck(myData['name']));
            break;
          case 'call':
            int callAmount = currentBet - (myData['currentBet'] as num).toInt();
            if (callAmount >= (myData['chips'] as num).toInt()) {
              callAmount = (myData['chips'] as num).toInt();
              myData['status'] = 'all-in';
              handLog.add(_l10n.faitTapisAllIn1(myData['name']));
            } else {
              handLog.add(_l10n.suitPour(myData['name'], callAmount));
            }
            myData['chips'] -= callAmount;
            myData['currentBet'] += callAmount;
            myData['totalBet'] =
                ((myData['totalBet'] as num?)?.toInt() ?? 0) + callAmount;
            pot += callAmount;
            break;
          case 'raise':
            if (amount == null) {
              throw Exception(_l10n.montantDeRelanceRequis);
            }
            int totalBetAmount = (amount as num).toInt();
            if (totalBetAmount <= currentBet) {
              throw Exception(_l10n.laRelanceDoitEtreStrictement);
            }
            int maxPossibleBet =
                (myData['chips'] as num).toInt() +
                (myData['currentBet'] as num).toInt();
            if (totalBetAmount > maxPossibleBet) {
              throw Exception(_l10n.vousNAvezPasAssez);
            }

            // Règle de relance minimale (au moins le double de la mise précédente, ou tapis)
            int minRaise = currentBet * 2;
            if (totalBetAmount < minRaise && totalBetAmount < maxPossibleBet) {
              throw Exception(_l10n.laRelanceDoitEtreD);
            }

            int raiseAmount =
                totalBetAmount - (myData['currentBet'] as num).toInt();
            myData['chips'] -= raiseAmount;
            myData['currentBet'] = totalBetAmount;
            myData['totalBet'] =
                ((myData['totalBet'] as num?)?.toInt() ?? 0) + raiseAmount;
            pot += raiseAmount;
            currentBet = totalBetAmount;
            lastRaiserId = playerId;

            if ((myData['chips'] as num).toInt() == 0) {
              myData['status'] = 'all-in';
              handLog.add(
                _l10n.faitTapisAllInEn1(myData['name'], totalBetAmount),
              );
            } else {
              handLog.add(_l10n.relanceA(myData['name'], totalBetAmount));
            }
            break;
        }
        playerData[playerId] = myData;

        List<String> actedPlayers = List<String>.from(
          gameData['pokerActedPlayers'] ?? [],
        );
        if (action == 'raise') {
          actedPlayers = [playerId];
        } else if (!actedPlayers.contains(playerId)) {
          actedPlayers.add(playerId);
        }

        int xpBase =
            (action == 'raise' || action == 'call')
                ? ((myData['status'] == 'all-in') ? 15 : 3)
                : 0;
        if (xpBase > 0) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            xpBase,
            applySpeedBonus: true,
          );
        }

        var updatedGameData = Map<String, dynamic>.from(gameData);
        updatedGameData['playerData'] = playerData;
        updatedGameData['pot'] = pot;
        updatedGameData['currentBet'] = currentBet;
        updatedGameData['lastRaiserId'] = lastRaiserId;
        updatedGameData['pokerActedPlayers'] = actedPlayers;
        updatedGameData['handLog'] = handLog;

        final turnUpdates = _advancePokerTurn(updatedGameData);

        allUpdates.addAll({
          'playerData': playerData,
          'pot': pot,
          'currentBet': currentBet,
          'lastRaiserId': lastRaiserId,
          'pokerActedPlayers': actedPlayers,
          'handLog': handLog,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        allUpdates.addAll(turnUpdates);

        transaction.update(gameRef, allUpdates);
      });
    } catch (e) {
      rethrow;
    }
  }

  Map<String, dynamic> _advancePokerTurn(Map<String, dynamic> gameData) {
    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    int currentIndex = (gameData['currentPlayerIndex'] as num? ?? 0).toInt();
    String? lastRaiserId = gameData['lastRaiserId'];

    if (playerOrder.isEmpty || playerData.isEmpty) return {};

    List<String> activePlayers =
        playerOrder
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();
    if (activePlayers.length <= 1) {
      return _determinePokerWinner(gameData);
    }

    int nextIndex = currentIndex;
    int safetyCounter = 0;
    do {
      nextIndex = (nextIndex + 1) % playerOrder.length;
      safetyCounter++;
    } while ((playerData[playerOrder[nextIndex]]?['status'] == 'folded' ||
            playerData[playerOrder[nextIndex]]?['status'] == 'all-in') &&
        safetyCounter <= playerOrder.length * 2);

    if (safetyCounter > playerOrder.length) {
      var updatedData = Map<String, dynamic>.from(gameData);
      Map<String, dynamic> allUpdates = {};
      int phaseGuard = 0;
      while (updatedData['phase'] != 'river' &&
          updatedData['phase'] != 'showdown' &&
          phaseGuard < 10) {
        final phaseUpdates = _startNextPokerPhase(updatedData);
        if (phaseUpdates.isEmpty) break;
        allUpdates.addAll(phaseUpdates);
        updatedData.addAll(phaseUpdates);
        phaseGuard++;
      }
      if (updatedData['phase'] == 'river') {
        final showdownUpdates = _startNextPokerPhase(updatedData);
        allUpdates.addAll(showdownUpdates);
        updatedData.addAll(showdownUpdates);
      }
      allUpdates['phase'] = 'showdown';
      updatedData['phase'] = 'showdown';
      allUpdates.addAll(_determinePokerWinner(updatedData));
      return allUpdates;
    }

    String nextPlayerId = playerOrder[nextIndex];

    bool allBetsMatched = activePlayers
        .where((pId) => playerData[pId]?['status'] == 'active')
        .every(
          (pId) =>
              (playerData[pId]?['currentBet'] as num? ?? 0).toInt() ==
              (gameData['currentBet'] as num? ?? 0).toInt(),
        );

    final List<String> actedPlayers = List<String>.from(
      gameData['pokerActedPlayers'] ?? [],
    );
    bool allActiveHaveActed = activePlayers
        .where((pId) => playerData[pId]?['status'] == 'active')
        .every((pId) => actedPlayers.contains(pId));

    bool isRoundComplete =
        allBetsMatched &&
        (allActiveHaveActed ||
            (nextPlayerId == lastRaiserId &&
                actedPlayers.contains(lastRaiserId)));

    if (isRoundComplete) {
      Map<String, dynamic> currentData = Map.from(gameData);
      final phaseUpdates = _startNextPokerPhase(currentData);
      currentData.addAll(phaseUpdates);

      if (currentData['phase'] == 'showdown') {
        phaseUpdates.addAll(_determinePokerWinner(currentData));
      }
      return phaseUpdates;
    } else {
      return {'currentPlayerIndex': nextIndex};
    }
  }

  Map<String, dynamic> _startNextPokerPhase(Map<String, dynamic> gameData) {
    String currentPhase = gameData['phase'];
    String nextPhase = '';
    List<dynamic> communityCards = List.from(gameData['communityCards'] ?? []);
    List<dynamic> deck = List.from(gameData['deck'] ?? []);
    List<String> log = List.from(gameData['handLog'] ?? []);

    Map<String, dynamic> updates = {};

    switch (currentPhase) {
      case 'pre-flop':
        nextPhase = 'flop';
        if (deck.length >= 3)
          communityCards.addAll([
            deck.removeAt(0),
            deck.removeAt(0),
            deck.removeAt(0),
          ]);
        log.add(_l10n.pokerFlop);
        break;
      case 'flop':
        nextPhase = 'turn';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add(_l10n.pokerTurn);
        break;
      case 'turn':
        nextPhase = 'river';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add(_l10n.pokerRiver);
        break;
      case 'river':
        nextPhase = 'showdown';
        log.add(_l10n.abattageShowdown);
        break;
      default:
        return {}; // Ne rien faire si la phase est inconnue
    }

    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    List<String> playerOrder = List.from(gameData['playerOrder'] ?? []);
    int dealerIndex = (gameData['dealerIndex'] as num? ?? -1).toInt();

    playerData.forEach((pId, data) {
      if (data['status'] != 'folded') {
        data['currentBet'] = 0;
      }
    });

    int firstToActIndex = (dealerIndex + 1) % playerOrder.length;
    int count = 0;
    while (playerData[playerOrder[firstToActIndex]]?['status'] != 'active') {
      firstToActIndex = (firstToActIndex + 1) % playerOrder.length;
      count++;
      if (count > playerOrder.length) break;
    }

    updates.addAll({
      'phase': nextPhase,
      'communityCards': communityCards,
      'deck': deck,
      'handLog': log,
      'playerData': playerData,
      'currentBet': 0,
      'currentPlayerIndex': firstToActIndex,
      'lastRaiserId': playerOrder[firstToActIndex],
      'pokerActedPlayers': <String>[],
    });

    return updates;
  }

  Map<String, dynamic> _determinePokerWinner(Map<String, dynamic> gameData) {
    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    final communityCards =
        (gameData['communityCards'] as List<dynamic>? ?? [])
            .cast<String>()
            .toList();
    List<String> playersInHand =
        playerData.keys
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();

    String winnerAnnouncement = "";
    List<String> winners = [];
    PokerHand? bestHand;

    Map<String, PokerHand> playerFinalHands = {};
    if (playersInHand.length == 1) {
      winners.add(playersInHand.first);
      winnerAnnouncement = _l10n.gagneLePotParForfait1(
        playerData[winners.first]['name'],
      );
      playerFinalHands[winners.first] = PokerHand(HandRank.highCard, []);
    } else {
      for (String pId in playersInHand) {
        final playerHand =
            (playerData[pId]['hand'] as List<dynamic>? ?? [])
                .cast<String>()
                .toList();
        final sevenCards = [...playerHand, ...communityCards];
        playerFinalHands[pId] = PokerHandEvaluator.evaluateHand(sevenCards);
      }

      playerFinalHands.forEach((pId, hand) {
        if (bestHand == null || hand.compareTo(bestHand!) > 0) {
          bestHand = hand;
          winners = [pId];
        } else if (hand.compareTo(bestHand!) == 0) {
          winners.add(pId);
        }
      });

      final winnerNames = winners
          .map((id) => playerData[id]?['name'] ?? _l10n.inconnu)
          .join(' ${_l10n.et} ');
      winnerAnnouncement = _l10n.gagneNtLePotAvec(
        winnerNames,
        bestHand?.rank.name ?? _l10n.uneMain,
      );
    }

    Map<String, dynamic> scoreUpdates = {};
    if (playersInHand.isNotEmpty) {
      int totalPot = (gameData['pot'] as num? ?? 0).toInt();

      // Gestion des Side Pots selon l'investissement de chaque joueur
      Map<String, int> totalBets = {};
      for (String pId in playerData.keys) {
        totalBets[pId] = ((playerData[pId]['totalBet'] as num?)?.toInt() ?? 0);
      }

      List<int> betTiers =
          totalBets.values.where((b) => b > 0).toSet().toList()..sort();
      bool hasAllIn = playerData.values.any((p) => p['status'] == 'all-in');

      if (hasAllIn && betTiers.length > 1) {
        int prevTier = 0;
        int remainingPot = totalPot;

        for (int tier in betTiers) {
          int sidePot = 0;
          for (String pId in totalBets.keys) {
            int b = totalBets[pId]!;
            if (b > prevTier) {
              sidePot += min(b - prevTier, tier - prevTier);
            }
          }
          if (sidePot <= 0) continue;
          sidePot = min(sidePot, remainingPot);

          List<String> eligible =
              playersInHand.where((id) => totalBets[id]! >= tier).toList();
          if (eligible.isEmpty) eligible = playersInHand;

          PokerHand? tierBestHand;
          List<String> tierWinners = [];
          for (String pId in eligible) {
            PokerHand h = playerFinalHands[pId]!;
            if (tierBestHand == null || h.compareTo(tierBestHand) > 0) {
              tierBestHand = h;
              tierWinners = [pId];
            } else if (h.compareTo(tierBestHand) == 0) {
              tierWinners.add(pId);
            }
          }

          int share = (sidePot / tierWinners.length).floor();
          for (String wId in tierWinners) {
            playerData[wId]['chips'] =
                (playerData[wId]['chips'] as int) + share;
          }
          remainingPot -= sidePot;
          prevTier = tier;
        }
      } else {
        int potPerWinner = (totalPot / winners.length).floor();
        for (String winId in winners) {
          playerData[winId]['chips'] += potPerWinner;
        }
      }

      for (String winId in winners) {
        int winXp = 30;
        if (bestHand?.rank == HandRank.straight ||
            bestHand?.rank == HandRank.flush ||
            bestHand?.rank == HandRank.fullHouse ||
            bestHand?.rank == HandRank.fourOfAKind ||
            bestHand?.rank == HandRank.straightFlush ||
            bestHand?.rank == HandRank.royalFlush) {
          winXp = 50;
        }
        final authUid = playerData[winId]['authUid'] ?? winId;
        _db.collection('users').doc(authUid).set({
          'xp': FieldValue.increment(winXp),
        }, SetOptions(merge: true));
        playerData[winId]['xp'] =
            ((playerData[winId]['xp'] as num?)?.toInt() ?? 0) + winXp;
        scoreUpdates['players.$winId.xp'] = FieldValue.increment(winXp);
      }
    }

    List<String> handLog = List.from(gameData['handLog'] ?? []);
    handLog.add(winnerAnnouncement);

    return {
      'phase': 'hand_over',
      'playerData': playerData,
      'handLog': handLog,
      'showdownHands': {
        for (var pId in playersInHand) pId: playerData[pId]['hand'],
      },
      'turnStartTime': FieldValue.serverTimestamp(),
      ...scoreUpdates,
    };
  }

  List<String> _generateBeloteDeck() {
    const suits = ['H', 'D', 'C', 'S'];
    const ranks = ['7', '8', '9', '10', 'J', 'Q', 'K', 'A'];
    List<String> deck = [];
    for (var s in suits) {
      for (var r in ranks) {
        deck.add('$r$s');
      }
    }
    deck.shuffle();
    return deck;
  }

  Future<void> _startBeloteRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final existingOrder =
        List<String>.from(
          gameData['belotePlayerOrder'] ?? [],
        ).where((id) => players.containsKey(id)).toList();
    final List<String> playerIds =
        existingOrder.length == 4
            ? [...existingOrder.sublist(1), existingOrder.first]
            : (players.keys.toList()..shuffle());
    if (playerIds.length != 4) {
      throw Exception(_l10n.laBeloteRequiertExactement4);
    }

    List<String> deck = _generateBeloteDeck();
    Map<String, dynamic> playerData = {};
    final existingPlayerData = Map<String, dynamic>.from(
      gameData['belotePlayerData'] ?? {},
    );

    // Équipes : conserver l'équipe existante ou 0 & 2 = teamA, 1 & 3 = teamB
    for (int i = 0; i < 4; i++) {
      String pId = playerIds[i];
      List<String> hand = [];
      for (int j = 0; j < 5; j++) {
        hand.add(deck.removeAt(0));
      }
      final String existingTeam =
          existingPlayerData[pId]?['team']?.toString() ??
          ((i % 2 == 0) ? 'teamA' : 'teamB');
      playerData[pId] = {
        'name': players[pId]['name'],
        'team': existingTeam,
        'hand': hand,
      };
    }

    String turnedCard = deck.removeAt(0);

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'bidding',
      'beloteDeck': deck,
      'beloteTurnedCard': turnedCard,
      'beloteTrumpSuit': null,
      'beloteTakerId': null,
      'belotePassCount': 0,
      'beloteBiddingRound': 1,
      'belotePlayerData': playerData,
      'belotePlayerOrder': playerIds,
      'beloteCurrentPlayerIndex': 0,
      'beloteCurrentTrick': {},
      'beloteTeamScores':
          gameData['beloteTeamScores'] ?? {'teamA': 0, 'teamB': 0},
      'beloteTargetScore': gameData['beloteTargetScore'] ?? 500,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': FieldValue.arrayUnion([_l10n.logBeloteStart]),
    });
  }

  Future<void> beloteAction(
    String gameCode,
    String playerId,
    String action, {
    String? card,
    String? suit,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      Map<String, dynamic> playerData = Map.from(gameData['belotePlayerData']);
      List<String> playerOrder = List.from(gameData['belotePlayerOrder']);
      int currentIndex = gameData['beloteCurrentPlayerIndex'];

      if (playerOrder[currentIndex] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }

      if (action == 'bid' && suit != null) {
        List<String> deck = List<String>.from(gameData['beloteDeck']);
        String turnedCard = gameData['beloteTurnedCard'];

        // Le preneur prend la carte retournée + 2 cartes du paquet (total 8)
        List<String> takerHand = List<String>.from(
          playerData[playerId]['hand'],
        );
        takerHand.add(turnedCard);
        for (int i = 0; i < 2; i++) {
          if (deck.isNotEmpty) takerHand.add(deck.removeAt(0));
        }
        playerData[playerId]['hand'] = takerHand;

        // Les 3 autres reçoivent 3 cartes
        for (String pId in playerOrder) {
          if (pId == playerId) continue;
          List<String> hand = List<String>.from(playerData[pId]['hand']);
          for (int i = 0; i < 3; i++) {
            if (deck.isNotEmpty) hand.add(deck.removeAt(0));
          }
          playerData[pId]['hand'] = hand;
        }

        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          5,
          applySpeedBonus: true,
        );

        transaction.update(gameRef, {
          'beloteDeck': deck,
          'beloteTrumpSuit': suit,
          'beloteTakerId': playerId,
          'belotePlayerData': playerData,
          'roundState': 'playing_trick',
          'beloteCurrentTrick': {},
          'beloteCurrentPlayerIndex': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            _l10n.aPrisA(playerData[playerId]['name'], suit),
          ]),
        });
      } else if (action == 'pass') {
        int passCount = (gameData['belotePassCount'] as num? ?? 0).toInt() + 1;
        int biddingRound =
            (gameData['beloteBiddingRound'] as num? ?? 1).toInt();
        int nextIndex = (currentIndex + 1) % playerOrder.length;

        if (passCount >= 4) {
          if (biddingRound == 1) {
            // Passe générale au 1er tour -> Passage au 2e tour
            transaction.update(gameRef, {
              'beloteBiddingRound': 2,
              'belotePassCount': 0,
              'beloteCurrentPlayerIndex': nextIndex,
              'turnStartTime': FieldValue.serverTimestamp(),
              'gameLog': FieldValue.arrayUnion([_l10n.passeGeneraleAu1erTour]),
            });
          } else {
            // Passe générale au 2e tour -> Nouvelle donne dans la transaction
            List<String> newDeck = _generateBeloteDeck();
            Map<String, dynamic> newPlayerData = {};
            for (int i = 0; i < 4; i++) {
              String pId = playerOrder[i];
              List<String> hand = [];
              for (int j = 0; j < 5; j++) {
                hand.add(newDeck.removeAt(0));
              }
              newPlayerData[pId] = {
                'name': playerData[pId]?['name'] ?? players[pId]?['name'],
                'team':
                    playerData[pId]?['team'] ??
                    ((i % 2 == 0) ? 'teamA' : 'teamB'),
                'hand': hand,
              };
            }
            String newTurnedCard = newDeck.removeAt(0);
            transaction.update(gameRef, {
              'roundState': 'bidding',
              'beloteDeck': newDeck,
              'beloteTurnedCard': newTurnedCard,
              'beloteTrumpSuit': null,
              'beloteTakerId': null,
              'belotePassCount': 0,
              'beloteBiddingRound': 1,
              'belotePlayerData': newPlayerData,
              'beloteCurrentPlayerIndex': nextIndex,
              'beloteCurrentTrick': {},
              'turnStartTime': FieldValue.serverTimestamp(),
            });
          }
        } else {
          transaction.update(gameRef, {
            'belotePassCount': passCount,
            'beloteCurrentPlayerIndex': nextIndex,
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      } else if (action == 'play' && card != null) {
        List<String> hand = List.from(playerData[playerId]['hand']);
        if (!hand.contains(card)) throw Exception(_l10n.carteNonPossedee);

        Map<String, dynamic> currentTrick = Map.from(
          gameData['beloteCurrentTrick'] ?? {},
        );
        String trumpSuit = gameData['beloteTrumpSuit'] ?? 'H';

        // Validation de jeu (Fournir la couleur si possible + règles de coupe à l'atout)
        if (currentTrick.isNotEmpty) {
          String ledCard = currentTrick.values.first as String;
          String ledSuit = ledCard.substring(ledCard.length - 1);
          String playedSuit = card.substring(card.length - 1);
          bool hasLedSuit = hand.any((c) => c.endsWith(ledSuit));

          if (hasLedSuit) {
            if (playedSuit != ledSuit) {
              throw Exception(_l10n.vousDevezFournirLaCouleur1(ledSuit));
            }
          } else {
            // Ne peut pas fournir la couleur demandée
            // Déterminer qui est maître actuellement sur le pli
            String masterId = currentTrick.keys.first;
            int highestPower = -1;
            int highestTrumpPower = -1;
            currentTrick.forEach((pId, c) {
              String cSuit = c.substring(c.length - 1);
              String rank = c.substring(0, c.length - 1);
              bool isTrump = (cSuit == trumpSuit);
              int cardPower = _getBeloteCardValue(c, isTrump);
              int cardRank = _getBeloteCardRank(rank, isTrump);
              int power =
                  isTrump
                      ? (2000 + cardPower * 10 + cardRank)
                      : (cSuit == ledSuit
                          ? (1000 + cardPower * 10 + cardRank)
                          : 0);
              if (power > highestPower) {
                highestPower = power;
                masterId = pId;
              }
              if (isTrump && power > highestTrumpPower) {
                highestTrumpPower = power;
              }
            });

            bool partnerIsMaster =
                (playerData[masterId]?['team'] ==
                    playerData[playerId]?['team']);
            bool hasTrump = hand.any((c) => c.endsWith(trumpSuit));

            // Si le partenaire n'est pas maître et qu'on possède de l'atout
            if (!partnerIsMaster && hasTrump) {
              if (highestTrumpPower > 0) {
                // Un atout a déjà été joué par un adversaire : obligation de surcouper si possible
                bool canOverTrump = hand.any((c) {
                  if (!c.endsWith(trumpSuit)) return false;
                  String rank = c.substring(0, c.length - 1);
                  int pwr =
                      2000 +
                      _getBeloteCardValue(c, true) * 10 +
                      _getBeloteCardRank(rank, true);
                  return pwr > highestTrumpPower;
                });

                if (canOverTrump) {
                  int playedPwr =
                      (playedSuit == trumpSuit)
                          ? (2000 +
                              _getBeloteCardValue(card, true) * 10 +
                              _getBeloteCardRank(
                                card.substring(0, card.length - 1),
                                true,
                              ))
                          : 0;
                  if (playedPwr <= highestTrumpPower) {
                    throw Exception(_l10n.vousDevezMonterAL);
                  }
                }
              } else {
                // Pas encore d'atout sur le pli et l'adversaire est maître -> couper obligatoire
                if (playedSuit != trumpSuit) {
                  throw Exception(_l10n.vousDevezCouperAL);
                }
              }
            }
          }
        }

        hand.remove(card);
        playerData[playerId]['hand'] = hand;
        currentTrick[playerId] = card;

        if (currentTrick.length == 4) {
          String winningPlayer = currentTrick.keys.first;
          String ledCard = currentTrick.values.first as String;
          String ledSuit = ledCard.substring(ledCard.length - 1);
          int highestPower = -1;

          currentTrick.forEach((pId, c) {
            String cSuit = c.substring(c.length - 1);
            String rank = c.substring(0, c.length - 1);
            bool isTrump = (cSuit == trumpSuit);
            int cardPower = _getBeloteCardValue(c, isTrump);
            int cardRank = _getBeloteCardRank(rank, isTrump);

            int totalPower = 0;
            if (isTrump) {
              totalPower = 2000 + (cardPower * 10) + cardRank; // Atout bat tout
            } else if (cSuit == ledSuit) {
              totalPower =
                  1000 + (cardPower * 10) + cardRank; // Couleur demandée
            } else {
              totalPower = 0; // Pisse / Défausse
            }

            if (totalPower > highestPower) {
              highestPower = totalPower;
              winningPlayer = pId;
            }
          });

          int trickPoints = 0;
          currentTrick.values.forEach((c) {
            trickPoints += _getBeloteCardValue(c, c.endsWith(trumpSuit));
          });

          if (trickPoints >= 162) {
            final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
            if (currentAuthUid != null) {
              _db.collection('users').doc(currentAuthUid).set({
                'unlockedBadges.belote_capot': FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
            }
          }

          String winnerTeam = playerData[winningPlayer]['team'];
          Map<String, dynamic> teamScores = Map.from(
            gameData['beloteTeamScores'] ?? {'teamA': 0, 'teamB': 0},
          );
          teamScores[winnerTeam] = (teamScores[winnerTeam] ?? 0) + trickPoints;

          bool roundOver = playerOrder.every(
            (pId) => (playerData[pId]['hand'] as List).isEmpty,
          );

          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            winningPlayer,
            5,
            applySpeedBonus: false,
          );
          if (roundOver) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              winningPlayer,
              20,
              applySpeedBonus: false,
            );
          }

          if (roundOver) {
            teamScores[winnerTeam] =
                (teamScores[winnerTeam] ?? 0) + 10; // Dix de der
            int targetScore = gameData['beloteTargetScore'] ?? 500;
            bool gameOver =
                (teamScores['teamA'] >= targetScore) ||
                (teamScores['teamB'] >= targetScore);

            Map<String, dynamic> scoreUpdates = {};
            if (gameOver) {
              String winnerTeam =
                  (teamScores['teamA'] ?? 0) > (teamScores['teamB'] ?? 0)
                      ? 'teamA'
                      : 'teamB';
              playerData.forEach((pId, pInfo) {
                if (pInfo is Map && pInfo['team'] == winnerTeam) {
                  scoreUpdates['players.$pId.score'] = FieldValue.increment(1);
                }
              });
            }

            transaction.update(gameRef, {
              'belotePlayerData': playerData,
              'beloteTeamScores': teamScores,
              'beloteCurrentTrick': {},
              'roundState': gameOver ? 'gameOver' : 'round_over',
              'gameState': gameOver ? 'gameOver' : 'playing',
              'gameWinner':
                  gameOver
                      ? (teamScores['teamA'] > teamScores['teamB']
                          ? 'teamA'
                          : 'teamB')
                      : null,
              'turnStartTime': FieldValue.serverTimestamp(),
              ...scoreUpdates,
            });
          } else {
            int winnerIndex = playerOrder.indexOf(winningPlayer);
            transaction.update(gameRef, {
              'belotePlayerData': playerData,
              'beloteTeamScores': teamScores,
              'beloteCurrentTrick': {},
              'beloteCurrentPlayerIndex': winnerIndex,
              'turnStartTime': FieldValue.serverTimestamp(),
            });
          }
        } else {
          int nextIndex = (currentIndex + 1) % playerOrder.length;
          transaction.update(gameRef, {
            'belotePlayerData': playerData,
            'beloteCurrentTrick': currentTrick,
            'beloteCurrentPlayerIndex': nextIndex,
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });
  }

  int _getBeloteCardValue(String card, bool isTrump) {
    String rank = card.substring(0, card.length - 1);
    if (isTrump) {
      switch (rank) {
        case 'J':
          return 20;
        case '9':
          return 14;
        case 'A':
          return 11;
        case '10':
          return 10;
        case 'K':
          return 4;
        case 'Q':
          return 3;
        case '8':
          return 0;
        case '7':
          return 0;
        default:
          return 0;
      }
    } else {
      switch (rank) {
        case 'A':
          return 11;
        case '10':
          return 10;
        case 'K':
          return 4;
        case 'Q':
          return 3;
        case 'J':
          return 2;
        case '9':
          return 0;
        case '8':
          return 0;
        case '7':
          return 0;
        default:
          return 0;
      }
    }
  }

  int _getBeloteCardRank(String rank, bool isTrump) {
    if (isTrump) {
      const order = {
        '7': 0,
        '8': 1,
        'Q': 2,
        'K': 3,
        '10': 4,
        'A': 5,
        '9': 6,
        'J': 7,
      };
      return order[rank] ?? 0;
    } else {
      const order = {
        '7': 0,
        '8': 1,
        '9': 2,
        'J': 3,
        'Q': 4,
        'K': 5,
        '10': 6,
        'A': 7,
      };
      return order[rank] ?? 0;
    }
  }

  // Gestion du timeout (si un joueur ne joue pas à temps)
  Future<void> handleBeloteTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (gameData['roundState'] == 'round_over') {
      await _startBeloteRound(gameRef, gameData);
      return;
    }
    if (!_isTurnTimedOut(gameData)) return;

    final playerOrder = gameData['belotePlayerOrder'] as List<dynamic>?;
    final currentIndex = gameData['beloteCurrentPlayerIndex'] as int?;
    if (playerOrder != null && currentIndex != null && playerOrder.isNotEmpty) {
      String timedOutPlayerId = playerOrder[currentIndex];
      String roundState = gameData['roundState'];
      final playerName =
          gameData['players']?[timedOutPlayerId]?['name'] ?? _l10n.unJoueur;

      if (roundState == 'bidding') {
        await notifyAutoPlay(
          gameRef,
          playerName,
          actionDetails: _l10n.passeLAnnonce,
        );
        await beloteAction(gameCode, timedOutPlayerId, 'pass', isAuto: true);
      } else if (roundState == 'playing_trick') {
        final Map<String, dynamic> playerData = Map<String, dynamic>.from(
          gameData['belotePlayerData'] ?? {},
        );
        List<String> hand = List<String>.from(
          playerData[timedOutPlayerId]?['hand'] ?? [],
        );
        if (hand.isNotEmpty) {
          final currentTrick = Map<String, dynamic>.from(
            gameData['beloteCurrentTrick'] ?? {},
          );
          final String trumpSuit = gameData['beloteTrumpSuit'] ?? 'H';
          List<String> legalCards = List<String>.from(hand);

          if (currentTrick.isNotEmpty) {
            String ledCard = currentTrick.values.first as String;
            String ledSuit = ledCard.substring(ledCard.length - 1);
            final sameSuitCards =
                hand.where((c) => c.endsWith(ledSuit)).toList();

            if (sameSuitCards.isNotEmpty) {
              // Si la couleur demandée est l'atout, obligation de monter si possible
              if (ledSuit == trumpSuit) {
                int highestTrumpPower = -1;
                currentTrick.forEach((_, c) {
                  String cStr = c.toString();
                  if (cStr.endsWith(trumpSuit)) {
                    String rank = cStr.substring(0, cStr.length - 1);
                    int pwr =
                        2000 +
                        _getBeloteCardValue(cStr, true) * 10 +
                        _getBeloteCardRank(rank, true);
                    if (pwr > highestTrumpPower) highestTrumpPower = pwr;
                  }
                });
                final overTrumps =
                    sameSuitCards.where((c) {
                      String rank = c.substring(0, c.length - 1);
                      int pwr =
                          2000 +
                          _getBeloteCardValue(c, true) * 10 +
                          _getBeloteCardRank(rank, true);
                      return pwr > highestTrumpPower;
                    }).toList();
                legalCards = overTrumps.isNotEmpty ? overTrumps : sameSuitCards;
              } else {
                legalCards = sameSuitCards;
              }
            } else {
              // Ne peut pas fournir la couleur demandée
              String masterId = currentTrick.keys.first;
              int highestPower = -1;
              int highestTrumpPower = -1;
              currentTrick.forEach((pId, c) {
                String cStr = c.toString();
                String cSuit = cStr.substring(cStr.length - 1);
                String rank = cStr.substring(0, cStr.length - 1);
                bool isTrump = (cSuit == trumpSuit);
                int cardPower = _getBeloteCardValue(cStr, isTrump);
                int cardRank = _getBeloteCardRank(rank, isTrump);
                int power =
                    isTrump
                        ? (2000 + cardPower * 10 + cardRank)
                        : (cSuit == ledSuit
                            ? (1000 + cardPower * 10 + cardRank)
                            : 0);
                if (power > highestPower) {
                  highestPower = power;
                  masterId = pId;
                }
                if (isTrump && power > highestTrumpPower) {
                  highestTrumpPower = power;
                }
              });

              bool partnerIsMaster =
                  (playerData[masterId]?['team'] ==
                      playerData[timedOutPlayerId]?['team']);
              final trumpCards =
                  hand.where((c) => c.endsWith(trumpSuit)).toList();

              if (!partnerIsMaster && trumpCards.isNotEmpty) {
                if (highestTrumpPower > 0) {
                  final overTrumps =
                      trumpCards.where((c) {
                        String rank = c.substring(0, c.length - 1);
                        int pwr =
                            2000 +
                            _getBeloteCardValue(c, true) * 10 +
                            _getBeloteCardRank(rank, true);
                        return pwr > highestTrumpPower;
                      }).toList();
                  legalCards = overTrumps.isNotEmpty ? overTrumps : hand;
                } else {
                  legalCards = trumpCards;
                }
              }
            }
          }

          String cardToPlay = legalCards.first;

          await notifyAutoPlay(
            gameRef,
            playerName,
            actionDetails: _l10n.carte1(cardToPlay),
          );
          await beloteAction(
            gameCode,
            timedOutPlayerId,
            'play',
            card: cardToPlay,
            isAuto: true,
          );
        }
      }
    }
  }

  Future<void> _startBlokusRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();
    final colors = ['blue', 'red', 'green', 'yellow'];

    Map<String, String> playerColors = {};
    Map<String, List<int>> playerHands = {};
    Map<String, bool> firstPiecePlaced = {};

    for (int i = 0; i < playerIds.length; i++) {
      playerColors[playerIds[i]] = colors[i % 4];
      playerHands[playerIds[i]] = List.generate(21, (index) => index + 1);
      firstPiecePlaced[playerIds[i]] = false;
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'blokusBoard': {}, // Map<String, String> "row_col": "color"
      'blokusPlayerColors': playerColors,
      'blokusPlayerHands': playerHands,
      'blokusFirstPiecePlaced': firstPiecePlaced,
      'blokusPlayerOrder': playerIds,
      'blokusCurrentPlayerIndex': 0,
      'blokusPassedPlayers': [],
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [_l10n.logBlokusStart],
    });
  }

  Future<void> placeBlokusPiece(
    String gameCode,
    String playerId,
    int pieceId,
    int startRow,
    int startCol,
    int rotation, {
    bool flipped = false,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      // SÉCURITÉ AUTH
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      final playerOrder = List<String>.from(gameData['blokusPlayerOrder']);
      if (playerOrder[gameData['blokusCurrentPlayerIndex']] != playerId) {
        throw Exception(_l10n.ceNEstPasVotre);
      }

      final myColor = gameData['blokusPlayerColors'][playerId];
      final hand = List<int>.from(gameData['blokusPlayerHands'][playerId]);
      if (!hand.contains(pieceId)) throw Exception(_l10n.pieceDejaUtilisee);

      final board = Map<String, String>.from(gameData['blokusBoard'] ?? {});
      final isFirstPiece =
          !(gameData['blokusFirstPiecePlaced'][playerId] ?? false);

      // Prise en compte du flipped côté serveur
      final rotatedPiece = GameData.getRotatedPiece(
        pieceId,
        rotation,
        flipped: flipped,
      );
      final absoluteCoords =
          rotatedPiece.map((p) => [p[0] + startRow, p[1] + startCol]).toList();

      // 1. Limites et Chevauchement
      for (var c in absoluteCoords) {
        if (c[0] < 0 || c[0] >= 20 || c[1] < 0 || c[1] >= 20) {
          throw Exception(_l10n.horsLimites);
        }
        if (board.containsKey("${c[0]}_${c[1]}")) {
          throw Exception(_l10n.caseDejaOccupee);
        }
      }

      // 2. Règle des côtés (Orthogonal interdit)
      for (var c in absoluteCoords) {
        List<List<int>> neighbors = [
          [c[0] - 1, c[1]],
          [c[0] + 1, c[1]],
          [c[0], c[1] - 1],
          [c[0], c[1] + 1],
        ];
        for (var n in neighbors) {
          if (board["${n[0]}_${n[1]}"] == myColor) {
            throw Exception(_l10n.contactParLeCoteInterdit);
          }
        }
      }

      // 3. Règle des coins (Diagonal obligatoire)
      bool touchesCorner = false;
      for (var c in absoluteCoords) {
        List<List<int>> diags = [
          [c[0] - 1, c[1] - 1],
          [c[0] - 1, c[1] + 1],
          [c[0] + 1, c[1] - 1],
          [c[0] + 1, c[1] + 1],
        ];
        for (var d in diags) {
          if (board["${d[0]}_${d[1]}"] == myColor) {
            touchesCorner = true;
            break;
          }
        }
        if (touchesCorner) break;
      }

      if (isFirstPiece) {
        final List<String> validCorners = ["0_0", "19_19", "0_19", "19_0"];
        String cornerTarget =
            myColor == 'blue'
                ? "0_0"
                : myColor == 'red'
                ? "19_19"
                : myColor == 'green'
                ? "0_19"
                : "19_0";
        bool coversCorner = absoluteCoords.any((c) {
          final key = "${c[0]}_${c[1]}";
          return key == cornerTarget ||
              (validCorners.contains(key) && !board.containsKey(key));
        });
        if (!coversCorner) {
          throw Exception(_l10n.lePremierCoupDoitCouvrir);
        }
      } else {
        if (!touchesCorner) {
          throw Exception(_l10n.votrePieceDoitToucherUne);
        }
      }

      // Placement effectif
      for (var c in absoluteCoords) {
        board["${c[0]}_${c[1]}"] = myColor;
      }
      hand.remove(pieceId);

      // Mémoriser la dernière pièce posée pour le bonus 1x1
      Map<String, dynamic> lastPiecesPlaced = Map<String, dynamic>.from(
        gameData['blokusLastPiecesPlaced'] ?? {},
      );
      lastPiecesPlaced[playerId] = pieceId;

      int xpBase = (pieceId == 1) ? 15 : (hand.isEmpty ? 40 : 5);
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      Map<String, dynamic> updates = {
        'blokusBoard': board,
        'blokusPlayerHands.$playerId': hand,
        'blokusFirstPiecePlaced.$playerId': true,
        'blokusLastPiecesPlaced': lastPiecesPlaced,
      };

      List<String> passedPlayers = List<String>.from(
        gameData['blokusPassedPlayers'] ?? [],
      );
      if (hand.isEmpty && !passedPlayers.contains(playerId)) {
        passedPlayers.add(playerId);
        updates['blokusPassedPlayers'] = passedPlayers;
      }

      if (passedPlayers.length >= playerOrder.length) {
        Map<String, int> scores = {};
        playerOrder.forEach((pId) {
          List<int> pHand = List<int>.from(
            gameData['blokusPlayerHands'][pId] ?? [],
          );
          if (pId == playerId) pHand = hand;
          int remainingSquares = pHand.fold(
            0,
            (sum, id) => sum + GameData.blokusPieces[id]!.length,
          );
          int score = -remainingSquares;
          if (remainingSquares == 0) {
            score += 15;
            // Correction de la règle : bonus si la DERNIÈRE pièce était bien le carré 1x1 (id: 1)
            if (lastPiecesPlaced[pId] == 1) score += 5;
          }
          scores[pId] = score;
        });
        String winnerId =
            scores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'players.$winnerId.score': FieldValue.increment(1),
          'blokusScores': scores,
          'gameEndReason': _l10n.finDeLaPartie,
        });
      } else {
        int nextIndex =
            (gameData['blokusCurrentPlayerIndex'] + 1) % playerOrder.length;
        int loopCount = 0;
        while (passedPlayers.contains(playerOrder[nextIndex]) &&
            loopCount < playerOrder.length) {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          loopCount++;
        }
        updates['blokusCurrentPlayerIndex'] = nextIndex;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> passBlokusTurn(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null)
      throw Exception(_l10n.nonAuthentifie);

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception(_l10n.actionNonAutorisee);
      }

      final playerOrder = List<String>.from(gameData['blokusPlayerOrder']);
      if (playerOrder[gameData['blokusCurrentPlayerIndex']] != playerId) return;

      List<String> passedPlayers = List<String>.from(
        gameData['blokusPassedPlayers'] ?? [],
      );
      if (!passedPlayers.contains(playerId)) passedPlayers.add(playerId);

      Map<String, dynamic> updates = {'blokusPassedPlayers': passedPlayers};

      bool allPassed = passedPlayers.length >= playerOrder.length;
      int nextIndex =
          (gameData['blokusCurrentPlayerIndex'] + 1) % playerOrder.length;
      int loopCount = 0;
      while (passedPlayers.contains(playerOrder[nextIndex]) &&
          loopCount < playerOrder.length) {
        nextIndex = (nextIndex + 1) % playerOrder.length;
        loopCount++;
      }
      if (loopCount >= playerOrder.length) {
        allPassed = true;
      }

      if (allPassed) {
        Map<String, dynamic> lastPiecesPlaced = Map<String, dynamic>.from(
          gameData['blokusLastPiecesPlaced'] ?? {},
        );
        Map<String, int> scores = {};
        playerOrder.forEach((pId) {
          List<int> pHand = List<int>.from(
            gameData['blokusPlayerHands'][pId] ?? [],
          );
          int remainingSquares = pHand.fold(
            0,
            (sum, id) => sum + GameData.blokusPieces[id]!.length,
          );
          int score = -remainingSquares;
          if (remainingSquares == 0) {
            score += 15;
            if (lastPiecesPlaced[pId] == 1) score += 5;
          }
          scores[pId] = score;
        });
        String winnerId =
            scores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'players.$winnerId.score': FieldValue.increment(1),
          'blokusScores': scores,
          'gameEndReason': _l10n.finDeLaPartie,
        });
      } else {
        updates['blokusCurrentPlayerIndex'] = nextIndex;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }
      transaction.update(gameRef, updates);
    });
  }
}

void showGameRules(BuildContext context, String gameType) {
  showDialog(
    context: context,
    builder: (BuildContext context) {
      String rules = GameData.gameRules[gameType] ?? "";
      if (rules.trim().isEmpty) {
        final loc = GameRulesLocalization.getRules(context, gameType);
        final notFound = GameRulesLocalization.tr(context, 'noRulesFound');
        if (loc.trim().isNotEmpty && loc != notFound) {
          rules = loc;
        }
      }
      if (rules.trim().isEmpty) {
        rules = GameRulesLocalization.tr(context, 'noRulesFound');
      }
      return AlertDialog(
        title: Text(AppLocalizations.of(context)!.rulesTitle),
        content: SingleChildScrollView(child: Text(rules)),
        actions: <Widget>[
          TextButton(
            child: Text(AppLocalizations.of(context)!.understoodButton),
            onPressed: () => Navigator.of(context).pop(),
          ),
        ],
      );
    },
  );
}

