                  ? _turnTimerSeconds
                  : null,
          undercoverRoleSettings: _undercoverRoleSettings,
          selectedLoupGarouRoles: _selectedLoupGarouRoles,
          petitsChevauxTeamMode:
              _selectedGame == 'Petits Chevaux' ? _petitsChevauxTeamMode : null,
          pokerStartChips: _selectedGame == 'Poker' ? _pokerStartChips : null,
          pokerSmallBlind: _selectedGame == 'Poker' ? _pokerSmallBlind : null,
          pokerBigBlind: _selectedGame == 'Poker' ? _pokerBigBlind : null,
          pictionaryOnly30Strokes: _pictionaryOnly30Strokes,
          pictionaryUseTeams: _pictionaryUseTeams,
          justOneAllowInvalidClues: _justOneAllowInvalidClues,
          cadavreVariant: _cadavreVariant,
          cadavrePassingMode: _cadavrePassingMode,
          aiInstructions:
              (playerState.isPremium &&
                      _aiSupportedGames.contains(_selectedGame))
                  ? (_aiInstructionsController.text.trim().isNotEmpty
                      ? _aiInstructionsController.text.trim()
                      : null)
                  : null,
          aiWords: preGeneratedAiWords,
          dobbleSymbolsPerCard: _dobbleSymbolsPerCard,
          isSimplifiedLiar: _isSimplifiedLiar,
          liarVoteMode: _liarVoteMode,
          presidentRevolution: _presidentRevolution,
          zeroPointeTargetScore: _zeroPointeTargetScore,
          gribouillisMode: _gribouillisMode,
          devineTeteUseTeams: _devineTeteUseTeams,
          hotPotatoUseGlobalTimer: _hotPotatoUseGlobalTimer,
          hotPotatoGlobalDuration: _hotPotatoGlobalDuration,
          selectedCategoriesList: _selectedGameCategories,
          aoVPlayersDecide:
              _selectedGame == 'Action ou Vérité' ? _aoVPlayersDecide : null,
          aoVVoteThreshold:
              _selectedGame == 'Action ou Vérité' ? _aoVVoteThreshold : null,
          aoVMaxRounds:
              _selectedGame == 'Action ou Vérité' ? _aoVMaxRounds : null,
        );

        await FirebaseFirestore.instance
            .collection('games')
            .doc(gameCode)
            .update({'loungeId': widget.loungeId});

        await FirebaseFirestore.instance
            .collection('lounges')
            .doc(widget.loungeId)
            .update({
              'pendingGame': {
                'gameCode': gameCode,
                'gameName': _selectedGame,
                'hostId': widget.playerId,
                'status': 'waiting',
                'joinedPlayers': [widget.playerId],
              },
            });

        await _firebaseService.sendLoungeMessage(
          widget.loungeId!,
          widget.playerId,
          widget.playerName,
          AppLocalizations.of(context)!.jAiLanceUnePartie(_selectedGame),
          type: 'game_invite',
          extraData: {
            'gameCode': gameCode,
            'gameName': _selectedGame,
            'hostId': widget.playerId,
          },
        );

        if (mounted) Navigator.pop(context);
        return;
      }

      final bool isAiActive =
          (_selectedAiWords != null && _selectedAiWords!.isNotEmpty) ||
          _aiInstructionsController.text.trim().isNotEmpty ||
          _selectedAiThemes.isNotEmpty;
      String effectiveDifficulty =
          isAiActive
              ? AppLocalizations.of(context)!.ia
              : (_gameHasDifficulty(_selectedGame)
                  ? _selectedDifficulty
                  : 'N/A');

      String gameCode = await _firebaseService.createGame(
        widget.playerName,
        widget.playerId,
        _selectedGame,
        effectiveDifficulty,
        dobbleSymbolsPerCard: _dobbleSymbolsPerCard,
        isSimplifiedLiar: _isSimplifiedLiar,
        liarVoteMode: _liarVoteMode,
        cadavreVariant: _cadavreVariant,
        cadavrePassingMode: _cadavrePassingMode,
        petitBacCategories: _petitBacCategories,
        petitBacTime: _turnTimerSeconds,
        presidentRevolution: _presidentRevolution,
        pictionaryOnly30Strokes: _pictionaryOnly30Strokes,
        pictionaryUseTeams: _pictionaryUseTeams,
        selectedCategoriesList: _selectedGameCategories,
        justOneAllowInvalidClues: _justOneAllowInvalidClues,
        selectedLoupGarouRoles: _selectedLoupGarouRoles,
        devineTeteUseTeams: _devineTeteUseTeams,
        unoStartingCards: _unoStartingCards,
        unoStackDraws: _unoStackDraws,
        timesUpTotalRounds: _timesUpTotalRounds,
        dominoesMode: _dominoesMode,
        dominoesTargetScore: _dominoesTargetScore,
        zeroPointeTargetScore: _zeroPointeTargetScore,
        pokerStartChips: _pokerStartChips,
        pokerSmallBlind: _pokerSmallBlind,
        pokerBigBlind: _pokerBigBlind,
        hotPotatoUseGlobalTimer: _hotPotatoUseGlobalTimer,
        hotPotatoGlobalDuration: _hotPotatoGlobalDuration,
        gribouillisMode: _gribouillisMode,
        gribouillisAjouter1: _gribouillisAjouter1,
        photoRouletteRounds: _photoRouletteRounds,
        photoRoulettePhotosPerPlayer: _photoRoulettePhotosPerPlayer,
        photoRouletteMediaType: _photoRouletteMediaType,
        isPremiumLobby: playerState.isPremium,
        videoEnabled: _videoEnabled,
        audioEnabled: _audioEnabled,
        aiInstructions:
            (playerState.isPremium && _aiSupportedGames.contains(_selectedGame))
                ? (_aiInstructionsController.text.trim().isNotEmpty
                    ? _aiInstructionsController.text.trim()
                    : null)
                : null,
        aiWords: preGeneratedAiWords,
        undercoverRoleSettings: _undercoverRoleSettings,
        infiltreCount: _infiltreCount,
        mrWhiteCount: _mrWhiteCount,
        useTimer: _useTimer,
        turnTimerSeconds: _turnTimerSeconds,
        resultTimerSeconds: _resultTimerSeconds,
        petitsChevauxTeamMode: _petitsChevauxTeamMode,
        enableFloatingChat:
            _enableFloatingChat &&
            !['Loup-Garou', 'Infiltré & Mr. White'].contains(_selectedGame),
        aoVPlayersDecide:
            _selectedGame == 'Action ou Vérité' ? _aoVPlayersDecide : null,
        aoVVoteThreshold:
            _selectedGame == 'Action ou Vérité' ? _aoVVoteThreshold : null,
        aoVMaxRounds:
            _selectedGame == 'Action ou Vérité' ? _aoVMaxRounds : null,
      );

      if (!mounted) return;

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder:
              (_) => GameLobbyScreen(
                gameCode: gameCode,
                playerId: widget.playerId,
              ),
        ),
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              AppLocalizations.of(
                context,
              )!.erreurLorsDeLaCreation.replaceAll("{0}", e.toString()),
            ),
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  void _startMatchmaking({required bool isRanked}) async {
    final playerState = Provider.of<PlayerState>(context, listen: false);

    List<String>? preGeneratedAiWords = _selectedAiWords;
    if (preGeneratedAiWords == null &&
        playerState.isPremium &&
        _aiSupportedGames.contains(_selectedGame) &&
        (_aiInstructionsController.text.trim().isNotEmpty ||
            _selectedAiThemes.isNotEmpty)) {
      setState(() => _isAiLoading = true);
      try {
        final promptText = _aiInstructionsController.text.trim();
        final formattedPrompt = FirebaseService.formatAiPromptForGame(
          _selectedGame,
          promptText,
          themes: _selectedAiThemes.toList(),
          style: _selectedAiStyle,
        );
        final count =
            _customAiWordCount ??
            FirebaseService.getAiWordCountForGame(_selectedGame);
        preGeneratedAiWords = await FirebaseService.generateAiWords(
          instructions: formattedPrompt,
          count: count,
          gameType: _selectedGame,
        );
      } catch (e) {
        print('Erreur génération IA: $e');
      } finally {
        if (mounted) setState(() => _isAiLoading = false);
      }
    }

    if (!await playerState.canPlayMultiplayer()) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            AppLocalizations.of(context)!.vousAvezAtteintVotreLimite,
          ),
        ),
      );
      return;
    }

    int cost = 1;
    bool success = await playerState.spendCoins(cost);
    if (!success) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(AppLocalizations.of(context)!.pasAssezDePiecesPour1),
        ),
      );
      return;
    }

    await playerState.recordMultiplayerGame();
    if (_videoEnabled) {
      await playerState.recordVideoGamePlayed();
    }

    final bool isAiActive =
        (_selectedAiWords != null && _selectedAiWords!.isNotEmpty) ||
        _aiInstructionsController.text.trim().isNotEmpty ||
        _selectedAiThemes.isNotEmpty;
    String effectiveDifficulty =
        isAiActive
            ? AppLocalizations.of(context)!.ia
            : (_gameHasDifficulty(_selectedGame) ? _selectedDifficulty : 'N/A');

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder:
            (_) => SearchingForPlayersScreen(
              playerId: widget.playerId,
              playerName: widget.playerName,
              gameName: _selectedGame,
              playerCount: _playerCount.toInt(),
              scope: _scope,
              videoEnabled: _videoEnabled,
              audioEnabled: _audioEnabled,
              videoPreference: _videoEnabled ? 'with' : _videoPreference,
              isRanked: isRanked,
              devineTeteUseTeams:
                  _selectedGame == 'Devine Tête' ? _devineTeteUseTeams : false,
              difficulty: effectiveDifficulty,
              dobbleSymbolsPerCard:
                  _selectedGame == 'Dobble' ? _dobbleSymbolsPerCard : false,
              isSimplifiedLiar:
                  _selectedGame == 'Le Menteur' ? _isSimplifiedLiar : false,
              liarVoteMode:
                  _selectedGame == 'Le Menteur'
                      ? _liarVoteMode
                      : 'simultaneous',
              quiPourraitVoteMode:
                  _selectedGame == 'Qui Pourrait le Plus ?'
                      ? _quiPourraitVoteMode
                      : 'simultaneous',
              petitBacCategories:
                  _selectedGame == 'Petit Bac' ? _petitBacCategories : null,
              petitBacTime:
                  _selectedGame == 'Petit Bac' ? _turnTimerSeconds : null,
              presidentRevolution:
                  _selectedGame == "Président" ? _presidentRevolution : false,
              pictionaryOnly30Strokes:
                  _selectedGame == 'Pictionary'
                      ? _pictionaryOnly30Strokes
                      : false,
              pictionaryUseTeams:
                  _selectedGame == 'Pictionary' ? _pictionaryUseTeams : false,
              justOneAllowInvalidClues:
                  _selectedGame == 'Just One'
                      ? _justOneAllowInvalidClues
                      : false,
              selectedLoupGarouRoles:
                  _selectedGame == 'Loup-Garou'
                      ? _selectedLoupGarouRoles
                      : null,
              unoStartingCards:
                  _selectedGame == 'Uno' ? _unoStartingCards : null,
              unoStackDraws: _selectedGame == 'Uno' ? _unoStackDraws : null,
              timesUpTotalRounds:
                  _selectedGame == "Time's Up" ? _timesUpTotalRounds : null,
              dominoesMode: _selectedGame == 'Dominoes' ? _dominoesMode : null,
              dominoesTargetScore:
                  _selectedGame == 'Dominoes' ? _dominoesTargetScore : null,
              zeroPointeTargetScore:
                  _selectedGame == 'Zéro Pointé'
                      ? _zeroPointeTargetScore
                      : null,
              pokerStartChips:
                  _selectedGame == 'Poker' ? _pokerStartChips : null,
              pokerSmallBlind:
                  _selectedGame == 'Poker' ? _pokerSmallBlind : null,
              pokerBigBlind: _selectedGame == 'Poker' ? _pokerBigBlind : null,
              hotPotatoUseGlobalTimer:
                  _selectedGame == 'La Patate Chaude'
                      ? _hotPotatoUseGlobalTimer
                      : null,
              hotPotatoGlobalDuration:
                  _selectedGame == 'La Patate Chaude'
                      ? _hotPotatoGlobalDuration
                      : null,
              gribouillisMode:
                  _selectedGame == 'Gribouillis' ? _gribouillisMode : null,
              gribouillisAjouter1:
                  _selectedGame == 'Gribouillis' ? _gribouillisAjouter1 : null,
              photoRouletteRounds:
                  _selectedGame == 'Photo Roulette'
                      ? _photoRouletteRounds
                      : null,
              photoRoulettePhotosPerPlayer:
                  _selectedGame == 'Photo Roulette'
                      ? _photoRoulettePhotosPerPlayer
                      : null,
              photoRouletteMediaType:
                  _selectedGame == 'Photo Roulette'
                      ? _photoRouletteMediaType
                      : null,
              aiInstructions:
                  (playerState.isPremium &&
                          _aiSupportedGames.contains(_selectedGame))
                      ? (_aiInstructionsController.text.trim().isNotEmpty
                          ? _aiInstructionsController.text.trim()
                          : null)
                      : null,
              aiWords: preGeneratedAiWords,
            ),
      ),
    );
  }

  void _showLaunchOptions(bool canLocal, bool canMonde) {
    // Vérifie si la communication est activée pour griser le mode Local
    final bool isCommunicationEnabled = _videoEnabled || _audioEnabled;
    // Vérifie si la recherche publique est activée pour griser Local et Privé
    final bool isPublicSearchEnabled = _enablePublicSearch;
    final bool isDevineTete =
        _selectedGame.contains('Devine Tête') ||
        _selectedGame.contains(AppLocalizations.of(context)!.devineT);
    final bool blockOnlineForDevineTete = isDevineTete && !_videoEnabled;

    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.grey[900],
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) {
        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                AppLocalizations.of(context)!.commentVoulezVousJouer,
                style: Theme.of(context).textTheme.headlineSmall,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 24),
              if (canLocal) ...[
                ElevatedButton.icon(
                  icon: Icon(Icons.phone_android),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        isPublicSearchEnabled || isCommunicationEnabled
                            ? Colors.grey
                            : Colors.green,
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      isPublicSearchEnabled
                          ? () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  AppLocalizations.of(
                                    context,
                                  )!.desactivezLaRecherchePubliquePour,
                                ),
                              ),
                            );
                          }
                          : isCommunicationEnabled
                          ? () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  AppLocalizations.of(
                                    context,
                                  )!.desactivezLaVideoOuL,
                                ),
                              ),
                            );
                          }
                          : () {
                            Navigator.pop(ctx);
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder:
                                    (_) => LocalPlayerSetupScreen(
                                      targetGame: _selectedGame,
                                    ),
                              ),
                            );
                          },
                  label: Text(
                    isPublicSearchEnabled
                        ? AppLocalizations.of(
                          ctx,
                        )!.localIndisponibleRechercheActive
                        : isCommunicationEnabled
                        ? AppLocalizations.of(
                          context,
                        )!.localIndisponibleVideoAudioActif
                        : AppLocalizations.of(context)!.jouerEnLocalSurCet,
                  ),
                ),
                SizedBox(height: 12),
              ],

              ElevatedButton.icon(
                icon: Icon(Icons.lock),
                style: ElevatedButton.styleFrom(
                  backgroundColor:
                      (isPublicSearchEnabled || blockOnlineForDevineTete)
                          ? Colors.grey
                          : Colors.deepPurple,
                  minimumSize: Size(double.infinity, 50),
                ),
                onPressed:
                    (isPublicSearchEnabled || blockOnlineForDevineTete)
                        ? () {
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(
                              content: Text(
                                blockOnlineForDevineTete
                                    ? AppLocalizations.of(
                                      context,
                                    )!.laVideoEstObligatoirePour
                                    : AppLocalizations.of(
                                      context,
                                    )!.desactivezLaRecherchePubliquePour1,
                              ),
                            ),
                          );
                        }
                        : () {
                          Navigator.pop(ctx);
                          _createGameForFriends();
                        },
                label: Text(
                  isPublicSearchEnabled
                      ? AppLocalizations.of(
                        context,
                      )!.priveIndisponibleRechercheActive
                      : blockOnlineForDevineTete
                      ? AppLocalizations.of(
                        context,
                      )!.priveIndisponibleVideoRequise
                      : AppLocalizations.of(context)!.creerUnePartiePriveeAvec,
                ),
              ),
              SizedBox(height: 12),

              // N'affiche le Matchmaking public que si le jeu le permet (canMonde)
              if (canMonde) ...[
                ElevatedButton.icon(
                  icon: Icon(Icons.public),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _enablePublicSearch ? Colors.blue : Colors.grey[800],
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      _enablePublicSearch
                          ? () {
                            Navigator.pop(ctx);
                            _startMatchmaking(isRanked: false);
                          }
                          : () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  blockOnlineForDevineTete
                                      ? AppLocalizations.of(
                                        context,
                                      )!.laVideoEstObligatoirePour
                                      : AppLocalizations.of(
                                        context,
                                      )!.activezLeBoutonRecherchePublique,
                                ),
                              ),
                            );
                          },
                  label: Text(
                    _enablePublicSearch
                        ? AppLocalizations.of(ctx)!.rechercheRapideMonde
                        : blockOnlineForDevineTete
                        ? AppLocalizations.of(
                          context,
                        )!.rechercheRapideVideoRequise
                        : AppLocalizations.of(
                          context,
                        )!.rechercheMondeDesactivee,
                  ),
                ),
                SizedBox(height: 12),
                ElevatedButton.icon(
                  icon: Icon(Icons.star, color: Colors.white),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _enablePublicSearch
                            ? Colors.orange[800]
                            : Colors.grey[800],
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      _enablePublicSearch
                          ? () {
                            Navigator.pop(ctx);
                            _startMatchmaking(isRanked: true);
                          }
                          : () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  blockOnlineForDevineTete
                                      ? AppLocalizations.of(
                                        context,
                                      )!.laVideoEstObligatoirePour1
                                      : AppLocalizations.of(
                                        context,
                                      )!.activezLeBoutonRecherchePublique1,
                                ),
                              ),
                            );
                          },
                  label: Text(
                    _enablePublicSearch
                        ? AppLocalizations.of(context)!.partieClasseeRanked
                        : blockOnlineForDevineTete
                        ? AppLocalizations.of(
                          context,
                        )!.partieClasseeVideoRequise
                        : AppLocalizations.of(context)!.partieClasseeDesactivee,
                  ),
                ),
              ],

              if (!canMonde && widget.isWorldMode) ...[
                Text(
                  AppLocalizations.of(context)!.ceJeuRequiertDeConnaitre,
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: Colors.redAccent,
                    fontStyle: FontStyle.italic,
                  ),
                ),
              ],
            ],
          ),
        );
      },
    );
  }

  /// Ouvre l'historique Firebase dans une bottom sheet
  void _openAiHistorySheet(BuildContext context, String uid) {
    String historyFilter = _selectedGame; // 'all' or specific game
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Color(0xFF141422),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (ctx) {
        return StatefulBuilder(
          builder: (context, setSheetState) {
            return SizedBox(
              height: MediaQuery.of(context).size.height * 0.88,
              child: Column(
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 12,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.black.withOpacity(0.4),
                      borderRadius: const BorderRadius.vertical(
                        top: Radius.circular(24),
                      ),
                      border: Border(bottom: BorderSide(color: Colors.white12)),
                    ),
                    child: Column(
                      children: [
                        Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Row(
                              children: [
                                Icon(
                                  Icons.history_rounded,
                                  color: Colors.cyanAccent,
                                  size: 22,
                                ),
                                SizedBox(width: 8),
                                Text(
                                  AppLocalizations.of(
                                    context,
                                  )!.historiqueDesThemesIa,
                                  style: TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.bold,
                                    fontSize: 16,
                                  ),
                                ),
                              ],
                            ),
                            IconButton(
                              icon: Icon(Icons.close, color: Colors.white70),
                              onPressed: () => Navigator.pop(ctx),
                            ),
                          ],
                        ),
                        SizedBox(height: 10),
                        // Filtres : AppLocalizations.of(context)!.ceJeu vs "Tous les jeux"
                        Row(
                          children: [
                            Expanded(
                              child: GestureDetector(
                                onTap:
                                    () => setSheetState(
                                      () => historyFilter = _selectedGame,
                                    ),
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    vertical: 8,
                                  ),
                                  decoration: BoxDecoration(
                                    color:
                                        historyFilter == _selectedGame
                                            ? Colors.cyanAccent.withOpacity(0.2)
                                            : Colors.white.withOpacity(0.05),
                                    borderRadius: BorderRadius.circular(10),
                                    border: Border.all(
                                      color:
                                          historyFilter == _selectedGame
                                              ? Colors.cyanAccent
                                              : Colors.white12,
                                    ),
                                  ),
                                  child: Center(
                                    child: Text(
                                      GameContentLocalization.format(
                                        context,
                                        AppLocalizations.of(context)!.pour,
                                        [_selectedGame],
                                      ),
                                      style: TextStyle(
                                        color:
                                            historyFilter == _selectedGame
                                                ? Colors.cyanAccent
                                                : Colors.white60,
                                        fontWeight: FontWeight.bold,
                                        fontSize: 12,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                            SizedBox(width: 8),
                            Expanded(
                              child: GestureDetector(
                                onTap:
                                    () => setSheetState(
                                      () => historyFilter = 'all',
                                    ),
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    vertical: 8,
                                  ),
                                  decoration: BoxDecoration(
                                    color:
                                        historyFilter == 'all'
                                            ? Colors.cyanAccent.withOpacity(0.2)
                                            : Colors.white.withOpacity(0.05),
                                    borderRadius: BorderRadius.circular(10),
                                    border: Border.all(
                                      color:
                                          historyFilter == 'all'
                                              ? Colors.cyanAccent
                                              : Colors.white12,
                                    ),
                                  ),
                                  child: Center(
                                    child: Text(
                                      AppLocalizations.of(context)!.tousLesJeux,
                                      style: TextStyle(
                                        color:
                                            historyFilter == 'all'
                                                ? Colors.cyanAccent
                                                : Colors.white60,
                                        fontWeight: FontWeight.bold,
                                        fontSize: 12,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                  Expanded(
                    child: StreamBuilder<List<AiThemeHistoryItem>>(
                      stream: _firebaseService.getAiHistoryStream(
                        uid,
                        historyFilter,
                      ),
                      builder: (context, snapshot) {
                        if (!snapshot.hasData) {
                          return Center(child: CircularProgressIndicator());
                        }
                        final items = snapshot.data ?? [];
                        if (items.isEmpty) {
                          return Center(
                            child: Padding(
                              padding: const EdgeInsets.all(24.0),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Icon(
                                    Icons.auto_awesome,
                                    size: 48,
                                    color: Colors.white24,
                                  ),
                                  SizedBox(height: 12),
                                  Text(
                                    historyFilter == 'all'
                                        ? AppLocalizations.of(
                                          context,
                                        )!.aucunThemeIaSauvegardeSur
                                        : GameContentLocalization.format(
                                          context,
                                          AppLocalizations.of(
                                            context,
                                          )!.aucunThemeSauvegardePour,
                                          [_selectedGame],
                                        ),
                                    style: TextStyle(
                                      color: Colors.white54,
                                      fontSize: 14,
                                    ),
                                    textAlign: TextAlign.center,
