  /// Boîte de dialogue pour modifier la liste et demander à l'IA de rajouter X mots
  void _openEditDialog(
    BuildContext context,
    String uid,
    AiThemeHistoryItem item,
  ) {
    final titleCtrl = TextEditingController(text: item.title);
    final addWordCtrl = TextEditingController();
    List<String> wordsList = List.from(item.words);
    bool isGeneratingMore = false;

    showDialog(
      context: context,
      builder: (dCtx) {
        return StatefulBuilder(
          builder: (context, setDState) {
            return AlertDialog(
              backgroundColor: Color(0xFF1B1B2A),
              title: Text(
                AppLocalizations.of(context)!.modifierLeTheme,
                style: TextStyle(color: Colors.white, fontSize: 18),
              ),
              content: SizedBox(
                width: double.maxFinite,
                height: 420,
                child: Column(
                  children: [
                    TextField(
                      controller: titleCtrl,
                      decoration: InputDecoration(
                        labelText:
                            AppLocalizations.of(
                              context,
                            )!.titreDuThemeIaPersonnalise,
                      ),
                      style: TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: addWordCtrl,
                            decoration: InputDecoration(
                              hintText:
                                  AppLocalizations.of(context)!.ajouterUnMot,
                            ),
                            onSubmitted: (v) {
                              if (v.trim().isNotEmpty) {
                                setDState(() {
                                  wordsList.add(v.trim());
                                  addWordCtrl.clear();
                                });
                              }
                            },
                          ),
                        ),
                        IconButton(
                          icon: Icon(
                            Icons.add_circle,
                            color: Colors.greenAccent,
                          ),
                          onPressed: () {
                            if (addWordCtrl.text.trim().isNotEmpty) {
                              setDState(() {
                                wordsList.add(addWordCtrl.text.trim());
                                addWordCtrl.clear();
                              });
                            }
                          },
                        ),
                      ],
                    ),
                    SizedBox(height: 8),
                    // Bouton IA pour compléter la liste
                    SizedBox(
                      width: double.infinity,
                      child: OutlinedButton.icon(
                        icon:
                            isGeneratingMore
                                ? SizedBox(
                                  width: 14,
                                  height: 14,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                    color: Colors.amberAccent,
                                  ),
                                )
                                : Icon(
                                  Icons.auto_awesome,
                                  size: 16,
                                  color: Colors.amberAccent,
                                ),
                        label: Text(
                          isGeneratingMore
                              ? AppLocalizations.of(context)!.generationEnCours
                              : AppLocalizations.of(
                                context,
                              )!.completerAvecLIa15,
                          style: TextStyle(
                            color: Colors.amberAccent,
                            fontSize: 12,
                          ),
                        ),
                        onPressed:
                            isGeneratingMore
                                ? null
                                : () async {
                                  setDState(() => isGeneratingMore = true);
                                  try {
                                    final formattedPrompt =
                                        FirebaseService.formatAiPromptForGame(
                                          item.gameType,
                                          AppLocalizations.of(
                                            context,
                                          )!.completeCetteListeSurLe(
                                            titleCtrl.text,
                                            wordsList.take(10).join(', '),
                                          ),
                                        );
                                    final addedWords =
                                        await FirebaseService.generateAiWords(
                                          instructions: formattedPrompt,
                                          count: 15,
                                          gameType: item.gameType,
                                        );
                                    if (addedWords.isNotEmpty) {
                                      setDState(() {
                                        for (var w in addedWords) {
                                          if (!wordsList.contains(w))
                                            wordsList.add(w);
                                        }
                                      });
                                    }
                                  } finally {
                                    setDState(() => isGeneratingMore = false);
                                  }
                                },
                      ),
                    ),
                    SizedBox(height: 8),
                    Expanded(
                      child: Container(
                        padding: const EdgeInsets.all(8),
                        decoration: BoxDecoration(
                          color: Colors.black26,
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: SingleChildScrollView(
                          child: Wrap(
                            spacing: 6,
                            runSpacing: 6,
                            children:
                                wordsList.map((w) {
                                  return Chip(
                                    label: Text(
                                      w,
                                      style: TextStyle(fontSize: 12),
                                    ),
                                    onDeleted:
                                        () => setDState(
                                          () => wordsList.remove(w),
                                        ),
                                  );
                                }).toList(),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(dCtx),
                  child: Text(AppLocalizations.of(context)!.annuler),
                ),
                ElevatedButton(
                  onPressed: () async {
                    await _firebaseService.saveAiThemeToFirebase(
                      uid: uid,
                      prompt: item.prompt,
                      gameType: item.gameType,
                      words: wordsList,
                      title: titleCtrl.text.trim(),
                      existingDocId: item.id,
                    );
                    if (_activeAiDocId == item.id) {
                      setState(() {
                        _selectedAiWords = wordsList;
                        _activeAiThemeTitle = titleCtrl.text.trim();
                      });
                    }
                    Navigator.pop(dCtx);
                  },
                  child: Text(
                    AppLocalizations.of(context)!.enregistrerSurFirebase,
                  ),
                ),
              ],
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    int totalRolesCount = _selectedLoupGarouRoles.values.fold(
      0,
      (sum, count) => sum + count,
    );
    bool canProceed = true;
    String validationMessage = "";

    if (_selectedGame == 'Loup-Garou') {
      if (totalRolesCount < 5) {
        canProceed = false;
        validationMessage =
            AppLocalizations.of(context)!.selectionnezAuMoins5Roles;
      }
    }

    final gameDataInfo = allAppGames.firstWhere(
      (g) => g['name'] == _selectedGame,
      orElse:
          () => {
            'modes': ['multi'],
          },
    );
    final modes = gameDataInfo['modes'] as List<String>;
    final bool canLocal = modes.contains('local');
    bool isDevineTete =
        _selectedGame.contains('Devine Tête') ||
        _selectedGame.contains(AppLocalizations.of(context)!.devineT);
    bool forceVideo = false;
    final bool isAiActive =
        (_selectedAiWords != null && _selectedAiWords!.isNotEmpty) ||
        _aiInstructionsController.text.trim().isNotEmpty ||
        _selectedAiThemes.isNotEmpty;

    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.creerUnePartie1),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, _selectedGame),
          ),
        ],
      ),
      body:
          _isLoading
              ? Center(child: CircularProgressIndicator())
              : SingleChildScrollView(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    DropdownButtonFormField<String>(
                      value: _selectedGame,
