                          if (forceVideo && canEnableVideo && !_videoEnabled) {
                            WidgetsBinding.instance.addPostFrameCallback((_) {
                              setState(() {
                                _videoEnabled = true;
                                _audioEnabled = false;
                              });
                            });
                          }

                          return Column(
