class _PetitBacInputField extends StatefulWidget {
  final String category;
  final String currentLetter;
  final String initialValue;
  final Function(String) onSubmitted;

  const _PetitBacInputField({
    Key? key,
    required this.category,
    required this.currentLetter,
    required this.initialValue,
    required this.onSubmitted,
  }) : super(key: key);

  @override
  State<_PetitBacInputField> createState() => _PetitBacInputFieldState();
}

class _PetitBacInputFieldState extends State<_PetitBacInputField> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(text: widget.initialValue);
  }

  @override
  void didUpdateWidget(_PetitBacInputField oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.category != widget.category ||
        oldWidget.currentLetter != widget.currentLetter) {
      _controller.text = widget.initialValue;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          widget.category.toUpperCase(),
          style: TextStyle(
            color: Colors.grey[600],
            fontSize: 12,
            fontWeight: FontWeight.bold,
          ),
        ),
        TextField(
          controller: _controller,
          style: TextStyle(
            color: Colors.indigo[900],
            fontSize: 18,
            fontFamily: 'Courier',
          ),
          decoration: InputDecoration(
            hintText: "${widget.currentLetter}...",
            hintStyle: TextStyle(color: Colors.grey[300]),
            border: InputBorder.none,
            isDense: true,
            contentPadding: const EdgeInsets.symmetric(vertical: 8),
          ),
          onChanged: widget.onSubmitted,
        ),
      ],
    );
  }
}

class MultiplayerGameScreen extends StatefulWidget {
  final String gameCode;
  final String playerId;
  final String? loungeId;

  MultiplayerGameScreen({
    required this.gameCode,
    required this.playerId,
    this.loungeId,
  });

  @override
  _MultiplayerGameScreenState createState() => _MultiplayerGameScreenState();
}

class _MultiplayerGameScreenState extends State<MultiplayerGameScreen>
    with WidgetsBindingObserver {
  Future<void> _safePopToFirst() async {
    if (_livekitInitialized) {
      try {
        await _livekitService.leaveChannel();
      } catch (e) {
        print('Erreur leaveChannel safePop: $e');
      }
    }
    if (mounted) {
      Navigator.of(context).popUntil((route) => route.isFirst);
    }
  }

  void _exitGame() async {
    final String playerId = widget.playerId;

    if (_livekitInitialized) {
      try {
        await _livekitService.leaveChannel();
      } catch (e) {
        print('Erreur lors de la déconnexion LiveKit : $e');
      }
    }

    // Nettoyage complet du salon avant de quitter pour éviter la boucle de redirection
    if (widget.loungeId != null) {
      try {
        final loungeDocRef = FirebaseFirestore.instance
            .collection('lounges')
            .doc(widget.loungeId);
        final loungeSnap = await loungeDocRef.get();

        if (loungeSnap.exists) {
          final loungeData = loungeSnap.data() as Map<String, dynamic>;
          final pendingGame = loungeData['pendingGame'];

          if (pendingGame != null) {
            if (pendingGame['hostId'] == playerId) {
              await loungeDocRef.update({'pendingGame': FieldValue.delete()});
            } else {
              await loungeDocRef.update({
                'pendingGame.joinedPlayers': FieldValue.arrayRemove([playerId]),
              });
            }
          }
        }
      } catch (e) {
        print('Erreur lors du nettoyage du salon de jeu : $e');
      }

      if (mounted) {
        Navigator.of(context).pop();
      }
    } else {
      if (mounted) {
        Navigator.of(context).popUntil((route) => route.isFirst);
      }
    }
  }

  Future<void> _confirmAndExitGame() async {
    final shouldLeave = await showDialog<bool>(
      context: context,
      builder:
          (ctx) => AlertDialog(
            title: Text(AppLocalizations.of(context)!.quitterLaPartie),
            content: Text(
              AppLocalizations.of(context)!.siVousQuittezVotrePlace,
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: Text(AppLocalizations.of(context)!.rester),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
                onPressed: () => Navigator.pop(ctx, true),
                child: Text(AppLocalizations.of(context)!.quitter),
              ),
            ],
          ),
    );

    if (shouldLeave == true && mounted) {
      if (_livekitInitialized) {
        await _livekitService.leaveChannel();
      }
      if (widget.loungeId != null) {
        FirebaseFirestore.instance
            .collection('lounges')
            .doc(widget.loungeId)
            .update({
              'pendingGame.joinedPlayers': FieldValue.arrayRemove([
                widget.playerId,
              ]),
            });
      }
      _firebaseService.removePlayerFromGame(widget.gameCode, widget.playerId);
      Navigator.of(context).popUntil((route) => route.isFirst);
    }
  }

  int? _lastKnownPlayerXp;
  final List<int> _activeXpPopups = [];

  void _triggerXpAnimation(int amount) {
    if (amount <= 0) return;
    setState(() {
      _activeXpPopups.add(amount);
    });
  }

  final FirebaseService _firebaseService = FirebaseService();
  final TextEditingController _answerController = TextEditingController();

  Map<String, String> _playerLivekitIdentities =
      {}; // Mapping playerId -> agoraUid
  final _answerControllers = <String, TextEditingController>{};
  int _lastProcessedRound = 0;
  // Dans _MultiplayerGameScreenState
  Timer? _postGameTimer;
  int _postGameCountdown = 15; // Temps pour voter
  int _refillCountdown = 10; // Temps pour trouver des joueurs
  List<String> _selectedPresidentCards = [];
  List<String> _selectedRamiCards = [];
  List<String> _selectedBigTwoCards = [];
  String? _selectedCheckersPiece; // Pour stocker la pièce sélectionnée "r,c"
  String?
  _selectedDominoTile; // Pour la sélection préalable et survol de Dominos
  int?
  _selectedLudoPawnIdx; // Pour la sélection préalable de pion Petits Chevaux
  String?
