  // =========================================================================
  // 1. GESTION CENTRALISÉE DU TIMER (HÔTE & JOUEUR ACTIF)
  // =========================================================================

  String _computeTurnKey(
    Map<String, dynamic> gameData,
    Timestamp turnStartTimeStamp,
  ) {
    final idx =
        gameData['currentPlayerIndex'] ??
        gameData['currentJudgeIndex'] ??
        gameData['currentDescriberIndex'] ??
        gameData['currentTurnPlayerIndex'] ??
        gameData['pokerCurrentPlayerIndex'] ??
        gameData['unoCurrentPlayerIndex'] ??
        gameData['zeroPointeCurrentPlayerIndex'] ??
        gameData['milleBornesCurrentPlayerIndex'] ??
        gameData['petitsChevauxCurrentIndex'] ??
        gameData['bigTwoCurrentPlayerIndex'] ??
        gameData['checkersCurrentPlayerIndex'] ??
        gameData['skullCurrentPlayerIndex'] ??
        gameData['blokusCurrentPlayerIndex'] ??
        gameData['zombieCurrentPlayerIndex'] ??
        gameData['beloteCurrentPlayerIndex'] ??
        gameData['dominoesCurrentPlayerIndex'] ??
        gameData['ramiCurrentPlayerId'] ??
        gameData['yamsCurrentPlayerId'] ??
        gameData['currentPlayerId'] ??
        gameData['hotPotatoCurrentPlayerId'] ??
        gameData['aoVCurrentPlayerId'] ??
        gameData['aoVChallengeAuthor'] ??
        gameData['bmcJudgeId'] ??
        gameData['bmcCzarId'] ??
        gameData['currentGuesserId'] ??
        gameData['justOneGuesserId'] ??
        gameData['tabooClueGiverId'] ??
        gameData['activeTeam'] ??
        gameData['subPhase'] ??
        0;
    final extra =
        '${gameData['currentStep']}_${gameData['currentPhase']}_${gameData['skullCurrentBid']}_${gameData['ramiHasDrawn']}_${gameData['petitsChevauxHasRolled']}_${gameData['yamsRollsLeft']}_${gameData['unoDrawActionDone']}_${gameData['tabooCurrentWord']}';
    return "${turnStartTimeStamp.millisecondsSinceEpoch}_${idx}_${gameData['roundState']}_${gameData['phase']}_${gameData['aoVPhase']}_${gameData['currentRound']}_$extra";
  }

  void _startPlayerTurnTimer(Map<String, dynamic> gameData) {
    final bool useTimer = gameData['useTimer'] ?? true;

    if (!useTimer || gameData['gameState'] != 'playing') {
      _playerTurnTimer?.cancel();
      return;
    }

    final turnStartTimeStamp =
        (gameData['turnStartTime'] ??
                gameData['roundStartTime'] ??
                gameData['petitBacRoundStartTime'] ??
                gameData['pictionaryStartTime'] ??
                gameData['hotPotatoRoundStartedAt'])
            as Timestamp?;
    if (turnStartTimeStamp == null) return;

    final String hostId = gameData['hostId'] ?? '';
    final String curPlayerId =
        FirebaseService.getCurrentPlayerId(gameData) ?? '';
    final bool isHost = hostId == widget.playerId;
    final bool isCurrentPlayer = curPlayerId == widget.playerId;

    // SÉCURITÉ CRITIQUE : Seul l'hôte ou le joueur actif déclenchent le timeout
    // pour éviter les doubles exécutions et les boucles infinies.
    if (!isHost && !isCurrentPlayer) {
      _playerTurnTimer?.cancel();
      return;
    }

    final String turnKey = _computeTurnKey(gameData, turnStartTimeStamp);

    if (_activeScheduledTurnKey == turnKey &&
        _playerTurnTimer != null &&
        _playerTurnTimer!.isActive) {
      return;
    }

    _activeScheduledTurnKey = turnKey;
    _playerTurnTimer?.cancel();

    final int turnDurationSec = FirebaseService.getEffectiveTurnTimer(gameData);
    final int elapsedMs =
        DateTime.now().difference(turnStartTimeStamp.toDate()).inMilliseconds;
    final int remainingMs = max(0, (turnDurationSec * 1000) - elapsedMs);

    _playerTurnTimer = Timer(Duration(milliseconds: remainingMs), () {
      if (!mounted) return;
      if (_lastExecutedTimeoutKey != turnKey) {
        _lastExecutedTimeoutKey = turnKey;
        _executeAutoPlayForGame(gameData);
      }
    });
  }

  void _executeAutoPlayForGame(Map<String, dynamic> gameData) {
    final String gameType = gameData['gameType'] ?? '';
    final String roundState = gameData['roundState'] ?? '';

    switch (gameType) {
      // --- JEUX DE CARTES ---
      case 'Big Two':
        _firebaseService.handleBigTwoTimeout(widget.gameCode);
        break;
      case 'Uno':
        _firebaseService.handleUnoTimeout(widget.gameCode);
        break;
      case 'Président':
      case 'Présidente':
        _firebaseService.handlePresidentTimeout(widget.gameCode);
        break;
      case 'Poker':
        _firebaseService.handlePokerTimeout(widget.gameCode);
        break;
      case 'Mille Bornes':
        _firebaseService.handleMilleBornesTimeout(widget.gameCode);
        break;
      case 'Zéro Pointé':
        _firebaseService.handleZeroPointeTimeout(widget.gameCode);
        break;
      case 'Rami':
        _firebaseService.handleRamiTimeout(widget.gameCode);
        break;
      case 'Belote':
        _firebaseService.handleBeloteTimeout(widget.gameCode);
        break;
      case 'Zombie!':
        _firebaseService.handleZombieTimeout(widget.gameCode);
        break;
      case 'Skull':
        _firebaseService.handleSkullTimeout(widget.gameCode);
        break;

      // --- JEUX DE PLATEAU & STRATÉGIE ---
      case 'Blokus':
        _firebaseService.handleBlokusTimeout(widget.gameCode);
        break;
      case 'Petits Chevaux':
        _firebaseService.handlePetitsChevauxTimeout(widget.gameCode);
        break;
      case 'Jeu de Dames':
        _firebaseService.handleCheckersTimeout(widget.gameCode);
        break;
      case 'Dominoes':
        _firebaseService.handleDominoesTimeout(widget.gameCode);
        break;
      case 'Bataille Navale':
        _firebaseService.handleBatailleNavaleTimeout(widget.gameCode);
        break;
      case 'Yams':
        _firebaseService.handleYamsTimeout(widget.gameCode);
        break;

      // --- JEUX D'AMBIANCE & ÉQUIPES ---
      case 'Petit Bac':
        _firebaseService.evaluatePetitBacAnswers(widget.gameCode);
        break;
      case 'Pictionary':
        _firebaseService.handlePictionaryTimeout(widget.gameCode, roundState);
        break;
      case 'Just One':
        _firebaseService.handleJustOneTimeout(widget.gameCode);
        break;
      case 'Codenames':
        _firebaseService.handleCodenamesTimeout(widget.gameCode);
        break;
      case "Time's Up":
        _firebaseService.handleTimesUpTimeout(widget.gameCode);
        break;
      case 'Taboo':
        _firebaseService.handleTabooTimeout(widget.gameCode);
        break;
      case 'Devine Tête':
        _firebaseService.handleDevineTeteTimeout(widget.gameCode);
        break;
      case 'Gribouillis':
        _firebaseService.handleGribouillisTimeout(widget.gameCode);
        break;
      case 'Cadavre Exquis':
        _firebaseService.handleCadavreExquisTimeout(widget.gameCode);
        break;
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        _firebaseService.handleHotPotatoTimeout(widget.gameCode);
        break;
      case 'Photo Roulette':
        _firebaseService.handlePhotoRouletteTimeout(widget.gameCode);
        break;
      case 'Action ou Vérité':
        _firebaseService.handleActionOuVeriteTimeout(widget.gameCode);
        break;
      case 'Blanc Manger Cocon':
      case 'Blanc Manger Coco':
      case 'BMC':
        _firebaseService.handleBMCTimeout(widget.gameCode);
        break;
      case 'Loup-Garou':
        _firebaseService.handleLoupGarouTimeout(widget.gameCode);
        break;

      default:
        if (['answering', 'declaring_truth'].contains(roundState)) {
          _firebaseService.handleSimultaneousInputTimeout(widget.gameCode);
        } else if (['voting', 'reveal_and_vote'].contains(roundState) ||
            gameData['currentPhase'] == 'voting') {
          _firebaseService.handleVotingTimeout(widget.gameCode);
        } else if (roundState == 'result' ||
            gameData['currentPhase'] == 'turn_result') {
          _firebaseService.handleHostActionTimeout(widget.gameCode);
        } else {
          _firebaseService.handleTurnTimeout(widget.gameCode);
        }
        break;
    }
  }

