          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                AppLocalizations.of(context)!.partieTerminee,
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.victoireDes,
                  [winnerFaction],
                ),
                style: Theme.of(
                  context,
                ).textTheme.headlineSmall?.copyWith(color: Colors.amber),
                textAlign: TextAlign.center,
              ),

              SizedBox(height: 30),
              if (isHost)
                ElevatedButton(
                  onPressed: () => _firebaseService.startGame(widget.gameCode),
                  child: Text(AppLocalizations.of(context)!.rejouer),
                ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildUndercoverTurnResultUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = gameData['playerData'];
    final eliminatedIds = List<String>.from(
      gameData['eliminatedThisTurn'] ?? [],
    );
    final bool isHost = gameData['hostId'] == playerId;

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          AppLocalizations.of(context)!.resultatDuVote,
          style: Theme.of(context).textTheme.headlineMedium,
        ),
        SizedBox(height: 20),
        if (eliminatedIds.isEmpty)
          Text(
            AppLocalizations.of(context)!.personneNAEteElimine,
            style: TextStyle(fontSize: 18, color: Colors.amber),
          )
        else
          ...eliminatedIds.map((pId) {
            final pName = playerData[pId]['name'];
            final pRole = playerData[pId]['role'];
            final List<dynamic> specialAbilities = List<dynamic>.from(
              playerData[pId]['specialAbilities'] ?? [],
            );
            final String roleDisplay =
                specialAbilities.isNotEmpty
                    ? "$pRole (${specialAbilities.join(', ')})"
                    : pRole;
            return Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.aEteElimineSonRole,
                [pName, roleDisplay],
              ),
              style: TextStyle(fontSize: 18, color: Colors.amber),
              textAlign: TextAlign.center,
            );
          }),
        SizedBox(height: 30),
        if (isHost)
          ElevatedButton(
            onPressed:
                () => _firebaseService.processEliminationsAndCheckWin(
                  widget.gameCode,
                ),
            child: Text(AppLocalizations.of(context)!.continuer),
          )
        else
          Center(child: Text(AppLocalizations.of(context)!.enAttenteDeLHote1)),
      ],
    );
  }

  Widget _buildUndercoverAvengerUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = gameData['playerData'];
    String? avengerId;
    playerData.forEach((pId, data) {
      final abilities = (data['specialAbilities'] as List?);
      if (abilities != null &&
          (abilities.contains('Vengeuse') ||
              abilities.contains(AppLocalizations.of(context)!.vengeuse))) {
        avengerId = pId;
      }
    });

    if (playerId != avengerId) {
      return Center(
        child: Text(
          AppLocalizations.of(context)!.laVengeuseChoisitSaCible,
          textAlign: TextAlign.center,
        ),
      );
    }

    List<String> activePlayers =
        playerData.entries
            .where((e) => e.value['status'] == 'active')
            .map((e) => e.key)
            .toList();

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          AppLocalizations.of(context)!.vengeance,
          style: Theme.of(context).textTheme.headlineMedium,
        ),
        Text(
          AppLocalizations.of(context)!.tuAsEteElimineE,
          style: Theme.of(context).textTheme.titleLarge,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        ...activePlayers.map(
          (pId) => ElevatedButton(
            onPressed:
                () => _firebaseService.undercoverAvengerDecision(
                  widget.gameCode,
                  avengerId!,
                  pId,
                ),
            child: Text(
              AppLocalizations.of(
                context,
              )!.undercoverEliminatePlayer("${playerData[pId]['name']}"),
            ),
          ),
        ),
      ],
    );
  }

