  Widget _buildUndercoverClueGivingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final playerOrder = List<String>.from(gameData['playerOrder']);
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length) {
      return Center(child: CircularProgressIndicator());
    }

    final String currentPlayerId = playerOrder[currentPlayerIndex];
    final String currentPlayerName =
        playerData[currentPlayerId]?['name'] ?? '...';
    final bool isMyTurn = playerId == currentPlayerId;
    final bool hasAlreadySubmitted =
        (gameData['playerClues'] as Map?)?.containsKey(playerId) ?? false;

    return Column(
      children: [
        SizedBox(height: 10),
        Text(
          isMyTurn
              ? AppLocalizations.of(context)!.cEstAToiDe1
              : GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.auTourDe,
                [currentPlayerName],
              ),
          style: Theme.of(context).textTheme.headlineSmall,
          textAlign: TextAlign.center,
        ),
        if (!isMyTurn) ...[SizedBox(height: 10), CircularProgressIndicator()],
        SizedBox(height: 12),
        _buildUndercoverPlayerLine(context, gameData, playerId),
        SizedBox(height: 12),
        if (isMyTurn && !hasAlreadySubmitted) ...[
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16.0),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _answerController,
                    autofocus: true,
                    decoration: InputDecoration(
                      labelText: AppLocalizations.of(context)!.tonIndiceUnMot,
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                      filled: true,
                      fillColor: Colors.grey[850],
                    ),
                    onSubmitted: (v) {
                      final clue = v.trim();
                      if (clue.isNotEmpty && !_isActionPending) {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .submitUndercoverClue(
                              widget.gameCode,
                              playerId,
                              clue,
                            )
                            .whenComplete(() {
                              if (mounted) {
                                _answerController.clear();
                                setState(() => _isActionPending = false);
                              }
                            });
                      }
                    },
                  ),
                ),
                SizedBox(width: 8),
                ElevatedButton(
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            final clue = _answerController.text.trim();
                            if (clue.isNotEmpty) {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .submitUndercoverClue(
                                    widget.gameCode,
                                    playerId,
                                    clue,
                                  )
                                  .whenComplete(() {
                                    if (mounted) {
                                      _answerController.clear();
                                      setState(() => _isActionPending = false);
                                    }
                                  });
                            }
                          },
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.deepPurpleAccent,
                  ),
                  child:
                      _isActionPending
                          ? SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              color: Colors.white,
                            ),
                          )
                          : Text(AppLocalizations.of(context)!.valider),
                ),
              ],
            ),
          ),
          SizedBox(height: 8),
        ] else if (isMyTurn && hasAlreadySubmitted) ...[
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              AppLocalizations.of(context)!.indiceEnvoyeEnAttenteDes,
              style: TextStyle(
                color: Colors.greenAccent,
                fontStyle: FontStyle.italic,
              ),
              textAlign: TextAlign.center,
            ),
          ),
        ],
        Expanded(child: _buildChatInterface(gameData, playerId)),
      ],
    );
  }

  Widget _buildUndercoverDiscussionVotingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final myData = playerData[playerId];
    final bool canIVote = myData['canVote'] ?? false;
    final bool hasVoted = gameData['votes']?[playerId] != null;
    final String currentPhase = gameData['currentPhase'];
    final bool isHost = gameData['hostId'] == playerId;

    return Column(
      children: [
        if (currentPhase == 'discussion') ...[
          StreamBuilder<DatabaseEvent>(
            stream: _firebaseService.getUndercoverLiveStream(widget.gameCode),
            builder: (context, snap) {
              Map<String, String> suspects = {};
              if (snap.hasData && snap.data!.snapshot.value != null) {
                try {
                  final raw = Map<String, dynamic>.from(
                    snap.data!.snapshot.value as Map,
                  );
                  raw.forEach((sId, data) {
                    if (data is Map && data['suspectId'] != null) {
                      suspects[sId] = data['suspectId'].toString();
                    }
                  });
                } catch (_) {}
              }

              if (suspects.isEmpty) {
                return Text(
                  AppLocalizations.of(context)!.phaseDeDiscussion,
                  style: Theme.of(context).textTheme.headlineSmall,
                );
              }

              return Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    AppLocalizations.of(context)!.phaseDeDiscussion,
                    style: Theme.of(context).textTheme.headlineSmall,
                  ),
                  SizedBox(height: 4),
                  Wrap(
                    spacing: 6,
                    children:
                        suspects.entries.map((entry) {
                          final accuserName =
                              playerData[entry.key]?['name'] ??
                              AppLocalizations.of(context)!.joueur;
                          final targetName =
                              playerData[entry.value]?['name'] ??
                              AppLocalizations.of(context)!.suspect;
                          return Container(
                            padding: EdgeInsets.symmetric(
                              horizontal: 8,
                              vertical: 2,
                            ),
                            decoration: BoxDecoration(
                              color: Colors.amber.withOpacity(0.2),
                              borderRadius: BorderRadius.circular(10),
                              border: Border.all(
                                color: Colors.amberAccent.withOpacity(0.5),
                              ),
                            ),
                            child: Text(
                              GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.soupconne,
                                [accuserName, targetName],
                              ),
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontSize: 11,
                              ),
                            ),
                          );
                        }).toList(),
                  ),
                ],
              );
            },
          ),
          SizedBox(height: 10),
          if (isHost)
            ElevatedButton(
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .startUndercoverVoting(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
              child: Text(AppLocalizations.of(context)!.lancerLeVote),
            )
          else
            Text(AppLocalizations.of(context)!.debattezLHoteLanceraLe),
        ] else if (currentPhase == 'voting') ...[
          Text(
            AppLocalizations.of(context)!.aQuiLaSentence,
            style: Theme.of(context).textTheme.headlineSmall,
          ),
          if (hasVoted)
            Text(
              AppLocalizations.of(context)!.voteEnregistreEnAttente,
              style: TextStyle(color: Colors.greenAccent),
            )
          else if (!canIVote)
            Text(
              AppLocalizations.of(context)!.vousNePouvezPasVoter,
              style: TextStyle(color: Colors.redAccent),
            )
          else
            Text(
              AppLocalizations.of(context)!.appuieSurLaBulleD,
              style: TextStyle(color: Colors.amberAccent),
            ),
        ],
        SizedBox(height: 20),
        _buildUndercoverPlayerLine(
          context,
          gameData,
          playerId,
        ), // La ligne des joueurs
        SizedBox(height: 20),
        Expanded(child: _buildChatInterface(gameData, playerId)), // Le chat
      ],
    );
  }

  Widget _buildUndercoverPlayerLine(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final playerOrder = List<String>.from(gameData['playerOrder']);
    final clues = Map<String, dynamic>.from(gameData['playerClues'] ?? {});
    final currentPhase = gameData['currentPhase'];
    final isVotingPhase =
        currentPhase == 'voting' || currentPhase == 'resolving_votes';
    final myData = playerData[playerId];
    final canIVote = myData['canVote'] ?? false;
    final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});

    Map<String, List<String>> votesReceived = {};
    votes.forEach((voterId, targetId) {
      if (!votesReceived.containsKey(targetId)) {
        votesReceived[targetId] = [];
      }
      votesReceived[targetId]!.add(
        playerData[voterId]?['name'] ?? AppLocalizations.of(context)!.anonyme,
      );
    });

    final Map<String, IconData> roleIcons = {
      AppLocalizations.of(context)!.boomerang: Icons.autorenew,
      AppLocalizations.of(context)!.vengeuse: Icons.whatshot,
      AppLocalizations.of(context)!.deesseDeLaJustice: Icons.gavel,
      AppLocalizations.of(context)!.fantome: Icons.visibility,
      AppLocalizations.of(context)!.amoureux: Icons.favorite,
      AppLocalizations.of(context)!.mrMeme: Icons.gesture,
      AppLocalizations.of(context)!.vendeurDeFalafels: Icons.fastfood,
      AppLocalizations.of(context)!.duellistes: Icons.compare_arrows,
    };

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      padding: const EdgeInsets.symmetric(horizontal: 16.0),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children:
            playerOrder.map((pId) {
              final pData = playerData[pId];
              final isDead = pData['status'] == 'eliminated';
              final clue = clues[pId];
              final bool canBeVotedFor =
                  isVotingPhase && canIVote && pId != playerId && !isDead;
              final List<String> voters = votesReceived[pId] ?? [];

              return Padding(
                padding: const EdgeInsets.symmetric(horizontal: 12.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    GestureDetector(
                      onTap:
                          canBeVotedFor && !_isActionPending
                              ? () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitUndercoverVote(
                                      widget.gameCode,
                                      playerId,
                                      pId,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              }
                              : null,
                      child: Opacity(
                        opacity: clue != null ? 1.0 : 0.0,
                        child: Container(
                          constraints: BoxConstraints(
                            minHeight: 40,
                            maxWidth: 100,
                          ),
                          padding: EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color:
                                canBeVotedFor
                                    ? Colors.deepPurple
                                    : Colors.grey[800],
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: Text(
                            clue ?? "",
                            textAlign: TextAlign.center,
                            style: TextStyle(color: Colors.white),
                          ),
                        ),
                      ),
                    ),
                    SizedBox(height: 8),

                    Stack(
                      alignment: Alignment.center,
                      clipBehavior: Clip.none,
                      children: [
                        CircleAvatar(
                          radius: 30,
                          child: Text(
                            (pData['name'] as String?)?.substring(0, 1) ?? "?",
                            style: TextStyle(fontSize: 24),
                          ),
                        ),
                        if (isDead)
                          Positioned.fill(
                            child: Icon(
                              Icons.close,
                              color: Colors.red.withOpacity(0.8),
                              size: 70,
                            ),
                          ),
                      ],
                    ),
                    SizedBox(height: 4),

                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          pData['name'],
                          style: TextStyle(
                            color: isDead ? Colors.grey : Colors.white,
                          ),
                        ),
                        ...(pData['revealedAbilities'] as List<dynamic>? ?? [])
                            .map((ability) {
                              if (roleIcons.containsKey(ability)) {
                                return Padding(
                                  padding: const EdgeInsets.only(left: 4.0),
                                  child: Icon(
                                    roleIcons[ability],
                                    size: 16,
                                    color: Colors.cyanAccent,
                                  ),
                                );
                              }
                              return SizedBox.shrink();
                            })
                            .toList(),
                      ],
                    ),

                    if (isVotingPhase && voters.isNotEmpty)
                      Padding(
                        padding: const EdgeInsets.only(top: 4.0),
                        child: Column(
                          children: [
                            Chip(
                              label: Text(
                                AppLocalizations.of(
                                  context,
                                )!.undercoverVoteCount('${voters.length}'),
                                style: TextStyle(fontSize: 10),
                              ),
                              padding: EdgeInsets.zero,
                              visualDensity: VisualDensity.compact,
                            ),
                            Text(
                              voters.join(', '),
                              style: TextStyle(
                                fontSize: 9,
                                color: Colors.grey[400],
                              ),
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ],
                        ),
                      ),
                  ],
                ),
              );
            }).toList(),
      ),
    );
  }

  Future<void> _pickAndUploadPhotos(
    String playerId,
    Map<String, dynamic> gameData,
  ) async {
    if (!mounted) return;
    setState(() => _isUploading = true);

    try {
      final PermissionState ps = await PhotoManager.requestPermissionExtend();
      if (ps != PermissionState.authorized && ps != PermissionState.limited) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                AppLocalizations.of(
                  context,
                )!.permissionRefuseeImpossibleDAcceder,
              ),
            ),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      final int photosToPick =
          gameData['photoRouletteSettings']?['photosPerPlayer'] ?? 20;
      final String mediaType =
          gameData['photoRouletteSettings']?['mediaType'] ??
          AppLocalizations.of(context)!.photos;

      RequestType requestType = RequestType.image;
      if (mediaType == AppLocalizations.of(context)!.videos)
        requestType = RequestType.video;
      if (mediaType == AppLocalizations.of(context)!.mixte)
        requestType = RequestType.common;

      List<AssetPathEntity> albums = await PhotoManager.getAssetPathList(
        type: requestType,
        onlyAll: true,
      );

      if (albums.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                AppLocalizations.of(context)!.aucunAlbumMediaTrouve,
              ),
            ),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      List<AssetEntity> allPhotos = await albums[0].getAssetListRange(
        start: 0,
        end: 300,
      );

      if (allPhotos.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(AppLocalizations.of(context)!.votreGalerieEstVide),
            ),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      allPhotos.shuffle();
      List<AssetEntity> selectedAssets = allPhotos.take(photosToPick).toList();
      List<String> uploadedUrls = [];

      for (final asset in selectedAssets) {
        // Optimisation : thumbnail haute qualité (1080x1080) au lieu de l'image brute 4K
        final Uint8List? bytes = await asset.thumbnailDataWithSize(
          ThumbnailSize(1080, 1080),
          quality: 85,
        );

        if (bytes != null) {
          final url = await _supabaseService.uploadImageBytes(
            bytes,
            widget.gameCode,
          );
          if (url != null) uploadedUrls.add(url);
        }
      }

      if (uploadedUrls.length >= 3) {
        await _firebaseService.playerReadyForPhotoRoulette(
          widget.gameCode,
          playerId,
          uploadedUrls,
        );
      } else {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                uploadedUrls.isEmpty
                    ? AppLocalizations.of(context)!.echecDeLUploadDes
                    : AppLocalizations.of(context)!.ilFautAuMoins3,
              ),
            ),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              AppLocalizations.of(
                context,
              )!.erreurLorsDeLaSelection.replaceAll("{0}", e.toString()),
            ),
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _isUploading = false);
    }
  }

  void _startPhotoRouletteTimer(
    DateTime startTime,
    int durationSeconds,
    String gameCode,
    String currentRoundState,
  ) {
    _timerSubscription?.cancel();
    _timerSubscription = Stream.periodic(
      Duration(seconds: 1),
      (count) => count,
    ).listen((_) {
      if (!mounted) {
        _timerSubscription?.cancel();
        return;
      }
      final now = DateTime.now();
      final elapsed = now.difference(startTime).inSeconds;
      final remaining = durationSeconds - elapsed;

      if (remaining <= 0) {
        _timerSubscription?.cancel();

        // --- CORRECTION ---
        // ANCIEN : final String playerId = Provider.of<String>(context, listen: false);
        // NOUVEAU :
        final String playerId = widget.playerId;
        // ------------------

        final gameData =
            Provider.of<DocumentSnapshot>(context, listen: false).data()
                as Map<String, dynamic>;
        if (gameData['hostId'] == playerId &&
            currentRoundState == 'showing_photo') {
          _firebaseService.handlePhotoRouletteTimeout(gameCode);
        }
      }
    });
  }

  Widget _buildPhotoRouletteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'];
    final Map<String, dynamic> players = Map.from(gameData['players']);
    final bool isHost = gameData['hostId'] == playerId;

    switch (roundState) {
      case 'photo_selection':
        final Map<String, dynamic> readyPlayers = Map.from(
          gameData['readyPlayers'] ?? {},
        );
        final bool amIReady = readyPlayers[playerId] ?? false;

        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              AppLocalizations.of(context)!.preparationDeLaPartie,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 20),
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.lApplicationVaSelectionnerPhotos,
                [gameData['photoRouletteSettings']?['photosPerPlayer'] ?? 20],
              ),
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 20),
            if (amIReady)
              Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  children: [
                    Icon(Icons.check_circle, color: Colors.green, size: 50),
                    Text(
                      AppLocalizations.of(context)!.vousEtesPret,
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                    Text(
                      AppLocalizations.of(context)!.enAttenteDesAutresJoueurs,
                    ),
                  ],
                ),
              )
            else if (_isUploading)
              CircularProgressIndicator()
            else
              ElevatedButton.icon(
                icon: Icon(Icons.sync),
                label: Text(
                  AppLocalizations.of(context)!.autoriserEtLancerLaSelection,
                ),
                onPressed: () => _pickAndUploadPhotos(playerId, gameData),
              ),
            SizedBox(height: 30),
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.joueursPrets,
                [readyPlayers.length, players.length],
              ),
              style: Theme.of(context).textTheme.bodyLarge,
            ),
            ...players.keys.map((pId) {
              return ListTile(
                title: Text(players[pId]['name'] ?? '...'),
                trailing: Icon(
                  (readyPlayers[pId] ?? false)
                      ? Icons.check_circle
                      : Icons.hourglass_empty,
                  color:
                      (readyPlayers[pId] ?? false) ? Colors.green : Colors.grey,
                ),
              );
            }).toList(),
          ],
        );

      case 'showing_photo':
        final photoUrl = gameData['currentPhoto']?['url'];
        final startTime = (gameData['roundStartTime'] as Timestamp?)?.toDate();
        final duration = gameData['turnTimerSeconds'] ?? 5;
        final Map<String, dynamic> votes = Map.from(gameData['votes'] ?? {});
        final bool hasVoted = votes.containsKey(playerId);

        if (photoUrl == null || startTime == null)
          return Center(
            child: Text(AppLocalizations.of(context)!.chargementDeLaPhoto),
          );

        if (isHost) {
          _startPhotoRouletteTimer(
            startTime,
            duration,
            widget.gameCode,
            roundState,
          );
        }

        return Column(
          children: [
            Text(
              AppLocalizations.of(context)!.aQuiEstCettePhoto,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 10),
            StreamBuilder(
              stream: Stream.periodic(Duration(milliseconds: 100)),
              builder: (context, snapshot) {
                int elapsed = DateTime.now().difference(startTime).inSeconds;
                int remaining = duration - elapsed;
                return LinearProgressIndicator(
                  value: (remaining > 0 ? remaining : 0) / duration,
                );
              },
            ),
            Expanded(
              flex: 3,
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 8.0),
                child: Image.network(
                  photoUrl,
                  fit: BoxFit.contain,
                  loadingBuilder: (context, child, progress) {
                    return progress == null
                        ? child
                        : Center(child: CircularProgressIndicator());
                  },
                ),
              ),
            ),
            SizedBox(height: 10),
            Expanded(
              flex: 2,
              child:
                  hasVoted
                      ? _buildWaitingWidget(
                        AppLocalizations.of(context)!.vousAvezVote,
                        players,
                        0,
                        0,
                      )
                      : GridView.builder(
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          childAspectRatio: 3.5,
                          mainAxisSpacing: 8,
                          crossAxisSpacing: 8,
                        ),
                        itemCount: players.length,
                        itemBuilder: (context, index) {
                          String pId = players.keys.elementAt(index);
                          String pName = players[pId]?['name'] ?? '...';
                          return ElevatedButton(
                            onPressed:
                                _isActionPending
                                    ? null
                                    : () {
                                      setState(() => _isActionPending = true);
                                      _firebaseService
                                          .submitPhotoRouletteVote(
                                            widget.gameCode,
                                            playerId,
                                            pId,
                                          )
                                          .whenComplete(() {
                                            if (mounted)
                                              setState(
                                                () => _isActionPending = false,
                                              );
                                          });
                                    },
                            child: Text(pName, textAlign: TextAlign.center),
                          );
                        },
                      ),
            ),
          ],
        );

      case 'results':
        final Map<String, dynamic> roundResults = Map.from(
          gameData['roundResults'] ?? {},
        );
        final String correctOwnerId = gameData['currentPhoto']['ownerId'];
        final String correctOwnerName =
            players[correctOwnerId]?['name'] ??
            AppLocalizations.of(context)!.inconnu;
        final String photoUrl = gameData['currentPhoto']['url'];
        final startTime =
            (gameData['roundResultsTimestamp'] as Timestamp?)?.toDate();

        if (startTime == null)
          return Center(
            child: Text(AppLocalizations.of(context)!.calculDesResultats),
          );

        if (isHost) {
          _startPhotoRouletteTimer(
            startTime,
            5,
            widget.gameCode,
            roundState,
          ); // 5s pour voir les résultats
        }

        return Column(
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.laPhotoEtaitA,
                [correctOwnerName],
              ),
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            StreamBuilder(
              stream: Stream.periodic(Duration(milliseconds: 100)),
              builder: (context, snapshot) {
                int elapsed = DateTime.now().difference(startTime).inSeconds;
                int remaining = 5 - elapsed;
                if (remaining <= 0 && isHost && !_isActionPending) {
                  _isActionPending = true;
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _firebaseService
                        .startNextPhotoRouletteRound(widget.gameCode)
                        .whenComplete(() {
                          if (mounted) setState(() => _isActionPending = false);
                        });
                  });
                }
                return LinearProgressIndicator(
                  value: (remaining > 0 ? remaining : 0) / 5.0,
                );
              },
            ),
            Expanded(
              flex: 2,
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 8.0),
                child: Image.network(photoUrl, fit: BoxFit.contain),
              ),
            ),
            Expanded(
              flex: 3,
              child: ListView(
                children:
                    players.keys.map((pId) {
                      final pName = players[pId]?['name'] ?? '...';
                      final resultData =
                          roundResults[pId] as Map<String, dynamic>?;
                      final bool wasCorrect = resultData?['correct'] ?? false;
                      final int scoreGained = resultData?['score'] ?? 0;

                      return ListTile(
                        title: Text(pName),
                        trailing: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            if (wasCorrect)
                              Text(
                                GameContentLocalization.format(
                                  context,
                                  AppLocalizations.of(context)!.pts,
                                  [scoreGained],
                                ),
                                style: TextStyle(
                                  color: Colors.greenAccent,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            SizedBox(width: 8),
                            Icon(
                              wasCorrect ? Icons.check : Icons.close,
                              color: wasCorrect ? Colors.green : Colors.red,
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
            ),
          ],
        );

      case 'gameOver':
        List<MapEntry<String, dynamic>> sortedPlayers =
            players.entries.toList()..sort(
              (a, b) =>
                  (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
            );
        String winnerName =
            sortedPlayers.isNotEmpty
                ? sortedPlayers.first.value['name']
                : AppLocalizations.of(context)!.personne;

        return Center(
          child: Card(
            child: Padding(
              padding: const EdgeInsets.all(24.0),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    AppLocalizations.of(context)!.partieTerminee,
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  SizedBox(height: 10),
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.leGagnantEst,
                      [winnerName],
                    ),
                    style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                      color: Colors.amberAccent,
                    ),
                  ),
                  SizedBox(height: 20),
                  Text(
                    AppLocalizations.of(context)!.classementFinal,
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  ...sortedPlayers.asMap().entries.map((entry) {
                    int rank = entry.key + 1;
                    String name = entry.value.value['name'];
                    int score = entry.value.value['score'];
                    return Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.points,
                        [rank, name, score],
                      ),
                    );
                  }),
                  SizedBox(height: 20),
                  ElevatedButton(
                    onPressed: _safePopToFirst,
                    child: Text(AppLocalizations.of(context)!.retourALAccueil),
                  ),
                ],
              ),
            ),
          ),
        );

      default:
        return _buildWaitingWidget(
          AppLocalizations.of(context)!.chargementDeLaPartie,
          players,
          0,
          0,
        );
    }
  }

  void _startTimer(
    DateTime startTime,
    int durationSeconds,
    String gameCode,
    String currentRoundState,
    Map<String, dynamic> gameData,
  ) {
    final bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer) {
      _timerSubscription?.cancel();
      return;
    }
    _timerSubscription?.cancel();
    _timerSubscription = Stream.periodic(
      Duration(seconds: 1),
      (count) => count,
    ).listen((_) {
      if (!mounted) {
        _timerSubscription?.cancel();
        return;
      }

      final now = DateTime.now();
      final elapsed = now.difference(startTime).inSeconds;
      final remaining = durationSeconds - elapsed;

      if (remaining <= 0) {
        _timerSubscription?.cancel();

        String gameType = gameData['gameType'];
        // Vérification pour éviter les appels multiples si l'hôte a déjà déclenché
        final String playerId = widget.playerId;
        final bool isHost = gameData['hostId'] == playerId;

        if (isHost) {
          if (gameType == 'Petit Bac' &&
              !(gameData['petitBacRoundEnded'] ?? false)) {
            _firebaseService.evaluatePetitBacAnswers(gameCode);
          } else if (gameType == 'Pictionary') {
            _firebaseService.handlePictionaryTimeout(
              gameCode,
              currentRoundState,
            );
          } else if (gameType == 'La Patate Chaude' ||
              gameType == 'Le Jeu des Catégories') {
            _firebaseService.handleHotPotatoTimeout(gameCode);
          }
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final String playerId = widget.playerId;

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, result) async {
        if (didPop) return;
        await _confirmAndExitGame();
      },
      child: StreamBuilder<DocumentSnapshot>(
        stream: _firebaseService.getGameStream(widget.gameCode),
        builder: (context, snapshot) {
          if (!snapshot.hasData) {
            return Scaffold(body: Center(child: CircularProgressIndicator()));
          }
          if (snapshot.hasError) {
            return Scaffold(
              body: Center(
                child: Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.erreur,
                    [snapshot.error],
                  ),
                ),
              ),
            );
          }
          if (!snapshot.data!.exists) {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) _exitGame();
            });
            return Scaffold(
              body: Center(
                child: Text(AppLocalizations.of(context)!.laPartieAEteTerminee),
              ),
            );
          }
          final gameData = snapshot.data!.data() as Map<String, dynamic>;

          if (gameData['gameState'] == 'lobby') {
            return Scaffold(
              body: Center(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    CircularProgressIndicator(),
                    SizedBox(height: 16),
                    Text(
                      AppLocalizations.of(context)!.laPartieCommence,
                      style: TextStyle(fontSize: 16, color: Colors.white70),
                    ),
                  ],
                ),
              ),
            );
          }

          if (gameData['gameState'] == 'gameOver') {
            if (!_xpAwarded) {
              _xpAwarded = true;
              WidgetsBinding.instance.addPostFrameCallback((_) async {
                final ps = Provider.of<PlayerState>(context, listen: false);

                // Récupération du mode classé et du niveau max des adversaires
                final bool isRanked = gameData['isRanked'] == true;
                final String myId = widget.playerId;
                final playersMap = Map<String, dynamic>.from(
                  gameData['players'] ?? {},
                );
                final myData = playersMap[myId] as Map<String, dynamic>?;
                final bool isBotOrExcluded =
                    myData?['isBot'] == true ||
                    myData?['replacedByBot'] == true ||
                    (gameData['botPlayers'] as Map<String, dynamic>?)?[myId] ==
                        true;

                // Si le joueur a été exclu et remplacé par l'ordinateur : aucun gain
                if (isBotOrExcluded) {
                  return;
                }

                final String? winnerId = gameData['gameWinner'];
                final bool isWin = (winnerId == myId);
                final String currentGame =
                    gameData['gameType'] ??
                    AppLocalizations.of(context)!.inconnu;

                // Calcul personnalisé de l'XP en fonction des actions spécifiques au jeu
                final xpCalc = GameXpHelper.calculateXp(
                  gameName: currentGame,
                  isWin: isWin,
                  playerId: myId,
                  gameData: gameData,
                  isPremium: ps.isPremium,
                );
                final int xpEarned = xpCalc.totalXp;

                // Enregistrement des stats par jeu
                await ps.recordGameResult(
                  gameName: currentGame,
                  isWin: isWin,
                  xpEarned: xpEarned,
                );

                // Calcul du niveau adverse maximum
                int maxOpponentLvl = 1;
                playersMap.forEach((pId, pData) {
                  if (pId != myId && pData is Map) {
                    int oppLvl = (pData['level'] as num?)?.toInt() ?? 1;
                    if (oppLvl > maxOpponentLvl) maxOpponentLvl = oppLvl;
                  }
                });

                // Attribution avec multiplicateurs Ranked, Giant Slayer et Win Streaks
                int finalAwardedXp = xpEarned;
                if (isRanked) {
                  finalAwardedXp = await ps.handleRankedGameEnd(
                    isWin: isWin,
                    maxOpponentLevel: maxOpponentLvl,
                    baseGameXp: xpEarned,
                  );
                } else {
                  finalAwardedXp = await ps.addXp(xpEarned);
                  await ps.claimGameReward(widget.gameCode);
                }

                // Déclenchement de l'animation visuelle de gain d'XP
                _triggerXpAnimation(finalAwardedXp);

                // NOUVEAU : Envoyer les résultats au salon si rattaché (fiabilisé : premier client qui détecte la fin)
                if (gameData['loungeId'] != null &&
                    !(gameData['loungeResultPosted'] ?? false)) {
                  await FirebaseFirestore.instance
                      .collection('games')
                      .doc(widget.gameCode)
                      .update({'loungeResultPosted': true});
                  String winnerName =
                      gameData['players']?[gameData['gameWinner']]?['name'] ??
                      AppLocalizations.of(context)!.inconnu;
                  String reason = gameData['gameEndReason'] ?? '';
                  await _firebaseService.sendLoungeMessage(
                    gameData['loungeId'],
                    widget.playerId,
                    AppLocalizations.of(context)!.systeme,
                    AppLocalizations.of(context)!.laPartieEstTerminee,
                    type: 'game_result',
                    extraData: {
                      'gameName': gameData['gameType'],
                      'winnerName': winnerName,
                      'reason': reason,
                      'oldGameCode': widget.gameCode,
                    },
                  );
                  await FirebaseFirestore.instance
                      .collection('lounges')
                      .doc(gameData['loungeId'])
                      .update({
                        'pendingGame': FieldValue.delete(),
                        'lastGameResult': {
                          'gameName': gameData['gameType'],
                          'winnerName': winnerName,
                          'reason': reason,
                          'timestamp': FieldValue.serverTimestamp(),
                        },
                      });
                }
              });
            }
          }

          _startPlayerTurnTimer(gameData);

          return Provider<DocumentSnapshot>.value(
            value: snapshot.data!,
            child: Builder(
              builder: (context) {
                final gameData = snapshot.data!.data() as Map<String, dynamic>;
                final players =
                    (gameData['players'] as Map<String, dynamic>?) ?? {};

                // ⚡ DÉTECTION DU GAIN D'XP EN TEMPS RÉEL
                final int currentXp =
                    (players[widget.playerId]?['xp'] as num?)?.toInt() ?? 0;
                if (_lastKnownPlayerXp == null) {
                  _lastKnownPlayerXp = currentXp;
                } else if (currentXp > _lastKnownPlayerXp!) {
                  final int gained = currentXp - _lastKnownPlayerXp!;
                  _lastKnownPlayerXp = currentXp;
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _triggerXpAnimation(gained);
                  });
                }
                final int currentRound = gameData['currentRound'] ?? 0;

                final int currentPlayerIndex =
                    gameData['currentPlayerIndex'] ?? -1;

                if (currentRound > _lastProcessedRound) {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _answerController.clear();
                    if (mounted)
                      setState(() {
                        _pictionaryStrokeCount = 0;
                        _straightLinePoints = [];
                        _straightLineStart = null;
                        _straightLineCurrentEnd = null;
                      });
                  });
                  _lastProcessedRound = currentRound;
                }

                // Gestion des timers spécifiques (inchangé)
                if (gameData['petitBacRoundStartTime'] != null &&
                    !(gameData['petitBacRoundEnded'] ?? false)) {
                  final Timestamp roundStartTimeStamp =
                      gameData['petitBacRoundStartTime'];
                  final String timerKey =
                      '${roundStartTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      roundStartTimeStamp.toDate(),
                      gameData['turnTimerSeconds'] ?? 120,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else if (gameData['pictionaryStartTime'] != null &&
                    gameData['roundState'] != 'result') {
                  final Timestamp startTimeStamp =
                      gameData['pictionaryStartTime'];
                  final int duration =
                      (gameData['roundState'] == 'drawing')
                          ? (gameData['turnTimerSeconds'] ?? 90)
                          : (gameData['resultTimerSeconds'] ?? 30);
                  final String timerKey =
                      '${startTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      startTimeStamp.toDate(),
                      duration,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else if (gameData['hotPotatoRoundStartedAt'] != null &&
                    gameData['roundState'] == 'playing') {
                  final Timestamp startTimeStamp =
                      gameData['hotPotatoRoundStartedAt'];
                  int duration = gameData['turnTimerSeconds'] ?? 30;
                  final String timerKey =
                      '${startTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      startTimeStamp.toDate(),
                      duration,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else {
                  if (_lastTimerKey != null) {
                    _lastTimerKey = null;
                    _timerSubscription?.cancel();
                  }
                }

                _unoDrawActionDone = gameData['unoDrawActionDone'] ?? false;

                // Récupérer les UIDs Agora de tous les joueurs
                _playerLivekitIdentities = {};
                players.forEach((pId, pData) {
                  if (pData['livekitIdentity'] != null) {
                    _playerLivekitIdentities[pId] = pData['livekitIdentity'];
                  }
                });

                // Déterminer les paramètres spécifiques pour Time's Up
                bool isTimeUpMime = false;
                String? timeUpActiveTeam;
                String? activePlayerId;

                String? activeTeamForVideo;
                String? activePlayerForVideo;

                if (gameData['gameType'] == "Devine Tête" &&
                    gameData['devineTeteUseTeams'] == true) {
                  activeTeamForVideo = gameData['activeTeam'];
                  activePlayerForVideo = gameData['currentGuesserId'];
                } else if (gameData['gameType'] == "Time's Up") {
                  int currentRoundNumber = gameData['currentRoundNumber'] ?? 1;
                  isTimeUpMime = currentRoundNumber == 3; // Mode Mime

                  // Trouver l'équipe active
                  String currentGuesserId = gameData['currentGuesserId'] ?? '';
                  List<String> redTeam = List<String>.from(
                    gameData['redTeam'] ?? [],
                  );
                  List<String> blueTeam = List<String>.from(
                    gameData['blueTeam'] ?? [],
                  );

                  if (redTeam.contains(currentGuesserId)) {
                    timeUpActiveTeam = 'red';
                  } else if (blueTeam.contains(currentGuesserId)) {
                    timeUpActiveTeam = 'blue';
                  }
                  activePlayerId = currentGuesserId;

                  activeTeamForVideo = timeUpActiveTeam;
                  activePlayerForVideo = activePlayerId;
                }

                // Connexion LiveKit si vidéo ou audio activé dans les options de la partie
                if (!_livekitInitialized &&
                    (gameData['videoEnabled'] == true ||
                        gameData['audioEnabled'] == true)) {
                  _connectToLivekit(
                    gameData['videoEnabled'] == true,
                    gameData['audioEnabled'] == true,
                  );
                }

                final String currentGameType = gameData['gameType'] ?? '';
                // Le tchat flottant est actif par défaut sur TOUS les jeux sauf Loup-Garou et Infiltré (qui ont leur tchat d'équipe intégré)
                final bool isIntegratedChatGame = [
                  'Loup-Garou',
                  'Infiltré & Mr. White',
                ].contains(currentGameType);
                final bool showFloatingChat =
                    (gameData['enableFloatingChat'] ?? true) &&
                    !isIntegratedChatGame;

                bool isDevineTete = currentGameType == 'Devine Tête';
                bool isActionOuVerite = currentGameType == 'Action ou Vérité';
                bool isDevineTeteGuesser =
                    isDevineTete &&
                    gameData['currentGuesserId'] == widget.playerId;

                Widget scaffold = Scaffold(
                  appBar: AppBar(
                    leading: IconButton(
                      icon: Icon(Icons.arrow_back),
                      tooltip: AppLocalizations.of(context)!.quitterLaPartie1,
                      onPressed: _confirmAndExitGame,
                    ),
                    title: Text(
                      currentGameType.isNotEmpty
                          ? currentGameType
                          : AppLocalizations.of(context)!.jeuEnCours,
                    ),
                    actions: [
                      IconButton(
                        icon: Icon(Icons.info_outline),
                        onPressed:
                            () => showGameRules(context, currentGameType),
                      ),
                    ],
                    automaticallyImplyLeading: false,
                    bottom: _buildTurnTimerIndicator(gameData),
                  ),
                  bottomNavigationBar:
                      (showFloatingChat && currentGameType == 'Pictionary')
                          ? Padding(
                            padding: EdgeInsets.only(
