  PreferredSizeWidget? _buildTurnTimerIndicator(Map<String, dynamic> gameData) {
    bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer || gameData['gameState'] != 'playing') return null;

    final turnStartTimeStamp =
        (gameData['turnStartTime'] ??
                gameData['roundStartTime'] ??
                gameData['petitBacRoundStartTime'] ??
                gameData['pictionaryStartTime'] ??
                gameData['hotPotatoRoundStartedAt'])
            as Timestamp?;
    if (turnStartTimeStamp == null) return null;

    final roundState = gameData['roundState']?.toString();
    final currentPhase = gameData['currentPhase']?.toString();
    final loupGarouPhase = gameData['phase']?.toString();
    final aoVPhase = gameData['aoVPhase']?.toString();

    final statesWithTimer = [
      'placement',
      'playing',
      'playing_turn',
      'playing_trick',
      'playing_round_1',
      'playing_round_2',
      'playing_round_3',
      'collecting_words',
      'rolling',
      'player_turn',
      'drawn_card_phase', // <--- Indispensable pour Zéro Pointé
      'revealing_initial', // <--- Indispensable pour Zéro Pointé
      'round_end',
      'voting',
      'result',
      'pre-flop',
      'flop',
      'turn',
      'river',
      'hand_over',
      'clue_giving',
      'turn_result',
      'answering',
      'declaring_truth',
      'guesser_chooses_word',
      'reveal_clues',
      'initial_writing',
      'drawing',
      'guessing',
      'guessing_drawing',
      'nuit',
      'jour_discussion',
      'jour_vote',
      'showing_photo',
      'placing',
      'bidding',
      'challenging',
      'judging_selection',
      'judge_voting',
      'spin_result',
      'writing_challenge',
      'performing',
    ];

    bool shouldShow =
        (roundState != null &&
            (statesWithTimer.contains(roundState) ||
                roundState.startsWith('playing_round_'))) ||
        (currentPhase != null && statesWithTimer.contains(currentPhase)) ||
        (loupGarouPhase != null && statesWithTimer.contains(loupGarouPhase)) ||
        (aoVPhase != null && statesWithTimer.contains(aoVPhase));

    if (!shouldShow) {
      return null;
    }

    final turnStartTime = turnStartTimeStamp.toDate();

    // Utiliser la durée effective (5s si bot, 30s sinon)
    double turnDurationSeconds =
        FirebaseService.getEffectiveTurnTimer(gameData).toDouble();
    if (turnDurationSeconds <= 0) turnDurationSeconds = 30.0;

    if (roundState == 'result' ||
        roundState == 'round_end' ||
        roundState == 'hand_over' ||
        currentPhase == 'turn_result') {
      turnDurationSeconds =
          (gameData['resultTimerSeconds'] as num?)?.toDouble() ?? 15.0;
    }

    final String currentTurnKey = _computeTurnKey(gameData, turnStartTimeStamp);

    return PreferredSize(
      preferredSize: Size.fromHeight(20.0),
      child: StreamBuilder(
        stream: Stream.periodic(Duration(milliseconds: 100)),
        builder: (context, snapshot) {
          final elapsedSeconds =
              DateTime.now().difference(turnStartTime).inMilliseconds / 1000.0;
          final progress =
              (turnDurationSeconds - elapsedSeconds) / turnDurationSeconds;
          final remainingSeconds = max(
            0,
            (turnDurationSeconds - elapsedSeconds).ceil(),
          );

          // ✅ CORRECTION : Ne déclencher le timeout QUE si le temps est réellement écoulé avec une marge,
          // et SEULEMENT si turnStartTime existe depuis au moins 2 secondes (évite le déclenchement immédiat au chargement)
          final bool hasTurnActuallyStarted =
              DateTime.now().difference(turnStartTime).inSeconds >= 2;

          if (hasTurnActuallyStarted &&
              elapsedSeconds >= (turnDurationSeconds + 1.0) &&
              _lastExecutedTimeoutKey != currentTurnKey) {
            _lastExecutedTimeoutKey = currentTurnKey;

            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) {
                final bool isHost = gameData['hostId'] == widget.playerId;
                final bool isCurrentPlayer =
                    FirebaseService.getCurrentPlayerId(gameData) ==
                    widget.playerId;
                if (isHost || isCurrentPlayer) {
                  _executeAutoPlayForGame(gameData);
                }
              }
            });
          }

          return Stack(
            alignment: Alignment.center,
            children: [
              LinearProgressIndicator(
                value: progress.clamp(0.0, 1.0),
                backgroundColor: Colors.grey[700],
                valueColor: AlwaysStoppedAnimation<Color>(
                  progress > 0.5
                      ? Colors.greenAccent
                      : (progress > 0.2
                          ? Colors.orangeAccent
                          : Colors.redAccent),
                ),
                minHeight: 20,
              ),
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.s,
                  [remainingSeconds],
                ),
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: 12,
                  shadows: [
                    Shadow(blurRadius: 2, color: Colors.black.withOpacity(0.8)),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildScoreHeader(
    BuildContext context,
    Map<String, dynamic> players,
    Map<String, dynamic> gameData,
  ) {
    String gameType = gameData['gameType'] ?? '';

    // Liste des jeux où voir la main/grille adverse est pertinent
    bool canViewHands = [
      "Président",
      'Uno',
      'Zéro Pointé',
      'Poker',
      'Big Two',
      'Mille Bornes',
      'Rami',
      'Yams',
    ].contains(gameType);

    List<MapEntry<String, dynamic>> sortedPlayers =
        players.entries.toList()..sort(
          (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
        );

    if (gameType == 'Zéro Pointé') {
      sortedPlayers.sort((a, b) {
        int scoreA = (gameData['totalScores']?[a.key] ?? 0);
        int scoreB = (gameData['totalScores']?[b.key] ?? 0);
        return scoreA.compareTo(scoreB);
      });
    }

    return Card(
      elevation: 4,
      color: Colors.black.withOpacity(0.4),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 6.0),
        child: Container(
          width: double.infinity,
          child: Wrap(
            spacing: 8,
            runSpacing: 6,
            alignment: WrapAlignment.center,
            children:
                sortedPlayers.map((entry) {
                  String pId = entry.key;
                  bool isMe = pId == widget.playerId;
                  String pName = AppLocalizations.of(context)!.joueur;
                  final rawName =
                      entry.value is Map ? entry.value['name'] : null;
                  if (rawName != null &&
                      rawName.toString().trim().isNotEmpty &&
                      rawName != AppLocalizations.of(context)!.inconnu) {
                    pName = rawName.toString();
                  } else {
                    final profileMap =
                        gameData['playerProfiles'] as Map<String, dynamic>?;
                    final profName = profileMap?[pId]?['name'];
                    if (profName != null &&
                        profName.toString().trim().isNotEmpty &&
                        profName != AppLocalizations.of(context)!.inconnu) {
                      pName = profName.toString();
                    } else if (isMe) {
                      final authName =
                          FirebaseAuth.instance.currentUser?.displayName;
                      if (authName != null && authName.trim().isNotEmpty) {
                        pName = authName;
                      }
                    }
                  }
                  int pScore =
                      (gameType == 'Zéro Pointé')
                          ? (gameData['totalScores']?[pId] ?? 0)
                          : (entry.value['score'] ?? 0);
                  int pXp = (entry.value['xp'] as num?)?.toInt() ?? 0;
                  bool isSelected = _viewedOpponentId == pId;
                  final String targetAuthUid = entry.value['authUid'] ?? pId;
                  final String myAuthUid =
                      players[widget.playerId]?['authUid'] ?? widget.playerId;
                  final bool isBot =
                      entry.value['isBot'] == true ||
                      entry.value['replacedByBot'] == true;

                  void toggleOpponentHand() {
                    if (canViewHands && !isMe) {
                      HapticFeedback.mediumImpact();
                      setState(() {
                        _viewedOpponentId =
                            (_viewedOpponentId == pId) ? null : pId;
                      });
                    }
                  }

                  return InkWell(
                    borderRadius: BorderRadius.circular(20),
                    onTap: () {
                      if (canViewHands && !isMe) {
                        toggleOpponentHand();
                      } else {
                        showUserProfileDialog(
                          context,
                          targetUid: targetAuthUid,
                          currentUserId: myAuthUid,
                        );
                      }
                    },
                    onLongPress: () {
                      showUserProfileDialog(
                        context,
                        targetUid: targetAuthUid,
                        currentUserId: myAuthUid,
                      );
                    },
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color:
                            isSelected
                                ? Colors.deepPurple.withOpacity(0.6)
                                : Color(0xFF1E1E28),
                        borderRadius: BorderRadius.circular(20),
                        border: Border.all(
                          color:
                              isSelected
                                  ? Colors.amberAccent
                                  : (isMe
                                      ? Colors.deepPurpleAccent
                                      : Colors.white12),
                          width: isSelected ? 2.0 : 1.0,
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          CircleAvatar(
                            radius: 12,
                            backgroundColor:
                                isMe
                                    ? Colors.deepPurpleAccent
                                    : Colors.grey[800],
                            child:
                                isBot
                                    ? Icon(
                                      Icons.smart_toy,
                                      size: 12,
                                      color: Colors.cyanAccent,
                                    )
                                    : Text(
                                      pName.isNotEmpty
                                          ? pName[0].toUpperCase()
                                          : "?",
                                      style: TextStyle(
                                        color: Colors.white,
                                        fontSize: 10,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                          ),
                          SizedBox(width: 6),
                          Text(
                            AppLocalizations.of(context)!.pts1(pName, pScore),
                            style: TextStyle(
                              fontWeight:
                                  isMe ? FontWeight.bold : FontWeight.normal,
                              color: isMe ? Colors.amberAccent : Colors.white,
                              fontSize: 12,
                            ),
                          ),
                          SizedBox(width: 5),
                          Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 4,
                              vertical: 1,
                            ),
                            decoration: BoxDecoration(
                              color: Colors.deepPurple.withOpacity(0.4),
                              borderRadius: BorderRadius.circular(6),
                            ),
                            child: Text(
                              AppLocalizations.of(context)!.xp(pXp),
                              style: TextStyle(
                                color: Color(0xFF67E8F9),
                                fontWeight: FontWeight.bold,
                                fontSize: 9.5,
                              ),
                            ),
                          ),
                          if (gameType == 'Rami' ||
                              gameType == 'Uno' ||
                              gameType == "Président" ||
                              gameType == 'Big Two' ||
                              gameType == 'Mille Bornes' ||
                              gameType == 'Yams') ...[
                            () {
                              int? cCount;
                              IconData badgeIcon = Icons.style;
                              if (gameType == 'Rami') {
                                cCount =
                                    (gameData['ramiPlayerHands']?[pId] as List?)
                                        ?.length;
                              } else if (gameType == 'Uno') {
                                cCount =
                                    (gameData['unoPlayerHands']?[pId] as List?)
                                        ?.length;
                              } else if (gameType == 'Président') {
                                cCount =
                                    (gameData['playerHands']?[pId] as List?)
                                        ?.length;
                              } else if (gameType == 'Big Two') {
                                cCount =
                                    (gameData['bigTwoPlayerHands']?[pId]
                                            as List?)
                                        ?.length;
                              } else if (gameType == 'Mille Bornes') {
                                cCount =
                                    (gameData['milleBornesPlayerData']?[pId]?['hand']
                                            as List?)
                                        ?.length;
                              } else if (gameType == 'Yams') {
                                badgeIcon = Icons.casino;
                                final sMap = Map<String, dynamic>.from(
                                  gameData['yamsScores']?[pId] ?? {},
                                );
                                int sUpper = [
                                  AppLocalizations.of(context)!.asLabel,
                                  AppLocalizations.of(context)!.deux,
                                  AppLocalizations.of(context)!.trois,
                                  AppLocalizations.of(context)!.quatre,
                                  AppLocalizations.of(context)!.cinq,
                                  AppLocalizations.of(context)!.six,
                                ].fold<int>(
                                  0,
                                  (sum, cat) =>
                                      sum + ((sMap[cat] as num?)?.toInt() ?? 0),
                                );
                                int sBonus = sUpper >= 63 ? 35 : 0;
                                cCount =
                                    sMap.values.fold<int>(
                                      0,
                                      (sum, val) =>
                                          sum + ((val as num?)?.toInt() ?? 0),
                                    ) +
                                    sBonus;
                              }
                              if (cCount == null)
                                return const SizedBox.shrink();
                              return Padding(
                                padding: const EdgeInsets.only(left: 4.0),
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 4,
                                    vertical: 1,
                                  ),
                                  decoration: BoxDecoration(
                                    color: Colors.amber.withOpacity(0.2),
                                    borderRadius: BorderRadius.circular(6),
                                    border: Border.all(
                                      color: Colors.amberAccent.withOpacity(
                                        0.4,
                                      ),
                                      width: 0.8,
                                    ),
                                  ),
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Icon(
                                        badgeIcon,
                                        size: 9,
                                        color: Colors.amberAccent,
                                      ),
                                      SizedBox(width: 2),
                                      Text(
                                        "$cCount",
                                        style: TextStyle(
                                          color: Colors.amberAccent,
                                          fontWeight: FontWeight.bold,
                                          fontSize: 9.5,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              );
                            }(),
                          ],
                          if (canViewHands && !isMe) ...[
                            SizedBox(width: 4),
                            GestureDetector(
                              onTap: toggleOpponentHand,
                              child: Icon(
                                _viewedOpponentId == pId
                                    ? Icons.visibility_off
                                    : Icons.visibility,
                                size: 14,
                                color:
                                    _viewedOpponentId == pId
                                        ? Colors.amberAccent
                                        : Colors.white54,
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                  );
                }).toList(),
          ),
        ),
      ),
    );
  }

  Widget _buildOpponentHandView(
    Map<String, dynamic> gameData,
    String opponentId,
  ) {
    final String gameType = gameData['gameType'] ?? '';

    Widget buildFaceDownCard() => Container(
      width: 32,
      height: 48,
      decoration: BoxDecoration(
        color: Color(0xFF1E293B),
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.white24),
        boxShadow: [
          BoxShadow(color: Colors.black45, offset: Offset(1, 1), blurRadius: 2),
        ],
      ),
      child: Center(
        child: Icon(Icons.style_rounded, color: Colors.white24, size: 16),
      ),
    );

    Widget buildFannedCards(int count, {List<String>? visibleCards}) {
      if (count == 0) {
        return Text(
          AppLocalizations.of(context)!.nAPlusDeCartes,
          style: TextStyle(color: Colors.white70, fontSize: 12),
        );
      }
      return SizedBox(
        height: 52,
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: BouncingScrollPhysics(),
          child: Row(
            children: [
              ...List.generate(count, (index) {
                Widget cardWidget;
                if (visibleCards != null && index < visibleCards.length) {
                  cardWidget = _buildCard(
                    card: visibleCards[index],
                    isSelected: false,
                    scale: 0.5,
                  );
                } else {
                  cardWidget = buildFaceDownCard();
                }

                return Align(
                  widthFactor: 0.38,
                  alignment: Alignment.centerLeft,
                  child: cardWidget,
                );
              }),
              SizedBox(width: 24),
            ],
          ),
        ),
      );
    }

    switch (gameType) {
      case 'Président':
        final hand = List<String>.from(
          gameData['playerHands']?[opponentId] ?? [],
        );
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.cartesRestantes,
                [hand.length],
              ),
              style: TextStyle(color: Colors.white70, fontSize: 11),
            ),
            SizedBox(height: 4),
            buildFannedCards(hand.length),
          ],
        );

      case 'Big Two':
        int count =
            (gameData['bigTwoPlayerHands']?[opponentId] as List?)?.length ?? 0;
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.cartesRestantes,
                [count],
              ),
              style: TextStyle(color: Colors.white70, fontSize: 11),
            ),
            SizedBox(height: 4),
            buildFannedCards(count),
          ],
        );

      case 'Uno':
        final handUno = List<String>.from(
          gameData['unoPlayerHands']?[opponentId] ?? [],
        );
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.cartesRestantes,
                [handUno.length],
              ),
              style: TextStyle(color: Colors.white70, fontSize: 11),
            ),
            SizedBox(height: 4),
            buildFannedCards(handUno.length),
          ],
        );

      case 'Poker':
        final pData = gameData['playerData']?[opponentId] ?? {};
        final chips = pData['chips'] ?? 0;
        final bet = pData['currentBet'] ?? 0;
        final status = pData['status'] ?? 'out';
        final hand = List<String>.from(pData['hand'] ?? []);
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.jetonsMise,
                [chips, bet],
              ),
              style: TextStyle(color: Colors.amberAccent, fontSize: 11),
            ),
            SizedBox(height: 4),
            (gameData['phase'] == 'showdown' || status == 'all-in')
                ? buildFannedCards(hand.length, visibleCards: hand)
                : buildFannedCards(hand.length),
          ],
        );

      case 'Zéro Pointé':
        return Container(
          constraints: BoxConstraints(maxHeight: 120),
          child: SingleChildScrollView(
            child: _buildZeroPointeGrid(
              List<Map<String, dynamic>>.from(
                gameData['playerGrids']?[opponentId] ?? [],
              ),
              null,
            ),
          ),
        );

      case 'Rami':
        final ramiHand = List<String>.from(
          gameData['ramiPlayerHands']?[opponentId] ?? [],
        );
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.cartesRestantes,
                [ramiHand.length],
              ),
              style: TextStyle(color: Colors.white70, fontSize: 11),
            ),
            SizedBox(height: 4),
            buildFannedCards(ramiHand.length),
          ],
        );

      case 'Yams':
        final rawScores = Map<String, dynamic>.from(
          gameData['yamsScores'] ?? {},
        );
        final oppScores = Map<String, dynamic>.from(
          rawScores[opponentId] ?? {},
        );
        int oppUpper = [
          AppLocalizations.of(context)!.asLabel,
          AppLocalizations.of(context)!.deux,
          AppLocalizations.of(context)!.trois,
          AppLocalizations.of(context)!.quatre,
          AppLocalizations.of(context)!.cinq,
          AppLocalizations.of(context)!.six,
        ].fold<int>(
          0,
          (sum, cat) => sum + ((oppScores[cat] as num?)?.toInt() ?? 0),
        );
        int oppBonus = oppUpper >= 63 ? 35 : 0;
        int oppTotal =
            oppScores.values.fold<int>(
              0,
              (sum, val) => sum + ((val as num?)?.toInt() ?? 0),
            ) +
            oppBonus;

        final List<String> categories = [
          AppLocalizations.of(context)!.asLabel,
          AppLocalizations.of(context)!.deux,
          AppLocalizations.of(context)!.trois,
          AppLocalizations.of(context)!.quatre,
          AppLocalizations.of(context)!.cinq,
          AppLocalizations.of(context)!.six,
          AppLocalizations.of(context)!.brelan,
          AppLocalizations.of(context)!.carre,
          AppLocalizations.of(context)!.full,
          AppLocalizations.of(context)!.petiteSuite,
          AppLocalizations.of(context)!.grandeSuite,
          'Yams',
          AppLocalizations.of(context)!.chance,
        ];

        return Container(
          constraints: BoxConstraints(maxHeight: 180),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.only(bottom: 6),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceAround,
                  children: [
                    Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.totalPts,
                        [oppTotal],
                      ),
                      style: TextStyle(
                        color: Colors.amberAccent,
                        fontWeight: FontWeight.bold,
                        fontSize: 13,
                      ),
                    ),
                    Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.sectionSup,
                        [
                          AppLocalizations.of(
                            context,
                          )!.k63Pts(oppUpper, oppBonus > 0 ? '(+35)' : ''),
                        ],
                      ),
                      style: TextStyle(
                        color:
                            oppBonus > 0 ? Colors.greenAccent : Colors.white70,
                        fontSize: 11,
                      ),
                    ),
                    Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.k13Remplies,
                        [oppScores.length],
                      ),
                      style: TextStyle(color: Colors.white54, fontSize: 11),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: SingleChildScrollView(
                  child: Wrap(
                    spacing: 6,
                    runSpacing: 6,
                    alignment: WrapAlignment.center,
                    children:
                        categories.map((cat) {
                          final hasScore = oppScores.containsKey(cat);
                          final scoreVal = oppScores[cat];
                          return Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 7,
                              vertical: 3,
                            ),
                            decoration: BoxDecoration(
                              color:
                                  hasScore
                                      ? ((scoreVal as num? ?? 0) > 0
                                          ? Colors.amber.withOpacity(0.2)
                                          : Colors.red.withOpacity(0.15))
                                      : Colors.white.withOpacity(0.05),
                              borderRadius: BorderRadius.circular(6),
                              border: Border.all(
                                color:
                                    hasScore
                                        ? ((scoreVal as num? ?? 0) > 0
                                            ? Colors.amberAccent
                                            : Colors.redAccent.withOpacity(0.5))
                                        : Colors.white12,
                              ),
                            ),
                            child: Text(
                              AppLocalizations.of(
                                context,
                              )!.str8f522b(cat, hasScore ? '$scoreVal' : '—'),
                              style: TextStyle(
                                fontSize: 10.5,
                                fontWeight:
                                    hasScore
                                        ? FontWeight.bold
                                        : FontWeight.normal,
                                color: hasScore ? Colors.white : Colors.white38,
                              ),
                            ),
                          );
                        }).toList(),
                  ),
                ),
              ),
            ],
          ),
        );

      default:
        return const SizedBox.shrink();
    }
  }

  Widget buildFaceDownCard() => Container(
    width: 40,
    height: 60,
    margin: EdgeInsets.symmetric(horizontal: 2),
    decoration: BoxDecoration(
      color: Colors.indigo,
      borderRadius: BorderRadius.circular(4),
      border: Border.all(color: Colors.white24),
    ),
  );

  // ===========================================================================
  // 🎴 ZÉRO POINTÉ (SKYJO) - DESIGN & EXPÉRIENCE MODERNE
  // ===========================================================================
  Widget _buildZeroPointeUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final gameState = gameData['gameState'];
    final players = gameData['players'] as Map<String, dynamic>;
    final isHost = gameData['hostId'] == playerId;

    // --- 1. ÉCRAN DE FIN DE MANCHE & CLASSEMENT ---
    if (roundState == 'round_end') {
      final totalScores = Map<String, dynamic>.from(
        gameData['totalScores'] ?? {},
      );
      final roundScores = Map<String, dynamic>.from(
        gameData['roundScores'] ?? {},
      );
      final roundEnderId = gameData['roundEnderId'];
      final roundEnderName =
          players[roundEnderId]?['name'] ??
          AppLocalizations.of(context)!.inconnu;

      List<MapEntry<String, dynamic>> sortedPlayersByTotal =
          totalScores.entries.toList()
            ..sort((a, b) => a.value.compareTo(b.value));

      if (gameState == 'gameOver') {
        final totalScores = Map<String, int>.from(
          (gameData['totalScores'] as Map? ?? {}).map(
            (k, v) => MapEntry(k.toString(), (v as num).toInt()),
          ),
        );
        return UniversalGameEndScreen(
          gameTitle: AppLocalizations.of(context)!.zeroPointe,
          winnerId: gameData['gameWinner'],
          winnerName: players[gameData['gameWinner']]?['name'],
          reason: AppLocalizations.of(context)!.partieTermineeAvecLeScore,
          players: players,
          customScores: totalScores,
          lowerScoreWins: true,
          gameData: gameData,
          gameCode: widget.gameCode,
          currentPlayerId: playerId,
          isHost: isHost,
          onExit: _exitGame,
        );
      }

      return Center(
        child: Container(
          margin: const EdgeInsets.all(16),
          padding: const EdgeInsets.all(20),
          decoration: BoxDecoration(
            color: Color(0xFF1E1E2E),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(color: Colors.white12),
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(Icons.flag_rounded, size: 48, color: Colors.cyanAccent),
              SizedBox(height: 8),
              Text(
                AppLocalizations.of(context)!.finDeLaManche,
                style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
              ),
              SizedBox(height: 4),
              Text(
                AppLocalizations.of(
                  context,
                )!.skyjoRoundEnderNotice(roundEnderName),
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.white70, fontSize: 13),
              ),
              SizedBox(height: 14),
              Divider(color: Colors.white24),
              SizedBox(height: 6),
              ...sortedPlayersByTotal.map((entry) {
                final pName =
                    players[entry.key]?['name'] ??
                    AppLocalizations.of(context)!.joueur;
                final rScore = roundScores[entry.key] ?? 0;
                final tScore = entry.value;
                return Container(
                  margin: const EdgeInsets.symmetric(vertical: 3),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.04),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        pName,
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                      Text(
                        AppLocalizations.of(
                          context,
                        )!.skyjoRoundScoreNotice('$rScore', '$tScore'),
                        style: TextStyle(color: Colors.white70, fontSize: 12),
                      ),
                    ],
                  ),
                );
              }),
              SizedBox(height: 18),
              if (isHost)
                ElevatedButton.icon(
                  icon: Icon(Icons.arrow_forward_rounded),
                  label:
                      _isActionPending
                          ? SizedBox(
                            width: 16,
                            height: 16,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                          : Text(AppLocalizations.of(context)!.mancheSuivante),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.green[700],
                    padding: const EdgeInsets.symmetric(
                      horizontal: 24,
                      vertical: 12,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .startGame(widget.gameCode)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                )
              else
                Text(
                  AppLocalizations.of(context)!.enAttenteDeLHote2,
                  style: TextStyle(
                    fontStyle: FontStyle.italic,
                    color: Colors.white54,
                    fontSize: 12,
                  ),
                ),
            ],
          ),
        ),
      );
    }

    // --- 2. PHASE INITIALE : RÉVÉLER 2 CARTES ---
    final myGrid = List<Map<String, dynamic>>.from(
      gameData['playerGrids'][playerId] ?? [],
    );
    final discardPile = List<int>.from(gameData['discardPile'] ?? []);
    final int? drawnCard = gameData['drawnCard'];
    final bool isMyTurn = gameData['currentPlayerId'] == playerId;

    if (roundState == 'revealing_initial') {
      int revealedCount = gameData['revealedInitialCardsCount'][playerId] ?? 0;
      return Column(
        children: [
          Container(
            margin: EdgeInsets.symmetric(vertical: 8, horizontal: 12),
            padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [Colors.deepPurple.shade900, Color(0xFF1E1B4B)],
              ),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: Colors.deepPurpleAccent.withOpacity(0.5),
              ),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  Icons.touch_app_rounded,
                  color: Colors.amberAccent,
                  size: 24,
                ),
                SizedBox(width: 10),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      AppLocalizations.of(context)!.revelezVos2PremieresCartes,
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        fontSize: 13,
                        color: Colors.amberAccent,
                        letterSpacing: 0.5,
                      ),
                    ),
                    Text(
                      AppLocalizations.of(
                        context,
                      )!.skyjoCardsRevealedCount('$revealedCount'),
                      style: TextStyle(color: Colors.white70, fontSize: 12),
                    ),
                  ],
                ),
              ],
            ),
          ),
          Expanded(
            child: _buildZeroPointeGrid(myGrid, (index) {
              if (revealedCount < 2 && myGrid[index]['revealed'] == false) {
                HapticFeedback.lightImpact();
                _firebaseService.revealInitialZeroPointeCard(
                  widget.gameCode,
                  playerId,
                  index,
                );
              }
            }),
          ),
        ],
      );
    }

    // --- 3. TOUR DE JEU ACTIF ---
    String instructions =
        isMyTurn
            ? AppLocalizations.of(context)!.cEstVotreTour
            : AppLocalizations.of(context)!.auTourDe1;
    Color instructionColor = isMyTurn ? Colors.greenAccent : Colors.white70;

    if (isMyTurn) {
      if (drawnCard != null) {
        if (_zeroPointeAction == 'use_drawn') {
          instructions = AppLocalizations.of(
            context,
          )!.skyjoReplaceWithDrawn('$drawnCard');
          instructionColor = Colors.greenAccent;
        } else if (_zeroPointeAction == 'discard_drawn') {
          instructions = AppLocalizations.of(context)!.skyjoTapHiddenToReveal;
          instructionColor = Colors.orangeAccent;
        } else {
          instructions = AppLocalizations.of(
            context,
          )!.skyjoChooseActionForDrawn('$drawnCard');
        }
      } else {
        if (_zeroPointeAction == 'take_discard') {
          instructions = AppLocalizations.of(context)!.skyjoReplaceWithDiscard(
            '${discardPile.isNotEmpty ? discardPile.last : 0}',
          );
          instructionColor = Colors.amberAccent;
        } else {
          instructions =
              AppLocalizations.of(context)!.prenezLaDefausseVisibleOu;
        }
      }
    }

    return Column(
      children: [
        // BANDEAU D'INSTRUCTION CONTEXTUEL
        Container(
          width: double.infinity,
          margin: const EdgeInsets.fromLTRB(10, 4, 10, 8),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          decoration: BoxDecoration(
            color:
                isMyTurn
                    ? instructionColor.withOpacity(0.12)
                    : Colors.black.withOpacity(0.3),
            borderRadius: BorderRadius.circular(14),
            border: Border.all(
              color:
                  isMyTurn ? instructionColor.withOpacity(0.5) : Colors.white10,
              width: 1.5,
            ),
          ),
          child: Row(
            children: [
              Icon(
                isMyTurn
                    ? Icons.play_arrow_rounded
                    : Icons.hourglass_top_rounded,
                size: 18,
                color: instructionColor,
              ),
              SizedBox(width: 8),
              Expanded(
                child: Text(
                  instructions,
                  style: TextStyle(
                    color: instructionColor,
                    fontWeight: isMyTurn ? FontWeight.bold : FontWeight.normal,
                    fontSize: 12,
                  ),
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              if (_zeroPointeAction != null && isMyTurn)
                TextButton(
                  onPressed: () => setState(() => _zeroPointeAction = null),
                  style: TextButton.styleFrom(
                    padding: EdgeInsets.zero,
                    visualDensity: VisualDensity.compact,
                  ),
                  child: Text(
                    AppLocalizations.of(context)!.annuler,
                    style: TextStyle(color: Colors.redAccent, fontSize: 11),
                  ),
                ),
            ],
          ),
        ),

        // TAPIS CENTRAL : PILES DE DÉFAUSSE, PIOCHE ET CARTE ACTIVE
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 10),
          padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 16),
          decoration: BoxDecoration(
            color: Color(0xFF14141E).withOpacity(0.85),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: Colors.white10),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              // PILE DÉFAUSSE
              GestureDetector(
                onTap:
                    (isMyTurn &&
                            roundState == 'player_turn' &&
                            drawnCard == null &&
                            discardPile.isNotEmpty)
                        ? () {
                          HapticFeedback.selectionClick();
                          setState(() => _zeroPointeAction = 'take_discard');
                        }
                        : null,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Stack(
                      alignment: Alignment.center,
                      children: [
                        if (_zeroPointeAction == 'take_discard')
                          Container(
                            width: 66,
                            height: 94,
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(10),
                              boxShadow: [
                                BoxShadow(
                                  color: Colors.amberAccent.withOpacity(0.6),
                                  blurRadius: 12,
                                  spreadRadius: 2,
                                ),
                              ],
                            ),
                          ),
                        discardPile.isNotEmpty
                            ? _ZeroPointeCardWidget(
                              value: discardPile.last,
                              isRevealed: true,
                              isSelected: _zeroPointeAction == 'take_discard',
                              scale: 0.9,
                            )
                            : Container(
                              width: 56,
                              height: 80,
                              decoration: BoxDecoration(
                                color: Colors.white10,
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: Colors.white24),
                              ),
                              child: Center(
                                child: Text(
                                  AppLocalizations.of(context)!.vide,
                                  style: TextStyle(
                                    color: Colors.white38,
                                    fontSize: 10,
                                  ),
                                ),
                              ),
                            ),
                      ],
                    ),
                    SizedBox(height: 4),
                    Text(
                      AppLocalizations.of(context)!.defausse,
                      style: TextStyle(
                        color: Colors.white60,
                        fontSize: 9,
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1,
                      ),
                    ),
                  ],
                ),
              ),

              // PILE PIOCHE
              GestureDetector(
                onTap:
                    (isMyTurn &&
                            roundState == 'player_turn' &&
                            drawnCard == null &&
                            !_isActionPending)
                        ? () {
                          HapticFeedback.mediumImpact();
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .drawFromDeckZeroPointe(widget.gameCode, playerId)
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        }
                        : null,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    _ZeroPointeCardWidget(
                      value: 0,
                      isRevealed: false,
                      isSelected: isMyTurn && drawnCard == null,
                      scale: 0.9,
                    ),
                    SizedBox(height: 4),
                    Text(
                      AppLocalizations.of(context)!.pioche1,
                      style: TextStyle(
                        color: Colors.white60,
                        fontSize: 9,
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1,
                      ),
                    ),
                  ],
                ),
              ),

              // CARTE EN COURS DE PIOCHE
              if (drawnCard != null)
                Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    _ZeroPointeCardWidget(
                      value: drawnCard,
                      isRevealed: true,
                      isSelected: true,
                      scale: 0.9,
                    ),
                    SizedBox(height: 4),
                    Text(
                      AppLocalizations.of(context)!.piochee,
                      style: TextStyle(
                        color: Colors.greenAccent,
                        fontSize: 9,
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1,
                      ),
                    ),
                  ],
                ),
            ],
          ),
        ),

        // BOUTONS D'ACTIONS LORSQU'UNE CARTE EST PIOCHÉE
        if (drawnCard != null && isMyTurn)
          Padding(
            padding: const EdgeInsets.symmetric(
              horizontal: 14.0,
              vertical: 6.0,
            ),
            child: Row(
              children: [
                Expanded(
                  child: ElevatedButton.icon(
                    icon: Icon(Icons.swap_horiz_rounded, size: 16),
                    label: Text(
                      AppLocalizations.of(context)!.garderRemplacer,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor:
                          _zeroPointeAction == 'use_drawn'
                              ? Colors.green[700]
                              : Color(0xFF10B981),
                      foregroundColor: Colors.white,
                      elevation: _zeroPointeAction == 'use_drawn' ? 6 : 2,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                    onPressed: () {
                      HapticFeedback.selectionClick();
                      setState(() => _zeroPointeAction = 'use_drawn');
                    },
                  ),
                ),
                SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton.icon(
                    icon: Icon(Icons.delete_outline_rounded, size: 16),
                    label: Text(
                      AppLocalizations.of(context)!.jeterDevoiler,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: Colors.orangeAccent,
                      side: BorderSide(
                        color:
                            _zeroPointeAction == 'discard_drawn'
                                ? Colors.orangeAccent
                                : Colors.white24,
                        width: 1.5,
                      ),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                    onPressed: () {
                      HapticFeedback.selectionClick();
                      setState(() => _zeroPointeAction = 'discard_drawn');
                    },
                  ),
                ),
              ],
            ),
          ),

        SizedBox(height: 4),

        // GRILLE DU JOUEUR (4 COLONNES x 3 RANGÉES)
        Expanded(
          child: _buildZeroPointeGrid(myGrid, (index) async {
            if (!isMyTurn || _isActionPending) return;

            if (_zeroPointeAction == 'take_discard') {
              HapticFeedback.mediumImpact();
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .takeDiscardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            } else if (_zeroPointeAction == 'use_drawn') {
              HapticFeedback.mediumImpact();
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .useDrawnCardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            } else if (_zeroPointeAction == 'discard_drawn') {
              if (myGrid[index]['revealed'] == true) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(
                    content: Text(
                      AppLocalizations.of(context)!.cetteCarteEstDejaVisible,
                    ),
                    backgroundColor: Colors.orange,
                  ),
                );
                return;
              }
              HapticFeedback.mediumImpact();
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .discardDrawnCardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            }
          }),
        ),
      ],
    );
  }

  // --- GRILLE OFFICIELLE 4x3 DE ZÉRO POINTÉ AVEC COLONNES ÉLIMINÉES ---
  Widget _buildZeroPointeGrid(
    List<Map<String, dynamic>> gridData,
    Function(int)? onCardTap,
  ) {
    if (gridData.isEmpty) {
      return Center(child: CircularProgressIndicator());
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        // Détection des colonnes complétées (éliminées = value -100)
        final Set<int> eliminatedCols = {};
        for (int col = 0; col < 4; col++) {
          if (gridData.length > col + 8) {
            if (gridData[col]['value'] == -100 &&
                gridData[col + 4]['value'] == -100 &&
                gridData[col + 8]['value'] == -100) {
              eliminatedCols.add(col);
            }
          }
        }

        return Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
          child: GridView.builder(
            physics: BouncingScrollPhysics(),
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 4,
              mainAxisSpacing: 6,
              crossAxisSpacing: 6,
              childAspectRatio: 0.72,
            ),
            itemCount: gridData.length,
            itemBuilder: (context, index) {
              final card = gridData[index];
              final bool isRevealed = card['revealed'] == true;
              final int value = card['value'] as int? ?? 0;
              final int colIndex = index % 4;
              final bool isColumnEliminated = eliminatedCols.contains(colIndex);

              // Rendu visuel d'une colonne éliminée (Lueur dorée / verrouillée à 0 pts)
              if (value == -100 || isColumnEliminated) {
                return _ZeroPointeClearedColumnSlot(rowIndex: index ~/ 4);
              }

              return GestureDetector(
                onTap: onCardTap != null ? () => onCardTap(index) : null,
                child: _ZeroPointeCardWidget(
                  value: value,
                  isRevealed: isRevealed,
                  isSelected: false,
                ),
              );
            },
          ),
        );
      },
    );
  }

  void _showGridSelectionDialog(
    BuildContext context,
    String title,
    List<Map<String, dynamic>> gridData,
    Function(int) onConfirm,
  ) {
    showDialog(
      context: context,
      builder:
          (dContext) => AlertDialog(
            backgroundColor: Color(0xFF1E1B2E),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
            title: Text(
              title,
              style: TextStyle(color: Colors.white, fontSize: 16),
            ),
            content: SizedBox(
              width: double.maxFinite,
              height: 320,
              child: _buildZeroPointeGrid(gridData, (index) {
                onConfirm(index);
                Navigator.of(dContext).pop();
              }),
            ),
          ),
    );
  }

  Widget _buildGribouillisUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'];
    final List<String> submittedPlayers = List<String>.from(
      gameData['submittedPlayers'] ?? [],
    );
    final Map<String, dynamic> players = Map.from(gameData['players'] ?? {});
    final int playerCount = players.length;
    final isHost = gameData['hostId'] == playerId;
    final String gribouillisMode =
        gameData['gribouillisMode'] ?? AppLocalizations.of(context)!.normal;
    final bool isComplementMode =
        gribouillisMode.toLowerCase().contains('compl') ||
        gribouillisMode == AppLocalizations.of(context)!.complement;
    final bool isBriseGlaceMode =
        gribouillisMode.toLowerCase().contains('brise') ||
        gribouillisMode.toLowerCase().contains('ice') ||
        gribouillisMode == AppLocalizations.of(context)!.briseGlace;
    final bool ajouter1 = gameData['gribouillisSettings']?['ajouter1'] ?? false;
    final int currentStep = gameData['currentStep'];
    final Map<String, dynamic> albums = Map.from(gameData['albums'] ?? {});

    if (roundState == 'results') {
      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      if (playerOrder.isEmpty)
        return Center(
          child: Text(AppLocalizations.of(context)!.aucunAlbumAAfficher),
        );

      final int serverPageIndex = gameData['gribouillisResultPageIndex'] ?? 0;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_gribouillisPageController!.hasClients &&
            _gribouillisPageController!.page?.round() != serverPageIndex) {
          _gribouillisPageController!.animateToPage(
            serverPageIndex,
            duration: Duration(milliseconds: 400),
            curve: Curves.easeInOut,
          );
        }
      });

      return Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              AppLocalizations.of(context)!.vernissage,
              style: Theme.of(context).textTheme.headlineMedium,
            ),
          ),
          Expanded(
            child: PageView.builder(
              controller: _gribouillisPageController,
              itemCount: playerOrder.length,
              physics: BouncingScrollPhysics(),
              onPageChanged: (page) {
                if (isHost) {
                  _firebaseService.setGribouillisResultPage(
                    widget.gameCode,
                    page,
                  );
                }
              },
              itemBuilder: (context, pageIndex) {
                final ownerId = playerOrder[pageIndex];
                final ownerName =
                    players[ownerId]?['name'] ??
                    AppLocalizations.of(context)!.inconnu;
                final albumSteps = List<Map<String, dynamic>>.from(
                  albums[ownerId] ?? [],
                );

                return Container(
                  margin: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: Colors.white, // Fond papier
                    borderRadius: BorderRadius.circular(16),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black54,
                        blurRadius: 15,
                        offset: Offset(0, 10),
                      ),
                    ],
                  ),
                  child: Column(
                    children: [
                      // En-tête Album
                      Container(
                        width: double.infinity,
                        padding: EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: Colors.amber[100],
                          borderRadius: BorderRadius.vertical(
                            top: Radius.circular(16),
                          ),
                        ),
                        child: Text(
                          GameContentLocalization.format(
                            context,
                            AppLocalizations.of(context)!.albumDe,
                            [ownerName],
                          ),
                          style: TextStyle(
                            color: Colors.brown[800],
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                            fontFamily: AppLocalizations.of(context)!.cursive,
                          ),
                          textAlign: TextAlign.center,
                        ),
                      ),
                      Expanded(
                        child: ListView.builder(
                          itemCount: albumSteps.length,
                          padding: EdgeInsets.zero,
                          itemBuilder: (context, index) {
                            final step = albumSteps[index];
                            final authorName = step['authorName'] ?? '...';
                            final isDrawing = step['type'] == 'drawing';

                            return Container(
                              padding: EdgeInsets.all(16),
                              decoration: BoxDecoration(
                                border: Border(
                                  bottom: BorderSide(color: Colors.grey[300]!),
                                ),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      Icon(
                                        isDrawing ? Icons.brush : Icons.edit,
                                        size: 16,
                                        color: Colors.grey,
                                      ),
                                      SizedBox(width: 5),
                                      Text(
                                        index == 0
                                            ? GameContentLocalization.format(
                                              context,
                                              AppLocalizations.of(
                                                context,
                                              )!.departPar,
                                              [authorName],
                                            )
                                            : (isDrawing
                                                ? GameContentLocalization.format(
                                                  context,
                                                  AppLocalizations.of(
                                                    context,
                                                  )!.dessinePar,
                                                  [authorName],
                                                )
                                                : GameContentLocalization.format(
                                                  context,
                                                  AppLocalizations.of(
                                                    context,
                                                  )!.devinePar,
                                                  [authorName],
                                                )),
                                        style: TextStyle(
                                          color: Colors.grey[600],
                                          fontSize: 12,
                                          fontStyle: FontStyle.italic,
                                        ),
                                      ),
                                    ],
                                  ),
                                  SizedBox(height: 8),
                                  if (isDrawing)
                                    Center(
                                      child: Container(
                                        height: 180,
                                        decoration: BoxDecoration(
                                          border: Border.all(
                                            color: Colors.grey[200]!,
                                          ),
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                        ),
                                        child: ClipRRect(
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                          child:
                                              step['content'] != null
                                                  ? Image.memory(
                                                    base64Decode(
                                                      step['content'],
                                                    ),
                                                    fit: BoxFit.contain,
                                                  )
                                                  : Center(
                                                    child: Icon(
                                                      Icons.broken_image,
                                                      color: Colors.grey,
                                                    ),
                                                  ),
                                        ),
                                      ),
                                    )
                                  else
                                    Center(
                                      child: Text(
                                        AppLocalizations.of(
                                          context,
                                        )!.aa(step['content']),
                                        style: TextStyle(
                                          fontSize: 20,
                                          color: Colors.black87,
                                          fontWeight: FontWeight.w500,
                                          fontFamily: 'Courier',
                                        ),
                                        textAlign: TextAlign.center,
                                      ),
                                    ),
                                ],
                              ),
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),

          if (isHost)
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton.icon(
                  onPressed: () {
                    final int newIndex =
                        (serverPageIndex - 1 + playerOrder.length) %
                        playerOrder.length;
                    _firebaseService.setGribouillisResultPage(
                      widget.gameCode,
                      newIndex,
                    );
                  },
                  icon: Icon(Icons.navigate_before),
                  label: Text(AppLocalizations.of(context)!.prec),
                ),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.album,
                    [serverPageIndex + 1, playerOrder.length],
                  ),
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
                ElevatedButton.icon(
                  onPressed: () {
                    final int newIndex =
                        (serverPageIndex + 1) % playerOrder.length;
                    _firebaseService.setGribouillisResultPage(
                      widget.gameCode,
                      newIndex,
                    );
                  },
                  icon: Icon(Icons.navigate_next),
                  label: Text(AppLocalizations.of(context)!.suiv),
                ),
              ],
            ),
          SizedBox(height: 8),
          if (isHost)
            ElevatedButton(
              onPressed: () => _firebaseService.startGame(widget.gameCode),
              child: Text(AppLocalizations.of(context)!.rejouer),
            ),
        ],
      );
    }

    if (submittedPlayers.contains(playerId)) {
      return _buildWaitingWidget(
        AppLocalizations.of(context)!.enAttenteDesAutresJoueurs,
        players,
        submittedPlayers.length,
        playerCount,
      );
    }

    final List<String> playerOrder = List<String>.from(gameData['playerOrder']);
    final int myIndex = playerOrder.indexOf(playerId);
    if (myIndex == -1) return Center(child: CircularProgressIndicator());

    Map<String, dynamic>? stepToProcess;
    if (currentStep > 0) {
      String sourceAlbumOwnerId;

      if ((isComplementMode && ajouter1) || isBriseGlaceMode) {
        sourceAlbumOwnerId = playerOrder[(myIndex + currentStep) % playerCount];
      } else {
        sourceAlbumOwnerId =
            playerOrder[(myIndex - currentStep + (playerCount * currentStep)) %
                playerCount];
      }
      List<dynamic> sourceAlbum = List.from(
        gameData['albums'][sourceAlbumOwnerId] ?? [],
      );
      if (sourceAlbum.isNotEmpty) {
        if ((isComplementMode && ajouter1) || isBriseGlaceMode) {
          stepToProcess = Map<String, dynamic>.from(sourceAlbum[0]);
        } else {
          stepToProcess = Map<String, dynamic>.from(sourceAlbum.last);
        }
      }
    }

    if (roundState == 'initial_writing' || roundState == 'guessing') {
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          if (stepToProcess != null && stepToProcess['type'] == 'drawing')
            Expanded(
              child: Column(
                children: [
                  Text(
                    AppLocalizations.of(context)!.devineCeQueRepresenteCe,
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  Expanded(
                    child: Container(
                      margin: EdgeInsets.symmetric(vertical: 10),
                      decoration: BoxDecoration(
                        color: Colors.white,
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(11),
                        child:
                            stepToProcess['content'] != null
                                ? Image.memory(
                                  base64Decode(stepToProcess['content']),
                                  fit: BoxFit.contain,
                                )
                                : Center(
                                  child: Icon(
                                    Icons.broken_image,
                                    color: Colors.grey,
                                  ),
                                ),
                      ),
                    ),
                  ),
                ],
              ),
            )
          else
            Text(
              gribouillisMode == AppLocalizations.of(context)!.briseGlace
                  ? AppLocalizations.of(context)!.ecrisUnThemeOuUne
                  : AppLocalizations.of(context)!.imagineUnePhrase,
              style: Theme.of(context).textTheme.headlineSmall,
              textAlign: TextAlign.center,
            ),
          SizedBox(height: 20),
          TextField(
            controller: _answerController,
            decoration: InputDecoration(
              labelText: AppLocalizations.of(context)!.ecrisTaPhrase,
            ),
            maxLines: 2,
          ),
          SizedBox(height: 20),
          ElevatedButton(
            onPressed: () {
              if (_answerController.text.trim().isNotEmpty) {
                _firebaseService.submitGribouillisStep(
                  widget.gameCode,
                  playerId,
                  'text',
                  _answerController.text.trim(),
                );
                _answerController.clear();
              }
            },
            child: Text(AppLocalizations.of(context)!.valider),
          ),
        ],
      );
    }

    if (roundState == 'initial_drawing' || roundState == 'drawing') {
      String promptText;
      if (stepToProcess != null && stepToProcess['type'] == 'text') {
        promptText = AppLocalizations.of(
          context,
        )!.dessineCettePhrase(stepToProcess['content']);
      } else if (isComplementMode) {
        promptText = AppLocalizations.of(context)!.completeCeDessin;
      } else {
        promptText = AppLocalizations.of(context)!.commenceParUnDessin;
      }

      final String? backgroundDrawingData =
          (isComplementMode &&
                  stepToProcess != null &&
                  stepToProcess['type'] == 'drawing')
              ? stepToProcess['content'] as String?
              : null;

      return Column(
        children: [
          Expanded(
            child: Center(
              child: Text(
                promptText,
                style: Theme.of(context).textTheme.headlineSmall,
                textAlign: TextAlign.center,
              ),
            ),
          ),
          ElevatedButton(
            onPressed: () async {
              final drawingResult = await Navigator.push<Map<String, dynamic>>(
                context,
                MaterialPageRoute(
                  builder:
                      (_) => DrawingScreen(
                        prompt: promptText,
                        backgroundDrawingData: backgroundDrawingData,
                      ),
                ),
              );
              if (drawingResult != null && mounted) {
                _firebaseService.submitGribouillisStep(
                  widget.gameCode,
                  playerId,
                  'drawing',
                  drawingResult['drawing'] as String,
                );
              }
            },
            child: Text(AppLocalizations.of(context)!.ouvrirLaZoneDeDessin),
          ),
        ],
      );
    }

    return Center(
      child: Text(
        GameContentLocalization.format(
          context,
          AppLocalizations.of(context)!.etatGribouillisInconnu,
          [roundState],
        ),
      ),
    );
  }

  Widget _buildTabooUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final livekit = Provider.of<LivekitService>(context, listen: false);
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final Map<String, dynamic> tabooTeams = Map<String, dynamic>.from(
      gameData['tabooTeams'] ?? {},
    );
    final Map<String, int> tabooScores = Map<String, int>.from(
      gameData['tabooScores'] ?? {},
    );

    final String currentTeamId = gameData['tabooCurrentTeamId'] ?? 'team_0';
    final String clueGiverId = gameData['tabooClueGiverId'] ?? '';
    final String currentWord = gameData['tabooCurrentWord'] ?? '...';
    final List<String> forbiddenWords = List<String>.from(
      gameData['tabooForbiddenWords'] ?? [],
    );
    final bool isTurnActive = gameData['tabooTurnActive'] ?? false;
    final bool videoEnabled = gameData['videoEnabled'] == true;

    // Détermination des rôles
    String myTeamId = '';
    tabooTeams.forEach((teamId, teamMembers) {
      if (List<String>.from(teamMembers).contains(playerId)) {
        myTeamId = teamId;
      }
    });

    final bool isMyTeamTurn = (myTeamId == currentTeamId);
    final bool amIClueGiver = (playerId == clueGiverId);
    final bool amIOpponent = !isMyTeamTurn;
    final String clueGiverName =
        players[clueGiverId]?['name'] ?? AppLocalizations.of(context)!.orateur;

    // Récupération des identifiants LiveKit
    final Map<String, String> playerLivekitIdentities = {};
    players.forEach((pId, pData) {
      if (pData['livekitIdentity'] != null) {
        playerLivekitIdentities[pId] = pData['livekitIdentity'];
      }
    });

    Widget buildCompactParticipant(String pId) {
      final String? identity = playerLivekitIdentities[pId];
      final String name =
          players[pId]?['name'] ?? AppLocalizations.of(context)!.joueur;
      final bool isGiver = (pId == clueGiverId);
      final bool isLocal = (pId == playerId);
      final bool isSameTeam = List<String>.from(
        tabooTeams[myTeamId] ?? [],
      ).contains(pId);

      VideoTrack? videoTrack =
          identity != null ? livekit.getVideoTrack(identity) : null;

      return Container(
        width: 64,
        margin: const EdgeInsets.symmetric(horizontal: 4),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Stack(
              alignment: Alignment.center,
              children: [
                Container(
                  width: 44,
                  height: 44,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(
                      color:
                          isGiver
                              ? Colors.amberAccent
                              : (isSameTeam
                                  ? Colors.cyanAccent.withOpacity(0.6)
                                  : Colors.redAccent.withOpacity(0.6)),
                      width: isGiver ? 2.5 : 1.5,
                    ),
                    boxShadow:
                        isGiver
                            ? [
                              BoxShadow(
                                color: Colors.amberAccent.withOpacity(0.4),
                                blurRadius: 8,
                                spreadRadius: 1,
                              ),
                            ]
                            : null,
                  ),
                  child: ClipOval(
                    child:
                        videoEnabled && videoTrack != null
                            ? VideoTrackRenderer(videoTrack)
                            : Container(
                              color:
                                  isSameTeam
                                      ? Color(0xFF1E3A8A)
                                      : Color(0xFF881337),
                              child: Center(
                                child: Text(
                                  name.isNotEmpty ? name[0].toUpperCase() : '?',
                                  style: TextStyle(
                                    fontWeight: FontWeight.bold,
                                    color: Colors.white,
                                    fontSize: 16,
                                  ),
                                ),
                              ),
                            ),
                  ),
                ),
                if (isGiver)
                  Positioned(
                    bottom: -2,
                    right: -2,
                    child: Container(
                      padding: const EdgeInsets.all(3),
                      decoration: BoxDecoration(
                        color: Colors.amber,
                        shape: BoxShape.circle,
                      ),
                      child: Icon(Icons.mic, size: 10, color: Colors.black),
                    ),
                  ),
              ],
            ),
            SizedBox(height: 3),
            Text(
              isLocal ? AppLocalizations.of(context)!.moi : name,
              style: TextStyle(
                fontSize: 10,
                fontWeight: isGiver ? FontWeight.bold : FontWeight.normal,
                color: isGiver ? Colors.amberAccent : Colors.white70,
              ),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.center,
            ),
          ],
        ),
      );
    }

    return Column(
      children: [
        // 1. BARRE SUPÉRIEURE : ÉQUIPES & JOUEURS RÉUNIS
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          decoration: BoxDecoration(
            color: Colors.black.withOpacity(0.4),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: Colors.white10),
          ),
          child: Row(
            children: [
              // Scores compacts
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 8,
                        height: 8,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color:
                              currentTeamId == 'team_0'
                                  ? Colors.greenAccent
                                  : Colors.white24,
                        ),
                      ),
                      SizedBox(width: 6),
                      Text(
                        GameContentLocalization.format(
                          context,
                          AppLocalizations.of(context)!.eq1Pts,
                          [tabooScores['team_0'] ?? 0],
                        ),
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w600,
                          color:
                              currentTeamId == 'team_0'
                                  ? Colors.greenAccent
                                  : Colors.white60,
                        ),
                      ),
                    ],
                  ),
                  SizedBox(height: 3),
                  Row(
                    children: [
                      Container(
                        width: 8,
                        height: 8,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color:
                              currentTeamId == 'team_1'
                                  ? Colors.greenAccent
                                  : Colors.white24,
                        ),
                      ),
                      SizedBox(width: 6),
                      Text(
                        GameContentLocalization.format(
                          context,
                          AppLocalizations.of(context)!.eq2Pts,
                          [tabooScores['team_1'] ?? 0],
                        ),
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w600,
                          color:
                              currentTeamId == 'team_1'
                                  ? Colors.greenAccent
                                  : Colors.white60,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
              SizedBox(width: 12),
              SizedBox(
                height: 36,
                child: VerticalDivider(color: Colors.white24, thickness: 1),
              ),
              Spacer(),
              // Statut manche
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.manche1,
                  [
                    (gameData['tabooRoundNumber'] as num?)?.toInt() ?? 1,
                    (gameData['tabooTotalRounds'] as num?)?.toInt() ?? 4,
                  ],
                ),
                style: TextStyle(
                  color: Colors.white54,
                  fontSize: 11,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 10),

        // 2. BANDEAU DE STATUT DE RÔLE CONTEXTUEL
        Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          decoration: BoxDecoration(
            color:
                amIClueGiver
                    ? Colors.amber.withOpacity(0.15)
                    : (isMyTeamTurn
                        ? Colors.cyanAccent.withOpacity(0.12)
                        : Colors.redAccent.withOpacity(0.12)),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color:
                  amIClueGiver
                      ? Colors.amberAccent.withOpacity(0.4)
                      : (isMyTeamTurn
                          ? Colors.cyanAccent.withOpacity(0.3)
                          : Colors.redAccent.withOpacity(0.3)),
            ),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                amIClueGiver
                    ? Icons.record_voice_over_rounded
                    : (isMyTeamTurn
                        ? Icons.hearing_rounded
                        : Icons.gavel_rounded),
                size: 18,
                color:
                    amIClueGiver
                        ? Colors.amberAccent
                        : (isMyTeamTurn ? Colors.cyanAccent : Colors.redAccent),
              ),
              SizedBox(width: 8),
              Flexible(
                child: Text(
                  amIClueGiver
                      ? AppLocalizations.of(context)!.vousEtesLOrateurFaites
                      : (isMyTeamTurn
                          ? GameContentLocalization.format(
                            context,
                            AppLocalizations.of(
                              context,
                            )!.faitDevinerAVotreEquipe,
                            [clueGiverName],
                          )
                          : GameContentLocalization.format(
                            context,
                            AppLocalizations.of(
                              context,
                            )!.surveillezEtBuzzezEnCas,
                            [clueGiverName],
                          )),
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    color:
                        amIClueGiver
                            ? Colors.amberAccent
                            : (isMyTeamTurn
                                ? Colors.cyanAccent
                                : Colors.redAccent),
                  ),
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 12),

        // Détection live du buzzer pour avertir l'orateur
        StreamBuilder<DatabaseEvent>(
          stream: _firebaseService.getTabooBuzzerLiveStream(widget.gameCode),
          builder: (context, snap) {
            String? buzzerPlayerId;
            if (snap.hasData && snap.data!.snapshot.value != null) {
              try {
                final raw = Map<String, dynamic>.from(
                  snap.data!.snapshot.value as Map,
                );
                buzzerPlayerId = raw['playerId'] as String?;
              } catch (_) {}
            }

            if (buzzerPlayerId != null && buzzerPlayerId != playerId) {
              final bName =
                  players[buzzerPlayerId]?['name'] ??
                  AppLocalizations.of(context)!.lAdversaire;
              return Container(
                margin: const EdgeInsets.only(bottom: 8),
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 6,
                ),
                decoration: BoxDecoration(
                  color: Colors.redAccent.withOpacity(0.25),
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: Colors.redAccent, width: 1.5),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.redAccent.withOpacity(0.4),
                      blurRadius: 10,
                      spreadRadius: 1,
                    ),
                  ],
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.touch_app, color: Colors.redAccent, size: 16),
                    SizedBox(width: 8),
                    Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.aLeDoigtSurLe,
                        [bName],
                      ),
                      style: TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 12,
                      ),
                    ),
                  ],
                ),
              );
            }
            return const SizedBox.shrink();
          },
        ),

        // 3. CARTE TABOO CENTRALE MINIMALISTE & DESIGN
        Expanded(
          child: Center(
            child: SingleChildScrollView(
              physics: BouncingScrollPhysics(),
              child: Container(
                width: double.infinity,
                constraints: BoxConstraints(maxWidth: 360),
                decoration: BoxDecoration(
                  color: Color(0xFF1E1E2E),
                  borderRadius: BorderRadius.circular(24),
                  border: Border.all(
                    color:
                        amIOpponent
                            ? Colors.redAccent.withOpacity(0.4)
                            : Colors.amberAccent.withOpacity(0.4),
                    width: 1.5,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: (amIOpponent
                              ? Colors.redAccent
                              : Colors.purpleAccent)
                          .withOpacity(0.18),
                      blurRadius: 20,
                      spreadRadius: 2,
                      offset: Offset(0, 8),
                    ),
                  ],
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    // En-tête de carte : Mot cible
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.symmetric(
                        vertical: 20,
                        horizontal: 16,
                      ),
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors:
                              amIOpponent
                                  ? [Color(0xFF4A1020), Color(0xFF2A0812)]
                                  : [Color(0xFF3B1366), Color(0xFF1D0933)],
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                        ),
                        borderRadius: const BorderRadius.vertical(
                          top: Radius.circular(22),
                        ),
                      ),
                      child: Column(
                        children: [
                          Text(
                            AppLocalizations.of(context)!.motCible,
                            style: TextStyle(
                              letterSpacing: 2,
                              fontSize: 11,
                              fontWeight: FontWeight.bold,
                              color:
                                  amIOpponent
                                      ? Colors.redAccent.shade100
                                      : Colors.amberAccent.shade100,
                            ),
                          ),
                          SizedBox(height: 6),
                          Text(
                            currentWord.toUpperCase(),
                            style: TextStyle(
                              fontSize: 28,
                              fontWeight: FontWeight.w900,
                              color: Colors.white,
                              letterSpacing: 1.2,
                            ),
                            textAlign: TextAlign.center,
                          ),
                        ],
                      ),
                    ),

                    // Corps de carte : Mots interdits
                    Padding(
                      padding: const EdgeInsets.all(20),
                      child: Column(
                        children: [
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              Icon(
                                Icons.block_rounded,
                                size: 14,
                                color: Colors.redAccent.shade200,
                              ),
                              SizedBox(width: 6),
                              Text(
                                AppLocalizations.of(context)!.interdits,
                                style: TextStyle(
                                  letterSpacing: 1.5,
                                  fontSize: 11,
                                  fontWeight: FontWeight.bold,
                                  color: Colors.redAccent.shade200,
                                ),
                              ),
                            ],
                          ),
                          SizedBox(height: 12),
                          Wrap(
                            spacing: 8,
                            runSpacing: 8,
                            alignment: WrapAlignment.center,
                            children:
                                forbiddenWords.map((word) {
                                  return Container(
                                    padding: EdgeInsets.symmetric(
                                      horizontal: 14,
                                      vertical: 8,
                                    ),
                                    decoration: BoxDecoration(
                                      color: Color(0xFF2A1520),
                                      borderRadius: BorderRadius.circular(12),
                                      border: Border.all(
                                        color: Colors.redAccent.withOpacity(
                                          0.35,
                                        ),
                                        width: 1,
                                      ),
                                    ),
                                    child: Text(
                                      word,
                                      style: TextStyle(
                                        color: Color(0xFFFCA5A5),
                                        fontWeight: FontWeight.bold,
                                        fontSize: 15,
                                      ),
                                    ),
                                  );
                                }).toList(),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),

        SizedBox(height: 12),

        // 4. PANNEAU DE CONTRÔLES ET BOUTONS D'ACTION
        if (isTurnActive) ...[
          if (amIClueGiver)
            SafeArea(
              top: false,
              child: Row(
                children: [
                  Expanded(
                    flex: 1,
                    child: SizedBox(
                      height: 52,
                      child: OutlinedButton.icon(
                        icon: Icon(Icons.skip_next_rounded),
                        label: Text(
                          AppLocalizations.of(context)!.passer,
                          style: TextStyle(fontWeight: FontWeight.bold),
                        ),
                        style: OutlinedButton.styleFrom(
                          foregroundColor: Colors.orangeAccent,
                          side: BorderSide(
                            color: Colors.orangeAccent,
                            width: 1.5,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(14),
                          ),
                        ),
                        onPressed: () {
                          HapticFeedback.lightImpact();
                          _firebaseService.tabooAction(
                            widget.gameCode,
                            playerId,
                            'skip',
                          );
                        },
                      ),
                    ),
                  ),
                  SizedBox(width: 12),
                  Expanded(
                    flex: 2,
                    child: SizedBox(
                      height: 52,
                      child: ElevatedButton.icon(
                        icon: Icon(Icons.check_circle_rounded, size: 22),
                        label: Text(
                          AppLocalizations.of(context)!.trouve,
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1,
                          ),
                        ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Color(0xFF10B981),
                          foregroundColor: Colors.white,
                          elevation: 6,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(14),
                          ),
                        ),
                        onPressed: () {
                          HapticFeedback.mediumImpact();
                          _firebaseService.tabooAction(
                            widget.gameCode,
                            playerId,
                            'correct',
                          );
                        },
                      ),
                    ),
                  ),
                ],
              ),
            )
          else if (amIOpponent)
            SafeArea(
              top: false,
              child: SizedBox(
                width: double.infinity,
                height: 54,
                child: Listener(
                  onPointerDown: (_) {
                    _firebaseService.updateTabooBuzzerLive(
                      widget.gameCode,
                      playerId,
                      true,
                    );
                  },
                  onPointerUp: (_) {
                    _firebaseService.updateTabooBuzzerLive(
                      widget.gameCode,
                      playerId,
                      false,
                    );
                  },
                  onPointerCancel: (_) {
                    _firebaseService.updateTabooBuzzerLive(
                      widget.gameCode,
                      playerId,
                      false,
                    );
                  },
                  child: ElevatedButton.icon(
                    icon: Icon(Icons.warning_amber_rounded, size: 26),
                    label: Text(
                      AppLocalizations.of(context)!.buzzMotInterdit,
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1,
                      ),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Color(0xFFDC2626),
                      foregroundColor: Colors.white,
                      elevation: 6,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                    ),
                    onPressed: () {
                      HapticFeedback.heavyImpact();
                      _firebaseService.updateTabooBuzzerLive(
                        widget.gameCode,
                        playerId,
                        false,
                      );
                      _firebaseService.tabooAction(
                        widget.gameCode,
                        playerId,
                        'buzz',
