  // ===========================================================================
  // 🧟 ZOMBIE ! (AMPHITHÉÂTRE HORREUR CARTOON & TENSION DE PIOCHE)
  // ===========================================================================
  Widget _buildZombieUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final hands = Map<String, List<dynamic>>.from(
      gameData['zombiePlayerHands'] ?? {},
    );
    final playerOrder = List<String>.from(gameData['zombiePlayerOrder'] ?? []);
    final eliminated = List<String>.from(
      gameData['zombieEliminatedPlayers'] ?? [],
    );
    final currentIndex = gameData['zombieCurrentPlayerIndex'] ?? 0;
    final currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final isMyTurn = currentPlayerId == playerId;

    // --- ÉCRAN DE FIN DE PARTIE ---
    if (gameData['gameState'] == 'gameOver') {
      final loserId = gameData['zombieLoserId'];
      final loserName =
          players[loserId]?['name'] ??
          AppLocalizations.of(context)!.unSurvivant;
      final bool amILoser = loserId == playerId;

      return Center(
        child: Container(
          margin: const EdgeInsets.all(24),
          padding: const EdgeInsets.all(28),
          decoration: BoxDecoration(
            color: Color(0xFF1B0F1E),
            borderRadius: BorderRadius.circular(28),
            border: Border.all(
              color: amILoser ? Color(0xFFEF4444) : Color(0xFF10B981),
              width: 2.5,
            ),
            boxShadow: [
              BoxShadow(
                color: (amILoser ? Colors.redAccent : Colors.greenAccent)
                    .withOpacity(0.35),
                blurRadius: 25,
                spreadRadius: 2,
              ),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                amILoser ? Icons.coronavirus_rounded : Icons.shield_rounded,
                size: 72,
                color: amILoser ? Color(0xFFEF4444) : Color(0xFF10B981),
              ),
              SizedBox(height: 14),
              Text(
                amILoser
                    ? AppLocalizations.of(context)!.vousAvezEteInfecte
                    : AppLocalizations.of(context)!.survivantsEchappes,
                style: TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1.2,
                  color: amILoser ? Color(0xFFFCA5A5) : Color(0xFF6EE7B7),
                ),
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 8),
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.estResteAvecLeZombie,
                  [loserName],
                ),
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.white70, fontSize: 14),
              ),
              SizedBox(height: 24),
              ElevatedButton.icon(
                icon: Icon(Icons.home_rounded),
                label: Text(AppLocalizations.of(context)!.retourAuSalon),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Color(0xFF4C1D95),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 12,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
                onPressed: _safePopToFirst,
              ),
            ],
          ),
        ),
      );
    }

    // Trouver la cible (voisin de gauche actif)
    int targetIndex = currentIndex;
    do {
      targetIndex = (targetIndex + 1) % playerOrder.length;
    } while (eliminated.contains(playerOrder[targetIndex]) &&
        targetIndex != currentIndex);

    String targetPlayerId =
        playerOrder.isNotEmpty ? playerOrder[targetIndex] : '';
    List<String> myHand = List<String>.from(hands[playerId] ?? []);
    List<String> targetHand = List<String>.from(hands[targetPlayerId] ?? []);
    final targetName =
        players[targetPlayerId]?['name'] ??
        AppLocalizations.of(context)!.voisin;

    final bool hasZombieInHand =
        myHand.contains('Zombie') ||
        myHand.contains(AppLocalizations.of(context)!.zombie1);

    return Container(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.topCenter,
          radius: 1.3,
          colors: [Color(0xFF1E1028), Color(0xFF0A050F)],
        ),
      ),
      child: Column(
        children: [
          // 1. BANDEAU DE STATUT & SURVIVANTS ÉCHAPPÉS
          Container(
            margin: const EdgeInsets.fromLTRB(10, 4, 10, 6),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color:
                  isMyTurn
                      ? Color(0xFF2E1065).withOpacity(0.8)
                      : Color(0xFF140F1E).withOpacity(0.8),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color:
                    isMyTurn
                        ? Color(0xFFA855F7)
                        : Colors.white.withOpacity(0.1),
                width: 1.5,
              ),
              boxShadow: [
                if (isMyTurn)
                  BoxShadow(
                    color: Color(0xFFA855F7).withOpacity(0.3),
                    blurRadius: 12,
                  ),
              ],
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(6),
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color:
                            isMyTurn
                                ? Color(0xFFA855F7).withOpacity(0.3)
                                : Colors.white10,
                      ),
                      child: Icon(
                        isMyTurn
                            ? Icons.pan_tool_rounded
                            : Icons.hourglass_top_rounded,
                        size: 16,
                        color: isMyTurn ? Color(0xFFC084FC) : Colors.white60,
                      ),
                    ),
                    SizedBox(width: 8),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          isMyTurn
                              ? GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.piochezChez,
                                [targetName],
                              )
                              : GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.tourDe,
                                [players[currentPlayerId]?['name'] ?? ''],
                              ),
                          style: TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 0.8,
                            color:
                                isMyTurn ? Color(0xFFFDE047) : Colors.white70,
                          ),
                        ),
                        Text(
                          isMyTurn
                              ? AppLocalizations.of(
                                context,
                              )!.choisissezUneCarteFaceCachee
                              : AppLocalizations.of(
                                context,
                              )!.enAttenteDeLaPioche,
                          style: TextStyle(fontSize: 10, color: Colors.white38),
                        ),
                      ],
                    ),
                  ],
                ),
                // Badge d'alerte Zombie en main
                if (hasZombieInHand)
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: Color(0xFF7F1D1D),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: Color(0xFFEF4444)),
                    ),
                    child: Row(
                      children: [
                        Icon(
                          Icons.warning_amber_rounded,
                          color: Colors.redAccent,
                          size: 14,
                        ),
                        SizedBox(width: 4),
                        Text(
                          AppLocalizations.of(context)!.zombieEnMain,
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 9,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ),
                  ),
              ],
            ),
          ),

          // Liste des survivants déjà sauvés (sans cartes)
          if (eliminated.isNotEmpty)
            Container(
              height: 28,
              margin: const EdgeInsets.only(bottom: 6),
              child: ListView(
                scrollDirection: Axis.horizontal,
                physics: BouncingScrollPhysics(),
                padding: const EdgeInsets.symmetric(horizontal: 12),
                children:
                    eliminated.map((pId) {
                      return Container(
                        margin: const EdgeInsets.only(right: 6),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 3,
                        ),
                        decoration: BoxDecoration(
                          color: Color(0xFF065F46),
                          borderRadius: BorderRadius.circular(12),
                          border: Border.all(color: Color(0xFF34D399)),
                        ),
                        child: Row(
                          children: [
                            Icon(
                              Icons.check_circle_rounded,
                              color: Colors.greenAccent,
                              size: 12,
                            ),
                            SizedBox(width: 4),
                            Text(
                              GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.sauve,
                                [players[pId]?['name'] ?? ''],
                              ),
                              style: TextStyle(
                                color: Colors.white,
                                fontSize: 10,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
            ),

          // Main du voisin avec écoute en direct de la carte visée
          Expanded(
            flex: 4,
            child: Container(
              margin: const EdgeInsets.symmetric(horizontal: 10),
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: Color(0xFF13091B).withOpacity(0.85),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: Colors.white10),
              ),
              child: StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getZombieHoverStream(widget.gameCode),
                builder: (context, snap) {
                  int? hoveredIndex;
                  if (snap.hasData && snap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        snap.data!.snapshot.value as Map,
                      );
                      hoveredIndex = raw['index'] as int?;
                    } catch (_) {}
                  }

                  return Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        GameContentLocalization.format(
                          context,
                          AppLocalizations.of(context)!.mainDeCartes,
                          [targetName, targetHand.length],
                        ),
                        style: TextStyle(
                          color: Colors.white70,
                          fontSize: 13,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      SizedBox(height: 10),
                      Expanded(
                        child: Center(
                          child: SingleChildScrollView(
                            scrollDirection: Axis.horizontal,
                            physics: BouncingScrollPhysics(),
                            child: Row(
                              children:
                                  targetHand.asMap().entries.map((entry) {
                                    final int index = entry.key;
                                    final bool isRemoteHovered =
                                        hoveredIndex == index;
                                    final bool isLocalSelected =
                                        isMyTurn &&
                                        _selectedZombieCardIndex == index;
                                    final bool isHovered =
                                        isRemoteHovered || isLocalSelected;

                                    return _SpookyTargetCardBack(
                                      isMyTurn: isMyTurn,
                                      isHoveredLive: isHovered,
                                      isSelectedLocal: isLocalSelected,
                                      onTap:
                                          isMyTurn && !_isActionPending
                                              ? () async {
                                                if (_selectedZombieCardIndex ==
                                                    index) {
                                                  // 2e clic : Confirmation et vol de la carte
                                                  HapticFeedback.heavyImpact();
                                                  setState(() {
                                                    _isActionPending = true;
                                                    _selectedZombieCardIndex =
                                                        null;
                                                  });
                                                  await _firebaseService
                                                      .updateZombieCardHover(
                                                        widget.gameCode,
                                                        playerId,
                                                        null,
                                                      );
                                                  await _firebaseService
                                                      .zombieTakeCard(
                                                        widget.gameCode,
                                                        playerId,
                                                        index,
                                                      );
                                                  if (mounted) {
                                                    setState(
                                                      () =>
                                                          _isActionPending =
                                                              false,
                                                    );
                                                  }
                                                } else {
                                                  // 1er clic : Ciblage préalable et diffusion live RTDB
                                                  HapticFeedback.selectionClick();
                                                  setState(
                                                    () =>
                                                        _selectedZombieCardIndex =
                                                            index,
                                                  );
                                                  await _firebaseService
                                                      .updateZombieCardHover(
                                                        widget.gameCode,
                                                        playerId,
                                                        index,
                                                      );
                                                }
                                              }
                                              : null,
                                    );
                                  }).toList(),
                            ),
                          ),
                        ),
                      ),
                    ],
                  );
                },
              ),
            ),
          ),

          SizedBox(height: 8),

          // 3. MA MAIN DE CARTES DE SURVIE (SURVIVORS & ZOMBIE)
          Expanded(
            flex: 5,
            child: Container(
              margin: const EdgeInsets.symmetric(horizontal: 10),
              padding: const EdgeInsets.fromLTRB(12, 8, 12, 10),
              decoration: BoxDecoration(
                color: Color(0xFF100918),
                borderRadius: const BorderRadius.vertical(
                  top: Radius.circular(24),
                ),
                border: Border.all(color: Colors.white10),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.6),
                    blurRadius: 16,
                    offset: Offset(0, -4),
                  ),
                ],
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        GameContentLocalization.format(
                          context,
                          AppLocalizations.of(context)!.votreMainDeSurvieCartes,
                          [myHand.length],
                        ),
                        style: TextStyle(
                          color: Colors.white60,
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1.2,
                        ),
                      ),
                      Text(
                        AppLocalizations.of(
                          context,
                        )!.lesPairesSontDefausseesAutomatiquement,
                        style: TextStyle(color: Colors.white30, fontSize: 10),
                      ),
                    ],
                  ),
                  SizedBox(height: 8),
                  Expanded(
                    child: Center(
                      child: SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        physics: BouncingScrollPhysics(),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children:
                              myHand.map((card) {
                                return _ZombieSurvivorCardWidget(card: card);
                              }).toList(),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildBigTwoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerProfiles = Map<String, dynamic>.from(
      gameData['playerProfiles'] ?? {},
    );

    String resolvePlayerName(String pId) {
      final pMap = players[pId] is Map ? players[pId] : null;
      final rawName = pMap?['name'];
      if (rawName != null &&
          rawName.toString().trim().isNotEmpty &&
          rawName != AppLocalizations.of(context)!.inconnu) {
        return rawName.toString();
      }
      final profName =
          playerProfiles[pId] is Map ? playerProfiles[pId]['name'] : null;
      if (profName != null &&
          profName.toString().trim().isNotEmpty &&
          profName != AppLocalizations.of(context)!.inconnu) {
        return profName.toString();
      }
      if (pId == playerId) {
        final authName = FirebaseAuth.instance.currentUser?.displayName;
        if (authName != null && authName.trim().isNotEmpty) return authName;
      }
      return AppLocalizations.of(context)!.joueur;
    }

    final Set<String> allParticipantIds = {};
    allParticipantIds.addAll(players.keys);
    allParticipantIds.addAll(playerProfiles.keys);
    if (gameData['bigTwoPlayerOrder'] is List) {
      allParticipantIds.addAll(
        (gameData['bigTwoPlayerOrder'] as List).map((e) => e.toString()),
      );
    }
    for (String pId in allParticipantIds) {
      if (!players.containsKey(pId) || players[pId] is! Map) {
        players[pId] = {'name': resolvePlayerName(pId), 'score': 0};
      } else if (players[pId]['name'] == null ||
          players[pId]['name'] == AppLocalizations.of(context)!.inconnu) {
        players[pId]['name'] = resolvePlayerName(pId);
      }
    }

    final playerOrder = List<String>.from(gameData['bigTwoPlayerOrder'] ?? []);
    final hands = Map<String, dynamic>.from(
      gameData['bigTwoPlayerHands'] ?? {},
    );
    final myHand = List<String>.from(hands[playerId] ?? []);
    final currentIndex =
        (gameData['bigTwoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
    final currentPlayerId =
        (playerOrder.isNotEmpty && currentIndex < playerOrder.length)
            ? playerOrder[currentIndex]
            : '';
    final isMyTurn = currentPlayerId == playerId;
    final lastPlay =
        gameData['bigTwoLastPlay'] != null
            ? Map<String, dynamic>.from(gameData['bigTwoLastPlay'])
            : null;
    final finishedPlayers = List<String>.from(
      gameData['bigTwoFinishedPlayers'] ?? [],
    );

    if (gameData['gameState'] == 'gameOver') {
      final winnerId = gameData['gameWinner'];
      return UniversalGameEndScreen(
        gameTitle: "Big Two",
        winnerId: winnerId,
        winnerName: resolvePlayerName(winnerId ?? ''),
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.laPartieDeBigTwo,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        // Liste des adversaires retirée pour simplifier l'interface
        Expanded(
          flex: 2,
          child: Container(
            padding: const EdgeInsets.all(16),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                StreamBuilder<DatabaseEvent>(
                  stream: _firebaseService.getBigTwoLiveStream(widget.gameCode),
                  builder: (context, snap) {
                    int liveCount = 0;
                    String? livePlayerId;
                    if (snap.hasData && snap.data!.snapshot.value != null) {
                      try {
                        final raw = Map<String, dynamic>.from(
                          snap.data!.snapshot.value as Map,
                        );
                        livePlayerId = raw['playerId'] as String?;
                        liveCount =
                            (raw['selectedCount'] as num?)?.toInt() ?? 0;
                      } catch (_) {}
                    }

                    final bool showThinking =
                        !isMyTurn &&
                        livePlayerId == currentPlayerId &&
                        liveCount > 0;

                    return Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          isMyTurn
                              ? AppLocalizations.of(context)!.cEstVotreTour
                              : AppLocalizations.of(
                                context,
                              )!.auTourDe2(resolvePlayerName(currentPlayerId)),
                          style: TextStyle(
                            color:
                                isMyTurn ? Colors.greenAccent : Colors.white70,
                            fontWeight: FontWeight.bold,
                            fontSize: 16,
                          ),
                        ),
                        if (showThinking) ...[
                          SizedBox(height: 6),
                          Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 4,
                            ),
                            decoration: BoxDecoration(
                              color: Colors.amber.withOpacity(0.2),
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(
                                color: Colors.amberAccent.withOpacity(0.6),
                              ),
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(
                                  Icons.style,
                                  color: Colors.amberAccent,
                                  size: 14,
                                ),
                                SizedBox(width: 6),
                                Text(
                                  GameContentLocalization.format(
                                    context,
                                    AppLocalizations.of(
                                      context,
                                    )!.aSelectionneCarte,
                                    [
                                      resolvePlayerName(currentPlayerId),
                                      liveCount,
                                      liveCount > 1 ? 's' : '',
                                    ],
                                  ),
                                  style: TextStyle(
                                    color: Colors.amberAccent,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ],
                    );
                  },
                ),
                SizedBox(height: 20),
                if (lastPlay != null) ...[
                  Text(
                    AppLocalizations.of(context)!.carteSEnJeu,
                    style: TextStyle(color: Colors.white54),
                  ),
                  SizedBox(height: 10),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        (lastPlay['cards'] as List)
                            .map((c) => _buildBigTwoCard(c.toString()))
                            .toList(),
                  ),
                  SizedBox(height: 10),
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.jouePar,
                      [resolvePlayerName(lastPlay['playedBy'] ?? '')],
                    ),
                    style: TextStyle(fontSize: 12, color: Colors.white70),
                  ),
                ] else
                  Text(
                    AppLocalizations.of(context)!.aucuneCarteEnJeuJouez,
                    style: TextStyle(color: Colors.amber),
                  ),
              ],
            ),
          ),
        ),
        Expanded(
          flex: 3,
          child: Container(
            padding: EdgeInsets.all(8),
            decoration: BoxDecoration(color: Colors.black.withOpacity(0.3)),
            child: Column(
              children: [
                Expanded(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(
                      children:
                          myHand.map((card) {
                            bool isSelected = _selectedBigTwoCards.contains(
                              card,
                            );
                            return GestureDetector(
                              onTap:
                                  isMyTurn
                                      ? () {
                                        setState(() {
                                          if (isSelected)
                                            _selectedBigTwoCards.remove(card);
                                          else
                                            _selectedBigTwoCards.add(card);
                                        });
                                        _firebaseService
                                            .updateBigTwoLiveSelection(
                                              widget.gameCode,
                                              playerId,
                                              _selectedBigTwoCards.length,
                                            );
                                      }
                                      : null,
                              child: Transform.translate(
                                offset: Offset(0, isSelected ? -20 : 0),
                                child: _buildBigTwoCard(
                                  card,
                                  isSelected: isSelected,
                                ),
                              ),
                            );
                          }).toList(),
                    ),
                  ),
                ),
                if (isMyTurn)
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      ElevatedButton(
                        onPressed: lastPlay != null ? () => bigTwoPass() : null,
                        child: Text(AppLocalizations.of(context)!.passer),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.red,
                        ),
                      ),
                      ElevatedButton(
                        onPressed:
                            _selectedBigTwoCards.isNotEmpty
                                ? () => bigTwoPlay()
                                : null,
                        child: Text(
                          GameContentLocalization.format(
                            context,
                            AppLocalizations.of(context)!.jouer,
                            [_selectedBigTwoCards.length],
                          ),
                        ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.green,
                        ),
                      ),
                    ],
                  ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildBigTwoCard(String card, {bool isSelected = false}) {
    if (card.trim().isEmpty) return const SizedBox.shrink();
    final (rank, suitKey) = FirebaseService.parseBigTwoCard(card);

    final bool isRed = (suitKey == 'H' || suitKey == 'D');
    final Color textColor = isRed ? Color(0xFFE11D48) : Color(0xFF0F172A);

    Widget buildSuitIcon(double size) {
      if (suitKey == 'H') {
        return Icon(Icons.favorite_rounded, size: size, color: textColor);
      } else if (suitKey == 'D') {
        return CustomPaint(
          size: Size(size * 0.85, size * 0.85),
          painter: _BigTwoDiamondPainter(textColor),
        );
      } else if (suitKey == 'C') {
        return CustomPaint(
          size: Size(size, size),
          painter: _BigTwoClubPainter(textColor),
        );
      } else {
        return CustomPaint(
          size: Size(size, size),
          painter: _BigTwoSpadePainter(textColor),
        );
      }
    }

    return Container(
      width: 62,
      height: 94,
      margin: const EdgeInsets.symmetric(horizontal: 4),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: isSelected ? Colors.greenAccent : Color(0xFFCBD5E1),
          width: isSelected ? 3.0 : 1.2,
        ),
        boxShadow: [
          BoxShadow(
            color:
                isSelected
                    ? Colors.greenAccent.withOpacity(0.5)
                    : Colors.black26,
            blurRadius: isSelected ? 8 : 4,
            offset: Offset(1, 3),
          ),
        ],
      ),
      child: Stack(
        children: [
          // Centre : grand rang et symbole vectoriel net
          Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  rank,
                  style: TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.w900,
                    color: textColor,
                    height: 1.0,
                  ),
                ),
                SizedBox(height: 3),
                buildSuitIcon(22),
              ],
            ),
          ),
          // Coin supérieur gauche
          Positioned(
            top: 4,
            left: 5,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  rank,
                  style: TextStyle(
                    fontSize: 11,
                    color: textColor,
                    fontWeight: FontWeight.w900,
                    height: 1.0,
                  ),
                ),
                SizedBox(height: 1),
                buildSuitIcon(10),
              ],
            ),
          ),
          // Coin inférieur droit inversé
          Positioned(
            bottom: 4,
            right: 5,
            child: Transform.rotate(
              angle: 3.14159,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    rank,
                    style: TextStyle(
                      fontSize: 11,
                      color: textColor,
                      fontWeight: FontWeight.w900,
                      height: 1.0,
                    ),
                  ),
                  SizedBox(height: 1),
                  buildSuitIcon(10),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  void bigTwoPlay() async {
    setState(() => _isActionPending = true);
    _firebaseService.updateBigTwoLiveSelection(
      widget.gameCode,
      widget.playerId,
      0,
    );
    try {
      await _firebaseService.bigTwoAction(
        widget.gameCode,
        widget.playerId,
        'play',
        cards: _selectedBigTwoCards,
      );
      setState(() => _selectedBigTwoCards.clear());
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            GameMessageLocalization.tr(
              context,
              e.toString().replaceAll(
                AppLocalizations.of(context)!.exception,
                '',
              ),
            ),
          ),
        ),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  void bigTwoPass() async {
    setState(() => _isActionPending = true);
    _firebaseService.updateBigTwoLiveSelection(
      widget.gameCode,
      widget.playerId,
      0,
    );
    try {
      await _firebaseService.bigTwoAction(
        widget.gameCode,
        widget.playerId,
        'pass',
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            GameMessageLocalization.tr(
              context,
              e.toString().replaceAll(
                AppLocalizations.of(context)!.exception,
                '',
              ),
            ),
          ),
        ),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  // =============================================================================
  // ACTION OU VÉRITÉ - INTERFACE DE JEU EN LIGNE
  // =============================================================================

  Widget _buildActionOuVeriteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    if (gameData['gameState'] == 'gameOver') {
      final winnerId = gameData['gameWinner'];
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final customScores = <String, int>{};
      players.forEach((pId, pData) {
        if (pData is Map) {
          customScores[pId] = (pData['xp'] as num?)?.toInt() ?? 0;
        }
      });

      return UniversalGameEndScreen(
        gameTitle: AppLocalizations.of(context)!.actionOuVerite,
        winnerId: winnerId,
        winnerName: players[winnerId]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.laPartieEstTerminee,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: widget.playerId == gameData['hostId'],
        onExit: () => Navigator.pop(context),
        customScores: customScores,
      );
    }

    return ActionOuVeriteGameView(
      gameData: gameData,
      playerId: playerId,
      gameCode: widget.gameCode,
      firebaseService: _firebaseService,
    );
  }

  Widget _buildCheckersUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, String> board = Map<String, String>.from(
      gameData['checkersBoard'] ?? {},
    );
    final String currentColor = gameData['checkersCurrentColor'] ?? 'red';
    final List<String> playerOrder = List<String>.from(
      gameData['checkersPlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['checkersCurrentPlayerIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final players = gameData['players'] as Map<String, dynamic>;

    // NOUVEAU : Récupérer le pion obligatoire s'il y a une prise multiple en cours
    final String? mandatoryPiece = gameData['checkersMandatoryPiece'];

    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Jeu de Dames",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.plusAucunCoupPossiblePour,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        Container(
          padding: EdgeInsets.all(12),
          color: isMyTurn ? Colors.green.withOpacity(0.2) : Colors.transparent,
          child: Column(
            children: [
              Text(
                isMyTurn
                    ? GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.cEstVotreTour1,
                      [
                        currentColor == 'red'
                            ? AppLocalizations.of(context)!.rouges
                            : AppLocalizations.of(context)!.noirs,
                      ],
                    )
                    : GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.auTourDe,
                      [players[currentPlayerId]?['name'] ?? '...'],
                    ),
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: isMyTurn ? Colors.greenAccent : Colors.white,
                ),
              ),
              if (isMyTurn && mandatoryPiece != null)
                Padding(
                  padding: const EdgeInsets.only(top: 8.0),
                  child: Text(
                    AppLocalizations.of(context)!.priseEnChaineVousDevez,
                    style: TextStyle(
                      color: Colors.orangeAccent,
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getCheckersLiveStream(widget.gameCode),
                builder: (context, liveSnap) {
                  String? liveSelected;
                  if (!isMyTurn &&
                      liveSnap.hasData &&
                      liveSnap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        liveSnap.data!.snapshot.value as Map,
                      );
                      liveSelected = raw['fromKey'] as String?;
                    } catch (_) {}
                  }
                  if (liveSelected != null) {
                    return Padding(
                      padding: const EdgeInsets.only(top: 6.0),
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color: Colors.amber.withOpacity(0.2),
                          borderRadius: BorderRadius.circular(12),
                          border: Border.all(
                            color: Colors.amberAccent.withOpacity(0.5),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(
                              Icons.touch_app,
                              color: Colors.amberAccent,
                              size: 14,
                            ),
                            SizedBox(width: 6),
                            Text(
                              AppLocalizations.of(
                                context,
                              )!.aSelectionneSonPionEt1(
                                players[currentPlayerId]?['name'] ??
                                    AppLocalizations.of(context)!.lAdversaire,
                              ),
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  }
                  return const SizedBox.shrink();
                },
              ),
            ],
          ),
        ),
        Expanded(
          child: AspectRatio(
            aspectRatio: 1.0,
            child: Container(
              margin: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                border: Border.all(color: Colors.brown[900]!, width: 6),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black45,
                    blurRadius: 10,
                    offset: Offset(0, 5),
                  ),
                ],
              ),
              child: StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getCheckersLiveStream(widget.gameCode),
                builder: (context, liveSnap) {
                  String? liveSelectedPiece = _selectedCheckersPiece;
                  if (!isMyTurn &&
                      liveSnap.hasData &&
                      liveSnap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        liveSnap.data!.snapshot.value as Map,
                      );
                      liveSelectedPiece = raw['fromKey'] as String?;
                    } catch (_) {}
                  }

                  return GridView.builder(
                    physics: NeverScrollableScrollPhysics(),
                    gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 8,
                    ),
                    itemCount: 64,
                    itemBuilder: (context, index) {
                      int r = index ~/ 8;
                      int c = index % 8;
                      bool isDark = (r + c) % 2 != 0;
                      String key = "$r,$c";
                      String? piece = board[key];

                      bool isSelected = key == liveSelectedPiece;
                      bool isMandatory = key == mandatoryPiece;
                      Color bgColor =
                          isDark ? Colors.brown[700]! : Color(0xFFF5F5DC);

                      return GestureDetector(
                        onTap:
                            isMyTurn && isDark
                                ? () {
                                  if (_selectedCheckersPiece == null) {
                                    if (piece != null &&
                                        piece.startsWith(currentColor)) {
                                      if (mandatoryPiece != null &&
                                          key != mandatoryPiece) {
                                        ScaffoldMessenger.of(
                                          context,
                                        ).showSnackBar(
                                          SnackBar(
                                            content: Text(
                                              AppLocalizations.of(
                                                context,
                                              )!.vousDevezSelectionnerLePion,
                                            ),
                                            duration: Duration(seconds: 2),
                                          ),
                                        );
                                        return;
                                      }
                                      setState(
                                        () => _selectedCheckersPiece = key,
                                      );
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            key,
                                          );
                                    }
                                  } else {
                                    if (key == _selectedCheckersPiece) {
                                      setState(
                                        () => _selectedCheckersPiece = null,
                                      );
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            null,
                                          );
                                    } else {
                                      List<int> from =
                                          _selectedCheckersPiece!
                                              .split(',')
                                              .map(int.parse)
                                              .toList();
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            null,
                                          );
                                      _firebaseService
                                          .checkersMove(
                                            widget.gameCode,
                                            playerId,
                                            from[0],
                                            from[1],
                                            r,
                                            c,
                                          )
                                          .then((_) {
                                            setState(
                                              () =>
                                                  _selectedCheckersPiece = null,
                                            );
                                          })
                                          .catchError((e) {
                                            setState(
                                              () =>
                                                  _selectedCheckersPiece = null,
                                            );
                                          });
                                    }
                                  }
                                }
                                : null,
                        child: Container(
                          color: bgColor,
                          child:
                              piece != null
                                  ? Center(
                                    child: AnimatedContainer(
                                      duration: Duration(milliseconds: 200),
                                      width: 35,
                                      height: 35,
                                      decoration: BoxDecoration(
                                        shape: BoxShape.circle,
                                        color:
                                            piece.startsWith('red')
                                                ? Colors.red[800]!
                                                : Colors.black87,
                                        border: Border.all(
                                          color:
                                              isSelected
                                                  ? (isMyTurn
                                                      ? Colors.greenAccent
                                                      : Colors.amberAccent)
                                                  : (isMandatory
                                                      ? Colors.orangeAccent
                                                      : Colors.white),
                                          width:
                                              (isSelected || isMandatory)
                                                  ? 3.5
                                                  : 2,
                                        ),
                                        boxShadow:
                                            (isSelected || isMandatory)
                                                ? [
                                                  BoxShadow(
                                                    color:
                                                        isMandatory
                                                            ? Colors.orange
                                                            : (isMyTurn
                                                                ? Colors
                                                                    .greenAccent
                                                                : Colors
                                                                    .amberAccent),
                                                    blurRadius: 10,
                                                    spreadRadius: 3,
                                                  ),
                                                ]
                                                : null,
                                      ),
                                      child:
                                          piece.endsWith('_king')
                                              ? Icon(
                                                Icons.star,
                                                color: Colors.amber,
                                                size: 20,
                                              )
                                              : null,
                                    ),
                                  )
                                  : null,
                        ),
                      );
                    },
                  );
                },
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildGameContent(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String rawGameType = gameData['gameType'] ?? '';

    // Normalisation UTF-8 pour éviter les erreurs d'accentuation ("non implémenté")
    final String gameType = rawGameType
        .replaceAll('é', 'é')
        .replaceAll('é', 'é')
        .replaceAll('è', 'è')
        .replaceAll('è', 'è')
        .replaceAll('ê', 'ê')
        .replaceAll('ê', 'ê')
        .replaceAll('ô', 'ô')
        .replaceAll('ô', 'ô')
        .replaceAll('û', 'û')
        .replaceAll('û', 'û');

    switch (gameType) {
      case 'Action ou Vérité':
        return _buildActionOuVeriteUI(context, gameData, playerId);
      case 'Jeu de Dames':
        return _buildCheckersUI(context, gameData, playerId);
      case 'Big Two':
        return _buildBigTwoUI(context, gameData, playerId);
      case 'Zombie!':
        return _buildZombieUI(context, gameData, playerId);
      case 'Blokus':
        return _buildBlokusUI(context, gameData, playerId);
      case 'Petits Chevaux':
        return _buildPetitsChevauxUI(context, gameData, playerId);
      case 'Cadavre Exquis':
        return _buildCadavreExquisUI(context, gameData, playerId);
      case 'Bataille Navale':
        return _buildBatailleNavaleUI(context, gameData, playerId);
      case 'Mille Bornes':
        return _buildMilleBornesUI(context, gameData, playerId);
      case 'Rami':
        return _buildRamiUI(context, gameData, playerId);
      case 'Belote':
        return _buildBeloteUI(context, gameData, playerId);
      case 'Yams':
        return _buildYamsUI(context, gameData, playerId);
      case 'Devine Tête':
        return _buildDevineTeteMultiUI(context, gameData, playerId);
      case 'Infiltré & Mr. White':
        return _buildUndercoverGameUI(context, gameData, playerId);
      case 'Photo Roulette':
        return _buildPhotoRouletteUI(context, gameData, playerId);
      case 'Zéro Pointé':
        return _buildZeroPointeUI(context, gameData, playerId);
      case 'Gribouillis':
        return _buildGribouillisUI(context, gameData, playerId);
      case 'Taboo':
        return _buildTabooUI(context, gameData, playerId);
      case 'Poker':
        return _buildPokerUI(context, gameData, playerId);
      case 'Uno':
        return _buildUnoUI(context, gameData, playerId);
      case 'Dobble':
        return _buildDobbleUI(context, gameData, playerId);
      case 'Codenames':
        return _buildCodenamesUI(context, gameData, playerId);
      case "Time's Up":
        return _buildTimesUpUI(context, gameData, playerId);
      case 'Petit Bac':
        return _buildPetitBacUI(context, gameData, playerId);
      case 'Président':
        return _buildPresidentUI(context, gameData, playerId);
      case 'Skull':
        return _buildSkullUI(context, gameData, playerId);
      case 'Pictionary':
        return _buildPictionaryUI(context, gameData, playerId);
      case 'Just One':
        return _buildJustOneUI(context, gameData, playerId);
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return _buildHotPotatoUI(context, gameData, playerId);
      case 'Loup-Garou':
        return _buildLoupGarouUI(context, gameData, playerId);
      case 'Dominoes':
        return _buildDominoesUI(context, gameData, playerId);
      case 'Blanc Manger Coco':
        return _buildBlancMangerCocoUI(context, gameData, playerId);
      case 'Qui Pourrait le Plus ?':
      case 'Le Juge':
      case 'Le Menteur':
      case 'Le Roi des Mèmes':
      case 'Le Roi des Mêmes':
      case 'Synonyme ou Banni':
        return _getWidgetForRoundState(context, gameData, playerId);
      default:
        return Center(
          child: Text(
            AppLocalizations.of(
              context,
            )!.jeuNonImplemente.replaceAll("{0}", rawGameType.toString()),
          ),
        );
    }
  }

  Widget _buildDevineTeteMultiUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'playing_turn';
    final String currentGuesserId = gameData['currentGuesserId'] ?? '';
    final String currentWord = gameData['currentWord'] ?? '...';
    final int guessedCount = gameData['guessedCount'] ?? 0;
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isMyTurn = playerId == currentGuesserId;
    final String guesserName =
        players[currentGuesserId]?['name'] ??
        AppLocalizations.of(context)!.unJoueur;

    final bool useTeams = gameData['devineTeteUseTeams'] == true;
    final String activeTeam = gameData['activeTeam'] ?? 'teamA';
    final Map<String, dynamic> teamScores =
        gameData['teamScores'] ?? {'teamA': 0, 'teamB': 0};

    bool isMyTeamTurn = false;
    if (useTeams) {
      List<String> teamList = List<String>.from(
        gameData['teams']?[activeTeam] ?? [],
      );
      isMyTeamTurn = teamList.contains(playerId);
    }

    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: AppLocalizations.of(context)!.devineTete,
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.finDeLaPartie,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    // Fin du chrono de 60s pour ce joueur : annonce et passage au suivant
    if (roundState == 'turn_result') {
      return Center(
        child: Container(
          margin: const EdgeInsets.all(24),
          padding: const EdgeInsets.all(24),
          decoration: BoxDecoration(
            color: Color(0xFF1E1B4B),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(
              color: Colors.amberAccent.withOpacity(0.6),
              width: 2,
            ),
            boxShadow: [
              BoxShadow(color: Colors.black.withOpacity(0.5), blurRadius: 16),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.timer_off_rounded,
                size: 54,
                color: Colors.amberAccent,
              ),
              SizedBox(height: 14),
              Text(
                AppLocalizations.of(context)!.tempsEcoule,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
              ),
              SizedBox(height: 8),
              Text(
                AppLocalizations.of(
                  context,
                )!.dtGuessedWords(guesserName, '$guessedCount'),
                style: TextStyle(
                  fontSize: 20,
                  color: Colors.greenAccent,
                  fontWeight: FontWeight.bold,
                ),
              ),
              SizedBox(height: 24),
              if (gameData['hostId'] == playerId)
                ElevatedButton.icon(
                  icon: Icon(Icons.arrow_forward_rounded),
                  label: Text(AppLocalizations.of(context)!.tourSuivant),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.green[700],
                    padding: const EdgeInsets.symmetric(
                      horizontal: 24,
                      vertical: 12,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .nextDevineTeteTurn(widget.gameCode)
                                .then((_) {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                )
              else
                Text(
                  AppLocalizations.of(context)!.enAttenteDeLHote3,
                  style: TextStyle(
                    color: Colors.white54,
                    fontStyle: FontStyle.italic,
                  ),
                ),
            ],
          ),
        ),
      );
    }

    // Phase de jeu active
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (useTeams)
          Padding(
            padding: const EdgeInsets.only(bottom: 12.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        activeTeam == 'teamA'
                            ? Colors.redAccent.withOpacity(0.3)
                            : Colors.black26,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color:
                          activeTeam == 'teamA'
                              ? Colors.redAccent
                              : Colors.white12,
                    ),
                  ),
                  child: Text(
                    AppLocalizations.of(context)!.equipeAPts,
                    style: TextStyle(
                      color:
                          activeTeam == 'teamA'
                              ? Colors.redAccent
                              : Colors.white70,
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                    ),
                  ),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        activeTeam == 'teamB'
                            ? Colors.blueAccent.withOpacity(0.3)
                            : Colors.black26,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color:
                          activeTeam == 'teamB'
                              ? Colors.blueAccent
                              : Colors.white12,
                    ),
                  ),
                  child: Text(
                    AppLocalizations.of(context)!.equipeBPts,
                    style: TextStyle(
                      color:
                          activeTeam == 'teamB'
                              ? Colors.blueAccent
                              : Colors.white70,
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                    ),
                  ),
                ),
              ],
            ),
          ),

        if (isMyTurn) ...[
          Text(
            AppLocalizations.of(context)!.cEstAToiDe,
            style: TextStyle(
              color: Colors.greenAccent,
              fontSize: 22,
              fontWeight: FontWeight.w900,
            ),
          ),
          SizedBox(height: 4),
          Text(
            useTeams
                ? AppLocalizations.of(context)!.ecoutezLesIndicesDeVotre
                : AppLocalizations.of(context)!.regardezVosAmisAL,
            style: TextStyle(color: Colors.white70, fontSize: 13),
            textAlign: TextAlign.center,
          ),
          Spacer(),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Color(0xFFEA580C),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 14,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                onPressed: () {
                  HapticFeedback.lightImpact();
                  _firebaseService.actionDevineTete(
                    widget.gameCode,
                    playerId,
                    false, // Passer -> mot suivant immédiat
                  );
                },
                icon: Icon(Icons.skip_next_rounded, size: 24),
                label: Text(
                  AppLocalizations.of(context)!.passer1,
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
              ),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Color(0xFF16A34A),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 28,
                    vertical: 14,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  elevation: 6,
                ),
                onPressed: () {
                  HapticFeedback.mediumImpact();
                  _firebaseService.actionDevineTete(
                    widget.gameCode,
                    playerId,
                    true, // Trouvé -> mot suivant immédiat
                  );
                },
                icon: Icon(Icons.check_circle_rounded, size: 24),
                label: Text(
                  AppLocalizations.of(context)!.trouve,
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
              ),
            ],
          ),
          SizedBox(height: 12),
        ] else ...[
          Text(
            useTeams && !isMyTeamTurn
                ? AppLocalizations.of(context)!.lEquipeAdverseJoueSurveillez
                : AppLocalizations.of(context)!.dtMakeGuessWordTo(guesserName),
            style: TextStyle(
              color:
                  (useTeams && !isMyTeamTurn)
                      ? Colors.orangeAccent
                      : Colors.amberAccent,
              fontSize: 15,
              fontWeight: FontWeight.bold,
            ),
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 10),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 24, horizontal: 16),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(24),
              boxShadow: [
                BoxShadow(
                  color: Colors.amberAccent.withOpacity(0.3),
                  blurRadius: 20,
                  spreadRadius: 2,
                ),
              ],
            ),
            child: Text(
              currentWord.toUpperCase(),
              style: TextStyle(
                color: Colors.deepPurple[900],
                fontSize: 32,
                fontWeight: FontWeight.w900,
                letterSpacing: 1.2,
              ),
              textAlign: TextAlign.center,
            ),
          ),
          Spacer(),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
            decoration: BoxDecoration(
              color: Colors.green.withOpacity(0.2),
              borderRadius: BorderRadius.circular(16),
            ),
            child: Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.motsTrouves,
                [guessedCount],
              ),
              style: TextStyle(
                color: Colors.greenAccent,
                fontSize: 16,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          SizedBox(height: 12),
        ],
      ],
    );
  }

  // ===========================================================================
  // 📜 CADAVRE EXQUIS (FEUILLE PLIÉE EN ACCORDÉON & ENCRE MANUSCRITE)
  // ===========================================================================
  Widget _buildCadavreExquisUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    final variant = gameData['cadavreVariant'] ?? 'classic';
    final passingMode = gameData['cadavrePassingMode'] ?? 'single';
    final currentRound = gameData['currentRound'] ?? 0;
    final currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    final totalSteps = gameData['totalStepsPerPaper'] ?? 5;
    final papers = Map<String, dynamic>.from(gameData['papers'] ?? {});

    final isMyTurn =
        playerOrder.isNotEmpty && playerOrder[currentPlayerIndex] == playerId;
    final currentPlayerName =
        playerOrder.isNotEmpty
            ? (players[playerOrder[currentPlayerIndex]]?['name'] ??
                AppLocalizations.of(context)!.unJoueur)
            : '...';

    // --- 1. ÉCRAN DES RÉSULTATS / DÉPLIAGE DU PARCHEMIN ---
    if (roundState == 'results' || gameData['gameState'] == 'gameOver') {
      return _buildCadavreExquisResults(context, papers, players, passingMode);
    }

    // Récupération de la feuille courante
    int paperIndex =
        passingMode == 'single'
            ? 0
            : (((currentPlayerIndex -
                    (currentRound % playerOrder.length) +
                    playerOrder.length) %
                playerOrder.length));
    Map<String, dynamic> currentPaper = Map<String, dynamic>.from(
      papers[paperIndex.toString()] ?? {'steps': []},
    );
    List<dynamic> steps = currentPaper['steps'] ?? [];

    String grammaticalPrompt = "";
    String peekingSnippet = "";
    String previousAuthorName = "";

    if (variant == 'classic') {
      int stepIndex = passingMode == 'single' ? steps.length : currentRound;
      final promptItem =
          stepIndex < GameData.cadavreExquisPrompts.length
              ? GameData.cadavreExquisPrompts[stepIndex]
              : AppLocalizations.of(context)!.laSuiteDeLHistoire;
      grammaticalPrompt = AppLocalizations.of(context)!.ecrivez(promptItem);
    } else {
      grammaticalPrompt = AppLocalizations.of(context)!.completezLaPhrase1A;
      if (steps.isNotEmpty) {
        final lastStep = steps.last;
        String lastText = (lastStep['text'] ?? '').toString().trim();
        previousAuthorName =
            players[lastStep['authorId']]?['name'] ??
            AppLocalizations.of(context)!.auteurPrecedent;
        List<String> words = lastText.split(' ');
        peekingSnippet =
            words.length <= 3
                ? lastText
                : words.sublist(words.length - 3).join(' ');
      }
    }

    return Container(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.topCenter,
          radius: 1.2,
          colors: [Color(0xFF2C2219), Color(0xFF140F0A), Color(0xFF070503)],
        ),
      ),
      child: Column(
        children: [
          // BANDEAU SUPÉRIEUR : ÉTAT DU TOUR & PROGRESSION
          Container(
            margin: const EdgeInsets.fromLTRB(12, 4, 12, 8),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color: Color(0xFF241A12).withOpacity(0.9),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: isMyTurn ? Color(0xFFE0A96D) : Colors.white12,
                width: isMyTurn ? 1.5 : 1,
              ),
              boxShadow: [
                if (isMyTurn)
                  BoxShadow(
                    color: Color(0xFFE0A96D).withOpacity(0.2),
                    blurRadius: 10,
                  ),
              ],
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(6),
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color:
                            isMyTurn
                                ? Color(0xFFE0A96D).withOpacity(0.2)
                                : Colors.white10,
                      ),
                      child: Icon(
                        Icons.history_edu_rounded,
                        size: 16,
                        color: isMyTurn ? Color(0xFFF3C68F) : Colors.white60,
                      ),
                    ),
                    SizedBox(width: 8),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          isMyTurn
                              ? AppLocalizations.of(context)!.aVousDEcrire
                              : AppLocalizations.of(
                                context,
                              )!.ceTurnOfPlayer(currentPlayerName),
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1,
                            color:
                                isMyTurn ? Color(0xFFF3C68F) : Colors.white70,
                          ),
                        ),
                        Text(
                          variant == 'classic'
                              ? AppLocalizations.of(
                                context,
                              )!.surrealismeClassique
                              : AppLocalizations.of(context)!.suiteDe3Mots,
                          style: TextStyle(fontSize: 10, color: Colors.white38),
                        ),
                      ],
                    ),
                  ],
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.black45,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: Colors.white10),
                  ),
                  child: Text(
                    AppLocalizations.of(
                      context,
                    )!.ceStepOfTotal('${currentRound + 1}', '$totalSteps'),
                    style: TextStyle(
                      color: Color(0xFFE0A96D),
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ],
            ),
          ),

          // FEUILLE DE PAPIER ACCORDÉON
          Expanded(
            child: Center(
              child: SingleChildScrollView(
                physics: BouncingScrollPhysics(),
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 4,
                ),
                child:
                    isMyTurn
                        ? _buildAccordionPaperActive(
                          context,
                          grammaticalPrompt: grammaticalPrompt,
                          peekingSnippet: peekingSnippet,
                          previousAuthorName: previousAuthorName,
                          variant: variant,
                          playerId: playerId,
                        )
                        : _buildAccordionPaperSpectator(
                          context,
                          currentPlayerName: currentPlayerName,
                          totalSteps: totalSteps,
                          currentRound: currentRound,
                        ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // --- FEUILLE ACCORDÉON ACTIVE (AVEC LANGUETTE PRÉCÉDENTE ET LIGNES) ---
