        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.6),
            blurRadius: 20,
            offset: Offset(0, 8),
          ),
        ],
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // 1. PLI SUPÉRIEUR : LANGUETTE DU MORCEAU PRÉCÉDENT
            if (peekingSnippet.isNotEmpty) ...[
              Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 12,
                ),
                decoration: BoxDecoration(
                  color: Color(0xFFEFE6D5),
                  border: Border(
                    bottom: BorderSide(color: Color(0xFFD6C8B2), width: 1.5),
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black12,
                      offset: Offset(0, 3),
                      blurRadius: 4,
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Icon(
                          Icons.bookmark_border_rounded,
                          size: 14,
                          color: Color(0xFF8C7355),
                        ),
                        SizedBox(width: 4),
                        Text(
                          AppLocalizations.of(
                            context,
                          )!.ceVisibleSnippetOf(previousAuthorName),
                          style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.bold,
                            color: Color(0xFF8C7355),
                            letterSpacing: 0.5,
                          ),
                        ),
                      ],
                    ),
                    SizedBox(height: 4),
                    Text(
                      "... $peekingSnippet",
                      style: TextStyle(
                        fontFamily: 'serif',
                        fontStyle: FontStyle.italic,
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Color(0xFF1E293B),
                      ),
                    ),
                  ],
                ),
              ),
              // Ombre de pliure accordéon
              Container(
                height: 6,
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [
                      Colors.black.withOpacity(0.18),
                      Colors.transparent,
                    ],
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                  ),
                ),
              ),
            ] else ...[
              // Première ligne / Pli vierge
              Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 8,
                ),
                color: Color(0xFFEFE6D5),
                child: Row(
                  children: [
                    Icon(
                      Icons.edit_note_rounded,
                      size: 16,
                      color: Color(0xFF8C7355),
                    ),
                    SizedBox(width: 6),
                    Text(
                      AppLocalizations.of(context)!.premiereLigneDuManuscrit,
                      style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.bold,
                        color: Color(0xFF8C7355),
                        letterSpacing: 1,
                      ),
                    ),
                  ],
                ),
              ),
            ],

            // 2. ZONE DE RÉDACTION LIGNÉE (STYLE CAHIER D'ÉCOLIER / PARCHEMIN)
            CustomPaint(
              painter: _LinedParchmentPainter(),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(28, 20, 20, 20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Badge de consigne grammaticale
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color: Color(0xFF78350F).withOpacity(0.12),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                          color: Color(0xFF78350F).withOpacity(0.3),
                        ),
                      ),
                      child: Text(
                        grammaticalPrompt.toUpperCase(),
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF78350F),
                          letterSpacing: 0.8,
                        ),
                      ),
                    ),
                    SizedBox(height: 14),

                    // Champ de texte à encre bleue/noire sur les lignes
                    TextField(
                      controller: _answerController,
                      autofocus: true,
                      onChanged: (text) {
                        int wordCount =
                            text.trim().isEmpty
                                ? 0
                                : text.trim().split(RegExp(r'\s+')).length;
                        _firebaseService.updateCadavreTypingCount(
                          widget.gameCode,
                          playerId,
                          wordCount,
                        );
                      },
                      style: TextStyle(
                        fontFamily: 'serif',
                        fontSize: 20,
                        fontWeight: FontWeight.w600,
                        color: Color(0xFF0F172A), // Encre profonde
                        height: 1.5,
                      ),
                      cursorColor: Color(0xFF78350F),
                      decoration: InputDecoration(
                        hintText: AppLocalizations.of(context)!.ecrivezIci,
                        hintStyle: TextStyle(
                          color: Colors.black26,
                          fontStyle: FontStyle.italic,
                          fontFamily: 'serif',
                        ),
                        border: InputBorder.none,
                        focusedBorder: InputBorder.none,
                        enabledBorder: InputBorder.none,
                        contentPadding: EdgeInsets.zero,
                      ),
                      maxLines: 2,
                      maxLength: variant == 'continuation' ? 60 : 35,
                    ),

                    SizedBox(height: 10),

                    // Bouton de validation type "Pliage & Sceau de cire"
                    Align(
                      alignment: Alignment.centerRight,
                      child: ElevatedButton.icon(
                        icon: Icon(Icons.send_rounded, size: 16),
                        label: Text(
                          AppLocalizations.of(context)!.plierPasser,
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            fontSize: 13,
                            letterSpacing: 0.8,
                          ),
                        ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Color(
                            0xFF881337,
                          ), // Rouge bordeaux / Sceau
                          foregroundColor: Colors.white,
                          elevation: 4,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 18,
                            vertical: 12,
                          ),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(14),
                          ),
                        ),
                        onPressed: () {
                          if (_answerController.text.trim().isNotEmpty) {
                            HapticFeedback.mediumImpact();
                            _firebaseService.submitCadavreExquisStep(
                              widget.gameCode,
                              playerId,
                              _answerController.text.trim(),
                            );
                            _firebaseService.updateCadavreTypingCount(
                              widget.gameCode,
                              playerId,
                              0,
                            );
                            _answerController.clear();
                          }
                        },
                      ),
                    ),
                  ],
                ),
              ),
            ),

            // 3. PLI INFÉRIEUR OMBRÉ (BAS DE LA FEUILLE PLIÉE)
            Container(
              height: 14,
              decoration: BoxDecoration(
                color: Color(0xFFEAE0CF),
                border: Border(top: BorderSide(color: Color(0xFFD6C8B2))),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // --- FEUILLE ACCORDÉON SPECTATEUR (EN ATTENTE) ---
  Widget _buildAccordionPaperSpectator(
    BuildContext context, {
    required String currentPlayerName,
    required int totalSteps,
    required int currentRound,
  }) {
    return Container(
      width: double.infinity,
      constraints: BoxConstraints(maxWidth: 360),
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        color: Color(0xFF1E1610),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: Color(0xFFE0A96D).withOpacity(0.3)),
      ),
      child: StreamBuilder<DatabaseEvent>(
        stream: _firebaseService.getCadavreTypingStream(widget.gameCode),
        builder: (context, snap) {
          int count = 0;
          if (snap.hasData && snap.data!.snapshot.value != null) {
            try {
              final raw = Map<String, dynamic>.from(
                snap.data!.snapshot.value as Map,
              );
              count = raw['wordCount'] as int? ?? 0;
            } catch (_) {}
          }

          return Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.history_edu_rounded,
                size: 54,
                color: Color(0xFFE0A96D),
              ),
              SizedBox(height: 14),
              Text(
                AppLocalizations.of(
                  context,
                )!.cePlayerWriting(currentPlayerName),
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 8),
              if (count > 0)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 4,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.amber.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: Colors.amberAccent.withOpacity(0.5),
                    ),
                  ),
                  child: Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.motsRediges,
                      [count],
                    ),
                    style: TextStyle(
                      color: Colors.amberAccent,
                      fontWeight: FontWeight.bold,
                      fontSize: 13,
                    ),
                  ),
                )
              else
                Text(
                  AppLocalizations.of(context)!.laFeuilleEstPlieePour,
                  style: TextStyle(color: Colors.white60, fontSize: 12),
                  textAlign: TextAlign.center,
                ),
              SizedBox(height: 20),
              CircularProgressIndicator(
                color: Color(0xFFE0A96D),
                strokeWidth: 2.5,
              ),
            ],
          );
        },
      ),
    );
  }

  // --- DÉPLIAGE COMPLET DES PARCHEMINS AUX RÉSULTATS ---
  Widget _buildCadavreExquisResults(
    BuildContext context,
    Map<String, dynamic> papers,
    Map<String, dynamic> players,
    String passingMode,
  ) {
    return SingleChildScrollView(
      physics: BouncingScrollPhysics(),
      padding: const EdgeInsets.all(16),
      child: Column(
        children: [
          Icon(Icons.auto_stories_rounded, size: 54, color: Color(0xFFE0A96D)),
          SizedBox(height: 8),
          Text(
            AppLocalizations.of(context)!.leGrandDepliage,
            style: TextStyle(
              fontSize: 24,
              fontWeight: FontWeight.w900,
              color: Colors.white,
              letterSpacing: 1,
            ),
          ),
          SizedBox(height: 4),
          Text(
            AppLocalizations.of(context)!.voiciLesUvresCollectivesNees,
            style: TextStyle(color: Colors.white60, fontSize: 13),
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 16),

          ...papers.entries.map((entry) {
            int paperIndex = int.parse(entry.key);
            List<dynamic> steps = entry.value['steps'] ?? [];
            String fullText = steps.map((s) => s['text']).join(' ');

            return Container(
              margin: const EdgeInsets.only(bottom: 20),
              decoration: BoxDecoration(
                color: Color(0xFFFDFBF7),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: Color(0xFFD8C7B0), width: 1.5),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.4),
                    blurRadius: 14,
                    offset: Offset(0, 6),
                  ),
                ],
              ),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    // En-tête Parchemin
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 10,
                      ),
                      color: Color(0xFFEFE6D5),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            passingMode == 'multiple'
                                ? AppLocalizations.of(
                                  context,
                                )!.ceStoryNumber('${paperIndex + 1}')
                                : AppLocalizations.of(
                                  context,
                                )!.histoireCollective,
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.bold,
                              letterSpacing: 1.5,
                              color: Color(0xFF78350F),
                            ),
                          ),
                          Icon(
                            Icons.bookmark_added_rounded,
                            size: 16,
                            color: Color(0xFF78350F),
                          ),
                        ],
                      ),
                    ),

                    // Texte complet style roman
                    Padding(
                      padding: const EdgeInsets.all(20),
                      child: Text(
                        AppLocalizations.of(context)!.strb74c15(fullText),
                        style: TextStyle(
                          fontFamily: 'serif',
                          fontSize: 20,
                          fontWeight: FontWeight.bold,
                          color: Color(0xFF0F172A),
                          height: 1.4,
                        ),
                        textAlign: TextAlign.center,
                      ),
                    ),

                    Divider(color: Color(0xFFE2D6C3), height: 1),

                    // Signatures des co-auteurs
                    Container(
                      padding: const EdgeInsets.all(12),
                      color: Color(0xFFF7F2E7),
                      child: Wrap(
                        spacing: 6,
                        runSpacing: 6,
                        alignment: WrapAlignment.center,
                        children:
                            steps.map((s) {
                              String authorName =
                                  players[s['authorId']]?['name'] ??
                                  AppLocalizations.of(context)!.auteur;
                              return Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 8,
                                  vertical: 4,
                                ),
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(8),
                                  border: Border.all(color: Color(0xFFD6C8B2)),
                                ),
                                child: RichText(
                                  text: TextSpan(
                                    style: TextStyle(
                                      fontSize: 11,
                                      color: Colors.black87,
                                    ),
                                    children: [
                                      TextSpan(
                                        text: AppLocalizations.of(
                                          context,
                                        )!.str1e0607(authorName),
                                        style: TextStyle(
                                          fontWeight: FontWeight.bold,
                                          color: Color(0xFF78350F),
                                        ),
                                      ),
                                      TextSpan(
                                        text: s['text'],
                                        style: TextStyle(
                                          fontStyle: FontStyle.italic,
