  // --- HELPER D'INFORMATIONS ET DESIGN DES CARTES ---
  _MilleBornesCardInfo _getMilleBornesCardInfo(String card) {
    if (card.startsWith('D')) {
      final km = card.substring(1);
      IconData distIcon;
      Color cardColor;
      Color darkColor;

      switch (km) {
        case '25':
          distIcon = Icons.slow_motion_video_rounded;
          cardColor = Color(0xFF38BDF8); // Cyan doux
          darkColor = Color(0xFF0369A1);
          break;
        case '50':
          distIcon = Icons.electric_car_rounded;
          cardColor = Color(0xFF34D399); // Vert menthe
          darkColor = Color(0xFF047857);
          break;
        case '75':
          distIcon = Icons.directions_car_filled_rounded;
          cardColor = Color(0xFF4ADE80); // Vert printemps
          darkColor = Color(0xFF15803D);
          break;
        case '100':
          distIcon = Icons.speed_rounded;
          cardColor = Color(0xFFA3E635); // Vert lime
          darkColor = Color(0xFF4D7C0F);
          break;
        case '200':
        default:
          distIcon = Icons.rocket_launch_rounded;
          cardColor = Color(0xFFFACC15); // Or / Turbo
          darkColor = Color(0xFFA16207);
          break;
      }

      return _MilleBornesCardInfo(
        name: km,
        category: AppLocalizations.of(context)!.distance,
        badgeText: "$km KM",
        icon: distIcon,
        primaryColor: cardColor,
        secondaryColor: darkColor,
        isDistance: true,
      );
    }

    switch (card) {
      // 🛡️ BOTTES (Sécurités permanentes)
      case 'SAFETY_RIGHT_OF_WAY':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.vehiculeNprioritaire,
          category: AppLocalizations.of(context)!.botte,
          badgeText: AppLocalizations.of(context)!.priorite,
          icon: Icons.emergency_rounded,
          primaryColor: Color(0xFFFFD700),
          secondaryColor: Color(0xFFB45309),
          isSafety: true,
        );
      case 'SAFETY_REPAIRS':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.pneuIncrevable,
          category: AppLocalizations.of(context)!.botte,
          badgeText: AppLocalizations.of(context)!.increvable,
          icon: Icons.verified_rounded,
          primaryColor: Color(0xFFFFD700),
          secondaryColor: Color(0xFFB45309),
          isSafety: true,
        );
      case 'SAFETY_EXTRA_TANK':
      case 'SAFETY_EMERGENCY':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.citerneNinepuisable,
          category: AppLocalizations.of(context)!.botte,
          badgeText: AppLocalizations.of(context)!.citerne,
          icon: Icons.local_gas_station_rounded,
          primaryColor: Color(0xFFFFD700),
          secondaryColor: Color(0xFFB45309),
          isSafety: true,
        );

      // ⚠️ ATTAQUES
      case 'STOP':
      case 'RED_LIGHT':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.feuRouge,
          category: AppLocalizations.of(context)!.attaque,
          badgeText: AppLocalizations.of(context)!.stop,
          icon: Icons.traffic_rounded,
          primaryColor: Color(0xFFEF4444),
          secondaryColor: Color(0xFF991B1B),
        );
      case 'SPEED_LIMIT':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.limite501,
          category: AppLocalizations.of(context)!.attaque,
          badgeText: AppLocalizations.of(context)!.k50Max,
          icon: Icons.speed_rounded,
          primaryColor: Color(0xFFFB923C),
          secondaryColor: Color(0xFFC2410C),
        );
      case 'OUT_OF_GAS':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.panneDEssence,
          category: AppLocalizations.of(context)!.attaque,
          badgeText: AppLocalizations.of(context)!.vide1,
          icon: Icons.no_crash_rounded,
          primaryColor: Color(0xFFF43F5E),
          secondaryColor: Color(0xFF9F1239),
        );
      case 'FLAT_TIRE':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.crevaison1,
          category: AppLocalizations.of(context)!.attaque,
          badgeText: AppLocalizations.of(context)!.crevaison,
          icon: Icons.tire_repair_rounded,
          primaryColor: Color(0xFFE11D48),
          secondaryColor: Color(0xFF881337),
        );

      // 🟢 PARADES & REMÈDES
      case 'GREEN_LIGHT':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.feuVert1,
          category: AppLocalizations.of(context)!.parade,
          badgeText: AppLocalizations.of(context)!.roulez,
          icon: Icons.check_circle_rounded,
          primaryColor: Color(0xFF10B981),
          secondaryColor: Color(0xFF065F46),
        );
      case 'END_OF_LIMIT':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.finDeLimite,
          category: AppLocalizations.of(context)!.parade,
          badgeText: AppLocalizations.of(context)!.fin50,
          icon: Icons.all_inclusive_rounded,
          primaryColor: Color(0xFFF59E0B),
          secondaryColor: Color(0xFF78350F),
        );
      case 'EXTRA_TANK':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.essence,
          category: AppLocalizations.of(context)!.parade,
          badgeText: AppLocalizations.of(context)!.plein,
          icon: Icons.local_gas_station_rounded,
          primaryColor: Color(0xFF10B981),
          secondaryColor: Color(0xFF065F46),
        );
      case 'SPARE_TIRE':
        return _MilleBornesCardInfo(
          name: AppLocalizations.of(context)!.roueDeSecours,
          category: AppLocalizations.of(context)!.parade,
          badgeText: AppLocalizations.of(context)!.repare,
          icon: Icons.change_circle_rounded,
          primaryColor: Color(0xFF10B981),
          secondaryColor: Color(0xFF065F46),
        );

      default:
        return _MilleBornesCardInfo(
          name: card,
          category: AppLocalizations.of(context)!.carte2,
          badgeText: AppLocalizations.of(context)!.carte2,
          icon: Icons.style_rounded,
          primaryColor: Colors.grey.shade400,
          secondaryColor: Colors.grey.shade800,
        );
    }
  }

  void _showTargetSelectionDialog(
    BuildContext context,
    Map<String, dynamic> gameData,
    String card,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final pDatas = Map<String, dynamic>.from(
      gameData['milleBornesPlayerData'] ?? {},
    );
    _firebaseService.updateMilleBornesTargetLive(
      widget.gameCode,
      widget.playerId,
      card,
      null,
    );

    showDialog(
      context: context,
      builder:
          (ctx) => AlertDialog(
            backgroundColor: Color(0xFF1E1E2C),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
            title: Row(
              children: [
                Icon(Icons.gps_fixed_rounded, color: Colors.redAccent),
                SizedBox(width: 10),
                Text(
                  AppLocalizations.of(context)!.choisirLaCible,
                  style: TextStyle(color: Colors.white),
                ),
              ],
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children:
                  players.keys.where((pId) => pId != widget.playerId).map((
                    pId,
                  ) {
                    final pData = pDatas[pId] ?? {};
                    final List<String> safeties = List<String>.from(
                      pData['safeties'] ?? [],
                    );

                    bool isProtected = false;
                    if (card == 'STOP' ||
                        card == 'RED_LIGHT' ||
                        card == 'SPEED_LIMIT') {
                      if (safeties.contains('SAFETY_RIGHT_OF_WAY'))
                        isProtected = true;
                    } else if (card == 'FLAT_TIRE') {
                      if (safeties.contains('SAFETY_REPAIRS'))
                        isProtected = true;
                    } else if (card == 'OUT_OF_GAS') {
                      if (safeties.contains('SAFETY_EXTRA_TANK') ||
                          safeties.contains('SAFETY_EMERGENCY')) {
                        isProtected = true;
                      }
                    }

                    return Container(
                      margin: const EdgeInsets.symmetric(vertical: 4),
                      decoration: BoxDecoration(
                        color:
                            isProtected
                                ? Colors.white.withOpacity(0.04)
                                : Colors.redAccent.withOpacity(0.12),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color:
                              isProtected
                                  ? Colors.white10
                                  : Colors.redAccent.withOpacity(0.5),
                        ),
                      ),
                      child: ListTile(
                        title: Text(
                          players[pId]?['name'] ??
                              AppLocalizations.of(context)!.joueur,
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: isProtected ? Colors.white38 : Colors.white,
                          ),
                        ),
                        subtitle: Text(
                          isProtected
                              ? AppLocalizations.of(context)!.protegeParUneBotte
                              : GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.distanceKm,
                                [pData['distance'] ?? 0],
                              ),
                          style: TextStyle(
                            fontSize: 12,
                            color:
                                isProtected
                                    ? Colors.cyanAccent
                                    : Colors.white70,
                          ),
                        ),
                        trailing: Icon(
                          isProtected
                              ? Icons.shield_rounded
                              : Icons.flash_on_rounded,
                          color:
                              isProtected
                                  ? Colors.cyanAccent
                                  : Colors.redAccent,
                        ),
                        enabled: !isProtected,
                        onTap: () {
                          Navigator.pop(ctx);
                          _firebaseService.updateMilleBornesTargetLive(
                            widget.gameCode,
                            widget.playerId,
                            null,
                            null,
                          );
                          _firebaseService
                              .milleBornesAction(
                                widget.gameCode,
                                widget.playerId,
                                'play',
                                card: card,
                                targetId: pId,
                              )
                              .catchError((e) {
                                ScaffoldMessenger.of(context).showSnackBar(
                                  SnackBar(
                                    content: Text(
                                      e.toString().replaceAll(
                                        AppLocalizations.of(context)!.exception,
                                        "",
                                      ),
                                    ),
                                  ),
                                );
                              });
                        },
                      ),
                    );
                  }).toList(),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(
                  AppLocalizations.of(context)!.annuler,
                  style: TextStyle(color: Colors.white54),
                ),
              ),
            ],
          ),
    );
  }

  Widget _buildBatailleNavaleUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final myData = Map<String, dynamic>.from(playerData[playerId] ?? {});
    final isMyTurn = gameData['currentPlayerId'] == playerId;
    final players = gameData['players'];

    if (roundState == 'placement') {
      return _buildBatailleNavalePlacementUI(
        context,
        gameData,
        playerId,
        myData,
        playerData,
      );
    } else if (roundState == 'playing') {
      return _buildBatailleNavalePlayingUI(context, playerId, myData, isMyTurn);
    } else if (roundState == 'gameOver' ||
        gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Bataille Navale",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.touteLaFlotteAdverseA,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }
    return Center(child: CircularProgressIndicator());
  }

  Widget _buildBatailleNavalePlacementUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    Map<String, dynamic> myData,
    Map<String, dynamic> allPlayerData,
  ) {
    final shipsPlaced = Map<String, dynamic>.from(myData['shipsPlaced'] ?? {});
    final myGrid = List<int>.from(myData['myGrid'] ?? List.filled(100, 0));
    final bool isReady = myData['isReady'] ?? false;
    final bool allShipsPlaced =
        shipsPlaced.length == GameData.batailleNavaleShips.length &&
        _pendingShipType == null;

    List<String> unplacedShips =
        GameData.batailleNavaleShips.keys
            .where(
              (ship) =>
                  !shipsPlaced.containsKey(ship) && ship != _pendingShipType,
            )
            .toList();

    return LayoutBuilder(
      builder: (context, constraints) {
        // Calcul de la taille de la grille et des cellules pour tout l'écran
        double estimatedGridHeight = constraints.maxHeight * 0.55;
        double boardSize = min(constraints.maxWidth, estimatedGridHeight);
        double cellSize = boardSize / 10;

        return Column(
          children: [
            Container(
              padding: EdgeInsets.all(8),
              color: Colors.black45,
              child: Text(
                AppLocalizations.of(context)!.placezVotreFlotte,
                style: TextStyle(
                  color: Colors.cyanAccent,
                  fontWeight: FontWeight.bold,
                  fontSize: 18,
                ),
              ),
            ),

            // GRILLE
            Expanded(
              flex: 5,
              child: Center(
                child: SizedBox(
                  width: boardSize,
                  height: boardSize,
                  child: Stack(
                    children: [
                      Container(
                        decoration: BoxDecoration(
                          color: Colors.blue[900],
                          border: Border.all(
                            color: Colors.cyanAccent,
                            width: 2,
                          ),
                        ),
                        child: GridView.builder(
                          physics: NeverScrollableScrollPhysics(),
                          gridDelegate:
                              SliverGridDelegateWithFixedCrossAxisCount(
                                crossAxisCount: 10,
                              ),
                          itemCount: 100,
                          itemBuilder: (ctx, idx) {
                            int r = idx ~/ 10;
                            int c = idx % 10;

                            return DragTarget<String>(
                              builder: (context, candidateData, rejectedData) {
                                return GestureDetector(
                                  onTap: () {
                                    if (!isReady && _pendingShipType != null) {
                                      setState(() {
                                        _pendingShipRow = r;
                                        _pendingShipCol = c;
                                      });
                                    }
                                  },
                                  child: Container(
                                    decoration: BoxDecoration(
                                      border: Border.all(
                                        color: Colors.white24,
                                        width: 0.5,
                                      ),
                                      color:
                                          candidateData.isNotEmpty
                                              ? Colors.white.withOpacity(0.1)
                                              : Colors.transparent,
                                    ),
                                  ),
                                );
                              },
                              onWillAccept: (shipType) {
                                if (isReady) return false;
                                setState(() {
                                  _hoveredShipType = shipType;
                                  _hoveredRow = r;
                                  _hoveredCol = c;
                                });
                                return true;
                              },
                              onLeave: (shipType) {
                                setState(() {
                                  if (_hoveredRow == r && _hoveredCol == c) {
                                    _hoveredShipType = null;
                                    _hoveredRow = null;
                                    _hoveredCol = null;
                                  }
                                });
                              },
                              onAccept: (shipType) {
                                if (isReady) return;
                                var shipInfo =
                                    GameData.batailleNavaleShips[shipType]!;
                                int actualCols =
                                    _pendingShipHorizontal
                                        ? shipInfo['length']
                                        : shipInfo['width'];
                                int actualRows =
                                    _pendingShipHorizontal
                                        ? shipInfo['width']
                                        : shipInfo['length'];
                                int finalRow = r;
                                int finalCol = c;
                                if (finalRow + actualRows > 10)
                                  finalRow = 10 - actualRows;
                                if (finalCol + actualCols > 10)
                                  finalCol = 10 - actualCols;
                                setState(() {
                                  _pendingShipType = shipType;
                                  _pendingShipRow = finalRow;
                                  _pendingShipCol = finalCol;
                                  _hoveredShipType = null;
                                  _hoveredRow = null;
                                  _hoveredCol = null;
                                });
                              },
                            );
                          },
                        ),
                      ),

                      // Bateaux déjà placés sur la grille (Rendus Draggables)
                      ...shipsPlaced.entries.map((entry) {
                        String shipType = entry.key;
                        Map<String, dynamic> placedData =
                            Map<String, dynamic>.from(entry.value);
                        bool isHoriz = placedData['isHorizontal'];
                        var shipInfo = GameData.batailleNavaleShips[shipType]!;
                        int startRow = placedData['startIndex'] ~/ 10;
                        int startCol = placedData['startIndex'] % 10;

                        double width =
                            (isHoriz ? shipInfo['length'] : shipInfo['width']) *
                            cellSize;
                        double height =
                            (isHoriz ? shipInfo['width'] : shipInfo['length']) *
                            cellSize;

                        // Widget de retour visuel qui suit le doigt
                        Widget feedbackWidget = Opacity(
                          opacity: 0.8,
                          child: SizedBox(
                            width: width,
                            height: height,
                            child: RotatedBox(
                              quarterTurns: isHoriz ? 3 : 0,
                              child: Image.asset(
                                'assets/images/${shipInfo['image']}',
                                fit: BoxFit.fill,
                              ),
                            ),
                          ),
                        );

                        return Positioned(
                          left: startCol * cellSize,
                          top: startRow * cellSize,
                          width: width,
                          height: height,
                          child: Draggable<String>(
                            data: shipType,
                            feedback: feedbackWidget,
                            childWhenDragging:
                                SizedBox.shrink(), // Cache le bateau à son ancienne position pendant le drag
                            onDragStarted: () {
                              _firebaseService.removeShipBatailleNavale(
                                widget.gameCode,
                                playerId,
                                shipType,
                              );
                              setState(() {
                                _pendingShipType = shipType;
                                _pendingShipHorizontal = isHoriz;
                                _pendingShipRow = startRow;
                                _pendingShipCol = startCol;
                              });
                            },
                            child: GestureDetector(
                              onTap:
                                  isReady
                                      ? null
                                      : () {
                                        _firebaseService
                                            .removeShipBatailleNavale(
                                              widget.gameCode,
                                              playerId,
                                              shipType,
                                            );
                                        setState(() {
                                          _pendingShipType = shipType;
                                          _pendingShipRow = startRow;
                                          _pendingShipCol = startCol;
                                          _pendingShipHorizontal = isHoriz;
                                        });
                                      },
                              child: RotatedBox(
                                quarterTurns: isHoriz ? 3 : 0,
                                child: Image.asset(
                                  'assets/images/${shipInfo['image']}',
                                  fit: BoxFit.fill,
                                ),
                              ),
                            ),
                          ),
                        );
                      }).toList(),

                      // Prévisualisation lors du survol (Translucide, même échelle que le bateau posé)
                      if (_hoveredShipType != null &&
                          _hoveredRow != null &&
                          _hoveredCol != null)
                        Builder(
                          builder: (ctx) {
                            var shipInfo =
                                GameData
                                    .batailleNavaleShips[_hoveredShipType!]!;
                            bool isHoriz = _pendingShipHorizontal;
                            int widthCols =
                                isHoriz
                                    ? shipInfo['length']
                                    : shipInfo['width'];
                            int heightRows =
                                isHoriz
                                    ? shipInfo['width']
                                    : shipInfo['length'];
                            return Positioned(
                              left: _hoveredCol! * cellSize,
                              top: _hoveredRow! * cellSize,
                              width: widthCols * cellSize,
                              height: heightRows * cellSize,
                              child: IgnorePointer(
                                child: Container(
                                  decoration: BoxDecoration(
                                    border: Border.all(
                                      color: Colors.cyanAccent,
                                      width: 3,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: Colors.cyanAccent.withOpacity(
                                          0.5,
                                        ),
                                        blurRadius: 10,
                                      ),
                                    ],
                                  ),
                                  child: Opacity(
                                    opacity: 0.5,
                                    child: RotatedBox(
                                      quarterTurns: isHoriz ? 3 : 0,
                                      child: Image.asset(
                                        'assets/images/${shipInfo['image']}',
                                        fit: BoxFit.fill,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            );
                          },
                        ),

                      // Bateau sélectionné prêt à être validé (Contour vert)
                      if (_pendingShipType != null &&
                          _pendingShipRow != null &&
                          _pendingShipCol != null)
                        Builder(
                          builder: (ctx) {
                            var shipInfo =
                                GameData
                                    .batailleNavaleShips[_pendingShipType!]!;
                            int widthCols =
                                _pendingShipHorizontal
                                    ? shipInfo['length']
                                    : shipInfo['width'];
                            int heightRows =
                                _pendingShipHorizontal
                                    ? shipInfo['width']
                                    : shipInfo['length'];
                            return Positioned(
                              left: _pendingShipCol! * cellSize,
                              top: _pendingShipRow! * cellSize,
                              width: widthCols * cellSize,
                              height: heightRows * cellSize,
                              child: IgnorePointer(
                                child: Container(
                                  decoration: BoxDecoration(
                                    border: Border.all(
                                      color: Colors.greenAccent,
                                      width: 3,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: Colors.greenAccent,
                                        blurRadius: 10,
                                      ),
                                    ],
                                  ),
                                  child: RotatedBox(
                                    quarterTurns:
                                        _pendingShipHorizontal ? 3 : 0,
                                    child: Image.asset(
                                      'assets/images/${shipInfo['image']}',
                                      fit: BoxFit.fill,
                                    ),
                                  ),
                                ),
                              ),
                            );
                          },
                        ),
                    ],
                  ),
                ),
              ),
            ),

            // QUAI (Bateaux restants)
            Expanded(
              flex: 2,
              child: Container(
                padding: EdgeInsets.all(8),
                decoration: BoxDecoration(color: Colors.black.withOpacity(0.5)),
                child:
                    unplacedShips.isEmpty && _pendingShipType == null
                        ? Center(
                          child: Text(
                            AppLocalizations.of(context)!.flotteDeployee,
                            style: TextStyle(
                              color: Colors.greenAccent,
                              fontSize: 18,
                            ),
                          ),
                        )
                        : ListView.builder(
                          scrollDirection: Axis.horizontal,
                          itemCount: unplacedShips.length,
                          itemBuilder: (context, index) {
                            String shipType = unplacedShips[index];
                            var shipInfo =
                                GameData.batailleNavaleShips[shipType]!;
                            Widget shipWidget = RotatedBox(
                              quarterTurns: 3,
                              child: Image.asset(
                                'assets/images/${shipInfo['image']}',
                              ),
                            );

                            bool isHoriz = _pendingShipHorizontal;
                            double dragWidth =
                                (isHoriz
                                    ? shipInfo['length']
                                    : shipInfo['width']) *
                                cellSize;
                            double dragHeight =
                                (isHoriz
                                    ? shipInfo['width']
                                    : shipInfo['length']) *
                                cellSize;

                            return Draggable<String>(
                              data: shipType,
                              dragAnchorStrategy: pointerDragAnchorStrategy,
                              feedback: Opacity(
                                opacity: 0.8,
                                child: SizedBox(
                                  width: dragWidth,
                                  height: dragHeight,
                                  child: RotatedBox(
                                    quarterTurns: isHoriz ? 3 : 0,
                                    child: Image.asset(
                                      'assets/images/${shipInfo['image']}',
                                      fit: BoxFit.fill,
                                    ),
                                  ),
                                ),
                              ),
                              childWhenDragging: Opacity(
                                opacity: 0.3,
                                child: SizedBox(
                                  width: 80,
                                  height: 40,
                                  child: shipWidget,
                                ),
                              ),
                              onDragStarted: () {
                                setState(() => _pendingShipHorizontal = true);
                              },
                              child: Padding(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 10,
                                ),
                                child: Column(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    SizedBox(
                                      height: 40,
                                      width: 80,
                                      child: shipWidget,
                                    ),
                                    SizedBox(height: 5),
                                    Text(
                                      shipType,
                                      style: TextStyle(fontSize: 10),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          },
                        ),
              ),
            ),

            // BOUTONS D'ACTION
            Padding(
              padding: const EdgeInsets.all(8.0),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                children: [
                  if (_pendingShipType != null) ...[
                    ElevatedButton.icon(
                      icon: Icon(Icons.rotate_right),
                      label: Text(AppLocalizations.of(context)!.tourner),
                      onPressed: () {
                        setState(() {
                          _pendingShipHorizontal = !_pendingShipHorizontal;
                          if (_pendingShipType != null) {
                            var shipInfo =
                                GameData
                                    .batailleNavaleShips[_pendingShipType!]!;
                            int actualCols =
                                _pendingShipHorizontal
                                    ? shipInfo['length']
                                    : shipInfo['width'];
                            int actualRows =
                                _pendingShipHorizontal
                                    ? shipInfo['width']
                                    : shipInfo['length'];
                            if (_pendingShipRow! + actualRows > 10)
                              _pendingShipRow = 10 - actualRows;
                            if (_pendingShipCol! + actualCols > 10)
                              _pendingShipCol = 10 - actualCols;
                          }
                        });
                      },
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.orange,
                      ),
                    ),
                    ElevatedButton.icon(
                      icon:
                          _isActionPending
                              ? SizedBox(
                                width: 16,
                                height: 16,
                                child: CircularProgressIndicator(
                                  color: Colors.white,
                                  strokeWidth: 2,
                                ),
                              )
                              : Icon(Icons.check),
                      label: Text(AppLocalizations.of(context)!.valider),
                      onPressed:
                          _isActionPending
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                int idx =
                                    (_pendingShipRow! * 10) + _pendingShipCol!;
                                _firebaseService
                                    .placeShipBatailleNavale(
                                      widget.gameCode,
                                      playerId,
                                      _pendingShipType!,
                                      idx,
                                      _pendingShipHorizontal,
                                    )
                                    .then((_) {
                                      if (mounted) {
                                        setState(() {
                                          _pendingShipType = null;
                                          _isActionPending = false;
                                        });
                                      }
                                    })
                                    .catchError((e) {
                                      if (mounted) {
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                        ScaffoldMessenger.of(
                                          context,
                                        ).showSnackBar(
                                          SnackBar(
                                            content: Text(
                                              AppLocalizations.of(
                                                context,
                                              )!.placementInvalideChevauchementOuHors,
                                            ),
                                          ),
                                        );
                                      }
                                    });
                              },
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.green,
                      ),
                    ),
                  ] else ...[
                    ElevatedButton.icon(
                      icon: Icon(Icons.casino),
                      label: Text(AppLocalizations.of(context)!.aleatoire),
                      onPressed:
                          isReady
                              ? null
                              : () =>
                                  _firebaseService.randomizeShipsBatailleNavale(
                                    widget.gameCode,
                                    playerId,
                                  ),
                    ),
                    ElevatedButton.icon(
                      icon: Icon(isReady ? Icons.check : Icons.play_arrow),
                      label: Text(
                        isReady
                            ? AppLocalizations.of(context)!.pret1
                            : AppLocalizations.of(context)!.pret2,
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor:
                            isReady
                                ? Colors.green
                                : (allShipsPlaced
                                    ? Colors.deepPurple
                                    : Colors.grey),
                      ),
                      onPressed:
                          (!allShipsPlaced || isReady)
                              ? null
                              : () =>
                                  _firebaseService.setPlayerReadyBatailleNavale(
                                    widget.gameCode,
                                    playerId,
                                  ),
                    ),
                  ],
                ],
              ),
            ),
          ],
        );
      },
    );
  }

  int? _selectedNavalTarget;

  Widget _buildBatailleNavalePlayingUI(
    BuildContext context,
    String playerId,
    Map<String, dynamic> myData,
    bool isMyTurn,
  ) {
    final enemyGrid = List<String>.from(
      myData['enemyGrid'] ?? List.filled(100, 'unknown'),
    );
    final incomingGrid = List<String>.from(
      myData['incomingGrid'] ?? List.filled(100, 'unknown'),
    );
    final shipsPlaced = Map<String, dynamic>.from(myData['shipsPlaced'] ?? {});
    final myGrid = List<int>.from(myData['myGrid'] ?? List.filled(100, 0));

    return Column(
      children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
          decoration: BoxDecoration(
            color:
                isMyTurn
                    ? Colors.greenAccent.withOpacity(0.18)
                    : Colors.black38,
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color:
                  isMyTurn
                      ? Colors.greenAccent.withOpacity(0.6)
                      : Colors.white12,
              width: 1,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                isMyTurn ? Icons.my_location : Icons.shield_outlined,
                color: isMyTurn ? Colors.greenAccent : Colors.white70,
                size: 13,
              ),
              SizedBox(width: 6),
              Text(
                isMyTurn
                    ? AppLocalizations.of(context)!.aVotreTour
                    : AppLocalizations.of(context)!.tourAdverse,
                style: TextStyle(
                  color: isMyTurn ? Colors.greenAccent : Colors.white70,
                  fontSize: 12,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 8),

        // GRILLE ADVERSE (ZONE DE TIR) AVEC VISEUR LIVE
        Expanded(
          flex: 5,
          child: Column(
            children: [
              Text(
                AppLocalizations.of(context)!.territoireEnnemiTouchezPourViser,
                style: TextStyle(
                  color: Colors.redAccent,
                  fontWeight: FontWeight.bold,
                  fontSize: 13,
                ),
              ),
              SizedBox(height: 4),
              Expanded(
                child: _buildBatailleNavaleGridGame(
                  gridData: enemyGrid,
                  isEnemy: true,
                  selectedTargetIndex: isMyTurn ? _selectedNavalTarget : null,
                  onTap:
                      isMyTurn
                          ? (index) {
                            if (enemyGrid[index] == 'unknown' &&
                                !_isActionPending) {
                              if (_selectedNavalTarget == index) {
                                // 2e clic : Confirmation et tir !
                                setState(() {
                                  _isActionPending = true;
                                  _selectedNavalTarget = null;
                                });
                                _firebaseService.updateBatailleNavaleAimLive(
                                  widget.gameCode,
                                  playerId,
                                  null,
                                );
                                _firebaseService
                                    .shootBatailleNavale(
                                      widget.gameCode,
                                      playerId,
                                      index,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              } else {
                                // 1er clic : Verrouillage laser de la cible en direct
                                HapticFeedback.selectionClick();
                                setState(() => _selectedNavalTarget = index);
                                _firebaseService.updateBatailleNavaleAimLive(
                                  widget.gameCode,
                                  playerId,
                                  index,
                                );
                              }
                            }
                          }
                          : null,
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 8),

        // VOTRE FLOTTE AVEC DÉTECTION DU RADAR ADVERSE EN DIRECT
        Expanded(
          flex: 4,
          child: StreamBuilder<DatabaseEvent>(
            stream: _firebaseService.getBatailleNavaleAimStream(
              widget.gameCode,
            ),
            builder: (context, aimSnap) {
              int? enemyAimedIndex;
              if (aimSnap.hasData && aimSnap.data!.snapshot.value != null) {
                try {
                  final raw = Map<String, dynamic>.from(
                    aimSnap.data!.snapshot.value as Map,
                  );
                  final aPlayerId = raw['playerId'] as String?;
                  if (aPlayerId != null && aPlayerId != playerId) {
                    enemyAimedIndex = (raw['targetIndex'] as num?)?.toInt();
                  }
                } catch (_) {}
              }

              return Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        AppLocalizations.of(
                          context,
                        )!.votreFlotteTirsEnnemisRecus,
                        style: TextStyle(
                          color: Colors.cyanAccent,
                          fontWeight: FontWeight.bold,
                          fontSize: 13,
                        ),
                      ),
                      if (enemyAimedIndex != null) ...[
                        SizedBox(width: 8),
                        Container(
                          padding: EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 2,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.redAccent.withOpacity(0.25),
                            borderRadius: BorderRadius.circular(10),
                            border: Border.all(
                              color: Colors.redAccent,
                              width: 1.2,
                            ),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                Icons.gps_fixed,
                                color: Colors.redAccent,
                                size: 12,
                              ),
                              SizedBox(width: 4),
                              Text(
                                "🚨 " +
                                    GameContentLocalization.format(
                                      context,
                                      AppLocalizations.of(
                                        context,
                                      )!.radarCaseCiblee,
                                      [
                                        "${String.fromCharCode(65 + enemyAimedIndex ~/ 10)}${enemyAimedIndex % 10 + 1}",
                                      ],
                                    ),
                                style: TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.bold,
                                  fontSize: 10,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ],
                  ),
                  SizedBox(height: 4),
                  Expanded(
                    child: _buildBatailleNavaleGridGame(
                      gridData: incomingGrid,
                      isEnemy: false,
                      myShips: shipsPlaced,
                      enemyAimedIndex: enemyAimedIndex,
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildBatailleNavaleGridGame({
    required List<String> gridData,
    required bool isEnemy,
    Map<String, dynamic>? myShips,
    Function(int)? onTap,
    int? selectedTargetIndex,
    int? enemyAimedIndex,
  }) {
    return LayoutBuilder(
      builder: (context, constraints) {
        double boardSize = min(constraints.maxWidth, constraints.maxHeight);
        double cellSize = boardSize / 10;

        return Center(
          child: SizedBox(
            width: boardSize,
            height: boardSize,
            child: Stack(
              children: [
                // 1. Fond bleu océan + lignes de grille
                Container(
                  decoration: BoxDecoration(
                    color: Color(0xFF0C2340),
                    border: Border.all(
                      color:
                          isEnemy
                              ? Colors.redAccent.withOpacity(0.6)
                              : Colors.cyanAccent.withOpacity(0.6),
                      width: 1.5,
                    ),
                    borderRadius: BorderRadius.circular(8),
                  ),
                ),

                // 2. Affichage des bateaux (sur Votre Flotte)
                if (!isEnemy && myShips != null)
                  ...myShips.entries.map((entry) {
                    var placedData = Map<String, dynamic>.from(entry.value);
                    int startIndex = placedData['startIndex'];
                    bool isHoriz = placedData['isHorizontal'];
                    bool isSunk = placedData['sunk'] ?? false;
                    var shipInfo = GameData.batailleNavaleShips[entry.key]!;

                    int startRow = startIndex ~/ 10;
                    int startCol = startIndex % 10;
                    int widthCols =
                        isHoriz ? shipInfo['length'] : shipInfo['width'];
                    int heightRows =
                        isHoriz ? shipInfo['width'] : shipInfo['length'];

                    return Positioned(
                      left: startCol * cellSize,
                      top: startRow * cellSize,
                      width: widthCols * cellSize,
                      height: heightRows * cellSize,
                      child: Opacity(
                        opacity: isSunk ? 0.45 : 1.0,
                        child: RotatedBox(
                          quarterTurns: isHoriz ? 3 : 0,
                          child: Image.asset(
                            'assets/images/${shipInfo['image']}',
                            fit: BoxFit.fill,
                          ),
                        ),
                      ),
                    );
                  }).toList(),

                // 3. Grille des tirs, explosions et flammes (PAR-DESSUS LES BATEAUX)
                GridView.builder(
                  physics: NeverScrollableScrollPhysics(),
                  gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 10,
                  ),
                  itemCount: 100,
                  itemBuilder: (context, index) {
                    String status = gridData[index];
                    Color cellBgColor = Colors.transparent;
                    Widget? overlay;

                    if (isEnemy) {
                      if (status == 'miss') {
                        overlay = Container(
                          width: 8,
                          height: 8,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: Colors.white54,
                          ),
                        );
                      } else if (status == 'hit') {
                        cellBgColor = Colors.red.withOpacity(0.35);
                        overlay = Icon(
                          Icons.local_fire_department_rounded,
                          color: Color(0xFFFF5722),
                          size: 22,
                          shadows: [
                            Shadow(color: Colors.yellowAccent, blurRadius: 8),
                          ],
                        );
                      } else if (status == 'sunk') {
                        cellBgColor = Colors.black.withOpacity(0.5);
                        overlay = Icon(
                          Icons.close_rounded,
                          color: Colors.redAccent,
                          size: 24,
                        );
                      }
                    } else {
                      // SUR VOTRE FLOTTE : Tirs reçus
                      if (status == 'miss') {
                        overlay = Container(
                          width: 7,
                          height: 7,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: Colors.white.withOpacity(0.6),
                          ),
                        );
                      } else if (status == 'hit' || status == 'sunk') {
                        // 🔥 FLAMME AFFICHÉE DIRECTEMENT SUR LE BATEAU TOUCHÉ
                        overlay = Container(
                          decoration: BoxDecoration(
                            color: Colors.red.withOpacity(0.3),
                            shape: BoxShape.circle,
                          ),
                          child: Center(
                            child: Icon(
                              Icons.local_fire_department_rounded,
                              color: Color(0xFFFF3D00), // Flamme ardente
                              size: 24,
                              shadows: [
                                Shadow(
                                  color: Colors.yellowAccent,
                                  blurRadius: 10,
                                ),
                              ],
                            ),
                          ),
                        );
                      }
                    }

                    final bool isTargetedByMe =
                        (isEnemy && selectedTargetIndex == index);
                    final bool isAimedByEnemy =
                        (!isEnemy && enemyAimedIndex == index);

                    Widget? liveOverlay = overlay;
                    if (isTargetedByMe) {
                      liveOverlay = Container(
                        decoration: BoxDecoration(
                          color: Colors.cyanAccent.withOpacity(0.25),
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: Colors.cyanAccent,
                            width: 2,
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.cyanAccent.withOpacity(0.6),
                              blurRadius: 8,
                            ),
                          ],
                        ),
                        child: Center(
                          child: Icon(
                            Icons.gps_fixed_rounded,
                            color: Colors.cyanAccent,
                            size: 20,
                          ),
                        ),
                      );
                    } else if (isAimedByEnemy) {
                      liveOverlay = Container(
                        decoration: BoxDecoration(
                          color: Colors.redAccent.withOpacity(0.35),
                          shape: BoxShape.circle,
                          border: Border.all(color: Colors.redAccent, width: 2),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.redAccent.withOpacity(0.8),
                              blurRadius: 10,
                              spreadRadius: 2,
                            ),
                          ],
                        ),
                        child: Center(
                          child: Icon(
                            Icons.gps_fixed_rounded,
                            color: Colors.redAccent,
                            size: 22,
                          ),
                        ),
                      );
                    }

                    return GestureDetector(
                      onTap: onTap != null ? () => onTap(index) : null,
                      child: Container(
                        decoration: BoxDecoration(
                          color:
                              (isTargetedByMe || isAimedByEnemy)
                                  ? (isTargetedByMe
                                      ? Colors.cyan.withOpacity(0.2)
                                      : Colors.red.withOpacity(0.25))
                                  : cellBgColor,
                          border: Border.all(
                            color:
                                (isTargetedByMe || isAimedByEnemy)
                                    ? (isTargetedByMe
                                        ? Colors.cyanAccent
                                        : Colors.redAccent)
                                    : Colors.white.withOpacity(0.12),
                            width:
                                (isTargetedByMe || isAimedByEnemy) ? 1.5 : 0.5,
                          ),
                        ),
                        child: Center(child: liveOverlay),
                      ),
                    );
                  },
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildPokerUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final phase = gameData['phase'];
    final communityCards =
        (gameData['communityCards'] as List<dynamic>? ?? [])
            .cast<String>()
            .toList();
    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final myData = playerData[playerId] ?? {};
    final myHand =
        (myData['hand'] as List<dynamic>? ?? []).cast<String>().toList();
    final int pot = (gameData['pot'] as num? ?? 0).toInt();
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    final bool isMyTurn =
        playerOrder.isNotEmpty
            ? playerOrder[currentPlayerIndex] == playerId &&
                myData['status'] == 'active'
            : false;

    // --- GAME OVER / FIN DE MAIN ---
    if (phase == 'hand_over') {
      final handLog = List<String>.from(gameData['handLog'] ?? []);
      final myName = myData['name'] ?? '';
      if (handLog.isNotEmpty &&
          myName.isNotEmpty &&
          handLog.last.contains(myName)) {
        if (myData['status'] == 'all-in') {
          Provider.of<PlayerState>(
            context,
            listen: false,
          ).recordBadgeEvent('poker_all_in_win');
        }
        if (myHand.isNotEmpty && communityCards.isNotEmpty) {
          final evaluated = PokerHandEvaluator.evaluateHand([
            ...myHand,
            ...communityCards,
          ]);
          if (evaluated.rank == HandRank.royalFlush) {
            Provider.of<PlayerState>(
              context,
              listen: false,
            ).recordBadgeEvent('poker_royal_flush');
          }
        }
      }
      if ((myData['chips'] ?? 0) >= 5000) {
        Provider.of<PlayerState>(
          context,
          listen: false,
        ).recordBadgeEvent('poker_win_chips_5000');
      }
      return Center(
        child: Card(
          elevation: 10,
          color: Colors.green[900],
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  AppLocalizations.of(context)!.mainTerminee,
                  style: TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                ),
                Divider(color: Colors.white30),
                Text(
                  handLog.isNotEmpty ? handLog.last : "",
                  style: TextStyle(color: Colors.amberAccent, fontSize: 18),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 20),
                if (gameData['hostId'] == playerId)
                  ElevatedButton(
                    onPressed:
                        () => _firebaseService.startGame(widget.gameCode),
                    child: Text(
                      AppLocalizations.of(context)!.distribuerLaSuite,
                    ),
                  )
                else
                  Text(
                    AppLocalizations.of(context)!.attenteDuDonneur,
                    style: TextStyle(color: Colors.white54),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    return Container(
      decoration: BoxDecoration(
        // TEXTURE DE TAPIS DE POKER
        color: Color(0xFF35654d), // Vert Poker classique
        borderRadius: BorderRadius.circular(20),
        border: Border.all(
          color: Colors.brown[900]!,
          width: 8,
        ), // Bordure en bois
        // CORRECTION ICI : Suppression de inset: true qui n'existe pas
        boxShadow: [BoxShadow(color: Colors.black, blurRadius: 10)],
      ),
      child: Column(
        children: [
          // 1. ADVERSAIRES (Haut) - infos déplacées dans le ActionChip
          Spacer(),

          // 2. TABLE CENTRALE (Pot + Cartes)
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // Pot + Écoute de la relance en préparation
              StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getPokerRaisePreviewStream(
                  widget.gameCode,
                ),
                builder: (context, snap) {
                  int? previewAmount;
                  String? previewPlayerName;
                  if (snap.hasData && snap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        snap.data!.snapshot.value as Map,
                      );
                      final pId = raw['playerId'] as String?;
                      if (pId != null && pId != playerId) {
                        previewAmount = raw['amount'] as int?;
                        previewPlayerName =
                            playerData[pId]?['name'] ??
                            AppLocalizations.of(context)!.adversaire;
                      }
                    } catch (_) {}
                  }

                  return Column(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 20,
                          vertical: 8,
                        ),
                        decoration: BoxDecoration(
                          color: Colors.black26,
                          borderRadius: BorderRadius.circular(30),
                          border: Border.all(
                            color: Colors.amber.withOpacity(0.3),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(
                              Icons.monetization_on,
                              color: Colors.amber,
                              size: 20,
                            ),
                            SizedBox(width: 8),
                            Text(
                              AppLocalizations.of(context)!.pokerPot('$pot'),
                              style: TextStyle(
                                fontSize: 18,
                                color: Colors.white,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                      ),
                      if (previewAmount != null)
                        Container(
                          margin: const EdgeInsets.only(top: 8),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.redAccent.withOpacity(0.25),
                            borderRadius: BorderRadius.circular(16),
                            border: Border.all(color: Colors.redAccent),
                          ),
                          child: Text(
                            AppLocalizations.of(context)!.pokerRaiseAlert(
                              previewPlayerName ?? '',
                              '$previewAmount',
                            ),
                            style: TextStyle(
                              color: Colors.white,
                              fontWeight: FontWeight.bold,
                              fontSize: 12,
                            ),
                          ),
                        ),
                    ],
                  );
                },
              ),
              SizedBox(height: 20),
              // Community Cards
              Container(
                height: 110,
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children:
                      communityCards.isNotEmpty
                          ? communityCards
                              .map(
                                (card) =>
                                    _buildCard(card: card, isSelected: false),
                              )
                              .toList()
                          : [
                            // Emplacements vides pour le réalisme
                            for (int i = 0; i < 5; i++)
                              Container(
                                width: 60,
                                height: 90,
                                margin: EdgeInsets.all(4),
                                decoration: BoxDecoration(
                                  border: Border.all(color: Colors.white10),
                                  borderRadius: BorderRadius.circular(8),
                                ),
                              ),
                          ],
                ),
              ),
            ],
          ),

          Spacer(),

          // 3. JOUEUR (Bas)
          Container(
            padding: EdgeInsets.all(10),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [Colors.transparent, Colors.black54],
              ),
            ),
            child: Column(
              children: [
                // Mes Cartes
                if (myData['status'] != 'folded')
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        myHand
                            .map(
                              (card) => Transform.translate(
                                offset: Offset(
                                  0,
                                  isMyTurn ? -10 : 0,
                                ), // Légère animation si c'est mon tour
                                child: _buildCard(
                                  card: card,
                                  isSelected: false,
                                  scale: 1.1,
                                ),
                              ),
                            )
                            .toList(),
                  )
                else
                  Text(
                    AppLocalizations.of(context)!.couche,
                    style: TextStyle(
                      color: Colors.grey,
                      fontStyle: FontStyle.italic,
                    ),
                  ),

                SizedBox(height: 10),

                // Mes Jetons
                Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Icon(
                      Icons.account_balance_wallet,
                      color: Colors.greenAccent,
                      size: 16,
                    ),
                    SizedBox(width: 5),
                    Text(
                      "${myData['chips']} \$",
                      style: TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.bold,
                        color: Colors.greenAccent,
                      ),
                    ),
                    SizedBox(width: 15),
                    Text(
                      AppLocalizations.of(context)!.miseActuelle,
                      style: TextStyle(color: Colors.white70),
                    ),
                  ],
                ),

                SizedBox(height: 10),

                // Boutons d'action
                if (isMyTurn)
                  _buildPokerActionButtons(gameData, playerId)
                else
                  Text(
                    AppLocalizations.of(context)!.enAttente,
                    style: TextStyle(color: Colors.white38),
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPokerActionButtons(
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    var myData = gameData['playerData'][playerId];
    int currentBet = gameData['currentBet'];
    bool canCheck = myData['currentBet'] == currentBet;

    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: [
        ElevatedButton(
          onPressed:
              () => _firebaseService.pokerAction(
                widget.gameCode,
                playerId,
                'fold',
              ),
          child: Text(AppLocalizations.of(context)!.seCoucher),
        ),
        if (canCheck)
          ElevatedButton(
            onPressed:
                () => _firebaseService.pokerAction(
                  widget.gameCode,
                  playerId,
                  'check',
                ),
            child: Text(AppLocalizations.of(context)!.checker),
          ),
        if (!canCheck)
          ElevatedButton(
            onPressed:
                () => _firebaseService.pokerAction(
                  widget.gameCode,
                  playerId,
                  'call',
                ),
            child: Text(AppLocalizations.of(context)!.pokerCall('$currentBet')),
          ),
        ElevatedButton(
          onPressed: () {
            _showRaiseDialog(gameData, playerId);
          },
          child: Text(AppLocalizations.of(context)!.relancer),
        ),
      ],
    );
  }

  void _showRaiseDialog(Map<String, dynamic> gameData, String playerId) {
    final playerData = gameData['playerData'][playerId];
    final int myChips = playerData['chips'];
    final int myCurrentBet = playerData['currentBet'];
    final int currentBet = gameData['currentBet'];
    final int bigBlind = gameData['bigBlind'] ?? 20;
    final int pot = gameData['pot'] ?? 0;

    int minRaise = currentBet + bigBlind;
    if (minRaise < currentBet * 2 && myChips + myCurrentBet > currentBet * 2) {
      minRaise = currentBet * 2;
    }

    final int maxRaise = myChips + myCurrentBet;

    if (minRaise >= maxRaise) {
      _firebaseService.pokerAction(
        widget.gameCode,
        playerId,
        'raise',
        amount: maxRaise,
      );
      return;
    }

    double raiseAmount = minRaise.toDouble();

    showDialog(
      context: context,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setStateDialog) {
            return AlertDialog(
              title: Text(AppLocalizations.of(context)!.choisirLeMontantDeLa),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    raiseAmount.toInt().toString(),
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  Slider(
                    value: raiseAmount,
                    min: minRaise.toDouble(),
                    max: maxRaise.toDouble(),
                    label: raiseAmount.toInt().toString(),
                    onChanged: (value) {
                      setStateDialog(() {
                        raiseAmount = value.roundToDouble();
                      });
                      _firebaseService.updatePokerRaisePreview(
                        widget.gameCode,
                        playerId,
                        raiseAmount.toInt(),
                      );
                    },
                  ),
                  SizedBox(height: 10),
                  Wrap(
                    spacing: 8,
                    alignment: WrapAlignment.center,
                    children: [
                      if (currentBet * 2 <= maxRaise)
                        ActionChip(
                          label: Text(AppLocalizations.of(context)!.x2),
                          onPressed: () {
                            setStateDialog(
                              () => raiseAmount = (currentBet * 2).toDouble(),
                            );
                            _firebaseService.updatePokerRaisePreview(
                              widget.gameCode,
                              playerId,
                              raiseAmount.toInt(),
                            );
                          },
                        ),
                      if (pot <= maxRaise)
                        ActionChip(
                          label: Text(AppLocalizations.of(context)!.pot),
                          onPressed: () {
                            setStateDialog(() => raiseAmount = pot.toDouble());
                            _firebaseService.updatePokerRaisePreview(
                              widget.gameCode,
                              playerId,
                              raiseAmount.toInt(),
                            );
                          },
                        ),
                      ActionChip(
                        label: Text(AppLocalizations.of(context)!.allIn),
                        onPressed: () {
                          setStateDialog(
                            () => raiseAmount = maxRaise.toDouble(),
                          );
                          _firebaseService.updatePokerRaisePreview(
                            widget.gameCode,
                            playerId,
                            raiseAmount.toInt(),
                          );
                        },
                      ),
                    ],
                  ),
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () {
                    _firebaseService.updatePokerRaisePreview(
                      widget.gameCode,
                      playerId,
                      null,
                    );
                    Navigator.of(context).pop();
                  },
                  child: Text(AppLocalizations.of(context)!.annuler),
                ),
                ElevatedButton(
                  onPressed: () {
                    _firebaseService.updatePokerRaisePreview(
                      widget.gameCode,
                      playerId,
                      null,
                    );
                    Navigator.of(context).pop();
                    _firebaseService.pokerAction(
                      widget.gameCode,
                      playerId,
                      'raise',
                      amount: raiseAmount.toInt(),
                    );
                  },
                  child: Text(
                    AppLocalizations.of(
                      context,
                    )!.pokerRaiseTo('${raiseAmount.toInt()}'),
                  ),
                ),
              ],
            );
          },
        );
      },
    ).then((_) {
      _firebaseService.updatePokerRaisePreview(widget.gameCode, playerId, null);
    });
  }

  Widget _buildUnoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String gameState = gameData['gameState'];
    final List<String> playerOrder = List<String>.from(
      gameData['unoPlayerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentPlayerIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;

    List<String> myHand = List<String>.from(
      gameData['unoPlayerHands']?[playerId] ?? [],
    );
    if (_isHandSorted) {
      myHand = _sortCards(myHand);
    }

    final List<String> discardPile = List<String>.from(
      gameData['unoDiscardPile'] ?? [],
    );
    final String topCard = discardPile.isNotEmpty ? discardPile.last : 'red-0';
    final int pendingDraw = gameData['unoPendingDraw'] ?? 0;
    final String? wildColorChosen = gameData['unoWildColorChosen'];
    final bool isHost = gameData['hostId'] == playerId;
    final Map<String, dynamic> players = gameData['players'] ?? {};
    _unoDrawActionDone = gameData['unoDrawActionDone'] ?? false;

    if (gameState == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Uno",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.derniereCartePosee,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: isHost,
        onExit: _exitGame,
      );
    }

    Color currentColor = _mapUnoColorToFlutterColor(
      wildColorChosen ?? GameData.getUnoCardColor(topCard),
    );

    // --- INTERFACE DE JEU ANTI-OVERFLOW & NEON ARCADE ---
    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          physics: BouncingScrollPhysics(),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: IntrinsicHeight(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  // 1. BANDEAU DE STATUT DU TOUR AVEC LIVE COLOR CHOOSING
                  _buildUnoTurnStatus(
                    context,
                    gameData,
                    isMyTurn,
                    currentPlayerId,
                    pendingDraw,
                    wildColorChosen,
                    currentColor,
                  ),
                  StreamBuilder<DatabaseEvent>(
                    stream: _firebaseService.getUnoLiveStream(widget.gameCode),
                    builder: (context, snap) {
                      String? choosingColor;
                      if (snap.hasData && snap.data!.snapshot.value != null) {
                        try {
                          final raw = Map<String, dynamic>.from(
                            snap.data!.snapshot.value as Map,
                          );
                          choosingColor = raw['color'] as String?;
                        } catch (_) {}
                      }

                      if (choosingColor != null && !isMyTurn) {
                        final String chooserName =
                            players[currentPlayerId]?['name'] ??
                            AppLocalizations.of(context)!.lAdversaire;
                        return Container(
                          margin: const EdgeInsets.symmetric(
                            horizontal: 16,
                            vertical: 4,
                          ),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 14,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.amber.withOpacity(0.2),
                            borderRadius: BorderRadius.circular(14),
                            border: Border.all(
                              color: Colors.amberAccent,
                              width: 1.5,
                            ),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                Icons.palette_rounded,
                                color: Colors.amberAccent,
                                size: 16,
                              ),
                              SizedBox(width: 8),
                              Text(
                                GameContentLocalization.format(
                                  context,
                                  AppLocalizations.of(
                                    context,
                                  )!.hesiteEtChoisitLaCouleur,
                                  [chooserName],
                                ),
                                style: TextStyle(
                                  color: Colors.amberAccent,
                                  fontSize: 12,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            ],
                          ),
                        );
                      }
                      return const SizedBox.shrink();
                    },
                  ),

                  SizedBox(height: 8),

                  // 2. TAPIS DE JEU : PIOCHE ET DÉFAUSSE GLOW
                  Container(
                    margin: const EdgeInsets.symmetric(vertical: 4),
                    padding: const EdgeInsets.symmetric(
                      vertical: 12,
                      horizontal: 20,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.black.withOpacity(0.3),
                      borderRadius: BorderRadius.circular(24),
                      border: Border.all(
                        color: currentColor.withOpacity(0.3),
                        width: 1.5,
                      ),
                    ),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        // PIOCHE TACTILE
                        GestureDetector(
                          onTap:
                              isMyTurn &&
                                      !_unoDrawActionDone &&
                                      !_isActionPending
                                  ? () => _onUnoDrawTapped()
                                  : null,
                          child: Container(
                            width: 68,
                            height: 102,
                            decoration: BoxDecoration(
                              gradient: LinearGradient(
                                colors: [Color(0xFF232526), Color(0xFF414345)],
                                begin: Alignment.topLeft,
                                end: Alignment.bottomRight,
                              ),
                              borderRadius: BorderRadius.circular(10),
                              border: Border.all(
                                color:
                                    (isMyTurn &&
                                            pendingDraw == 0 &&
                                            !_unoDrawActionDone)
                                        ? Colors.greenAccent
                                        : Colors.white24,
                                width:
                                    (isMyTurn &&
                                            pendingDraw == 0 &&
                                            !_unoDrawActionDone)
                                        ? 2
                                        : 1,
                              ),
                              boxShadow: [
                                BoxShadow(
                                  color: Colors.black.withOpacity(0.6),
                                  blurRadius: 8,
                                  offset: Offset(2, 4),
                                ),
                              ],
                            ),
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Icon(
                                  Icons.style_rounded,
