  Widget _buildUnoGameTable(
    BuildContext context,
    Map<String, dynamic> gameData,
    bool isMyTurn,
    int pendingDraw,
  ) {
    final List<String> discardPile = List<String>.from(
      gameData['unoDiscardPile'] ?? [],
    );
    final String topCard = discardPile.isNotEmpty ? discardPile.last : 'red-0';
    final String? wildColorChosen = gameData['unoWildColorChosen'];

    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        _buildUnoCardWidget(
          topCard,
          isTopCard: true,
          isPlayable: false,
          wildColor: wildColorChosen,
        ),
        SizedBox(width: 20),
        GestureDetector(
          onTap:
              isMyTurn && !_unoDrawActionDone && !_isActionPending
                  ? () => _onUnoDrawTapped()
                  : null,
          child: Container(
            width: 70,
            height: 100,
            decoration: BoxDecoration(
              color: Colors.grey[800],
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                color:
                    isMyTurn && pendingDraw == 0 && !_unoDrawActionDone
                        ? Colors.greenAccent
                        : Colors.white24,
                width: 2,
              ),
            ),
            child: Center(
              child: Icon(Icons.add_box_rounded, size: 40, color: Colors.white),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildUnoPlayerHand(
    BuildContext context,
    Map<String, dynamic> gameData,
    bool isMyTurn,
    List<String> myHand,
    String topCard,
    String? wildColorChosen,
    int pendingDraw,
  ) {
    return Expanded(
      child:
          myHand.isEmpty
              ? Center(
                child: Text(AppLocalizations.of(context)!.vousNAvezPlusDe),
              )
              : GridView.builder(
                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 5,
                  childAspectRatio: 0.7,
                  crossAxisSpacing: 8,
                  mainAxisSpacing: 8,
                ),
                itemCount: myHand.length,
                itemBuilder: (context, index) {
                  String card = myHand[index];
                  bool canPlayNormally = GameData.canPlayUnoCard(
                    card,
                    topCard,
                    wildColorChosen,
                  );
                  bool isPlayableInContext = false;

                  if (isMyTurn && !_isActionPending) {
                    if (pendingDraw > 0) {
                      String cardValue = GameData.getUnoCardValue(card);
                      bool isDrawCard =
                          (cardValue == 'draw2' || cardValue == 'wild_draw4');
                      if (canPlayNormally &&
                          isDrawCard &&
                          (gameData['unoStackDraws'] ?? true)) {
                        isPlayableInContext = true;
                      }
                    } else if (_unoDrawActionDone) {
                      if (card == myHand.last && canPlayNormally) {
                        isPlayableInContext = true;
                      }
                    } else {
                      isPlayableInContext = canPlayNormally;
                    }
                  }

                  return Opacity(
                    opacity: isPlayableInContext ? 1.0 : 0.5,
                    child: _buildUnoCardWidget(
                      card,
                      isTopCard: false,
                      isPlayable: isPlayableInContext,
                    ),
                  );
                },
              ),
    );
  }

  Widget _buildUnoActionButtons(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    bool isMyTurn,
    List<String> myHand,
    int pendingDraw,
  ) {
    final String? lastActionPlayerId = gameData['unoLastActionPlayerId'];
    final Map<String, dynamic> unoCalledUno = Map<String, dynamic>.from(
      gameData['unoCalledUno'] ?? {},
    );
    final Timestamp? contraDeadline =
        gameData['unoContraDeadline'] as Timestamp?;
    final bool contraDelayPassed =
        contraDeadline != null &&
        DateTime.now().isAfter(contraDeadline.toDate());
    final bool targetHasNotCalledUno =
        lastActionPlayerId != null &&
        !(unoCalledUno[lastActionPlayerId] ?? true);
    final bool canContraUno =
        !isMyTurn &&
        lastActionPlayerId != null &&
        lastActionPlayerId != playerId &&
        targetHasNotCalledUno &&
        contraDelayPassed;
    final bool canSayUno =
        myHand.length == 1 &&
        !(unoCalledUno[playerId] ?? true) &&
        contraDeadline != null;
    final bool hasDrawnPlayable = gameData['unoDrawActionDone'] == true;

    return Wrap(
      spacing: 12,
      runSpacing: 8,
      alignment: WrapAlignment.center,
      children: [
        if (isMyTurn && pendingDraw > 0)
          ElevatedButton.icon(
            icon: Icon(Icons.download_for_offline_rounded),
            label: Text(
              AppLocalizations.of(context)!.unoDrawCountCards('$pendingDraw'),
            ),
            onPressed: _isActionPending ? null : () => _onUnoDrawTapped(),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
          ),
        if (isMyTurn && hasDrawnPlayable)
          ElevatedButton.icon(
            icon: Icon(Icons.skip_next_rounded),
            label: Text(AppLocalizations.of(context)!.garderPasser),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.blueGrey),
            onPressed:
                _isActionPending
                    ? null
                    : () async {
                      setState(() => _isActionPending = true);
                      try {
                        await _firebaseService.passUnoTurn(
                          widget.gameCode,
                          playerId,
                        );
                      } finally {
                        if (mounted) setState(() => _isActionPending = false);
                      }
                    },
          ),
        ElevatedButton.icon(
          icon: Icon(Icons.flash_on),
          label: Text(AppLocalizations.of(context)!.uno),
          onPressed:
              canSayUno && !_isUnoCalling && !_isActionPending
                  ? () async {
                    setState(() => _isUnoCalling = true);
                    try {
                      await _firebaseService.callUno(
                        widget.gameCode,
                        playerId,
                        playerId,
                      );
                    } catch (e) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text(
                            GameContentLocalization.format(
                              context,
                              AppLocalizations.of(context)!.erreur2,
                              [
                                e.toString().replaceAll(
                                  AppLocalizations.of(context)!.exception,
                                  '',
                                ),
                              ],
                            ),
                          ),
                        ),
                      );
                    } finally {
                      if (mounted) setState(() => _isUnoCalling = false);
                    }
                  }
                  : null,
          style: ElevatedButton.styleFrom(backgroundColor: Colors.orange),
        ),
        if (canContraUno)
          ElevatedButton.icon(
            icon: Icon(Icons.warning_amber_rounded),
            label: Text(AppLocalizations.of(context)!.contreUno),
            onPressed:
                _isActionPending
                    ? null
                    : () async {
                      setState(() => _isActionPending = true);
                      try {
                        await _firebaseService.callUno(
                          widget.gameCode,
                          playerId,
                          lastActionPlayerId!,
                        );
                        if (mounted) {
                          Provider.of<PlayerState>(
                            context,
                            listen: false,
                          ).recordBadgeEvent('uno_contra');
                        }
                      } catch (e) {
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text(
                              AppLocalizations.of(context)!.erreur1(
                                e.toString().replaceAll(
                                  AppLocalizations.of(context)!.exception,
                                  '',
                                ),
                              ),
                            ),
                          ),
                        );
                      } finally {
                        if (mounted) setState(() => _isActionPending = false);
                      }
                    },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.deepOrange),
          ),
      ],
    );
  }

  Widget _buildUnoCardWidget(
    String card, {
    required bool isTopCard,
    required bool isPlayable,
    String? wildColor,
  }) {
    String color = GameData.getUnoCardColor(card);
    String value = GameData.getUnoCardValue(card);

    Color cardColor = _mapUnoColorToFlutterColor(color);
    Color textColor = Colors.white;
    if (color == 'yellow') textColor = Colors.black;

    String cardText;
    switch (value) {
      case 'skip':
        cardText = AppLocalizations.of(context)!.ys;
        break;
      case 'reverse':
        cardText = AppLocalizations.of(context)!.yaaz;
        break;
      case 'draw2':
        cardText = '+2';
        break;
      case 'wild':
        cardText = '🌈';
        break;
      case 'wild_draw4':
        cardText = '+4';
        break;
      default:
        cardText = value;
        break;
    }

    if (isTopCard &&
        wildColor != null &&
        (value == 'wild' || value == 'wild_draw4')) {
      cardColor = _mapUnoColorToFlutterColor(wildColor);
      if (wildColor == 'yellow') textColor = Colors.black;
    }

    return GestureDetector(
      onTap: isPlayable ? () => _onUnoCardTapped(card) : null,
      child: Container(
        width: 70,
        height: 100,
        decoration: BoxDecoration(
          color: cardColor,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: Colors.white24, width: 1),
          boxShadow:
              isPlayable
                  ? [
                    BoxShadow(
                      color: Colors.greenAccent.withOpacity(0.7),
                      blurRadius: 10,
                      spreadRadius: 2,
                    ),
                  ]
                  : [],
        ),
        child: Center(
          child: Text(
            cardText,
            style: TextStyle(
              fontSize: 24,
              fontWeight: FontWeight.bold,
              color: textColor,
              shadows: [
                Shadow(blurRadius: 1, color: Colors.black.withOpacity(0.5)),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Color _mapUnoColorToFlutterColor(String unoColor) {
    switch (unoColor) {
      case 'red':
        return Colors.red;
      case 'yellow':
        return Colors.yellow;
      case 'green':
        return Colors.green;
      case 'blue':
        return Colors.blue;
      case 'wild':
        return Colors.black;
      default:
        return Colors.grey;
    }
  }

  void _onUnoCardTapped(String card) async {
    if (_isActionPending) return;

    final String playerId = widget.playerId;
    String cardValue = GameData.getUnoCardValue(card);

    final docSnap = Provider.of<DocumentSnapshot>(context, listen: false);
    final gameData = docSnap.data() as Map<String, dynamic>;
    final bool stackDraws = gameData['unoStackDraws'] ?? true;
    final int pendingDraw = gameData['unoPendingDraw'] ?? 0;
    final bool isStacking =
        stackDraws &&
        pendingDraw > 0 &&
        (cardValue == 'draw2' || cardValue == 'wild_draw4');

    if (cardValue == 'wild' || cardValue == 'wild_draw4') {
      _showColorPicker(card);
    } else {
      setState(() => _isActionPending = true);
      try {
        await _firebaseService.playUnoCard(widget.gameCode, playerId, card);
        if (isStacking && mounted) {
          Provider.of<PlayerState>(
            context,
            listen: false,
          ).recordBadgeEvent('uno_stack');
        }
      } catch (e) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                AppLocalizations.of(context)!.erreur1(
                  e.toString().replaceAll(
                    AppLocalizations.of(context)!.exception,
                    '',
                  ),
                ),
              ),
            ),
          );
      } finally {
        if (mounted) setState(() => _isActionPending = false);
      }
    }
  }

  // Animation visuelle simple : Fait apparaître une carte au centre qui descend vers le bas
  // Animation visuelle simple : Fait apparaître une carte au centre qui descend vers le bas
  void _animateCardFly(BuildContext context) {
    OverlayEntry? entry;

    entry = OverlayEntry(
      builder: (context) {
        // Démarre au centre (deck) et va vers le bas (main)
        return TweenAnimationBuilder<double>(
          tween: Tween(begin: 0.0, end: 1.0),
          duration: Duration(milliseconds: 600),
          curve: Curves.easeInOutCubic,
          onEnd: () {
            entry?.remove(); // On nettoie à la fin
          },
          builder: (context, value, child) {
            // Interpolation de position
            // Start: Centre écran (MediaQuery / 2)
            // End: Bas écran (Main du joueur)
            final size = MediaQuery.of(context).size;
            final startY = size.height * 0.4; // Un peu au-dessus du centre
            final endY = size.height * 0.85; // Vers la main

            final currentY = startY + (endY - startY) * value;
            final scale =
                0.5 +
                (0.5 * value); // La carte grandit en approchant (effet 3D)

            return Positioned(
              top: currentY,
              left:
                  (size.width / 2) -
                  30, // Centré horizontalement (- moitié largeur carte)
              child: Opacity(
                opacity:
                    1.0 -
                    value * 0.5, // Disparait doucement en arrivant dans la main
                child: Transform.scale(
                  scale: scale,
                  child: Container(
                    width: 60,
                    height: 90,
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: Colors.white),
                      boxShadow: [
                        BoxShadow(color: Colors.black54, blurRadius: 10),
                      ],
                    ),
                    // Dos de carte générique
                    child: Center(child: Icon(Icons.style, color: Colors.red)),
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    Overlay.of(context).insert(entry);
  }

  void _onUnoDrawTapped() async {
    if (_isActionPending) return;
    _animateCardFly(context);

    setState(() => _isActionPending = true);

    final String playerId = widget.playerId;

    try {
      await _firebaseService.drawUnoCard(widget.gameCode, playerId);
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              AppLocalizations.of(context)!.erreur1(
                e.toString().replaceAll(
                  AppLocalizations.of(context)!.exception,
                  '',
                ),
              ),
            ),
          ),
        );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  void _showColorPicker(String card) {
    _firebaseService.updateUnoLiveColorChoosing(
      widget.gameCode,
      widget.playerId,
      AppLocalizations.of(context)!.joker,
    );
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (BuildContext context) {
        return AlertDialog(
          title: Text(AppLocalizations.of(context)!.choisissezUneCouleur),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children:
                GameData.unoColors.map((colorName) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 4.0),
                    child: ElevatedButton(
                      onPressed:
                          _isActionPending
                              ? null
                              : () async {
                                Navigator.of(context).pop();
                                _firebaseService.updateUnoLiveColorChoosing(
                                  widget.gameCode,
                                  widget.playerId,
                                  null,
                                );
                                setState(() => _isActionPending = true);
                                try {
                                  final String playerId = widget.playerId;
                                  final docSnap = Provider.of<DocumentSnapshot>(
                                    context,
                                    listen: false,
                                  );
                                  final gameData =
                                      docSnap.data() as Map<String, dynamic>;
                                  final bool stackDraws =
                                      gameData['unoStackDraws'] ?? true;
                                  final int pendingDraw =
                                      gameData['unoPendingDraw'] ?? 0;
                                  final bool isStacking =
                                      stackDraws &&
                                      pendingDraw > 0 &&
                                      card.contains('wild_draw4');
                                  await _firebaseService.playUnoCard(
                                    widget.gameCode,
                                    playerId,
                                    card,
                                    chosenColor: colorName,
                                  );
                                  if (isStacking && mounted) {
                                    Provider.of<PlayerState>(
                                      context,
                                      listen: false,
                                    ).recordBadgeEvent('uno_stack');
                                  }
                                } catch (e) {
                                  if (mounted)
                                    ScaffoldMessenger.of(
                                      this.context,
                                    ).showSnackBar(
                                      SnackBar(
                                        content: Text(
                                          AppLocalizations.of(context)!.erreur1(
                                            e.toString().replaceAll(
                                              AppLocalizations.of(
                                                context,
                                              )!.exception,
                                              '',
                                            ),
                                          ),
                                        ),
                                      ),
                                    );
                                } finally {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                }
                              },
                      child: Text(
                        GameUiLocalization.tr(context, colorName).toUpperCase(),
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: _mapUnoColorToFlutterColor(colorName),
                        minimumSize: Size(150, 50),
                      ),
                    ),
                  );
                }).toList(),
          ),
        );
      },
    );
  }

  Widget _buildDobbleUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'waiting';
    final List<String> centerCard =
        gameData['dobbleCenterCard'] != null
            ? List<String>.from(gameData['dobbleCenterCard'])
            : [];
    final Map<String, dynamic> playerCards =
        gameData['dobblePlayerCards'] != null
            ? Map<String, dynamic>.from(gameData['dobblePlayerCards'])
            : {};
    final List<String> myCard =
        playerCards[playerId] != null
            ? List<String>.from(playerCards[playerId])
            : [];
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );

    // Récupération des infos pour le HUD
    final List<dynamic> deck = gameData['dobbleDeck'] ?? [];
    final int cardsLeftInDeck = deck.length;
    final int myScore = players[playerId]?['score'] ?? 0;

    // Gestion Game Over
    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Dobble",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.dobbleAllCardsFound,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    // Chargement initial
    if (myCard.isEmpty || centerCard.isEmpty) {
      return Center(
        child: _buildWaitingWidget(
          AppLocalizations.of(context)!.dobbleDealingCards,
          players,
          0,
          0,
        ),
      );
    }

    // Fond d'écran style "Table de jeu"
    return Container(
      width: double.infinity,
      height: double.infinity,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color(0xFF2C3E50),
            Color(0xFF4CA1AF),
          ], // Dégradé Bleu Gris Pro
        ),
      ),
      child: SafeArea(
        child:
            roundState == 'playing'
                ? _buildDobblePlayingUI(
                  context,
                  gameData,
                  playerId,
                  centerCard,
                  myCard,
                  players,
                  cardsLeftInDeck,
                  myScore,
                )
                : _buildDobbleResultUI(
                  context,
                  gameData,
                  playerId,
                  gameData['roundWinnerId'],
                  gameData['commonSymbol'],
                ),
      ),
    );
  }

  Widget _buildDobblePlayingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    List<String> centerCard,
    List<String> myCard,
    Map<String, dynamic> players,
    int cardsLeftInDeck,
    int myScore,
  ) {
    return Stack(
      children: [
        Column(
          children: [
            // 1. SCORES ADVERSAIRES (Bandeau supérieur)
            Container(
              height: 38,
              margin: const EdgeInsets.only(bottom: 4),
              child: ListView(
                scrollDirection: Axis.horizontal,
                physics: BouncingScrollPhysics(),
                children:
                    players.entries
                        .where((e) => e.key != playerId)
                        .map(
                          (e) => Padding(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 4.0,
                            ),
                            child: Chip(
                              backgroundColor: Colors.black.withOpacity(0.45),
                              label: Text(
                                AppLocalizations.of(context)!.str422faa(
                                  e.value['name'],
                                  e.value['score'] ?? 0,
                                ),
