  Widget _getWidgetForRoundState(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final gameType = gameData['gameType'];
    final players = (gameData['players'] as Map<String, dynamic>?) ?? {};
    final answers = (gameData['answers'] as Map<String, dynamic>?) ?? {};
    final votes = (gameData['votes'] as Map<String, dynamic>?) ?? {};
    final isSimplifiedLiar = gameData['isSimplifiedLiar'] ?? false;

    if (gameType == 'Qui Pourrait le Plus ?') {
      if (roundState == 'voting') {
        if (votes.containsKey(playerId)) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.voteEnregistreEnAttenteDes,
            players,
            votes.length,
            players.length,
          );
        }
        return _buildQuiPourraitLePlusVotingUI(context, gameData, playerId);
      }
    }

    if (gameType == 'Skull' &&
        (roundState == 'placing' || roundState == 'bidding')) {
      return _buildSkullUI(context, gameData, playerId);
    }

    switch (roundState) {
      case 'judging_selection':
        return _buildBMCPlayingUI(context, gameData, playerId);

      case 'judge_voting':
        return _buildBMCJudgeVotingUI(context, gameData, playerId);

      case 'playing':
        if (gameType == 'La Patate Chaude') {
          return _buildHotPotatoUI(context, gameData, playerId);
        }
        if (answers.containsKey(playerId)) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.enAttenteDesAutres,
            players,
            answers.length,
            players.length,
          );
        }
        if (gameType == 'Le Juge' &&
            gameData['currentTargetPlayerId'] == playerId) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.lesAutresJoueursRepondent,
            players,
            answers.length,
            players.length - 1,
          );
        }
        return _buildAnsweringUI(context, gameData, playerId);

      case 'answering':
        if (answers.containsKey(playerId)) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.enAttenteDesAutres,
            players,
            answers.length,
            players.length,
          );
        }
        if (gameType == 'Le Juge' &&
            gameData['currentTargetPlayerId'] == playerId) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.lesAutresJoueursRepondent,
            players,
            answers.length,
            players.length - 1,
          );
        }
        return _buildAnsweringUI(context, gameData, playerId);

      case 'declaring_truth':
        final storyTruths = Map.from(
          gameData['storyTruths'] as Map<String, dynamic>? ?? {},
        );
        if (storyTruths.containsKey(playerId)) {
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.enAttenteDesDeclarations,
            players,
            storyTruths.length,
            players.length,
          );
        }
        return _buildDeclaringTruthUI(context, gameData, playerId);

      case 'reveal_and_vote':
        return _buildSimplifiedLiarVotingUI(context, gameData, playerId);

      case 'voting':
        if (votes.containsKey(playerId) && !isSimplifiedLiar) {
          if (gameType == 'Le Juge' &&
              gameData['currentTargetPlayerId'] == playerId) {
            return _buildJudgeVotingUI(context, gameData, true);
          }
          return _buildWaitingWidget(
            AppLocalizations.of(context)!.enAttenteDesVotes,
            players,
            votes.length,
            players.length,
          );
        }
        if (isSimplifiedLiar) {
          return _buildSimplifiedLiarVotingUI(context, gameData, playerId);
        }
        if (gameType == 'Le Juge') {
          return _buildJudgeVotingUI(
            context,
            gameData,
            gameData['currentTargetPlayerId'] == playerId,
          );
        }
        return _buildVotingUI(context, gameData, playerId);

      case 'tie_breaker':
        return _buildUndercoverTieBreakerUI(context, gameData, playerId);

      case 'mrwhite_guess':
        return _buildMrWhiteGuessUI(context, gameData, playerId);

      case 'exploded':
        if (gameType == 'La Patate Chaude') {
          return _buildHotPotatoExplodedUI(context, gameData, playerId);
        }
        return _buildResultUI(context, gameData, playerId);

      case 'result':
        return _buildResultUI(context, gameData, playerId);

      case 'placing':
      case 'bidding':
        if (gameType == 'Skull') {
          return _buildSkullUI(context, gameData, playerId);
        }
        return _buildWaitingWidget(
          AppLocalizations.of(context)!.laPartieContinue,
          players,
          0,
          0,
        );

      default:
        return _buildWaitingWidget(
          AppLocalizations.of(context)!.laPartieVaBientotCommencer,
          players,
          0,
          0,
        );
    }
  }

  Widget _buildMrWhiteGuessUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final mrWhiteId = gameData['mrWhiteId'];
    final isMrWhite = playerId == mrWhiteId;
    final players = (gameData['players'] as Map<String, dynamic>?) ?? {};
    final mrWhiteName =
        players[mrWhiteId]?['name'] ?? AppLocalizations.of(context)!.mrWhite;

    if (!isMrWhite) {
      return _buildWaitingWidget(
        AppLocalizations.of(context)!.aEteDemasqueIlTente(mrWhiteName),
        players,
        0,
        1,
      );
    }

    return Center(
      child: SingleChildScrollView(
        padding: EdgeInsets.all(24),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
