  Widget _buildUndercoverTieBreakerUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = (gameData['players'] as Map<String, dynamic>?) ?? {};
    final votes = (gameData['votes'] as Map<String, dynamic>?) ?? {};
    final candidates = List<String>.from(
      gameData['tieBreakerCandidates'] ?? [],
    );

    if (votes.containsKey(playerId)) {
      return _buildWaitingWidget(
        AppLocalizations.of(context)!.voteDecisifEnregistreEnAttente,
        players,
        votes.length,
        players.length,
      );
    }

    final String? goddessId = gameData['specialRoles']?['justiceGoddess'];
    final bool isGoddess = goddessId != null && goddessId == playerId;

    if (goddessId != null && !isGoddess) {
      return _buildWaitingWidget(
        AppLocalizations.of(context)!.egaliteParfaiteLaDeesseDe,
        players,
        0,
        1,
      );
    }

    return Column(
      children: [
        Card(
          color: Colors.deepOrange.withOpacity(0.2),
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                Icon(Icons.balance, color: Colors.deepOrange, size: 36),
                SizedBox(height: 8),
                Text(
                  AppLocalizations.of(context)!.egaliteParfaite,
                  style: Theme.of(
                    context,
                  ).textTheme.titleLarge?.copyWith(color: Colors.deepOrange),
                ),
                SizedBox(height: 4),
                Text(
                  AppLocalizations.of(context)!.votezUniquementParmiLesSuspects,
                  style: TextStyle(color: Colors.white70),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
        SizedBox(height: 20),
        Expanded(
          child: GridView.builder(
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 2,
              crossAxisSpacing: 12,
              mainAxisSpacing: 12,
              childAspectRatio: 1.2,
            ),
            itemCount: candidates.length,
            itemBuilder: (context, index) {
              final cId = candidates[index];
              final cName =
                  players[cId]?['name'] ?? AppLocalizations.of(context)!.joueur;
              final isMe = cId == playerId;

              return GestureDetector(
                onTap:
                    (isMe || _isActionPending)
                        ? null
                        : () {
                          setState(() => _isActionPending = true);
                          if (goddessId != null && isGoddess) {
                            _firebaseService
                                .undercoverGoddessDecision(widget.gameCode, cId)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          } else {
                            _firebaseService
                                .submitUndercoverVote(
                                  widget.gameCode,
                                  playerId,
                                  cId,
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          }
                        },
                child: Container(
                  decoration: BoxDecoration(
                    color: isMe ? Colors.grey[800] : Colors.deepOrange[700],
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      CircleAvatar(
                        radius: 28,
                        backgroundColor: Colors.white24,
                        child: Text(
                          cName.isNotEmpty ? cName[0] : '?',
                          style: TextStyle(fontSize: 22, color: Colors.white),
                        ),
                      ),
                      SizedBox(height: 8),
                      Text(
                        cName,
                        style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                      if (isMe)
                        Text(
                          AppLocalizations.of(context)!.vous,
                          style: TextStyle(color: Colors.white54, fontSize: 12),
                        ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildBMCPlayingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String question = gameData['bmcQuestion'] ?? '...';
    final String judgeId = gameData['bmcJudgeId'] ?? '';
    final bool isJudge = playerId == judgeId;
    final Map<String, dynamic> hands = Map<String, dynamic>.from(
      gameData['bmcHands'] ?? {},
    );
    List<String> myHand = List<String>.from(hands[playerId] ?? []);
    if (_isHandSorted) {
      myHand = _sortCards(myHand);
    }
    final Map<String, dynamic> playedCards = Map<String, dynamic>.from(
      gameData['bmcPlayedCards'] ?? {},
    );
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final Map<String, dynamic> scores = Map<String, dynamic>.from(
      gameData['bmcScores'] ?? {},
    );
    final bool hasPlayed = playedCards.containsKey(playerId);
    final int totalPlayers = players.length;

    return Column(
      children: [
        // Scores
        Container(
          padding: EdgeInsets.all(8),
          color: Colors.black38,
          child: Wrap(
            alignment: WrapAlignment.center,
            spacing: 12,
            children:
                players.entries.map((e) {
                  return Text(
                    AppLocalizations.of(
                      context,
                    )!.str95d36e(e.value['name'], scores[e.key] ?? 0),
                    style: TextStyle(
                      color: e.key == judgeId ? Colors.amber : Colors.white70,
                      fontWeight:
                          e.key == judgeId
                              ? FontWeight.bold
                              : FontWeight.normal,
                    ),
                  );
                }).toList(),
          ),
        ),
        SizedBox(height: 12),

        // Question
        Card(
          color: Colors.deepPurple[900],
          margin: EdgeInsets.symmetric(horizontal: 16),
          child: Padding(
            padding: EdgeInsets.all(20),
            child: Column(
              children: [
                Text(
                  AppLocalizations.of(context)!.question,
                  style: TextStyle(color: Colors.white54, letterSpacing: 2),
                ),
                SizedBox(height: 8),
                Text(
                  question,
                  style: Theme.of(context).textTheme.headlineSmall,
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
        SizedBox(height: 12),

        if (isJudge) ...[
          Expanded(
            child: Center(
              child: _buildWaitingWidget(
                AppLocalizations.of(context)!.vousEtesLeJugeAttendez,
                players,
                playedCards.length,
                totalPlayers - 1,
              ),
            ),
          ),
        ] else if (hasPlayed) ...[
          Expanded(
            child: Center(
              child: _buildWaitingWidget(
                AppLocalizations.of(context)!.carteJoueeAttenteDesAutres,
                players,
                playedCards.length,
                totalPlayers - 1,
              ),
            ),
          ),
        ] else ...[
          Text(
            AppLocalizations.of(context)!.choisissezUneCarteAJouer,
            style: Theme.of(context).textTheme.titleLarge,
          ),
          SizedBox(height: 8),
          Expanded(
            child: GridView.builder(
              padding: EdgeInsets.all(12),
              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 3,
                childAspectRatio: 1.2,
                crossAxisSpacing: 8,
                mainAxisSpacing: 8,
              ),
              itemCount: myHand.length,
              itemBuilder: (context, index) {
                return GestureDetector(
                  onTap: () {
                    _firebaseService.playBMCCard(
                      widget.gameCode,
                      playerId,
                      myHand[index],
                    );
                  },
                  child: Card(
                    color: Colors.white,
                    elevation: 4,
                    child: Center(
                      child: Padding(
                        padding: EdgeInsets.all(8),
                        child: Text(
                          myHand[index],
                          style: TextStyle(
                            color: Colors.black87,
                            fontWeight: FontWeight.bold,
                            fontSize: 13,
                          ),
                          textAlign: TextAlign.center,
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ],
    );
  }

  Widget _buildBMCJudgeVotingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String judgeId = gameData['bmcJudgeId'] ?? '';
    final bool isJudge = playerId == judgeId;
    final Map<String, dynamic> playedCards = Map<String, dynamic>.from(
      gameData['bmcPlayedCards'] ?? {},
    );
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );

    List<MapEntry<String, String>> shuffledAnswers =
        playedCards.entries
            .map((e) => MapEntry<String, String>(e.key, e.value.toString()))
            .toList()
          ..shuffle();

    return Column(
      children: [
        Text(
          isJudge
              ? AppLocalizations.of(context)!.choisissezLaMeilleureReponse
              : AppLocalizations.of(context)!.leJugeChoisit,
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 16),
        Expanded(
          child: ListView.builder(
            padding: EdgeInsets.all(16),
            itemCount: shuffledAnswers.length,
            itemBuilder: (context, index) {
              var entry = shuffledAnswers[index];
              return Card(
                color: Colors.white,
                margin: EdgeInsets.symmetric(vertical: 6),
                child: ListTile(
                  title: Text(
                    entry.value,
                    style: TextStyle(
                      color: Colors.black87,
                      fontWeight: FontWeight.bold,
                      fontSize: 16,
                    ),
                  ),
                  subtitle:
                      !isJudge
                          ? Text(
                            AppLocalizations.of(context)!.enAttenteDuChoixDu,
                            style: TextStyle(color: Colors.grey, fontSize: 11),
                          )
                          : null,
                  trailing:
                      isJudge
                          ? ElevatedButton(
                            onPressed: () {
                              _firebaseService.judgeBMCWinner(
                                widget.gameCode,
                                entry.key,
                              );
                            },
                            child: Text(AppLocalizations.of(context)!.choisir),
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.green,
                            ),
                          )
                          : null,
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildAnsweringUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final gameType = gameData['gameType'];
    final String? memeUrl = gameData['memeUrl']; // 1. Récupérer l'URL

    Widget? secretInfoWidget;

    // 2. Si c'est le jeu des mèmes, on prépare l'image
    if (gameType == 'Le Roi des Mèmes' && memeUrl != null) {
      secretInfoWidget = Container(
        constraints: BoxConstraints(maxHeight: 300), // Limiter la hauteur
        margin: EdgeInsets.only(bottom: 10),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Image.network(
            memeUrl,
            fit: BoxFit.contain,
            loadingBuilder: (context, child, loadingProgress) {
              if (loadingProgress == null) return child;
              return Center(child: CircularProgressIndicator());
            },
            errorBuilder: (context, error, stackTrace) {
              return Text(
                AppLocalizations.of(context)!.impossibleDeChargerLImage,
                style: TextStyle(color: Colors.red),
              );
            },
          ),
        ),
      );
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: EdgeInsets.only(
            bottom: MediaQuery.of(context).viewInsets.bottom + 16,
          ),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16.0),
                    child: Text(
                      gameData['currentQuestion'] ??
                          AppLocalizations.of(context)!.question1,
                      textAlign: TextAlign.center,
                      style: Theme.of(context).textTheme.headlineSmall,
                    ),
                  ),
                ),
                SizedBox(height: 20),

                // 3. Afficher le widget secret (l'image du mème)
                if (secretInfoWidget != null) secretInfoWidget,

                SizedBox(height: 20),
                TextField(
                  controller: _answerController,
                  decoration: InputDecoration(
                    labelText: AppLocalizations.of(context)!.votreReponse,
                  ),
                  maxLines: 1,
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      _isActionPending || _answerController.text.trim().isEmpty
                          ? null
                          : () {
                            setState(() => _isActionPending = true);

                            _firebaseService
                                .submitAnswer(
                                  widget.gameCode,
                                  playerId,
                                  _answerController.text.trim(),
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                  child:
                      _isActionPending
                          ? SizedBox(
                            height: 20,
                            width: 20,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                          : Text(AppLocalizations.of(context)!.soumettre),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

