  // Helper pour les boutons animés
  Widget _buildAnimatedTruthButton({
    required String label,
    required Color color,
    required IconData icon,
    required VoidCallback? onTap,
  }) {
    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: Duration(milliseconds: 200),
        width: 100,
        height: 100,
        decoration: BoxDecoration(
          color: onTap == null ? Colors.grey : color.withOpacity(0.2),
          borderRadius: BorderRadius.circular(15),
          border: Border.all(
            color: onTap == null ? Colors.grey : color,
            width: 2,
          ),
          boxShadow:
              onTap != null
                  ? [BoxShadow(color: color.withOpacity(0.4), blurRadius: 10)]
                  : [],
        ),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(icon, size: 40, color: onTap == null ? Colors.black45 : color),
            SizedBox(height: 8),
            Text(
              label,
              style: TextStyle(
                fontWeight: FontWeight.bold,
                color: onTap == null ? Colors.black45 : color,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSimplifiedLiarVotingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String voterId,
  ) {
    final players = gameData['players'] as Map<String, dynamic>;
    final answers = gameData['answers'] as Map<String, dynamic>;
    final allVotes = Map.from(gameData['votes'] as Map<String, dynamic>? ?? {});
    final voteMode = gameData['liarVoteMode'];

    if (voteMode == 'turn_by_turn') {
      // ... (Gardez la logique 'turn_by_turn' existante, elle est fonctionnelle. On peut juste styliser la carte principale)
      // Pour ne pas tout recopier, je focus sur la liste complète qui est plus utilisée.
      // Vous pouvez appliquer le même style de Card que ci-dessous.
      final playerOrder = List<String>.from(gameData['playerOrder']);
      final revealIndex = gameData['revealIndex'] as int;
      final storyOwnerId = playerOrder[revealIndex];
      final storyOwnerName =
          players[storyOwnerId]?['name'] ??
          AppLocalizations.of(context)!.inconnu;
      final story = answers[storyOwnerId];
      final storyVotes = Map.from(
        allVotes[storyOwnerId] as Map<String, dynamic>? ?? {},
      );

      if (storyVotes.containsKey(voterId)) {
        return _buildWaitingWidget(
          AppLocalizations.of(context)!.voteEnregistre,
          players,
          storyVotes.length,
          players.length - 1,
        );
      }
      if (storyOwnerId == voterId) {
        return _buildWaitingWidget(
          AppLocalizations.of(context)!.lesAutresJugentTonHistoire,
          players,
          storyVotes.length,
          players.length - 1,
        );
      }

      return Center(
        child: Card(
          elevation: 10,
          margin: EdgeInsets.all(16),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircleAvatar(child: Text(storyOwnerName[0]), radius: 30),
                SizedBox(height: 10),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.lHistoireDe,
                    [storyOwnerName],
                  ),
                  style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                ),
                Divider(),
                SizedBox(height: 20),
                Text(
                  '"$story"',
                  style: TextStyle(fontSize: 18, fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 40),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    _buildAnimatedTruthButton(
                      label: AppLocalizations.of(context)!.vrai,
                      color: Colors.green,
                      icon: Icons.thumb_up,
                      onTap:
                          _isActionPending
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitSimplifiedLiarVote(
                                      widget.gameCode,
                                      voterId,
                                      storyOwnerId,
                                      AppLocalizations.of(context)!.vrai1,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                    ),
                    _buildAnimatedTruthButton(
                      label: AppLocalizations.of(context)!.faux,
                      color: Colors.red,
                      icon: Icons.thumb_down,
                      onTap:
                          _isActionPending
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitSimplifiedLiarVote(
                                      widget.gameCode,
                                      voterId,
                                      storyOwnerId,
                                      AppLocalizations.of(context)!.faux1,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      );
    } else {
      // Mode Simultané : Liste
      return Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              AppLocalizations.of(context)!.detecteurDeMensonges,
              style: Theme.of(
                context,
              ).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold),
            ),
          ),
          Expanded(
            child: ListView.builder(
              itemCount: answers.length,
              padding: EdgeInsets.symmetric(horizontal: 16),
              itemBuilder: (context, index) {
                final entry = answers.entries.elementAt(index);
                if (entry.key == voterId)
                  return SizedBox.shrink(); // Pas ma propre histoire

                final storyOwnerId = entry.key;
                final storyOwnerName =
                    players[storyOwnerId]?['name'] ??
                    AppLocalizations.of(context)!.inconnu;
                final story = entry.value;
                final myVote =
                    (allVotes[storyOwnerId] as Map<String, dynamic>?)?[voterId];
                bool isVoted = myVote != null;

                return AnimatedContainer(
                  duration: Duration(milliseconds: 300),
                  margin: EdgeInsets.only(bottom: 12),
                  decoration: BoxDecoration(
                    color: isVoted ? Colors.grey[900] : Colors.deepPurple[800],
                    borderRadius: BorderRadius.circular(15),
