                      ),
                      IconButton(
                        onPressed:
                            selectedBid < maximumBid
                                ? () {
                                  setStateModal(() => selectedBid++);
                                  _firebaseService.updateLiveBidOrRaise(
                                    widget.gameCode,
                                    playerId,
                                    selectedBid,
                                  );
                                }
                                : null,
