  // --- TCHAT COMPACT & MODERNE ---
  Widget _buildChatInterface(
    Map<String, dynamic> gameData,
    String playerId, {
    bool isLiveStyle = false,
  }) {
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final myStatus = myData['status'] ?? 'vivant';
    final myRole = myData['role'] ?? AppLocalizations.of(context)!.inconnu;
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool amIDead = myStatus == 'mort';
    final bool amILover = (gameData['lovers'] ?? []).contains(playerId);
    final bool amINecromancer =
        myRole == AppLocalizations.of(context)!.necromancien;
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    List<dynamic> currentChatMessages = [];
    bool canSendMessage = false;

    switch (_selectedChatType) {
      case 'wolf':
        canSendMessage = amILoup && !amIDead;
        break;
      case 'dead':
        canSendMessage = amIDead || amINecromancer;
        break;
      case 'lover':
        canSendMessage = amILover && !amIDead;
        break;
      default:
        canSendMessage = !amIDead;
        break;
    }

    return Container(
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: Color(0xFF0B1120).withOpacity(0.75),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.white.withOpacity(0.08)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Onglets de canaux
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                _buildChatTab(
                  AppLocalizations.of(context)!.village,
                  'global',
                  Colors.blueAccent,
                ),
                if (amILoup || (amIDead && amILoup)) ...[
                  SizedBox(width: 4),
                  _buildChatTab(
                    AppLocalizations.of(context)!.loups,
                    'wolf',
                    Colors.redAccent,
                  ),
                ],
                if (amIDead || amINecromancer) ...[
                  SizedBox(width: 4),
                  _buildChatTab(
                    AppLocalizations.of(context)!.outreTombe,
                    'dead',
                    Colors.purpleAccent,
                  ),
                ],
                if (amILover && lovers.length == 2) ...[
                  SizedBox(width: 4),
                  _buildChatTab(
                    AppLocalizations.of(context)!.amoureux,
                    'lover',
                    Colors.pinkAccent,
                  ),
                ],
              ],
            ),
          ),
          SizedBox(height: 4),

          // Messages
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: _firebaseService.getChatStream(
                widget.gameCode,
                _selectedChatType,
              ),
              builder: (context, snapshot) {
                final docs = snapshot.hasData ? snapshot.data!.docs : [];
                return ListView.builder(
                  reverse: false,
                  physics: BouncingScrollPhysics(),
                  itemCount: docs.length,
                  itemBuilder: (context, index) {
                    final messageData =
                        docs[docs.length - 1 - index].data()
                            as Map<String, dynamic>;
                    final senderId = messageData['senderId'];
                    final senderName =
                        messageData['senderName'] ??
                        AppLocalizations.of(context)!.inconnu;
                    final message =
                        messageData['text'] ?? messageData['message'] ?? '';
                    final isMine = senderId == playerId;

                    return Padding(
                      padding: const EdgeInsets.symmetric(vertical: 1.5),
                      child: RichText(
                        text: TextSpan(
                          style: TextStyle(fontSize: 11, color: Colors.white),
                          children: [
                            TextSpan(
                              text:
                                  isMine
                                      ? "${AppLocalizations.of(context)!.moi}: "
                                      : "$senderName: ",
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                color:
                                    isMine
                                        ? Colors.cyanAccent
                                        : (_selectedChatType == 'wolf'
                                            ? Colors.redAccent.shade100
                                            : Colors.white60),
                              ),
                            ),
                            TextSpan(text: message),
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),

          // Barre d'envoi compacte
          if (canSendMessage)
            Row(
              children: [
                Expanded(
                  child: SizedBox(
                    height: 32,
                    child: TextField(
                      controller: _chatController,
                      style: const TextStyle(fontSize: 12, color: Colors.white),
                      decoration: InputDecoration(
                        hintText: AppLocalizations.of(context)!.ecrireAu(
                          _selectedChatType == 'wolf'
                              ? AppLocalizations.of(context)!.meute
                              : AppLocalizations.of(context)!.village,
                        ),
                        hintStyle: const TextStyle(
                          color: Colors.white30,
                          fontSize: 11,
                        ),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(16),
                          borderSide: BorderSide.none,
                        ),
                        filled: true,
                        fillColor: Colors.white.withOpacity(0.08),
                        contentPadding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 0,
                        ),
                      ),
                      onSubmitted: (text) {
                        if (text.trim().isNotEmpty) {
                          _firebaseService.sendChatMessage(
                            widget.gameCode,
                            playerId,
                            text.trim(),
                            _selectedChatType,
                          );
                          _chatController.clear();
                        }
                      },
                    ),
                  ),
                ),
                const SizedBox(width: 4),
                IconButton(
                  icon: const Icon(
                    Icons.send_rounded,
                    size: 18,
                    color: Colors.cyanAccent,
                  ),
                  padding: EdgeInsets.zero,
                  constraints: const BoxConstraints(),
                  onPressed: () {
                    if (_chatController.text.trim().isNotEmpty) {
                      _firebaseService.sendChatMessage(
                        widget.gameCode,
                        playerId,
                        _chatController.text.trim(),
                        _selectedChatType,
                      );
                      _chatController.clear();
                    }
                  },
                ),
              ],
            ),
        ],
      ),
    );
  }

  Widget _buildChatTab(String label, String type, Color activeColor) {
    final bool isSelected = _selectedChatType == type;
    return GestureDetector(
      onTap: () => setState(() => _selectedChatType = type),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          color:
              isSelected
                  ? activeColor.withOpacity(0.25)
                  : Colors.white.withOpacity(0.04),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color:
                isSelected ? activeColor.withOpacity(0.6) : Colors.transparent,
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 10,
            fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
            color: isSelected ? activeColor : Colors.white60,
          ),
        ),
      ),
    );
  }

  // --- MISE À JOUR DE L'AVATAR POUR LE RENDRE INTERACTIF ---

  Widget _buildSyncTimer(Timestamp? startTime, int durationInSeconds) {
    if (startTime == null) return const SizedBox.shrink();

    // TweenAnimationBuilder permet un chrono visuel super fluide sans Timer bloquant et setState manuel, ce qui allège grandement le thread (Point 4)
    final endTime = startTime.toDate().add(
      Duration(seconds: durationInSeconds),
    );
    final remaining = endTime.difference(DateTime.now());

    if (remaining.isNegative)
      return Text(
        "0 s",
        style: Theme.of(
          context,
        ).textTheme.headlineSmall?.copyWith(color: Colors.redAccent),
      );

    return TweenAnimationBuilder<Duration>(
      duration: remaining,
      tween: Tween(begin: remaining, end: Duration.zero),
      builder: (BuildContext context, Duration value, Widget? child) {
        final seconds = value.inSeconds;
        return Text(
          AppLocalizations.of(context)!.tempsRestantS1(seconds),
          style: Theme.of(context).textTheme.headlineSmall?.copyWith(
            color: seconds < 20 ? Colors.redAccent : Colors.amberAccent,
          ),
        );
      },
    );
  }

  Widget _buildPetitsChevauxUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(
      gameData['petitsChevauxPlayerOrder'] ?? [],
    );
    final positions = Map<String, dynamic>.from(
      gameData['petitsChevauxPositions'] ?? {},
    );
    final int currentIndex = gameData['petitsChevauxCurrentIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final int dice = (gameData['petitsChevauxDice'] as num?)?.toInt() ?? 0;
    final bool hasRolled = gameData['petitsChevauxHasRolled'] ?? false;
    final bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
    final Map<String, dynamic> consecutiveSixes = Map<String, dynamic>.from(
      gameData['petitsChevauxConsecutiveSixes'] ?? {},
    );
    final int mySixStreak = consecutiveSixes[playerId] ?? 0;

    // Palette moderne fluo / arcade sur fond sombre
    final List<Color> playerColors = [
      const Color(0xFFEF4444), // Rouge néon
      const Color(0xFF38BDF8), // Bleu ciel néon
      const Color(0xFF10B981), // Vert émeraude
      const Color(0xFFF59E0B), // Ambre doré
    ];

    // --- ÉCRAN DE VICTOIRE ---
    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Petits Chevaux",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.arriveeAuCentreDuPlateau,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        // 1. BANDEAU D'ÉTAT SUPÉRIEUR ÉLÉGANT
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          decoration: BoxDecoration(
            color: isMyTurn ? Color(0xFF261E3E) : Color(0xFF14141E),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color:
                  isMyTurn
                      ? Colors.greenAccent.withOpacity(0.6)
                      : Colors.white10,
              width: 1.5,
            ),
            boxShadow: [
              if (isMyTurn)
                BoxShadow(
                  color: Colors.greenAccent.withOpacity(0.15),
                  blurRadius: 10,
                ),
            ],
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(6),
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color:
                          isMyTurn
                              ? Colors.greenAccent.withOpacity(0.2)
                              : Colors.white10,
                    ),
                    child: Icon(
                      Icons.casino_rounded,
                      size: 16,
                      color: isMyTurn ? Colors.greenAccent : Colors.white60,
                    ),
                  ),
                  SizedBox(width: 8),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        isMyTurn
                            ? (hasRolled
                                ? AppLocalizations.of(context)!.deplacezUnCheval
                                : AppLocalizations.of(context)!.aVousDeLancer)
                            : GameContentLocalization.format(
                              context,
                              AppLocalizations.of(context)!.tourDe,
                              [players[currentPlayerId]?['name'] ?? ''],
                            ),
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1,
                          color: isMyTurn ? Colors.greenAccent : Colors.white60,
                        ),
                      ),
                      Text(
                        isTeamMode
                            ? AppLocalizations.of(context)!.mode2v2Allies
                            : AppLocalizations.of(context)!.courseIndividuelle,
                        style: TextStyle(fontSize: 10, color: Colors.white38),
                      ),
                    ],
                  ),
                ],
              ),
              if (mySixStreak > 0)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.amberAccent.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: Colors.amberAccent.withOpacity(0.5),
                    ),
                  ),
                  child: Row(
                    children: [
                      Icon(
                        Icons.bolt_rounded,
                        size: 13,
                        color: Colors.amberAccent,
                      ),
                      SizedBox(width: 2),
                      Text(
                        AppLocalizations.of(context)!.k6Consecutifs3,
                        style: TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                          color: Colors.amberAccent,
                        ),
                      ),
                    ],
                  ),
                ),
            ],
          ),
        ),

        Expanded(
          flex: 4,
          child: LayoutBuilder(
            builder: (context, constraints) {
              final double boardSize =
                  min(constraints.maxWidth, constraints.maxHeight) * 0.96;
              final cellSize = boardSize / 15;

              return StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getLudoHoverStream(widget.gameCode),
                builder: (context, hoverSnap) {
                  String? hoveredOwner;
                  int? hoveredPawnIdx;
                  if (hoverSnap.hasData &&
                      hoverSnap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        hoverSnap.data!.snapshot.value as Map,
                      );
                      hoveredOwner = raw['ownerId'] as String?;
                      hoveredPawnIdx = raw['pawnIndex'] as int?;
                    } catch (_) {}
                  }

                  Offset? ghostDestination;
                  if (hoveredOwner != null &&
                      hoveredPawnIdx != null &&
                      dice > 0) {
                    final pList = List<int>.from(
                      positions[hoveredOwner] ?? [-1, -1, -1, -1],
                    );
                    final curP = pList[hoveredPawnIdx];
                    final pIdx = playerOrder.indexOf(hoveredOwner);
                    if (curP == -1 && (dice == 1 || dice == 6)) {
                      ghostDestination = _getLudoPathPosition(
                        0,
                        pIdx % 4,
                        cellSize,
                      );
                    } else if (curP >= 0 && curP + dice <= 56) {
                      final targetP = curP + dice;
                      if (targetP <= 50) {
                        ghostDestination = _getLudoPathPosition(
                          targetP,
                          pIdx % 4,
                          cellSize,
                        );
                      } else {
                        ghostDestination = _getLudoHomePosition(
                          targetP - 51,
                          pIdx % 4,
                          cellSize,
                        );
                      }
                    }
                  }

                  return Center(
                    child: Container(
                      width: boardSize,
                      height: boardSize,
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(24),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withOpacity(0.7),
                            blurRadius: 20,
                            offset: Offset(0, 8),
                          ),
                        ],
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(24),
                        child: Stack(
                          alignment: Alignment.center,
                          children: [
                            CustomPaint(
                              size: Size(boardSize, boardSize),
                              painter: _LudoBoardPainter(playerColors),
                            ),
                            if (ghostDestination != null)
                              Positioned(
                                left: ghostDestination.dx - (cellSize * 0.45),
                                top: ghostDestination.dy - (cellSize * 0.45),
                                child: Container(
                                  width: cellSize * 0.9,
                                  height: cellSize * 0.9,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: Colors.amberAccent.withOpacity(0.4),
                                    border: Border.all(
                                      color: Colors.amberAccent,
                                      width: 2,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: Colors.amberAccent.withOpacity(
                                          0.6,
                                        ),
                                        blurRadius: 10,
                                        spreadRadius: 2,
                                      ),
                                    ],
                                  ),
                                  child: Icon(
                                    Icons.gps_fixed,
                                    color: Colors.amberAccent,
                                    size: 16,
                                  ),
                                ),
                              ),
                            ..._buildLudoPawns(
                              boardSize,
                              positions,
                              playerOrder,
                              playerColors,
                              playerId,
                              isMyTurn,
                              dice,
                              hasRolled,
                              widget.gameCode,
                              _firebaseService,
                              isTeamMode,
                              selectedOwnerId: _selectedLudoPawnOwner,
                              selectedPawnIdx: _selectedLudoPawnIdx,
                              onPawnTap: (ownerId, pawnIdx) {
                                if (!isMyTurn || !hasRolled || dice <= 0)
                                  return;
                                if (_selectedLudoPawnOwner == ownerId &&
                                    _selectedLudoPawnIdx == pawnIdx) {
                                  // 2e clic : Confirmation et déplacement !
                                  HapticFeedback.mediumImpact();
                                  _firebaseService.updateLudoPawnHover(
                                    widget.gameCode,
                                    playerId,
                                    null,
                                    null,
                                  );
                                  setState(() {
                                    _selectedLudoPawnIdx = null;
                                    _selectedLudoPawnOwner = null;
                                  });
                                  _firebaseService
                                      .movePawnPetitsChevaux(
                                        widget.gameCode,
                                        playerId,
                                        ownerId,
                                        pawnIdx,
                                      )
                                      .catchError((e) {
                                        debugPrint(e.toString());
                                      });
                                } else {
                                  // 1er clic : Sélection et diffusion live RTDB
                                  HapticFeedback.selectionClick();
                                  setState(() {
                                    _selectedLudoPawnIdx = pawnIdx;
                                    _selectedLudoPawnOwner = ownerId;
                                  });
                                  _firebaseService.updateLudoPawnHover(
                                    widget.gameCode,
                                    playerId,
                                    ownerId,
                                    pawnIdx,
                                  );
                                }
                              },
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              );
            },
          ),
        ),

        // 3. ZONE DÉ & COMMANDES TACTILES
        Container(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
          decoration: BoxDecoration(
            color: Color(0xFF101018),
            borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
            border: Border.all(color: Colors.white10),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              // Dé 3D avec vrais points
              _Ludo3DDice(
                value: dice,
                isRolling: false,
                isMyTurn: isMyTurn && !hasRolled,
                onTap:
                    isMyTurn && !hasRolled
                        ? () {
                          setState(() {
                            _selectedLudoPawnIdx = null;
                            _selectedLudoPawnOwner = null;
                          });
                          _firebaseService.updateLudoPawnHover(
                            widget.gameCode,
                            playerId,
                            null,
                            null,
                          );
                          _firebaseService.rollDicePetitsChevaux(
                            widget.gameCode,
                            playerId,
                          );
                        }
                        : null,
              ),

              // Actions
              Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  if (isMyTurn && !hasRolled)
                    ElevatedButton.icon(
                      icon: Icon(Icons.casino_rounded, size: 20),
                      label: Text(AppLocalizations.of(context)!.lancerLeDe),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.deepPurpleAccent,
                        foregroundColor: Colors.white,
                        padding: const EdgeInsets.symmetric(
                          horizontal: 20,
                          vertical: 12,
                        ),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                      ),
                      onPressed: () {
                        setState(() {
                          _selectedLudoPawnIdx = null;
                          _selectedLudoPawnOwner = null;
                        });
                        _firebaseService.updateLudoPawnHover(
                          widget.gameCode,
                          playerId,
                          null,
                          null,
                        );
                        _firebaseService.rollDicePetitsChevaux(
                          widget.gameCode,
                          playerId,
                        );
                      },
                    )
                  else if (isMyTurn && hasRolled)
                    Row(
                      children: [
                        Text(
                          _selectedLudoPawnIdx != null
                              ? AppLocalizations.of(
                                context,
                              )!.chevalSelectionneNtouchezPourAvancer
                              : AppLocalizations.of(context)!.touchezUnPion,
                          style: TextStyle(
                            color:
                                _selectedLudoPawnIdx != null
                                    ? Colors.amberAccent
                                    : Colors.greenAccent,
                            fontWeight: FontWeight.bold,
                            fontSize: _selectedLudoPawnIdx != null ? 11 : 13,
                          ),
                        ),
                        SizedBox(width: 12),
                        OutlinedButton.icon(
                          icon: Icon(Icons.skip_next_rounded, size: 16),
                          label: Text(AppLocalizations.of(context)!.passer),
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.white60,
                            side: BorderSide(color: Colors.white24),
                            padding: const EdgeInsets.symmetric(
                              horizontal: 14,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                          ),
                          onPressed: () {
                            setState(() {
                              _selectedLudoPawnIdx = null;
                              _selectedLudoPawnOwner = null;
                            });
                            _firebaseService.updateLudoPawnHover(
                              widget.gameCode,
                              playerId,
                              null,
                              null,
                            );
                            _firebaseService.passTurnPetitsChevaux(
                              widget.gameCode,
                              playerId,
                            );
                          },
                        ),
                      ],
                    )
                  else
                    Row(
                      children: [
                        SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: Colors.white38,
                          ),
                        ),
                        SizedBox(width: 8),
                        Text(
                          AppLocalizations.of(context)!.reflechit,
                          style: TextStyle(
                            color: Colors.white54,
                            fontSize: 12,
                            fontStyle: FontStyle.italic,
                          ),
                        ),
                      ],
                    ),
                ],
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildDominoesUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // ── Extraction des données ───────────────────────────────────────────────
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    if (gameData['gameState'] == 'gameOver') {
      final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
      return UniversalGameEndScreen(
        gameTitle: AppLocalizations.of(context)!.dominos,
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.scoreLimiteAtteint,
        players: players,
        customScores: scores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }
    final playerOrder = List<String>.from(
      gameData['dominoesPlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['dominoesCurrentPlayerIndex'] ?? 0;
    final currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final bool isHost = gameData['hostId'] == playerId;

    final hands = Map<String, dynamic>.from(
      gameData['dominoesPlayerHands'] ?? {},
    );
    final myHand = List<String>.from(hands[playerId] ?? []);
    final openEnds = List<int>.from(gameData['dominoesOpenEnds'] ?? []);
    final boardChain = List<dynamic>.from(gameData['dominoesBoardChain'] ?? []);
    final boneyard = List<String>.from(gameData['dominoesBoneyard'] ?? []);
    final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
    final bool roundOver = gameData['dominoesRoundOver'] ?? false;
    final String mode =
        gameData['dominoesMode'] ?? AppLocalizations.of(context)!.pioche3;
    final bool isDrawMode =
        mode.toLowerCase() == 'pioche' ||
        mode.toLowerCase() == 'draw' ||
        mode.toLowerCase() == 'robo' ||
        mode == AppLocalizations.of(context)!.pioche3;

    void _showOpponentSheet(String pId) {
      final oppName = players[pId]?['name'] ?? pId;
      final oppScore = scores[pId] ?? 0;
      final oppHand = List<String>.from(hands[pId] ?? []);

      showModalBottomSheet(
        context: context,
        backgroundColor: Colors.transparent,
        builder:
            (ctx) => Container(
              padding: const EdgeInsets.all(24),
              decoration: BoxDecoration(
                color: Color(0xFF1E1E2C),
                borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    oppName,
                    style: TextStyle(
                      fontSize: 22,
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                    ),
                  ),
                  SizedBox(height: 10),
                  Text(
                    AppLocalizations.of(context)!.scorePoints,
                    style: TextStyle(fontSize: 18, color: Colors.amberAccent),
                  ),
                  SizedBox(height: 10),
                  Text(
                    AppLocalizations.of(context)!.dominosRestants,
                    style: TextStyle(color: Colors.white70),
                  ),
                  SizedBox(height: 20),
                  Wrap(
                    spacing: 4,
                    runSpacing: 4,
                    alignment: WrapAlignment.center,
                    children: List.generate(
                      oppHand.length,
                      (_) => Container(
                        width: 16,
                        height: 28,
                        decoration: BoxDecoration(
                          color: Colors.white24,
                          borderRadius: BorderRadius.circular(4),
                        ),
                      ),
                    ),
                  ),
                  SizedBox(height: 20),
                ],
              ),
            ),
      );
    }

    // ┌── Helpers ────────────────────────────────────────────────────────
    bool canPlayTile(String tile) {
      if (openEnds.isEmpty) return true;
      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      return openEnds.contains(a) || openEnds.contains(b);
    }

    bool hasPlayableTile() => myHand.any(canPlayTile);

    void _playTile(String tile, int matchEnd) {
      _firebaseService
          .playDominoesTile(widget.gameCode, playerId, tile, matchEnd)
          .then((_) {
            if (mounted) {
              setState(() => _selectedDominoTile = null);
            }
          })
          .catchError((e) {
            if (mounted) {
              setState(() => _selectedDominoTile = null);
              ScaffoldMessenger.of(
                context,
              ).showSnackBar(SnackBar(content: Text(e.toString())));
            }
          });
    }

    void onTileTap(String tile) {
      if (!isMyTurn || roundOver) return;
      if (!canPlayTile(tile)) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              AppLocalizations.of(context)!.impossibleDeJouerCeDomino,
            ),
          ),
        );
        return;
      }

      if (_selectedDominoTile == tile) {
        setState(() => _selectedDominoTile = null);
        return;
      }

      if (boardChain.isEmpty) {
        _playTile(tile, -1);
        return;
      }

      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      final validEnds =
          openEnds.where((e) => e == a || e == b).toSet().toList();

      if (validEnds.length == 1) {
        _playTile(tile, validEnds.first);
      } else if (validEnds.length > 1) {
        HapticFeedback.selectionClick();
        setState(() => _selectedDominoTile = tile);
      }
    }

    // ── Build ─────────────────────────────────────────────────────────────────
    return Column(
      children: [
        if (roundOver && gameData['gameState'] != 'gameOver')
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
            color: Colors.black87,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  AppLocalizations.of(context)!.mancheTerminee,
                  style: TextStyle(
                    color: Colors.amberAccent,
                    fontWeight: FontWeight.bold,
                    fontSize: 14,
                  ),
                ),
                SizedBox(width: 12),
                if (isHost)
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.green,
                      foregroundColor: Colors.white,
                    ),
                    onPressed:
                        () => _firebaseService.startNextDominoesRound(
                          widget.gameCode,
                        ),
                    child: Text(AppLocalizations.of(context)!.mancheSuivante),
                  )
                else
                  Text(
                    AppLocalizations.of(context)!.enAttenteDeLHote1,
                    style: TextStyle(color: Colors.white70, fontSize: 13),
                  ),
              ],
            ),
          ),

        // ── Barre de scores allégée ──────────────────────────────────────────
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
          color: Colors.black.withOpacity(0.35),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                AppLocalizations.of(context)!.dominos,
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.w500,
                  fontSize: 15,
                ),
              ),
              Row(
                children:
                    playerOrder.map((pId) {
                      final isActive = pId == currentPlayerId;
                      return GestureDetector(
                        onTap:
                            () =>
                                pId != playerId
                                    ? _showOpponentSheet(pId)
                                    : null,
                        child: Container(
                          margin: const EdgeInsets.only(left: 8),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color:
                                isActive
                                    ? Colors.green.withOpacity(0.2)
                                    : Colors.white.withOpacity(0.08),
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(
                              color:
                                  isActive
                                      ? Colors.greenAccent.withOpacity(0.5)
                                      : Colors.white.withOpacity(0.12),
                            ),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(
                                players[pId]?['name']
                                        ?.toString()
                                        .split(' ')
                                        .first ??
                                    pId,
                                style: TextStyle(
                                  color:
                                      isActive
                                          ? Color(0xFF6ee7b7)
                                          : Colors.white70,
                                  fontSize: 12,
                                ),
                              ),
                              SizedBox(width: 6),
                              Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 4,
                                  vertical: 2,
                                ),
                                decoration: BoxDecoration(
                                  color: Colors.black54,
                                  borderRadius: BorderRadius.circular(4),
                                ),
                                child: Text(
                                  "${(hands[pId] as List?)?.length ?? 0}",
                                  style: TextStyle(
                                    fontSize: 10,
                                    color: Colors.amber,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    }).toList(),
              ),
            ],
          ),
        ),

        // ── Barre extrémités ouvertes ──────────────────────────────────────
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 5),
          color: Colors.black.withOpacity(0.2),
          child: Row(
            children: [
              Text(
                AppLocalizations.of(context)!.extremites,
                style: TextStyle(color: Colors.white38, fontSize: 11),
              ),
              if (openEnds.isEmpty)
                Text("—", style: TextStyle(color: Colors.white24, fontSize: 11))
              else
                ...openEnds.map(
                  (e) => Container(
                    margin: const EdgeInsets.only(right: 6),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 2,
                    ),
                    decoration: BoxDecoration(
                      color: Color(0xFF34d399).withOpacity(0.15),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(
                        color: Color(0xFF34d399).withOpacity(0.35),
                      ),
                    ),
                    child: Text(
                      '$e',
                      style: TextStyle(
                        color: Color(0xFF6ee7b7),
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                ),
              Spacer(),
              if (isDrawMode)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: Text(
                    AppLocalizations.of(context)!.pioche2,
                    style: TextStyle(color: Colors.white38, fontSize: 11),
                  ),
                ),
            ],
          ),
        ),

        // ── Plateau de jeu avec overlay de choix direct ───────────────────
        Expanded(
          flex: 4,
          child: Container(
            margin: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: Color(0xFF3a7bd5),
              borderRadius: BorderRadius.circular(16),
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(16),
              child: Stack(
                children: [
                  DominoesBoardWidget(
                    chain:
                        boardChain
                            .map((e) => Map<String, dynamic>.from(e))
                            .toList(),
                    selectedTile: _selectedDominoTile,
                    onEndTap: (matchEnd) {
                      if (_selectedDominoTile != null) {
                        _playTile(_selectedDominoTile!, matchEnd);
                      }
                    },
                  ),
                ],
              ),
            ),
          ),
        ),

        // ── Rack du joueur ──────────────────────────────────────────────────
        Expanded(
          flex: 3,
          child: Container(
            decoration: BoxDecoration(
              color: Colors.black.withOpacity(0.6),
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(24),
              ),
              border: Border(
                top: BorderSide(color: Colors.white.withOpacity(0.1)),
              ),
            ),
            child: Column(
              children: [
                // Indicateur de tour + actions
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 10, 12, 4),
                  child: Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 14,
                          vertical: 5,
                        ),
                        decoration: BoxDecoration(
                          color:
                              isMyTurn
                                  ? Colors.green.withOpacity(0.15)
                                  : Colors.transparent,
                          borderRadius: BorderRadius.circular(20),
                          border:
                              isMyTurn
                                  ? Border.all(
                                    color: Colors.greenAccent.withOpacity(0.5),
                                    width: 1.2,
                                  )
                                  : null,
                        ),
                        child: Text(
                          isMyTurn
                              ? AppLocalizations.of(context)!.cEstVotreTour
                              : GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.tourDe,
                                [players[currentPlayerId]?['name'] ?? '...'],
                              ),
                          style: TextStyle(
                            color:
                                isMyTurn ? Color(0xFF34d399) : Colors.white38,
                            fontSize: 13,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ),
                      Spacer(),
                      // Bouton pioche
                      if (isMyTurn &&
                          !roundOver &&
                          isDrawMode &&
                          boneyard.isNotEmpty &&
                          !hasPlayableTile())
                        TextButton(
                          onPressed:
                              () => _firebaseService
                                  .drawDominoesTile(widget.gameCode, playerId)
                                  .catchError(
                                    (e) => ScaffoldMessenger.of(
                                      context,
                                    ).showSnackBar(
                                      SnackBar(content: Text(e.toString())),
                                    ),
                                  ),
                          child: Text(
                            AppLocalizations.of(context)!.piocher,
                            style: TextStyle(
                              color: Colors.white70,
                              fontSize: 12,
                            ),
                          ),
                        ),
                      // Bouton passer
                      if (isMyTurn &&
                          !roundOver &&
                          (boneyard.isEmpty ||
                              mode != AppLocalizations.of(context)!.pioche3) &&
                          !hasPlayableTile())
                        TextButton(
                          onPressed:
                              () => _firebaseService
                                  .passDominoesTurn(widget.gameCode, playerId)
                                  .catchError(
                                    (e) => ScaffoldMessenger.of(
                                      context,
                                    ).showSnackBar(
                                      SnackBar(content: Text(e.toString())),
                                    ),
                                  ),
                          child: Text(
                            AppLocalizations.of(context)!.passer,
                            style: TextStyle(
                              color: Colors.redAccent,
                              fontSize: 12,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),

                // Tuiles en main
                Expanded(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.fromLTRB(12, 4, 12, 12),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children:
                          myHand.map((tile) {
                            final playable = isMyTurn && canPlayTile(tile);
                            return HandTileWidgetSimple(
                              tile: tile,
                              isPlayable: playable,
                              onTap: playable ? () => onTileTap(tile) : null,
                            );
                          }).toList(),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildYamsUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // Consolidation complète de tous les joueurs et adversaires
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerProfiles = Map<String, dynamic>.from(
      gameData['playerProfiles'] ?? {},
    );
    final rawScores = Map<String, dynamic>.from(gameData['yamsScores'] ?? {});
    final Set<String> allPlayerIds = {};
    allPlayerIds.addAll(players.keys);
    allPlayerIds.addAll(playerProfiles.keys);
    allPlayerIds.addAll(rawScores.keys);
    if (gameData['yamsPlayerOrder'] is List) {
      allPlayerIds.addAll(
        (gameData['yamsPlayerOrder'] as List).map((e) => e.toString()),
      );
    }
    if (gameData['playerOrder'] is List) {
      allPlayerIds.addAll(
        (gameData['playerOrder'] as List).map((e) => e.toString()),
      );
    }

    String getPlayerName(String pId) {
      final pMap = players[pId] is Map ? players[pId] : null;
      final rawName = pMap?['name'];
      if (rawName != null &&
          rawName.toString().trim().isNotEmpty &&
          rawName != AppLocalizations.of(context)!.inconnu) {
        return rawName.toString();
      }
      final profName =
          playerProfiles[pId] is Map ? playerProfiles[pId]['name'] : null;
      if (profName != null &&
          profName.toString().trim().isNotEmpty &&
          profName != AppLocalizations.of(context)!.inconnu) {
        return profName.toString();
      }
      if (pId == playerId) {
        final authName = FirebaseAuth.instance.currentUser?.displayName;
        if (authName != null && authName.trim().isNotEmpty) return authName;
      }
      return AppLocalizations.of(context)!.joueur;
    }

    for (String pId in allPlayerIds) {
      if (!players.containsKey(pId) || players[pId] is! Map) {
        players[pId] = {'name': getPlayerName(pId), 'score': 0};
      } else if (players[pId]['name'] == null ||
          players[pId]['name'] == AppLocalizations.of(context)!.inconnu) {
        players[pId]['name'] = getPlayerName(pId);
      }
    }

    final currentPlayerId = gameData['yamsCurrentPlayerId'] ?? playerId;
    final isMyTurn = currentPlayerId == playerId;
    final List<int> dice = List<int>.from(gameData['yamsDice'] ?? []);
    final List<bool> heldDice = List<bool>.from(
      gameData['yamsHeldDice'] ?? [false, false, false, false, false],
    );
    final int rollsLeft = gameData['yamsRollsLeft'] ?? 3;
    final myScores = Map<String, dynamic>.from(rawScores[playerId] ?? {});

    int calcUpper(Map<String, dynamic> s) => [
      AppLocalizations.of(context)!.asLabel,
      AppLocalizations.of(context)!.deux,
      AppLocalizations.of(context)!.trois,
      AppLocalizations.of(context)!.quatre,
      AppLocalizations.of(context)!.cinq,
      AppLocalizations.of(context)!.six,
    ].fold<int>(0, (sum, cat) => sum + ((s[cat] as num?)?.toInt() ?? 0));
    int calcBonus(Map<String, dynamic> s) => calcUpper(s) >= 63 ? 35 : 0;
    int calcTotal(Map<String, dynamic> s) =>
        s.values.fold<int>(
          0,
          (sum, val) => sum + ((val as num?)?.toInt() ?? 0),
        ) +
        calcBonus(s);

    final List<String> categories = [
      AppLocalizations.of(context)!.asLabel,
      AppLocalizations.of(context)!.deux,
      AppLocalizations.of(context)!.trois,
      AppLocalizations.of(context)!.quatre,
      AppLocalizations.of(context)!.cinq,
      AppLocalizations.of(context)!.six,
      AppLocalizations.of(context)!.brelan,
      AppLocalizations.of(context)!.carre,
      AppLocalizations.of(context)!.full,
      AppLocalizations.of(context)!.petiteSuite,
      AppLocalizations.of(context)!.grandeSuite,
      'Yams',
      AppLocalizations.of(context)!.chance,
    ];

    if (gameData['gameState'] == 'gameOver') {
      final finalScores = Map<String, int>.from(
        (gameData['yamsFinalScores'] as Map? ?? {}).map(
          (k, v) => MapEntry(k.toString(), (v as num).toInt()),
        ),
      );
      return UniversalGameEndScreen(
        gameTitle: "Yams",
        winnerId: gameData['gameWinner'],
        winnerName: getPlayerName(gameData['gameWinner'] ?? ''),
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.toutesLesGrillesSontCompletees,
        players: players,
        customScores: finalScores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    final opponentIds = allPlayerIds.where((id) => id != playerId).toList();
    final String? primaryOpponentId =
        opponentIds.isNotEmpty
            ? ((_viewedOpponentId != null &&
                    opponentIds.contains(_viewedOpponentId))
                ? _viewedOpponentId
                : opponentIds.first)
            : null;
    final primaryOpponentScores =
        (primaryOpponentId != null)
            ? Map<String, dynamic>.from(rawScores[primaryOpponentId] ?? {})
            : <String, dynamic>{};
    final String oppName =
        (primaryOpponentId != null)
            ? getPlayerName(primaryOpponentId)
            : AppLocalizations.of(context)!.adversaire;

    final int myUpper = calcUpper(myScores);
    final int myBonus = calcBonus(myScores);
    final int myTotal = calcTotal(myScores);
    final int oppUpper = calcUpper(primaryOpponentScores);
    final int oppBonus = calcBonus(primaryOpponentScores);
    final int oppTotal = calcTotal(primaryOpponentScores);
    final String? lastHoldAction = gameData['yamsLastHoldAction'] as String?;
    final int? firestoreTappedDie =
        (gameData['yamsLastTappedIndex'] as num?)?.toInt();

    return StreamBuilder<DatabaseEvent>(
      stream: _firebaseService.getYamsLiveStream(widget.gameCode),
      builder: (context, liveSnap) {
        int? liveTappedDie;
        if (liveSnap.hasData && liveSnap.data!.snapshot.value is Map) {
          final liveMap = Map<dynamic, dynamic>.from(
            liveSnap.data!.snapshot.value as Map,
          );
          if (liveMap['playerId'] != playerId) {
            liveTappedDie = (liveMap['tappedDieIndex'] as num?)?.toInt();
          }
        }
        if (liveTappedDie == null && !isMyTurn && firestoreTappedDie != null) {
          liveTappedDie = firestoreTappedDie;
        }

        final bool isInspectingOpponentOnly =
            (_viewedOpponentId != null && _viewedOpponentId != playerId);

        return Column(
          children: [
            // --- SÉLECTEUR RAPIDE D'ONGLET / VUE DE LA GRILLE ---
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
              color: Colors.black45,
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    ChoiceChip(
                      avatar: Icon(Icons.compare_arrows_rounded, size: 14),
                      label: Text(
