  // ===========================================================================
  // 🃏 BELOTE (TAPIS EN LOSANGE CASINO & BOUTONS D'ATOUTS MODERNES)
  // ===========================================================================
  Widget _buildBeloteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final playerData = Map<String, dynamic>.from(
      gameData['belotePlayerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final List<String> myHand = List<String>.from(myData['hand'] ?? []);
    final String? trumpSuit = gameData['beloteTrumpSuit'];
    final String? turnedCard = gameData['beloteTurnedCard'];
    final Map<String, dynamic> currentTrick = Map<String, dynamic>.from(
      gameData['beloteCurrentTrick'] ?? {},
    );
    final Map<String, dynamic> teamScores = Map<String, dynamic>.from(
      gameData['beloteTeamScores'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['belotePlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['beloteCurrentPlayerIndex'] ?? 0;
    final bool isMyTurn =
        playerOrder.isNotEmpty && playerOrder[currentIndex] == playerId;
    final bool isHost = gameData['hostId'] == playerId;
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    // --- FIN DE PARTIE ---
    if (gameData['gameState'] == 'gameOver') {
      final String winnerTeam = gameData['gameWinner'] ?? 'teamA';
      return UniversalGameEndScreen(
        gameTitle: "Belote",
        winnerId: winnerTeam,
        winnerName:
            winnerTeam == 'teamA'
                ? AppLocalizations.of(context)!.timesUpTeamA
                : AppLocalizations.of(context)!.timesUpTeamB,
        reason: AppLocalizations.of(context)!.scoreFinal,
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: isHost,
        onExit: _exitGame,
      );
    }

    return Container(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.center,
          radius: 1.2,
          colors: [Color(0xFF1B4D3E), Color(0xFF0F2E24), Color(0xFF061511)],
        ),
      ),
      child: Column(
        children: [
          // 1. SCOREBOARD & CONTRAT D'ATOUT
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color: Colors.black.withOpacity(0.45),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: Colors.white12),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      AppLocalizations.of(context)!.equipeAPts,
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color:
                            myData['team'] == 'teamA'
                                ? Colors.cyanAccent
                                : Colors.white70,
                      ),
                    ),
                    Text(
                      AppLocalizations.of(context)!.equipeBPts,
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color:
                            myData['team'] == 'teamB'
                                ? Colors.cyanAccent
                                : Colors.white70,
                      ),
                    ),
                  ],
                ),

                // Badge Atout
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 5,
                  ),
                  decoration: BoxDecoration(
                    color:
                        trumpSuit != null
                            ? Color(0xFF2E6F58)
                            : Colors.amber.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color:
                          trumpSuit != null ? Colors.amberAccent : Colors.amber,
                    ),
                  ),
                  child: Row(
                    children: [
                      Text(
                        trumpSuit != null
                            ? AppLocalizations.of(
                              context,
                            )!.atout(_getSuitSymbol(context, trumpSuit))
                            : AppLocalizations.of(context)!.encheresEnCours,
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          fontSize: 12,
                          color:
                              trumpSuit != null
                                  ? (_isRedSuit(trumpSuit)
                                      ? Colors.redAccent.shade100
                                      : Colors.white)
                                  : Colors.amberAccent,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),

          // 2. TAPIS DE JEU EN LOSANGE (PLI CENTRAL & POSITIONS DES 4 JOUEURS)
          Expanded(
            child: Stack(
              alignment: Alignment.center,
              children: [
                // Fond du losange de pli
                Container(
                  width: 220,
                  height: 220,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.black.withOpacity(0.2),
                    border: Border.all(
                      color: Colors.white.withOpacity(0.08),
                      width: 1.5,
                    ),
                  ),
                ),

                // Indicateur de tour au centre
                if (currentTrick.isEmpty && roundState == 'playing_trick')
                  Text(
                    isMyTurn
                        ? AppLocalizations.of(context)!.aVousDOuvrirLe
                        : GameContentLocalization.format(
                          context,
                          AppLocalizations.of(context)!.tourDe1,
                          [
                            playerData[playerOrder[currentIndex]]?['name'] ??
                                '',
                          ],
                        ),
                    style: TextStyle(
                      color: isMyTurn ? Colors.greenAccent : Colors.white38,
                      fontWeight: FontWeight.bold,
                      fontSize: 12,
                    ),
                    textAlign: TextAlign.center,
                  ),

                // Affichage de la carte retournée pendant les enchères
                if (roundState == 'bidding' && turnedCard != null)
                  Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        AppLocalizations.of(context)!.carteAPrendre,
                        style: TextStyle(
                          color: Colors.amberAccent,
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1,
                        ),
                      ),
                      SizedBox(height: 6),
                      _buildCard(
                        card: turnedCard,
                        isSelected: false,
                        scale: 0.95,
                      ),
                    ],
                  ),

                // Cartes jouées dans le pli en cours (disposées en croix)
                ...currentTrick.entries.map((entry) {
                  final String pId = entry.key;
                  final String playedCard = entry.value.toString();
                  final int pIndex = playerOrder.indexOf(pId);
                  final int myIndex = playerOrder.indexOf(playerId);
                  final int relPos =
                      (pIndex - myIndex + 4) %
                      4; // 0=Moi (Bas), 1=Gauche, 2=Face (Haut), 3=Droite

                  double dx = 0, dy = 0;
                  if (relPos == 0) dy = 45; // Bas
                  if (relPos == 2) dy = -45; // Haut
                  if (relPos == 1) dx = -55; // Gauche
                  if (relPos == 3) dx = 55; // Droite

                  return Transform.translate(
                    offset: Offset(dx, dy),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        _buildCard(
                          card: playedCard,
                          isSelected: false,
                          scale: 0.85,
                        ),
                        SizedBox(height: 2),
                        Text(
                          players[pId]?['name'] ?? '',
                          style: TextStyle(
                            color: Colors.white70,
                            fontSize: 9,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ),
                  );
                }).toList(),
              ],
            ),
          ),

          // 3. PANNEAU D'ENCHÈRES STYLISÉ
          if (roundState == 'bidding' && isMyTurn)
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              margin: const EdgeInsets.fromLTRB(10, 0, 10, 6),
              decoration: BoxDecoration(
                color: Color(0xFF14141E),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: Colors.amberAccent.withOpacity(0.5)),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    AppLocalizations.of(context)!.prendreLAtoutOuPasser,
                    style: TextStyle(
                      color: Colors.white70,
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  SizedBox(height: 8),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      ...['H', 'D', 'C', 'S'].map((suit) {
                        final bool isRed = (suit == 'H' || suit == 'D');
                        return ElevatedButton(
                          style: ElevatedButton.styleFrom(
                            backgroundColor:
                                isRed ? Color(0xFF991B1B) : Color(0xFF1E293B),
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                          ),
                          onPressed: () {
                            HapticFeedback.mediumImpact();
                            _firebaseService.beloteAction(
                              widget.gameCode,
                              playerId,
                              'bid',
                              suit: suit,
                            );
                          },
                          child: Text(
                            _getSuitSymbol(context, suit),
                            style: TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        );
                      }).toList(),
                      OutlinedButton(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: Colors.white70,
                          side: BorderSide(color: Colors.white24),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onPressed: () {
                          HapticFeedback.lightImpact();
                          _firebaseService.beloteAction(
                            widget.gameCode,
                            playerId,
                            'pass',
                          );
                        },
                        child: Text(AppLocalizations.of(context)!.passer),
                      ),
                    ],
                  ),
                ],
              ),
            ),

          // 4. MAIN DU JOUEUR (CARTES JOUABLES FLUIDES)
          Container(
            padding: const EdgeInsets.fromLTRB(10, 6, 10, 8),
            decoration: BoxDecoration(
              color: Color(0xFF0B1713),
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(20),
              ),
              border: Border.all(color: Colors.white10),
            ),
            child: Column(
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      AppLocalizations.of(context)!.votreMain,
                      style: TextStyle(
                        color: Colors.white60,
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    if (isMyTurn && roundState == 'playing_trick')
                      Text(
                        AppLocalizations.of(context)!.touchezUneCartePourLa,
                        style: TextStyle(
                          color: Colors.greenAccent,
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                  ],
                ),
                SizedBox(height: 6),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  physics: BouncingScrollPhysics(),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        myHand.map((card) {
                          final bool canPlay =
                              isMyTurn && roundState == 'playing_trick';
                          return GestureDetector(
                            onTap:
                                canPlay
                                    ? () {
                                      HapticFeedback.selectionClick();
                                      _firebaseService
                                          .beloteAction(
                                            widget.gameCode,
                                            playerId,
                                            'play',
                                            card: card,
                                          )
                                          .catchError((e) {
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  e.toString().replaceAll(
                                                    AppLocalizations.of(
                                                      context,
                                                    )!.exception,
                                                    '',
                                                  ),
                                                ),
                                                backgroundColor:
                                                    Colors.red[900],
                                              ),
                                            );
                                          });
                                    }
                                    : null,
                            child: Opacity(
                              opacity: canPlay ? 1.0 : 0.65,
                              child: _buildCard(
                                card: card,
                                isSelected: false,
                                scale: 0.95,
                              ),
                            ),
                          );
                        }).toList(),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // --- HELPERS SYMBOLES DE COULEUR POUR LA BELOTE ---
  String _getSuitSymbol(BuildContext context, String suit) {
    switch (suit) {
      case 'H':
        return AppLocalizations.of(context)!.cur;
      case 'D':
        return AppLocalizations.of(context)!.carreau;
      case 'C':
        return AppLocalizations.of(context)!.trefle;
      case 'S':
        return AppLocalizations.of(context)!.pique;
      default:
        return suit;
    }
  }

  bool _isRedSuit(String suit) => (suit == 'H' || suit == 'D');

  // ===========================================================================
  // 🃏 RAMI (TAPIS FEUTRINE CASINO & PLATEAUX DE COMBINAISONS BOISÉS)
  // ===========================================================================
  Widget _buildRamiUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    final myHand = List<String>.from(
      gameData['ramiPlayerHands']?[playerId] ?? [],
    );
    final stock = List<String>.from(gameData['ramiStock'] ?? []);
    final discard = List<String>.from(gameData['ramiDiscard'] ?? []);
    final melds = Map<String, dynamic>.from(gameData['ramiMelds'] ?? {});
    final currentPlayerId = gameData['ramiCurrentPlayerId'];
    final isMyTurn = currentPlayerId == playerId;
    final hasDrawn = gameData['ramiHasDrawn'] ?? false;
    final roundOver = gameData['ramiRoundOver'] ?? false;

    if (roundOver || gameData['gameState'] == 'gameOver') {
      return _buildRamiGameOverUI(context, gameData, playerId);
    }

    return Container(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.center,
          radius: 1.2,
          colors: [Color(0xFF1B4D3E), Color(0xFF0D2B22), Color(0xFF061511)],
        ),
      ),
      child: Column(
        children: [
          // 1. STATUT DU TOUR ACTUEL (MINIMALISTE)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 4.0),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 3),
              decoration: BoxDecoration(
                color:
                    isMyTurn
                        ? Colors.greenAccent.withOpacity(0.18)
                        : Colors.black38,
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                  color:
                      isMyTurn
                          ? Colors.greenAccent.withOpacity(0.5)
                          : Colors.white12,
                ),
              ),
              child: Text(
                isMyTurn
                    ? AppLocalizations.of(context)!.aVotreTourDeJouer
                    : AppLocalizations.of(context)!.auTourDe1,
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.bold,
                  color: isMyTurn ? Colors.greenAccent : Colors.white70,
                ),
              ),
            ),
          ),

          // 2. ZONE CENTRALE : COMBINAISONS ÉTALÉES (PLATEAUX EN BOIS D'ACAJOU)
          Expanded(
            flex: 3,
            child: Container(
              margin: EdgeInsets.symmetric(horizontal: 8),
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: Colors.black.withOpacity(0.3),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: Colors.white10),
              ),
              child:
                  melds.values.every((list) => (list as List).isEmpty)
                      ? Center(
                        child: Text(
                          AppLocalizations.of(
                            context,
                          )!.aucuneCombinaisonEtaleeSurLa,
                          style: TextStyle(
                            color: Colors.white38,
                            fontSize: 12,
                            fontStyle: FontStyle.italic,
                          ),
                        ),
                      )
                      : ListView(
                        physics: BouncingScrollPhysics(),
                        children:
                            melds.entries.map((entry) {
                              final String pId = entry.key;
                              final List<dynamic> playerMelds = entry.value;
                              if (playerMelds.isEmpty)
                                return const SizedBox.shrink();

                              return Container(
                                margin: const EdgeInsets.only(bottom: 8),
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(
                                  gradient: LinearGradient(
                                    colors: [
                                      Color(0xFF3B2317),
                                      Color(0xFF26150D),
                                    ],
                                    begin: Alignment.topLeft,
                                    end: Alignment.bottomRight,
                                  ),
                                  borderRadius: BorderRadius.circular(12),
                                  border: Border.all(
                                    color: Color(0xFF8D5B4C),
                                    width: 1.2,
                                  ),
                                  boxShadow: [
                                    BoxShadow(
                                      color: Colors.black38,
                                      blurRadius: 4,
                                      offset: Offset(0, 2),
                                    ),
                                  ],
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      AppLocalizations.of(
                                        context,
                                      )!.combinaisonsDe,
                                      style: TextStyle(
                                        fontSize: 11,
                                        fontWeight: FontWeight.bold,
                                        color: Color(0xFFFFD1A9),
                                      ),
                                    ),
                                    SizedBox(height: 6),
                                    Wrap(
                                      spacing: 10,
                                      runSpacing: 6,
                                      children:
                                          playerMelds.map((meld) {
                                            final List<String> meldCards =
                                                List<String>.from(meld);
                                            return Container(
                                              padding:
                                                  const EdgeInsets.symmetric(
                                                    horizontal: 6,
                                                    vertical: 4,
                                                  ),
                                              decoration: BoxDecoration(
                                                color: Colors.black.withOpacity(
                                                  0.35,
                                                ),
                                                borderRadius:
                                                    BorderRadius.circular(8),
                                                border: Border.all(
                                                  color: Colors.white12,
                                                ),
                                              ),
                                              child: Row(
                                                mainAxisSize: MainAxisSize.min,
                                                children:
                                                    meldCards
                                                        .map(
                                                          (c) => _buildRamiCard(
                                                            c,
                                                            true,
                                                            null,
                                                            scale: 0.72,
                                                          ),
                                                        )
                                                        .toList(),
                                              ),
                                            );
                                          }).toList(),
                                    ),
                                  ],
                                ),
                              );
                            }).toList(),
                      ),
            ),
          ),

          SizedBox(height: 6),

          // 3. TABLE CENTRALE : PIOCHE ET DÉFAUSSE TACTILES
          Container(
            padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 16),
            margin: const EdgeInsets.symmetric(horizontal: 12),
            decoration: BoxDecoration(
              color: Colors.black.withOpacity(0.35),
              borderRadius: BorderRadius.circular(18),
              border: Border.all(
                color:
                    isMyTurn && !hasDrawn
                        ? Colors.greenAccent.withOpacity(0.6)
                        : Colors.white10,
              ),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                // Pioche (Stock)
                GestureDetector(
                  onTap:
                      isMyTurn && !hasDrawn
                          ? () {
                            HapticFeedback.lightImpact();
                            _firebaseService.ramiAction(
                              widget.gameCode,
                              playerId,
                              'draw_stock',
                            );
                          }
                          : null,
                  child: Column(
                    children: [
                      Container(
                        width: 58,
                        height: 84,
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            colors: [Color(0xFF1E3A8A), Color(0xFF0F172A)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                          borderRadius: BorderRadius.circular(8),
                          border: Border.all(
                            color:
                                isMyTurn && !hasDrawn
                                    ? Colors.greenAccent
                                    : Colors.white24,
                            width: isMyTurn && !hasDrawn ? 2.0 : 1.0,
                          ),
                          boxShadow: [
                            if (isMyTurn && !hasDrawn)
                              BoxShadow(
                                color: Colors.greenAccent.withOpacity(0.4),
                                blurRadius: 8,
                              ),
                          ],
                        ),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              Icons.style_rounded,
                              color: Colors.amberAccent,
                              size: 24,
                            ),
                            SizedBox(height: 4),
                            Text(
                              "${stock.length}",
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                fontSize: 13,
                                color: Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                      SizedBox(height: 4),
                      Text(
                        AppLocalizations.of(context)!.pioche1,
                        style: TextStyle(
                          fontSize: 9,
                          fontWeight: FontWeight.bold,
                          color:
                              isMyTurn && !hasDrawn
                                  ? Colors.greenAccent
                                  : Colors.white54,
                          letterSpacing: 1,
                        ),
                      ),
                    ],
                  ),
                ),

                // Indicateur de statut
                Column(
                  children: [
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color:
                            isMyTurn
                                ? Colors.green.withOpacity(0.2)
                                : Colors.white10,
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: isMyTurn ? Colors.greenAccent : Colors.white24,
                        ),
                      ),
                      child: Text(
                        isMyTurn
                            ? (hasDrawn
                                ? AppLocalizations.of(context)!.etaleOuDefausse
                                : AppLocalizations.of(context)!.piocheUneCarte)
                            : AppLocalizations.of(context)!.auTourDe1,
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                          color: isMyTurn ? Colors.greenAccent : Colors.white70,
                        ),
                      ),
                    ),
                  ],
                ),

                // Défausse
                GestureDetector(
                  onTap:
                      isMyTurn && !hasDrawn && discard.isNotEmpty
                          ? () {
                            HapticFeedback.lightImpact();
                            _firebaseService.ramiAction(
                              widget.gameCode,
                              playerId,
                              'draw_discard',
                            );
                          }
                          : null,
                  child: Column(
                    children: [
                      discard.isNotEmpty
                          ? _buildRamiCard(
                            discard.last,
                            true,
                            isMyTurn && !hasDrawn ? Colors.amberAccent : null,
                            scale: 0.95,
                          )
                          : Container(
                            width: 58,
                            height: 84,
                            decoration: BoxDecoration(
                              color: Colors.white10,
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(color: Colors.white24),
                            ),
                            child: Center(
                              child: Text(
                                AppLocalizations.of(context)!.vide,
                                style: TextStyle(
                                  color: Colors.white38,
                                  fontSize: 10,
                                ),
                              ),
                            ),
                          ),
                      SizedBox(height: 4),
                      Text(
                        AppLocalizations.of(context)!.defausse,
                        style: TextStyle(
                          fontSize: 9,
                          fontWeight: FontWeight.bold,
                          color:
                              isMyTurn && !hasDrawn && discard.isNotEmpty
                                  ? Colors.amberAccent
                                  : Colors.white54,
                          letterSpacing: 1,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),

          SizedBox(height: 6),

          // 4. MAIN DU JOUEUR & BOUTONS D'ACTION
          Expanded(
            flex: 3,
            child: Container(
              padding: const EdgeInsets.fromLTRB(12, 6, 12, 8),
              decoration: BoxDecoration(
                color: Color(0xFF0A1813),
                borderRadius: const BorderRadius.vertical(
                  top: Radius.circular(22),
                ),
                border: Border.all(color: Colors.white10),
              ),
              child: Column(
                children: [
                  Expanded(
                    child: Center(
                      child: SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        physics: BouncingScrollPhysics(),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children:
                              myHand.map((card) {
                                final bool isSelected = _selectedRamiCards
                                    .contains(card);
                                return GestureDetector(
                                  onTap:
                                      isMyTurn
                                          ? () {
                                            HapticFeedback.selectionClick();
                                            setState(() {
                                              if (isSelected) {
                                                _selectedRamiCards.remove(card);
                                              } else {
                                                _selectedRamiCards.add(card);
                                              }
                                            });
                                          }
                                          : null,
                                  child: Transform.translate(
                                    offset: Offset(0, isSelected ? -16 : 0),
                                    child: _buildRamiCard(
                                      card,
                                      true,
                                      isSelected ? Colors.greenAccent : null,
                                      scale: 1.0,
                                    ),
                                  ),
                                );
                              }).toList(),
                        ),
                      ),
                    ),
                  ),

                  // Actions : Étaler et Défausser
                  if (isMyTurn)
                    Padding(
                      padding: const EdgeInsets.only(top: 4.0),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                        children: [
                          ElevatedButton.icon(
                            icon: Icon(Icons.layers_rounded, size: 16),
                            label: Text(AppLocalizations.of(context)!.etaler),
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.teal[700],
                              foregroundColor: Colors.white,
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(12),
                              ),
                            ),
                            onPressed:
                                hasDrawn && _selectedRamiCards.length >= 3
                                    ? () {
                                      _firebaseService
                                          .ramiAction(
                                            widget.gameCode,
                                            playerId,
                                            'meld',
                                            cards: _selectedRamiCards,
                                          )
                                          .then((_) {
                                            setState(
                                              () => _selectedRamiCards.clear(),
                                            );
                                          })
                                          .catchError((e) {
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  e.toString().replaceAll(
                                                    AppLocalizations.of(
                                                      context,
                                                    )!.exception,
                                                    '',
                                                  ),
                                                ),
                                                backgroundColor:
                                                    Colors.red[900],
                                              ),
                                            );
                                          });
                                    }
                                    : null,
                          ),
                          ElevatedButton.icon(
                            icon: Icon(Icons.arrow_downward_rounded, size: 16),
                            label: Text(
                              AppLocalizations.of(context)!.defausserFin,
                            ),
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.orange[800],
                              foregroundColor: Colors.white,
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(12),
                              ),
                            ),
                            onPressed:
                                hasDrawn && _selectedRamiCards.length == 1
                                    ? () {
                                      _firebaseService
                                          .ramiAction(
                                            widget.gameCode,
                                            playerId,
                                            'discard',
                                            cards: _selectedRamiCards,
                                          )
                                          .then((_) {
                                            setState(
                                              () => _selectedRamiCards.clear(),
                                            );
                                          })
                                          .catchError((e) {
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  e.toString().replaceAll(
                                                    AppLocalizations.of(
                                                      context,
                                                    )!.exception,
                                                    '',
                                                  ),
                                                ),
                                                backgroundColor:
                                                    Colors.red[900],
                                              ),
                                            );
                                          });
                                    }
                                    : null,
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildRamiCard(
    String card,
    bool faceUp,
    Color? borderColor, {
    double scale = 1.0,
  }) {
    final String cleanC = card.split('_')[0];
    final String rank = cleanC.substring(0, cleanC.length - 1);
    final String suit = cleanC.substring(cleanC.length - 1);
    final bool isRed = (suit == 'H' || suit == 'D');
    final Color textColor = isRed ? Color(0xFFD32F2F) : Color(0xFF212121);
    final String suitSymbol =
        {'H': '♥', 'D': '♦', 'C': '♣', 'S': '♠'}[suit] ?? '?';

    return Container(
      width: 58 * scale,
      height: 88 * scale,
      margin: const EdgeInsets.symmetric(horizontal: 3),
      decoration: BoxDecoration(
        color: faceUp ? Colors.white : Color(0xFF1E3A8A),
        borderRadius: BorderRadius.circular(8 * scale),
        border: Border.all(
          color: borderColor ?? Colors.grey.shade300,
          width: borderColor != null ? 2.2 : 1.0,
        ),
        boxShadow: [
          BoxShadow(
            color:
                borderColor != null
                    ? borderColor.withOpacity(0.4)
                    : Colors.black26,
            blurRadius: borderColor != null ? 8 : 3,
            offset: Offset(1, 2),
          ),
        ],
      ),
      child:
          faceUp
              ? Stack(
                children: [
                  Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          rank,
                          style: TextStyle(
                            fontSize: 22 * scale,
                            fontWeight: FontWeight.bold,
                            color: textColor,
                          ),
                        ),
                        Text(
                          suitSymbol,
                          style: TextStyle(
                            fontSize: 18 * scale,
                            color: textColor,
                          ),
                        ),
                      ],
                    ),
                  ),
                  Positioned(
                    top: 3 * scale,
                    left: 4 * scale,
                    child: Text(
                      rank,
                      style: TextStyle(
                        fontSize: 11 * scale,
                        fontWeight: FontWeight.bold,
                        color: textColor,
                      ),
                    ),
                  ),
                  Positioned(
                    bottom: 3 * scale,
                    right: 4 * scale,
                    child: Transform.rotate(
                      angle: pi,
                      child: Text(
                        rank,
                        style: TextStyle(
                          fontSize: 11 * scale,
                          fontWeight: FontWeight.bold,
                          color: textColor,
                        ),
                      ),
                    ),
                  ),
                ],
              )
              : Center(child: Icon(Icons.style_rounded, color: Colors.white54)),
    );
  }

  Widget _buildRamiGameOverUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final totalScores = Map<String, dynamic>.from(
      gameData['ramiTotalScores'] ?? {},
    );
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final isHost = gameData['hostId'] == playerId;
    final isGameOver = gameData['gameState'] == 'gameOver';

    if (isGameOver) {
      final scores = Map<String, int>.from(
        totalScores.map((k, v) => MapEntry(k, (v as num).toInt())),
      );
      return UniversalGameEndScreen(
        gameTitle: "Rami",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.scoreLimiteAtteint,
        players: players,
        customScores: scores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: isHost,
        onExit: _exitGame,
      );
    }

    final sortedScores =
        totalScores.entries.toList()
          ..sort((a, b) => a.value.compareTo(b.value));

    return Center(
      child: Container(
        margin: const EdgeInsets.all(20),
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: Color(0xFF1E1E2E),
          borderRadius: BorderRadius.circular(24),
          border: Border.all(
            color: Colors.amberAccent.withOpacity(0.5),
            width: 2,
          ),
          boxShadow: [
            BoxShadow(
              color: Colors.amberAccent.withOpacity(0.2),
              blurRadius: 20,
            ),
          ],
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              isGameOver ? Icons.emoji_events_rounded : Icons.flag_rounded,
              size: 54,
              color: Colors.amberAccent,
            ),
            SizedBox(height: 12),
            Text(
              isGameOver
                  ? AppLocalizations.of(context)!.partieTerminee
                  : AppLocalizations.of(context)!.finDeLaManche1,
              style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                fontWeight: FontWeight.bold,
                color: Colors.white,
              ),
            ),
            SizedBox(height: 14),
            ...sortedScores.map((e) {
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      players[e.key]?['name'] ??
                          AppLocalizations.of(context)!.joueur,
                      style: TextStyle(color: Colors.white70, fontSize: 15),
                    ),
                    Text(
                      AppLocalizations.of(context)!.pts8(e.value),
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        color: Colors.amberAccent,
                        fontSize: 15,
                      ),
                    ),
                  ],
                ),
              );
            }),
            SizedBox(height: 20),
            if (isHost && !isGameOver)
              ElevatedButton.icon(
                icon: Icon(Icons.arrow_forward_rounded),
                label: Text(AppLocalizations.of(context)!.mancheSuivante),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.green[700],
                ),
                onPressed: () => _firebaseService.startGame(widget.gameCode),
              )
            else if (isGameOver)
              ElevatedButton.icon(
                icon: Icon(Icons.home_rounded),
                label: Text(AppLocalizations.of(context)!.retourALAccueil),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.deepPurpleAccent,
                ),
                onPressed: _safePopToFirst,
              )
            else
              Text(
                AppLocalizations.of(context)!.enAttenteDeLHote1,
                style: TextStyle(color: Colors.white54),
              ),
          ],
        ),
      ),
    );
  }

  // NOUVELLE UI BLOKUS COMPLÈTE
  // NOUVELLE UI BLOKUS COMPLÈTE
  Widget _buildBlokusUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final board = Map<String, String>.from(gameData['blokusBoard'] ?? {});
    final myColor = gameData['blokusPlayerColors']?[playerId] ?? 'blue';
    final myHand = List<int>.from(
      gameData['blokusPlayerHands']?[playerId] ?? [],
    );
    final playerOrder = List<String>.from(gameData['blokusPlayerOrder'] ?? []);
    final currentPlayerId =
        playerOrder.isNotEmpty
            ? playerOrder[gameData['blokusCurrentPlayerIndex'] ?? 0]
            : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final players = gameData['players'] as Map<String, dynamic>;
    final passedPlayers = List<String>.from(
      gameData['blokusPassedPlayers'] ?? [],
    );
    final isFirstPiece =
        !(gameData['blokusFirstPiecePlaced']?[playerId] ?? false);

    // --- CORRECTION 1 : NETTOYAGE SI FIN DU CHRONO OU TOUR PASSÉ ---
    if (!isMyTurn && _selectedBlokusPieceId != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          setState(() {
            _selectedBlokusPieceId = null;
            _blokusStartRow = null;
            _blokusStartCol = null;
            _blokusCanPlace = false;
          });
        }
      });
    }

    if (gameData['gameState'] == 'gameOver') {
      final scores = Map<String, int>.from(gameData['blokusScores'] ?? {});
      final lastPiecesPlaced = Map<String, dynamic>.from(
        gameData['blokusLastPiecesPlaced'] ?? {},
      );
      if (myHand.isEmpty) {
        Provider.of<PlayerState>(
          context,
          listen: false,
        ).recordBadgeEvent('blokus_all_placed');
        if (lastPiecesPlaced[playerId] == 1) {
          Provider.of<PlayerState>(
            context,
            listen: false,
          ).recordBadgeEvent('blokus_monomino_last');
        }
      }
      return UniversalGameEndScreen(
        gameTitle: "Blokus",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            AppLocalizations.of(context)!.plusAucunCoupPossible,
        players: players,
        customScores: scores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    Color getColor(String c) {
      switch (c) {
        case 'blue':
          return Colors.blue;
        case 'red':
          return Colors.red;
        case 'green':
          return Colors.green;
        case 'yellow':
          return Colors.yellow;
        default:
          return Colors.grey;
      }
    }

    final double gridSize = 20;

    return LayoutBuilder(
      builder: (context, constraints) {
        final double boardPixelSize = constraints.maxWidth - 16;
        final double cellSize = boardPixelSize / gridSize;

        void _updatePiecePosition(Offset localOffset, {int? draggingPieceId}) {
          final int? activePiece = draggingPieceId ?? _selectedBlokusPieceId;
          if (activePiece != null) {
            final col = (localOffset.dx / cellSize).floor().clamp(0, 19);
            final row = ((localOffset.dy / cellSize) - 2).floor().clamp(0, 19);

            setState(() {
              _selectedBlokusPieceId = activePiece;
              _blokusStartRow = row;
              _blokusStartCol = col;
              _checkBlokusPlacement(board, myColor, isFirstPiece);
            });

            if (isMyTurn) {
              _firebaseService.updateBlokusLivePreview(
                widget.gameCode,
                playerId,
                pieceId: activePiece,
                row: row,
                col: col,
                rotation: _blokusRotation,
                flipped: _blokusFlipped,
                canPlace: _blokusCanPlace,
              );
            }
          }
        }

        return DragTarget<int>(
          onWillAcceptWithDetails: (details) => isMyTurn,
          onAcceptWithDetails: (details) {
            setState(() {
              _selectedBlokusPieceId = details.data;
              _checkBlokusPlacement(board, myColor, isFirstPiece);
            });
          },
          onMove: (details) {
            final RenderBox? renderBox =
                _canvasKey.currentContext?.findRenderObject() as RenderBox?;
            if (renderBox != null) {
              final localOffset = renderBox.globalToLocal(details.offset);
              _updatePiecePosition(localOffset, draggingPieceId: details.data);
            }
          },
          builder: (context, candidateData, rejectedData) {
            return Column(
              children: [
                // --- EN-TÊTE ---
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color:
                        isMyTurn
                            ? getColor(myColor).withOpacity(0.15)
                            : Colors.transparent,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(
                              isMyTurn
                                  ? AppLocalizations.of(context)!.aVotreTour
                                  : GameContentLocalization.format(
                                    context,
                                    AppLocalizations.of(context)!.tourDe,
                                    [
                                      players[currentPlayerId]?['name'] ??
                                          '...',
                                    ],
                                  ),
                              style: TextStyle(
                                color:
                                    isMyTurn ? getColor(myColor) : Colors.white,
                                fontWeight: FontWeight.bold,
                                fontSize: 12,
                              ),
                              overflow: TextOverflow.ellipsis,
                            ),
                            if (isFirstPiece && isMyTurn)
                              Text(
                                AppLocalizations.of(
                                  context,
                                )!.placezDansVotreCoin,
                                style: TextStyle(
                                  color: Colors.amberAccent,
                                  fontSize: 11,
                                ),
                              ),
                          ],
                        ),
                      ),

                      if (isMyTurn && _selectedBlokusPieceId != null) ...[
                        IconButton(
                          icon: Icon(
                            Icons.rotate_right,
                            color: Colors.deepPurpleAccent,
                          ),
                          tooltip: AppLocalizations.of(context)!.tourner,
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed: () {
                            setState(() {
                              _blokusRotation = (_blokusRotation + 1) % 4;
                              _checkBlokusPlacement(
                                board,
                                myColor,
                                isFirstPiece,
                              );
                            });
                            _firebaseService.updateBlokusLivePreview(
                              widget.gameCode,
                              playerId,
                              pieceId: _selectedBlokusPieceId,
                              row: _blokusStartRow,
                              col: _blokusStartCol,
                              rotation: _blokusRotation,
                              flipped: _blokusFlipped,
                              canPlace: _blokusCanPlace,
                            );
                          },
                        ),
                        IconButton(
                          icon: Icon(Icons.flip, color: Colors.tealAccent),
                          tooltip: AppLocalizations.of(context)!.retourner,
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed: () {
                            setState(() {
                              _blokusFlipped = !_blokusFlipped;
                              _checkBlokusPlacement(
                                board,
                                myColor,
                                isFirstPiece,
                              );
                            });
                            _firebaseService.updateBlokusLivePreview(
                              widget.gameCode,
                              playerId,
                              pieceId: _selectedBlokusPieceId,
                              row: _blokusStartRow,
                              col: _blokusStartCol,
                              rotation: _blokusRotation,
                              flipped: _blokusFlipped,
                              canPlace: _blokusCanPlace,
                            );
                          },
                        ),
                        IconButton(
                          icon: Icon(Icons.cancel, color: Colors.redAccent),
                          tooltip: AppLocalizations.of(context)!.annuler,
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed: () {
                            setState(() {
                              _selectedBlokusPieceId = null;
                              _blokusStartRow = null;
                              _blokusStartCol = null;
                              _blokusCanPlace = false;
                            });
                            _firebaseService.updateBlokusLivePreview(
                              widget.gameCode,
                              playerId,
                              pieceId: null,
                              row: null,
                              col: null,
                              rotation: 0,
                              flipped: false,
                              canPlace: false,
                            );
                          },
                        ),
                        IconButton(
                          icon: Icon(
                            Icons.check_circle,
                            color:
                                _blokusCanPlace
                                    ? Colors.greenAccent
                                    : Colors.grey,
                          ),
                          tooltip:
                              AppLocalizations.of(context)!.validerLePlacement,
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed:
                              _blokusCanPlace &&
                                      _blokusStartRow != null &&
                                      _blokusStartCol != null
                                  ? () async {
                                    try {
                                      await _firebaseService.placeBlokusPiece(
                                        widget.gameCode,
                                        playerId,
                                        _selectedBlokusPieceId!,
                                        _blokusStartRow!,
                                        _blokusStartCol!,
                                        _blokusRotation,
                                        flipped: _blokusFlipped,
                                      );
                                      setState(() {
                                        _selectedBlokusPieceId = null;
                                        _blokusRotation = 0;
                                        _blokusFlipped = false;
                                        _blokusStartRow = null;
                                        _blokusStartCol = null;
                                        _blokusCanPlace = false;
                                      });
                                      _firebaseService.updateBlokusLivePreview(
                                        widget.gameCode,
                                        playerId,
                                        pieceId: null,
                                        row: null,
                                        col: null,
                                        rotation: 0,
                                        flipped: false,
                                        canPlace: false,
                                      );
                                    } catch (e) {
                                      ScaffoldMessenger.of(
                                        context,
                                      ).showSnackBar(
                                        SnackBar(
                                          content: Text(
                                            e.toString().replaceAll(
                                              AppLocalizations.of(
                                                context,
                                              )!.exception,
                                              '',
                                            ),
                                          ),
                                        ),
                                      );
                                    }
                                  }
                                  : null,
                        ),
                      ],

                      if (isMyTurn && _selectedBlokusPieceId == null)
                        ElevatedButton(
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.red[900],
                            padding: EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 8,
                            ),
                            minimumSize: Size(0, 36),
                          ),
                          onPressed: () {
                            _firebaseService.passBlokusTurn(
                              widget.gameCode,
                              playerId,
                            );
                            // --- CORRECTION 3 : Retirer la pièce sélectionnée en passant ---
                            setState(() {
                              _selectedBlokusPieceId = null;
                              _blokusStartRow = null;
                              _blokusStartCol = null;
                              _blokusCanPlace = false;
                            });
                            _firebaseService.updateBlokusLivePreview(
                              widget.gameCode,
                              playerId,
                              pieceId: null,
                              row: null,
                              col: null,
                              rotation: 0,
                              flipped: false,
                              canPlace: false,
                            );
                          },
                          child: Text(
                            AppLocalizations.of(context)!.passer,
                            style: TextStyle(fontSize: 12),
                          ),
                        ),
                    ],
                  ),
                ),

                // --- PLATEAU DE JEU ---
                Expanded(
                  child: Center(
                    child: Container(
                      width: boardPixelSize,
                      height: boardPixelSize,
                      decoration: BoxDecoration(
                        border: Border.all(color: Colors.white24, width: 2),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: GestureDetector(
                        onPanStart:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        onPanUpdate:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        onTapDown:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        child: StreamBuilder<DatabaseEvent>(
                          stream: _firebaseService.getBlokusLivePreviewStream(
                            widget.gameCode,
                          ),
                          builder: (context, snap) {
                            List<List<int>>? ghostPiece;
                            int? ghostRow;
                            int? ghostCol;
                            Color? ghostColor;
                            bool ghostCanPlace = true;

                            if (snap.hasData &&
                                snap.data!.snapshot.value != null) {
                              try {
                                final raw = Map<String, dynamic>.from(
                                  snap.data!.snapshot.value as Map,
                                );
                                final pId = raw['playerId'] as String?;
                                if (pId != null && pId != playerId) {
                                  final pIdPiece = raw['pieceId'] as int?;
                                  final r = raw['row'] as int?;
                                  final c = raw['col'] as int?;
                                  final rot = raw['rotation'] as int? ?? 0;
                                  final flip = raw['flipped'] as bool? ?? false;
                                  ghostCanPlace =
                                      raw['canPlace'] as bool? ?? true;

                                  if (pIdPiece != null &&
                                      r != null &&
                                      c != null) {
                                    ghostPiece = GameData.getRotatedPiece(
                                      pIdPiece,
                                      rot,
                                      flipped: flip,
                                    );
                                    ghostRow = r;
                                    ghostCol = c;
                                    final oppColor =
                                        gameData['blokusPlayerColors']?[pId] ??
                                        'red';
                                    ghostColor = getColor(oppColor);
                                  }
                                }
                              } catch (_) {}
                            }

                            return CustomPaint(
                              key: _canvasKey,
                              size: Size(boardPixelSize, boardPixelSize),
                              painter: _BlokusBoardPainter(
                                board: board,
                                gridSize: gridSize,
                                cellSize: cellSize,
                                previewPiece:
                                    _selectedBlokusPieceId != null &&
                                            _blokusStartRow != null &&
                                            _blokusStartCol != null
                                        ? GameData.getRotatedPiece(
                                          _selectedBlokusPieceId!,
                                          _blokusRotation,
                                          flipped: _blokusFlipped,
                                        )
                                        : null,
                                previewRow: _blokusStartRow,
                                previewCol: _blokusStartCol,
                                previewColor: getColor(myColor),
                                canPlace: _blokusCanPlace,
                                ghostPiece: ghostPiece,
                                ghostRow: ghostRow,
                                ghostCol: ghostCol,
                                ghostColor: ghostColor,
                                ghostCanPlace: ghostCanPlace,
                              ),
                            );
                          },
                        ),
                      ),
                    ),
                  ),
                ),

                // --- RACK DE PIÈCES (COMPACT) ---
                Container(
                  height: 95,
                  padding: EdgeInsets.symmetric(vertical: 4, horizontal: 8),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [
                        Colors.black.withOpacity(0.6),
                        Colors.grey[900]!.withOpacity(0.85),
                      ],
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                    ),
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(20),
                    ),
                    border: Border.all(color: Colors.white10, width: 1.5),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black54,
                        blurRadius: 10,
                        offset: Offset(0, -4),
                      ),
                    ],
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Padding(
                        padding: const EdgeInsets.only(bottom: 6.0),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Text(
                              AppLocalizations.of(context)!.vosPieces,
                              style: TextStyle(
                                color: Colors.white70,
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                                letterSpacing: 0.5,
                              ),
                            ),
                          ],
                        ),
                      ),
                      Expanded(
                        child: ListView.builder(
                          scrollDirection: Axis.horizontal,
                          itemCount: myHand.length,
                          itemBuilder: (context, index) {
                            int pieceId = myHand[index];
                            bool isSelected = _selectedBlokusPieceId == pieceId;

                            Widget pieceWidget = Container(
                              width: 58,
                              height: 58,
                              margin: EdgeInsets.symmetric(
                                horizontal: 3,
                                vertical: 1,
                              ),
                              decoration: BoxDecoration(
                                color:
                                    isSelected
                                        ? getColor(myColor).withOpacity(0.25)
                                        : Colors.white.withOpacity(0.04),
                                borderRadius: BorderRadius.circular(12),
                                border: Border.all(
                                  color:
                                      isSelected
                                          ? getColor(myColor)
                                          : Colors.white12,
                                  width: isSelected ? 2.5 : 1.0,
                                ),
                                boxShadow:
                                    isSelected
                                        ? [
                                          BoxShadow(
                                            color: getColor(
                                              myColor,
                                            ).withOpacity(0.3),
                                            blurRadius: 8,
                                            spreadRadius: 1,
                                          ),
                                        ]
                                        : [],
                              ),
                              child: CustomPaint(
                                painter: _BlokusPiecePainter(
                                  pieceId,
                                  isSelected ? _blokusRotation : 0,
                                  getColor(myColor),
                                  flipped: isSelected ? _blokusFlipped : false,
                                ),
                              ),
                            );

                            return GestureDetector(
                              onTap:
                                  isMyTurn
                                      ? () {
                                        setState(() {
                                          if (isSelected) {
                                            _selectedBlokusPieceId = null;
                                          } else {
                                            _selectedBlokusPieceId = pieceId;
                                            _blokusRotation = 0;
                                            _blokusFlipped = false;
                                            _checkBlokusPlacement(
                                              board,
                                              myColor,
                                              isFirstPiece,
                                            );
                                          }
                                        });
                                      }
                                      : null,
                              child: Draggable<int>(
                                data: pieceId,
                                maxSimultaneousDrags: isMyTurn ? 1 : 0,
                                affinity: Axis.vertical,
                                onDragStarted: () {
                                  setState(() {
                                    _selectedBlokusPieceId = pieceId;
                                    _blokusRotation = 0;
                                    _blokusFlipped = false;
                                  });
                                },
                                feedback: const SizedBox.shrink(),
                                childWhenDragging: Opacity(
                                  opacity: 0.25,
                                  child: pieceWidget,
                                ),
                                child: pieceWidget,
                              ),
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            );
          },
        );
      },
    );
  }

  // Fonction de vérification du placement
  void _checkBlokusPlacement(
    Map<String, String> board,
    String myColor,
    bool isFirstPiece,
  ) {
    if (_selectedBlokusPieceId == null ||
        _blokusStartRow == null ||
        _blokusStartCol == null) {
      setState(() => _blokusCanPlace = false);
      return;
    }
    final rotatedPiece = GameData.getRotatedPiece(
      _selectedBlokusPieceId!,
      _blokusRotation,
      flipped: _blokusFlipped,
    );
    final absoluteCoords =
        rotatedPiece
            .map((p) => [p[0] + _blokusStartRow!, p[1] + _blokusStartCol!])
            .toList();

    for (var c in absoluteCoords) {
      if (c[0] < 0 || c[0] >= 20 || c[1] < 0 || c[1] >= 20) {
        setState(() => _blokusCanPlace = false);
        return;
      }
      if (board.containsKey("${c[0]}_${c[1]}")) {
        setState(() => _blokusCanPlace = false);
        return;
      }
    }
    for (var c in absoluteCoords) {
      List<List<int>> neighbors = [
        [c[0] - 1, c[1]],
        [c[0] + 1, c[1]],
        [c[0], c[1] - 1],
        [c[0], c[1] + 1],
      ];
      for (var n in neighbors) {
        if (board["${n[0]}_${n[1]}"] == myColor) {
          setState(() => _blokusCanPlace = false);
          return;
        }
      }
    }
    bool touchesCorner = false;
    for (var c in absoluteCoords) {
      List<List<int>> diags = [
        [c[0] - 1, c[1] - 1],
        [c[0] - 1, c[1] + 1],
        [c[0] + 1, c[1] - 1],
        [c[0] + 1, c[1] + 1],
      ];
      for (var d in diags) {
        if (board["${d[0]}_${d[1]}"] == myColor) {
          touchesCorner = true;
          break;
        }
      }
      if (touchesCorner) break;
    }

    if (isFirstPiece) {
      final List<String> validCorners = ["0_0", "19_19", "0_19", "19_0"];
      String cornerTarget =
          myColor == 'blue'
              ? "0_0"
              : myColor == 'red'
              ? "19_19"
              : myColor == 'green'
              ? "0_19"
              : "19_0";
      bool coversCorner = absoluteCoords.any((c) {
        final key = "${c[0]}_${c[1]}";
        return key == cornerTarget ||
            (validCorners.contains(key) && !board.containsKey(key));
      });
      setState(() => _blokusCanPlace = coversCorner);
    } else {
      setState(() => _blokusCanPlace = touchesCorner);
    }
  }
}

// PAINTER POUR LE PLATEAU BLOKUS
class _BlokusBoardPainter extends CustomPainter {
  final Map<String, String> board;
  final double gridSize;
  final double cellSize;
  final List<List<int>>? previewPiece;
  final int? previewRow;
  final int? previewCol;
  final Color previewColor;
  final bool canPlace;

  // Données de la pièce fantôme de l'adversaire
  final List<List<int>>? ghostPiece;
  final int? ghostRow;
  final int? ghostCol;
  final Color? ghostColor;
  final bool ghostCanPlace;

  _BlokusBoardPainter({
    required this.board,
    required this.gridSize,
    required this.cellSize,
    this.previewPiece,
    this.previewRow,
    this.previewCol,
    required this.previewColor,
    required this.canPlace,
    this.ghostPiece,
    this.ghostRow,
    this.ghostCol,
    this.ghostColor,
    this.ghostCanPlace = true,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final bgPaint = Paint()..color = Colors.grey[900]!;
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), bgPaint);

    for (int r = 0; r < gridSize; r++) {
      for (int c = 0; c < gridSize; c++) {
        final rect = Rect.fromLTWH(
          c * cellSize,
          r * cellSize,
          cellSize,
          cellSize,
        );
        final key = "${r}_${c}";
        final cellColor = board[key];

        if (cellColor != null) {
          Color color;
          switch (cellColor) {
            case 'blue':
              color = Colors.blue;
              break;
            case 'red':
              color = Colors.red;
              break;
            case 'green':
              color = Colors.green;
              break;
            case 'yellow':
              color = Colors.yellow;
              break;
            default:
              color = Colors.grey;
          }
          final paint = Paint()..color = color;
          canvas.drawRect(rect.inflate(-1), paint);
        } else {
          final paint = Paint()..color = Colors.grey[800]!;
          canvas.drawRect(rect.inflate(-1), paint);
        }

        final borderPaint =
            Paint()
              ..color = Colors.white10
              ..style = PaintingStyle.stroke;
        canvas.drawRect(rect, borderPaint);
      }
    }

    void drawStartCorner(int r, int c, Color color) {
      if (board["${r}_${c}"] == null) {
        final rect = Rect.fromLTWH(
          c * cellSize,
          r * cellSize,
          cellSize,
          cellSize,
        );
        canvas.drawRect(
          rect.inflate(-2),
          Paint()
            ..color = color.withOpacity(0.3)
            ..style = PaintingStyle.fill,
        );
        canvas.drawCircle(
          rect.center,
          cellSize * 0.2,
          Paint()..color = color.withOpacity(0.8),
        );
      }
    }

    drawStartCorner(0, 0, Colors.blue);
    drawStartCorner(19, 19, Colors.red);
    drawStartCorner(0, 19, Colors.green);
    drawStartCorner(19, 0, Colors.yellow);

    // 1. DESSIN DU FANTÔME ADVERSE EN DIRECT
    if (ghostPiece != null &&
        ghostRow != null &&
        ghostCol != null &&
        ghostColor != null) {
      final ghostFill = Paint()..color = ghostColor!.withOpacity(0.40);
      final ghostBorder =
          Paint()
            ..color = (ghostCanPlace ? ghostColor! : Colors.redAccent)
                .withOpacity(0.8)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2.0;

      for (var p in ghostPiece!) {
        final row = p[0] + ghostRow!;
        final col = p[1] + ghostCol!;
        if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
          final rect = Rect.fromLTWH(
            col * cellSize,
            row * cellSize,
            cellSize,
            cellSize,
          );
          canvas.drawRect(rect.inflate(-1), ghostFill);
          canvas.drawRect(rect, ghostBorder);
        }
      }
    }

    // 2. DESSIN DE MA PROPRE PRÉVISUALISATION
    if (previewPiece != null && previewRow != null && previewCol != null) {
      final previewPaint = Paint()..color = previewColor.withOpacity(0.65);
      final borderPaint =
          Paint()
            ..color = canPlace ? Colors.greenAccent : Colors.redAccent
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2.5;

      for (var p in previewPiece!) {
        final row = p[0] + previewRow!;
        final col = p[1] + previewCol!;
        if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
          final rect = Rect.fromLTWH(
            col * cellSize,
            row * cellSize,
            cellSize,
            cellSize,
          );
          canvas.drawRect(rect.inflate(-1), previewPaint);
          canvas.drawRect(rect, borderPaint);
        }
      }
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

// PAINTER POUR LES PIÈCES DANS LA MAIN
class _BlokusPiecePainter extends CustomPainter {
  final int pieceId;
  final int rotation;
  final Color color;
  final bool flipped; // NOUVEAU

  _BlokusPiecePainter(
    this.pieceId,
    this.rotation,
    this.color, {
    this.flipped = false,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final piece = GameData.getRotatedPiece(pieceId, rotation, flipped: flipped);
    if (piece.isEmpty) return;

    int maxR = piece.map((p) => p[0]).reduce((a, b) => a > b ? a : b);
    int maxC = piece.map((p) => p[1]).reduce((a, b) => a > b ? a : b);

    double cellW = size.width / (maxC + 1);
    double cellH = size.height / (maxR + 1);
    double cellSize = cellW < cellH ? cellW : cellH;

    double offsetX = (size.width - (maxC + 1) * cellSize) / 2;
    double offsetY = (size.height - (maxR + 1) * cellSize) / 2;

    final paint = Paint()..color = color;
    final borderPaint =
        Paint()
          ..color = Colors.white
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1;

    for (var p in piece) {
      final rect = Rect.fromLTWH(
        offsetX + p[1] * cellSize,
        offsetY + p[0] * cellSize,
        cellSize * 0.9,
        cellSize * 0.9,
      );
      canvas.drawRect(rect, paint);
      canvas.drawRect(rect, borderPaint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

// Painter for straight-line-only Pictionary drawing mode
class _StraightLinePainter extends CustomPainter {
  final List<Offset> points; // flat list of [start1, end1, start2, end2, ...]
  final Offset? currentStart;
  final Offset? currentEnd;

  const _StraightLinePainter({
    required this.points,
    this.currentStart,
    this.currentEnd,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = Colors.black
          ..strokeWidth = 3.0
          ..strokeCap = StrokeCap.round;

    for (int i = 0; i + 1 < points.length; i += 2) {
      canvas.drawLine(points[i], points[i + 1], paint);
    }
    if (currentStart != null && currentEnd != null) {
      canvas.drawLine(
        currentStart!,
        currentEnd!,
        paint..color = Colors.black54,
      );
    }
  }

  @override
  bool shouldRepaint(_StraightLinePainter old) =>
      old.points != points ||
      old.currentStart != currentStart ||
      old.currentEnd != currentEnd;
}

class DrawingScreen extends StatefulWidget {
  final String prompt;
  final bool limitStrokes;
  final int maxStrokes;
  final SignatureController? initialController;
  final String? backgroundDrawingData;

  DrawingScreen({
    Key? key,
    required this.prompt,
    this.limitStrokes = false,
    this.maxStrokes = 30,
    this.initialController,
    this.backgroundDrawingData,
  }) : super(key: key);

  @override
  _DrawingScreenState createState() => _DrawingScreenState();
}

class _DrawingScreenState extends State<DrawingScreen> {
  late SignatureController _controller;
  int _currentStrokeCount = 0;

  final GlobalKey _canvasKey = GlobalKey();

  static const double CANVAS_WIDTH = 800.0;
  static const double CANVAS_HEIGHT = 600.0;

  @override
  void initState() {
    super.initState();
    _controller =
        widget.initialController ??
        SignatureController(
          penStrokeWidth: 5,
          penColor: Colors.black,
          exportBackgroundColor: Colors.transparent,
        );
    _controller.addListener(_updateStrokeCount);
  }

  @override
  void dispose() {
    _controller.removeListener(_updateStrokeCount);
    if (widget.initialController == null) {
      _controller.dispose();
    }
    super.dispose();
  }

  void _updateStrokeCount() {
    if (mounted) {
      setState(() {
        _currentStrokeCount =
            _controller.points.where((p) => p == null).length +
            (_controller.points.isNotEmpty ? 1 : 0);
      });
    }
  }

  Future<Uint8List?> _captureCanvas() async {
    try {
      RenderRepaintBoundary boundary =
          _canvasKey.currentContext!.findRenderObject()
              as RenderRepaintBoundary;

      ui.Image image = await boundary.toImage(pixelRatio: 1.0);
      ByteData? byteData = await image.toByteData(
        format: ui.ImageByteFormat.png,
      );

      return byteData?.buffer.asUint8List();
    } catch (e) {
      print('Erreur lors de la capture: $e');
      return null;
    }
  }

  Future<String?> _exportMergedImage() async {
    final Uint8List? canvasBytes = await _captureCanvas();

    if (canvasBytes == null) return null;

    final img.Image? capturedImage = img.decodeImage(canvasBytes);
    if (capturedImage == null) return null;

    final img.Image finalImage = img.copyResize(
      capturedImage,
      width: CANVAS_WIDTH.round(),
      height: CANVAS_HEIGHT.round(),
      interpolation:
          img
              .Interpolation
              .nearest, // Pas d'interpolation pour garder la netteté
    );

    return base64Encode(img.encodePng(finalImage));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.dessine),
        actions: [
          IconButton(
            icon: Icon(Icons.undo),
            onPressed: () => _controller.undo(),
          ),
          IconButton(
            icon: Icon(Icons.clear),
            onPressed: () => _controller.clear(),
          ),
        ],
        automaticallyImplyLeading: false,
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              widget.prompt,
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
          ),
          Expanded(
            child: Center(
              child: Container(
                margin: EdgeInsets.all(16),
                width: CANVAS_WIDTH,
                height: CANVAS_HEIGHT,
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(11),

                  child: RepaintBoundary(
                    key: _canvasKey,
                    child: Stack(
                      children: [
                        Positioned.fill(child: Container(color: Colors.white)),

                        if (widget.backgroundDrawingData != null)
                          Positioned.fill(
                            child: Image.memory(
                              base64Decode(widget.backgroundDrawingData!),
                              fit: BoxFit.fill,
                            ),
                          ),

                        Positioned.fill(
                          child: Signature(
                            controller: _controller,
                            backgroundColor: Colors.transparent,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: ElevatedButton(
              onPressed: () async {
                if (_controller.isEmpty &&
                    widget.backgroundDrawingData == null) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        AppLocalizations.of(
                          context,
                        )!.vousDevezDessinerQuelqueChose,
                      ),
                    ),
                  );
                  return;
                }

                final String? mergedBase64 = await _exportMergedImage();

                if (mergedBase64 != null) {
                  Navigator.of(context).pop({
                    'drawing': mergedBase64,
                    'strokeCount': _currentStrokeCount,
                  });
                } else {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        AppLocalizations.of(context)!.erreurLorsDeLaSauvegarde,
                      ),
                    ),
                  );
                }
              },
              child: Text(AppLocalizations.of(context)!.jAiFini),
            ),
          ),
        ],
      ),
    );
  }
}

class LocalPlayerSetupScreen extends StatefulWidget {
  final String? targetGame; // AJOUT
  LocalPlayerSetupScreen({this.targetGame});

  @override
  _LocalPlayerSetupScreenState createState() => _LocalPlayerSetupScreenState();
}

class _LocalPlayerSetupScreenState extends State<LocalPlayerSetupScreen> {
  final _nameController = TextEditingController();
  final List<String> _players = [];

  void _addPlayer() {
    final name = _nameController.text.trim();
    if (name.isNotEmpty && !_players.contains(name)) {
      setState(() {
        _players.add(name);
        _nameController.clear();
      });
    } else if (name.isNotEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(AppLocalizations.of(context)!.ceJoueurExisteDeja),
        ),
      );
    }
  }

  void _removePlayer(String name) {
    setState(() {
      _players.remove(name);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.participantsModeLocal),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              AppLocalizations.of(context)!.ajoutezLesJoueurs,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _nameController,
                    decoration: InputDecoration(
                      labelText: AppLocalizations.of(context)!.prenomDuJoueur,
                    ),
                    onSubmitted: (_) => _addPlayer(),
                  ),
                ),
                SizedBox(width: 8),
                IconButton(
                  icon: Icon(
                    Icons.add_circle,
                    color: Colors.deepPurpleAccent,
                    size: 30,
                  ),
                  onPressed: _addPlayer,
                ),
              ],
            ),
            SizedBox(height: 16),
            Expanded(
              child:
                  _players.isEmpty
                      ? Center(
                        child: Text(
                          AppLocalizations.of(context)!.ajoutezAuMoins2Joueurs,
                          style: TextStyle(color: Colors.white70),
                        ),
                      )
                      : ListView.builder(
                        itemCount: _players.length,
                        itemBuilder: (context, index) {
                          final player = _players[index];
                          return Card(
                            child: ListTile(
                              leading: CircleAvatar(
                                child: Text((index + 1).toString()),
                              ),
                              title: Text(player),
                              trailing: IconButton(
                                icon: Icon(
                                  Icons.remove_circle_outline,
                                  color: Colors.redAccent,
                                ),
                                onPressed: () => _removePlayer(player),
                              ),
                            ),
                          );
                        },
                      ),
            ),
            SizedBox(height: 16),
            ElevatedButton(
              onPressed:
                  _players.length < 2
                      ? null
                      : () {
                        if (widget.targetGame != null) {
                          // Lancer directement le bon jeu !
                          _launchLocalGame(widget.targetGame!);
                        } else {
                          // S'il n'y a pas de target, on ouvre le menu
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder:
                                  (_) => OfflineMenuScreen(players: _players),
                            ),
                          );
                        }
                      },
              child: Text(
                widget.targetGame != null
                    ? GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.lancer1,
                      [widget.targetGame],
                    )
                    : AppLocalizations.of(context)!.choisirUnJeu,
              ),
            ),
          ],
        ),
      ),
    );
  }

  void _launchLocalGame(String gameName) {
    Widget screen;
    bool isTeamGame = gameName == "Codenames" || gameName == "Time's Up";

    if (isTeamGame) {
      showDialog(
        context: context,
        builder: (BuildContext dialogContext) {
          return TeamSelectionDialog(
            allPlayers: _players,
            gameName: gameName,
            minPlayersPerTeam: _players.length >= 4 ? 2 : 1,
            onTeamsConfirmed: (teamA, teamB) {
              if (gameName == "Codenames") {
                return CodenamesLocalGameScreen(
                  players: _players,
                  redTeam: teamA,
                  blueTeam: teamB,
                );
              } else {
                return TimesUpLocalGameScreen(
                  players: _players,
                  teamA: teamA,
                  teamB: teamB,
                );
              }
            },
          );
        },
      );
      return; // On arrête ici, le dialog s'occupe du reste
    }

    // Assignation des jeux classiques
    switch (gameName) {
      case 'Qui Pourrait le Plus ?':
        screen = WhoIsMostLikelyLocalScreen(players: _players);
        break;
      case 'Infiltré & Mr. White':
      case 'Undercover Local':
        screen = UndercoverLocalGameScreen(players: _players);
        break;
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        screen = HotPotatoLocalScreen(players: _players);
        break;
      case 'Synonyme ou Banni':
        screen = SynonymOrBannedLocalScreen(players: _players);
        break;
      case 'Action ou Vérité':
        screen = TruthOrDareLocalSetupScreen(players: _players);
        break;
      case 'Jeu de la Pièce':
        screen = CoinFlipLocalSetupScreen(players: _players);
        break;
      case 'Le Dilemme':
        screen = DilemmaLocalSetupScreen(players: _players);
        break;
      case 'On se passe un objet rapidement':
        screen = PassTheObjectGameScreen(players: _players);
        break;
      case 'Devine Tête':
        screen = GuessTheWordLocalScreen(players: _players);
        break;
      case 'Dobble':
        screen = DobbleLocalScreen(players: _players);
        break;
      default:
        screen = OfflineMenuScreen(players: _players);
        break;
    }

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(builder: (_) => screen),
    );
  }
}

class TeamSelectionDialog extends StatefulWidget {
  final List<String> allPlayers;
  final Widget Function(List<String> teamA, List<String> teamB)
  onTeamsConfirmed;
  final int minPlayersPerTeam;
  final String gameName;

  TeamSelectionDialog({
    Key? key,
    required this.allPlayers,
    required this.onTeamsConfirmed,
    required this.gameName,
    this.minPlayersPerTeam = 2,
  }) : super(key: key);

  @override
  _TeamSelectionDialogState createState() => _TeamSelectionDialogState();
}

class _TeamSelectionDialogState extends State<TeamSelectionDialog> {
  late List<String> unassignedPlayers;
  List<String> teamA = [];
  List<String> teamB = [];

  @override
  void initState() {
    super.initState();
    unassignedPlayers = List.from(widget.allPlayers);
  }

  void _assignPlayer(String player, String team) {
    setState(() {
      unassignedPlayers.remove(player);
      teamA.remove(player);
      teamB.remove(player);

      if (team == 'A') teamA.add(player);
      if (team == 'B') teamB.add(player);
    });
  }

  void _unassignPlayer(String player) {
    setState(() {
      teamA.remove(player);
      teamB.remove(player);
      if (!unassignedPlayers.contains(player)) {
        unassignedPlayers.add(player);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = List.from(widget.allPlayers)..shuffle();
      teamA.clear();
      teamB.clear();
      unassignedPlayers.clear();
      for (int i = 0; i < all.length; i++) {
        if (i % 2 == 0) {
          teamA.add(all[i]);
        } else {
          teamB.add(all[i]);
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm =
        unassignedPlayers.isEmpty &&
        teamA.length >= widget.minPlayersPerTeam &&
        teamB.length >= widget.minPlayersPerTeam;

    return AlertDialog(
      title: Text(
        AppLocalizations.of(context)!.equipesPour.replaceAll(
          "{0}",
          GameRulesLocalization.getGameTitle(context, widget.gameName),
        ),
      ),
      content: Container(
        width: double.maxFinite,
        height: 400,
        child: Column(
          children: [
            ElevatedButton.icon(
              icon: Icon(Icons.sync),
              label: Text(
                AppLocalizations.of(context)!.equilibrerAleatoirement,
              ),
              onPressed: _autoBalance,
            ),
            SizedBox(height: 10),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _buildTeamColumn(
                    AppLocalizations.of(context)!.equipeARouge,
                    teamA,
                    'A',
                    Colors.redAccent,
                  ),
                  _buildTeamColumn(
                    AppLocalizations.of(context)!.equipeBBleue,
                    teamB,
                    'B',
                    Colors.blueAccent,
                  ),
                ],
