  Widget _buildGameCard(
    BuildContext context,
    String title,
    String description,
    IconData icon,
    Widget screen, {
    required int minPlayers,
    int? maxPlayers,
  }) {
    bool isTeamGame = title == "Codenames" || title == "Time's Up";

    return Card(
      elevation: 4,
      margin: EdgeInsets.only(bottom: 16),
      child: ListTile(
        leading: Icon(icon, size: 40, color: Colors.deepPurpleAccent),
        title: Text(
          GameContentLocalization.ui(context, title),
          style: Theme.of(context).textTheme.titleLarge,
        ),
        subtitle: Text(
          GameContentLocalization.ui(context, description),
          style: Theme.of(context).textTheme.bodyMedium,
        ),
        trailing: Icon(Icons.arrow_forward_ios),
        onTap: () {
          if (players.length < minPlayers) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.ilFautAuMoinsJoueurs,
                    [minPlayers],
                  ),
                ),
              ),
            );
            return;
          }
          if (maxPlayers != null && players.length > maxPlayers) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.ceModeSupporteAuMaximum,
                    [maxPlayers],
                  ),
                ),
              ),
            );
            return;
          }

          if (isTeamGame) {
            showDialog(
              context: context,
              builder: (BuildContext dialogContext) {
                return TeamSelectionDialog(
                  allPlayers: players,
                  gameName: title,
                  minPlayersPerTeam: 2,
                  onTeamsConfirmed: (teamA, teamB) {
                    if (title == "Codenames") {
                      return CodenamesLocalGameScreen(
                        players: players,
                        redTeam: teamA,
                        blueTeam: teamB,
                      );
                    } else {
                      // Time's Up
                      return TimesUpLocalGameScreen(
                        players: players,
                        teamA: teamA,
                        teamB: teamB,
                      );
                    }
                  },
                );
              },
            );
          } else {
            Navigator.push(context, MaterialPageRoute(builder: (_) => screen));
          }
        },
        contentPadding: EdgeInsets.symmetric(vertical: 10, horizontal: 16),
      ),
    );
  }
}

