class TruthOrDareLocalSetupScreen extends StatefulWidget {
  final List<String> players;
  TruthOrDareLocalSetupScreen({Key? key, required this.players})
    : super(key: key);

  @override
  State<TruthOrDareLocalSetupScreen> createState() =>
      _TruthOrDareLocalSetupScreenState();
}

class _TruthOrDareLocalSetupScreenState
    extends State<TruthOrDareLocalSetupScreen> {
  String _difficulty = 'soft';
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiTruths = [];
  List<String> _aiDares = [];

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

  void _launchGame() {
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder:
            (_) => TruthOrDareLocalGameScreen(
              players: widget.players,
              difficulty: _difficulty,
              customTruths: _aiTruths,
              customDares: _aiDares,
            ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.parametresActionOuVerite1),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Action ou Vérité'),
          ),
        ],
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Center(
              child: Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: Colors.deepPurple.withOpacity(0.15),
                ),
                child: Icon(
                  Icons.sync_problem,
                  size: 54,
                  color: Colors.deepPurpleAccent,
                ),
              ),
            ),
            SizedBox(height: 12),
            Text(
              AppLocalizations.of(context)!.parametresDeLaPartie,
              style: TextStyle(
                fontSize: 22,
                fontWeight: FontWeight.bold,
                color: Colors.white,
              ),
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 24),

            Text(
              AppLocalizations.of(context)!.k1IntensiteDesDefis,
              style: TextStyle(
                fontWeight: FontWeight.bold,
                color: Colors.white70,
              ),
            ),
            SizedBox(height: 8),
            SegmentedButton<String>(
              segments: [
                ButtonSegment(
                  value: 'soft',
                  label: Text(AppLocalizations.of(context)!.soft),
                ),
                ButtonSegment(
                  value: 'hard',
                  label: Text(AppLocalizations.of(context)!.hard),
                ),
                ButtonSegment(
                  value: 'hardcore',
                  label: Text(AppLocalizations.of(context)!.hardcore),
                ),
              ],
              selected: {_difficulty},
              onSelectionChanged: (s) => setState(() => _difficulty = s.first),
            ),
            SizedBox(height: 20),

            // IA Génératrice
            Consumer<PlayerState>(
              builder: (ctx, ps, _) {
                if (!ps.isPremium) return const SizedBox.shrink();
                return Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Color(0xFF1E1E2E),
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(
                      color: Colors.amberAccent.withOpacity(0.5),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Icon(
                            Icons.auto_awesome,
                            color: Colors.amberAccent,
                            size: 20,
                          ),
                          SizedBox(width: 8),
                          Text(
                            AppLocalizations.of(
                              context,
                            )!.generationIaPersonnalisee,
                            style: TextStyle(
                              color: Colors.amberAccent,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                      SizedBox(height: 10),
                      TextField(
                        controller: _aiController,
                        decoration: InputDecoration(
                          hintText:
                              AppLocalizations.of(
                                context,
                              )!.exSoireePyjamaSecretsDe,
                          hintStyle: TextStyle(color: Colors.white38),
                          filled: true,
                          fillColor: Colors.black.withOpacity(0.3),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                      ),
                      SizedBox(height: 10),
                      ElevatedButton.icon(
                        icon:
                            _isAiLoading
                                ? SizedBox(
                                  width: 14,
                                  height: 14,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                    color: Colors.black,
                                  ),
                                )
                                : Icon(Icons.bolt, color: Colors.black),
                        label: Text(
                          _isAiLoading
                              ? AppLocalizations.of(context)!.generation
                              : AppLocalizations.of(
                                context,
                              )!.genererLesDefisParIa,
                        ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.amberAccent,
                          foregroundColor: Colors.black,
                        ),
                        onPressed:
                            _isAiLoading
                                ? null
                                : () async {
                                  if (_aiController.text.trim().isNotEmpty) {
                                    setState(() => _isAiLoading = true);
                                    try {
                                      final res =
                                          await FirebaseService.generateAiWords(
                                            instructions: AppLocalizations.of(
                                              context,
                                            )!.genereUnMelangeDActions(
                                              _aiController.text.trim(),
                                            ),
                                            count: 30,
                                            gameType: 'Action ou Vérité',
                                          );
                                      if (res.isNotEmpty) {
                                        setState(() {
                                          final parsedDares = <String>[];
                                          final parsedTruths = <String>[];
                                          final unprefixed = <String>[];
                                          for (final item in res) {
                                            final trimmed = item.trim();
                                            final lower = trimmed.toLowerCase();
                                            if (lower.startsWith('action:') ||
                                                lower.startsWith('action :')) {
                                              parsedDares.add(
                                                trimmed
                                                    .substring(
                                                      trimmed.indexOf(':') + 1,
                                                    )
                                                    .trim(),
                                              );
                                            } else if (lower.startsWith(
                                                  'vérité:',
                                                ) ||
                                                lower.startsWith('vérité :') ||
                                                lower.startsWith('verite:') ||
                                                lower.startsWith('verite :')) {
                                              parsedTruths.add(
                                                trimmed
                                                    .substring(
                                                      trimmed.indexOf(':') + 1,
                                                    )
                                                    .trim(),
                                              );
                                            } else {
                                              unprefixed.add(trimmed);
                                            }
                                          }
                                          for (
                                            int i = 0;
                                            i < unprefixed.length;
                                            i++
                                          ) {
                                            if (i.isEven) {
                                              parsedDares.add(unprefixed[i]);
                                            } else {
                                              parsedTruths.add(unprefixed[i]);
                                            }
                                          }
                                          _aiDares =
                                              parsedDares.isNotEmpty
                                                  ? parsedDares
                                                  : res;
                                          _aiTruths =
                                              parsedTruths.isNotEmpty
                                                  ? parsedTruths
                                                  : res;
                                        });
                                        ScaffoldMessenger.of(
                                          context,
                                        ).showSnackBar(
                                          SnackBar(
                                            content: Text(
                                              GameContentLocalization.format(
                                                context,
                                                AppLocalizations.of(
                                                  context,
                                                )!.defisIaGeneres,
                                                [res.length],
                                              ),
                                            ),
                                            backgroundColor: Colors.green[800],
                                          ),
                                        );
                                      }
                                    } finally {
                                      if (mounted) {
                                        setState(() => _isAiLoading = false);
                                      }
                                    }
                                  }
                                },
                      ),
                      if (_aiTruths.isNotEmpty || _aiDares.isNotEmpty) ...[
                        SizedBox(height: 6),
                        Text(
                          GameContentLocalization.format(
                            context,
                            AppLocalizations.of(context)!.defisPrets,
                            [_aiTruths.length + _aiDares.length],
                          ),
                          style: TextStyle(
                            color: Colors.greenAccent,
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ],
                  ),
                );
              },
            ),
            SizedBox(height: 30),

            ElevatedButton.icon(
              icon: Icon(Icons.play_arrow_rounded, size: 28),
              label: Text(
                AppLocalizations.of(context)!.commencerLaPartie,
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.deepPurple,
                padding: const EdgeInsets.symmetric(vertical: 16),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16),
                ),
              ),
              onPressed: _launchGame,
            ),
          ],
        ),
      ),
    );
  }
}

class TruthOrDareLocalGameScreen extends StatefulWidget {
  final List<String> players;
  final String difficulty;
  final List<String> customTruths;
  final List<String> customDares;

  TruthOrDareLocalGameScreen({
    Key? key,
    required this.players,
    this.difficulty = 'soft',
    this.customTruths = const [],
    this.customDares = const [],
  }) : super(key: key);

  @override
  State<TruthOrDareLocalGameScreen> createState() =>
      _TruthOrDareLocalGameScreenState();
}

class _TruthOrDareLocalGameScreenState
    extends State<TruthOrDareLocalGameScreen> {
  late String _difficulty;
  String _currentContent = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;
  bool _playerHasToChoose = false;
  final Map<String, int> _scores = {};

  @override
  void initState() {
    super.initState();
    _difficulty = widget.difficulty;
    for (var p in widget.players) {
      _scores[p] = 0;
    }
  }

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _playerHasToChoose = true;
      _currentContent = "";
    });
  }

  void _generateNewContent(String type) {
    List<String> contentList = [];
    if (type == 'truth') {
      contentList =
          widget.customTruths.isNotEmpty
              ? widget.customTruths
              : (GameWords.truths[_difficulty] ?? GameWords.truths['soft']!);
    } else {
      contentList =
          widget.customDares.isNotEmpty
              ? widget.customDares
              : (GameWords.dares[_difficulty] ?? GameWords.dares['soft']!);
    }

    String content = contentList[Random().nextInt(contentList.length)];

    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex != -1 &&
          _currentPlayerIndex < otherPlayers.length) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        content = content.replaceAll(
          '{player}',
          otherPlayers[Random().nextInt(otherPlayers.length)],
        );
      } else {
        content = content.replaceAll(
          '{player}',
          AppLocalizations.of(context)!.toiMeme,
        );
      }
    }

    int xpGain =
        (type == 'truth')
            ? (_difficulty == 'hardcore' ? 25 : 15)
            : (_difficulty == 'hardcore' ? 45 : 28);
    Provider.of<PlayerState>(context, listen: false).addXp(xpGain);

    if (_currentPlayerIndex != -1 &&
        _currentPlayerIndex < widget.players.length) {
      final p = widget.players[_currentPlayerIndex];
      _scores[p] = (_scores[p] ?? 0) + (type == 'truth' ? 1 : 2);
    }

    setState(() {
      _currentContent = content;
      _playerHasToChoose = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final currentPlayer =
        (_currentPlayerIndex >= 0 &&
                _currentPlayerIndex < widget.players.length)
            ? widget.players[_currentPlayerIndex]
            : "";

    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.actionOuVerite),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Action ou Vérité'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: Duration(milliseconds: 500),
                  child: _buildMainContent(currentPlayer),
                ),
              ),
            ),
            SizedBox(height: 10),
            _buildGameControls(),
            SizedBox(height: 10),
            _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildMainContent(String currentPlayer) {
    if (_isSpinning) {
      return SpinTheWheelWidget(
        key: ValueKey('wheel'),
        players: widget.players,
        onSpinEnd: _onWheelStopped,
      );
    }
    if (_playerHasToChoose) {
      return Card(
        key: ValueKey('choice'),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 10),
              Text(
                AppLocalizations.of(context)!.choisisTonDestin,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    if (_currentContent.isNotEmpty) {
      return Card(
        key: ValueKey(_currentContent),
        elevation: 4,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                AppLocalizations.of(context)!.cEstAuTourDe,
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 20),
              Text(
                _currentContent,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    return Text(
      AppLocalizations.of(context)!.appuyezSurLancerLaRoue,
      style: Theme.of(
        context,
      ).textTheme.headlineSmall?.copyWith(color: Colors.white70),
      textAlign: TextAlign.center,
    );
  }

  Widget _buildGameControls() {
    if (_isSpinning) return SizedBox(height: 50);

    if (_playerHasToChoose) {
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.teal,
              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
            ),
            onPressed: () => _generateNewContent('truth'),
            child: Text(AppLocalizations.of(context)!.verite),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.deepOrangeAccent,
              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
            ),
            onPressed: () => _generateNewContent('dare'),
            child: Text(AppLocalizations.of(context)!.action),
          ),
        ],
      );
    }

    return ElevatedButton(
      style: ElevatedButton.styleFrom(
        backgroundColor: Colors.deepPurple,
        padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 14),
      ),
      onPressed: () => setState(() => _isSpinning = true),
      child: Text(
        _currentPlayerIndex == -1
            ? AppLocalizations.of(context)!.lancerLaRoue
            : AppLocalizations.of(context)!.tourSuivant,
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final p = widget.players[index];
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return Chip(
          label: Text(
            GameContentLocalization.format(
              context,
              AppLocalizations.of(context)!.pts9,
              [p, _scores[p] ?? 0],
            ),
          ),
          backgroundColor: isCurrent ? Colors.deepPurple : Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
        );
      }),
    );
  }
}

