                                  if (_aiController.text.trim().isNotEmpty) {
                                    setState(() => _isAiLoading = true);
                                    try {
                                      final res =
                                          await FirebaseService.generateAiWords(
                                            instructions:
                                                GameContentLocalization.format(
                                                  context,
                                                  AppLocalizations.of(
                                                    context,
                                                  )!.genereDesDilemmesAuFormat,
                                                  [_aiController.text.trim()],
                                                ),
                                            count: 25,
                                            gameType: 'Le Dilemme',
                                          );
