                                          context,
                                        ).showSnackBar(
                                          SnackBar(
                                            content: Text(
                                              GameContentLocalization.format(
                                                context,
                                                AppLocalizations.of(
                                                  context,
                                                )!.dilemmesIaGeneres,
                                                ["${res.length}"],
                                              ),
                                            ),
                                            backgroundColor: Colors.green[800],
                                          ),
                                        );
                                      }
                                    } finally {
                                      if (mounted) {
                                        setState(() => _isAiLoading = false);
                                      }
                                    }
                                  }
                                },
                      ),
                      if (_aiDilemmas.isNotEmpty) ...[
                        SizedBox(height: 6),
                        Text(
                          GameContentLocalization.format(
                            context,
                            AppLocalizations.of(context)!.dilemmesPrets,
                            ["${_aiDilemmas.length}"],
                          ),
                          style: TextStyle(
                            color: Colors.greenAccent,
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ],
                  ),
                );
              },
            ),
            SizedBox(height: 30),

            ElevatedButton.icon(
              icon: Icon(Icons.play_arrow_rounded, size: 28),
              label: Text(
                AppLocalizations.of(context)!.commencerLesDilemmes,
                style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.teal[700],
                padding: const EdgeInsets.symmetric(vertical: 16),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16),
                ),
              ),
              onPressed: _launchGame,
            ),
          ],
        ),
      ),
    );
  }
}

class DilemmaLocalGameScreen extends StatefulWidget {
  final List<String> players;
  final String difficulty;
  final bool useWheel;
  final List<String> customDilemmas;

  DilemmaLocalGameScreen({
    Key? key,
    required this.players,
    this.difficulty = 'soft',
    this.useWheel = true,
    this.customDilemmas = const [],
  }) : super(key: key);

  @override
  State<DilemmaLocalGameScreen> createState() => _DilemmaLocalGameScreenState();
}

class _DilemmaLocalGameScreenState extends State<DilemmaLocalGameScreen> {
  late String _difficulty;
  late bool _useWheelForDilemma;
  String _currentContent = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;

  final Map<String, String> _dilemmaVotes = {};
  int _dilemmaVoterIndex = 0;
  String? _activeDilemmaVoterId;
  String _dilemmaOptionA = "";
  String _dilemmaOptionB = "";
  final Map<String, int> _globalScores = {};

  @override
  void initState() {
    super.initState();
    _difficulty = widget.difficulty;
    _useWheelForDilemma = widget.useWheel;
    for (var p in widget.players) {
      _globalScores[p] = 0;
    }
  }

  void _showScoreDialog(String selectedPlayer) {
    showDialog(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (context, setStateDialog) {
            return AlertDialog(
              title: Text(
                AppLocalizations.of(context)!.gererLesScores,
                textAlign: TextAlign.center,
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children:
                    widget.players.map((p) {
                      bool isSelected = p == selectedPlayer;
                      return ListTile(
                        title: Text(
                          p,
                          style: TextStyle(
                            fontWeight:
                                isSelected
                                    ? FontWeight.bold
                                    : FontWeight.normal,
                            color: isSelected ? Colors.amber : Colors.white,
                          ),
                        ),
                        trailing: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            IconButton(
                              icon: Icon(
                                Icons.remove_circle_outline,
                                color: Colors.redAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) - 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                            Text(
                              "${_globalScores[p]}",
                              style: TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            IconButton(
                              icon: Icon(
                                Icons.add_circle_outline,
                                color: Colors.greenAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) + 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: Text(AppLocalizations.of(context)!.fermer),
                ),
              ],
            );
          },
        );
      },
    );
  }

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _generateNewContent();
      if (widget.players.isNotEmpty) {
        _activeDilemmaVoterId = widget.players[selectedIndex];
      }
    });
  }

  String _processContent(String content) {
    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex >= 0 &&
          _currentPlayerIndex < otherPlayers.length) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        String randomPlayer =
            otherPlayers[Random().nextInt(otherPlayers.length)];
        return content.replaceAll('{player}', randomPlayer);
      } else {
        return content.replaceAll(
          '{player}',
          AppLocalizations.of(context)!.toiMeme,
        );
      }
    }
    return content;
  }

  List<String> _splitDilemmaOptions(String content) {
    final normalized = content.trim().replaceFirst(RegExp(r'[?]+$'), '');
    final match = RegExp(
      r'\sou\s',
      caseSensitive: false,
    ).firstMatch(normalized);

    if (match == null) {
      return [normalized, AppLocalizations.of(context)!.jePasse];
    }

    final first = normalized.substring(0, match.start).trim();
    final second = normalized.substring(match.end).trim();

    if (first.isEmpty || second.isEmpty) {
      return [normalized, AppLocalizations.of(context)!.jePasse];
    }

    return [first, second];
  }

  String _currentDilemmaWinner() {
    final optionACount =
        _dilemmaVotes.values.where((vote) => vote == 'A').length;
    final optionBCount =
        _dilemmaVotes.values.where((vote) => vote == 'B').length;

    if (optionACount == 0 && optionBCount == 0) return '';
    if (optionACount > optionBCount) return 'A';
    if (optionBCount > optionACount) return 'B';
    return 'TIE';
  }

  void _submitDilemmaVote(String playerId, String option) {
    setState(() {
      _dilemmaVotes[playerId] = option;
      if (!_useWheelForDilemma) {
        if (_dilemmaVoterIndex < widget.players.length - 1) {
          _dilemmaVoterIndex++;
          _activeDilemmaVoterId = widget.players[_dilemmaVoterIndex];
        } else {
          _activeDilemmaVoterId = null;
          _checkDilemmaXp();
        }
      } else {
        _activeDilemmaVoterId = null;
        Provider.of<PlayerState>(context, listen: false).addXp(15);
      }
    });
  }

  void _checkDilemmaXp() {
    int countA = _dilemmaVotes.values.where((v) => v == 'A').length;
    int countB = _dilemmaVotes.values.where((v) => v == 'B').length;

    bool isUltraMinority = (countA == 1 || countB == 1);
    bool isConsensus = (countA == 0 || countB == 0);
    int xpGain = isUltraMinority ? 30 : (isConsensus ? 22 : 16);

    Provider.of<PlayerState>(context, listen: false).addXp(xpGain);
  }

  Widget _buildDilemmaOptionCard({
    required BuildContext context,
    required String optionKey,
    required String optionText,
    required Color color,
  }) {
    final voteCount =
        _dilemmaVotes.values.where((vote) => vote == optionKey).length;
    final totalVotes = _dilemmaVotes.isEmpty ? 1 : _dilemmaVotes.length;
    final progress = (voteCount / totalVotes).clamp(0.0, 1.0);
    final winner = _currentDilemmaWinner();
    final isWinning = winner == optionKey;
    final isTied = winner == 'TIE';

    return Expanded(
      child: GestureDetector(
        onTap:
            _activeDilemmaVoterId == null
                ? null
                : () => _submitDilemmaVote(_activeVoterOrCurrent(), optionKey),
        child: AnimatedContainer(
          duration: Duration(milliseconds: 250),
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color:
                isWinning ? color.withOpacity(0.28) : color.withOpacity(0.16),
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: isWinning ? color : Colors.white12,
              width: isWinning ? 2.5 : 1.0,
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                optionText,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: 16,
                ),
              ),
              SizedBox(height: 14),
              ClipRRect(
                borderRadius: BorderRadius.circular(999),
                child: LinearProgressIndicator(
                  minHeight: 10,
                  value: progress,
                  backgroundColor: Colors.white10,
                  valueColor: AlwaysStoppedAnimation<Color>(color),
                ),
              ),
              SizedBox(height: 10),
              Text(
                voteCount <= 1
                    ? AppLocalizations.of(context)!.vote1
                    : GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.votes1,
                      ['$voteCount'],
                    ),
                style: TextStyle(
                  color: Colors.white70,
                  fontWeight: FontWeight.w600,
                ),
              ),
              if (isWinning && voteCount > 0)
                Padding(
                  padding: EdgeInsets.only(top: 8.0),
                  child: Text(
                    isTied
                        ? AppLocalizations.of(context)!.egalite
                        : AppLocalizations.of(context)!.majoritaire,
                    style: TextStyle(color: color, fontWeight: FontWeight.bold),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

  String _getInstructionText() {
    if (_useWheelForDilemma) {
      final voterName =
          _currentPlayerIndex != -1
              ? widget.players[_currentPlayerIndex]
              : '...';
      return _activeDilemmaVoterId == null
          ? AppLocalizations.of(context)!.choixEnregistre
          : GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.dilemmePourFaisTonChoix,
            [voterName],
          );
    } else {
      return _activeDilemmaVoterId == null
          ? AppLocalizations.of(context)!.tousLesVotesSontEnregistres
          : GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.cEstAuTourDe1,
            ["$_activeDilemmaVoterId"],
          );
    }
  }

  String _getCurrentVoterName() {
    return _useWheelForDilemma
        ? (_currentPlayerIndex != -1
            ? widget.players[_currentPlayerIndex]
            : AppLocalizations.of(context)!.joueur)
        : (_activeDilemmaVoterId ?? AppLocalizations.of(context)!.fin);
  }

  String _activeVoterOrCurrent() {
    return _useWheelForDilemma
        ? _getCurrentVoterName()
        : (_activeDilemmaVoterId ?? "");
  }

  Widget _buildDilemmaVoteUI(BuildContext context) {
    final allVotesCast =
        _useWheelForDilemma
            ? _dilemmaVotes.isNotEmpty
            : _dilemmaVotes.length >= widget.players.length;

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          padding: const EdgeInsets.only(bottom: 16),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Card(
                  elevation: 6,
                  color: Colors.blueGrey[900],
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: Padding(
                    padding: const EdgeInsets.all(20.0),
                    child: Column(
                      children: [
                        Text(
                          AppLocalizations.of(context)!.leDilemme,
                          style: TextStyle(
                            color: Colors.amberAccent,
                            letterSpacing: 2,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                        SizedBox(height: 12),
                        Text(
                          _currentContent,
                          textAlign: TextAlign.center,
                          style: Theme.of(
                            context,
                          ).textTheme.headlineSmall?.copyWith(fontSize: 20),
                        ),
                      ],
                    ),
                  ),
                ),
                SizedBox(height: 16),
                Text(
                  _getInstructionText(),
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 12),
                if (!_useWheelForDilemma && _activeDilemmaVoterId != null)
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    alignment: WrapAlignment.center,
                    children:
                        widget.players.map((player) {
                          final hasVoted = _dilemmaVotes.containsKey(player);
                          final isActive = player == _activeDilemmaVoterId;
                          return Chip(
                            label: Text(player),
                            backgroundColor:
                                isActive
                                    ? Colors.deepPurple
                                    : (hasVoted
                                        ? Colors.green[800]
                                        : Colors.white10),
                            labelStyle: TextStyle(
                              color: Colors.white,
                              fontWeight:
                                  isActive
                                      ? FontWeight.bold
                                      : FontWeight.normal,
                            ),
                          );
                        }).toList(),
                  ),
                SizedBox(height: 20),
                Row(
                  children: [
                    _buildDilemmaOptionCard(
                      context: context,
                      optionKey: 'A',
                      optionText: _dilemmaOptionA,
                      color: Colors.deepPurpleAccent,
                    ),
                    SizedBox(width: 12),
                    _buildDilemmaOptionCard(
                      context: context,
                      optionKey: 'B',
                      optionText: _dilemmaOptionB,
                      color: Colors.teal,
                    ),
                  ],
                ),
                SizedBox(height: 20),
                if (allVotesCast)
                  ElevatedButton.icon(
                    icon: Icon(Icons.arrow_forward),
                    label: Text(AppLocalizations.of(context)!.dilemmeSuivant),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.green,
                      padding: const EdgeInsets.symmetric(
                        horizontal: 24,
                        vertical: 12,
                      ),
                    ),
                    onPressed:
                        () => setState(() {
                          _isSpinning = false;
                          _currentContent = "";
                          _currentPlayerIndex = -1;
                          _dilemmaVotes.clear();
                          _activeDilemmaVoterId = null;
                          _dilemmaOptionA = "";
                          _dilemmaOptionB = "";
                        }),
                  )
                else if (_useWheelForDilemma)
                  Text(
                    AppLocalizations.of(context)!.leJoueurDesigneDoitFaire,
                    style: TextStyle(
                      color: Colors.white38,
                      fontStyle: FontStyle.italic,
                    ),
                  )
                else
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.enAttenteDuVoteDe,
                      [
                        '$_activeDilemmaVoterId',
                        '${_dilemmaVotes.length}',
                        '${widget.players.length}',
                      ],
                    ),
                    style: TextStyle(
                      color: Colors.white54,
                      fontStyle: FontStyle.italic,
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _generateNewContent() {
    List<String> contentList = [];
    Random random = Random();

    if (widget.customDilemmas.isNotEmpty) {
      contentList = widget.customDilemmas;
    } else {
      contentList =
          GameWords.dilemmas[_difficulty] ?? GameWords.dilemmas['soft']!;
    }

    String nextContent = _processContent(
      contentList[random.nextInt(contentList.length)],
    );

    setState(() {
      _currentContent = nextContent;
      final dilemmaOptions = _splitDilemmaOptions(nextContent);
      _dilemmaOptionA = dilemmaOptions[0];
      _dilemmaOptionB = dilemmaOptions[1];
      _dilemmaVotes.clear();

      if (_useWheelForDilemma) {
        _activeDilemmaVoterId =
            _currentPlayerIndex != -1
                ? widget.players[_currentPlayerIndex]
                : null;
      } else {
        _dilemmaVoterIndex = 0;
        _activeDilemmaVoterId =
            widget.players.isNotEmpty ? widget.players.first : null;
      }
    });
  }

  void _startNextDilemmaRoundDirectly() {
    setState(() {
      _isSpinning = false;
      _generateNewContent();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.leDilemme1),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Le Dilemme'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: Duration(milliseconds: 500),
                  transitionBuilder:
                      (child, animation) =>
                          ScaleTransition(scale: animation, child: child),
                  child:
                      _currentContent.isNotEmpty
                          ? _buildDilemmaVoteUI(context)
                          : _isSpinning
                          ? SpinTheWheelWidget(
                            key: ValueKey('wheel_spin'),
                            players: widget.players,
                            onSpinEnd: _onWheelStopped,
                          )
                          : Text(
                            AppLocalizations.of(
                              context,
                            )!.appuyezSurLancerPourCommencer,
                            style: Theme.of(context).textTheme.headlineSmall
                                ?.copyWith(color: Colors.white70),
                            textAlign: TextAlign.center,
                          ),
                ),
              ),
            ),
            SizedBox(height: 10),
            if (_currentContent.isEmpty && !_isSpinning)
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.teal[700],
                  padding: const EdgeInsets.symmetric(
                    horizontal: 32,
                    vertical: 14,
                  ),
                ),
                onPressed: () {
                  if (!_useWheelForDilemma) {
                    _startNextDilemmaRoundDirectly();
                  } else {
                    setState(() => _isSpinning = true);
                  }
                },
                child: Text(
                  !_useWheelForDilemma
                      ? AppLocalizations.of(context)!.lancerLeDilemme
                      : AppLocalizations.of(context)!.lancerLaRoue,
                ),
              ),
            SizedBox(height: 10),
            if (_currentContent.isEmpty || _isSpinning) _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final pName = widget.players[index];
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return ActionChip(
          avatar: CircleAvatar(
            backgroundColor: Colors.white24,
            child: Text(
              pName[0],
              style: TextStyle(fontSize: 10, color: Colors.white),
            ),
          ),
          label: Text(
            GameContentLocalization.format(
              context,
              AppLocalizations.of(context)!.pts9,
              [pName, _globalScores[pName]],
            ),
          ),
          backgroundColor: isCurrent ? Colors.teal : Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
          onPressed: () => _showScoreDialog(pName),
        );
      }),
    );
  }
}

