        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                AppLocalizations.of(context)!.resultatDuTour,
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              Text(
                _resultMessage,
                textAlign: TextAlign.center,
                style: Theme.of(
                  context,
                ).textTheme.titleLarge?.copyWith(color: Colors.amber),
              ),
              if (_resultMessage.contains("gagnent")) ...[
                SizedBox(height: 20),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.leMotDesCivilsEtait1,
                    [_wordCivil],
                  ),
                  style: TextStyle(fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.leMotDeLInfiltre1,
                    [_wordUndercover],
                  ),
                  style: TextStyle(fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
              ],
              SizedBox(height: 30),
              ElevatedButton(
                onPressed:
                    () =>
                        setState(() => _gameState = UndercoverGameState.setup),
                child: Text(AppLocalizations.of(context)!.nouvelleManche),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

enum HotPotatoState { setup, playing, exploded }

class HotPotatoLocalScreen extends StatefulWidget {
  final List<String> players;
  HotPotatoLocalScreen({Key? key, required this.players}) : super(key: key);

  @override
  _HotPotatoLocalScreenState createState() => _HotPotatoLocalScreenState();
}

class _HotPotatoLocalScreenState extends State<HotPotatoLocalScreen>
    with TickerProviderStateMixin {
  HotPotatoState _gameState = HotPotatoState.setup;
  Timer? _turnTimer;
  int _secondsLeft = 0;
  final Random _random = Random();
  final _answerController = TextEditingController();
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiCategories = [];

  int _currentPlayerIndex = 0;
  List<String> _usedAnswers = [];

  String _selectedCategory = GameWords.hotPotatoCategories['soft']!.keys.first;
  int _turnDuration = 10;
  bool _useGlobalTimer = false;
  int _globalDuration = 30;

  @override
  void dispose() {
    _turnTimer?.cancel();
    _answerController.dispose();
    _aiController.dispose();
    super.dispose();
  }

  void _startGame() {
    _turnTimer?.cancel(); // Annule tout timer précédent par sécurité
    _usedAnswers.clear();
    _currentPlayerIndex = _random.nextInt(widget.players.length);

    if (_useGlobalTimer) {
      _secondsLeft = _globalDuration;
    } else {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        // Mode aléatoire
        duration = 5 + _random.nextInt(11); // 5 à 15 secondes
      }
      _secondsLeft = duration;
    }

    _turnTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (_secondsLeft > 1) {
        setState(() => _secondsLeft--);
      } else {
        _explode();
      }
    });

    setState(() {
      _gameState = HotPotatoState.playing;
    });
  }

  void _explode() {
    _turnTimer?.cancel();
    HapticFeedback.vibrate();
    setState(() {
      _gameState = HotPotatoState.exploded;
    });
  }

  void _passPotato() {
    final answer = _answerController.text.trim().toLowerCase();
    if (answer.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(AppLocalizations.of(context)!.tuDoisEcrireUneReponse),
        ),
      );
      return;
    }
    if (_usedAnswers.contains(answer)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(AppLocalizations.of(context)!.cetteReponseADejaEte),
        ),
      );
      return;
    }

    _answerController.clear();
    FocusScope.of(context).unfocus();

    if (!_useGlobalTimer) {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        duration = 5 + _random.nextInt(11);
      }
      _secondsLeft = duration;
    }

    setState(() {
      _usedAnswers.add(answer);
      _currentPlayerIndex = (_currentPlayerIndex + 1) % widget.players.length;
    });
  }

  void _resetGame() {
    _turnTimer?.cancel();
    setState(() {
      _gameState = HotPotatoState.setup;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.laPatateChaude),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'La Patate Chaude'),
          ),
        ],
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
