  Widget _buildWordInputPhase() {
    String currentPlayerForInput = widget.players[_currentPlayerIndex];
    int wordsForCurrentPlayer =
        _playersWords[currentPlayerForInput]?.length ?? 0;

    return Column(
      key: ValueKey('word_input_$_currentPlayerIndex'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.passeLeTelephoneA1,
            [currentPlayerForInput],
          ),
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        Text(
          AppLocalizations.of(context)!.ajoute5MotsQueTu,
          style: Theme.of(context).textTheme.bodyMedium,
        ),
        SizedBox(height: 20),
        TextField(
          controller: _wordInputController,
          decoration: InputDecoration(
            labelText: GameContentLocalization.format(
              context,
              AppLocalizations.of(context)!.mot5,
              ["${wordsForCurrentPlayer + 1}"],
            ),
          ),
          onSubmitted: (_) {
            if (_wordInputController.text.trim().isNotEmpty) {
              _addPlayerWord(
                currentPlayerForInput,
                _wordInputController.text.trim(),
              );
              _wordInputController.clear();
              if (wordsForCurrentPlayer + 1 >= 5) {
                if (_currentPlayerIndex < widget.players.length - 1) {
                  setState(() => _currentPlayerIndex++);
                } else {
                  _finishWordInput();
                }
              }
            }
          },
        ),
        SizedBox(height: 20),
        ElevatedButton(
          onPressed: () {
            if (_wordInputController.text.trim().isNotEmpty) {
              _addPlayerWord(
                currentPlayerForInput,
                _wordInputController.text.trim(),
              );
              _wordInputController.clear(); // Vider le champ après l'ajout
            }
          },
          child: Text(AppLocalizations.of(context)!.ajouterCeMot),
        ),
        SizedBox(height: 20),
        ElevatedButton(
          onPressed:
              wordsForCurrentPlayer >= 5
                  ? () {
                    if (_currentPlayerIndex < widget.players.length - 1) {
                      setState(() => _currentPlayerIndex++);
                    } else {
                      _finishWordInput();
                    }
                  }
                  : null,
          child: Text(
            AppLocalizations.of(context)!.jAiFiniDAjouter,
          ), // Nouveau bouton pour passer au joueur suivant
        ),
        SizedBox(height: 20),
        Text(
          GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.motsRestantsAAjouterPour,
            [currentPlayerForInput, "${5 - wordsForCurrentPlayer}"],
          ),
          style: TextStyle(color: Colors.white70),
        ),
        SizedBox(height: 20),
        Text(
          GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.totalDesMotsDansLe,
            ["${_allWords.length}"],
          ),
          style: Theme.of(context).textTheme.bodySmall,
        ),
      ],
    );
  }

  Widget _buildPlayingPhase() {
    String currentGuesser =
        (_activeTeam == 'red' ? _redTeam : _blueTeam)[_currentPlayerIndex];
    String currentWord =
        _currentDeck.isNotEmpty
            ? _currentDeck.first
            : AppLocalizations.of(context)!.timesUpRoundEnd;

    String modeText = '';
    if (_currentRoundNumber == 1)
      modeText = AppLocalizations.of(context)!.timesUpModeFree;
    else if (_currentRoundNumber == 2)
      modeText = AppLocalizations.of(context)!.timesUpModeOneWord;
    else if (_currentRoundNumber == 3)
      modeText = AppLocalizations.of(context)!.mime;

    return Column(
      key: ValueKey('playing_round_$_currentRoundNumber'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.manche,
            ["$_currentRoundNumber", modeText],
          ),
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 8),
        Text(
          '$_timeRemaining s',
          style: TextStyle(
            fontSize: 28,
            fontWeight: FontWeight.bold,
            color: _timeRemaining <= 5 ? Colors.redAccent : Colors.amberAccent,
          ),
        ),
        SizedBox(height: 10),
        Text(
          GameContentLocalization.format(
            context,
            AppLocalizations.of(context)!.cEstAuTourDe2,
            [
              currentGuesser,
              _activeTeam == 'red'
                  ? AppLocalizations.of(context)!.codenamesRedTeam
                  : AppLocalizations.of(context)!.codenamesBlueTeam,
            ],
          ),
          style: Theme.of(context).textTheme.titleLarge,
        ),
        SizedBox(height: 20),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              children: [
                Text(
                  currentWord,
                  style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                    color: Colors.deepPurpleAccent,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 10),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.motsDevinesCeTour,
                    [_discardedWords.length],
                  ),
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.motsRestantsDansLePaquet,
                    [_currentDeck.length],
                  ),
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
              ],
            ),
          ),
        ),
        SizedBox(height: 20),
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            ElevatedButton(
              onPressed:
                  _currentDeck.isNotEmpty
                      ? () => _guessWord(currentWord, true)
                      : null,
              child: Text(AppLocalizations.of(context)!.devine),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.green),
            ),
            ElevatedButton(
              onPressed:
                  _currentDeck.isNotEmpty
                      ? () => _guessWord(currentWord, false)
                      : null,
              child: Text(AppLocalizations.of(context)!.passer),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.orange),
            ),
            ElevatedButton(
              onPressed: () => _endTurn(),
              child: Text(AppLocalizations.of(context)!.finDuTour1),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            ),
          ],
        ),
        SizedBox(height: 20),
        _buildTeamScoreDisplay(),
      ],
    );
  }

  Widget _buildGameOverScreen() {
    String winnerTeam = '';
    if ((_teamScores['red'] ?? -1) > (_teamScores['blue'] ?? -1)) {
      winnerTeam = AppLocalizations.of(context)!.rouge;
    } else if ((_teamScores['blue'] ?? -1) > (_teamScores['red'] ?? -1)) {
      winnerTeam = AppLocalizations.of(context)!.bleue;
    } else {
      winnerTeam = AppLocalizations.of(context)!.timesUpDraw;
    }

    if (_teamScores['red'] == -1) {
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  AppLocalizations.of(
                    context,
                  )!.erreurNombreDeJoueursInsuffisant,
                  style: Theme.of(context).textTheme.headlineMedium,
                  textAlign: TextAlign.center,
                ),
                Text(
                  AppLocalizations.of(context)!.veuillezRevenirALEcran,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed: () => Navigator.of(context).pop(),
                  child: Text(AppLocalizations.of(context)!.retour),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return Center(
      key: ValueKey('game_over'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                AppLocalizations.of(context)!.partieTerminee,
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 10),
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.lEquipeAGagne,
                  [winnerTeam],
                ),
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                  color:
                      winnerTeam == AppLocalizations.of(context)!.rouge
                          ? Colors.redAccent
                          : Colors.blueAccent,
                ),
              ),
              SizedBox(height: 20),
              _buildTeamScoreDisplay(),
              SizedBox(height: 40),
              ElevatedButton(
                onPressed: _resetGame,
                child: Text(AppLocalizations.of(context)!.nouvellePartie),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildTeamScoreDisplay() {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(8.0),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            Column(
              children: [
                Text(
                  AppLocalizations.of(context)!.rouge,
                  style: TextStyle(
                    color: Colors.redAccent,
                    fontWeight: FontWeight.bold,
                    fontSize: 18,
                  ),
                ),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.points1,
                    ["${_teamScores['red']}"],
                  ),
                  style: TextStyle(fontSize: 16),
                ),
              ],
            ),
            Text(
              AppLocalizations.of(context)!.vs,
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
            ),
            Column(
              children: [
                Text(
                  AppLocalizations.of(context)!.bleu,
                  style: TextStyle(
                    color: Colors.blueAccent,
                    fontWeight: FontWeight.bold,
                    fontSize: 18,
                  ),
                ),
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.points1,
                    ["${_teamScores['blue']}"],
                  ),
                  style: TextStyle(fontSize: 16),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

enum PassTheObjectGameState { setup, playing, questionPhase }

class PassTheObjectGameScreen extends StatefulWidget {
  final List<String> players;
  PassTheObjectGameScreen({Key? key, required this.players}) : super(key: key);

  @override
  _PassTheObjectGameScreenState createState() =>
      _PassTheObjectGameScreenState();
}

class _PassTheObjectGameScreenState extends State<PassTheObjectGameScreen>
    with TickerProviderStateMixin {
  PassTheObjectGameState _gameState = PassTheObjectGameState.setup;
  String _difficulty = 'soft';
  Timer? _gameTimer;
  Timer? _flashTimer;
  int _secondsRemaining = 0;
  final Random _random = Random();
  String _currentQuestion = "";
  int _loserIndex = 0;
  bool _isFlashing = false;

  bool _useButton = true;
  bool _showTimer = true;

  int _minDuration = 10;
  int _maxDuration = 30;

  String? _nextPlayerToPass;
  final List<int> _passedSequence =
      []; // Historique pour éviter la répétition immédiate du même joueur

  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiQuestions = [];

  @override
  void dispose() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _aiController.dispose();
    super.dispose();
  }

  void _startGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();

    if (_maxDuration > _minDuration) {
      _secondsRemaining =
          _minDuration + _random.nextInt(_maxDuration - _minDuration + 1);
    } else {
      _secondsRemaining = _minDuration;
    }

    _loserIndex = _random.nextInt(widget.players.length);
    _passedSequence.add(_loserIndex);
    _nextPlayerToPass = null; // Réinitialiser au début

    _gameTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _secondsRemaining--;
        if (_secondsRemaining <= 5 && _secondsRemaining > 0) {
          _startFlashing();
        }
        if (_secondsRemaining <= 0) {
          timer.cancel();
          _flashTimer?.cancel();
          _triggerQuestion();
        }
      });
    });

    setState(() {
      _gameState = PassTheObjectGameState.playing;
    });
  }

  void _passToRandomPlayer() {
    if (widget.players.length < 2) return;

    // Règle équitable : sélectionne un joueur différent qui n'a pas eu l'objet récemment
    List<int> eligibleIndices = [];
    for (int i = 0; i < widget.players.length; i++) {
      if (i != _loserIndex) {
        eligibleIndices.add(i);
      }
    }

    int nextIdx = eligibleIndices[_random.nextInt(eligibleIndices.length)];
    String nextPlayer = widget.players[nextIdx];

    // --- ATTRIBUTION XP LOCAL : +12 XP pour un passage réussi ---
    Provider.of<PlayerState>(context, listen: false).addXp(12);

    setState(() {
      _nextPlayerToPass = nextPlayer;
      _loserIndex = nextIdx;
      _passedSequence.add(nextIdx);
    });
  }

  void _startFlashing() {
    _flashTimer?.cancel();
    _flashTimer = Timer.periodic(Duration(milliseconds: 300), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _isFlashing = !_isFlashing;
      });
    });
  }

  void _triggerQuestion() {
    String cleanQ = "";
    if (_aiQuestions.isNotEmpty) {
      cleanQ = _aiQuestions[_random.nextInt(_aiQuestions.length)];
    } else {
      final questions =
          GameWords.passTheObjectQuestions[_difficulty] ??
          GameWords.passTheObjectQuestions['soft']!;
      String rawQ = questions[_random.nextInt(questions.length)];
      cleanQ = FirebaseService.sanitizeUserInput(rawQ, maxLength: 150);
    }

    // --- ATTRIBUTION XP LOCAL : +35 XP pour répondre à la question sous pression ---
    Provider.of<PlayerState>(context, listen: false).addXp(35);

    setState(() {
      _currentQuestion = cleanQ;
      _gameState = PassTheObjectGameState.questionPhase;
      _isFlashing = false;
    });
  }

  void _resetGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();
    setState(() {
      _gameState = PassTheObjectGameState.setup;
      _currentQuestion = "";
      _secondsRemaining = 0;
      _isFlashing = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.passeLObjet),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed:
                () => showGameRules(context, 'On se passe un objet rapidement'),
          ),
        ],
      ),
      body: AnimatedContainer(
        duration: Duration(milliseconds: 150),
        color:
            _isFlashing
                ? Colors.red.withOpacity(0.5)
                : Theme.of(context).scaffoldBackgroundColor,
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case PassTheObjectGameState.setup:
        return _buildSetupScreen();
      case PassTheObjectGameState.playing:
        return _buildPlayingScreen();
      case PassTheObjectGameState.questionPhase:
        return _buildQuestionPhase();
    }
  }

  Widget _buildSetupScreen() {
    return SingleChildScrollView(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(
                Icons.directions_run,
                size: 80,
                color: Colors.deepPurpleAccent,
              ),
              SizedBox(height: 10),
              Text(
                AppLocalizations.of(context)!.passeLObjetRapidement,
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              DropdownButtonFormField<String>(
                value: _difficulty,
                items:
                    GameWords.passTheObjectQuestions.keys
                        .map(
                          (diff) =>
                              DropdownMenuItem(value: diff, child: Text(diff)),
                        )
                        .toList(),
                onChanged: (val) => setState(() => _difficulty = val!),
                decoration: InputDecoration(
                  labelText:
                      AppLocalizations.of(context)!.difficulteDesQuestions,
                ),
              ),
              SizedBox(height: 16),

              // Module IA
              Consumer<PlayerState>(
                builder: (ctx, ps, _) {
                  if (!ps.isPremium) return const SizedBox.shrink();
                  return Container(
                    margin: const EdgeInsets.only(bottom: 16),
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: Color(0xFF1E1E2E),
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(
                        color: Colors.amberAccent.withOpacity(0.5),
                      ),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Icon(
                              Icons.auto_awesome,
                              color: Colors.amberAccent,
                              size: 18,
                            ),
                            SizedBox(width: 8),
                            Text(
                              AppLocalizations.of(
                                context,
                              )!.generationIaDeQuestions,
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                        SizedBox(height: 8),
                        TextField(
                          controller: _aiController,
                          decoration: InputDecoration(
                            hintText:
                                AppLocalizations.of(
                                  context,
                                )!.exCultureGeneraleGagesDroles,
                            hintStyle: TextStyle(color: Colors.white38),
                            filled: true,
                            fillColor: Colors.black.withOpacity(0.3),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                          ),
                        ),
