// =============================================================================
// 2. DOBBLE LOCAL (AVEC ÉCRAN DE CONFIGURATION COMPLET ET CHOIX DE SYMBOLES)
// =============================================================================

// =============================================================================
// 👁️ DOBBLE LOCAL - DESIGN ADAPTATIF ANTI-CHEVAUCHEMENT & TAPS RÉACTIFS
// =============================================================================
class DobbleLocalScreen extends StatefulWidget {
  final List<String> players;
  DobbleLocalScreen({Key? key, required this.players}) : super(key: key);

  @override
  _DobbleLocalScreenState createState() => _DobbleLocalScreenState();
}

class _DobbleLocalScreenState extends State<DobbleLocalScreen> {
  bool _isConfiguring = true;
  int _symbolsPerCard = 8; // 6 (Facile) ou 8 (Standard)
  int _targetScore = 10;

  List<List<String>> _deck = [];
  Map<String, List<String>> _playerCards = {};
  Map<String, int> _playerScores = {};
  List<String> _centerCard = [];
  bool _gameOver = false;
  String? _gameWinner;

  final List<Color> _playerColors = [
    Color(0xFF38BDF8), // Bleu ciel
    Color(0xFFF43F5E), // Rose néon
    Color(0xFF10B981), // Émeraude
    Color(0xFFF59E0B), // Ambre doré
    Color(0xFFA855F7), // Violet
    Color(0xFF06B6D4), // Cyan
  ];

  void _startNewGame() {
    final generatedCardsIndices = GameData.generateDobbleCards(_symbolsPerCard);
    List<List<String>> fullDeck =
        generatedCardsIndices.map((cardIndices) {
          return cardIndices
              .map((index) => GameData.dobbleSymbols[index])
              .toList();
        }).toList();
    fullDeck.shuffle();

    final initialScores = {for (var player in widget.players) player: 0};
    final initialPlayerCards = <String, List<String>>{};
    for (var player in widget.players) {
      if (fullDeck.isNotEmpty) {
        initialPlayerCards[player] = fullDeck.removeAt(0)..shuffle();
      }
    }

    final initialCenterCard =
        fullDeck.isNotEmpty ? (fullDeck.removeAt(0)..shuffle()) : <String>[];

    setState(() {
      _deck = fullDeck;
      _playerScores = initialScores;
      _playerCards = initialPlayerCards;
      _centerCard = initialCenterCard;
      _gameOver = initialCenterCard.isEmpty;
      _gameWinner = null;
      _isConfiguring = false;
    });
  }

  String? _findCommonSymbol(List<String> card1, List<String> card2) {
    final card2Symbols = card2.toSet();
    for (var symbol in card1) {
      if (card2Symbols.contains(symbol)) {
        return symbol;
      }
    }
    return null;
  }

  void _claimCard(String playerName, String tappedSymbol) {
    if (_gameOver) return;

    final myCard = _playerCards[playerName] ?? [];
    final common = _findCommonSymbol(myCard, _centerCard);

    if (common != null && common == tappedSymbol) {
      HapticFeedback.heavyImpact();
      final takenCard = List<String>.from(_centerCard);
      final newScore = (_playerScores[playerName] ?? 0) + 1;

      setState(() {
        _playerScores[playerName] = newScore;
        _playerCards[playerName] = takenCard..shuffle();

        if (newScore >= _targetScore || _deck.isEmpty) {
          _gameOver = true;
          _determineWinner();
        } else {
          _centerCard = _deck.removeAt(0)..shuffle();
        }
      });
    } else {
      HapticFeedback.lightImpact();
      ScaffoldMessenger.of(context).clearSnackBars();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            GameContentLocalization.format(
              context,
              AppLocalizations.of(context)!.mauvaisSymbole,
              [playerName],
            ),
          ),
          duration: Duration(milliseconds: 600),
          backgroundColor: Colors.red[800],
        ),
      );
    }
  }

  void _determineWinner() {
    if (_playerScores.isEmpty) {
      _gameWinner = AppLocalizations.of(context)!.personne;
      return;
    }
    final sortedScores =
        _playerScores.entries.toList()
          ..sort((a, b) => b.value.compareTo(a.value));
    _gameWinner = sortedScores.first.key;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Color(0xFF0D1117),
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.dobbleLocal),
        backgroundColor: Colors.transparent,
        elevation: 0,
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Dobble'),
          ),
        ],
      ),
      body:
          _isConfiguring
              ? _buildConfigUI()
              : (_gameOver ? _buildGameOverUI() : _buildGameUI()),
    );
  }

  // ===========================================================================
  // ⚙️ CONFIGURATION
  // ===========================================================================
  Widget _buildConfigUI() {
    return Center(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Container(
          constraints: BoxConstraints(maxWidth: 420),
          padding: const EdgeInsets.all(24),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              colors: [Color(0xFF1E1B4B), Color(0xFF0F172A)],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            ),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(color: Colors.purpleAccent.withOpacity(0.4)),
            boxShadow: [
              BoxShadow(
                color: Colors.purpleAccent.withOpacity(0.2),
                blurRadius: 20,
              ),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(
                Icons.remove_red_eye_rounded,
                size: 64,
                color: Colors.amberAccent,
              ),
              SizedBox(height: 12),
              Text(
                AppLocalizations.of(context)!.parametresDeLaPartie,
                style: TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 24),
              Text(
                AppLocalizations.of(context)!.symbolesParCarte,
                style: TextStyle(color: Colors.white70),
              ),
              SizedBox(height: 8),
              SegmentedButton<int>(
                segments: [
                  ButtonSegment(
                    value: 6,
                    label: Text(AppLocalizations.of(context)!.k6Facile),
                  ),
                  ButtonSegment(
                    value: 8,
                    label: Text(AppLocalizations.of(context)!.k8Standard),
                  ),
                ],
                selected: {_symbolsPerCard},
                onSelectionChanged:
                    (s) => setState(() => _symbolsPerCard = s.first),
              ),
              SizedBox(height: 20),
              Text(
                GameContentLocalization.format(
                  context,
                  AppLocalizations.of(context)!.scoreCibleCartes,
                  [_targetScore],
                ),
                style: TextStyle(color: Colors.white70),
              ),
              Slider(
                value: _targetScore.toDouble(),
                min: 5,
                max: 20,
                divisions: 3,
                label: "$_targetScore",
                onChanged: (v) => setState(() => _targetScore = v.toInt()),
              ),
              SizedBox(height: 24),
              ElevatedButton.icon(
                icon: Icon(Icons.play_arrow_rounded, size: 24),
                label: Text(
                  AppLocalizations.of(context)!.commencer2,
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.deepPurpleAccent,
                  padding: const EdgeInsets.symmetric(vertical: 16),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                onPressed: _startNewGame,
              ),
            ],
          ),
        ),
      ),
    );
  }

  // ===========================================================================
  // 🎮 ARÈNE DE JEU ADAPTATIVE SANS CHEVAUCHEMENT
  // ===========================================================================
  Widget _buildGameUI() {
    final int count = widget.players.length;

    return SafeArea(
      child: LayoutBuilder(
        builder: (context, constraints) {
          final double maxW = constraints.maxWidth;
          final double maxH = constraints.maxHeight;

          // 1. CAS 2 JOUEURS (FACE À FACE IDÉAL SUR TABLE / TÉLÉPHONE)
          if (count == 2) {
            final double cardSize = min(
              maxW * 0.44,
              maxH * 0.28,
            ).clamp(90.0, 150.0);
            final double centerCardSize = min(
              maxW * 0.48,
              maxH * 0.32,
            ).clamp(100.0, 160.0);

            return Column(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                // Joueur 1 (Haut - rotation 180° pour être face à lui)
                Transform.rotate(
                  angle: pi,
                  child: _buildPlayerSlot(widget.players[0], 0, cardSize),
                ),

                // Carte centrale au milieu
                _buildCenterDeck(centerCardSize),

                // Joueur 2 (Bas)
                _buildPlayerSlot(widget.players[1], 1, cardSize),
              ],
            );
          }

          // 2. CAS 3 JOUEURS (1 EN HAUT, 2 EN BAS)
          if (count == 3) {
            final double cardSize = min(
              maxW * 0.38,
              maxH * 0.25,
            ).clamp(80.0, 125.0);
            final double centerCardSize = min(
              maxW * 0.42,
              maxH * 0.28,
            ).clamp(90.0, 140.0);

            return Column(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Transform.rotate(
                  angle: pi,
                  child: _buildPlayerSlot(widget.players[0], 0, cardSize),
                ),
                _buildCenterDeck(centerCardSize),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    _buildPlayerSlot(widget.players[1], 1, cardSize),
                    _buildPlayerSlot(widget.players[2], 2, cardSize),
                  ],
                ),
              ],
            );
          }

          // 3. CAS 4 JOUEURS (DISPOSITION EN CROIX 4 CÔTÉS)
          if (count == 4) {
            final double cardSize = min(
              maxW * 0.32,
              maxH * 0.22,
            ).clamp(75.0, 115.0);
            final double centerCardSize = min(
              maxW * 0.38,
              maxH * 0.26,
            ).clamp(85.0, 130.0);

            return Column(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Transform.rotate(
                  angle: pi,
                  child: _buildPlayerSlot(widget.players[0], 0, cardSize),
                ),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Transform.rotate(
                      angle: pi / 2,
                      child: _buildPlayerSlot(widget.players[1], 1, cardSize),
                    ),
                    _buildCenterDeck(centerCardSize),
                    Transform.rotate(
                      angle: -pi / 2,
                      child: _buildPlayerSlot(widget.players[2], 2, cardSize),
                    ),
                  ],
                ),
                _buildPlayerSlot(widget.players[3], 3, cardSize),
              ],
            );
          }

          // 4. CAS 5 À 6 JOUEURS (DISPOSITION ORBITALE CALCULÉE POUR ZÉRO COLLISION)
          final double centerSize = min(
            maxW * 0.32,
            maxH * 0.24,
          ).clamp(80.0, 120.0);
          final double cardSize = min(
            maxW * 0.26,
            maxH * 0.18,
          ).clamp(65.0, 95.0);
          final double radiusX = (maxW / 2) - (cardSize / 2) - 16;
          final double radiusY = (maxH / 2) - (cardSize / 2) - 24;

          return Stack(
            alignment: Alignment.center,
            children: [
              _buildCenterDeck(centerSize),
              ...List.generate(count, (index) {
                final double angle = (2 * pi * index / count) - (pi / 2);
                final double x = radiusX * cos(angle);
                final double y = radiusY * sin(angle);

                return Positioned(
                  left: (maxW / 2) + x - (cardSize / 2),
                  top: (maxH / 2) + y - (cardSize / 2),
                  child: _buildPlayerSlot(
                    widget.players[index],
                    index,
                    cardSize,
                  ),
                );
              }),
            ],
          );
        },
      ),
    );
  }

  // --- CENTRE DU PLATEAU (PIOCHE CENTRALE) ---
  Widget _buildCenterDeck(double size) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 3),
          margin: const EdgeInsets.only(bottom: 6),
          decoration: BoxDecoration(
            color: Colors.black.withOpacity(0.5),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: Colors.amberAccent.withOpacity(0.5)),
          ),
          child: Text(
            GameContentLocalization.format(
              context,
              AppLocalizations.of(context)!.piocheBut,
              [_deck.length + 1, _targetScore],
            ),
            style: TextStyle(
              fontSize: 10,
              fontWeight: FontWeight.w900,
              color: Colors.amberAccent,
              letterSpacing: 1,
            ),
          ),
        ),
        Draggable<List<String>>(
          data: _centerCard,
          feedback: Material(
            color: Colors.transparent,
            child: _buildDobbleCard(_centerCard, size: size, isCenter: true),
          ),
          childWhenDragging: Opacity(
            opacity: 0.3,
            child: _buildDobbleCard(_centerCard, size: size, isCenter: true),
          ),
          child: _buildDobbleCard(_centerCard, size: size, isCenter: true),
        ),
      ],
    );
  }

  // --- EMPLACEMENT & CARTE D'UN JOUEUR ---
  Widget _buildPlayerSlot(String player, int playerIndex, double cardSize) {
    final playerCard = _playerCards[player] ?? [];
    final score = _playerScores[player] ?? 0;
    final color = _playerColors[playerIndex % _playerColors.length];

    return DragTarget<List<String>>(
      onWillAccept:
          (dragged) => _findCommonSymbol(playerCard, dragged ?? []) != null,
      onAccept: (dragged) {
        final common = _findCommonSymbol(playerCard, dragged);
        if (common != null) _claimCard(player, common);
      },
      builder: (context, candidate, rejected) {
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            // Badge Nom + Score
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 3),
              margin: const EdgeInsets.only(bottom: 4),
              decoration: BoxDecoration(
                color: color.withOpacity(0.2),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: color.withOpacity(0.6)),
              ),
              child: Text(
                AppLocalizations.of(context)!.pts12(player, score),
                style: TextStyle(
                  color: color,
                  fontWeight: FontWeight.bold,
                  fontSize: 11,
                ),
              ),
            ),
            // Carte du joueur interactive
            _buildDobbleCard(
              playerCard,
              size: cardSize,
              borderColor: color,
              onSymbolTap: (symbol) => _claimCard(player, symbol),
            ),
          ],
        );
      },
    );
  }

  // --- RENDU D'UNE CARTE DOBBLE ORGANIQUE AVEC SYMBOLES ---
  Widget _buildDobbleCard(
    List<String> symbols, {
    required double size,
    Color? borderColor,
    bool isCenter = false,
    Function(String)? onSymbolTap,
  }) {
    if (symbols.isEmpty) {
      return Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          color: Colors.white10,
          shape: BoxShape.circle,
        ),
      );
    }

    final double baseSymbolSize = size * 0.22;

    // Emplacements organisés pour 6 ou 8 symboles sans débordement
    final List<Offset> slots =
        symbols.length <= 6
            ? [
              Offset(0.0, 0.0),
              Offset(0.0, -0.58),
              Offset(0.55, -0.20),
              Offset(0.35, 0.52),
              Offset(-0.35, 0.52),
              Offset(-0.55, -0.20),
            ]
            : [
              Offset(-0.20, -0.20),
              Offset(0.22, 0.20),
              Offset(0.0, -0.62),
              Offset(0.58, -0.30),
              Offset(0.58, 0.35),
              Offset(0.0, 0.62),
              Offset(-0.58, 0.35),
              Offset(-0.58, -0.30),
            ];

    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: Colors.white,
        shape: BoxShape.circle,
        border: Border.all(
          color:
              isCenter
                  ? Colors.amberAccent
                  : (borderColor ?? Color(0xFFCBD5E1)),
          width: isCenter ? 3.5 : 2.5,
        ),
        boxShadow: [
          BoxShadow(
            color: (isCenter ? Colors.amber : Colors.black).withOpacity(
              isCenter ? 0.35 : 0.4,
            ),
            blurRadius: isCenter ? 14 : 8,
            offset: Offset(0, 4),
          ),
        ],
      ),
      child: Stack(
        alignment: Alignment.center,
        children: List.generate(symbols.length, (index) {
          final symbol = symbols[index];
          final pos = slots[index % slots.length];
          final posX = pos.dx * (size / 2);
          final posY = pos.dy * (size / 2);

          return Positioned.fill(
            child: Center(
              child: Transform.translate(
                offset: Offset(posX, posY),
                child: GestureDetector(
                  onTap: onSymbolTap != null ? () => onSymbolTap(symbol) : null,
                  behavior: HitTestBehavior.opaque,
                  child: Padding(
                    padding: const EdgeInsets.all(2.0),
                    child: Text(
                      symbol,
                      style: TextStyle(
                        fontSize: baseSymbolSize,
                        shadows: [
                          Shadow(
                            color: Colors.black26,
                            blurRadius: 2,
                            offset: Offset(1, 1),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          );
        }),
      ),
    );
  }

  // ===========================================================================
  // 🏆 VICTOIRE
  // ===========================================================================
  Widget _buildGameOverUI() {
    return Center(
      child: Container(
        margin: const EdgeInsets.all(24),
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: Color(0xFF1E1B4B),
          borderRadius: BorderRadius.circular(24),
          border: Border.all(color: Colors.amberAccent, width: 2),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              Icons.emoji_events_rounded,
              size: 72,
              color: Colors.amberAccent,
            ),
            SizedBox(height: 12),
            Text(
              AppLocalizations.of(context)!.partieTerminee2,
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.w900,
                color: Colors.white,
              ),
            ),
            SizedBox(height: 8),
            Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.victoireDe,
                [_gameWinner],
              ),
              style: TextStyle(
                fontSize: 18,
                color: Colors.amberAccent,
                fontWeight: FontWeight.bold,
              ),
            ),
            SizedBox(height: 16),
            Divider(color: Colors.white24),
            ..._playerScores.entries.map((e) {
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 3.0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      e.key,
                      style: TextStyle(color: Colors.white70, fontSize: 14),
                    ),
                    Text(
                      GameContentLocalization.format(
                        context,
                        AppLocalizations.of(context)!.cartes,
                        [e.value],
                      ),
                      style: TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 14,
                      ),
                    ),
                  ],
                ),
              );
            }),
            SizedBox(height: 24),
            ElevatedButton.icon(
              icon: Icon(Icons.replay_rounded),
              label: Text(AppLocalizations.of(context)!.rejouer),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.deepPurpleAccent,
                padding: const EdgeInsets.symmetric(
                  horizontal: 24,
                  vertical: 12,
                ),
              ),
              onPressed: () => setState(() => _isConfiguring = true),
            ),
          ],
        ),
      ),
    );
  }
}

// CLASSE D'ANIMATION POUR LES SYMBOLES DOBBLE
class _DobbleSymbolButton extends StatefulWidget {
  final String symbol;
  final double size;
  final VoidCallback? onTap;

  const _DobbleSymbolButton({
    Key? key,
    required this.symbol,
    required this.size,
    this.onTap,
  }) : super(key: key);

  @override
  __DobbleSymbolButtonState createState() => __DobbleSymbolButtonState();
}

class __DobbleSymbolButtonState extends State<_DobbleSymbolButton>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 100), // Animation très rapide (pop)
    );
    // L'emoji grossit de 1.0 à 1.5 puis revient
    _scaleAnimation = Tween<double>(
      begin: 1.0,
      end: 1.5,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeInOut));
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _handleTap() {
    if (widget.onTap == null) return;

    // Jouer l'animation aller-retour
    _controller.forward().then((_) => _controller.reverse());

    // Appeler la logique du jeu
    widget.onTap!();
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: _handleTap,
      behavior: HitTestBehavior.opaque,
      child: ScaleTransition(
        scale: _scaleAnimation,
        child: Text(
          widget.symbol,
          style: TextStyle(
            fontSize: widget.size,
            shadows: [
              Shadow(
                blurRadius: 2,
                color: Colors.black26,
                offset: Offset(1, 1),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

