}

class _LudoBoardPainter extends CustomPainter {
  final List<Color> colors;

  const _LudoBoardPainter(this.colors);

  @override
  void paint(Canvas canvas, Size size) {
    final cellSize = size.width / 15;

    // 1. Fond Boisé / Feutrine Sombre
    final bgPaint =
        Paint()
          ..shader = RadialGradient(
            center: Alignment.center,
            radius: 1.0,
            colors: [Color(0xFF1E1F2C), Color(0xFF0F1018)],
          ).createShader(Rect.fromLTWH(0, 0, size.width, size.height));
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), bgPaint);

    // 2. Bordure d'ébène avec liseré doré
    canvas.drawRect(
      Rect.fromLTWH(0, 0, size.width, size.height),
      Paint()
        ..color = Color(0xFF3B2D20)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 6,
    );

    // 3. Écuries / Bases des 4 coins
    _drawHomeBase(canvas, Offset(0, 0), colors[0], cellSize, _l10n.ecurie1);
    _drawHomeBase(
      canvas,
      Offset(9 * cellSize, 0),
      colors[1],
      cellSize,
      _l10n.ecurie2,
    );
    _drawHomeBase(
      canvas,
      Offset(0, 9 * cellSize),
      colors[2],
      cellSize,
      _l10n.ecurie3,
    );
    _drawHomeBase(
      canvas,
      Offset(9 * cellSize, 9 * cellSize),
      colors[3],
      cellSize,
      _l10n.ecurie4,
    );

    // 4. Circuit de cases et escaliers
    _drawCrossPath(canvas, cellSize);
  }

  void _drawHomeBase(
    Canvas canvas,
    Offset offset,
    Color color,
    double cellSize,
    String label,
  ) {
    final baseRect = Rect.fromLTWH(
      offset.dx,
      offset.dy,
      6 * cellSize,
      6 * cellSize,
    );

    // Cadre sombre teinté
    canvas.drawRRect(
      RRect.fromRectAndRadius(baseRect.deflate(2), const Radius.circular(12)),
      Paint()..color = color.withOpacity(0.18),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(baseRect.deflate(2), const Radius.circular(12)),
      Paint()
        ..color = color.withOpacity(0.5)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.5,
    );

    // Emplacements d'écurie
    for (int i = 0; i < 2; i++) {
      for (int j = 0; j < 2; j++) {
        final slotCenter = Offset(
          offset.dx + (1.5 + i * 3.0) * cellSize,
          offset.dy + (1.5 + j * 3.0) * cellSize,
        );
        // Cercle d'accueil du pion
        canvas.drawCircle(
          slotCenter,
          cellSize * 0.7,
          Paint()..color = Color(0xFF0F1018),
        );
        canvas.drawCircle(
          slotCenter,
          cellSize * 0.7,
          Paint()
            ..color = color.withOpacity(0.4)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.2,
        );
      }
    }
  }

  void _drawCrossPath(Canvas canvas, double cellSize) {
    final strokePaint =
        Paint()
          ..color = Colors.white.withOpacity(0.12)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.0;

    void drawCell(int r, int c, {Color? fillColor, bool isStar = false}) {
      final rect = Rect.fromLTWH(
        c * cellSize,
        r * cellSize,
        cellSize,
        cellSize,
      );

      // Fond de case
      canvas.drawRRect(
        RRect.fromRectAndRadius(rect.deflate(1.2), const Radius.circular(5)),
        Paint()..color = fillColor ?? Color(0xFF161724),
      );
      // Contour
      canvas.drawRRect(
        RRect.fromRectAndRadius(rect.deflate(1.2), const Radius.circular(5)),
        strokePaint,
      );

      // Case refuge (Étoile)
      if (isStar) {
        canvas.drawCircle(
          rect.center,
          cellSize * 0.28,
          Paint()..color = Colors.amberAccent.withOpacity(0.7),
        );
      }
    }

    // Bras Gauche (Rouge)
    for (int r = 6; r <= 8; r++) {
      for (int c = 0; c <= 5; c++) {
        Color? fill;
        bool star = false;
        if (r == 7 && c > 0) fill = colors[0].withOpacity(0.4); // Escalier
        if (r == 6 && c == 1) fill = colors[0].withOpacity(0.85); // Départ
        if (r == 8 && c == 2) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Haut (Bleu)
    for (int r = 0; r <= 5; r++) {
      for (int c = 6; c <= 8; c++) {
        Color? fill;
        bool star = false;
        if (c == 7 && r > 0) fill = colors[1].withOpacity(0.4);
        if (c == 8 && r == 1) fill = colors[1].withOpacity(0.85);
        if (c == 6 && r == 2) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Droit (Jaune)
    for (int r = 6; r <= 8; r++) {
      for (int c = 9; c <= 14; c++) {
        Color? fill;
        bool star = false;
        if (r == 7 && c < 14) fill = colors[3].withOpacity(0.4);
        if (r == 8 && c == 13) fill = colors[3].withOpacity(0.85);
        if (r == 6 && c == 12) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Bas (Vert)
    for (int r = 9; r <= 14; r++) {
      for (int c = 6; c <= 8; c++) {
        Color? fill;
        bool star = false;
        if (c == 7 && r < 14) fill = colors[2].withOpacity(0.4);
        if (c == 6 && r == 13) fill = colors[2].withOpacity(0.85);
        if (c == 8 && r == 12) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Centre Triangles
    _drawCenterTriangles(canvas, cellSize);
  }

  void _drawCenterTriangles(Canvas canvas, double cellSize) {
    final center = Offset(7.5 * cellSize, 7.5 * cellSize);

    void drawTri(List<Offset> points, Color col) {
      final path = Path()..addPolygon(points, true);
      canvas.drawPath(path, Paint()..color = col.withOpacity(0.65));
      canvas.drawPath(
        path,
        Paint()
          ..color = Colors.white24
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1,
      );
    }

    drawTri([
      Offset(6 * cellSize, 6 * cellSize),
      Offset(6 * cellSize, 9 * cellSize),
      center,
    ], colors[0]);
    drawTri([
      Offset(6 * cellSize, 6 * cellSize),
      Offset(9 * cellSize, 6 * cellSize),
      center,
    ], colors[1]);
    drawTri([
      Offset(9 * cellSize, 6 * cellSize),
      Offset(9 * cellSize, 9 * cellSize),
      center,
    ], colors[3]);
    drawTri([
      Offset(6 * cellSize, 9 * cellSize),
      Offset(9 * cellSize, 9 * cellSize),
      center,
    ], colors[2]);

    // Cercle d'or au milieu
    canvas.drawCircle(
      center,
      cellSize * 0.6,
      Paint()..color = Color(0xFF0F1018),
    );
    canvas.drawCircle(
      center,
      cellSize * 0.6,
      Paint()
        ..color = Colors.amberAccent
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.5,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

// 52 cases standard
const List<List<int>> _ludoPath = [
  [1, 6], [2, 6], [3, 6], [4, 6], [5, 6], // Bras gauche haut
  [6, 5], [6, 4], [6, 3], [6, 2], [6, 1], [6, 0], // Bras haut gauche
  [7, 0], [8, 0], // Tournant haut
  [8, 1], [8, 2], [8, 3], [8, 4], [8, 5], // Bras haut droit
  [9, 6], [10, 6], [11, 6], [12, 6], [13, 6], [14, 6], // Bras droit haut
  [14, 7], [14, 8], // Tournant droit
  [13, 8], [12, 8], [11, 8], [10, 8], [9, 8], // Bras droit bas
  [8, 9], [8, 10], [8, 11], [8, 12], [8, 13], [8, 14], // Bras bas droit
  [7, 14], [6, 14], // Tournant bas
  [6, 13], [6, 12], [6, 11], [6, 10], [6, 9], // Bras bas gauche
  [5, 8], [4, 8], [3, 8], [2, 8], [1, 8], [0, 8], // Bras gauche bas
  [0, 7], [0, 6], // Tournant gauche
];

Offset _getLudoPathPosition(int pos, int playerIndex, double cellSize) {
  final startOffsets = [0, 13, 39, 26]; // 0:Rouge, 1:Bleu, 2:Vert, 3:Jaune
  final actualPos = (pos + startOffsets[playerIndex]) % 52;
  final gridPos = _ludoPath[actualPos];
  return Offset((gridPos[0] + 0.5) * cellSize, (gridPos[1] + 0.5) * cellSize);
}

Offset _getLudoHomePosition(int pos, int playerIndex, double cellSize) {
  if (pos == 5) return Offset(7.5 * cellSize, 7.5 * cellSize); // Le centre
  int col = 0, row = 0;
  switch (playerIndex) {
    case 0:
      col = 1 + pos;
      row = 7;
      break; // Rouge, Escalier Gauche
    case 1:
      col = 7;
      row = 1 + pos;
      break; // Bleu, Escalier Haut
    case 2:
      col = 7;
      row = 13 - pos;
      break; // Vert, Escalier Bas
    case 3:
      col = 13 - pos;
      row = 7;
      break; // Jaune, Escalier Droit
  }
  return Offset((col + 0.5) * cellSize, (row + 0.5) * cellSize);
}

List<Widget> _buildLudoPawns(
  double size,
  Map<String, dynamic> positions,
  List<String> playerOrder,
  List<Color> colors,
  String myId,
  bool isMyTurn,
  int dice,
  bool hasRolled,
  String gameCode,
  FirebaseService firebaseService,
  bool isTeamMode, {
  String? selectedOwnerId,
  int? selectedPawnIdx,
  void Function(String ownerId, int pawnIdx)? onPawnTap,
}) {
  final List<Widget> pawns = [];
  final cellSize = size / 15;

  final Map<int, List<Offset>> homePositions = {
    0: [Offset(1.5, 1.5), Offset(4.5, 1.5), Offset(1.5, 4.5), Offset(4.5, 4.5)],
    1: [
      Offset(10.5, 1.5),
      Offset(13.5, 1.5),
      Offset(10.5, 4.5),
      Offset(13.5, 4.5),
    ],
    2: [
      Offset(1.5, 10.5),
      Offset(4.5, 10.5),
      Offset(1.5, 13.5),
      Offset(4.5, 13.5),
    ],
    3: [
      Offset(10.5, 10.5),
      Offset(13.5, 10.5),
      Offset(10.5, 13.5),
      Offset(13.5, 13.5),
    ],
  };

  final int myPlayerIdx = playerOrder.indexOf(myId);

  for (int pIdx = 0; pIdx < playerOrder.length; pIdx++) {
    final String ownerId = playerOrder[pIdx];
    final List<int> pPos = List<int>.from(
      positions[ownerId] ?? [-1, -1, -1, -1],
    );
    final Color pColor = colors[pIdx % 4];

    final bool isMe = (ownerId == myId);
    final bool isTeammate =
        isTeamMode && !isMe && (myPlayerIdx % 2 == pIdx % 2);

    for (int pawnIdx = 0; pawnIdx < 4; pawnIdx++) {
      final int pos = pPos[pawnIdx];
      double x = 0, y = 0;

      if (pos == -1) {
        final homePos = homePositions[pIdx % 4]![pawnIdx];
        x = homePos.dx * cellSize;
        y = homePos.dy * cellSize;
      } else if (pos <= 50) {
        final pathPos = _getLudoPathPosition(pos, pIdx % 4, cellSize);
        x = pathPos.dx;
        y = pathPos.dy;
      } else {
        final homePos = _getLudoHomePosition(pos - 51, pIdx % 4, cellSize);
        x = homePos.dx;
        y = homePos.dy;
      }

      // Validité de mouvement
      bool canMove = false;
      if (isMyTurn && hasRolled && dice > 0) {
        if (isMe) {
          canMove = true;
        } else if (isTeammate) {
          if (pos == -1 && (dice == 1 || dice == 6)) canMove = true;
          if (pos > 50 && pos < 56) canMove = true;
        }
      }

      final double pawnRadius = cellSize * 0.44;
      final bool isSelected =
          (selectedOwnerId == ownerId && selectedPawnIdx == pawnIdx);

      pawns.add(
        AnimatedPositioned(
          key: ValueKey("pawn_${ownerId}_$pawnIdx"),
          duration: Duration(milliseconds: 320),
          curve: Curves.easeOutBack,
          left: x - pawnRadius,
          top: y - pawnRadius,
          child: GestureDetector(
            onTap: canMove ? () => onPawnTap?.call(ownerId, pawnIdx) : null,
            child: _Pawn3DWidget(
              color: pColor,
              canMove: canMove,
              isSelected: isSelected,
              size: pawnRadius * 2,
              pawnNumber: pawnIdx + 1,
            ),
          ),
        ),
      );
    }
  }

  return pawns;
}

// ─── Modèle d'une tuile posée ──────────────────────────────
class PlacedTile {
  final String tile;
  final int matchEnd;
  final Offset position;
  final TileOrientation orientation;
  final bool flipped;

  PlacedTile({
    required this.tile,
    required this.matchEnd,
    required this.position,
    required this.orientation,
    required this.flipped,
  });
}

enum TileOrientation { horizontal, vertical }

class LayoutResult {
  final List<PlacedTile> tiles;
  final Size boardSize;
  final int leftVal;
  final int rightVal;
  final PlacedTile? leftTile;
  final PlacedTile? rightTile;

  LayoutResult(
    this.tiles,
    this.boardSize, {
    this.leftVal = -1,
    this.rightVal = -1,
    this.leftTile,
    this.rightTile,
  });
}

// ─── Moteur de layout (Vraie logique bout à bout) ──────────
class ChainLayoutEngine {
  static const double HALF_W = 24.0; // largeur d'une demi-tuile
  static const double HALF_H = 36.0; // hauteur d'une demi-tuile

  LayoutResult computeLayout(List<Map<String, dynamic>> chain) {
    List<PlacedTile> result = [];
    if (chain.isEmpty) return LayoutResult([], Size(300, 200));

    int leftVal = -1, rightVal = -1;
    double leftX = 0.0, rightX = 0.0;

    for (int i = 0; i < chain.length; i++) {
      final entry = chain[i];
      final tileStr = entry['tile'] as String;
      final matchEnd = entry['matchEnd'] as int? ?? -1;
      final parts = tileStr.split('-');
      final a = int.parse(parts[0]);
      final b = int.parse(parts[1]);
      final isDouble = a == b;

      // Largeur physique de la tuile posée (un double se pose à la verticale)
      final double tileWidth = isDouble ? HALF_W * 2 : HALF_W * 4;

      if (i == 0) {
        // Premier domino au centre (0,0)
        leftVal = a;
        rightVal = b;
        result.add(
          PlacedTile(
            tile: tileStr,
            matchEnd: -1,
            position: Offset(0, 0),
            orientation:
                isDouble
                    ? TileOrientation.vertical
                    : TileOrientation.horizontal,
            flipped: false,
          ),
        );
        leftX = -(tileWidth / 2);
        rightX = (tileWidth / 2);
      } else {
        bool attachLeft = false;
        bool attachRight = false;

        if (matchEnd == leftVal && matchEnd == rightVal) {
          attachRight = true; // Si ambigu, on part à droite
        } else if (matchEnd == leftVal) {
          attachLeft = true;
        } else if (matchEnd == rightVal) {
          attachRight = true;
        } else {
          attachRight = true; // Fallback
        }

        bool flipped = false;

        if (attachRight) {
          if (matchEnd == b) flipped = true;
          double cx = rightX + (tileWidth / 2);
          result.add(
            PlacedTile(
              tile: tileStr,
              matchEnd: matchEnd,
              position: Offset(cx, 0),
              orientation:
                  isDouble
                      ? TileOrientation.vertical
                      : TileOrientation.horizontal,
              flipped: flipped,
            ),
          );
          rightX += tileWidth;
          rightVal = flipped ? a : b;
        } else if (attachLeft) {
          if (matchEnd == a) flipped = true;
          double cx = leftX - (tileWidth / 2);
          result.add(
            PlacedTile(
              tile: tileStr,
              matchEnd: matchEnd,
              position: Offset(cx, 0),
              orientation:
                  isDouble
                      ? TileOrientation.vertical
                      : TileOrientation.horizontal,
              flipped: flipped,
            ),
          );
          leftX -= tileWidth;
          leftVal = flipped ? b : a;
        }
      }
    }

    // Centrer le tout pour que toutes les coordonnées soient positives
    if (result.isEmpty) return LayoutResult([], Size(300, 200));

    double minX = result
        .map(
          (p) =>
              p.position.dx -
              (p.orientation == TileOrientation.vertical ? HALF_W : HALF_W * 2),
        )
        .reduce((a, b) => a < b ? a : b);
    double maxX = result
        .map(
          (p) =>
              p.position.dx +
              (p.orientation == TileOrientation.vertical ? HALF_W : HALF_W * 2),
        )
        .reduce((a, b) => a > b ? a : b);

    const double padding = 80.0;
    double totalWidth = (maxX - minX) + (padding * 2);
    double totalHeight = (HALF_H * 2) + (padding * 2);

    List<PlacedTile> shiftedResult =
        result.map((p) {
          return PlacedTile(
            tile: p.tile,
            matchEnd: p.matchEnd,
            // On recentre tout
            position: Offset(p.position.dx - minX + padding, totalHeight / 2),
            orientation: p.orientation,
            flipped: p.flipped,
          );
        }).toList();

    PlacedTile? leftTile;
    PlacedTile? rightTile;
    if (shiftedResult.isNotEmpty) {
      leftTile = shiftedResult.reduce(
        (a, b) => a.position.dx < b.position.dx ? a : b,
      );
      rightTile = shiftedResult.reduce(
        (a, b) => a.position.dx > b.position.dx ? a : b,
      );
    }
    return LayoutResult(
      shiftedResult,
      Size(totalWidth, totalHeight),
      leftVal: leftVal,
      rightVal: rightVal,
      leftTile: leftTile,
      rightTile: rightTile,
    );
  }
}

// ─── Widget du plateau de jeu ──────────────────────────────
class DominoesBoardWidget extends StatefulWidget {
  final List<Map<String, dynamic>> chain;
  final String? selectedTile;
  final ValueChanged<int>? onEndTap;

  DominoesBoardWidget({
    super.key,
    required this.chain,
    this.selectedTile,
    this.onEndTap,
  });

  @override
  State<DominoesBoardWidget> createState() => _DominoesBoardWidgetState();
}

class _DominoesBoardWidgetState extends State<DominoesBoardWidget>
    with SingleTickerProviderStateMixin {
  final TransformationController _transformationController =
      TransformationController();
  late AnimationController _glowAnimController;
  int _lastChainLength = -1;

  @override
  void initState() {
    super.initState();
    _glowAnimController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 900),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _glowAnimController.dispose();
    _transformationController.dispose();
    super.dispose();
  }

  void _autoFit(Size boardSize, BoxConstraints constraints) {
    if (constraints.maxWidth <= 0 || constraints.maxHeight <= 0) return;
    final scaleX = (constraints.maxWidth - 36) / boardSize.width;
    final scaleY = (constraints.maxHeight - 36) / boardSize.height;
    final scale = min(scaleX, scaleY).clamp(0.40, 1.20);

    final tx = (constraints.maxWidth - boardSize.width * scale) / 2;
    final ty = (constraints.maxHeight - boardSize.height * scale) / 2;

    _transformationController.value =
        Matrix4.identity()
          ..translate(tx, ty)
          ..scale(scale);
  }

  @override
  Widget build(BuildContext context) {
    final engine = ChainLayoutEngine();
    final layout = engine.computeLayout(widget.chain);

    // Parsing du domino sélectionné pour savoir quelle extrémité illuminer
    int? selA;
    int? selB;
    if (widget.selectedTile != null) {
      final parts = widget.selectedTile!.split('-');
      if (parts.length == 2) {
        selA = int.tryParse(parts[0]);
        selB = int.tryParse(parts[1]);
      }
    }

    final bool matchLeft =
        (selA != null && selB != null) &&
        (layout.leftVal == selA || layout.leftVal == selB) &&
        layout.leftTile != null;

    final bool matchRight =
        (selA != null && selB != null) &&
        (layout.rightVal == selA || layout.rightVal == selB) &&
        layout.rightTile != null;

    return LayoutBuilder(
      builder: (context, constraints) {
        if (_lastChainLength != widget.chain.length) {
          _lastChainLength = widget.chain.length;
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) _autoFit(layout.boardSize, constraints);
          });
        }

        return InteractiveViewer(
          transformationController: _transformationController,
          minScale: 0.05,
          maxScale: 3.0,
          constrained: false,
          boundaryMargin: const EdgeInsets.all(double.infinity),
          child: SizedBox(
            width: layout.boardSize.width,
            height: layout.boardSize.height,
            child: Stack(
              alignment: Alignment.center,
              children:
                  layout.tiles.map((p) {
                    final bool isLeftEnd = (p == layout.leftTile) && matchLeft;
                    final bool isRightEnd =
                        (p == layout.rightTile) && matchRight;
                    final bool isIlluminated = isLeftEnd || isRightEnd;
                    final int endValue =
                        isLeftEnd ? layout.leftVal : layout.rightVal;

                    return Positioned(
                      left:
                          p.position.dx -
                          (p.orientation == TileOrientation.vertical
                              ? ChainLayoutEngine.HALF_W
                              : ChainLayoutEngine.HALF_W * 2),
                      top:
                          p.position.dy -
                          (p.orientation == TileOrientation.vertical
                              ? ChainLayoutEngine.HALF_W * 2
                              : ChainLayoutEngine.HALF_H),
                      child: GestureDetector(
                        onTap:
                            isIlluminated && widget.onEndTap != null
                                ? () => widget.onEndTap!(endValue)
                                : null,
                        behavior: HitTestBehavior.opaque,
                        child: AnimatedBuilder(
                          animation: _glowAnimController,
                          builder: (context, child) {
                            final glow =
                                isIlluminated ? _glowAnimController.value : 0.0;
                            return Stack(
                              clipBehavior: Clip.none,
                              alignment: Alignment.center,
                              children: [
                                Container(
                                  decoration: BoxDecoration(
                                    borderRadius: BorderRadius.circular(8),
                                    boxShadow:
                                        isIlluminated
                                            ? [
                                              BoxShadow(
                                                color: Colors.amberAccent
                                                    .withValues(
                                                      alpha: 0.4 + 0.5 * glow,
                                                    ),
                                                blurRadius: 10 + 10 * glow,
                                                spreadRadius: 2 + 3 * glow,
                                              ),
                                            ]
                                            : null,
                                  ),
                                  child: _BoardTile(
                                    tile: p.tile,
                                    flipped: p.flipped,
                                    isHighlighted: isIlluminated,
                                  ),
                                ),
                                if (isIlluminated)
                                  Positioned(
                                    top: -24,
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                        horizontal: 8,
                                        vertical: 2,
                                      ),
                                      decoration: BoxDecoration(
                                        gradient: LinearGradient(
                                          colors: [
                                            Colors.amber,
                                            Colors.orangeAccent,
                                          ],
                                        ),
                                        borderRadius: BorderRadius.circular(10),
                                        boxShadow: [
                                          BoxShadow(
                                            color: Colors.black.withValues(
                                              alpha: 0.5,
                                            ),
                                            blurRadius: 4,
                                          ),
                                        ],
                                      ),
                                      child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(
                                            Icons.touch_app,
                                            size: 11,
                                            color: Colors.black,
                                          ),
                                          SizedBox(width: 3),
                                          Text(
                                            "$endValue",
                                            style: TextStyle(
                                              color: Colors.black,
                                              fontWeight: FontWeight.w900,
                                              fontSize: 11,
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                              ],
                            );
                          },
                        ),
                      ),
                    );
                  }).toList(),
            ),
          ),
        );
      },
    );
  }
}

// ─── Tuile sur le plateau ──────────────────────────────────
class _BoardTile extends StatelessWidget {
  final String tile;
  final bool flipped;
  final bool isHighlighted;

  const _BoardTile({
    required this.tile,
    required this.flipped,
    this.isHighlighted = false,
  });

  @override
  Widget build(BuildContext context) {
    final parts = tile.split('-');
    int a = int.parse(parts[0]);
    int b = int.parse(parts[1]);
    if (flipped) {
      int tmp = a;
      a = b;
      b = tmp;
    }
    final bool isDouble = a == b;

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(6),
        border: Border.all(
          color:
              isHighlighted
                  ? Colors.amberAccent
                  : (isDouble
                      ? Colors.amber.withOpacity(0.8)
                      : Colors.grey.shade400),
          width: isHighlighted ? 2.5 : 1.5,
        ),
        boxShadow: [
          BoxShadow(color: Colors.black26, blurRadius: 4, offset: Offset(2, 2)),
        ],
      ),
      child:
          isDouble
              ? Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_W * 2,
                    child: _PipGrid(value: a),
                  ),
                  Container(
                    height: 1.5,
                    width: ChainLayoutEngine.HALF_W * 2,
                    color: Colors.grey.shade400,
                  ),
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_W * 2,
                    child: _PipGrid(value: b),
                  ),
                ],
              )
              : Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_H * 2,
                    child: _PipGrid(value: a),
                  ),
                  Container(
                    width: 1.5,
                    height: ChainLayoutEngine.HALF_H * 2,
                    color: Colors.grey.shade400,
                  ),
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_H * 2,
                    child: _PipGrid(value: b),
                  ),
                ],
              ),
    );
  }
}

// ─── Tuile en main (rack) ──────────────────────────────────
class HandTileWidgetSimple extends StatefulWidget {
  final String tile;
  final bool isPlayable;
  final bool isSelected;
  final VoidCallback? onTap;

  HandTileWidgetSimple({
    super.key,
    required this.tile,
    required this.isPlayable,
    this.isSelected = false,
    this.onTap,
  });

  @override
  State<HandTileWidgetSimple> createState() => _HandTileWidgetSimpleState();
}

class _HandTileWidgetSimpleState extends State<HandTileWidgetSimple> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    final parts = widget.tile.split('-');
    final int a = int.parse(parts[0]);
    final int b = int.parse(parts[1]);
    final bool isDouble = a == b;

    final double dy =
        _pressed
            ? -2.0
            : widget.isSelected
            ? -16.0
            : widget.isPlayable
            ? -10.0
            : 0.0;

    return GestureDetector(
      onTap: widget.onTap,
      onTapDown: (_) => setState(() => _pressed = true),
      onTapUp: (_) => setState(() => _pressed = false),
      onTapCancel: () => setState(() => _pressed = false),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 12),
        child: Transform.translate(
          offset: Offset(0, dy),
          child: Container(
            decoration: BoxDecoration(
              color: Color(0xFFF5F0E8),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                color:
                    widget.isSelected
                        ? Colors.amberAccent
                        : widget.isPlayable
                        ? Color(0xFF4ade80)
                        : Colors.grey.shade400,
                width:
                    widget.isSelected
                        ? 3.0
                        : widget.isPlayable
                        ? 2.5
                        : 1.5,
              ),
              boxShadow:
                  widget.isSelected
                      ? [
                        BoxShadow(
                          color: Colors.amberAccent.withOpacity(0.8),
                          blurRadius: 12,
                          spreadRadius: 2,
                          offset: Offset(0, 4),
                        ),
                      ]
                      : widget.isPlayable
                      ? [
                        BoxShadow(
                          color: Color(0xFF4ade80).withOpacity(0.5),
                          blurRadius: 8,
                          offset: Offset(0, 4),
                        ),
                      ]
                      : [
                        BoxShadow(
                          color: Colors.black26,
                          blurRadius: 4,
                          offset: Offset(1, 2),
                        ),
                      ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox(
                  width: 40,
                  height: isDouble ? 40 : 60,
                  child: _PipGrid(value: a),
                ),
                Container(height: 1.5, width: 40, color: Colors.grey.shade400),
                SizedBox(
                  width: 40,
                  height: isDouble ? 40 : 60,
                  child: _PipGrid(value: b),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ─── Nouveau rendu des points SANS GridView (Zéro crash) ──
class _PipGrid extends StatelessWidget {
  final int value;

  const _PipGrid({required this.value});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(painter: _PipPainter(value), child: Container());
  }
}

class _PipPainter extends CustomPainter {
  final int value;
  _PipPainter(this.value);

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = Color(0xFF111111);
    final double r = size.width * 0.11; // Rayon du point
    final double padX = size.width * 0.28;
    final double padY = size.height * 0.28;
    final double cx = size.width / 2;
    final double cy = size.height / 2;

    void drawDot(double x, double y) =>
        canvas.drawCircle(Offset(x, y), r, paint);

    if (value == 1 || value == 3 || value == 5) drawDot(cx, cy); // Milieu
    if (value > 1) {
      drawDot(padX, padY); // Haut Gauche
      drawDot(size.width - padX, size.height - padY); // Bas Droite
    }
    if (value > 3) {
      drawDot(size.width - padX, padY); // Haut Droite
      drawDot(padX, size.height - padY); // Bas Gauche
    }
    if (value == 6) {
      drawDot(padX, cy); // Milieu Gauche
      drawDot(size.width - padX, cy); // Milieu Droite
    }
  }

  @override
  bool shouldRepaint(_PipPainter old) => old.value != value;
}

class FloatingChatOverlay extends StatefulWidget {
  final String gameCode;
  final String playerId;
  final String playerName;
  final Map<String, dynamic> gameData;

  const FloatingChatOverlay({
    Key? key,
    required this.gameCode,
    required this.playerId,
    required this.playerName,
    required this.gameData,
  }) : super(key: key);

  @override
  State<FloatingChatOverlay> createState() => _FloatingChatOverlayState();
}

class _FloatingChatOverlayState extends State<FloatingChatOverlay> {
  final FirebaseService _firebaseService = FirebaseService();
  final TextEditingController _textCtrl = TextEditingController();
  final ScrollController _scrollCtrl = ScrollController();

  bool _isExpanded = false; // false = 3 messages max (92px), true = 6 messages max (175px)
  bool _isSending = false;

  @override
  void initState() {
    super.initState();
    _scrollCtrl.addListener(_onScroll);
  }

  void _onScroll() {
    if (!_scrollCtrl.hasClients) return;
    final offset = _scrollCtrl.offset;

    if (offset > 12 && !_isExpanded) {
      setState(() => _isExpanded = true);
    } else if (offset <= 2 && _isExpanded) {
      setState(() => _isExpanded = false);
    }
  }

  @override
  void dispose() {
    _scrollCtrl.removeListener(_onScroll);
    _scrollCtrl.dispose();
    _textCtrl.dispose();
    super.dispose();
  }

  void _sendMessage() {
    final text = _textCtrl.text.trim();
    if (text.isEmpty || _isSending) return;

    setState(() => _isSending = true);
    final isPictionaryGuessing =
        widget.gameData['gameType'] == 'Pictionary' &&
        (widget.gameData['roundState'] == 'drawing' ||
            widget.gameData['roundState'] == 'guessing_drawing') &&
        widget.gameData['currentDrawingPlayerId'] != widget.playerId;

    if (isPictionaryGuessing) {
      _firebaseService
          .submitPictionaryGuess(
            widget.gameCode,
            widget.playerId,
            widget.playerName,
            text,
          )
          .whenComplete(() {
            if (mounted) setState(() => _isSending = false);
          });
    } else {
      _firebaseService
          .sendChatMessage(widget.gameCode, widget.playerId, text, 'global')
          .whenComplete(() {
            if (mounted) setState(() => _isSending = false);
          });
    }
    _textCtrl.clear();
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream: _firebaseService.getChatStream(widget.gameCode, 'global'),
      builder: (context, snapshot) {
        final docs = snapshot.hasData ? snapshot.data!.docs : [];
        final ps = Provider.of<PlayerState>(context, listen: false);

        // Messages du plus récent au plus ancien pour un chat dynamique
        final List<Map<String, dynamic>> allMessages = docs
            .map((doc) => doc.data() as Map<String, dynamic>)
            .where((data) {
              if (data['chatType'] != null && data['chatType'] != 'global') {
                return false;
              }
              if (ps.isUserBlocked(data['senderId'])) return false;
              return true;
            })
            .toList();

        // 3 messages max au repos, jusqu'à 6 visibles quand étendu
        final int maxItems = _isExpanded ? 6 : 3;
        final List<Map<String, dynamic>> visibleMessages =
            allMessages
                .take(
                  allMessages.length > maxItems ? maxItems : allMessages.length,
                )
                .toList();

        // Hauteur animée fluide : ~92px (3 messages) <-> ~175px (6 messages)
        final double targetHeight = _isExpanded ? 175.0 : 92.0;

        return Material(
          color: Colors.transparent,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // ── BULLES FLOTTANTES DE MESSAGES ──
              if (visibleMessages.isNotEmpty)
                GestureDetector(
                  // Détection par glissement tactile (Swipe)
                  onVerticalDragEnd: (details) {
                    final vel = details.primaryVelocity;
                    if (vel != null) {
                      if (vel < -40 && !_isExpanded) {
                        setState(() => _isExpanded = true);
                      } else if (vel > 40 && _isExpanded) {
                        setState(() {
                          _isExpanded = false;
                          if (_scrollCtrl.hasClients) {
                            _scrollCtrl.jumpTo(0);
                          }
                        });
                      }
                    }
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 260),
                    curve: Curves.easeOutCubic,
                    constraints: BoxConstraints(maxHeight: targetHeight),
                    child: ListView.builder(
                      controller: _scrollCtrl,
                      reverse: true, // Le message le plus récent est en bas
                      shrinkWrap: true,
                      padding: EdgeInsets.zero,
                      physics: const BouncingScrollPhysics(),
                      itemCount: visibleMessages.length,
                      itemBuilder: (context, index) {
                        final msg = visibleMessages[index];
                        final sender =
                            msg['senderName'] ??
                            AppLocalizations.of(context)?.joueur ??
                            "Joueur";
                        final text = msg['text'] ?? '';
                        final isMe = msg['senderId'] == widget.playerId;

                        return Align(
                          alignment: Alignment.centerLeft,
                          child: GestureDetector(
                            onTap:
                                isMe
                                    ? null
                                    : () {
                                      if (msg['senderId'] != null) {
                                        showUserProfileDialog(
                                          context,
                                          targetUid: msg['senderId'],
                                          currentUserId: widget.playerId,
                                        );
                                      }
                                    },
                            child: Container(
                              margin: const EdgeInsets.symmetric(vertical: 2),
                              padding: const EdgeInsets.symmetric(
                                horizontal: 10,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.black.withValues(alpha: 0.45),
                                borderRadius: BorderRadius.circular(10),
                                border: Border.all(
                                  color:
                                      isMe
                                          ? Colors.pinkAccent.withValues(
                                            alpha: 0.4,
                                          )
                                          : Colors.white.withValues(alpha: 0.1),
                                ),
                              ),
                              child: RichText(
                                text: TextSpan(
                                  style: const TextStyle(
                                    fontSize: 11.5,
                                    color: Colors.white,
                                  ),
                                  children: [
                                    TextSpan(
                                      text: "$sender : ",
                                      style: TextStyle(
                                        fontWeight: FontWeight.bold,
                                        fontSize: 11,
                                        color:
                                            isMe
                                                ? Colors.pinkAccent
                                                : Colors.cyanAccent,
                                      ),
                                    ),
                                    TextSpan(text: text),
                                  ],
                                ),
