  @override
  State<LoungeListScreen> createState() => _LoungeListScreenState();
}

class _LoungeListScreenState extends State<LoungeListScreen>
    with SingleTickerProviderStateMixin {
  int _selectedTabIndex = 0; // 0 = Publics, 1 = Privé avec code
  final TextEditingController _searchCtrl = TextEditingController();
  final TextEditingController _privateCodeCtrl = TextEditingController();
  bool _isJoiningPrivate = false;
  String? _joiningLoungeId;

  String _selectedTheme = _l10n.tous;
  String _sortBy = 'recent'; // 'recent', 'players', 'slots'
  bool _hideFull = false;

  final List<String> _themes = [
    _l10n.tous,
    _l10n.general,
    _l10n.fun,
    _l10n.gaming,
    _l10n.chill,
    _l10n.soiree,
    _l10n.competition,
  ];

  @override
  void dispose() {
    _searchCtrl.dispose();
    _privateCodeCtrl.dispose();
    super.dispose();
  }

  Future<void> _joinWithCode(String rawCode) async {
    final input = rawCode.trim();
    if (input.isEmpty) return;

    setState(() => _isJoiningPrivate = true);

    try {
      String? targetLoungeId;
      final querySnap =
          await FirebaseFirestore.instance
              .collection('lounges')
              .where('joinCode', isEqualTo: input)
              .limit(1)
              .get();

      if (querySnap.docs.isNotEmpty) {
        targetLoungeId = querySnap.docs.first.id;
      } else {
        final doc =
            await FirebaseFirestore.instance
                .collection('lounges')
                .doc(input)
                .get();
        if (doc.exists) {
          targetLoungeId = doc.id;
        }
      }

      if (targetLoungeId != null && mounted) {
        final ps = Provider.of<PlayerState>(context, listen: false);

        // Vérifier si l'hôte est VIP ou si le salon est gratuit
        final loungeSnap =
            querySnap.docs.isNotEmpty
                ? querySnap.docs.first
                : await FirebaseFirestore.instance
                    .collection('lounges')
                    .doc(targetLoungeId)
                    .get();
        final lData = loungeSnap.data() as Map<String, dynamic>? ?? {};
        final bool isHostVip =
            lData['isHostVip'] == true || lData['isPremiumLobby'] == true;
        final bool isAlreadyMember =
            (lData['players'] as Map?)?.containsKey(widget.playerId) == true;

        if (!ps.isPremium && !isAlreadyMember) {
          if (!isHostVip) {
            bool success = await ps.spendCoins(
              1,
            ); // 1 pièce pour rejoindre un salon
            if (!success) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(
                    AppLocalizations.of(context)!.pasAssezDePiecesPour2,
                  ),
                  backgroundColor: Colors.redAccent,
                ),
              );
              return;
            }
          } else {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  AppLocalizations.of(context)!.vousRejoignezUnePartieVip,
                ),
                backgroundColor: Colors.amber[800],
              ),
            );
          }
        }

        await FirebaseService().joinLounge(
          targetLoungeId,
          widget.playerId,
          ps.userName ?? AppLocalizations.of(context)!.joueur,
        );
        if (mounted) {
          _privateCodeCtrl.clear();
          Navigator.push(
            context,
            MaterialPageRoute(
              builder:
                  (_) => LoungeRoomScreen(
                    loungeId: targetLoungeId!,
                    playerId: widget.playerId,
                  ),
            ),
          );
        }
      } else if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              AppLocalizations.of(context)!.codeDeSalonPriveIntrouvable,
            ),
            backgroundColor: Colors.redAccent,
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              GameContentLocalization.format(
                context,
                AppLocalizations.of(context)!.erreurLorsDeLaConnexion,
                [e],
              ),
            ),
            backgroundColor: Colors.redAccent,
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _isJoiningPrivate = false);
    }
  }

