                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                const Icon(
                                  Icons.people,
                                  size: 16,
                                  color: Colors.white70,
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  "$activeCount / $maxPlayers",
                                  style: const TextStyle(
                                    color: Colors.white70,
                                    fontWeight: FontWeight.bold,
                                    fontSize: 12,
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(width: 8),
                            const Icon(
                              Icons.chevron_right_rounded,
                              color: Colors.white38,
                            ),
                          ],
                        ],
                      ),
                      onTap:
                          _joiningLoungeId != null
                              ? null
                              : () async {
                                setState(() => _joiningLoungeId = doc.id);
                                try {
                                  final ps = Provider.of<PlayerState>(
                                    context,
                                    listen: false,
                                  );
                                  await FirebaseService().joinLounge(
                                    doc.id,
                                    widget.playerId,
                                    ps.userName ??
                                        AppLocalizations.of(context)!.joueur,
                                  );
                                  if (context.mounted) {
                                    Navigator.push(
                                      context,
                                      MaterialPageRoute(
                                        builder:
                                            (_) => LoungeRoomScreen(
                                              loungeId: doc.id,
                                              playerId: widget.playerId,
                                            ),
                                      ),
                                    );
                                  }
                                } catch (e) {
                                  if (context.mounted) {
                                    ScaffoldMessenger.of(context).showSnackBar(
                                      SnackBar(
                                        content: Text(
                                          GameContentLocalization.format(
                                            context,
                                            AppLocalizations.of(
                                              context,
                                            )!.erreurLorsDeLaConnexion,
                                            [e],
                                          ),
                                        ),
                                        backgroundColor: Colors.redAccent,
                                      ),
                                    );
                                  }
                                } finally {
                                  if (mounted) {
                                    setState(() => _joiningLoungeId = null);
                                  }
                                }
                              },
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  // VUE 0 : LISTE DES SALONS PUBLICS AVEC RECHERCHE, THÈMES & FILTRES
  Widget _buildPublicLoungesView() {
    return Column(
      children: [
        // BARRE DE RECHERCHE + FILTRES RAPIDES
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          child: Row(
            children: [
              Expanded(
                child: TextField(
                  controller: _searchCtrl,
                  onChanged: (_) => setState(() {}),
                  style: TextStyle(fontSize: 13, color: Colors.white),
                  decoration: InputDecoration(
                    isDense: true,
                    contentPadding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 10,
                    ),
                    hintText: AppLocalizations.of(context)!.rechercherUnSalon,
                    hintStyle: TextStyle(color: Colors.white38, fontSize: 12),
                    prefixIcon: Icon(
                      Icons.search,
                      size: 18,
                      color: Colors.cyanAccent,
                    ),
                    suffixIcon:
                        _searchCtrl.text.isNotEmpty
                            ? IconButton(
                              icon: Icon(
                                Icons.clear,
                                size: 16,
                                color: Colors.white54,
                              ),
                              onPressed:
                                  () => setState(() => _searchCtrl.clear()),
                            )
                            : null,
                    filled: true,
                    fillColor: Colors.white.withValues(alpha: 0.05),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(14),
                      borderSide: BorderSide(color: Colors.white12),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(14),
                      borderSide: BorderSide(color: Colors.white10),
                    ),
                  ),
                ),
              ),
              SizedBox(width: 8),
              PopupMenuButton<String>(
                tooltip: AppLocalizations.of(context)!.trier,
                icon: Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.05),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: Colors.white12),
                  ),
                  child: Icon(
                    Icons.sort_rounded,
                    size: 18,
                    color: Colors.cyanAccent,
                  ),
                ),
                onSelected: (val) => setState(() => _sortBy = val),
                itemBuilder:
                    (ctx) => [
                      PopupMenuItem(
                        value: 'recent',
                        child: Row(
                          children: [
                            Icon(
                              Icons.access_time,
                              size: 16,
                              color:
                                  _sortBy == 'recent'
                                      ? Colors.amber
                                      : Colors.white70,
                            ),
                            SizedBox(width: 8),
                            Text(
                              AppLocalizations.of(context)!.plusRecents,
                              style: TextStyle(
                                color:
                                    _sortBy == 'recent'
                                        ? Colors.amber
                                        : Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                      PopupMenuItem(
                        value: 'players',
                        child: Row(
                          children: [
                            Icon(
                              Icons.people,
                              size: 16,
                              color:
                                  _sortBy == 'players'
                                      ? Colors.amber
                                      : Colors.white70,
                            ),
                            SizedBox(width: 8),
                            Text(
                              AppLocalizations.of(context)!.plusActifs,
                              style: TextStyle(
                                color:
                                    _sortBy == 'players'
                                        ? Colors.amber
                                        : Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                      PopupMenuItem(
                        value: 'slots',
                        child: Row(
                          children: [
                            Icon(
                              Icons.event_seat,
                              size: 16,
                              color:
                                  _sortBy == 'slots'
                                      ? Colors.amber
                                      : Colors.white70,
                            ),
                            SizedBox(width: 8),
                            Text(
                              AppLocalizations.of(context)!.placesDisponibles,
                              style: TextStyle(
                                color:
                                    _sortBy == 'slots'
                                        ? Colors.amber
                                        : Colors.white,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
              ),
              SizedBox(width: 4),
              IconButton(
                tooltip:
                    _hideFull
                        ? AppLocalizations.of(context)!.afficherLesSalonsPleins
                        : AppLocalizations.of(context)!.masquerLesSalonsPleins,
                icon: Icon(
                  _hideFull
                      ? Icons.filter_alt_rounded
                      : Icons.filter_alt_outlined,
                  size: 20,
                  color: _hideFull ? Colors.amberAccent : Colors.white60,
                ),
                onPressed: () => setState(() => _hideFull = !_hideFull),
              ),
            ],
          ),
        ),

        // CHIPS DES THÈMES
        SizedBox(
          height: 38,
          child: ListView.builder(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.symmetric(horizontal: 16),
            itemCount: _themes.length,
            itemBuilder: (context, idx) {
              final t = _themes[idx];
              final isSel = _selectedTheme == t;
              return Padding(
                padding: const EdgeInsets.only(right: 6.0),
                child: FilterChip(
                  label: Text(GameContentLocalization.ui(context, t)),
                  selected: isSel,
                  selectedColor: Colors.deepPurpleAccent,
                  checkmarkColor: Colors.white,
                  labelStyle: TextStyle(
                    color: isSel ? Colors.white : Colors.white70,
                    fontSize: 11,
                    fontWeight: isSel ? FontWeight.bold : FontWeight.normal,
                  ),
                  backgroundColor: Colors.white.withValues(alpha: 0.05),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 4,
                    vertical: 0,
                  ),
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  onSelected: (_) => setState(() => _selectedTheme = t),
                ),
              );
            },
          ),
        ),
        SizedBox(height: 6),

        // LISTE STREAMÉE DE TOUS LES SALONS PUBLICS SANS RISQUE DE DISPARITION
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream:
                FirebaseFirestore.instance.collection('lounges').snapshots(),
            builder: (context, snapshot) {
              if (!snapshot.hasData) {
                return Center(child: CircularProgressIndicator());
              }

              final now = DateTime.now();
              final allDocs = snapshot.data!.docs;

              // Filtrage résilient : exclure uniquement si explicitement privé
              List<DocumentSnapshot> filtered =
                  allDocs.where((doc) {
                    final d = doc.data() as Map<String, dynamic>;
                    if (d['isPrivate'] == true) return false;
                    if (d['status'] == 'closed') return false;

                    // Filtre de recherche
                    if (_searchCtrl.text.isNotEmpty) {
                      final q = _searchCtrl.text.toLowerCase();
                      final name = (d['name'] ?? '').toString().toLowerCase();
                      final theme = (d['theme'] ?? '').toString().toLowerCase();
                      final desc =
                          (d['description'] ?? '').toString().toLowerCase();
                      if (!name.contains(q) &&
                          !theme.contains(q) &&
                          !desc.contains(q)) {
                        return false;
                      }
                    }

                    // Filtre de thème
                    if (_selectedTheme != AppLocalizations.of(context)!.tous) {
                      final theme = (d['theme'] ?? '').toString().toLowerCase();
                      if (theme != _selectedTheme.toLowerCase()) {
                        return false;
                      }
                    }

                    // Filtre salons pleins
                    if (_hideFull) {
                      final players =
                          d['players'] as Map<String, dynamic>? ?? {};
                      final maxP = (d['maxPlayers'] as num?)?.toInt() ?? 10;
                      if (players.length >= maxP) return false;
                    }

                    return true;
                  }).toList();

              // Calcul de la présence active en direct pour chaque salon
              int getActiveOnlineCount(Map<String, dynamic> data) =>
                  _getActiveOnlineCount(data, now);

              // Tri intelligent
              filtered.sort((a, b) {
                final aData = a.data() as Map<String, dynamic>;
                final bData = b.data() as Map<String, dynamic>;

                final bool aIsMyHost = aData['hostId'] == widget.playerId;
                final bool bIsMyHost = bData['hostId'] == widget.playerId;
                // Mon salon toujours en tête !
                if (aIsMyHost && !bIsMyHost) return -1;
                if (!aIsMyHost && bIsMyHost) return 1;

                if (_sortBy == 'players') {
                  final aOnline = getActiveOnlineCount(aData);
                  final bOnline = getActiveOnlineCount(bData);
                  return bOnline.compareTo(aOnline);
                } else if (_sortBy == 'slots') {
                  final aMax = (aData['maxPlayers'] as num?)?.toInt() ?? 10;
                  final bMax = (bData['maxPlayers'] as num?)?.toInt() ?? 10;
                  final aAvail = (aMax - getActiveOnlineCount(aData)).clamp(
                    0,
                    99,
                  );
                  final bAvail = (bMax - getActiveOnlineCount(bData)).clamp(
                    0,
                    99,
                  );
                  return bAvail.compareTo(aAvail);
                }

                // Par défaut : plus récents
                final aTime =
                    (aData['createdAt'] as Timestamp?)?.toDate() ??
                    DateTime.now();
                final bTime =
                    (bData['createdAt'] as Timestamp?)?.toDate() ??
                    DateTime.now();
                return bTime.compareTo(aTime);
              });

              if (filtered.isEmpty) {
                return Center(
                  child: Padding(
                    padding: const EdgeInsets.all(24.0),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          Icons.search_off_rounded,
                          size: 50,
                          color: Colors.white24,
                        ),
                        SizedBox(height: 12),
                        Text(
                          _searchCtrl.text.isNotEmpty ||
                                  _selectedTheme !=
                                      AppLocalizations.of(context)!.tous
                              ? AppLocalizations.of(
                                context,
                              )!.aucunSalonNeCorrespondA
                              : AppLocalizations.of(
                                context,
                              )!.aucunSalonPublicDisponibleNcreez,
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: Colors.white54,
                            height: 1.4,
                            fontSize: 14,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }

              return ListView.builder(
                padding: const EdgeInsets.only(bottom: 80),
                itemCount: filtered.length,
                itemBuilder: (context, index) {
                  final doc = filtered[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final players =
                      data['players'] as Map<String, dynamic>? ?? {};
                  final int maxPlayers =
                      (data['maxPlayers'] as num?)?.toInt() ?? 10;
                  final int activeCount = getActiveOnlineCount(data);
                  final bool isFull = activeCount >= maxPlayers;
                  final String hostId = data['hostId'] ?? '';
                  final bool amIHost = hostId == widget.playerId;
                  final String theme =
                      data['theme'] ?? AppLocalizations.of(context)!.general;

                  return Card(
                    margin: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 6,
                    ),
                    color:
                        amIHost
                            ? Colors.deepPurple[900]?.withValues(alpha: 0.5)
                            : Color(0xFF1C1D2A),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(16),
                      side: BorderSide(
                        color:
                            amIHost
                                ? Colors.amberAccent.withValues(alpha: 0.6)
                                : Colors.white.withValues(alpha: 0.08),
                        width: amIHost ? 1.5 : 1,
                      ),
                    ),
                    child: ListTile(
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 6,
                      ),
                      leading: Container(
                        padding: const EdgeInsets.all(10),
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: (amIHost
                                  ? Colors.amberAccent
                                  : Colors.cyanAccent)
                              .withValues(alpha: 0.15),
                        ),
                        child: Icon(
                          Icons.living_rounded,
                          size: 26,
                          color:
                              amIHost ? Colors.amberAccent : Colors.cyanAccent,
                        ),
                      ),
                      title: Row(
                        children: [
                          Flexible(
                            child: Text(
                              data['name'] ??
                                  AppLocalizations.of(context)!.salon,
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                fontSize: 16,
                                color: Colors.white,
                              ),
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                          if (amIHost) ...[
                            SizedBox(width: 8),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 6,
                                vertical: 2,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.amber,
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Text(
                                AppLocalizations.of(context)!.monSalon,
                                style: TextStyle(
                                  color: Colors.black,
                                  fontSize: 9,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                      subtitle: Padding(
                        padding: const EdgeInsets.only(top: 4.0),
                        child: Row(
                          children: [
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 6,
                                vertical: 2,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.white.withValues(alpha: 0.08),
                                borderRadius: BorderRadius.circular(6),
                              ),
                              child: Text(
                                theme,
                                style: TextStyle(
                                  color: Colors.white70,
                                  fontSize: 10,
                                ),
                              ),
                            ),
                            SizedBox(width: 8),
                            // INDICATEUR EN LIGNE
                            Row(
                              children: [
                                Container(
                                  width: 7,
                                  height: 7,
                                  decoration: BoxDecoration(
                                    color:
                                        activeCount > 0
                                            ? Colors.greenAccent
                                            : Colors.white30,
                                    shape: BoxShape.circle,
                                  ),
                                ),
                                SizedBox(width: 4),
                                Text(
                                  GameContentLocalization.format(
                                    context,
                                    AppLocalizations.of(context)!.enLigne,
                                    [activeCount],
                                  ),
                                  style: TextStyle(
                                    color:
                                        activeCount > 0
                                            ? Colors.greenAccent
                                            : Colors.white38,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      trailing:
                          _joiningLoungeId == doc.id
                              ? const SizedBox(
                                width: 22,
                                height: 22,
                                child: CircularProgressIndicator(
                                  strokeWidth: 2,
                                  color: Colors.cyanAccent,
                                ),
                              )
                              : Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  Icon(
                                    Icons.people,
                                    size: 16,
                                    color:
                                        isFull
                                            ? Colors.redAccent
                                            : Colors.white70,
                                  ),
                                  SizedBox(height: 2),
                                  Text(
                                    "${activeCount} / ${maxPlayers}",
                                    style: TextStyle(
                                      color:
                                          isFull
                                              ? Colors.redAccent
                                              : Colors.white70,
                                      fontWeight: FontWeight.bold,
                                      fontSize: 12,
                                    ),
                                  ),
                                ],
                              ),
                      onTap:
                          (_joiningLoungeId != null || (isFull && !amIHost))
                              ? null
                              : () async {
                                setState(() => _joiningLoungeId = doc.id);
                                try {
                                  final ps = Provider.of<PlayerState>(
                                    context,
                                    listen: false,
                                  );
                                  final lData =
                                      doc.data() as Map<String, dynamic>? ?? {};
                                  final bool isHostVip =
                                      lData['isHostVip'] == true ||
                                      lData['isPremiumLobby'] == true;
                                  final bool isAlreadyMember =
                                      (lData['players'] as Map?)?.containsKey(
                                        widget.playerId,
                                      ) ==
                                      true;

                                  if (!amIHost &&
                                      !isAlreadyMember &&
                                      !ps.isPremium) {
                                    if (!isHostVip) {
                                      bool success = await ps.spendCoins(
                                        1,
                                      ); // 1 pièce pour rejoindre un salon
                                      if (!success) {
                                        if (context.mounted) {
                                          ScaffoldMessenger.of(
                                            context,
                                          ).showSnackBar(
                                            SnackBar(
                                              content: Text(
                                                AppLocalizations.of(
                                                  context,
                                                )!.pasAssezDePiecesPour2,
                                              ),
                                              backgroundColor: Colors.redAccent,
                                            ),
                                          );
                                        }
                                        return;
                                      }
                                    } else {
                                      if (context.mounted) {
                                        ScaffoldMessenger.of(
                                          context,
                                        ).showSnackBar(
                                          SnackBar(
                                            content: Text(
                                              AppLocalizations.of(
                                                context,
                                              )!.vousRejoignezUnePartieVip,
                                            ),
                                            backgroundColor: Colors.amber[800],
                                          ),
                                        );
                                      }
                                    }
                                  }

                                  await FirebaseService().joinLounge(
                                    doc.id,
                                    widget.playerId,
                                    ps.userName ??
                                        AppLocalizations.of(context)!.joueur,
                                  );
                                  if (context.mounted) {
                                    Navigator.push(
                                      context,
                                      MaterialPageRoute(
                                        builder:
                                            (_) => LoungeRoomScreen(
                                              loungeId: doc.id,
                                              playerId: widget.playerId,
                                            ),
                                      ),
                                    );
                                  }
                                } catch (e) {
                                  if (context.mounted) {
                                    ScaffoldMessenger.of(context).showSnackBar(
                                      SnackBar(
                                        content: Text(
                                          GameContentLocalization.format(
                                            context,
                                            AppLocalizations.of(
                                              context,
                                            )!.erreurLorsDeLaConnexion,
                                            [e],
                                          ),
                                        ),
                                        backgroundColor: Colors.redAccent,
                                      ),
                                    );
                                  }
                                } finally {
                                  if (mounted) {
                                    setState(() => _joiningLoungeId = null);
                                  }
                                }
                              },
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }
}

class CreateLoungeScreen extends StatefulWidget {
  final String playerId;
  CreateLoungeScreen({required this.playerId});
  @override
  _CreateLoungeScreenState createState() => _CreateLoungeScreenState();
}

class _CreateLoungeScreenState extends State<CreateLoungeScreen> {
  final _nameCtrl = TextEditingController();
  final _themeCtrl = TextEditingController(text: 'Général');
  final _descCtrl = TextEditingController();
  double _maxPlayers = 10;
  bool _isPrivate = false;
  bool _isLoading = false;

  final List<String> _suggestedThemes = [
    'Général',
    'Fun & Party',
    'Gaming',
    'Chill & Musique',
    'Soirée',
    'Compétition',
  ];

  @override
  void dispose() {
    _nameCtrl.dispose();
    _themeCtrl.dispose();
    _descCtrl.dispose();
    super.dispose();
  }

  void _createLounge() async {
    if (_nameCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(AppLocalizations.of(context)!.pleaseEnterLoungeName),
        ),
      );
      return;
    }

    final ps = Provider.of<PlayerState>(context, listen: false);
    if (!ps.isPremium) {
      bool success = await ps.spendCoins(
        2,
      ); // Le salon coûte 2 pièces (gratuit pour les VIP)
      if (!success) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(AppLocalizations.of(context)!.vousAvezBesoinDe5),
          ),
        );
        return;
      }
    }

    setState(() => _isLoading = true);

    final String generatedJoinCode = randomNumeric(6);

    Map<String, dynamic> loungeData = {
      'name': _nameCtrl.text.trim(),
      'theme':
          _themeCtrl.text.trim().isNotEmpty
              ? _themeCtrl.text.trim()
              : AppLocalizations.of(context)!.general,
      'description': _descCtrl.text.trim(),
      'maxPlayers': _maxPlayers.toInt(),
      'isPrivate': _isPrivate,
      'joinCode': generatedJoinCode,
      'status': 'active',
      'isPermanent': true,
      'hostId': widget.playerId,
      'isHostVip': ps.isPremium,
      'isPremiumLobby': ps.isPremium,
      'players': {
        widget.playerId: {
          'name': ps.userName ?? AppLocalizations.of(context)!.hote,
          'joinedAt': FieldValue.serverTimestamp(),
          'lastHeartbeat': FieldValue.serverTimestamp(),
          'isOnline': true,
        },
      },
    };

    String loungeId = await FirebaseService().createLounge(loungeData);

    // Débloquer le badge hôte de salon
    ps.recordBadgeEvent('social_lounge_host');

    setState(() => _isLoading = false);
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder:
            (_) => LoungeRoomScreen(
              loungeId: loungeId,
              playerId: widget.playerId,
              createdPrivateCode: _isPrivate ? generatedJoinCode : null,
            ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF13141E),
      appBar: AppBar(
        title: Text(AppLocalizations.of(context)!.creerUnSalon),
        backgroundColor: Colors.transparent,
        elevation: 0,
      ),
      body:
          _isLoading
              ? const Center(child: CircularProgressIndicator())
              : SingleChildScrollView(
                padding: const EdgeInsets.all(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    // Header visuel
                    Container(
                      padding: const EdgeInsets.all(18),
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [
                            const Color(0xFF6A11CB).withOpacity(0.35),
                            const Color(0xFF2575FC).withOpacity(0.35),
                          ],
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                        ),
                        borderRadius: BorderRadius.circular(20),
                        border: Border.all(
                          color: const Color(0xFF2575FC).withOpacity(0.4),
                        ),
                      ),
                      child: Row(
                        children: [
                          Container(
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: Colors.white.withOpacity(0.12),
                              shape: BoxShape.circle,
                            ),
                            child: const Icon(
                              Icons.meeting_room_rounded,
                              color: Colors.cyanAccent,
                              size: 32,
                            ),
                          ),
