class LoungeRoomScreen extends StatefulWidget {
  final String loungeId;
  final String playerId;
  final String? createdPrivateCode;
  LoungeRoomScreen({
    required this.loungeId,
    required this.playerId,
    this.createdPrivateCode,
  });
  @override
  _LoungeRoomScreenState createState() => _LoungeRoomScreenState();
}

class _LoungeRoomScreenState extends State<LoungeRoomScreen>
    with WidgetsBindingObserver {
  final _chatCtrl = TextEditingController();
  final FirebaseService _firebaseService = FirebaseService();
  bool _isNavigating = false;
  Timer? _heartbeatTimer;
  bool _isHost = false;
  int _sweepCounter = 0;
  DatabaseReference? _rtLoungePresenceRef;
  StreamSubscription? _rtConnectedSub;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _sendHeartbeat();
    _setupRtdbPresence();
    _heartbeatTimer = Timer.periodic(const Duration(seconds: 10), (_) {
      _sendHeartbeat();
      _sweepCounter++;
      // Balayer l'état du jeu toutes les 20 secondes pour maintenir le salon et le tchat synchronisés
      if (_sweepCounter % 2 == 0) {
        _sweepLoungeGame();
      }
    });

    if (widget.createdPrivateCode != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          _showPrivateCodeCreatedDialog(widget.createdPrivateCode!);
        }
      });
    }
  }

  void _setupRtdbPresence() {
    try {
      final safeLoungeId = widget.loungeId.replaceAll(RegExp(r'[.#$\[\]]'), '_');
      final safePlayerId = widget.playerId.replaceAll(RegExp(r'[.#$\[\]]'), '_');
      final connectedRef = FirebaseDatabase.instance.ref('.info/connected');
      _rtLoungePresenceRef = FirebaseDatabase.instance.ref(
        'lounges/$safeLoungeId/presence/$safePlayerId',
      );
      _rtConnectedSub = connectedRef.onValue.listen((event) async {
        try {
          final connected = event.snapshot.value as bool? ?? false;
          if (connected && _rtLoungePresenceRef != null) {
            _rtLoungePresenceRef!.onDisconnect().set({
              'isOnline': false,
              'lastSeen': ServerValue.timestamp,
            }).catchError((e) {
              debugPrint("RTDB lounge onDisconnect error: $e");
            });
            _rtLoungePresenceRef!.set({
              'isOnline': true,
              'lastSeen': ServerValue.timestamp,
            }).catchError((e) {
              debugPrint("RTDB lounge set presence error: $e");
            });
          }
        } catch (e) {
          debugPrint("Erreur stream RTDB lounge: $e");
        }
      }, onError: (e) {
        debugPrint("Erreur listener RTDB lounge: $e");
      });
    } catch (e) {
      debugPrint("Erreur _setupRtdbPresence lounge: $e");
    }
  }

  void _showPrivateCodeCreatedDialog(String code) {
    showDialog(
      context: context,
      builder:
          (ctx) => AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
            backgroundColor: const Color(0xFF1E1E2F),
            title: Row(
              children: [
                const Icon(Icons.vpn_key_rounded, color: Colors.amberAccent),
                const SizedBox(width: 8),
                Text(AppLocalizations.of(context)!.privateLoungeCreatedTitle),
              ],
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  AppLocalizations.of(context)!.privateLoungeCreatedSubtitle,
                  style: const TextStyle(color: Colors.white70, fontSize: 13),
                ),
                const SizedBox(height: 16),
                Container(
                  padding: const EdgeInsets.symmetric(
                    vertical: 14,
                    horizontal: 16,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.black38,
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: Colors.amberAccent.withOpacity(0.6),
                      width: 1.5,
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      SelectableText(
                        code,
                        style: const TextStyle(
                          fontSize: 32,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 4,
                          color: Colors.amberAccent,
                        ),
                      ),
                      const SizedBox(width: 12),
                      IconButton(
                        icon: const Icon(
                          Icons.copy_rounded,
                          color: Colors.amberAccent,
                        ),
                        tooltip: AppLocalizations.of(context)!.copyCodeTooltip,
                        onPressed: () {
                          Clipboard.setData(ClipboardData(text: code));
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(
                              content: Text(
                                AppLocalizations.of(
                                  context,
                                )!.accessCodeCopiedSnackbar,
                              ),
                            ),
                          );
                        },
                      ),
                    ],
                  ),
                ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(AppLocalizations.of(context)!.letsGoButton),
              ),
            ],
          ),
    );
  }

  Future<void> _sweepLoungeGame() async {
    await _firebaseService.sweepLoungeGame(widget.loungeId);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      final ps = Provider.of<PlayerState>(context, listen: false);
      _firebaseService.joinLounge(
        widget.loungeId,
        widget.playerId,
        ps.userName ?? AppLocalizations.of(context)!.joueur,
      );
      _sendHeartbeat();
      _rtLoungePresenceRef?.set({
        'isOnline': true,
        'lastSeen': ServerValue.timestamp,
      }).catchError((e) {
        debugPrint("RTDB lounge resume error: $e");
      });
      _firebaseService.setPlayerOnlineStatusInLounge(
        widget.loungeId,
        widget.playerId,
        true,
      );
    } else if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.detached) {
      _rtLoungePresenceRef?.set({
        'isOnline': false,
        'lastSeen': ServerValue.timestamp,
      }).catchError((e) {
        debugPrint("RTDB lounge pause error: $e");
      });
      _firebaseService.setPlayerOnlineStatusInLounge(
        widget.loungeId,
        widget.playerId,
        false,
      );
    }
  }

  void _sendHeartbeat() {
    _firebaseService.updateLoungeHeartbeat(widget.loungeId, widget.playerId);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _heartbeatTimer?.cancel();
    _rtConnectedSub?.cancel();
    _rtLoungePresenceRef?.set({
      'isOnline': false,
      'lastSeen': ServerValue.timestamp,
    }).catchError((e) {
      debugPrint("RTDB lounge dispose error: $e");
    });
    _firebaseService.setPlayerOnlineStatusInLounge(
      widget.loungeId,
      widget.playerId,
      false,
    );
    _chatCtrl.dispose();
    super.dispose();
  }

  void _sendMessage() {
    final ps = Provider.of<PlayerState>(context, listen: false);
    if (_chatCtrl.text.trim().isNotEmpty) {
      _firebaseService.sendLoungeMessage(
        widget.loungeId,
        widget.playerId,
        ps.userName ?? AppLocalizations.of(context)!.joueur,
        _chatCtrl.text.trim(),
      );
      _chatCtrl.clear();
    }
  }

