                              .where((g) => g['modes'].contains('multi'))
                              .toList()[index];
                      return ListTile(
                        leading: Icon(game['icon'], color: Colors.cyanAccent),
                        title: Text(game['name']),
                        onTap: () {
                          Navigator.pop(ctx);
                          final ps = Provider.of<PlayerState>(
                            context,
                            listen: false,
                          );
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder:
                                  (_) => CreateGameScreen(
                                    playerName:
                                        ps.userName ??
                                        AppLocalizations.of(context)!.hote,
                                    playerId: widget.playerId,
                                    initialGame: game['name'],
                                    loungeId: widget.loungeId,
                                    loungePlayers: currentPlayers,
                                  ),
                            ),
                          );
                        },
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
    );
  }

  Future<void> _replayGame(
    String oldGameCode,
    Map<String, dynamic> currentPlayers,
  ) async {
    final ps = Provider.of<PlayerState>(context, listen: false);
    final doc =
        await FirebaseFirestore.instance
            .collection('games')
            .doc(oldGameCode)
            .get();
    if (!doc.exists) return;

    final data = doc.data() as Map<String, dynamic>;
    String newGameCode = randomNumeric(6);

    Map<String, dynamic> hostOnly = {
      widget.playerId: {
        'name': ps.userName ?? AppLocalizations.of(context)!.hote,
        'score': 0,
      },
    };

    await _firebaseService.createGameWithAllPlayers(
      gameCode: newGameCode,
      hostId: widget.playerId,
      allPlayers: hostOnly,
      gameType: data['gameType'] ?? 'Gribouillis',
      difficulty: data['difficulty'] ?? 'N/A',
      playerCount: currentPlayers.length,
      isPremiumLobby: data['isPremiumLobby'] ?? false,
      videoEnabled: data['videoEnabled'] ?? false,
      audioEnabled: data['audioEnabled'] ?? false,
      aiWords:
          data['aiWords'] != null ? List<String>.from(data['aiWords']) : null,
      cadavreVariant: data['cadavreVariant'],
      cadavrePassingMode: data['cadavrePassingMode'],
      scope: data['scope'],
      dobbleSymbolsPerCard: data['dobbleSymbolsPerCard'] ?? false,
      isSimplifiedLiar: data['isSimplifiedLiar'] ?? false,
      liarVoteMode: data['liarVoteMode'] ?? 'simultaneous',
      petitBacCategories:
          data['petitBacCategories'] != null
              ? List<String>.from(data['petitBacCategories'])
              : null,
      petitBacTime: data['petitBacTime'],
      presidentRevolution: data['presidentRevolution'] ?? false,
      pictionaryOnly30Strokes: data['pictionaryOnly30Strokes'] ?? false,
      pictionaryUseTeams: data['pictionaryUseTeams'],
      justOneAllowInvalidClues: data['justOneAllowInvalidClues'] ?? false,
      selectedLoupGarouRoles:
          data['selectedLoupGarouRoles'] != null
              ? Map<String, int>.from(data['selectedLoupGarouRoles'])
              : null,
      unoStartingCards: data['unoStartingCards'],
      unoStackDraws: data['unoStackDraws'],
      zeroPointeTargetScore: data['zeroPointeTargetScore'],
      pokerStartChips: data['pokerStartChips'],
      pokerSmallBlind: data['pokerSmallBlind'],
      pokerBigBlind: data['pokerBigBlind'],
      hotPotatoUseGlobalTimer: data['hotPotatoUseGlobalTimer'],
      hotPotatoGlobalDuration: data['hotPotatoGlobalDuration'],
      gribouillisMode: data['gribouillisMode'],
      gribouillisAjouter1: data['gribouillisAjouter1'],
      photoRouletteRounds: data['photoRouletteRounds'],
      photoRoulettePhotosPerPlayer: data['photoRoulettePhotosPerPlayer'],
      photoRouletteMediaType: data['photoRouletteMediaType'],
      photoRouletteTime: data['photoRouletteTime'],
      undercoverRoleSettings:
          data['undercoverRoleSettings'] != null
              ? Map<String, bool>.from(data['undercoverRoleSettings'])
              : null,
      infiltreCount: data['infiltreCount'],
      mrWhiteCount: data['mrWhiteCount'],
      aiInstructions: data['aiInstructions'],
      turnTimerSeconds: data['turnTimerSeconds'],
      resultTimerSeconds: data['resultTimerSeconds'],
      petitsChevauxTeamMode: data['petitsChevauxTeamMode'] ?? false,
      timesUpTotalRounds: data['timesUpTotalRounds'],
      dominoesMode: data['dominoesMode'],
      dominoesTargetScore: data['dominoesTargetScore'],
    );

    await FirebaseFirestore.instance
        .collection('games')
        .doc(newGameCode)
        .update({'loungeId': widget.loungeId});

    await FirebaseFirestore.instance
        .collection('lounges')
        .doc(widget.loungeId)
        .update({
          'pendingGame': {
            'gameCode': newGameCode,
            'gameName': data['gameType'] ?? 'Gribouillis',
            'hostId': widget.playerId,
            'status': 'waiting',
            'joinedPlayers': [widget.playerId],
          },
        });

    await _firebaseService.sendLoungeMessage(
      widget.loungeId,
      widget.playerId,
      ps.userName ?? AppLocalizations.of(context)!.hote,
      AppLocalizations.of(
        context,
      )!.jAiLanceUnePartie1(data['gameType'] ?? 'Gribouillis'),
      type: 'game_invite',
      extraData: {
        'gameCode': newGameCode,
        'gameName': data['gameType'] ?? 'Gribouillis',
        'hostId': widget.playerId,
      },
    );
  }

  Widget _buildPlayGameButton(
    Map<String, dynamic> loungeData,
    Map<String, dynamic> players,
    bool isHost,
  ) {
    final pendingGame = loungeData['pendingGame'] as Map<String, dynamic>?;
    final String status = pendingGame?['status'] ?? '';

    if (pendingGame == null || status == 'finished' || status == 'cancelled') {
      return Padding(
        padding: const EdgeInsets.only(left: 8.0),
        child: ElevatedButton.icon(
          icon: Icon(Icons.videogame_asset, size: 18),
          label: Text(AppLocalizations.of(context)!.jouer1),
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.green,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          ),
          onPressed: () => _openGameLauncher(players),
        ),
      );
    }

    if (status == 'waiting') {
      List<dynamic> joined = pendingGame['joinedPlayers'] ?? [];
      return Padding(
        padding: const EdgeInsets.only(left: 8.0),
        child: ElevatedButton.icon(
          icon: Icon(Icons.hourglass_top, size: 18),
          label: Text(
            "${AppLocalizations.of(context)!.enAttente2} (${joined.length})",
          ),
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.deepPurple,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
          ),
          onPressed: () {
            _showPendingGameDialog(pendingGame, isHost);
          },
        ),
      );
    }

    if (status == 'started') {
      final gameName =
          pendingGame['gameName'] ?? AppLocalizations.of(context)!.jeu1;
      return Padding(
        padding: const EdgeInsets.only(left: 8.0),
        child: ElevatedButton.icon(
          icon: Icon(Icons.play_circle_fill, size: 18),
          label: Text("${AppLocalizations.of(context)!.enCours1} ($gameName)"),
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.orange[800],
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
          ),
          onPressed: () {
            Navigator.push(
              context,
              MaterialPageRoute(
                builder:
                    (_) => MultiplayerGameScreen(
                      gameCode: pendingGame['gameCode'],
                      playerId: widget.playerId,
                      loungeId: widget.loungeId,
                    ),
              ),
            );
          },
        ),
      );
    }

    return const SizedBox.shrink();
  }

  Widget _buildLoungeGameBanner(
    BuildContext context,
    Map<String, dynamic> loungeData,
    Map<String, dynamic> players,
    bool isHost,
  ) {
    final pendingGame = loungeData['pendingGame'] as Map<String, dynamic>?;
    final lastGameResult =
        loungeData['lastGameResult'] as Map<String, dynamic>?;
    final String status = pendingGame?['status'] ?? '';

    // 1. Partie en cours
    if (pendingGame != null && status == 'started') {
      final String gameCode = pendingGame['gameCode'] ?? '';
      final String gameName =
          pendingGame['gameName'] ?? AppLocalizations.of(context)!.jeu1;
      final List<dynamic> joinedPlayers = pendingGame['joinedPlayers'] ?? [];
      final bool isPlayerJoined = joinedPlayers.contains(widget.playerId);

      return Container(
        margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: Colors.green[900]?.withOpacity(0.85),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.greenAccent, width: 1.5),
        ),
        child: Row(
          children: [
            Container(
              width: 10,
              height: 10,
              decoration: BoxDecoration(
                color: Colors.greenAccent,
                shape: BoxShape.circle,
              ),
            ),
            SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.enCours,
                      [GameContentLocalization.ui(context, gameName)],
                    ),
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                      fontSize: 13,
                    ),
                  ),
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.joueurSEnJeu,
                      [joinedPlayers.length],
                    ),
                    style: TextStyle(color: Colors.white70, fontSize: 11),
                  ),
                ],
              ),
            ),
            if (isPlayerJoined)
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.green,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 6,
                  ),
                ),
                onPressed: () {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder:
                          (_) => MultiplayerGameScreen(
                            gameCode: gameCode,
                            playerId: widget.playerId,
                            loungeId: widget.loungeId,
                          ),
                    ),
                  );
                },
                child: Text(
                  AppLocalizations.of(context)!.rejoindre,
                  style: TextStyle(fontSize: 12),
                ),
              ),
            if (isHost) ...[
              SizedBox(width: 6),
              IconButton(
                icon: Icon(Icons.close, color: Colors.white70, size: 20),
                tooltip: AppLocalizations.of(context)!.cloturerLaPartie,
                onPressed: () async {
                  await FirebaseFirestore.instance
                      .collection('lounges')
                      .doc(widget.loungeId)
                      .update({'pendingGame': FieldValue.delete()});
                },
              ),
            ],
          ],
        ),
      );
    }

    // 2. Partie en attente
    if (pendingGame != null && status == 'waiting') {
      final String gameCode = pendingGame['gameCode'] ?? '';
      final String gameName =
          pendingGame['gameName'] ?? AppLocalizations.of(context)!.jeu1;
      final String hostId = pendingGame['hostId'] ?? '';
      final bool isGameHost = hostId == widget.playerId;
      final List<dynamic> joinedPlayers = pendingGame['joinedPlayers'] ?? [];
      final bool hasJoined = joinedPlayers.contains(widget.playerId);

      return Container(
        margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: Colors.deepPurple[900]?.withOpacity(0.9),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.purpleAccent, width: 1.5),
        ),
        child: Row(
          children: [
            Icon(Icons.hourglass_empty, color: Colors.amberAccent, size: 20),
            SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.partieDeEnAttente,
                      [GameContentLocalization.ui(context, gameName)],
                    ),
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                      fontSize: 13,
                    ),
                  ),
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.pretS,
                      [joinedPlayers.length],
                    ),
                    style: TextStyle(color: Colors.white70, fontSize: 11),
                  ),
                ],
              ),
            ),
            Builder(
              builder: (context) {
                final int minReq = GameData.getMinPlayers(gameName);
                final bool canStart = joinedPlayers.length >= minReq;

                return Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (!hasJoined)
                      ElevatedButton(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.blueAccent,
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                        ),
                        onPressed: () async {
                          await FirebaseFirestore.instance
                              .collection('lounges')
                              .doc(widget.loungeId)
                              .update({
                                'pendingGame.joinedPlayers':
                                    FieldValue.arrayUnion([widget.playerId]),
                              });
                          final ps = Provider.of<PlayerState>(
                            context,
                            listen: false,
                          );
                          await _firebaseService.joinGame(
                            gameCode,
                            ps.userName ?? AppLocalizations.of(context)!.joueur,
                            widget.playerId,
                          );
                        },
                        child: Text(
                          AppLocalizations.of(context)!.rejoindre,
                          style: const TextStyle(fontSize: 12),
                        ),
                      ),
                    if (hasJoined) ...[
                      ElevatedButton(
                        style: ElevatedButton.styleFrom(
                          backgroundColor:
                              canStart ? Colors.green : Colors.grey.shade700,
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                        ),
                        onPressed: () async {
                          if (!canStart) {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  AppLocalizations.of(
                                    context,
                                  )!.minPlayersToLaunchGameError(
                                    minReq,
                                    gameName,
                                    joinedPlayers.length,
                                  ),
                                ),
                                backgroundColor: Colors.orange.shade800,
                              ),
                            );
                            return;
                          }
                          await FirebaseFirestore.instance
                              .collection('lounges')
                              .doc(widget.loungeId)
                              .update({'pendingGame.status': 'started'});
                          await FirebaseFirestore.instance
                              .collection('games')
                              .doc(gameCode)
                              .update({'gameState': 'playing'});
                        },
                        child: Text(
                          canStart
                              ? AppLocalizations.of(context)!.commencer
                              : "Attente ($minReq requis)",
                          style: const TextStyle(fontSize: 12),
                        ),
                      ),
                      const SizedBox(width: 6),
                      TextButton(
                        onPressed: () async {
                          await FirebaseFirestore.instance
                              .collection('lounges')
                              .doc(widget.loungeId)
                              .update({
                                'pendingGame.joinedPlayers':
                                    FieldValue.arrayRemove([widget.playerId]),
                              });
                        },
                        child: Text(
                          AppLocalizations.of(context)!.quitter,
                          style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 11,
                          ),
                        ),
                      ),
                    ],
                    if (isGameHost || isHost) ...[
                      const SizedBox(width: 4),
                      TextButton(
                        onPressed: () async {
                          await FirebaseFirestore.instance
                              .collection('lounges')
                              .doc(widget.loungeId)
                              .update({'pendingGame': FieldValue.delete()});
                        },
                        child: Text(
                          AppLocalizations.of(context)!.annuler,
                          style: const TextStyle(
                            color: Colors.redAccent,
                            fontSize: 11,
                          ),
                        ),
                      ),
                    ],
                  ],
                );
              },
            ),
          ],
        ),
      );
    }

    // 3. Partie terminée (lastGameResult)
    if (lastGameResult != null &&
        (pendingGame == null ||
            status == 'finished' ||
            status == 'cancelled')) {
      final String gName =
          lastGameResult['gameName'] ?? AppLocalizations.of(context)!.jeu1;
      final String winner = lastGameResult['winnerName'] ?? '';
      final String reason = lastGameResult['reason'] ?? '';

      return Container(
        margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: Colors.amber[900]?.withOpacity(0.85),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: Colors.amberAccent, width: 1.5),
        ),
        child: Row(
          children: [
            Icon(Icons.emoji_events, color: Colors.amberAccent, size: 20),
            SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    AppLocalizations.of(
                      context,
                    )!.termineJeu(GameContentLocalization.ui(context, gName)),
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                      fontSize: 13,
                    ),
                  ),
                  Text(
                    winner.isNotEmpty
                        ? "${GameContentLocalization.format(context, AppLocalizations.of(context)!.vainqueur, [winner])} ${reason.isNotEmpty ? "(${GameMessageLocalization.tr(context, reason)})" : ""}"
                        : GameMessageLocalization.tr(context, reason),
                    style: TextStyle(color: Colors.white70, fontSize: 11),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ],
              ),
            ),
            IconButton(
              icon: Icon(Icons.close, color: Colors.white70, size: 18),
              onPressed: () async {
                await FirebaseFirestore.instance
                    .collection('lounges')
                    .doc(widget.loungeId)
                    .update({'lastGameResult': FieldValue.delete()});
              },
            ),
          ],
        ),
      );
    }

    return const SizedBox.shrink();
  }

  void _showPendingGameDialog(Map<String, dynamic> pendingGame, bool isHost) {
    final String gName =
        pendingGame['gameName'] ?? AppLocalizations.of(context)!.partie;
    final int minReq = GameData.getMinPlayers(gName);
    final int joinedCount =
        (pendingGame['joinedPlayers'] as List? ?? []).length;
    final bool canStart = joinedCount >= minReq;

    showDialog(
      context: context,
      builder:
          (ctx) => AlertDialog(
            title: Text(GameContentLocalization.ui(context, gName)),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  GameContentLocalization.format(
                    context,
                    AppLocalizations.of(context)!.joueurSPretS,
                    [joinedCount],
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  AppLocalizations.of(context)!.minPlayersRequiredCount(minReq),
                  style: TextStyle(
                    color: canStart ? Colors.greenAccent : Colors.orangeAccent,
                    fontSize: 13,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                if (!canStart) ...[
                  const SizedBox(height: 4),
                  Text(
                    AppLocalizations.of(context)!.waitingMorePlayersQuorum,
                    style: const TextStyle(color: Colors.white54, fontSize: 11),
                  ),
                ],
              ],
            ),
            actions: [
              if (isHost || pendingGame['hostId'] == widget.playerId)
                TextButton(
                  onPressed: () async {
                    Navigator.pop(ctx);
                    await FirebaseFirestore.instance
                        .collection('lounges')
                        .doc(widget.loungeId)
                        .update({'pendingGame': FieldValue.delete()});
                  },
                  child: Text(
                    AppLocalizations.of(context)!.annulerLaPartie,
                    style: const TextStyle(color: Colors.redAccent),
                  ),
                ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor:
                      canStart ? Colors.green : Colors.grey.shade700,
                ),
                onPressed: () async {
                  if (!canStart) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          AppLocalizations.of(
                            context,
                          )!.minPlayersToLaunchGameError(
                            minReq,
                            gName,
                            joinedCount,
                          ),
                        ),
                        backgroundColor: Colors.orange.shade800,
                      ),
                    );
                    return;
                  }
                  Navigator.pop(ctx);
                  await FirebaseFirestore.instance
                      .collection('lounges')
                      .doc(widget.loungeId)
                      .update({'pendingGame.status': 'started'});
                  await FirebaseFirestore.instance
                      .collection('games')
                      .doc(pendingGame['gameCode'])
                      .update({'gameState': 'playing'});
                },
                child: Text(
                  canStart
                      ? AppLocalizations.of(context)!.lancer
                      : AppLocalizations.of(
                        context,
                      )!.waitingQuorumProgress(joinedCount, minReq),
                ),
              ),
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: Text(AppLocalizations.of(context)!.fermer),
              ),
            ],
          ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('lounges')
              .doc(widget.loungeId)
              .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Scaffold(
            backgroundColor: Color(0xFF0F0E17),
            body: Center(
              child: CircularProgressIndicator(color: Colors.cyanAccent),
            ),
          );
        }
        if (!snapshot.hasData || !snapshot.data!.exists) {
          return Scaffold(
            backgroundColor: const Color(0xFF0F0E17),
            appBar: AppBar(
              title: Text(AppLocalizations.of(context)!.salon),
              backgroundColor: Colors.transparent,
            ),
            body: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(
                    Icons.meeting_room_outlined,
                    size: 48,
                    color: Colors.white38,
                  ),
                  const SizedBox(height: 12),
                  Text(
                    AppLocalizations.of(context)!.ceSalonAEteFerme,
                    style: const TextStyle(color: Colors.white70, fontSize: 16),
                  ),
                  const SizedBox(height: 16),
                  ElevatedButton(
                    onPressed: () => Navigator.pop(context),
                    child: Text(AppLocalizations.of(context)!.retourAuSalon),
                  ),
                ],
              ),
            ),
          );
        }
        final data = snapshot.data!.data() as Map<String, dynamic>;
        final players = data['players'] as Map<String, dynamic>? ?? {};
        final isHost = data['hostId'] == widget.playerId;
        _isHost = isHost;
        final pendingGame = data['pendingGame'];

        bool isHostOfPendingGame =
            pendingGame != null &&
            pendingGame['hostId'] == widget.playerId &&
            pendingGame['status'] == 'waiting';

        if (pendingGame != null &&
            pendingGame['status'] == 'started' &&
            !_isNavigating) {
          List<dynamic> joinedPlayers = pendingGame['joinedPlayers'] ?? [];
          if (joinedPlayers.contains(widget.playerId)) {
            _isNavigating = true;
            WidgetsBinding.instance.addPostFrameCallback((_) {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder:
                      (_) => MultiplayerGameScreen(
                        gameCode: pendingGame['gameCode'],
                        playerId: widget.playerId,
                        loungeId: widget.loungeId,
                      ),
                ),
              ).then((_) async {
                _isNavigating = false;
                // Nettoyer localement la présence dans le pendingGame à la sortie du jeu
                await FirebaseFirestore.instance
                    .collection('lounges')
                    .doc(widget.loungeId)
                    .update({
                      'pendingGame.joinedPlayers': FieldValue.arrayRemove([
                        widget.playerId,
                      ]),
                    });
              });
            });
          }
        }

        List<dynamic> streamers = data['streamers'] ?? [];

        final now = DateTime.now();
        List<String> onlineIds = [];
        players.forEach((pId, pVal) {
          if (pVal is Map) {
            final ts = pVal['lastHeartbeat'] as Timestamp?;
            final isOnline = pVal['isOnline'] != false;
            if (isOnline &&
                (ts == null || now.difference(ts.toDate()).inSeconds < 30)) {
              onlineIds.add(pId);
            }
          }
        });

        return PopScope(
          canPop: !isHostOfPendingGame,
          onPopInvokedWithResult: (didPop, result) async {
            if (didPop) {
              await _firebaseService.leaveLounge(
                widget.loungeId,
                widget.playerId,
              );
              return;
            }
            if (isHostOfPendingGame) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(
                    AppLocalizations.of(context)!.veuillezCommencerOuAnnulerLa,
                  ),
                ),
              );
            }
          },
          child: Scaffold(
            appBar: AppBar(
              title: Text(AppLocalizations.of(context)!.salon),
              actions: [
                IconButton(
                  icon: Stack(
                    clipBehavior: Clip.none,
                    children: [
                      const Icon(Icons.people_alt_rounded),
                      Positioned(
                        right: -3,
                        top: -3,
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 4,
                            vertical: 1,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.greenAccent.shade700,
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Text(
                            '${onlineIds.length}',
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 10,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                  tooltip:
                      AppLocalizations.of(context)!.viewLoungeMembersTooltip,
                  onPressed:
                      () => _showMembersModal(
                        context,
                        data,
                        players,
                        onlineIds,
                        isHost,
                      ),
                ),
                if (isHost)
                  IconButton(
                    icon: Icon(Icons.delete_forever, color: Colors.redAccent),
                    tooltip: AppLocalizations.of(context)!.fermerLeSalon,
                    onPressed: () async {
                      final confirm = await showDialog<bool>(
                        context: context,
                        builder:
                            (ctx) => AlertDialog(
                              title: Text(
                                AppLocalizations.of(context)!.fermerLeSalon1,
                              ),
                              content: Text(
                                AppLocalizations.of(
                                  context,
                                )!.leSalonSeraDefinitivementSupprime,
                              ),
                              actions: [
                                TextButton(
                                  onPressed: () => Navigator.pop(ctx, false),
                                  child: Text(
                                    AppLocalizations.of(context)!.annuler,
                                  ),
                                ),
                                ElevatedButton(
                                  style: ElevatedButton.styleFrom(
                                    backgroundColor: Colors.red,
                                  ),
                                  onPressed: () => Navigator.pop(ctx, true),
                                  child: Text(
                                    AppLocalizations.of(context)!.fermerLeSalon,
                                  ),
                                ),
                              ],
                            ),
                      );

                      if (confirm == true) {
                        await _firebaseService.deleteLounge(widget.loungeId);
                        if (mounted) Navigator.pop(context);
                      }
                    },
                  ),
              ],
            ),
            body: Column(
              children: [
                // Info du salon
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 16,
                    vertical: 12,
                  ),
                  decoration: BoxDecoration(
                    gradient: const LinearGradient(
                      colors: [Color(0xFF1E1B4B), Color(0xFF311042)],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                    border: const Border(
                      bottom: BorderSide(color: Colors.white10),
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Row(
                          children: [
                            Container(
                              padding: const EdgeInsets.all(8),
                              decoration: BoxDecoration(
                                color: Colors.deepPurpleAccent.withOpacity(0.2),
                                shape: BoxShape.circle,
                              ),
                              child: const Icon(
                                Icons.nightlife_rounded,
                                color: Colors.cyanAccent,
                                size: 20,
                              ),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    data['name'] ??
                                        AppLocalizations.of(context)!.salon,
                                    style: const TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 17,
                                      color: Colors.white,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                  Text(
                                    AppLocalizations.of(
                                      context,
                                    )!.loungeOnlineInfo(
                                      data['theme'] ??
                                          AppLocalizations.of(
                                            context,
                                          )!.themeGeneral,
                                      onlineIds.length,
                                    ),
                                    style: const TextStyle(
                                      color: Colors.white60,
                                      fontSize: 12,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                      if (data['isPrivate'] == true) ...[
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.amber.withOpacity(0.18),
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(color: Colors.amberAccent),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Icon(
                                Icons.lock_rounded,
                                size: 14,
                                color: Colors.amberAccent,
                              ),
                              const SizedBox(width: 4),
                              SelectableText(
                                "Code : ${data['joinCode'] ?? widget.loungeId.substring(0, 6)}",
                                style: const TextStyle(
                                  color: Colors.amberAccent,
                                  fontWeight: FontWeight.bold,
                                  fontSize: 13,
                                  letterSpacing: 1,
                                ),
                              ),
                              const SizedBox(width: 4),
                              InkWell(
                                onTap: () {
                                  Clipboard.setData(
                                    ClipboardData(
                                      text: data['joinCode'] ?? widget.loungeId,
                                    ),
                                  );
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    SnackBar(
                                      content: Text(
                                        AppLocalizations.of(
                                          context,
                                        )!.codeDeSalonCopie,
                                      ),
                                    ),
                                  );
                                },
                                child: const Icon(
                                  Icons.copy_rounded,
                                  size: 16,
                                  color: Colors.amberAccent,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ] else ...[
                        OutlinedButton.icon(
                          style: OutlinedButton.styleFrom(
                            side: const BorderSide(color: Colors.cyanAccent),
                            foregroundColor: Colors.cyanAccent,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 4,
                            ),
                            visualDensity: VisualDensity.compact,
                          ),
                          icon: const Icon(Icons.group_outlined, size: 16),
                          label: Text(
                            AppLocalizations.of(
                              context,
                            )!.membersCountLabel(onlineIds.length),
                          ),
                          onPressed:
                              () => _showMembersModal(
                                context,
                                data,
                                players,
                                onlineIds,
                                isHost,
                              ),
                        ),
                      ],
                    ],
                  ),
                ),
                // Présences en ligne filtrées
                StreamBuilder<QuerySnapshot>(
                  stream:
                      FirebaseFirestore.instance
                          .collection('lounges')
                          .doc(widget.loungeId)
                          .collection('presences')
                          .snapshots(),
                  builder: (context, presenceSnap) {
                    if (!presenceSnap.hasData) return SizedBox(height: 65);
                    final now = DateTime.now();
                    List<String> onlineIds = [];
                    for (var doc in presenceSnap.data!.docs) {
                      // VÉRIFICATION 1 : Le joueur doit encore être enregistré dans le salon
                      if (!players.containsKey(doc.id)) continue;

                      final pData = doc.data() as Map<String, dynamic>;
                      final ts = pData['lastHeartbeat'] as Timestamp?;
                      // VÉRIFICATION 2 : Le heartbeat doit dater de moins de 25 secondes
                      if (ts != null &&
                          now.difference(ts.toDate()).inSeconds < 25) {
                        onlineIds.add(doc.id);
                      }
                    }

                    if (onlineIds.isEmpty) return SizedBox(height: 65);

                    return Container(
                      height: 65,
                      padding: const EdgeInsets.symmetric(vertical: 8),
                      child: ListView(
                        scrollDirection: Axis.horizontal,
                        children:
                            onlineIds.map((id) {
                              String name = players[id]?['name'] ?? '';
                              if (name.isEmpty) return const SizedBox.shrink();

                              return GestureDetector(
                                onTap: () {
                                  showUserProfileDialog(
                                    context,
                                    targetUid: id,
                                    currentUserId: widget.playerId,
                                  );
                                },
                                child: Padding(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 8.0,
                                  ),
                                  child: Column(
                                    children: [
                                      Stack(
                                        children: [
                                          CircleAvatar(
                                            radius: 16,
                                            child: Text(
                                              name.isNotEmpty
                                                  ? name[0].toUpperCase()
                                                  : '?',
                                            ),
                                          ),
                                          Positioned(
                                            right: 0,
                                            bottom: 0,
                                            child: Container(
                                              width: 12,
                                              height: 12,
                                              decoration: BoxDecoration(
                                                color: Colors.green,
                                                shape: BoxShape.circle,
                                                border: Border.all(
                                                  color: Colors.black,
                                                ),
                                              ),
                                            ),
                                          ),
                                        ],
                                      ),
                                      Text(
                                        name,
                                        style: TextStyle(fontSize: 10),
                                        overflow: TextOverflow.ellipsis,
                                      ),
                                    ],
                                  ),
                                ),
                              );
                            }).toList(),
                      ),
                    );
                  },
                ),
                // Boutons d'action du salon
