                  padding: const EdgeInsets.symmetric(horizontal: 16.0),
                  child: Row(
                    children: [
                      Expanded(
                        child: ElevatedButton.icon(
                          icon: Icon(Icons.videocam),
                          label: Text(
                            streamers.isEmpty
                                ? AppLocalizations.of(context)!.lancerUnStream
                                : AppLocalizations.of(
                                  context,
                                )!.rejoindreLeStream(streamers.length),
                          ),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.blueAccent,
                          ),
                          onPressed: () {
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder:
                                    (_) => LoungeStreamingScreen(
                                      loungeId: widget.loungeId,
                                      playerId: widget.playerId,
                                    ),
                              ),
                            );
                          },
                        ),
                      ),
                      _buildPlayGameButton(data, players, isHost),
                    ],
                  ),
                ),
                Divider(),
                _buildLoungeGameBanner(context, data, players, isHost),
                // Liste de messages de chat avec logique game_invite et game_result
                Expanded(
                  child: StreamBuilder<QuerySnapshot>(
                    stream: _firebaseService.getLoungeChatStream(
                      widget.loungeId,
                    ),
                    builder: (context, chatSnap) {
                      if (!chatSnap.hasData) return SizedBox.shrink();
                      final ps = Provider.of<PlayerState>(
                        context,
                        listen: false,
                      );
                      final messages =
                          chatSnap.data!.docs.where((doc) {
                            final m = doc.data() as Map<String, dynamic>;
                            return !ps.isUserBlocked(m['senderId']);
                          }).toList();
                      return ListView.builder(
                        reverse: true,
                        itemCount: messages.length,
                        itemBuilder: (context, index) {
                          var msg =
                              messages[index].data() as Map<String, dynamic>;

                          if (msg['type'] == 'game_invite' ||
                              (msg['text'] != null &&
                                  msg['text'].toString().contains(
                                    AppLocalizations.of(
                                      context,
                                    )!.jAiLanceUnePartie2,
                                  ))) {
                            String gameCode =
                                msg['extraData']?['gameCode'] ??
                                (pendingGame != null
                                    ? pendingGame['gameCode'] ?? ''
                                    : '');
                            String gameName =
                                msg['extraData']?['gameName'] ??
                                (pendingGame != null
                                    ? pendingGame['gameName'] ?? ''
                                    : '');
                            String hostId =
                                msg['extraData']?['hostId'] ??
                                (pendingGame != null
                                    ? pendingGame['hostId'] ?? ''
                                    : '');

                            bool isGameFinished =
                                (pendingGame == null ||
                                    pendingGame['gameCode'] != gameCode);
                            bool isGameHost = hostId == widget.playerId;
                            List<dynamic> joinedPlayers =
                                pendingGame != null
                                    ? (pendingGame['joinedPlayers'] ?? [])
                                    : [];
                            bool hasJoined = joinedPlayers.contains(
                              widget.playerId,
                            );
                            bool isStarted =
                                pendingGame != null &&
                                pendingGame['status'] == 'started';

                            return Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 8,
                                horizontal: 16,
                              ),
                              padding: EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: Colors.deepPurple[800],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                children: [
                                  Text(
                                    GameContentLocalization.format(
                                      context,
                                      AppLocalizations.of(
                                        context,
                                      )!.aCreeUnePartieDe,
                                      [msg['senderName'], gameName],
                                    ),
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 16,
                                    ),
                                  ),
                                  SizedBox(height: 10),
                                  Text(
                                    GameContentLocalization.format(
                                      context,
                                      AppLocalizations.of(
                                        context,
                                      )!.joueurSPrets,
                                      [joinedPlayers.length],
                                    ),
                                  ),
                                  SizedBox(height: 10),
                                  if (isGameFinished)
                                    Padding(
                                      padding: const EdgeInsets.only(top: 8.0),
                                      child: Text(
                                        AppLocalizations.of(
                                          context,
                                        )!.cettePartieEstTermineeOu,
                                        style: TextStyle(
                                          fontStyle: FontStyle.italic,
                                          color: Colors.grey,
                                        ),
                                      ),
                                    ),
                                  if (!isGameFinished && isStarted)
                                    Padding(
                                      padding: const EdgeInsets.only(top: 8.0),
                                      child: Container(
                                        padding: EdgeInsets.symmetric(
                                          horizontal: 16,
                                          vertical: 8,
                                        ),
                                        decoration: BoxDecoration(
                                          color: Colors.green,
                                          borderRadius: BorderRadius.circular(
                                            20,
                                          ),
                                        ),
                                        child: Text(
                                          AppLocalizations.of(
                                            context,
                                          )!.enPartie,
                                          style: TextStyle(
                                            color: Colors.white,
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                      ),
                                    ),
                                  if (!isGameFinished && !isStarted)
                                    Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.spaceEvenly,
                                      children: [
                                        if (isGameHost || isHost)
                                          ElevatedButton(
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor: Colors.red,
                                            ),
                                            onPressed: () async {
                                              await FirebaseFirestore.instance
                                                  .collection('games')
                                                  .doc(gameCode)
                                                  .delete();
                                              await FirebaseFirestore.instance
                                                  .collection('lounges')
                                                  .doc(widget.loungeId)
                                                  .update({
                                                    'pendingGame':
                                                        FieldValue.delete(),
                                                  });
                                            },
                                            child: Text(
                                              AppLocalizations.of(
                                                context,
                                              )!.annuler,
                                            ),
                                          ),
                                        if (!hasJoined)
                                          ElevatedButton(
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor:
                                                  Colors.blueAccent,
                                            ),
                                            onPressed: () async {
                                              final ps =
                                                  Provider.of<PlayerState>(
                                                    context,
                                                    listen: false,
                                                  );
                                              await FirebaseFirestore.instance
                                                  .collection('lounges')
                                                  .doc(widget.loungeId)
                                                  .update({
                                                    'pendingGame.joinedPlayers':
                                                        FieldValue.arrayUnion([
                                                          widget.playerId,
                                                        ]),
                                                  });
                                              await _firebaseService.joinGame(
                                                gameCode,
                                                ps.userName ??
                                                    AppLocalizations.of(
                                                      context,
                                                    )!.joueur,
                                                widget.playerId,
                                              );
                                            },
                                            child: Text(
                                              AppLocalizations.of(
                                                context,
                                              )!.rejoindre,
                                            ),
                                          ),
                                        Builder(
                                          builder: (context) {
                                            final int minReq =
                                                GameData.getMinPlayers(
                                                  gameName,
                                                );
                                            final bool canStart =
                                                joinedPlayers.length >= minReq;

                                            return ElevatedButton(
                                              style: ElevatedButton.styleFrom(
                                                backgroundColor:
                                                    canStart
                                                        ? Colors.green
                                                        : Colors.grey.shade700,
                                              ),
                                              onPressed: () async {
                                                if (!canStart) {
                                                  ScaffoldMessenger.of(
                                                    context,
                                                  ).showSnackBar(
                                                    SnackBar(
                                                      content: Text(
                                                        AppLocalizations.of(
                                                          context,
                                                        )!.minPlayersToLaunchGameError(
                                                          minReq,
                                                          gameName,
                                                          joinedPlayers.length,
                                                        ),
                                                      ),
                                                      backgroundColor:
                                                          Colors
                                                              .orange
                                                              .shade800,
                                                    ),
                                                  );
                                                  return;
                                                }
                                                await _firebaseService
                                                    .startGame(gameCode);
                                                await FirebaseFirestore.instance
                                                    .collection('lounges')
                                                    .doc(widget.loungeId)
                                                    .update({
                                                      'pendingGame.status':
                                                          'started',
                                                    });
                                              },
                                              child: Text(
                                                canStart
                                                    ? AppLocalizations.of(
                                                      context,
                                                    )!.commencer
                                                    : "Attente ($minReq)",
                                              ),
                                            );
                                          },
                                        ),
                                      ],
                                    ),
                                ],
                              ),
                            );
                          } else if (msg['type'] == 'game_result') {
                            return Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 8,
                                horizontal: 16,
                              ),
                              padding: EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: Colors.amber[900],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                children: [
                                  Text(
                                    GameContentLocalization.format(
                                      context,
                                      AppLocalizations.of(
                                        context,
                                      )!.partieDeTerminee,
                                      [msg['extraData']['gameName']],
                                    ),
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 16,
                                    ),
                                  ),
                                  SizedBox(height: 8),
                                  Row(
                                    mainAxisAlignment: MainAxisAlignment.center,
                                    children: [
                                      ElevatedButton(
                                        onPressed: () {
                                          showDialog(
                                            context: context,
                                            builder:
                                                (_) => AlertDialog(
                                                  title: Text(
                                                    GameContentLocalization.format(
                                                      context,
                                                      AppLocalizations.of(
                                                        context,
                                                      )!.statistiques,
                                                      [
                                                        msg['extraData']['gameName'],
                                                      ],
                                                    ),
                                                  ),
                                                  content: Text(
                                                    GameContentLocalization.format(
                                                      context,
                                                      AppLocalizations.of(
                                                        context,
                                                      )!.vainqueur1,
                                                      [
                                                        msg['extraData']['winnerName'] ??
                                                            AppLocalizations.of(
                                                              context,
                                                            )!.inconnu,
                                                        msg['extraData']['reason'] ??
                                                            '',
                                                      ],
                                                    ),
                                                  ),
                                                  actions: [
                                                    TextButton(
                                                      onPressed:
                                                          () => Navigator.pop(
                                                            context,
                                                          ),
                                                      child: Text(
                                                        AppLocalizations.of(
                                                          context,
                                                        )!.fermer,
                                                      ),
                                                    ),
                                                  ],
                                                ),
                                          );
                                        },
                                        child: Text(
                                          AppLocalizations.of(
                                            context,
                                          )!.voirLesStats,
                                        ),
                                      ),
                                      if (isHost &&
                                          msg['extraData']['oldGameCode'] !=
                                              null) ...[
                                        SizedBox(width: 10),
                                        ElevatedButton.icon(
                                          icon: Icon(Icons.refresh),
                                          label: Text(
                                            AppLocalizations.of(
                                              context,
                                            )!.relancer,
                                          ),
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor: Colors.green,
                                          ),
                                          onPressed: () {
                                            _replayGame(
                                              msg['extraData']['oldGameCode'],
                                              players,
                                            );
                                          },
                                        ),
                                      ],
                                    ],
                                  ),
                                ],
                              ),
                            );
                          }

                          bool isMe = msg['senderId'] == widget.playerId;
                          return Align(
                            alignment:
                                isMe
                                    ? Alignment.centerRight
                                    : Alignment.centerLeft,
                            child: Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 4,
                                horizontal: 8,
                              ),
                              padding: EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color:
                                    isMe
                                        ? Colors.blueAccent[700]
                                        : Colors.grey[800],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                crossAxisAlignment:
                                    isMe
                                        ? CrossAxisAlignment.end
                                        : CrossAxisAlignment.start,
                                children: [
                                  GestureDetector(
                                    onTap: () {
                                      if (msg['senderId'] != null) {
                                        showUserProfileDialog(
                                          context,
                                          targetUid: msg['senderId'],
                                          currentUserId: widget.playerId,
                                        );
                                      }
                                    },
                                    child: Text(
                                      isMe
                                          ? AppLocalizations.of(context)!.moi
                                          : (msg['senderName'] ??
                                              AppLocalizations.of(
                                                context,
                                              )!.joueur),
                                      style: TextStyle(
                                        fontSize: 10,
                                        color: Colors.white70,
                                        decoration: TextDecoration.underline,
                                      ),
                                    ),
                                  ),
                                  Text(
                                    msg['text'],
                                    style: TextStyle(fontSize: 16),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      );
                    },
                  ),
                ),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 8, vertical: 8),
                  color: Colors.black26,
                  child: Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: _chatCtrl,
                          decoration: InputDecoration(
                            hintText: AppLocalizations.of(context)!.message,
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(20),
                            ),
                            contentPadding: EdgeInsets.symmetric(
                              horizontal: 16,
                            ),
                          ),
                          onSubmitted: (_) => _sendMessage(),
                        ),
                      ),
                      IconButton(
                        icon: Icon(Icons.send, color: Colors.deepPurpleAccent),
                        onPressed: _sendMessage,
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class LoungeStreamingScreen extends StatefulWidget {
  final String loungeId;
  final String playerId;
  LoungeStreamingScreen({required this.loungeId, required this.playerId});

  @override
  _LoungeStreamingScreenState createState() => _LoungeStreamingScreenState();
}

class _LoungeStreamingScreenState extends State<LoungeStreamingScreen> {
  late LivekitService _livekitService;
  bool _joined = false;
  final PageController _pageController = PageController();

  @override
  void initState() {
    super.initState();
    _livekitService = Provider.of<LivekitService>(context, listen: false);
    _initStream();
  }

  Future<void> _initStream() async {
    await _livekitService.initialize();
    await _livekitService.joinChannel(
      widget.loungeId,
      identity: widget.playerId,
      videoEnabled: true, // Force l'activation de la vidéo pour le stream
      audioEnabled: true, // Force l'activation de l'audio pour le stream
    );
    await FirebaseService().joinLoungeStream(widget.loungeId, widget.playerId);
    if (mounted) {
      setState(() => _joined = true);
      Provider.of<PlayerState>(
        context,
        listen: false,
      ).recordBadgeEvent('social_stream_join');
    }
  }

  @override
  void dispose() {
    _pageController.dispose();
    _livekitService.leaveChannel();
    FirebaseService().leaveLoungeStream(widget.loungeId, widget.playerId);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: SafeArea(
        child: Stack(
          children: [
            if (_joined)
              Consumer<LivekitService>(
                builder: (context, livekit, _) {
                  List<String> participants = [livekit.localIdentity];
                  participants.addAll(livekit.remoteUsers.keys);

                  int itemsPerPage = 8;
                  int pages = (participants.length / itemsPerPage).ceil();
                  if (pages == 0) pages = 1;

                  return Stack(
                    children: [
                      PageView.builder(
                        controller: _pageController,
                        itemCount: pages,
                        itemBuilder: (ctx, pageIndex) {
                          var pageParticipants =
                              participants
                                  .skip(pageIndex * itemsPerPage)
                                  .take(itemsPerPage)
                                  .toList();
                          return GridView.builder(
                            physics: NeverScrollableScrollPhysics(),
                            gridDelegate:
                                SliverGridDelegateWithFixedCrossAxisCount(
                                  crossAxisCount:
                                      pageParticipants.length <= 2 ? 1 : 2,
                                  childAspectRatio:
                                      pageParticipants.length <= 2 ? 1.5 : 1.0,
                                ),
                            itemCount: pageParticipants.length,
                            itemBuilder: (ctx, idx) {
                              String identity = pageParticipants[idx];
                              bool isLocal = identity == livekit.localIdentity;

                              VideoTrack? videoTrack = livekit.getVideoTrack(
                                identity,
                              );

                              return Container(
                                margin: EdgeInsets.all(4),
                                decoration: BoxDecoration(
                                  color: Colors.grey[900],
                                  borderRadius: BorderRadius.circular(12),
                                ),
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(12),
                                  child:
                                      videoTrack != null
                                          ? VideoTrackRenderer(videoTrack)
                                          : Center(
                                            child: Icon(
                                              Icons.person,
                                              color: Colors.white54,
                                              size: 50,
                                            ),
                                          ),
                                ),
                              );
                            },
                          );
                        },
                      ),
                      if (pages > 1) ...[
                        Positioned(
                          left: 5,
                          top: 0,
                          bottom: 0,
                          child: Center(
                            child: IconButton(
                              icon: Icon(
                                Icons.arrow_back_ios,
                                color: Colors.white54,
                                size: 30,
                              ),
                              onPressed:
                                  () => _pageController.previousPage(
                                    duration: Duration(milliseconds: 300),
                                    curve: Curves.easeInOut,
                                  ),
                            ),
                          ),
                        ),
                        Positioned(
                          right: 5,
                          top: 0,
                          bottom: 0,
                          child: Center(
                            child: IconButton(
                              icon: Icon(
                                Icons.arrow_forward_ios,
                                color: Colors.white54,
                                size: 30,
                              ),
                              onPressed:
                                  () => _pageController.nextPage(
                                    duration: Duration(milliseconds: 300),
                                    curve: Curves.easeInOut,
                                  ),
                            ),
                          ),
                        ),
                      ],
                    ],
                  );
                },
              ),
            Positioned(
              top: 10,
              right: 10,
              child: IconButton(
                icon: Icon(Icons.close, color: Colors.white, size: 30),
                onPressed: () => Navigator.pop(context),
              ),
            ),
            Positioned(
              bottom: 80,
              right: 10,
              width: 220,
              height: 250,
              child: IgnorePointer(
                child: LoungeFloatingChatOverlay(loungeId: widget.loungeId),
              ),
            ),
            Positioned(
              bottom: 20,
              left: 0,
              right: 0,
              child: Consumer<LivekitService>(
                builder: (context, livekit, _) {
                  return Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      FloatingActionButton(
                        heroTag: "mic_stream",
                        backgroundColor:
                            livekit.isLocalMuted
                                ? Colors.red
                                : Colors.grey[800],
                        child: Icon(
                          livekit.isLocalMuted ? Icons.mic_off : Icons.mic,
                          color: Colors.white,
                        ),
                        onPressed: () => livekit.toggleLocalAudio(),
                      ),
                      SizedBox(width: 20),
                      FloatingActionButton(
                        heroTag: "cam_stream",
                        backgroundColor:
                            livekit.isLocalVideoOff
                                ? Colors.red
                                : Colors.grey[800],
                        child: Icon(
                          livekit.isLocalVideoOff
                              ? Icons.videocam_off
                              : Icons.videocam,
                          color: Colors.white,
                        ),
                        onPressed: () => livekit.toggleLocalVideo(),
                      ),
                    ],
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class LoungeFloatingChatOverlay extends StatelessWidget {
  final String loungeId;
  LoungeFloatingChatOverlay({Key? key, required this.loungeId})
    : super(key: key);

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('lounges')
              .doc(loungeId)
              .collection('chat')
              .orderBy('timestamp', descending: true)
              .limit(6)
              .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) return SizedBox.shrink();
        final messages = snapshot.data!.docs;

        return ListView.builder(
          reverse: true,
          itemCount: messages.length,
          itemBuilder: (context, index) {
            final data = messages[index].data() as Map<String, dynamic>;
            if (data['type'] != null && data['type'] != 'text')
              return SizedBox.shrink();

            return Padding(
              padding: const EdgeInsets.symmetric(vertical: 4.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text(
                    data['senderName'],
                    style: TextStyle(
                      color: Colors.amber,
                      fontWeight: FontWeight.bold,
                      fontSize: 13,
                      shadows: [Shadow(color: Colors.black, blurRadius: 4)],
                    ),
                  ),
                  Text(
                    data['text'] ?? '',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      shadows: [Shadow(color: Colors.black, blurRadius: 4)],
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

// =============================================================================
// 🎴 WIDGET DE CARTE ZÉRO POINTÉ / SKYJO (CODE COULEUR OFFICIEL)
// =============================================================================
class _ZeroPointeCardWidget extends StatelessWidget {
  final int value;
  final bool isRevealed;
  final bool isSelected;
  final double scale;

  const _ZeroPointeCardWidget({
    Key? key,
    required this.value,
    required this.isRevealed,
    this.isSelected = false,
    this.scale = 1.0,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    // DOS DE CARTE (FACE CACHÉE)
    if (!isRevealed) {
      return AnimatedContainer(
        duration: Duration(milliseconds: 200),
        decoration: BoxDecoration(
          gradient: LinearGradient(
            colors: [Color(0xFF2E1065), Color(0xFF1E1B4B), Color(0xFF0F172A)],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
          borderRadius: BorderRadius.circular(10 * scale),
          border: Border.all(
            color: isSelected ? Colors.amberAccent : Colors.white24,
            width: isSelected ? 2.5 : 1.2,
          ),
          boxShadow: [
            BoxShadow(
              color:
                  isSelected
                      ? Colors.amberAccent.withOpacity(0.4)
                      : Colors.black45,
              blurRadius: isSelected ? 8 : 4,
              offset: Offset(1, 2),
            ),
          ],
        ),
        child: Center(
          child: Container(
            width: 32 * scale,
            height: 32 * scale,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              border: Border.all(
                color: Colors.white.withOpacity(0.3),
                width: 1.5,
              ),
            ),
            child: Center(
              child: Text(
                "0",
                style: TextStyle(
                  fontSize: 16 * scale,
                  fontWeight: FontWeight.w900,
                  color: Colors.white.withOpacity(0.5),
                ),
              ),
            ),
          ),
        ),
      );
    }

    // FACE VISIBLE : COULEURS PAR TRANCHE SKYJO
    final _SkyjoCardTheme theme = _getSkyjoCardTheme(value);

    return AnimatedContainer(
      duration: Duration(milliseconds: 200),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: theme.gradient,
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(10 * scale),
        border: Border.all(
          color: isSelected ? Colors.white : theme.borderColor,
          width: isSelected ? 2.5 : 1.5,
        ),
        boxShadow: [
          BoxShadow(
            color:
                isSelected ? Colors.white.withOpacity(0.5) : theme.shadowColor,
            blurRadius: isSelected ? 10 : 4,
            offset: Offset(1, 2),
          ),
        ],
      ),
      child: Stack(
        children: [
          // Valeur centrale imposante
          Center(
            child: Text(
              "$value",
              style: TextStyle(
                fontSize: 28 * scale,
                fontWeight: FontWeight.w900,
                color: theme.textColor,
                shadows: [
                  Shadow(
                    color: Colors.black.withOpacity(0.3),
                    blurRadius: 3,
                    offset: Offset(1, 1),
                  ),
                ],
              ),
            ),
          ),

          // Mini-chiffre en haut à gauche
          Positioned(
            top: 4 * scale,
            left: 5 * scale,
            child: Text(
              "$value",
              style: TextStyle(
                fontSize: 11 * scale,
                fontWeight: FontWeight.w900,
                color: theme.textColor.withOpacity(0.85),
              ),
            ),
          ),

          // Mini-chiffre inversé en bas à droite
          Positioned(
            bottom: 4 * scale,
            right: 5 * scale,
            child: Transform.rotate(
              angle: pi,
              child: Text(
                "$value",
                style: TextStyle(
                  fontSize: 11 * scale,
                  fontWeight: FontWeight.w900,
                  color: theme.textColor.withOpacity(0.85),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // Code couleur officiel par tranche de points
  _SkyjoCardTheme _getSkyjoCardTheme(int val) {
    if (val < 0) {
      // -2 et -1 : Bleu nuit / Violet (très avantageux)
      return _SkyjoCardTheme(
        gradient: [Color(0xFF6B21A8), Color(0xFF4C1D95), Color(0xFF2E1065)],
        borderColor: Color(0xFFA855F7),
        textColor: Colors.white,
        shadowColor: Color(0xFF6B21A8).withOpacity(0.4),
      );
    } else if (val == 0) {
      // 0 : Cyan / Turquoise
      return _SkyjoCardTheme(
        gradient: [Color(0xFF06B6D4), Color(0xFF0891B2), Color(0xFF0E7490)],
        borderColor: Color(0xFF67E8F9),
        textColor: Colors.white,
        shadowColor: Color(0xFF06B6D4).withOpacity(0.4),
      );
    } else if (val >= 1 && val <= 4) {
      // 1 à 4 : Vert franc
      return _SkyjoCardTheme(
        gradient: [Color(0xFF10B981), Color(0xFF059669), Color(0xFF047857)],
        borderColor: Color(0xFF6EE7B7),
        textColor: Colors.white,
        shadowColor: Color(0xFF10B981).withOpacity(0.4),
      );
    } else if (val >= 5 && val <= 8) {
      // 5 à 8 : Jaune / Orange chaud
      return _SkyjoCardTheme(
        gradient: [Color(0xFFF59E0B), Color(0xFFD97706), Color(0xFFB45309)],
        borderColor: Color(0xFFFCD34D),
        textColor: Colors.white,
        shadowColor: Color(0xFFF59E0B).withOpacity(0.4),
      );
    } else {
      // 9 à 12 : Rouge vif (danger)
      return _SkyjoCardTheme(
        gradient: [Color(0xFFEF4444), Color(0xFFDC2626), Color(0xFF991B1B)],
        borderColor: Color(0xFFFCA5A5),
        textColor: Colors.white,
        shadowColor: Color(0xFFEF4444).withOpacity(0.4),
      );
    }
  }
}

class _SkyjoCardTheme {
  final List<Color> gradient;
  final Color borderColor;
  final Color textColor;
  final Color shadowColor;

  const _SkyjoCardTheme({
    required this.gradient,
    required this.borderColor,
    required this.textColor,
    required this.shadowColor,
  });
}

