  Widget _buildPhaseContent(
    BuildContext context, {
    required String phase,
    required bool isCurrentPlayer,
    required String currentPlayerName,
    required String? challengeType,
    required String? currentChallenge,
    required String? challengeAuthor,
    required String? authorName,
    required bool isAuthor,
    required Map<String, dynamic> votes,
    required int votersCount,
    required bool hasVoted,
    required List<String> playerOrder,
    required Map<String, dynamic> players,
  }) {
    final playerNames =
        playerOrder
            .map(
              (id) =>
                  (players[id]?['name'] ?? AppLocalizations.of(context)!.joueur)
                      .toString(),
            )
            .toList();

    switch (phase) {
      case 'waiting_spin':
        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              AppLocalizations.of(context)!.quiVaReleverLeDefi,
              style: TextStyle(
                color: Colors.white,
                fontSize: 22,
                fontWeight: FontWeight.bold,
              ),
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 6),
            Text(
              AppLocalizations.of(context)!.faitesTournerLaRoulettePour,
              style: TextStyle(color: Colors.white70, fontSize: 13),
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 24),
            _buildRouletteWidget(playerNames),
            SizedBox(height: 32),
            ElevatedButton.icon(
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.transparent,
                elevation: 0,
                padding: const EdgeInsets.symmetric(
                  horizontal: 32,
                  vertical: 16,
                ),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(30),
                ),
              ),
              onPressed: _isSubmitting ? null : _handleSpinWheel,
              icon: Icon(Icons.refresh, color: Colors.white, size: 24),
              label: Ink(
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [Color(0xFFFF007A), Color(0xFF7928CA)],
                  ),
                  borderRadius: BorderRadius.circular(30),
                ),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 14,
                  ),
                  child: Text(
                    AppLocalizations.of(context)!.tournerLaRoulette,
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 1.1,
                    ),
                  ),
                ),
              ),
            ),
          ],
        );

      case 'spin_result':
        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            _buildRouletteWidget(playerNames),
            SizedBox(height: 24),
            Container(
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [
                    Colors.deepPurple.shade900.withOpacity(0.8),
                    Colors.pink.shade900.withOpacity(0.8),
                  ],
                ),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: Colors.amber, width: 2),
                boxShadow: [
                  BoxShadow(
                    color: Colors.amber.withOpacity(0.3),
                    blurRadius: 16,
                    spreadRadius: 2,
                  ),
                ],
              ),
              child: Column(
                children: [
                  Text(
                    AppLocalizations.of(context)!.joueurSelectionne,
                    style: TextStyle(
                      color: Colors.amber,
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 1.5,
                    ),
                  ),
                  SizedBox(height: 8),
                  Text(
                    currentPlayerName,
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 26,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  SizedBox(height: 16),
                  if (isCurrentPlayer) ...[
                    Text(
                      AppLocalizations.of(context)!.cEstAVotreTour,
                      style: TextStyle(color: Colors.white70, fontSize: 14),
