// 🏆 ÉCRAN DE FIN & RÉCAPITULATIF UNIVERSEL AVEC CONSERVATION DES SCORES
// =============================================================================
class UniversalGameEndScreen extends StatefulWidget {
  final String gameTitle;
  final String? winnerId;
  final String? winnerName;
  final String? reason;
  final Map<String, dynamic> players;
  final Map<String, dynamic> gameData;
  final String gameCode;
  final String currentPlayerId;
  final bool isHost;
  final VoidCallback onExit;
  final Map<String, int>? customScores;
  final bool lowerScoreWins;

  UniversalGameEndScreen({
    Key? key,
    required this.gameTitle,
    this.winnerId,
    this.winnerName,
    this.reason,
    required this.players,
    required this.gameData,
    required this.gameCode,
    required this.currentPlayerId,
    required this.isHost,
    required this.onExit,
    this.customScores,
    this.lowerScoreWins = false,
  }) : super(key: key);

  @override
  State<UniversalGameEndScreen> createState() => _UniversalGameEndScreenState();
}

class _UniversalGameEndScreenState extends State<UniversalGameEndScreen> {
  Timer? _countdownTimer;
  int _secondsLeft = 30;
  bool _timerTriggered = false;

  @override
  void initState() {
    super.initState();
    _startCountdown();
  }

  void _startCountdown() {
    _countdownTimer?.cancel();
    _secondsLeft = 30;
    _countdownTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        if (_secondsLeft > 0) {
          _secondsLeft--;
        } else {
          timer.cancel();
          if (!_timerTriggered) {
            _timerTriggered = true;
            FirebaseService().handleRestartDecisionTimeout(widget.gameCode);
          }
        }
      });
    });
  }

  @override
  void dispose() {
    _countdownTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .snapshots(),
      builder: (context, snapshot) {
        final currentData =
            snapshot.hasData && snapshot.data!.exists
                ? (snapshot.data!.data() as Map<String, dynamic>)
                : widget.gameData;

        final currentPlayersRaw = currentData['players'];
        final Map<String, dynamic> currentPlayers = Map<String, dynamic>.from(
          widget.players,
        );
        if (currentPlayersRaw is Map) {
          currentPlayersRaw.forEach((k, v) {
            final key = k.toString();
            if (v is Map) {
              currentPlayers[key] = {
                ...(currentPlayers[key] is Map ? currentPlayers[key] : {}),
                ...Map<String, dynamic>.from(v),
              };
            } else {
              currentPlayers[key] = v;
            }
          });
        }

        final playerProfiles = Map<String, dynamic>.from(
          currentData['playerProfiles'] ?? {},
        );

        // Rassembler tous les identifiants de joueurs de la partie pour ne jamais tomber à 1/1
        final Set<String> allParticipantIds = {};
        allParticipantIds.addAll(currentPlayers.keys);
        allParticipantIds.addAll(widget.players.keys.map((e) => e.toString()));
        allParticipantIds.addAll(playerProfiles.keys);
        if (currentData['playerOrder'] is List) {
          allParticipantIds.addAll(
            (currentData['playerOrder'] as List).map((e) => e.toString()),
          );
        }
        for (String key in [
          'bigTwoPlayerOrder',
          'belotePlayerOrder',
          'unoPlayerOrder',
          'tarotPlayerOrder',
          'ramiPlayerOrder',
          'yamsPlayerOrder',
          'yamsScores',
        ]) {
          if (currentData[key] is List) {
            allParticipantIds.addAll(
              (currentData[key] as List).map((e) => e.toString()),
            );
          } else if (currentData[key] is Map) {
            allParticipantIds.addAll(
              (currentData[key] as Map).keys.map((e) => e.toString()),
            );
          }
        }
        allParticipantIds.add(widget.currentPlayerId);

        // Veiller à ce que chaque participant soit dans currentPlayers
        for (String pId in allParticipantIds) {
          if (!currentPlayers.containsKey(pId) || currentPlayers[pId] is! Map) {
            final prof =
                playerProfiles[pId] is Map
                    ? Map<String, dynamic>.from(playerProfiles[pId])
                    : (widget.players[pId] is Map
                        ? Map<String, dynamic>.from(widget.players[pId])
                        : {});
            currentPlayers[pId] = prof;
          }
        }

        final currentHostId = currentData['hostId'] ?? '';
        final bool isCurrentHost = (currentHostId == widget.currentPlayerId);
        final restartVotes = Map<String, dynamic>.from(
          currentData['restartVotes'] ?? {},
        );
        final bool hasVoted = restartVotes.containsKey(widget.currentPlayerId);
        final int readyCount = restartVotes.length;
        final int totalPlayers =
            currentPlayers.length >= 2
                ? currentPlayers.length
                : (allParticipantIds.length >= 2
                    ? allParticipantIds.length
                    : (widget.players.length >= 2
                        ? widget.players.length
                        : currentPlayers.length));

        String resolvePlayerName(String pId) {
          final fromPlayers =
              currentPlayers[pId] is Map ? currentPlayers[pId]['name'] : null;
          if (fromPlayers != null &&
              fromPlayers.toString().trim().isNotEmpty &&
              fromPlayers != AppLocalizations.of(context)!.inconnu) {
            return fromPlayers.toString();
          }
          final fromProfiles =
              playerProfiles[pId] is Map ? playerProfiles[pId]['name'] : null;
          if (fromProfiles != null &&
              fromProfiles.toString().trim().isNotEmpty &&
              fromProfiles != AppLocalizations.of(context)!.inconnu) {
            return fromProfiles.toString();
          }
          final fromWidget =
              widget.players[pId] is Map ? widget.players[pId]['name'] : null;
          if (fromWidget != null &&
              fromWidget.toString().trim().isNotEmpty &&
              fromWidget != AppLocalizations.of(context)!.inconnu) {
            return fromWidget.toString();
          }
          if (pId == widget.currentPlayerId) {
            final authName = FirebaseAuth.instance.currentUser?.displayName;
            if (authName != null && authName.trim().isNotEmpty) return authName;
          }
          return AppLocalizations.of(context)!.joueur;
        }

        // Calcul du classement par score conservé
        final List<MapEntry<String, int>> leaderboard = [];
        currentPlayers.forEach((pId, pData) {
          int score = 0;
          if (widget.customScores != null &&
              widget.customScores!.containsKey(pId)) {
            score = widget.customScores![pId]!;
          } else if (pData is Map && pData.containsKey('score')) {
            score = (pData['score'] as num?)?.toInt() ?? 0;
          }
          leaderboard.add(MapEntry(pId, score));
        });

        if (widget.lowerScoreWins) {
          leaderboard.sort((a, b) => a.value.compareTo(b.value));
        } else {
          leaderboard.sort((a, b) => b.value.compareTo(a.value));
        }

        final String displayWinner =
            widget.winnerName ??
            (leaderboard.isNotEmpty
                ? resolvePlayerName(leaderboard.first.key)
                : AppLocalizations.of(context)!.partieTerminee3);

        final bool amIWinner =
            (widget.winnerId != null &&
                widget.winnerId == widget.currentPlayerId) ||
            (leaderboard.isNotEmpty &&
                leaderboard.first.key == widget.currentPlayerId);

        return Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 24),
            child: Container(
              width: double.infinity,
              constraints: BoxConstraints(maxWidth: 460),
              padding: const EdgeInsets.all(22),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [Color(0xFF241438), Color(0xFF130E22)],
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                ),
                borderRadius: BorderRadius.circular(28),
                border: Border.all(
                  color:
                      amIWinner
                          ? Colors.amberAccent
                          : Colors.deepPurpleAccent.withOpacity(0.5),
                  width: 2,
                ),
                boxShadow: [
                  BoxShadow(
                    color: (amIWinner ? Colors.amberAccent : Colors.deepPurple)
                        .withOpacity(0.35),
                    blurRadius: 25,
                    spreadRadius: 2,
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // Trophée et En-tête
                  Icon(
                    amIWinner
                        ? Icons.emoji_events_rounded
                        : Icons.military_tech_rounded,
                    size: 64,
                    color:
                        amIWinner
                            ? Colors.amberAccent
                            : Colors.deepPurpleAccent,
                  ),
                  SizedBox(height: 8),
                  Text(
                    widget.gameTitle.toUpperCase(),
                    style: TextStyle(
                      color: Colors.white54,
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 2,
                    ),
                  ),
                  SizedBox(height: 4),
                  Text(
                    amIWinner
                        ? AppLocalizations.of(context)!.victoire
                        : AppLocalizations.of(context)!.finDeLaManche2,
                    style: TextStyle(
                      fontSize: 24,
                      fontWeight: FontWeight.w900,
                      color: amIWinner ? Colors.amberAccent : Colors.white,
                      letterSpacing: 1.2,
                    ),
                  ),
                  SizedBox(height: 4),
                  Text(
                    GameContentLocalization.format(
                      context,
                      AppLocalizations.of(context)!.aGagneCetteManche,
                      [displayWinner],
                    ),
                    style: TextStyle(
                      fontSize: 15,
                      color: Colors.white70,
                      fontWeight: FontWeight.w600,
                    ),
                    textAlign: TextAlign.center,
                  ),

                  SizedBox(height: 16),

                  // BARRE D'ÉTAT : COMPTEUR JOUEURS PRÊTS + CHRONO 30S
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 14,
                      vertical: 10,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.black.withOpacity(0.4),
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(
                        color:
                            _secondsLeft <= 5
                                ? Colors.redAccent
                                : Colors.amberAccent.withOpacity(0.4),
                      ),
                    ),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Row(
                          children: [
                            Icon(
                              Icons.people_alt_rounded,
                              color: Colors.greenAccent,
                              size: 18,
                            ),
                            SizedBox(width: 8),
                            Text(
                              GameContentLocalization.format(
                                context,
                                AppLocalizations.of(context)!.prets,
                                [readyCount, totalPlayers],
                              ),
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                color: Colors.white,
                                fontSize: 13,
                              ),
                            ),
                          ],
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 3,
                          ),
                          decoration: BoxDecoration(
                            color:
                                _secondsLeft <= 5
                                    ? Colors.redAccent.withOpacity(0.25)
                                    : Colors.white10,
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: Row(
                            children: [
                              Icon(
                                Icons.timer,
                                size: 14,
                                color:
                                    _secondsLeft <= 5
                                        ? Colors.redAccent
                                        : Colors.amberAccent,
                              ),
                              SizedBox(width: 4),
                              Text(
                                GameContentLocalization.format(
                                  context,
                                  AppLocalizations.of(context)!.s,
                                  [_secondsLeft],
                                ),
                                style: TextStyle(
                                  fontWeight: FontWeight.w900,
                                  color:
                                      _secondsLeft <= 5
                                          ? Colors.redAccent
                                          : Colors.amberAccent,
                                  fontSize: 13,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),

                  SizedBox(height: 14),
                  Divider(color: Colors.white12, thickness: 1),
                  SizedBox(height: 8),

                  Align(
                    alignment: Alignment.centerLeft,
                    child: Text(
                      AppLocalizations.of(context)!.scoresConservesDeLaSession,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                        color: Colors.cyanAccent,
                        letterSpacing: 1.2,
                      ),
                    ),
                  ),
                  SizedBox(height: 8),

                  // TABLEAU DU CLASSEMENT CUMULÉ
                  ...leaderboard.asMap().entries.map((entry) {
                    final int rank = entry.key + 1;
                    final String pId = entry.value.key;
                    final int pScore = entry.value.value;
                    final String pName = resolvePlayerName(pId);
                    final bool isMe = (pId == widget.currentPlayerId);
                    final bool playerReady = restartVotes.containsKey(pId);
                    final bool isPlayerAdmin = (pId == currentHostId);

                    Color medalColor = Colors.white60;
                    if (rank == 1) medalColor = Colors.amberAccent;
                    if (rank == 2) medalColor = Color(0xFFCBD5E1);
                    if (rank == 3) medalColor = Color(0xFFCD7F32);

                    return Container(
                      margin: const EdgeInsets.symmetric(vertical: 3),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 8,
                      ),
                      decoration: BoxDecoration(
                        color:
                            isMe
                                ? Colors.deepPurple.withOpacity(0.35)
                                : Colors.white.withOpacity(0.04),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color:
                              isMe ? Colors.deepPurpleAccent : Colors.white10,
                          width: isMe ? 1.5 : 1,
                        ),
                      ),
                      child: Row(
                        children: [
                          Text(
                            "#$rank",
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              color: medalColor,
                              fontSize: 13,
                            ),
                          ),
                          SizedBox(width: 10),
                          Expanded(
                            child: Row(
                              children: [
                                Flexible(
                                  child: Text(
                                    isMe
                                        ? "$pName (${AppLocalizations.of(context)!.moi})"
                                        : pName,
                                    style: TextStyle(
                                      fontWeight:
                                          isMe
                                              ? FontWeight.w900
                                              : FontWeight.bold,
                                      color:
                                          isMe
                                              ? Colors.amberAccent
                                              : Colors.white,
                                      fontSize: 13,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                                if (isPlayerAdmin) ...[
                                  SizedBox(width: 4),
                                  Icon(
                                    Icons.admin_panel_settings,
                                    size: 14,
                                    color: Colors.amberAccent,
                                  ),
                                ],
                              ],
                            ),
                          ),
                          // Badge Prêt / En attente
                          Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 6,
                              vertical: 2,
                            ),
                            decoration: BoxDecoration(
                              color:
                                  playerReady
                                      ? Colors.green.withOpacity(0.2)
                                      : Colors.white10,
                              borderRadius: BorderRadius.circular(8),
                            ),
                            child: Text(
                              playerReady
                                  ? AppLocalizations.of(context)!.pret4
                                  : "...",
                              style: TextStyle(
                                fontSize: 10,
                                fontWeight: FontWeight.bold,
                                color:
                                    playerReady
                                        ? Colors.greenAccent
                                        : Colors.white38,
                              ),
                            ),
                          ),
                          SizedBox(width: 10),
                          Text(
                            AppLocalizations.of(context)!.pts13(pScore),
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w900,
                              color:
                                  rank == 1
                                      ? Colors.amberAccent
                                      : Colors.white70,
                            ),
                          ),
                        ],
                      ),
                    );
                  }).toList(),

                  SizedBox(height: 22),

                  // BOUTONS D'ACTION : REJOUER / QUITTER / FORCE ADMIN
                  Column(
                    children: [
                      Row(
                        children: [
                          Expanded(
                            child: OutlinedButton.icon(
                              icon: Icon(Icons.exit_to_app_rounded, size: 16),
                              label: Text(
                                AppLocalizations.of(context)!.quitter,
                              ),
                              style: OutlinedButton.styleFrom(
                                foregroundColor: Colors.redAccent,
                                side: BorderSide(color: Colors.redAccent),
                                padding: const EdgeInsets.symmetric(
                                  vertical: 13,
                                ),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                              ),
                              onPressed: widget.onExit,
                            ),
                          ),
                          SizedBox(width: 10),
                          Expanded(
                            flex: 2,
                            child: ElevatedButton.icon(
                              icon: Icon(
                                hasVoted
                                    ? Icons.check_circle
                                    : Icons.replay_rounded,
                                size: 18,
                              ),
                              label: Text(
                                hasVoted
                                    ? "${AppLocalizations.of(context)!.pret} ($readyCount/$totalPlayers)"
                                    : AppLocalizations.of(
                                      context,
                                    )!.rejouerGarderPts,
                                style: TextStyle(
                                  fontWeight: FontWeight.bold,
                                  fontSize: 12.5,
                                ),
                              ),
                              style: ElevatedButton.styleFrom(
                                backgroundColor:
                                    hasVoted
                                        ? Colors.grey[700]
                                        : Color(0xFF10B981),
                                foregroundColor: Colors.white,
                                elevation: 5,
                                padding: EdgeInsets.symmetric(vertical: 13),
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                              ),
                              onPressed:
                                  hasVoted
                                      ? null
                                      : () {
                                        HapticFeedback.mediumImpact();
                                        FirebaseService().submitRestartVote(
                                          widget.gameCode,
                                          widget.currentPlayerId,
                                        );
                                      },
                            ),
                          ),
                        ],
                      ),

                      // BOUTON SPÉCIAL ADMIN : FORCER LE LANCEMENT MANUEL SI BESOIN
                      if (isCurrentHost && totalPlayers >= 2) ...[
                        SizedBox(height: 8),
                        SizedBox(
                          width: double.infinity,
                          child: TextButton.icon(
                            icon: Icon(
                              Icons.flash_on,
                              size: 16,
                              color: Colors.amberAccent,
                            ),
                            label: Text(
                              AppLocalizations.of(
                                context,
                              )!.adminLancerMaintenantAvecLes,
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontSize: 11,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            onPressed: () {
                              FirebaseService().restartGameKeepScores(
                                widget.gameCode,
                              );
                            },
                          ),
                        ),
                      ],
                    ],
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}

class _BigTwoSpadePainter extends CustomPainter {
  final Color color;
  _BigTwoSpadePainter(this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = color
          ..style = PaintingStyle.fill
          ..isAntiAlias = true;

    final w = size.width;
    final h = size.height;
    final path = Path();

    // Pointe en haut
    path.moveTo(w * 0.5, 0);
    // Côté droit
    path.cubicTo(w * 0.75, h * 0.28, w, h * 0.52, w * 0.78, h * 0.72);
    path.cubicTo(w * 0.62, h * 0.85, w * 0.52, h * 0.75, w * 0.5, h * 0.68);
    // Côté gauche
    path.cubicTo(w * 0.48, h * 0.75, w * 0.38, h * 0.85, w * 0.22, h * 0.72);
    path.cubicTo(0, h * 0.52, w * 0.25, h * 0.28, w * 0.5, 0);
    path.close();

    // Pied du pique
    final stem = Path();
    stem.moveTo(w * 0.44, h * 0.65);
    stem.lineTo(w * 0.56, h * 0.65);
    stem.lineTo(w * 0.68, h);
    stem.lineTo(w * 0.32, h);
    stem.close();

    canvas.drawPath(path, paint);
    canvas.drawPath(stem, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _BigTwoClubPainter extends CustomPainter {
  final Color color;
  _BigTwoClubPainter(this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = color
          ..style = PaintingStyle.fill
          ..isAntiAlias = true;

    final w = size.width;
    final h = size.height;
    final r = w * 0.25;

    // 3 lobes
    canvas.drawCircle(Offset(w * 0.5, h * 0.28), r, paint);
    canvas.drawCircle(Offset(w * 0.28, h * 0.56), r, paint);
    canvas.drawCircle(Offset(w * 0.72, h * 0.56), r, paint);
    canvas.drawCircle(Offset(w * 0.5, h * 0.5), r * 0.8, paint);

    // Pied du trèfle
    final stem = Path();
    stem.moveTo(w * 0.44, h * 0.55);
    stem.lineTo(w * 0.56, h * 0.55);
    stem.lineTo(w * 0.68, h);
    stem.lineTo(w * 0.32, h);
    stem.close();

    canvas.drawPath(stem, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

class _BigTwoDiamondPainter extends CustomPainter {
  final Color color;
  _BigTwoDiamondPainter(this.color);

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = color
          ..style = PaintingStyle.fill
          ..isAntiAlias = true;

    final w = size.width;
    final h = size.height;
    final path = Path();
    path.moveTo(w * 0.5, 0);
    path.lineTo(w, h * 0.5);
    path.lineTo(w * 0.5, h);
    path.lineTo(0, h * 0.5);
    path.close();

    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}
